#include <bits/stdc++.h>
using namespace std;

inline int lowbit( int x ) {
	return x & ( -x );
}
void go( int, int, int, vector< int >& );

int main() {
	ios_base::sync_with_stdio( false );
	cin.tie( nullptr );
	int n, a, b; cin >> n >> a >> b;
	if ( __builtin_popcount( a ^ b ) % 2 == 0 ) {
		cout << "NO\n";
		return 0;
	}
	cout << "YES\n";
	vector< int > ans;
	go( n, a, b, ans );
	for ( size_t i = 0 ; i < ans.size() ; ++ i )
		cout << ans[ i ] << " \n"[ i + 1 == ans.size() ];
	return 0;
}

void go( int n, int a, int b, vector< int >& ret ) {
	if ( n == 1 ) {
		ret.push_back( a );
		ret.push_back( b );
		return;
	}
	int xr = lowbit( a ^ b );
	int aa = min( a, a ^ xr );
	int bb = min( b, b ^ xr );
	go( n - 1, aa, aa ^ 1, ret );
	go( n - 1, aa ^ 1, bb, ret );
	int n2 = 1 << ( n - 1 );
	if ( aa == a ) {
		for ( int i = 0 ; i < n2 ; ++ i )
			ret[ ret.size() - 1 - i ] ^= xr;
	} else {
		for ( int i = 0 ; i < n2 ; ++ i )
			ret[ ret.size() - 1 - i - n2 ] ^= xr;
	}
}

