//最下位ビット
int lbit(int n) {
    return n & -n;
}
//最上位ビット
int hbit(int n) {
    n |= (n >> 1);
    n |= (n >> 2);
    n |= (n >> 4);
    n |= (n >> 8);
    n |= (n >> 16);
    n |= (n >> 32);
    return n - (n >> 1);
}
#define bcou __builtin_popcountll

void dfs(int s, int t, int cuts) {
    //t以外に行ける場所がない
    if (bcou(cuts) == n - 1) {
        res.pb(s);
        res.pb(t);
        return;
    }
    //s -> t で使うことになる軸の集合
    int need = s ^t;
    //needに含まれる軸ncutで切断すれば、sとtを分離できる
    int ncut = lbit(need);
    cuts |= ncut;
    //sとtを分離した時、s側で使える軸の集合
    int cand = ((1 << n) - 1) ^cuts;
    int mid = s ^lbit(cand);
    //t側のスタート地点がtになってはいけない
    if ((mid ^ ncut) == t) {
        mid = s ^ hbit(cand);
    }
    //二つの部分問題に帰着できた
    dfs(s, mid, cuts);
    //ncutでsとtを分離したため、mid^ncutでt側に移動できる
    dfs(mid ^ ncut, t, cuts);
}

