vector<int> solve(int n, int a, int b) {
    if(n == 1) {
        return vector<int> {a, b};
    } else {
        int d = 0;
        for( ; d < n; ++d) {
            if(((a >> d) & 1) != ((b >> d) & 1)) break;
        }
        int na = ((a & ~((1 << (d + 1)) - 1)) >> 1) | (a % (1 << d));
        int nb = ((b & ~((1 << (d + 1)) - 1)) >> 1) | (b % (1 << d));
        int c = na ^ 1;
        vector<int> reta = move(solve(n - 1, na, c));
        vector<int> retb = move(solve(n - 1, c, nb));

        vector<int> ret(1 << n);
        for(int i = 0; i < (1 << (n - 1)); ++i) {
            ret[i] = ((reta[i] << 1) & ~((1 << (d + 1)) - 1))
            | (((a >> d) & 1) << d) | (reta[i] % (1 << d));
        }
        for(int i = 0; i < (1 << (n - 1)); ++i) {
            ret[i + (1 << (n - 1))] = ((retb[i] << 1) & ~((1 << (d + 1)) - 1))
            | (((b >> d) & 1) << d) | (retb[i] % (1 << d));
        }
        return ret;
    }
}


