uint64_t popcnt(uint64_t n)
{
    uint64_t c = 0;
    c = (n & 0x5555555555555555) + ((n>>1) & 0x5555555555555555);
    c = (c & 0x3333333333333333) + ((c>>2) & 0x3333333333333333);
    c = (c & 0x0f0f0f0f0f0f0f0f) + ((c>>4) & 0x0f0f0f0f0f0f0f0f);
    c = (c & 0x00ff00ff00ff00ff) + ((c>>8) & 0x00ff00ff00ff00ff);
    c = (c & 0x0000ffff0000ffff) + ((c>>16) & 0x0000ffff0000ffff);
    c = (c & 0x00000000ffffffff) + ((c>>32) & 0x00000000ffffffff);
    return(c);
}

void dfs(vector<int>& ans, vector<int> fixed, int a, int b, int i, int n) {
    ans[i] = a;
    ans[i + (1 << n) - 1] = b;

    if (n == 1) {
        return;
    }

    int j = -1;
    for (int k = 0; k < fixed.size(); k++) {
        if (!fixed[k] && ((a >> k) & 1) != ((b >> k) & 1)) {
            j = k;
            break;
        }
    }

    fixed[j] = 1;

    for (int k = 0; k < (1 << (n - 1)); k++) {
        if ((a >> j) & 1) {
            ans[i + k] = ans[i + k] | (1 << j);
        } else {
            ans[i + k + (1 << (n - 1))] = ans[i + k + (1 << (n - 1))] | (1 << j);
        }
    }


    for (int k = 0; k < fixed.size(); k++) {
        if (!fixed[k]) {

            int c = a ^ (1 << k);
            dfs(ans, fixed, a, c, i, n - 1);

            dfs(ans, fixed, c ^ (b & (1 << j)), b, i + (1 << (n - 1)), n - 1);

            break;
        }
    }    
}

int main() {
    int n;
    int a, b;
    in(n, a, b);

    if (popcnt(a) % 2 == popcnt(b) % 2) {
        out("NO");
        return 0;   
    }

    int m = 1 << n;

    vector<int> ans(m);
    vector<int> fixed(n);

    dfs(ans, fixed, a, b, 0, n);

    out("YES");

    vout(ans, m);
}

