int N, A, B;

void Solve(int s, int t, int mask) {
    if (__builtin_popcount(mask) == 1) {
        printf("%d %d ", s, t);
        return ;
    }

    int diff = 1, add = 1;
    while (!(diff & mask) || !((s ^ t) & diff)) diff <<= 1;
    while (!(diff != add) || !(add & mask)) add <<= 1;

    Solve(s, s ^ add, mask ^ diff);
    Solve(s ^ diff ^ add, t, mask ^ diff);
}

int main() {
    scanf("%d %d %d", &N, &A, &B);

    bool has_sol = ((__builtin_popcount(A) % 2) != (__builtin_popcount(B) % 2));
    if (has_sol) {
        puts("YES");
        Solve(A, B, (1 << N) - 1);
        puts("");
    } else {
        puts("NO");
    }

    return 0;
}

