vector<int> st;
vector<int> top;

vector<int> calc(int a, int b, int n) {
    if (n == 1) return {a, b};
    int s = __builtin_ffs(a^b);
    int aa = a % (1 << (s-1)) + ((a >> s) << (s-1));
    int bb = b % (1 << (s-1)) + ((b >> s) << (s-1));
    int d = aa ^ 1;
    //cout << a << b << " " << aa << " " << bb << " " << d <<  endl;
    vector<int> e = calc(aa, d, n-1), f = calc(d, bb, n-1);
    for (int i = 0; i < (int)e.size(); i++) e[i] = ((e[i] >> (s-1)) << s) + e[i] % (1 << (s-1));
    for (int q : f) e.push_back(((q >> (s-1)) << s) + (1 << (s-1)) + q % (1 << (s-1)));
    return e;
}

