vector<int> S(MAX);

void solve(int A,int B,int left,int right){

    if(left+2==right){
        S[left]=A;
        S[left+1]=B;
        return;
    }

    for(int i=0;i<18;i++){
        if((A&(1<<i))!=(B&(1<<i))){
            int T=A-(A&(1<<i));
            int j;
            for(j=0;j<18;j++){
                if(i!=j) break;
            }
            solve(A,(T^(1<<j))+(A&(1<<i)),left,(left+right)/2);
            solve((T^(1<<j))+(B&(1<<i)),B,(left+right)/2,right);
        }
    }
}

