void go(int s, int t, int mask)
{
  if(__builtin_popcount(mask) == N - 1){
    cout << s << ' ' << t << ' ';
    return;
  }
  int c = -1, e = -1;
  for(int i = 0; i < N; ++i) if(!(mask >> i & 1)){
