using namespace std;

// Aの下からKbit目(0-indexed)を返す
inline int kthbit(int A, int K) { return (A >> K) & 1; }

// Aの下からKbitを取り出す
inline int mask(int A, int K) { return A & ((1 << K) - 1); }

// wbit整数Aをkbitだけ左に回す
// kが負なら右に回す
inline int slide(int A, int w, int k) {
    if (k >= 0) {
        return (mask(A, w - k) << k) + (A >> (w - k));
    } else {
        return (A >> (-k)) + (mask(A, -k) << (w - (-k)));
    }
}

// [0, 2^N)全体を回るようなサイクル(グレイコード)を作る
vector<int> cycle(int N) {
    static vector<int> dp[20];

    if (N == 0) return {0};
    if (!dp[N].empty()) return dp[N];

    // 1つ下のグレイコードを求める
    vector<int> head = cycle(N - 1);
    vector<int> tail = head;

    // 一方を反転させ、先頭bitを変えてくっつける
    reverse(tail.begin(), tail.end());
    for (int& t : tail) t |= (1 << (N - 1));

    copy(tail.begin(), tail.end(), back_inserter(head));
    return dp[N] = head;
}

vector<int> solve(int A, int B, int N) {
    if (N == 1) return {A, B};

    int k;
    for (k = 0; k < N; ++k) {
        if (kthbit(A, N - 1 - k) != kthbit(B, N - 1 - k)) break;
    }
    // 先頭bitが異なるように、左にkだけslideする
    A = slide(A, N, k), B = slide(B, N, k);

    // bit長N-1のグレイコード
    vector<int> head = cycle(N - 1);
    for (int& a : head) a ^= A;

    // 末尾からBまでの答えをマージする
    vector<int> tail = solve(mask(head.back(), N - 1), mask(B, N - 1), N - 1);
    // 先頭bitをBと一致させる
    for (int& a : tail) a ^= B & (1 << (N - 1));
    copy(tail.begin(), tail.end(), back_inserter(head));

    // kだけ右に回して元に戻す
    for (int& a : head) a = slide(a, N, -k);
    return head;
}

int main() {
    int N, A, B;
    cin >> N >> A >> B;

    if (__builtin_popcount(A ^ B) % 2 == 0) {
        cout << "NO" << endl;
        return 0;
    }

    cout << "YES" << endl;
    auto ans = solve(A, B, N);

    for (auto a : ans) cout << a << " ";
    cout << endl;
    return 0;
}

