int sn[M][2], sz[M], fa[M], rt;
bool laz[M];
inline int dotira(int x) {return sn[fa[x]][1] == x;}
inline void Up(int x) {sz[x] = sz[sn[x][0]] + sz[sn[x][1]] + 1;}
inline void Down(int x) {
	if(!laz[x]) return;
	std::swap(sn[x][0], sn[x][1]);
	if(sn[x][0]) laz[sn[x][0]] ^= 1;
	if(sn[x][1]) laz[sn[x][1]] ^= 1;
	laz[x] = false;
}
inline void rotate(int x) {
	int cur = dotira(x), f = fa[x], &xsn = sn[x][cur ^ 1], oji = fa[f];
	if((fa[x] = oji)) sn[oji][dotira(f)] = x;
	if((sn[f][cur] = xsn)) fa[xsn] = f;
	fa[xsn = f] = x;
	Up(f), Up(x);
}
void splay(int x, int goal) {
	int f;
	while((f = fa[x]) != goal) {
		Down(fa[f]), Down(f), Down(x);
		if(fa[f] != goal) {
			if(dotira(x) == dotira(f)) rotate(f);
			else rotate(x);
		}
		rotate(x);
	}
	if(!goal) rt = x;
}
int tonari(int x, int cur) {
	splay(x, 0);
	x = sn[x][cur];
	while(Down(x), sn[x][cur ^ 1]) x = sn[x][cur ^ 1];
	return x;
}
inline int findkth(int k) {
	int x = rt, totsz;
findst:
	Down(x);
	totsz = sz[sn[x][0]] + 1;
	if(k > totsz) x = sn[x][1], k -= totsz;
	else if(k <= sz[sn[x][0]]) x = sn[x][0];
	else return x;
	goto findst;
}
int split(int x, int y) {
	splay(x, 0), splay(y, x);
	int p = sn[y][0];
	sn[y][0] = 0;
	fa[p] = 0;
	Up(y), Up(x);
	return p;
}
inline void New(int x, int cur, int p) {
	int f = tonari(x, cur);
	splay(x, 0);
	if(f) splay(f, x), sn[f][cur ^ 1] = p, Up(f), Up(x);
	else if(x) sn[f = x][cur] = p, Up(x);
	fa[p] = f;
	splay(p, 0);
}
