void makeKaruno(int karuno[]) {
	int i, j;

	karuno[0] = 0;
	karuno[1] = 1;
	for (i = 2; i < 17; i++) {
		for (j = 0; j < (1 << (i - 1)); j++) {
			karuno[(1 << (i - 1)) + j] = karuno[(1 << (i - 1)) - 1 - j] + (1 << (i - 1));
		}
	}
}

