vector<int> ans;

void gen(int &cur, int mask) {
  if (mask == 0) return;
  int bit = mask & ~(mask - 1);
  gen(cur, mask ^ bit);
  ans.push_back(cur ^= bit);
  gen(cur, mask ^ bit);
}

