const int B = 18;
int mark[B];
int numbers[1 << B];
int n, a, b;

void solve(int st, int en, int set_bit, int rest, int mask){
    //cout << st << " , " << en << " setando " << set_bit << endl;
    for(int i = st ; i <= en ; i++){
        numbers[i] |= set_bit;
    }    

    if(rest <= 1){
        return;
    }

    int find = -1, se = -1;

    for(int j = 0 ; j < n ; j++){
        if(!mark[j]){
            if(find == -1 && (numbers[st] & (1 << j)) != (numbers[en] & (1 << j)))
                find = j;
            else
                se = j;
        }
    }

    assert(find != -1 && se != -1);
    mask ^= (1 << find);

    mark[find] = true;

    int mid = (st + en) >> 1;

    numbers[mid] |= (numbers[st] & mask) ^ (1 << se);
    numbers[mid + 1] |= (numbers[st] & mask) ^ (1 << se);

    solve(st, mid, numbers[st] & (1 << find), rest - 1, mask);
    solve(mid + 1, en, numbers[en] & (1 << find), rest - 1, mask);

    mark[find] = false;
}

