vector<int> ans;

void solve (int r, int a, int b, int x) {
    if (r == 0) {
        ans.push_back((b|x));
        return;
    }

    a %= (1<<(r+1));
    b %= (1<<(r+1));
    if ((a&(1<<r)) == (b&(1<<r))) {
        if (r == 1) {
            if (a&(1<<r)) {
                ans.push_back((a-(1<<r))|x);
                ans.push_back((b-(1<<r))|x);
                ans.push_back(b|x);
            } else {
                ans.push_back((a+(1<<r))|x);
                ans.push_back((b+(1<<r))|x);
                ans.push_back(b|x);
            }
        } else {
            if (a&(1<<r)) solve(r-1, a, b, x+(1<<r));
            else solve(r-1, a, b, x);
            ans.pop_back();
            int tmp = ans.back();
            if (a&(1<<r)) {
                ans.push_back(tmp|x);
                solve(r-1, tmp, b, x);
                ans.push_back((b|(1<<r))|x);
            } else {
                ans.push_back((tmp|(1<<r))|x);
                solve(r-1, tmp, b, x+(1<<r));
                ans.push_back(b|x);
            }
        }
    } else {
        int t = (a+1)%(1<<r);
        if (t == (b&((1<<r)-1))) t = (t+1)%(1<<r);
        if (a < b) {
            solve(r-1, a, t, x);
            ans.push_back((t+(1<<r))|x);
            solve(r-1, t, b, x+(1<<r));
        } else {
            solve(r-1, a, t, x+(1<<r));
            ans.push_back(t|x);
            solve(r-1, t, b, x);
        }
    }
}

