  bool s = now & b;
  ll ans = now;
  if (f xor s) {
    ans = now xor (1LL << (n-1)) xor b;
  }
  ans = ans xor a;
  counter++;
  printf("%lld%c", ans, counter == (1LL << n) ? '\n' : ' ');
}

