int pops(int x)
{
    int ret = 0;
    while (x)
    {
        if (x % 2)
            ret++;
        x /= 2;
    }
    return ret;
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, A, B;
    cin >> N >> A >> B;
    vector<queue<int>> nums(N + 1);
    int apop = pops(A);
    int bpop = pops(B);
    for (int i = 0; i < (1 << N); i++)
    {
        if (i == A || i == B)
            continue;
        int p = pops(i);
        nums[p].push(i);
    }
    nums[bpop].push(B);
    vector<int> ret;
    ret.push_back(A);
    vector<int> cnt(N, 0);
    cnt[0] = apop;
    for (int i = 1; i < (1 << N); i++)
    {
        int last = ret[ret.size() - 1];
        int pos = pops(last);
        if (pos == 0)
        {
            if (nums[pos + 1].size() == 0)
            {
                cout << "NO" << endl;
                return 0;
            }
            ret.push_back(nums[pos + 1].front());
            nums[pos + 1].pop();
        }
        else if (pos == N)
        {
            if (nums[pos - 1].size() == 0)
            {
                cout << "NO" << endl;
                return 0;
            }
            ret.push_back(nums[pos - 1].front());
            nums[pos - 1].pop();
        }
        else
        {
            if (nums[pos - 1].size() == 0 && nums[pos + 1].size() == 0)
            {
                cout << "NO" << endl;
                return 0;
            }
            else if (nums[pos - 1].size() == 0)
            {
                ret.push_back(nums[pos + 1].front());
                nums[pos + 1].pop();
            }
            else if (nums[pos + 1].size() == 0)
            {
                ret.push_back(nums[pos - 1].front());
                nums[pos - 1].pop();
            }
            else
            {
                int next;
                if (abs(pos - 1 - bpop) < abs(pos + 1 - bpop))
                    next = pos + 1;
                else
                    next = pos - 1;
                ret.push_back(nums[next].front());
                nums[next].pop();
            }
        }
    }
    if (ret[(1 << N) - 1] != B)
    {
        cout << "NO" << endl;
        return 0;
    }
    for (int i = 1; i < (1 << N); i++)
    {
        assert(abs(pops(ret[i - 1]) - pops(ret[i])) == 1);
    }
    cout << "YES" << endl;
    printv(ret);
    return 0;
}

