typedef long long ll;
vector<ll> f(ll i,ll j){
  vector<ll> res;
  if(j==1){
    res.push_back(i);
    res.push_back(i+1);
    return res;
  }
  else{
    vector<ll> f1=f(i,j-1),f2=f(i+(1<<(j-1)),j-1);
    for(int a=0;a<f1.size();a++) res.push_back(f1[a]);
    for(int a=f2.size()-1;a>=0;a--) res.push_back(f2[a]);
    return res;
  }
}
ll convert(ll x,ll kt){
  ll res=0;
  for(int i=18;i>kt;i--){
    res+=(((x>>i)&1)<<i);
  }
  for(int i=kt-1;i>=0;i--){
    res+=(((x>>i)&1)<<(i+1));
  }
  res+=((x>>kt)&1);
  return res;
}
ll g_convert(ll x,ll kt){
  ll res=0;
  for(int i=18;i>kt;i--){
    res+=(((x>>i)&1)<<i);
  }
  for(int i=kt;i>0;i--){
    res+=(((x>>i)&1)<<(i-1));
  }
  res+=((x%2)<<kt);
  return res;
}
