  ll a,b;
  cin>>a>>b;
  bool f=false,kt=0;
  for(int i=0;i<18;i++){
    if(((a>>i)&1)!=((b>>i)&1)){
      if(!f){
        f=true;
        kt=i;
      }
      else{
        cout<<"NO"<<endl;
        return 0;
      }
    }
  }
  cout<<"YES"<<endl;
  a=convert(a,kt);
  b=convert(b,kt);
  ll N=(1<<n);
  vector<ll> ans;
  for(int i=0;i<N;i++){
    if(cycle[i]==a){
      if(cycle[(i+1)%N]==b){
        ans.push_back(g_convert(a,kt));
        for(int j=(i+N-1)%N;j!=(i+1)%N;j--,j+=N,j%=N){
          ans.push_back(g_convert(cycle[j],kt));
        }
        ans.push_back(g_convert(b,kt));
      }
      else{
        ans.push_back(g_convert(a,kt));
        for(int j=(i+1)%N;j!=(i+N-1)%N;j++,j%=N){
          ans.push_back(g_convert(cycle[j],kt));
