int pct(int x){
    return __builtin_popcount(x);
}
int mbit(int x){
    int res=0;
    while(!(x&1)){
        res++;
        x>>=1;
    }
    return res;
}
int nbit(int x){
    int res=0;
    while(x&1){
        res++;
        x>>=1;
    }
    return res;
}
vi solve(int a,int b,int c,int d){
    if(a==1){
        return vi{b,c};
    }
    int k=1<<mbit((b^c)&(~d));
    d|=k;
    int x=1<<nbit(d);
    vi p(solve(a-1,b,b^x,d));
    vi q(solve(a-1,b^x^k,c,d));
    p.insert(p.end(),all(q));
    return p;
}
