void solve(int a, int b, vector<int> v) {
    if (v.size() == 1) {
        cout << a<<" "<<b<<" ";
        return;
    }

    FOR (i,0,v.size())
    {
        if ((a&(1<<v[i])) != (b&(1<<v[i])))
