ll N,A,B;
ll used[200020];
int c;
int ed;
vector<int> ans;

void solve(int now){
  used[now]=true;
  ans.push_back(now);
  c++;

  for(int i=0;i<N;i++){
    int next=now^(1<<i);
    if(c==ed&&next==B){
      cout<<"YES"<<endl;
      for(int i=0;i<ans.size();i++){
        cout<<ans[i]<<" ";
      }
      cout<<B<<endl;
      cout<<endl;
      exit(0);
    }
    if(used[next]) continue;
    solve(next);
  }
  used[now]=false;
  ans.pop_back();
  c--;
  return;
}

int main(){
