int hummingDif(int N, int A, int B) {
	int k = 1;
	int count = 0;
	for (int i = 0; i < N; i++) {
		if (A&k != B & k) { count++; }
		k *= 2;
	}
	return count;
}

int main() {
	int N, A, B;
	cin >> N >> A >> B;
	int c = hummingDif(N, A, B);

	if (c % 2 == 0) {
		cout << "NO";
	}

	return 0;
}

