    if(!((__builtin_popcount(a)+__builtin_popcount(b))&1)) cout<<"NO\n", exit(0);
    vector<int> ans;
    solve(n, a, b, ans);
    cout<<"YES\n";
    for(int x:ans) cout<<x<<' ';
    cout<<endl;
