ll n, a, b, ans[1<<18], act[1<<18];

int main() {
  scanf("%lld", &n);
  scanf("%lld%lld", &a, &b);
  bool ok = false;
  ll keta;
  for (ll i = 0, j = 1; i < n; i++, j *= 2) {
    if ((a xor b) & j) {
      if (ok) {
        printf("NO\n");
        return 0;
      }
      ok = true;
      keta = i;
    }
  }
  printf("YES\n");
  ans[1] = 1;
  act[1] = 0;
  for (ll i = 2, j = 0, jMax = 2, tempCounter = 1; i < (1 << n); i++) {
    if (j == 0) {
      ans[i] = ans[i-1] xor (1 << tempCounter);
      act[i] = tempCounter;
    } else {
      ans[i] = ans[i-1] xor (1 << act[j]);
      act[i] = act[j];
    }
    j++;
    if (j == jMax) {
      j = 0, jMax *= 2, tempCounter++;
    }
  }
  for (ll k = 0; k < (1<<n); k++) {
    ll t = 0;
    for (ll i = 0, j = 0; i < n; i++) {
      if (i == keta) {
        t += (a xor ans[k]) & (1 << (n-1));
      } else {
        t += (a xor ans[k]) & (1 << j);
        j++;
      }
    }
    printf("%lld", t);
    if (k == (1<<n) - 1) printf("\n");
    else printf(" ");
  }
  //for (ll i = 1; i < 1<<n; i++) cout<< static_cast<bitset<8>>(ans[i])<<endl;
}

