using u32 = uint32_t;

static constexpr u32 dbj[32] = {
  0, 1, 28, 2, 29, 14, 24, 3, 30, 22, 20, 15, 25, 17, 4, 8,
  31, 27, 13, 23, 21, 19, 16, 7, 26, 12, 18, 6, 11, 5, 10, 9
};

u32 get(u32 v) {
  return 1u << (u32) dbj[((v & -v) * 0x077CB531U) >> 27];
}


void dfs(u32 mask, u32 a, u32 b) {
  if ((mask & (mask - 1)) == 0) {
    cout << a << ' ' << b << ' ';
  } else {
    u32 c = get(a ^ b);
    u32 d = get(mask ^ c);
    dfs(mask ^ c, a, a ^ d);
    dfs(mask ^ c, a ^ d ^ c, b);
  }
}

