#define mul(a,b) a=a*b%mod

vector<ll> solve(ll n,ll a,ll b){
    vector<ll> ans;
    if(n==1){
	ans.push_back(a);
	ans.push_back(b);
	return ans;
    }
    ll x=a&(1<<(n-1)); a%=(1<<(n-1));
    ll y=b&(1<<(n-1)); b%=(1<<(n-1));
    if(x!=y){
	ll mid=a^1;
	for(auto t:solve(n-1,a,mid)){
	    ans.push_back(t+x);
	}
	for(auto t:solve(n-1,mid,b)){
	    ans.push_back(t+y);
	}
	return ans;
    }
    bool p=0;
    for(auto t:solve(n-1,a,b)){
	if(p==0){
	    ans.push_back(t+x);
	    ans.push_back(t+y);
	}
	if(p==1){
	    ans.push_back(t+y);
	    ans.push_back(t+x);
	}
	p^=1;
    }
    return ans;
}

int main(){
    ll n,a,b;
    cin>>n>>a>>b;
    ll cnt=0;
    for(int i=0;i<n;i++){
	if((a&(1<<i))!=(b&(1<<i)))cnt++;
    }
    if(cnt%2==0)cout<<"NO"<<endl;
    else{
	cout<<"YES"<<endl;
	vector<ll> res=solve(n,a,b);
	for(auto t:res)cout<<t<<endl;
    }
}

