void dfs1(ll u)
{
	vis[u]=1;
	v.pb(u);
	while(sz(adj[u]) and vis[adj[u].begin()->S])
		adj[u].erase(adj[u].begin());
	if(sz(adj[u]))
	{
		pll p=*adj[u].begin();
		adj[u].erase(adj[u].begin());
		dfs1(p.S);
	}
}
