#include <iostream>
#include <algorithm>
using namespace std;

string bit(int n){
  string ans="";
  for(int i=0;i<20;i++){
    char c='0'+n%2;
    ans=ans+c;
    n/=2;
  }
  return ans;
}

int two(int n){
  int ans=1;
  for(int i=0;i<n;i++){
    ans*=2;
  }
  return ans;
}

int my_xor(int n,int m){
  string a=bit(n);
  string b=bit(m);
  int ans=0;
  for(int i=0;i<20;i++){
    int x=a.at(i)-'0';
    int y=b.at(i)-'0';
    if(x+y==1){
      ans+=two(i);
    }
  }
  return ans;
}   

int main(){
  int n,a,b;
  cin >> n >> a >> b;
  int c[n];
  string s=bit(a);
  string t=bit(b);
  int count=0;
  for(int i=0;i<n;i++){
    if(s.at(i)!=t.at(i)){
      count++;
      c[i]=1;
    }
    else{
      c[i]=0;
    }
  }
  if(count%2==0){
    cout << "NO" << endl;
  }
  else{
    cout << "YES" << endl;
    int k=two(n);
    int p[k];
    for(int i=0;i<k;i++){
      p[i]=0;
    }
    p[a]++;
    p[b]++;
    int ans=a;
    cout << ans << " ";
    string dif=bit(my_xor(a,b));
    for(int i=0;i<n;i++){
      if(dif.at(i)=='0'){
        ans=my_xor(ans,two(i));
        cout << ans << " ";
        p[ans]++;
      }
    }
    int d[n]; 
    for(int i=0;i<n;i++){
      if(c[i]==0){
        d[i]=100+i;
      }
      else{
        d[i]=i;
      }
    }
    sort(d,d+n);
    for(int i=0;i<n;i++){
      d[i]=d[i]%100;
    }
    for(int i=0;i<n;i++){
      d[i]=two(d[i]);
    }
    for(int i=0;i<k-2-n+count;i++){
      int j=0;
      while(p[my_xor(ans,d[j])]!=0){
        j++;
      }
      ans=my_xor(ans,d[j]);
      p[ans]++;
      cout << ans << " ";
    }
    cout << b;
  }
}

