#include <bits/stdc++.h>

using namespace std;

const int MaxN = 20;

bool used[1 << MaxN];
int n;
int N;
int a[1 << MaxN];

int A, B;

void rec(int pos)
{
    if(a[pos] == B && pos + 1 != n)
        return;

    if(pos + 1 == n)
    {
        for(int i = 0; i < n; ++i)
            cout << a[i] << ' ';
        cout << '\n';
        exit(0);
    }

    for(int bit = 0; bit < N; ++bit)
    {
        int to = (a[pos] ^ (1 << bit));

        if(!used[to])
        {
            used[to] = true;
            a[pos + 1] = to;
            rec(pos + 1);
            used[to] = false;
        }
    }

}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
//    freopen("input.txt", "r", stdin);

    cin >> N;

    n = (1 << N);

    cin >> A >> B;

    if(__builtin_popcount(A) % 2 == __builtin_popcount(B) % 2)
    {
        cout << "NO\n";
        return 0;
    }

    if(N == 17)
        throw;

    cout << "YES\n";
    {
        a[0] = A;
        used[A] = true;
        rec(0);
    }

    return 0;
}

