		ans.emplace_back(mask);
		return mask;
	}
	for (auto& x : p) {
		if (X == -1 || ((mask & 1 << x) != (X & 1 << x))) {
			int t1 = rec(mask, fixed ^ 1 << x, -1);
			int t2 = rec(t1 ^ 1 << x, fixed ^ 1 << x, X);
			return t2;
		}
	}
}

