#include <bits/stdc++.h>
using namespace std;
using ll = long long;

// x の下から key 番目 (0-indexed) の bit を消す
int erase_bit(int x, int key) {
    int mask = pow(2, key);
    int low = x & (mask-1);
    x = (x / (mask*2)) * mask;
    return x + low;
}

// x の下から key 番目 (0-indexed) に bit を挿入
int insert_bit(int x, int key, int bit) {
    int mask = pow(2, key);
    int low = x & (mask-1);
    x = (x - low) * 2 + bit * mask;
    return x + low;
}

vector<int> solve(int a, int b, int n) {
    if(n == 1)
        return {a, b};
    int d = a ^ b;
    int key = __builtin_ctz(d); // このbitを消す
    int a_key = 0;
    int b_key = 0;
    if(a & (1 << key)) a_key = 1;
    if(b & (1 << key)) b_key = 1;
    // a_key != b_key
    a = erase_bit(a, key);
    b = erase_bit(b, key);
    int c = a ^ 1;
    auto ac = solve(a, c, n-1);
    for (int x: ac ) {
        x = insert_bit(x, key, a_key);
    }
    auto cb = solve(c, b, n-1);
    for (int x: cb ) {
        x = insert_bit(x, key, b_key);
        ac.push_back(x);
    }
    return ac;
}

int main() {
    int N, A, B;
    cin >> N >> A >> B;

    if (! __builtin_parity(A^B)) {
        cout << "NO";
        return 0;
    }
    cout << "YES" << "\n";
    auto ans = solve(A, B, N);
    for (int x: ans ) {
        cout << x << " ";
    }
    return 0;
}

