ll skip = -1;
ll n;
ll bitswap(ll i, ll s1, ll s2) {
    if (s1 == s2) {
        return i;
    }
    ll m = ((1LL << 20) - 1) ^ (1LL << s1) ^ (1LL << s2);
    ll v1 = (i&(1 << s1))? 1 << s2 : 0;
    ll v2 = (i&(1 << s2))? 1 << s1: 0;
    return (i & m) |  v1 | v2;
}
ll h(ll i, ll mask) {
    return bitswap(i ^ mask, n-1, skip);
}

void rec(ll k, ll mask, bool r) {
    //cout << "mask=" << mask << " k=" << k << endl;
    if (k == 1) {
        if (r) {
            cout << h(1LL, mask) << " " << h(0LL, mask) << " ";
