}

void exc(ll i, ll j){
    ans[i][j]=1-ans[i][j];
    return;
}

void solve(ll a, ll b){
    ll A=(a+b)/2;
    ll B=A+1;
    int x=-1,y=-1;
    rep(i,N) if(!used[a][i] && !used[b][i] && ans[a][i]!=ans[b][i]) {x=i; break;}
