    rep(i,N) if(!used[a][i] && !used[b][i]) {y=i;break;}
    rep(i,N) ans[A][i]=ans[a][i];
    exc(A,y);
    rep(i,N) ans[B][i]=ans[A][i];
    exc(B,x);
    return;    
}



