int mask(int l, int r) {
  return (1 << r) - (1 << l);
}

int del(int n, int k) {
  return (n & mask(0, k)) | ((n & mask(k + 1, n)) >> 1);
}

int ins(int n, int k, int bit) {
  return (n & mask(0, k)) | ((n & mask(k, n)) << 1) | (bit << k);
}

vector<int> rec(int s, int t, int cnt) {
  if (cnt == 1) return {s, t};
  int k = 0;
  while (!((s ^ t) & (1 << k))) ++k;
  int ns = del(s, k); 
  int nt = del(t, k);
  int nu = 0;
  while (bitset<32>(nu ^ ns).count() % 2 == 0) {
    ++nu;
  }
  vector<int> vs = rec(ns, nu, cnt - 1);
  vector<int> vt = rec(nu, nt, cnt - 1);
  vector<int> ret;
  for (int a : vs) ret.push_back(ins(a, k, (s >> k) & 1));
  for (int a : vt) ret.push_back(ins(a, k, (t >> k) & 1));
  return ret;
}

