int main(){
	ios_base::sync_with_stdio(false);
	int n, a, b;
	cin >> n >> a >> b;

	const int m = (1 << n);
	vector<int> r(m);
	for(int i = 0; i < m; ++i){
		r[i] = a ^ i ^ (i >> 1);
	}

	vector<int> history(m, -1);
	queue<int> q;
	for(int i = 0; i < m; ++i){
		if(r[i] == b){
			history[i] = 0;
			q.push(i);
		}
	}

	while(!q.empty()){
		const int u = q.front();
		q.pop();
		for(int s = 1; s <= n; ++s){
			const int step   = (1 << s);
			const int offset = u & ~(step - 1);
			const int t = u & (step - 1);
			if(t == 0){ continue; }
			const int v = offset + step - t;
			if(history[v] < 0){
				history[v] = s;
				q.push(v);
			}
		}
	}

	if(history[m - 1] < 0){
		cout << "NO" << endl;
		return 0;
	}

	int cur = m - 1;
	while(history[cur] > 0){
		const int u = cur;
		const int s = history[cur];
		const int step   = (1 << s);
		const int offset = u & ~(step - 1);
		const int t = u & (step - 1);
		const int v = offset + step - t;
		reverse(r.begin() + offset + 1, r.begin() + offset + step);
		cur = v;
	}

	cout << "YES" << endl;
	for(int i = 0; i < m; ++i){
		cout << r[i] << " ";
	}
	cout << endl;
	return 0;
}

