	if (__builtin_popcount(A^B) % 2 == 0) {
		cout << "NO" << endl;
		return 0;
	}
	vector<int> a(1<<N, -1);
	{
		int x = A;
		for (int i = 0; i < N; ++ i) {
			if (((x>>i)&1) != ((B>>i)&1)) {
				int y = x ^ (1<<i);
				a[x] = y;
				x = y;
			}
		}
	}
	a[B] = INF;
	for (int x = A; a[x] != INF; ) {
		int y = a[x];
		int t = -1, s = -1;
		int xy = x^y;
		int pcx = __builtin_popcount(x);
		int pcy = __builtin_popcount(y);
		for (int i = 0; i < N; ++ i) if ((1<<i) != xy) {
			int c = x^(1<<i);
			int d = y^(1<<i);
			if (a[c] < 0 && a[d] < 0) {
				int ss = 0;
				int pcc = __builtin_popcount(c);
				int pcd = __builtin_popcount(d);
				if (pcc > max(pcx, pcy) || pcd > max(pcx, pcy)) ss = 1;
				if (pcc < min(pcx, pcy) || pcd < min(pcx, pcy)) ss = 2;
				if (ss > s) {
					t = i;
					s = ss;
				}
			}
		}
		if (t == -1) {
			x = y;
			continue;
		}
