vector<int> makenoch(int len)
{
	if(len<=0)return {0};
	vector<int> xl=makenoch(len-1),xr=xl;
	reverse(xr.begin(),xr.end());
	for(auto i:xr)xl.emplace_back(i+shl(len-1));
	return xl;
}

vector<int> makech(int len)
{
	if(len<=1)return {0,1};
	if(len<=2)return {0,1,3,2,6,4,5,7};

	vector<int> xl=makech(len-2),xr;
	for(int i=0;i<(int)xl.size();i++)
	{
		xr.emplace_back(xl[i]);
		xr.emplace_back(xl[i]+shl(len-2));
		i++;
		xr.emplace_back(xl[i]+shl(len-2));
		xr.emplace_back(xl[i]);
	}

	reverse(xl.begin(),xl.end());
	for(auto i:xl)xr.emplace_back(i+shl(len-1));
	reverse(xl.begin(),xl.end());
	for(auto i:xl)xr.emplace_back(i+shl(len-1)+shl(len-2));
	return xr;
}

