	if(nw==1){
		res[0]=st,res[1]=ed;
		return res;
	}
	int pos=0;
	for(int i=0;i<nw;i++)
		if((st&(1<<i))!=(ed&(1<<i))){
			pos=i;break;
		}
	int nxts=((st>>(pos+1))<<pos)|(st&((1<<pos)-1));
	int nxte=((ed>>(pos+1))<<pos)|(ed&((1<<pos)-1));
