void build(int l,int r,int s,int e)
{
	if(l+1==r){f[l]=s;f[r]=e;return;}
	int m=(l+r)/2;
	e^=s;
	int k=18;
	while(~e&(1<<k))k--;
	build(l,m,0,e^(1<<k)^1);
	build(m+1,r,e^(1<<k)^1,e^(1<<k));
	for(int i=r;i>m;i--)f[i]^=(1<<k);
	for(int i=l;i<=r;i++)f[i]^=s;
}
