inline int cutBit(int x, int n, int b) {
  const int MASK_ALL = (1 << n) - 1;
  const int MASK1 = (1 << b) - 1;
  int r1 = x & MASK1;
  int r2 = (x >> 1) & (MASK_ALL ^ MASK1);
  return r1 | r2;
}

inline int insertBit(int x, int n, int b, int v) {
  const int MASK_ALL = (1 << n) - 1;
  const int MASK1 = (1 << b) - 1;
  int r1 = x & MASK1;
  int r2 = (x & (MASK_ALL ^ MASK1)) << 1;
  return r1 | (v << b) | r2;
}

vector<int> solve(int n, int a, int b, int cnt) {
  // fprintf(stderr, "solve(%d, %d, %d, %d)\n", n, a, b, cnt);
  vector<int> res;
  assert(cnt % 2 == 1);
  if(n == 1) {
    assert(cnt == 1);
    res.push_back(a);
    res.push_back(b);
    return res;
  }
  int diff = a^b;
  REP(i, n) {
    if(diff & (1 << i)) {
      int aa = cutBit(a, n, i);
      int ab = -1, c1, c2;
      int bb = cutBit(b, n, i);
      if(cnt == 1) {
        c1 = 1;
        c2 = 1;
        ab = aa ^ 1;
      } else if((cnt-1) % 4 == 0) {
        c1 = (cnt-1) / 2 - 1;
        c2 = (cnt-1) / 2 + 1;
      } else {
        c1 = (cnt-1) / 2;
        c2 = (cnt-1) / 2;
      }
      if(ab < 0) {
        int dd = aa ^ bb;
        int hoge = c1;
        ab = aa;
        REP(j, n) {
          if(dd & (1 << j)) {
            if(hoge-- > 0) {
              ab ^= 1 << j;
            }
          }
        }
      }
      vector<int> r1 = solve(n-1, aa, ab, c1);
      vector<int> r2 = solve(n-1, ab, bb, c2);
      int v = (a >> i) & 1;
      REP(j, r1.size()) {
        res.push_back(insertBit(r1[j], n, i, v));
      }
      REP(j, r2.size()) {
        res.push_back(insertBit(r2[j], n, i, v^1));
      }
      break;
    }
  }
  // fprintf(stderr, "solve(%d, %d, %d, %d): ", n, a, b, cnt);
  // REP(i, res.size()) {
  //   fprintf(stderr, "%d, ", res[i]);
  // }
  // fprintf(stderr, "\n");
  return res;
}

int main(void) {
  int N, A, B;
  scanf("%d%d%d", &N, &A, &B);
  int diff = A ^ B;
  int cnt = 0;
  REP(i, N) {
    if(diff & (1 << i)) {
      ++cnt;
    }
  }
  if(cnt % 2 == 0) {
    puts("NO");
    return 0;
  }
  vector<int> res = solve(N, A, B, cnt);
  puts("YES");
  REP(i, res.size()) {
    printf("%d%c", res[i], i == int(res.size())-1 ? '\n' : ' ');
  }
  return 0;
}

