void swap_bits(int& a, int x, int y) {
    if (x == y) return ;
    int bit1 = (a >> x) & 1;
    int bit2 = (a >> y) & 1;
    if (bit1) a ^= (1 << x);
    if (bit2) a ^= (1 << y);
    if (bit1) a ^= (1 << y);
    if (bit2) a ^= (1 << x);
}
