// i < j
int swap_bit(int x, int i, int j) {
    int mask_i = x & (1 << i);
    int mask_j = x & (1 << j);
    x ^= mask_i;
    x ^= mask_j;
    x ^= mask_i << (j - i);
    x ^= mask_j >> (j - i);
    return x;
}

int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    /*
    bitset<6> b(57), bs(swap_bit(57, 2, 3));
    cout << b << endl;
    cout << bs << endl;
    */

    int N, A, B;
    cin >> N >> A >> B;

    int diffs = 0;
    int diff_point;
    REP(i, N) {
        int mask = 1 << i;
        if ((A & mask) != (B & mask)) {
            diffs++;
            diff_point = i;
        }
    }
    if (diffs != 1) {
        cout << "NO" << endl;
        return 0;
    }
    A = swap_bit(A, diff_point, N - 1);
    B = swap_bit(B, diff_point, N - 1);

    vector<int> code(1 << N);
    if (A & 1) {
        code[0] = 1;
        code[1] = 0;
    } else {
        code[0] = 0;
        code[1] = 1;
    }
    info(code);

    FOR(k, 1, N) {
        REP(i, 1 << k) {
            code[(1 << k) + i] = code[(1 << k) - 1 - i];
        }
        PRINT("after reflection");
        info(code);
        int b = A & (1 << k);
        int mask = 1 << k;
        REP(i, 1 << k) {
            if (b) {
                code[i] |= mask;
            } else {
                code[(1 << k) + i] |= mask;
            }
        }
        PRINT("after step 2");
        info(code);
    }

    PRINTA(code, 0, 1 << N);

    assert(code[(1 << N) - 1] == B);
    if (code[(1 << N) - 1] == B) {
        cout << "YES\n";
        REP(i, 1 << N) {
            if (i != 0) {
                cout << " ";
            }
            cout << swap_bit(code[i], diff_point, N - 1);
        }
        cout << "\n";
    } else {
        cout << "NO\n";
    }
    cout << flush;

    return 0;
}

