int top;
int ans[(1<<20)];

int swap_bit(int x, int pos1, int pos2)
{
    int x1=0,x2=0,bit1,bit2;
    bit1 = (1<<pos1), bit2 = (1<<pos2);
    if(x&bit1)x1=1,x-=bit1;
    if(x&bit2)x2=1,x-=bit2;
    if(x1)x+=bit2;
    if(x2)x+=bit1;
    return x;
}

pair<int, int> f(int A, int B, int lev)
{
    int S, E, i, pos, maxbit, nA, nB, bit, bitA, bitB;
    if(lev==1){
        S = top;
        ans[top++]=A,ans[top++]=B;
        E = top;
        return make_pair(S, E);
    }
    for(i=0;i<lev;i++){
        bit=(1<<i);
        bitA=A&bit, bitB=B&bit;
        if(bitA!=bitB)break;
    }
    pos = i;
    nA = swap_bit(A, pos, lev-1), nB = swap_bit(B, pos, lev-1);
    maxbit = (1<<(lev-1));
    if((nA|maxbit)==(nB|maxbit)){
        S = f(nA, (nA^1), lev-1).first;
        E = f((nB^1), nB, lev-1).second;
        for(i=S;i<E;i++)ans[i]=swap_bit(ans[i], pos, lev-1);
    }
    else{
        S = f(nA,(nA^1),lev-1).first;
        E = f(((nA^1)^maxbit),nB,lev-1).second;
        for(i=S;i<E;i++)ans[i]=swap_bit(ans[i], pos, lev-1);
    }
    return make_pair(S, E);
}

