vector<int> make(int start, vector<int> fixed) {
  vector<int> ans;
  int N = fixed.size();
  for (int i = 0; i < (1 << N); i++) ans.push_back(i ^ (i >> 1));

  if (N >= 2) {
    for (int i = 0; i < ans.size(); i++) {
      int ok = (ans[i] >= (1 << (N - 1)));
      ans[i] = (ans[i] % (1 << (N - 1))) * 2 + ok;
    }
  }
  /*
  for (int i = 0; i < ans.size(); i++) {
    int a = ans[i] & mask;
    int b = (ans[i] - a) >> cnt;
    ans[i] = start ^ (b + a * (1 << (N - cnt)));
  }
  */
  for (int i = 0; i < ans.size(); i++) {
    int next = 0;
    for (int j = 0; j < N; j++) {
      int digit = (ans[i] >> j) & 1;
      next += digit * (1 << fixed[j]);
    }
    next ^= start;
    ans[i] = next;
  }
  /*
  if (!end) {
    ans.push_back(ans.back() ^ (1 << pivotA));
  }
  */
  return ans;
}

void solve(long long N, long long A, long long B) {
  vector<int> ans;

  LL diff = B ^ A;

  vector<int> pivots;
  vector<int> amari;
  for (int i = 0; i < N; i++) {
    if ((diff >> i) & 1) {
      pivots.push_back(i);
    } else
      amari.push_back(i);
  }
  if (pivots.size() % 2 == 0) {
    cout << "NO" << endl;
    return;
  }

  cout << "YES" << endl;
  int cur = A;
  for (int i = 0; i < pivots.size(); i += 2) {
    vector<int> tmp;
    vector<int> fixed = {pivots[i]};
    for (int j = 0; j < i; j += 2) fixed.push_back(pivots[j]);
    for (int j = i + 2; j < pivots.size(); j++) fixed.push_back(pivots[j]);
    for (int k : amari) fixed.push_back(k);

    // cout << fixed.size() << endl;
    vector<int> ret = make(cur, fixed);
    for (auto r : ret) ans.push_back(r);
    if (i + 1 < pivots.size()) cur = ans.back() ^ (1 << pivots[i + 1]);
  }

  for (int i = 0; i < ans.size(); i++) {
    cout << ans[i];
    if (i < ans.size() - 1)
      cout << " ";
    else
      cout << endl;
  }
}

