	int x = a ^ b;
	if (!(__builtin_popcount(x) % 2)) {
		cout << "NO" << std::endl;
		return 0;
	}
	cout << "YES" << endl;
	bool used[1<<n];
	INIT(used, 0);
	used[0] = 1;
	int cur = 0;
	FOR(i,(1<<n)-1) {
		FOR(j,n) {
			int next = cur ^ (1 << j);
			if (!used[next]) {
				used[next] = true;
				cur = next;
				stdpath.push_back(next);
				break;
			}
		}
	}
	auto res = solve(n, x);
	for (auto i : res) cout <<(i ^ a) << " ";
	cout << endl;
	return 0;
}

