bool dfs(vector<bool>& vu, vector<int>& path, int nb, int b){
  if(b == e) return nb == LIM;
  if(nb >= LIM) return false;
  for(int i = 0; i < N; ++i){
    int ni = b^(1<<i);
    if(!vu[ni]){
      vu[ni] = true;
      path.push_back(ni);
      if(dfs(vu,path,nb+1,ni)) return true;
      path.pop_back();
      vu[ni] = false;
    }
  }
  return false;
}
