void solve() {
    //const i64 mod = 1'000'000'007;

    i64 N,A,B;
    cin >> N >> A >> B;

    const i64 maxn=17;
    vector<i64> diff;
    rep(i,0,N){
        i64 k=1<<i;
        if((A&k)!=(B&k)){
            diff.emplace_back(i);
        }
    }

    if(diff.size()%2!=1){
        cout << "NO" << endl;
        return;
    }

    vector<i64> perm(N);
    rep(i,0,N){
        perm[i]=i;
    }

    static bool visit[1<<maxn];
    fill_n((bool*)visit,1<<maxn,false);

    const i64 period_len=perm.size()+1;

    do{
        for(auto d:diff) {
            auto period = perm;
            period.emplace_back(d);

            bool ok = true;

            i64 p = A;
            visit[p] = true;
            rep(i, 0, (1 << N) - 1) {
                p = p ^ (1 << period[i % period_len]);
                if (visit[p]) {
                    ok = false;
                    break;
                }
            }

            if (!ok) {
                fill_n((bool *) visit, 1 << N, false);
                continue;
            }

            vector<i64> ans(1 << N);
            p = A;
            rep(i, 0, (1 << N) - 1) {
                ans[i] = p;
                p = p ^ (1 << period[i % period_len]);
            }
            ans[(1 << N) - 1] = B;

            cout << "YES" << endl;
            rep(i, 0, 1 << N) {
                cout << ans[i];
                if (i == ((1 << N) - 1)) cout << endl;
                else cout << " ";
            }
            return;
        }
    }while(next_permutation(begin(perm),end(perm)));
}

