    auto size = SIZE(ans);
    REP(i, size - 1) {
        int n1 = ans[i];
        int n2 = ans[i + 1];
        int diff = 0;
        REP(n, N) {
            diff += (n1 & (1 << n)) != (n2 & (1 << n));
        }
        if (diff != 1) return false;
    }
    if (ans[0] != from) return false;
    if (ans.back() != to) return false;

    return true;
}

