int permu(int l){
  int bits[17];
  REP(i,17){
    bits[i]=l%2;
    l/=2;
  }
  REP(i,pv.size()){
    swap(bits[pv[pv.size()-1-i]],bits[pv.size()-1-i]);
  }
  int ret=0;
  REP(i,17){
    ret+=bits[i]<<i;
  }
  return ret;
}

