		c=n-1;
	}else{
		p=v1.back(),v1.pop_back();
		q=v2.back(),v2.pop_back();
		for(i=0;i<(1<<n);i++){
			r=i>>(n-2);
			if(rev[0][r])s[i]+=(~a)&(1<<q);
			else s[i]+=a&(1<<q);
			if(rev[1][r])s[i]+=(~a)&(1<<p);
			else s[i]+=a&(1<<p);
		}
		c=n-2;
	}
	while(!v1.empty()){
		p=v1.back(),v1.pop_back();
		q=v1.back(),v1.pop_back();
		c-=2;
		for(i=0;i<(1<<n);i++){
			r=(i>>c)%8;
			if(rev[0][r])s[i]+=(~a)&(1<<q);
			else s[i]+=a&(1<<q);
			if(rev[1][r])s[i]+=(~a)&(1<<p);
			else s[i]+=a&(1<<p);
		}
	}
	while(!v2.empty()){
		p=v2.back(),v2.pop_back();
		q=v2.back(),v2.pop_back();
		c-=2;
		for(i=0;i<(1<<n)-(1<<(c+3));i++){
			r=(i>>c)%8;
			if(rev[0][r])s[i]+=(~a)&(1<<q);
			else s[i]+=a&(1<<q);
			if(rev[1][r])s[i]+=(~a)&(1<<p);
			else s[i]+=a&(1<<p);
		}
		for(i=(1<<n)-(1<<(c+3));i<(1<<n);i++){
			r=(i>>c)%8;
			if(rev_2[0][r])s[i]+=(~a)&(1<<q);
			else s[i]+=a&(1<<q);
			if(rev_2[1][r])s[i]+=(~a)&(1<<p);
			else s[i]+=a&(1<<p);
		}
	}
	cout<<"YES"<<endl;
	array_show(s,(1<<n));
	return 0;
}

