void setPrime() {
    isPrime.resize(4010101);
    fill(isPrime, true);
    int len = sizeof(isPrime) / sizeof(isPrime[0]);
    isPrime[0] = isPrime[1] = false;
    for (int i = 2; i <= sqrt(len) + 5; ++i) {
        if (!isPrime[i])continue;
        for (int j = 2; i * j < len; ++j) {
            isPrime[i * j] = false;
        }
    }
    rep(i, len)if (isPrime[i])primes.pb(i);
}
