const int mod=1000000007,MAX=1<<17,INF=1<<30;
vector<int> S(MAX);

void solve(int A,int B,int left,int right,int start){

    if(left+2==right){
        S[left]=A;
        S[left+1]=B;
        return;
    }

    for(int i=start;i<18;i++){
        if((A&(1<<i))!=(B&(1<<i))){
            int T=A-(A&(1<<i));
            int j;
            for(j=start;j<18;j++){
                if(i!=j) break;
            }
            solve(A,(T^(1<<j))+(A&(1<<i)),left,(left+right)/2,i+1);
            solve((T^(1<<j))+(B&(1<<i)),B,(left+right)/2,right,i+1);
            return;
        }
    }
}

