    }
    if(abs(cnt)%2==0){
        cout<<"NO"<<endl;
        return 0;
    }

    cout<<"YES"<<endl;

    solve(A,B,0,(1<<N),0);

    for(int i=0;i<(1<<N);i++){
        cout<<S[i]<<" ";
    }
    cout<<endl;
}

