const int MAXBIT=17;

int nbit,a,b;

int ans[1<<MAXBIT],nans;

void gen(int a,int b,int done) {
	int idx=-1; REP(i,nbit) { bool same=((a>>i)&1)==((b>>i)&1); if(done&(1<<i)) assert(same); else if(idx==-1&&!same) idx=i; } assert(idx!=-1);
	if((done|(1<<idx))==(1<<nbit)-1) { ans[nans++]=a; ans[nans++]=b; return; }
	int otheridx=-1; REP(i,nbit) if(otheridx==-1&&i!=idx&&(done&(1<<i))==0) otheridx=i;
	gen(a,a^(1<<otheridx),done|(1<<idx));
	gen(a^(1<<otheridx)^(1<<idx),b,done|(1<<idx));
}

bool solve() {
	int c=a^b; int cnt=0; REP(i,nbit) if(c&(1<<i)) ++cnt; if(cnt%2==0) return false;
	nans=0; gen(a,b,0);
	return true;
}

void run() {
	scanf("%d%d%d",&nbit,&a,&b);
	if(!solve()) { printf("NO\n"); return; }
	printf("YES\n");
	REP(i,1<<nbit) { if(i!=0) printf(" "); printf("%d",ans[i]); } puts("");
}

