		int q = 0;
		while(((a ^ b) & (1 << q)) == 0) q++;
		vector<int> other_bits;
		for(int j = 0; j < n; j++) if(j != q && ((mask >> j) & 1)) other_bits.push_back(j);
		if(other_bits.size() > 1){
