    ret.eb(b);
    return ret;
  }

  rep(i, n) {
    int p = a >> i & 1;
    int q = b >> i & 1;
    assert(Insert(Remove(a, i), i, p) == a);
    assert(Insert(Remove(b, i), i, q) == b);
    if (p == q) {
      auto res = Create(n-1, Remove(a, i), Remove(b, i));
      for (int v : res) {
        ret.eb(Insert(v, i, p));
        ret.eb(Insert(v, i, p^1));
        p ^= 1;
      }
      assert(ret.front() == a);
      assert(ret.back() == b);
      assert(ret.size() == 1 << n);
      return ret;
    }
  }

  auto res = Create(n-2, a >> 2, b >> 2);
  deque<int> fgray = {0, 1, 3, 2};
  while (1) {
    int v = fgray.front();
    if (v == (a&3)) break;
    fgray.pop_front();
    fgray.eb(v);
  }

  deque<int> ngray;
  rep(i, 4) {
    ngray.eb(fgray[(i+3)%4]);
  }

  rep(i, 4) {
    ret.eb((res[0] << 2) | fgray[i]);
  }

  reps(i, 1, res.size()) {
    rep(j, 4) {
      ret.eb((res[i] << 2) | ngray[j]);
    }
    reverse(all(ngray));
  }
  assert(ret.front() == a);
  assert(ret.back() == b);
  assert(ret.size() == 1 << n);
  return ret;
}

