namespace max_flower
{
	int lst[400005], to[10000005], pre[10000005], cap[10000005], tot;
	int dep[400005], fst[400005], que[400005];
	inline void add_edge(int u, int v, int _cap)
	{
		auto add = [&] (int x, int y, int c)
		{
			to[tot] = y;
			pre[tot] = lst[x];
			cap[tot] = c;
			lst[x] = tot++;
		};
		add(u, v, _cap);
		add(v, u, 0);
	}
	inline bool bfs(int s, int t)
	{
		memset(dep, -1, sizeof(dep));
		int he = 0, ta = 0;
		que[ta++] = s;
		dep[s] = 0;
		while (he < ta)
		{
			int u = que[he++];
			for (int i = lst[u]; ~i; i = pre[i])
			{
				if (cap[i] && dep[to[i]] == -1)
				{
					dep[to[i]] = dep[u] + 1;
					que[ta++] = to[i];
				}
			}
		}
		return ~dep[t];
	}
	int dfs(int u, int t, int rem)
	{
		if (u == t)
			return rem;
		int ans = 0;
		for (int i = fst[u]; ~i; i = pre[i])
		{
			if (cap[i] && dep[to[i]] == dep[u] + 1)
			{
				int res = dfs(to[i], t, std::min(cap[i], rem - ans));
				cap[i] -= res;
				cap[i ^ 1] += res;
				if (cap[i])
					fst[u] = i;
				ans += res;
				if (ans == rem)
					return ans;
			}
		}
		if (!ans)
			dep[u] = -1;
		return ans;
	}
	inline int dinic(int s, int t)
	{
		int ans = 0;
		while (bfs(s, t))
		{
			memcpy(fst, lst, sizeof(lst));
			ans += dfs(s, t, 1e9);
		}
		return ans;
	}
	inline void init() { memset(lst, -1, sizeof(lst)); }
}
