void euler(int u)
{
	vis[u] = true;
	while (true)
	{
		int e = lst[u];
		if (e == -1)
			break;
		lst[u] = pre[e];
		if (del[e >> 1])
			continue;
		del[e >> 1] = true;
		euler(to[e]);
		seq[cnt++] = e;
	}
}
