const int N = 1e6;
int n, A, B;
int a[N];
int count(int x)
{
    int sum = 0;
    while (x)
    {
        sum += (x & 1);
        x >>= 1;
    }
    return sum;
}
void work(int*a, int n, int A, int B)
{
    if (!n)
    {
        a[0] = A;
        return;
    }
    if (n == 1)
    {
        a[0] = A;
        a[1] = B;
        return;
    }
    int sig = 0;
    int AA, BB;
    int x;
    while (1) {
        while (((1 << sig) & A) == ((1 << sig) & B)) sig++;
        AA = (A & ((1 << (sig)) - 1)) + ((A >> (sig + 1)) << (sig));
        BB = ((B & ((1 << (sig)) - 1)) + ((B >> (sig + 1)) << (sig)));
        x = 1;
        while ((AA ^ x) == BB && x <= (1 << (n - 2)) ) x <<= 1;
        if (x <= (1 << (n - 2))) break;
    }
    work(a, n - 1, AA, (AA ^ x));

    work(a + (1 << (n - 1)), n - 1, (AA ^ x), BB);
    for (int i = 0; i < (1 << (n - 1)) ; i ++)
        a[i] = ((a[i] >> (sig)) << (sig + 1)) + (a[i] & ((1 << (sig)) - 1)) + (A & (1 << sig));
    for (int i = (1 << (n - 1)); i < (1 << n) ; i ++)
        a[i] = ((a[i] >> (sig)) << (sig + 1)) + (a[i] & ((1 << (sig)) - 1)) + (B & (1 << sig));
}
