    if ((count(A) &1) == (count(B) & 1))
    {
        printf("NO");
        return 0;
    }
    work(a, n, A, B);
    printf("YES\n");
    for (int i = 0; i < (1 << n); i ++)
        printf("%d ", a[i]);
    return 0;
}

