void solve(int k,int A,int B,int *a)
{
	if(k==1){a[0]=A,a[1]=B;return;}
	int C=A^B,t=(C&-C);
	int tA=A%t+A/(t<<1)*t,tB=B%t+B/(t<<1)*t,tC=tA^1;
	solve(k-1,tA,tC,ta),solve(k-1,tC,tB,tb);
	for(int i=0;i<(1<<(k-1));i++)
	a[i]=ta[i]%t+ta[i]/t*(t<<1)+((A&t)?t:0);
	for(int i=0;i<(1<<(k-1));i++)
	a[i+(1<<(k-1))]=tb[i]%t+tb[i]/t*(t<<1)+((B&t)?t:0);
}
