int main() {
	ios_base::sync_with_stdio( false );
	cin.tie( nullptr );
	int n, a, b; cin >> n >> a >> b;
	if ( __builtin_popcount( a ^ b ) % 2 == 0 ) {
		cout << "NO\n";
		return 0;
	}
	cout << "YES\n";
	unordered_set< int > able;
	for ( int i = 0 ; i < n ; ++ i )
		able.insert( i );
	vector< int > ans;
	go( n - 1, a, b, ans, able );
	for ( size_t i = 0 ; i < ans.size() ; ++ i )
		cout << ( ans[ i ] ) << " \n"[ i + 1 == ans.size() ];
	return 0;
}

void go( int n, int a, int b, vector< int >& ret, unordered_set< int >& st ) {
	if ( not n ) {
		ret.push_back( a );
		ret.push_back( b );
		return;
	}
	int bt = -1;
	for ( auto p : st ) {
		if ( ( a ^ b ) & ( 1 << p ) ) {
			bt = p;
			break;
		}
	}
	st.erase( bt );
	int aa = min( a, a ^ ( 1 << bt ) );
	int bb = min( b, b ^ ( 1 << bt ) );
	int lb = *st.begin();
	go( n - 1, aa, aa ^ ( 1 << lb ), ret, st );
	go( n - 1, aa ^ ( 1 << lb ), bb, ret, st );
	int n2 = 1 << n;
	for ( int i = 1 ; i <= n2 ; ++ i )
		ret[ ret.size() - i - n2 * ( a != aa ) ] ^= 1 << bt;
	st.insert( bt );
}

