const int C = 18;

vi solve(int fullbit, int a, int b)
{
	int n = __builtin_popcount(fullbit);
	//cerr<<"CALL "<<fullbit<<' '<<a<<' '<<b<<'\n';
	if(n==1){return {a,b};}
	//cerr<<fullbit<<' '<<a<<' '<<b<<'\n';
	int xr = a^b; int difbit=-1;
	vi bits;
	for(int i=C;i>=0;i--)
	{
		if(fullbit&(1<<i))
		{
			if(xr&(1<<i))
			{
				difbit=i; break;
			}
		}
	}
	for(int i=0;i<=C;i++)
	{
		if(fullbit&(1<<i))
		{
			if(difbit==i) continue;
			bits.pb(i);
		}
	}
	int x=-1;
	bool flip=0;
	if(a&(1<<difbit))
	{
		flip=1; swap(a,b);
	}
	for(int i=0;i<(1<<(n-1));i++)
	{
		int num=0;
		for(int j=0;j<n-1;j++)
		{
			if(i&(1<<j)) num^=(1<<bits[j]);
		}
		//cerr<<num<<' '<<(1<<difbit)<<'\n';
		if(!(num&(1<<difbit)))
		{
			if(a!=num)
			{
				//cerr<<"NUM : "<<num<<' '<<__builtin_popcount(num)%2<<' '<<__builtin_popcount(a)%2<<'\n';
				if((__builtin_popcount(num)%2)!=(__builtin_popcount(a)%2))
				{
					x=num;
				}
			}
		}
	}
	//cerr<<"X : "<<x<<'\n';
	//cerr<<"SOLVE "<<a<<' '<<x<<' '<<(x^(1<<difbit))<<' '<<b<<'\n';
	vi p = solve(fullbit^(1<<difbit),a,x);
	vi R = solve(fullbit^(1<<difbit),x,b^(1<<difbit));
	//for(int v:p) cerr<<v<<' ';
	//for(int v:R) cerr<<v<<' ';
	//cerr<<'\n';
	for(int i=0;i<R.size();i++)
	{
		p.pb(R[i]^(1<<difbit));
	}
	if(flip) reverse(p.begin(),p.end());
	return p;
}

