{
	ios_base::sync_with_stdio(0); cin.tie(0);
	int n,a,b; cin>>n>>a>>b;
	int cnt1=__builtin_popcount(a);
	int cnt2=__builtin_popcount(b);
	if(cnt1%2==cnt2%2)
	{
		cout<<"NO\n"; return 0;
	}
	cout<<"YES\n";
	vi p = solve((1<<n)-1,a,b);
	for(int i=0;i<(1<<n);i++)
	{
		cout<<p[i];
		if(i+1<(1<<n)) cout<<' ';
	}
	cout<<'\n';
