vec solve(int a,int b,int t){
    if(t==1){
        return {a,b};
    }
    b^=a;
    int k;
    rep(i,t){
        if((1<<i)&b){
            k=(1<<i);break;
        }
    }
    int bb = b%k + b/k/2;
    vec res=solve(0,bb^1,t-1);
    for(auto &e:res)e=(e%k + (e/k)*2 );
    vec res2=solve(bb^1,bb,t-1);
    for(auto e:res2){
        res.pb(e%k + (e/k)*2 + k);
    }
    for(auto &e :res){
        e^=a;
    }
    return res;
}

