vec DC(int n,int s,int t)
{
    if(__builtin_popcount(s^t)%2==0){
        puts("NO");
        exit(0);
    }
    vec res(1<<n);
    if(n==1){
        res[0]=s,res[1]=t;
        return res;
    }
    int p=__builtin_ctz(s^t);
    int s1=Del(s,p),t1=Del(t,p);
    for(int u=0;;u++)
        if(__builtin_popcount(s1^u)&1){
            vec r1=DC(n-1,s1,u),r2=DC(n-1,u,t1);
            for(int i=0;i<(1<<(n-1));i++)
                res[i]=Add(r1[i],p,s>>p&1),res[i+(1<<(n-1))]=Add(r2[i],p,t>>p&1);
            return res;
        }
}
