int popcnt(int x) {
	int ret = 0;
	for(int i = 0; i < 17; i++) ret += (x >> i) & 1;
	return ret;
}

void build(int mask, int A, int B, int mask_val, int l, int r, vector<int> & ans) {
	cout << mask_val << " " << A << " " << B << " " << l << " " << r << "\n";
	if(l+1 == r) { // A == B
		ans[l] = mask_val;
		return;
	}
	int dif = A ^ B, c = (l + r) / 2;
	for(int i = 0; i < 17; i++) if((dif >> i) & 1) {
		if(mask == (1<<i)) {
			build(0, 0, 0, A | mask_val, l, c, ans);
			build(0, 0, 0, B | mask_val, c, r, ans);
			break;
		}
		for(int j = 0; j < 17; j++) if(j != i) if((mask >> j) & 1) {
			int C = (A - (A & (1<<i))) ^ (1<<j);
			build(mask - (1<<i), A - (A & (1<<i)), C, mask_val | (A & (1<<i)), l, c, ans);
			build(mask - (1<<i), C, B - (B & (1<<i)), mask_val | (B & (1<<i)), c, r, ans);
		}
		break;
	}
}

