int bits_diff(int n, int a, int b) {
    int diff = a^b;
    int c = 0;
    rep(i,0,n) if(diff&(1<<i)) ++c;
    return c;
}

vector<int> solve(int n, int a, int b) {
    assert(n>=1);
    b = b^a;
    vector<int> result(1<<n);
    int bdiff = bits_diff(n,0,b);
    assert(bdiff>=1);
    if(bdiff==1) {
        int below_mask = (b-1);
        int above_mask = ((1<<(n-1))-1)^below_mask;
        rep(i,0,(1<<n)) {
            int gray = i^(i/2);
            bool has_big = gray&(1<<(n-1));
            result[i] = (gray&below_mask)+((gray&above_mask)<<1);
            if(has_big) result[i] += b;
        }
    }
    else {
        assert(bdiff>=3);
        int first = -1, second = -1;
        rep(i,0,n) {
            if(first==-1 && ((b&(1<<i))>0)) first = 1<<i;
            else if(second==-1 && ((b&(1<<i))>0)) second = 1<<i;
        }
        int below_mask = (second-1);
        int above_mask = ((1<<n)-1)^((second<<1)-1);
        int bb = (b&below_mask)|((b&above_mask)>>1);
        auto first_part = solve(n-1,0,first);
        auto second_part = solve(n-1,first,bb);
        above_mask = ((1<<(n-1))-1)^below_mask;
        rep(i,0,1<<(n-1)) {
            int x = first_part[i];
            result[i] = (x&below_mask)+((x&above_mask)<<1);
        }
        rep(i,0,1<<(n-1)) {
            int x=  second_part[i];
            result[i+(1<<(n-1))] = (x&below_mask)+((x&above_mask)<<1)+second;
        }
    }
    for(int &x:result) x^=a;
    return result;
}

