int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int n, a, b; cin >> n >> a >> b;
  int check_a = 0, check_b = 0;
  REP(i, n) {
    if ((a >> i) & 1) ++check_a;
    if ((b >> i) & 1) ++check_b;
  }
  if (abs(check_a - check_b) != 1) {
    cout << "NO\n";
    return 0;
  }
  cout << "YES\n";
  int mx = 1;
  REP(i, n) mx <<= 1;
  vector<bool> used(mx, false);
  used[a] = used[b] = true;
  vector<int> ans(mx);
  int now = a;
  ans[0] = a;
  FOR(i, 1, mx) {
    bool changed = false;
    REP(j, n) if (!((now >> j) & 1)) {
      int tmp = now | (1 << j);
      if (!used[tmp]) {
        ans[i] = tmp;
        used[tmp] = true;
        now = tmp;
        changed = true;
        break;
      }
    }
    if (changed) continue;
    REP(j, n) if ((now >> j) & 1) {
      int tmp = now ^ (1 << j);
      if (!used[tmp]) {
        ans[i] = tmp;
        used[tmp] = true;
        now = tmp;
        changed = true;
        break;
      }
    }
  }
  ans[mx - 1] = b;
  REP(i, mx) cout << ans[i] << (i == mx - 1 ? '\n' : ' ');
  return 0;
}

