string changeBase(int N, int b, int digit = -1) {
    string s = "";
    while (N != 0) {
        s = to_string(N % b) + s;
        N /= b;
    }
    if (digit != -1) {
        while (s.length() < digit) {
            s = "0" + s;
        }
    }
    return s;
}

int to10(string S) {
    reverse(S.begin(), S.end());
    int ret = 0;
    rep(i, S.length()) {
        ret += (S[i] - '0') << i;
    }
    return ret;
}

int main() {
//    cout<<to10("01001")<<endl;
    int N, A, B;
    cin >> N >> A >> B;
    string st = changeBase(A, 2);
    string en = changeBase(B, 2);
    if (st.length() > en.length()) {
        en = changeBase(B, 2, st.length());
    } else {
        st = changeBase(A, 2, en.length());
    }
    int len = st.length();

    vi ans;
    ans.push_back(A);
