string tob(int n, int m) {
  stringstream ss;
  ss << bitset<17>(m);
  return ss.str().substr(17-n, n);
}

vector<string> calc(int n, string ss, string es) {
  // s,eで異なる桁dを探す。
  // その桁を除いた問題を解けばよい。
  // 接続点はsを反転したものを使う。これがeと等しいなら初めの桁を変更する。
  int d;
  rep(i, n){
    if (ss[i]!=es[i]){
      d=i;
      break;
    }
  }

  string ns="";
  string mm="";
  string ne="";
  rep(i, n){
    if (i==d) continue;
    else {
      ns += ss[i];
      mm += ss[i]=='1'?'0':'1';
      ne += ss[i]=='1'?'0':'1';
    }
  }
  if (mm==ne) mm = ((mm[0]=='1'?'0':'1') + mm.substr(1));
  dump(ns, es);

  vector<string> pres = calc(n-1, ns, mm);
  vector<string> ares = calc(n-1, mm, ne);
  vector<string> res;
  for(auto x:pres){
    string tmp="";
    tmp += x.substr(0, d);
    tmp += ss[d];
    tmp += x.substr(d, n-d);
    res.pb(tmp);
  }
  for(auto x:ares){
    string tmp="";
    tmp += x.substr(0, d);
    tmp += es[d];
    tmp += x.substr(d, n-d);
    res.pb(tmp);
  }
  return res;
}

