}

vi rek(int k, int a, int b)
{
	//~ debug() << k << " " << a << " " << b;
	if (k==1)
		return {a, b};
	int m=(1<<k);
	int x=a^b;
	if (__builtin_popcount(x)==1)
	{
		for (int i=0; i<k; i++)
		{
			if (!(x&(1<<i)))
			{
				debug() << i;
				vi wez=rek(k-1, usun(a, i), usun(b, i));
				debug() << wez;
				vi ret;
				for (int j=0; j<m/2; j++)
				{
					if (!(j&1))
					{
						ret.push_back(wstaw(wez[j], i, (a>>i)&1));
						ret.push_back(wstaw(wez[j], i, ((a>>i)&1)^1));
					}
					else
					{
						ret.push_back(wstaw(wez[j], i, ((a>>i)&1)^1));
						ret.push_back(wstaw(wez[j], i, (a>>i)&1));
					}
				}
				return ret;
			}
		}

		assert(0);
	}
	vi roz;
	for (int i=0; i<k; i++)
		if (x&(1<<i))
			roz.push_back(i);
	x=roz[0];
	int y=roz[1];
	int z=roz[2];

	int na=usun(a, z);
	int nb=usun(b, z);

	vi raz=rek(k-1, na, na^(1<<x));
	vi dwa=rek(k-1, nb^(1<<y), nb);

	vi ret;
	for (int i : raz)
		ret.push_back(wstaw(i, z, (a>>z)&1));
	for (int i : dwa)
		ret.push_back(wstaw(i, z, (b>>z)&1));

	return ret;
}

