#include <bits/stdc++.h>

ulong diff(ulong a, ulong b){
    return __builtin_ctzl(a^b);
}

ulong hd(ulong a, ulong b){
    return __builtin_popcountl(a^b);
}

ulong bit_remove(ulong a, ulong n){
    ulong low  = a & ((1<<n)-1);
    ulong high = (a >> (n+1)) << n;
    return high | low;
}

ulong bit_insert(ulong a, ulong n, ulong b){
    ulong low  = a & ((1<<n)-1);
    ulong high = (a >> n) << (n+1);
    return high | (b<<n) | low;
}

long data[1<<17];

void solve(const long n, const long a, const long b, const size_t sp, const size_t ep){
    if(n==1){
        data[sp+0] = a;
        data[sp+1] = b;
        return;
    }
    ulong d = diff(a, b);
    ulong aa = bit_remove(a, d);
    ulong ab = bit_remove(a, d) ^ 1;
    ulong bb = bit_remove(b, d);
    const size_t mp = (sp+ep)/2;
    solve(n-1, aa, ab, sp, mp);
    solve(n-1, ab, bb, mp, ep);
    for(size_t i=sp; i<mp; i++){
