const int L = 18;

bool is_lr(int l, int r) {
    return (__builtin_popcount(l) ^ __builtin_popcount(r)) & 1;
}

void dfs(const vi & a, int l, int r, vi & ans) {
    assert(is_lr(l, r));
    if (a.empty()) {
        ans.push_back(l);
        ans.push_back(r);
        assert(__builtin_popcount(l ^ r) == 1);
        return;
    }
    vi f, s;
    int bt;
    for (int i = 0; ; ++i) {
        if (((l ^ r) >> i) & 1) {
            bt = i;
            break;
        }
    }

    for (auto c : a) {
        if (((c >> bt) & 1) == ((l >> bt) & 1)) {
            f.push_back(c);
        } else {
            s.push_back(c);
        }
    }
    set<int> sts(ALL(s));
    for (auto c : f) {
        fori (i, L) {
            int nc = c ^ (1 << i);
            if (is_lr(l, c) && sts.count(nc)) {
                f.erase(find(ALL(f), c));
                s.erase(find(ALL(s), nc));
                dfs(f, l, c, ans);
                dfs(s, nc, r, ans);
                return;
            }
        }
    }
    assert(0);
}

