		double now_min = 0;
		int starter = ans[ans.size() - 1];
		for (int i = 0; i < a.size(); ++i) {
			if (i != starter) {
				double goa = angles(ba, a[i] - a[starter]);
				if (goa > now_min) {
					now_min = goa;
					now_go = i;
				}
			}
		}
		if (now_go == ans[0]) break;
		ans.push_back(now_go);
		ba = complex<double>(a[now_go] - a[starter]);
	}
	return ans;
}
long long gcd(long long a, long long b) {
	if (b == 0) return a;
	return gcd(b, a % b);
}
long long mod = 2;
vector<long long> kake(vector<long long> a, vector<long long> b) {
	vector<long long> ans;
	int size_a = sqrt(a.size());
	REP(i, size_a) {
		REP(q, size_a) {
			long long tmp = 0;
			REP(j, size_a) {
				tmp += a[i * size_a + j] * a[j * size_a + q];
				tmp %= mod;
			}
			ans.push_back(tmp);
		}
	}
	return ans;
}
int swa(int a, int i, int j) {
	if ((a & (1 << i)) != 0 && (a & (1 << j)) == 0) a += (1 << j) - (1 << i);
	else if ((a & (1 << i)) == 0 && (a & (1 << j)) != 0) {
		a += (1 << i) - (1 << j);
	}
	return a;
}
vector<long long> solve(int n, int a, int b) {
	if (n == 1) return { a,b };
	int change = n - 1;
	int c = a ^ b;
	if ((c & (1 << (n - 1))) == 0) {
		for (int d = n - 1; d > 0; --d) {
			if (c & (1 << d)) {
				change = d;
				break;
			}
		}
	}
	swa(a, n - 1, change);
	swa(b, n - 1, change);
	int na = a & ~(1 << (n - 1));
	vector<long long> zenhan = solve(n - 1, na, na ^ 1);
	int nb = b & ~(1 << (n - 1));
	vector<long long> kouhan = solve(n - 1, na ^ 1, nb);
	vector<long long> ans;
	if (a & (1 << (n - 1)) != 0) {
		REP(i, zenhan.size()) {
			ans.push_back(zenhan[i] ^ (1 << (n - 1)));
		}
		REP(i, kouhan.size()) {
			ans.push_back(kouhan[i]);
		}
	}
	else {
		REP(i, zenhan.size()) {
			ans.push_back(zenhan[i]);
		}
		REP(i, kouhan.size()) {
			ans.push_back(kouhan[i] ^ (1 << (n-1)));
		}
	}
	REP(i, ans.size()) {
		swa(ans[i], n - 1, change);
	}
	return ans;
}
