                int mid = ((1 << n) - 1) >> 1;

                numbers[mid] = numbers[mid + 1] = (numbers[0] & mask) ^ (1 << ss);

                solve(0, mid, (a & (1 << i)), n - 1, mask);
                solve(mid + 1, (1 << n) - 1, (b & (1 << i)), n - 1, mask);
                break;
            }
        }

        cout << "YES" << endl;

