vector<ll> solve(ll A, ll B, ll N){
    vector<ll> res;
    if(N == 2){
        res.push_back(A);
        res.push_back(B);
        return res;
    }
    rep(i,0,N){
        if(((A>>i) & 1) != ((B>>i) & 1)){
            ll v = (1LL<<i);
            ll c = A;
            rep(j,0,N){
                if(i != j){
                    c ^= (1LL<<j);
                    break;
                }
            }
            ll a = A % v + (A - A % (v*2)) / 2;
            ll b = B % v + (B - B % (v*2)) / 2;
            c = c % v + (c - c % (v*2)) / 2;

            // print(i,a,b,c, N);
            vector<ll> r1 = solve(a,c,N/2);
            vector<ll> r2 = solve(c,b,N/2);
            // print(a,b);
            // vector<ll> rr = solve(a, b, N/2);
            ll bit1 = ((A>>i) & 1), bit2 = ((B>>i) & 1);
            for(auto &e: r1){
                ll val = e % v + (1LL<<i) * bit1 + (e - e % v) * 2;
                res.push_back(val);
            }
            for(auto &e: r2){
                ll val = e % v + (1LL<<i) * bit2 + (e - e % v) * 2;
                res.push_back(val);
            }

            break;
        }
    }
    return res;


}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N,A,B;
    cin >> N >> A >> B;
    ll na = __builtin_popcount(A);
    ll nb = __builtin_popcount(B);
    if(na % 2 == nb % 2){
        print("NO");
        return 0;
    }
    print("YES");
    vector<ll> ans = solve(A, B, (1LL<<N));
    printa(ans, (1LL<<N));



}

