void swap_bit(int&x,int i,int j){
	if(i==j)return;
	x^=((x>>i)&1)<<j;
	x^=((x>>j)&1)<<i;
	x^=((x>>i)&1)<<j;
}

vi Solve(int n,int a,int b){
	if(n==1)
		return {a,b};
	int pos=n-1;
	REP(i,n)if((a^b)&(1<<i))
		pos=i;
	swap_bit(a,pos,n-1);
	swap_bit(b,pos,n-1);
	vi res;
	int atop=a&(1<<(n-1));
	int btop=b&(1<<(n-1));
	vi x=Solve(n-1,a-atop,(a-atop)^1);
	vi y=Solve(n-1,(a-atop)^1,b-btop);
	for(auto v:x)
		res.PB(v+atop);
	for(auto v:y)
		res.PB(v+btop);
	for(auto&v:res)
		swap_bit(v,pos,n-1);
	return res;
}

