vector<int> solve(int n, int a, int b) {
    if (a == b) {
        return {};
    }
    int bit = -1;
    int cnt = __builtin_popcount(a ^ b);
    for (int i = (1 << (n - 1)); i; i >>= 1) {
        if ((a ^ b) & i) {
            bit = i;
            break;
        }
    }
    vector<int> aa, bb;
    if (cnt % 2 == 1) {
        int bit2 = -1;
        for (int j = (bit >> 1); j; j >>= 1) {
            if ((a ^ b) & j) {
                bit2 = j;
                break;
            }
        }
        if (bit2 != -1) {
            aa = solve(n, a, b ^ bit ^ bit2);
            bb = solve(n, b ^ bit2, b);
        } else {
            aa = bb = {};
        }
        vector<int> ans = aa;
        ans.push_back(bit);
        for (auto x: bb) {
            ans.push_back(x);
        }
        return ans;
    }
    throw;
}


