vector<int> dfs(int m,int a,int b){
    /* cout << "call m,a,b = " << bitset<5>(m) << " " << bitset<5>(a) << " " << bitset<5>(b) << endl; */
    if(__builtin_popcount(m) == 1){
        vector<int> ret{a,b};
        /* cout << "return " << ret << endl; */
        return ret;
    }
    int x = (a^b)&m;
    x=x&-x;     // maskの中でaとbが異なるbitの最右bit
    int m2 = m^x;
    /* cout << "m2 = " << bitset<5>(m2) << endl; */
    // mask(m2)の範囲ではa,bは経ってるbitの偶奇が等しい
    // cはm2の範囲でaと1bitだけ異なる
    int c = a ^ (m2 & -m2);
    auto l = dfs(m2,a,c);
    auto r = dfs(m2,c^x,b);
    for(auto rr : r) l.emplace_back(rr);
    return l;
}

