#include <bits/stdc++.h>
using namespace std;

vector<int> getFull(int n);
vector<int> getSequence(int n, int end);

int bits(int x) {
    int ans = 0;
    while(x > 0) {
        ans += (x % 2);
        x /= 2;
    }
    return ans;
}

bool good(int x, int y) {
    int z = (x xor y);
    return (z & (z - 1)) == 0;
}

bool goodSequence(vector<int> a) {
    int n = a.size();
    for(int i = 1; i < n; i += 1) {
        if(not good(a[i], a[i - 1]))
            return false;
    }
    return true;
}

vector<int> getGrayCode(int n) {
    cerr << "GETGRAY " << n << "\n";
    if(n == 1)
        return {0, 1};
    vector<int> ret = getGrayCode(n - 1);
    for(int i = int(ret.size()) - 1; i >= 0; i -= 1) {
        ret.push_back((1 << (n - 1)) + ret[i]);
    }
    return ret;
}

vector<int> getFull(int n) {
    cerr << "GETFULL " << n << "\n";
    if(n == 1)
        return {0, 1};
    vector<int> ret = getGrayCode(n - 1);
    int last = (1 << (n - 1)) - 1;
    int last_ret = ret.back();

    vector<int> second = getSequence(n - 1, last ^ last_ret);

    for(auto& val : second) {
        val ^= last_ret;
        val += (1 << (n - 1));
        ret.push_back(val);
    }
    return ret;
}

vector<int> getSequence(int n, int end) {
    cerr << "GETSEQUENCE " << n << " " << end << "\n";
    if(n == 1) {
        if(end == 0) 
            return {1, 0};
        else
            return {0, 1};
    }

    if(end == ((1 << n) - 1)) {
        return getFull(n);
    }

    vector<int> pos(n, 0);

    for(int i = 0; i < n; i += 1)
        if((1 << i) & end) {
            pos[i] = 1;
        }

    int k = bits(end);

    vector<int> alfa = getGrayCode(n - k);
    vector<int> beta = getFull(k);

    for(auto elem : alfa)
        cerr << elem << " ";
    cerr << "\n";
    for(auto elem : beta)
        cerr << elem << " ";
    cerr << "\n";

    vector<int> ret((1 << n), 0);

    for(int i = 0; i < (1 << n); i += 1) {
        int temp_beta = beta[i / (1 << (n - k))];
        int par = (i / (1 << (n - k))) % 2;
        int temp_alfa = alfa[i % alfa.size()];
        if(par)
            temp_alfa = alfa[alfa.size() - 1 - i % alfa.size()];

        for(int j = 0; j < n; j += 1) {
            if(pos[j] == 0) {
                ret[i] += (1 << j) * (temp_alfa % 2);
                temp_alfa /= 2;
            } else {
                ret[i] += (1 << j) * (temp_beta % 2);
                temp_beta /= 2;
            }
        }
    }

    return ret;
}

int main() {
    int n, a, b; cin >> n >> a >> b;

    if(bits(a) % 2 == bits(b) % 2) {
        cout << "NO\n";
