    vector<int> seq = getSequence(n, c);
    assert(goodSequence(seq));

    for(auto &val : seq) {
        val ^= a;
        cout << val << " ";
    }
}

#include<bits/stdc++.h>
using namespace std;

int n;
int dfs(int pos,int cnt,int a,int bit,vector<int>& tmp){
    int keta=(pos+cnt)%n;
    if(cnt==0){
        if((bit>>cnt)&1) return a;
        else{
            a^=(1<<keta);
            tmp.push_back(a);
            return a;
        }
    }
    else{
        if((bit>>cnt)&1) return dfs(pos,cnt-1,a,bit,tmp);
        else{
            a=dfs(pos,cnt-1,a,bit,tmp);
            a^=(1<<keta);
            tmp.push_back(a);
            a=dfs(pos,cnt-1,a,bit,tmp);         
            return a;
        }
    }
}
void solve(int a,int b,int bit,vector<int> &v){
    if(a==b){
        v.push_back(b);
        return;
    }
    for(int i=0;i<n;i++){
        if(((a^b)>>i)&1){
            bit^=(1<<i);
            for(int j=0;j<n;j++){
                vector<int> tmp;
                tmp.push_back(a);
                int x=dfs(j,n-1,a,bit,tmp);
                if(x!=b){
                    v.insert(v.end(),tmp.begin(),tmp.end());
                    solve(x^(1<<i),b,bit,v);
                    return;
                }
            }
        }
    }
}
