ll N, A, B;

void input() {
    cin >> N >> A >> B;
//    N = 4;
//    A = 0b00001;
//    B = 0b00011;
}

void bitshow(ll x) {
    for (ll i = N; i > 0; i--) {
        cerr << (x >> (i - 1) & 1);
    }
    cerr << endl;
}

void show(ll x) {
    cout << x << endl;
//    bitshow(x);
}

ll bitchange(ll x, ll n) {
    x ^= 1ull << n;
    show(x);
    return x;
}

ll bitroutine(ll x, ll n) {
    if (n == -1)
        return x;

    x = bitroutine(x, n - 1);
    x = bitchange(x, n);
    x = bitroutine(x, n - 1);
    return x;
}

void solve() {
    ll haminglen = A ^ B;
    ll eo = 0;
    for (ll i = 0; i < N; i++) {
        if ((haminglen >> i) & 1)
            eo ^= 1;
    }
    if (eo == 0) {
        cout << "NO" << endl;
        return;
    }
    cout << "YES" << endl;

    if (A > B)
        swap(A, B);

    show(A);
    ll x = A;

    ll topa = -1;
    for (ll i = N - 1; i >= 0; i--) {
        if (A >> i & 1) {
            topa = i;
            break;
        }
    }
    ll topb = -1;
    for (ll i = N - 1; i >= 0; i--) {
        if (B >> i & 1) {
            topb = i;
            break;
        }
    }
    if (topb > 0) {
        if (topa == topb) {
            x = bitchange(x, topb);
            x = bitroutine(x, topb - 1);
        } else {
            x = bitroutine(x, topb - 1);
        }
    }

    for (ll i = N - 1; i >= topb; i--) {
        ll xdf = x ^ B;
        if (xdf >> i & 1) {
            x = bitroutine(x, i - 1);
            x = bitchange(x, i);
        } else {
            x = bitchange(x, i);
            x = bitroutine(x, i - 1);
            x = bitchange(x, i);
        }
    }
}

int main() {
    input();
//    cout << solve() << endl;
    solve();

    return 0;
}

