vector<int> go(int n, int a, int b) {
	if (n == 1) {
		assert((a ^ 1) == b);
		return {a, b};
	}
	int bit = (1 << (n - 1));
	bool bita = a & bit;
	bool bitb = b & bit;
	vector<int> z;
	if (bita != bitb) {
		int mid = a ^ 1;
		auto x = go(n - 1, a, mid);
		auto y = go(n - 1, mid ^ bit, b);
		z = x;
		z.insert(z.end(), y.begin(), y.end());
	} else {
		auto x = go(n - 1, a, b);
		for (int i = 0; i < x.size(); i += 2) {
			z.push_back(x[i]);
			z.push_back(x[i] ^ bit);
			z.push_back(x[i + 1] ^ bit);
			z.push_back(x[i + 1]);
		}
	}
	return z;
}
