void proc(int n, int b, int x, vi &v) {
    if (n == 0) {
        v.push_back(x);
        v.push_back(b ^ x);
        return;
    }

    if ((b >> n) == 0) {
        proc(n - 1, b, x, v);
        int orib = v[v.size()-1];
        int l1 = v[v.size()-1] ^ x;
        int l2 = v[v.size()-2] ^ x;
        v.resize(v.size()-1);
        b = l1 ^ l2;
        x ^= l2 ^ (1 << n);
        proc(n - 1, b, x, v);
        v.push_back(orib);
    } else {
        proc(n - 1, 1, x, v);
        b ^= (1 ^ (1 << n));
        x ^= (1 ^ (1 << n));
        proc(n - 1, b, x, v);
    }
}

