ll bitchange(ll x, ll n) {
    x ^= 1ull << n;
    show(x);
    cnt[x]++;
    return x;
}

ll bitroutine(ll x, ll n) {
    if (n == -1)
        return x;

    x = bitroutine(x, n - 1);
    x = bitchange(x, n);
    x = bitroutine(x, n - 1);
    return x;
}

void solve() {
    ll haminglen = A ^ B;
    ll eo = 0;
    for (ll i = 0; i < N; i++) {
        if ((haminglen >> i) & 1)
            eo ^= 1;
    }
    if (eo == 0) {
