        return;
    }
    cout << "YES" << endl;

    if (A > B)
        swap(A, B);

    cnt[A]++;
    show(A);
    ll x = A;

    ll topa = -1;
    for (ll i = N - 1; i >= 0; i--) {
        if (A >> i & 1) {
            topa = i;
            break;
        }
    }
    ll topb = -1;
    for (ll i = N - 1; i >= 0; i--) {
        if (B >> i & 1) {
            topb = i;
            break;
        }
    }
    if (topb > 0) {
        if (topa == topb) {
            x = bitchange(x, topb);
            x = bitroutine(x, topb - 1);
        } else {
            x = bitroutine(x, topb - 1);
        }
    }

    for (ll i = N - 1; i >= topb; i--) {
        ll xdf = x ^ B;
        if (xdf >> i & 1) {
            x = bitroutine(x, i - 1);
            x = bitchange(x, i);
        } else {
            x = bitchange(x, i);
            x = bitroutine(x, i - 1);
            x = bitchange(x, i);
        }
    }
}

