#define MAX_N (17L)

long mod(long n, long k) {
  return n % k >= 0 ? n % k : n % k + k;
}

int main(int argc, char *argv[]) {
  // read inputs
  long N, A, B;
  scanf("%ld %ld %ld", &N, &A, &B);

  // check if it is possible
  long cnt_diff = 0, i_diff = -1;
  for (long i = 0; i < N; i++) {
    if ((A ^ B) & (1 << i)) {
      cnt_diff++;
      i_diff = i;
    }
  }
  if (cnt_diff != 1) {
    printf("NO\n");
    exit(0);
  }
  // printf("A = 0x%08lx, B = 0x%08lx, i_diff = %ld\n", A, B, i_diff);

  // create sequence
  long ps[1L << MAX_N] = {};
  ps[0] = 0;
  ps[1] = 1L << i_diff;
  for (long k = 2; k <= N; k++) {
    // mirror
    const long two_pow_k = 1 << k, two_pow_km1 = 1 << (k - 1);
    for (long i = 0; i < two_pow_km1; i++) {
      ps[two_pow_k - 1 - i] = ps[i];
    }
    // printf("after mirror\n");
    // for (long i = 0; i < two_pow_k; i++) {
    //   printf("%ld\n", ps[i]);
    // }
    // fill 1s
    const long i_fill = N + 1 - k <= i_diff ? N - k : N + 1 - k;
    // printf("k = %ld, i_fill = %ld\n", k, i_fill);
    for (long i = two_pow_km1; i < two_pow_k; i++) {
      ps[i] |= 1 << i_fill;
    }
    // check
    // printf("after fill\n");
    // for (long i = 0; i < two_pow_k; i++) {
    //   printf("%ld\n", ps[i]);
    // }
  }

  // find A
  long i0 = -1, b = -1;
  for (long i = 0, i_end = 1 << N; i < i_end; i++) {
    if (ps[i] == A) {
      i0 = i;
      if (i + 1 < 1 << N && ps[i + 1] == B) {
        b = 0;  // go to the negative side
      } else if (i - 1 >= 0 && ps[i - 1] == B) {
        b = 1;  // go to the positive side
      }
    }
  }
  // printf("i0 = %ld, b = %ld\n", i0, b);

  // print answer
  printf("YES\n");
  if (b) {
    for (long i = 0, i_end = 1 << N; i < i_end; i++) {
      printf("%ld ", ps[mod(i0 + i, 1 << N)]);
    }
    printf("\n");
  } else {
    for (long i = 0, i_end = 1 << N; i < i_end; i++) {
      printf("%ld ", ps[mod(i0 - i, 1 << N)]);
    }
    printf("\n");
  }

  return 0;
}

