	if((1<<N)-2<cnt)
	{
		puts("NO");
		return 0;
	}
	write(A),putchar(32);
	C=A^B;
	while(C)
	{
		int lbit=C&(-C);
		A^=lbit;
		write(A),putchar(32);
		C-=lbit;
	}
	for(int i=(1<<N)-1;i>cnt;--i)
	{
		B^=1;
		write(B),putchar(32);
	}
	return 0;
}

#include <bits/stdc++.h>


uint32_t bit_flag[17];
uint32_t bit_low_all[17];

std::vector<uint32_t> gen(const uint16_t n, const uint32_t a,
  const uint32_t b) {
  if (n == 0) {
    return {a, b};
  } else {
    std::bitset<17> bit(a^b);
    uint16_t diff = 0;
    for (uint16_t i = 0; i < 17; i++) {
      if (bit[16 - i]) {
        diff = 16 - i;
        break;
      }
    }
    bool a_diff_bit = (a & bit_flag[diff]) != 0;

    uint32_t a_v, b_v, c_v;
    if (diff == 0) {
      a_v = a >> 1;
      b_v = b >> 1;
      c_v = a_v ^ bit_flag[n - 1];
    } else if (diff == n) {
      a_v = a & bit_low_all[n - 1];
      b_v = b & bit_low_all[n - 1];
      c_v = a & bit_low_all[n - 1];
      c_v = a_v ^ bit_flag[0];
    } else {
      a_v = ((a & ~bit_low_all[diff]) >> 1) | (a & bit_low_all[diff - 1]);
      b_v = ((b & ~bit_low_all[diff]) >> 1) | (b & bit_low_all[diff - 1]);
      c_v = a_v ^ bit_flag[n - 1];
    }
    const auto before = gen(n - 1, a_v, c_v);
    const auto after = gen(n - 1, c_v, b_v);
    std::vector<uint32_t> result(before.size() + after.size());
    const auto itr
      = std::copy(before.cbegin(), before.cend(), result.begin());
    std::copy(after.cbegin(), after.cend(), itr);

    for (size_t i = 0; i < before.size(); i++) {
      if (diff == 0) {
        result[i] <<= 1;
        if (a_diff_bit) {
          result[i] |= bit_flag[0];
        }
      } else if (diff == n) {
        if (a_diff_bit) {
          result[i] |= bit_flag[n];
        }
      } else {
        result[i] = ((result[i] & ~bit_low_all[diff - 1]) << 1) |
          (result[i] & bit_low_all[diff - 1]);
        if (a_diff_bit) {
          result[i] |= bit_flag[diff];
        }
      }
    }
    for (size_t i = before.size(); i < before.size() + after.size(); i++) {
      if (diff == 0) {
        result[i] <<= 1;
        if (!a_diff_bit) {
          result[i] |= bit_flag[0];
        }
      } else if (diff == n) {
        if (!a_diff_bit) {
          result[i] |= bit_flag[n];
        }
      } else {
        result[i] = ((result[i] & ~bit_low_all[diff - 1]) << 1) |
          (result[i] & bit_low_all[diff - 1]);
        if (!a_diff_bit) {
          result[i] |= bit_flag[diff];
        }
      }
    }
    return result;
  }
}

int main() {
  uint16_t n;
  uint32_t a, b;
  std::cin >> n >> a >> b;

  bit_flag[0] = 1;
  bit_low_all[0] = 1;
  for (uint16_t i = 1; i < 17; i++) {
    bit_flag[i] = 2 * bit_flag[i - 1];
    bit_low_all[i] = bit_low_all[i - 1] + bit_flag[i];
  }

  std::bitset<17> bit(a^b);
  if (bit.count() % 2 == 0) {
    std::cout << "NO" << std::endl;
  } else {
    std::cout << "YES" << std::endl;
    const auto val = gen(n - 1, a, b);
    for (size_t i = 0; i < val.size(); i++) {
      std::cout << val[i];
      if (i + 1 != val.size()) {
        std::cout << " ";
      }
    }
  }
