#include <bits/stdc++.h>
using namespace std;

queue<int> dat[20];

int bit_cnt(int n){
    int ans = 0;
    while(n > 0){
        ans += (n & 1);
        n >>= 1;
    }

    return ans;
}

int main(){
    int n, a, b;
    cin >> n >> a >> b;

    if(bit_cnt(a) % 2 == bit_cnt(b) % 2){
        cout << "NO" << endl;
        return 0;
    }

    for(int i = 0;i < (1 << n);i++){
        if(i != a && i != b){
            dat[bit_cnt(i)].push(i);
        }
    }

    queue<int> fi;
    stack<int> se;

    bool fip = true;
    bool sep = true;
    int ficnt = bit_cnt(a);
    int secnt = bit_cnt(b);

    fi.push(a);
    se.push(b);
    for(int i = 0;i < (1 << n)-2;i++){
        if(i % 2 == 0){
            if(fip){
                if(ficnt+1 > n || dat[ficnt+1].empty()){
                    fip = false;
                    ficnt--;
                }else{
                    ficnt++;
                }
            }else{
                if(ficnt-1 < 0 || dat[ficnt-1].empty()){
                    fip = true;
                    ficnt++;
                }else{
                    ficnt--;
                }
            }

            if(dat[ficnt].empty()){
                cout << "NO" << endl;
                return 0;
            }
            fi.push(dat[ficnt].front());
            dat[ficnt].pop();

        }else{
            if(sep){
                if(secnt+1 > n || dat[secnt+1].empty()){
                    sep = false;
                    secnt--;
                }else{
                    secnt++;
                }
            }else{
                if(secnt-1 < 0 || dat[secnt-1].empty()){
                    sep = true;
                    secnt++;
                }else{
                    secnt--;
                }
            }

            if(dat[secnt].empty()){
                cout << "NO" << endl;
                return 0;
            }

            se.push(dat[secnt].front());
            dat[secnt].pop();
        }
    }

    vector<int> vec;


    while(!fi.empty()){
        vec.push_back(fi.front());
        fi.pop();

    }

    while(!se.empty()){
        vec.push_back(se.top());
        se.pop();
    }

    for(int i = 0;i < vec.size()-1;i++){
        if(abs(bit_cnt(vec[i])-bit_cnt(vec[i+1])) != 1){
            cout << "NO" << endl;
            return 0;
        }
    }

    cout << "YES" << endl;

    for(int i = 0;i < vec.size();i++){
        cout << vec[i];
        if(i == vec.size()-1){
            cout << endl;
        }else{
            cout << " ";
        }
    }


    return 0;
}

