int fs(int x) {
	for (int i = 0; i < n; ++i)
		if ((x >> i) & 1)
			return i;
	return 0;
}

void run(int x, int y) {
	int c = __builtin_popcount(x);
	if (c == 1) {
		if (y == 0) {
			ans[now] = ans[now - 1] ^ x;
			++now;
		}
		else {
			int b = fs(y);
			run(1 << b, y ^ (1 << b));
			ans[now] = ans[now - 1] ^ x;
			++now;
			run(1 << b, y ^ (1 << b));
		}
	}
	else {
		int a = fs(x);
		int b = fs(x ^ (1 << a));
		run(x ^ (1 << a) ^ (1 << b), y ^ (1 << b));
		ans[now] = ans[now - 1] ^ (1 << a);
		++now;
		run(1 << b, y ^ x ^ (1 << a) ^ (1 << b));
	}
}


