namespace adaptor = boost::adaptors;

struct bit_shuffler
{
	int N;
	int target;
	int count;
	std::vector<int> con, inv;
	bit_shuffler(int n, int t):N(n), target(t), count(0), con(n), inv(n)
	{
		int i = 0;
		for (int k : boost::irange(0, N))
		{
			if ((target&(1 << k)) != 0)
			{
				con[k] = i;
				inv[i] = k;
				++i;
			}
		}
		count = i;
		for (int k : boost::irange(0, N))
		{
			if ((target&(1 << k)) == 0)
			{
				con[k] = i;
				inv[i] = k;
				++i;
			}
		}
	}
	int convert(int v)
	{
		int ret = 0;
		for (int k : boost::irange(0, N))
		{
			ret += (v % 2) << con[k];
			v /= 2;
		}
		return ret;
	}
	int invert(int v)
	{
		int ret = 0;
		for (int k : boost::irange(0, N))
		{
			ret += (v % 2) << inv[k];
			v /= 2;
		}
		return ret;
	}

};

void Main()
{
	int N, A, B;
	std::cin >> N >> A >> B;
	int T = A ^ B;
	bit_shuffler shuffler(N, T);
	if (shuffler.count % 2 == 0)
	{
		out::write_line("NO");
		return;
	}
	int C = shuffler.count - 1;
	std::vector<int> left[18];
	left[0] = { 0 };
	for (int i : boost::irange(0, 17))
	{
		left[i + 1].reserve(2 << i);
		for (auto a : left[i])
		{
			left[i + 1].emplace_back(a << 1);
		}
		for (auto b : left[i] | adaptor::reversed)
		{
			left[i + 1].emplace_back((b << 1) + 1);
		}
	}
	std::vector<int> right = { 0 };
	for (int i : boost::irange(0, C / 2))
	{
		std::array<int, 4> x = { 0,2,3,1 };
		std::array<int, 4> y = { 1,0,2,3 };
		std::vector<int> next;
		next.reserve(4 * right.size());
		for (int k : boost::irange<int>(0, right.size() - 1))
		{
			if (k % 2 == 0)
			{
				for (auto v : x)
				{
					next.emplace_back((v << (2 * i)) + right[k]);
				}
			}
			else
			{
				for (auto v : x | adaptor::reversed)
				{
					next.emplace_back((v << (2 * i)) + right[k]);
				}
			}
		}
		for (auto v : y)
		{
			next.emplace_back((v << (2 * i)) + right.back());
		}
	}
	out::write_line("YES");
	for (int i : left[C])
	{
		std::cout << (shuffler.invert(i) ^ A) << " ";
	}
	for (int i : boost::irange<int>(1, left[N - C].size()))
	{
		int s = 0;
		if (i % 2 == 1)
		{
			for (auto v : right)
			{
				s = (left[N - C][i] << C) + v;
			}
		}
		else
		{
			for (auto v : right | adaptor::reversed)
			{
				s = (left[N - C][i] << C) + v;
			}
		}
		std::cout << (shuffler.invert(s) ^ A) << " ";
	}
}

