int main() {
  ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);

  int n; cin >> n;

  int a, b; cin >> a >> b;

  if( n == 1 ) {
    cout << "YES" << nl << a << ' ' << b << nl;
    return 0;
  }

  int x = a^b;
  if( __builtin_popcount(x) != 1 ) {
    cout << "NO" << nl;
    return 0;
  }

  int fb = __builtin_ctz(x);

  int p[1<<n];
  p[0] = 0, p[1] = 1;
  for(int b=2, j=1; j<n; j++, b<<=1) {
    for(int i=0; i<b; i++) {
      p[b+b-1-i] = p[i] | b;
    }
  }

  auto bit_swap = [&](int x, int i, int j) {
    int bi = (x>>i)&1, bj = (x>>j)&1;
    if( bi == 1 ) x |= (1<<j); else x &= (~(1<<j));
    if( bj == 1 ) x |= (1<<i); else x &= (~(1<<i));
    return x;
  };

  for(int i=0; i<(1<<n); i++) p[i] = bit_swap(p[i], n-1, fb);
  for(int i=0; i<(1<<n); i++) p[i] ^= a;

  assert(p[0] == a and p[(1<<n)-1] == b);
  for(int i=1; i<(1<<n); i++) assert(__builtin_popcount(p[i]^p[i-1])==1);

  cout << "YES" << nl;
  for(int i=0; i<(1<<n); i++) cout << p[i] << " \n"[i+1==(1<<n)];

}
