#include <bits/stdc++.h>
using namespace std;

constexpr size_t N = 17;
constexpr size_t M = 1<<N;
ulong graph[M][N];
bool used[M];

void prep(ulong n){
    for(size_t i=0; i<(1<<n); i++){
        for(size_t j=0; j<n; j++){
            graph[i][j] = i ^ (1<<j);
        }
    }
}

ulong hd(ulong a, ulong b){
    return __builtin_popcountl(a^b);
}

void dfs(const ulong n, vector<ulong>& stack, const ulong b){
    for(;;){
        ulong i, next;
push:
        if(stack.size()==((1<<n)-1) && hd(stack.back(), b)==1){
            std::cout << "YES\n";
            for(ulong i=0; i<(1<<n)-1; i++){
                std::cout << stack[i] << " ";
            }
            std::cout << b << std::endl;
            exit(0);
        }else{
            ulong now = stack.back();
            for(i=0; i<n; i++){
                next = graph[now][i];
                if(!used[next]){
                    used[next] = true;
                    stack.push_back(next);
                    goto push;
pop:
                    stack.pop_back();
                    used[next] = false;
                }
            }
            if(stack.size()==1){
                return;
            }else{
                goto pop;
            }
        }
    }
}

int main(void){
    ulong n, a, b;
    cin >> n >> a >> b;
    prep(n);
    vector<ulong> stack = {a};
    used[a] = true;
    used[b] = true;
    dfs(n, stack, b);
    std::cout << "NO" << std::endl;
    return 0;
}

