int popcnt(int n) {
    int ret = 0;
    for (int i = 1; i <= n; i <<= 1) {
        if (n & i) ++ret;
    }
    return ret;
}

int itog(int g) {
    return g ^ (g >> 1);
}

int gtoi(int n) {
    int ret = n;
    while (n) {
        n >>= 1;
        ret ^= n;
    }
    return ret;
}

