using namespace std;

int rdist(int a, int b) {
  int ret = 0;
  for (int i = 0; i < 20; i++) {
    if (a % 2 != b % 2) ret++;
    a /= 2;
    b /= 2;
  }
  return ret;
}

vector<bool> getbit(int a) {
  vector<bool> ret(20, false);
  for (int i = 0; i < 20; i++) {
    ret[i] = a % 2;
    a /= 2;
  }
  return ret;
}

int getnum(vector<bool> v) {
  int p = 1, ret = 0;
  for (int i = 0; i < 20; i++) {
    ret += p * v[i];
    p *= 2;
  }
  return ret;
}

int main() {
  int n, a, b;
  cin >> n >> a >> b;
  int n2 = 1;
  for (int i = 0; i < n; i++) n2 *= 2;
  int d = rdist(a, b);
  if (n2 - 1 < d)
    cout << "NO";
  else if (d % 2 == 0)
    cout << "NO";
  else {
    int a1 = a;
    if (a1 % 2 == 1)
      a1--;
    else
      a1++;
    cout << "YES" << endl;
    for (int i = 0; i < n2 - d; i++) {
      if (i % 2 == 0)
        cout << a << ' ';
      else
        cout << a1 << ' ';
    }
    vector<bool> av = getbit(a), bv = getbit(b);
    for (int i = 0; i < 20; i++) {
      if (av[i] != bv[i]) {
        d--;
        av[i] = bv[i];
        cout << getnum(av);
        if(d>0)cout << ' ';
      }
    }
  }
  return 0;
}

