	Edge *nxt;
}edges[MAXS*MAXN],*adj[MAXS],*ed_it=edges;

void AddEdge(int u,int v)
{
	ed_it->v=v;
	ed_it->nxt=adj[u];
	adj[u]=ed_it++;
}

int N,A,B,it;
int ans[MAXS];
bool vis[MAXS];

bool dfs(int u)
{
	ans[++it]=u;
	vis[u]=true;
	if(u==B)
	{
		if(it!=(1<<N))
		{
			it--;
			vis[u]=false;
			return false;
		}
		puts("YES");
		for(int i=1;i<=it;i++)
			printf("%d%c",ans[i]," \n"[i==it]);
		return true;
	}
	for(Edge *e=adj[u];e;e=e->nxt)
		if(!vis[e->v])
		{
			if(dfs(e->v))
				return true;
		}
	it--;
	vis[u]=false;
	return false;
}

