ll n,a,b,visit[200010]={};
vector<int> g[200010],ans;

int main(void){
	cin>>n>>a>>b;
	if(n%2==1){
		cout<<"NO"<<endl;
	}else{
		ll t=0;
		rep(i,n){
			if((a^b) & (1<<i)){
				t++;
			}
		}
		if(t!=1){
			cout<<"NO"<<endl;
		}else{
			cout<<"YES"<<endl;
			rep(i,1<<n){
				rep(j,n){
					if(a==i && (i^(1<<j))==b)continue;
					if(b==i && (i^(1<<j))==a)continue;
					g[i].push_back(i^(1<<j));
				}
			}
			ll p=a;
			visit[a]=1;
			ans.push_back(a);
			rep(i,(1<<n)-2){
				bool ok=false;
				for(ll q:g[p]){
					if(visit[q]==0 && q!=b){
						visit[q]=1;
						p=q;
						ans.push_back(q);
						ok=true;
						break;
					}
				}
