int pw(int n,int k){
  int res=1;
  while(k){
    if(k&1)res*=n;
    n*=n;k>>=1;
  }
  return res;
}
int bitcount(int a){
  int res=0;
  while(a){
    res+=a&1;
    a>>=1;
  }
  return res;
}
int N,A,B,C,D,now;
std::vector<vector<int>> v(20);
void changeout(int s){
  s^=D;s^=C;s^=A;
  cout<<s<<" ";
}
void turn(int a){
  now+=pw(2,N-a-1);
}
void guru(int i,bool f){
  int a=N-2-i;
  if(f)reverse(v[a].begin(),v[a].end());
  for(int p:v[a])changeout(now+p);
}
