#define pc __builtin_popcount
using namespace std;
const int N = 20;

int n;
int A, B;

int cnt[N];
vector <int> v[N];

vector <int> seq, ans;

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL); cout.tie(NULL);

    cin >> n >> A >> B;
    for(int i = 0; i < (1 << n); i++)
    {
        if(i != A && i != B)
            v[pc(i)].pb(i);
        cnt[pc(i)]++;
    }

    if(pc(A) % 2 == pc(B) % 2)
    {
        cout << "NO" << endl;
        return 0;
    }

    int last = -1;
    for(int i = 0; i < (1 << n); i++)
        for(int j = 0; j <= n; j++)
            if(cnt[j] && j != last)
            {
                cnt[j]--;
                last = j;
                seq.pb(j);
                break;
            }


    bool swapped = false;
    if(pc(A) & 1)
    {
        swapped = true;
        swap(A, B);
    }

    int seek;
    if(n & 1)
        seek = n - 2;
    else
        seek = n - 3;
    for(int i = (1 << n) - 2; i > 0 && seek >= pc(B); i--)
        if(seq[i] == seek && abs(seq[i - 1] - seq.back()) == 1)
        {
            reverse(seq.begin() + i, seq.end());
            seek -= 2;
        }

    seek = 2;
    for(int i = 1; i < ((1 << n) - 1) && seek <= pc(A); i++)
        if(seq[i] == seek && abs(seq[i + 1] - seq[0]) == 1)
        {
            reverse(seq.begin(), seq.begin() + i + 1);
            seek += 2;

        }
    if(swapped)
    {
        swap(A, B);
        reverse(seq.begin(), seq.end());
    }

    ans.resize((1 << n));
    ans[0] = A;
    ans[(1 << n) - 1] = B;
    for(int i = 1; i < (1 << n) - 1; i++)
    {
        ans[i] = v[seq[i]].back();
        v[seq[i]].pop_back();
    }

    for(int i = 1; i < (1 << n); i++)
        assert(abs(pc(ans[i]) - pc(ans[i - 1])) == 1);

    cout << "YES" << endl;
    for(int i = 0; i < (1 << n); i++)
        cout << ans[i] << " ";
    cout << endl;



    return 0;
}


