    for(int i=0;i<n;i++){
        if((1<<i) == t) {
            ok=1; pivot=i; break;
        }
    }
    if(!ok) return !printf("NO\n");
    char **p = GrayCode(n);
    printf("YES\n");
    for(int i=0;i<(1<<n);i++){
        int tmp=0;
        for(int j=0;j<n;j++){
            tmp=tmp*2+p[i][j]-'0';
        } 
        tmp^=a;
        int b1=(tmp>>pivot)&1;
        int b2=(tmp>>(n-1))&1;
