void solve(int n, int l, int r, int a, int b) {
    if(n == 1) {
        p[l] = a;
        p[r] = b;
        return;
    }
    int mid = (l + r) >> 1, nexlm = (1 << (n - 1)) - 1;
    if(((a >> (n - 1)) & 1) == ((b >> (n - 1)) & 1)) {
        solve(n - 1, mid + 1, r, a & nexlm, b & nexlm);
        if((a >> (n - 1)) & 1) {
            for(int i = mid + 1; i <= r; i++) {
                p[i] |= 1 << (n - 1);
            }
            p[l] = p[mid + 1];
            solve(n - 1, l + 1, mid + 1, a & nexlm, p[mid + 2] & nexlm);
        }
        else {
            p[l] = p[mid + 1];
            solve(n - 1, l + 1, mid + 1, a & nexlm, p[mid + 2] & nexlm);
            for(int i = l + 1; i <= mid + 1; i++) {
                p[i] |= (1 << (n - 1));
            }
        }
    }
    else {
        solve(n - 1, l, mid, a & nexlm, (b & nexlm) ^ 1);
        if((a >> (n - 1)) & 1) {
            for(int i = l; i <= mid; i++) {
                p[i] |= 1 << (n - 1);
            }
            solve(n - 1, mid + 1, r, p[mid] & nexlm, b & nexlm);
        }
        else {
            solve(n - 1, mid + 1, r, p[mid] & nexlm, b & nexlm);
            for(int i = mid + 1; i <= r; i++) {
                p[i] |= 1 << (n - 1);
            }
        }
    }
    return;
}

