vi rec(int a, int b, vi& g) {
  if (a == b) return vi{a};

  vi ret;
  for (int i = 0; i < n; i++) {
    if ((a ^ b) & (1<<i)) {
      vi g1, g2;
      int x = a, y = b;
      for (int c : g) {
