          g1.push_back(c);
          if (popcnt(a)%2 != popcnt(c)%2 && a != c && b != (c ^ (1<<i))) {
            x = c;
            y = c ^ (1<<i);
          }
        } else {
          g2.push_back(c);
          if (popcnt(b)%2 != popcnt(c)%2 && b != c && a != (c ^ (1<<i))) {
            y = c;
            x = c ^ (1<<i);
          }
        }
      }
      ret = rec(a,x,g1);
      vi r2 = rec(y,b,g2);
      ret.insert(ret.end(),r2.begin(),r2.end());
    }
  }
  return ret;
}

