#include <bits/stdc++.h>
using namespace std;

vector<int> solve(int n, int a, int b) {
    if (n == 1)
        return {a, b};

    int m = (1 << (n - 1));
    if (a < m && b < m) {
        vector<int> v = solve(n - 1, a, b);
        vector<int> res;
        for (int i = 0; i < m; i += 2) {
            res.push_back(v[i]);
            res.push_back(v[i] ^ m);
            res.push_back(v[i + 1] ^ m);
            res.push_back(v[i + 1]);
        }
        return res;
    } else if (a >= m && b >= m) {
        vector<int> v = solve(n - 1, a ^ m, b ^ m);
        vector<int> res;
        for (int i = 0; i < m; i += 2) {
            res.push_back(v[i] ^ m);
            res.push_back(v[i]);
            res.push_back(v[i + 1]);
            res.push_back(v[i + 1] ^ m);
        }
        return res;
    } else if (a < m && b >= m) {
        for (int i = 0; i < m; ++i) {
            if (__builtin_popcount(a ^ i) & 1) {
                int j = i ^ m;
                if (__builtin_popcount(b ^ j) & 1) {
                    vector<int> x = solve(n - 1, a, i);
                    vector<int> y = solve(n - 1, j ^ m, b ^ m);
                    vector<int> res;
                    for (int k = 0; k < (int)x.size(); ++k)
                        res.push_back(x[k]);
                    for (int k = 0; k < (int)x.size(); ++k)
                        res.push_back(y[k] ^ m);
                    return res;
                }
            }
        }
        assert(false);
    } else {
        for (int i = m; i < (1 << n); ++i) {
            if (__builtin_popcount(a ^ i) & 1) {
                int j = i ^ m;
                if (__builtin_popcount(b ^ j) & 1) {
                    vector<int> x = solve(n - 1, a ^ m, i ^ m);
                    vector<int> y = solve(n - 1, j, b);
                    vector<int> res;
                    for (int k = 0; k < (int)x.size(); ++k)
                        res.push_back(x[k] ^ m);
                    for (int k = 0; k < (int)x.size(); ++k)
                        res.push_back(y[k]);
                    return res;
                }
            }
        }
        assert(false);
    }
}

int main() {
    int n, a, b; scanf("%d%d%d", &n, &a, &b);
    int m = (1 << n);

    if (__builtin_popcount(a ^ b) % 2 == 0) {
        puts("NO");
        return 0;
    }

    puts("YES");
    vector<int> ans = solve(n, a, b);
    assert(ans[0] == a && ans[m - 1] == b);
    for (int i = 0; i + 1 < m; ++i) 
        assert(__builtin_popcount(ans[i] ^ ans[i + 1]) == 1);

    for (int i = 0; i < m; ++i) printf("%d ", ans[i]);
    puts("");
    return 0;
}

