std::vector<int> digitcount(int a){ // Count the number of '1's
	std::vector<int> result;
	for(int i=0; i<32; i++) if((a&(1<<i)) != 0) result.push_back(i);
	return result;
}
int changebit(int x, int digit){ // Change x at bit digit
	return x ^ (1<<digit);
}

void append(std::vector<int> &origin, const std::vector<int> &add){
	for(auto it: add) origin.push_back(it);
}

