void solve(int s,int t,int a,int b,int l,int r){
    //cout<<s<<' '<<a<<' '<<b<<' '<<l<<' '<<r<<endl;
    if (l+2==r){
        ans[l]=a;
        ans[l+1]=b;
        return;
    }
    int p=-1;
    for (int i=0;i<n;i++)
        if (s&(1<<i)){
            if ((a&(1<<i))^(b&(1<<i))) {p=i;break;}
        }
    assert(p!=-1);
    s^=1<<p;
    //cout<<s<<endl;
    int mid=(l+r)>>1;
    for (int i=s;;i=(i-1)&s){
        if ((a&(1<<p))&&d[i|t|(1<<p)]!=d[a]){
            i|=t;
            solve(s,t|(1<<p),a,i|(1<<p),l,mid);
            solve(s,t,i,b,mid,r);
            return;
        }
        if ((b&(1<<p))&&d[i|t|(1<<p)]!=d[b]){
            i|=t;
            solve(s,t,a,i,l,mid);
            solve(s,t|(1<<p),i|(1<<p),b,mid,r);
            return;
        }
        if (!i) assert(0);
    }
}
