vector <int> solve(int n, int x, int y)
{
  if ((x >> (n + 1)) & 1) x -= (1 << (n + 1));
  if ((y >> (n + 1)) & 1) y -= (1 << (n + 1));
  if (n == 0)
  {
    return {x, y};
  }
  if (((x >> n) & 1) != ((y >> n) & 1))
  {
    for (int i = 0; i < (1 << (n + 1)); i++)
    {
      if (((i >> n) & 1) != ((x >> n) & 1)) continue;
      if (can(x, i) && can(i ^ (1 << n), y))
      {
        auto l = solve(n - 1, x, i);
        auto r = solve(n - 1, i ^ (1 << n), y);
        vector <int> ret;
        for (int a : l) ret.push_back(a + (x & (1 << n)));
        for (int a : r) ret.push_back(a + (y & (1 << n)));
        for (int i = 1; i < (int) ret.size(); i++)
        {
          assert(__builtin_popcount(ret[i] ^ ret[i - 1]) == 1);
        }
        return ret;
      }
    }
    assert(0);
  }
  else
  {
    auto b = solve(n - 1, x, y);
    auto ret = solve(n - 1, x, b[1]);
    vector <int> ans;
    ans.push_back(x);
    ans.push_back(x ^ (1 << n));
    ret.erase(ret.begin());
    for (int t : ret)
    {
      int sw = ((1 << n) & (x ^ (1 << n)));
      ans.push_back(t + sw);
    }
    b.erase(b.begin());
    for (int t : b)
    {
      int sw = ((1 << n) & x);
      ans.push_back(t + sw);
    }
    return ans;
  }
