int n;

vector<int> solve(int mask, int end) {
    assert((end & (~mask)) == 0);

    if (__builtin_popcount(mask) == 1) {
        return vector<int> {0, end};
    } else {
        int bt = 0;
        while ((end & (1 << bt)) == 0)
            ++bt;

        end ^= (1 << bt);
        mask ^= (1 << bt);

        for (int elem = mask; elem != 0; elem = (elem - 1) & mask) {
            if (__builtin_popcount(elem) % 2 == 0)
                continue;
            if (__builtin_popcount(end ^ elem) % 2 == 0)
                continue;

            if (elem != end) {
                vector<int> ch1 = solve(mask, elem);
                vector<int> ch2 = solve(mask, end ^ elem);

                vector<int> res;
                for (int el: ch1)
                    res.push_back(el);

                std::reverse(ALL(ch2));
                for (int el: ch2)
                    res.push_back(el ^ end ^ (1 << bt));

                return res;
            }
        }

        assert(false);
    }
}

void verify(int n, int a, int b, vector<int> ans) {
    return;

    assert(SZ(ans) == (1 << n));
    assert(ans[0] == a);
    assert(ans.back() == b);

    for (int i = 1; i != SZ(ans); ++i)
        assert((__builtin_popcount(ans[i - 1] xor ans[i])) == 1);

    vector<char> used(1 << n, 0);
    for (int el: ans) {
        assert(0 <= el and el < (1 << n));

        assert(not used[el]);
        used[el] = 1;
    }
}

