    if((__builtin_popcount(a^b)&1)==0){
        cout<<"NO"<<endl;
        return 0;
    }
    vector<int> v;
    int bit=0;
    solve(a,b,bit,v);
    cout<<"YES"<<endl;
    for(int i=0;i<(1<<n);i++){
        cout<<v[i]<<((i+1==(1<<n)) ? "\n" : " ");
    }
    return 0;
}

