int N;
int P[1<<17];
void rec(int mask, int L, int R, int A, int B) {
    //eprintf("%d %d %d %d\n", L, R, A, B);
    if (R-L == 2) {
	P[L] = A;
	P[L+1] = B;
	return;
    }

    int pivot = -1;
    REP (t, N) if (mask>>t&1) {
	if ((A>>t&1) != (B>>t&1)) {
	    pivot = t;
	    break;
	}
    }

    int cnt = 0;
    REP (t, N) if (mask>>t&1 && t != pivot) {
	cnt += A>>t&1;
    }

    int lmid = A, rmid = B;
    REP (t, N) if (mask>>t&1 && t != pivot) {
	lmid &= ~(1<<t);
	rmid &= ~(1<<t);
    }
    if (A>>pivot&1) {
	lmid |= 1<<pivot;
    } else {
	rmid |= 1<<pivot;
    }

    if (cnt % 2 == 0) {
	REP (t, N) if (mask>>t&1 && t != pivot) {
	    lmid |= 1<<t;
	    rmid |= 1<<t;
	    break;
	}
    }

    int nmask = mask & ~(1<<pivot);
    rec(nmask, L, (L+R)/2, A, lmid);
    rec(nmask, (L+R)/2, R, rmid, B);
}

