void bfs (int s) {
    queue <int> q; q.push(s);
    while (!q.empty()) {
        int mask = q.front(); q.pop();
        for (int i = 0; i < n; i++) {
            if (f[mask ^ (1 << i)] > f[mask] + 1) {
                if ((mask ^ (1 << i)) == b && f[mask] != (1 << n) - 1) continue;
                f[mask ^ (1 << i)] = f[mask] + 1;
                trace[mask ^ (1 << i)] = mask;
                q.push(mask ^ (1 << i));
            }
        }
    }
}

