vector<int> dfs(int start,int goal,int len){
    if(len==1) return (vector<int>) {start,goal};
    if(len==0) return (vector<int>) {start};
    int x = 0;
    for(int i=0;i<len;i++){
        if((start xor goal)&(1<<i)){
            x = i;
            break;
        }
    }
    int a = 0,b = 0;
    for(int i=0;i<len;i++){
        if(i<x){
            if(start&(1<<i)) a += (1<<i);
            if(goal&(1<<i)) b += (1<<i);
        }
        if(i>x){
            if(start&(1<<i)) a += (1<<(i-1));
            if(goal&(1<<i)) b += (1<<(i-1));
        }
    }
    int c = a^(1<<0);
    vector<int> q = dfs(a,c,len-1),r = dfs(c,b,len-1),res;
    for(auto n:q){
        int now = (A&(1<<x)? (1<<x):0);
        for(int i=0;i<len-1;i++){
            if(i<x && n&(1<<i)) now += (1<<i);
            if(i>=x &&n&(1<<i)) now += (1<<(i+1));
        }
        res.push_back(now);
    }
    for(auto n:r){
        int now = (B&(1<<x)? (1<<x):0);
        for(int i=0;i<len-1;i++){
            if(i<x && n&(1<<i)) now += (1<<i);
            if(i>=x &&n&(1<<i)) now += (1<<(i+1));
        }
        res.push_back(now);
    }
    return res;
}

