#include <iostream>
#include <vector>

int getDiff(int A, int B) {
    int X = A ^ B;
    int ret = 0;
    while( X % 2 == 0 ) {
        X >>= 1;
        ++ret;
    }
    if( X == 1 ) { return ret; }
    return -1;
}

// 0110;
// 00111100;
// 0000111111110000;
// というような感じでビットパターンを操作する;
// 隣接 2 ビットを見て、自分のところか隣が立っていれば反転させる;
int add(int value, int diff, int N, int add) {
    for( int i = 0; i < N; ++i ) {
        int self = (add >> i) & 1;
        int next = (add >> (i + 1)) & 1;
        if( self ^ next ) { value ^= (1 << ((diff + 1 + i) % N)); }
    }
    return value;
}

int main() {

    int N, A, B;
    std::cin >> N >> A >> B;

    int diff = getDiff(A, B);

    if( diff == -1 ) {
        std::cout << "NO" << std::endl;
        return 0;
    }

    std::vector<int> array;
    array.push_back(B);
    array.push_back(A);
    for( int i = 1; i < (1 << N); ++i ) {
        array.push_back(add(A, diff, N, i));
    }

    if( array[(1 << N)] != B ) {
        std::cout << "failed..." << std::endl;
    }

    std::cout << "YES" << std::endl;
