        i64 k=1<<i;
        if((A&k)!=(B&k)){
            diff.emplace_back(i);
        }
    }

    if(diff.size()%2!=1){
        cout << "NO" << endl;
        return;
    }

    vector<i64> ans(1<<N),eo(N),use(N),org;
    for(auto d:diff){
        eo[d]=1;
    }

    org=eo;

    static bool visit[1<<maxn];
    fill_n((bool*)visit,1<<maxn,false);

    vector<i64> js(N);
    rep(i,0,N){
        js[i]=i;
    }

    i64 cnt=0;
    vector<i64> deg(1<<N,N);

    function<bool(i64,i64)> dfs=[&](i64 i,i64 pos){
        ans[i]=pos;
        visit[pos]=true;

        if(i==((1<<N)-1)){
            assert(pos==B);
            return true;
        }

        rep(j,0,N) {
            i64 np = pos ^(1 << j);
            if (visit[np]) continue;
            --deg[np];
        }

        i64 deg1=-1;
        bool ok=true;
        rep(j,0,N){
            i64 np = pos ^(1 << j);
            if (visit[np]) continue;

            if(deg[np]==0){
                if(i+1==((1<<N)-1) and np==B) continue;
                print(np);
                ok=false;
                break;
            } else if(deg[np]==1){
                if(np==B and i+1!=((1<<N)-1)){
                    continue;
                }
                if(deg1==-1){
                    deg1=np;
                    continue;
                }
                ok=false;
                break;
            }
        }

        if(!ok){
            rep(j,0,N) {
                i64 np = pos ^(1 << j);
                if (visit[np]) continue;
                ++deg[np];
            }
            visit[pos]=false;
            return false;
        }

        if(deg1!=-1){
            auto res=dfs(i+1,deg1);
            rep(j,0,N) {
                i64 np = pos ^(1 << j);
                if (visit[np]) continue;
                ++deg[np];
            }
            visit[pos]=false;
            return res;
        }

        ++cnt;
        if(cnt%100==0){
            random_shuffle(begin(js),end(js));
        }

        for(auto j:js){
            i64 np=pos^(1<<j);
            if(visit[np]) continue;
            if(np==B and (i+1!=((1<<N)-1))) continue;

            if(dfs(i+1,pos^(1<<j))) return true;
        }

        rep(j,0,N) {
            i64 np = pos ^(1 << j);
            if (visit[np]) continue;
            ++deg[np];
        }

        visit[pos]=false;
        return false;
    };

    if(!dfs(0,A)){
        cout << "NO" << endl;
        return;
    }

    cout << "YES" << endl;
    rep(i,0,1<<N){
        cout << ans[i];
        if(i==((1<<N)-1)) cout << endl;
        else cout << " ";
    }
}

