        for(int i=0;i<(1<<N);++i){
            v[i] = i ^ (i >> 1);

            int z = ((v[i] >> (N - 1)) ^ (v[i] >> y)) & 1;
            v[i] = v[i] ^ ((z << (N - 1)) | (z << y));
            v[i] = v[i] ^ A;
