            v[(1 << N) - 1 - i] = b ^ (b >> 1);
            b -= 1;
        }

        if(A > 0){
            for(int i=0;i<(1<<N);++i){
                v[i] = v[i] ^ ((1 << N) - 1);
            }
        }
    }

