int ans[200000][17];

int DFS(int L_index, int R_index){
  if (R_index == L_index + 1) return 0;

  int mid = (L_index + R_index) / 2;
  int next;
  for (int i = 0; i < N; i++){
    if (ans[L_index + 1][i] == -1 && ans[L_index][i] != ans[R_index][i]){
      next = i; break;
    }
  }

  for (int i = L_index + 1; i <= mid; i++){
    ans[i][next] = ans[L_index][next];
  }
  for (int i = mid + 1; i < R_index; i++){
    ans[i][next] = ans[R_index][next];
  }


  bool flag = false;
  for (int i = 0; i < N; i++){
    if (ans[mid][i] == -1) {
      if (flag == true) ans[mid][i] = ans[L_index][i];
      else{
        ans[mid][i] = 1 - ans[L_index][i];
        flag = true;
      }
    }
  }


  for (int i = 0; i < N; i++){
    if (ans[mid + 1][i] == -1){
      ans[mid + 1][i] = ans[mid][i];
    }
  }

  DFS(L_index, mid);
  DFS(mid + 1, R_index);
  return 0;
}

