  fill((int*)ans, (int*)(ans + all), -1);
  for (int i = 0; i < N; i++){
    ans[0][i] = A % 2; A /= 2;
  }
  for (int i = 0; i < N; i++){
    ans[all - 1][i] = B % 2; B /= 2;
  }
  DFS(0, all - 1);

  for (int i = 0; i < all; i++){
    int now = 0, cnt = 1;
    for (int j = 0; j < N; j++){
      now += ans[i][j] * cnt;
      cnt *= 2;
    }
    cout << now;
    if (i == all - 1) cout << endl;
    else cout << " ";
  }

  return 0;
}

