const int maxN = 20;

void GrayCodes(int n, int* T)
{
	int s = 1 << n, q = 1, oldestBit = -1, mask = 0;
	FOR(i, 1, s+1)
	{
		if (i == q)	q *= 2, T[i - 1] = ++oldestBit;
		else 		T[i - 1] = T[i - q/2 - 1];
		mask ^= 1 << T[i - 1];
	}
}

int bit[1 << maxN], M[maxN];

