#include <bits/stdc++.h>
using namespace std;

int popcount(unsigned int bit, int n){
    int count = 0;
    for(int i = 0; i < n; i++)
    {
        if(bit & (1<<i))count++;
    }
    return count;
}

vector<unsigned int> perm(unsigned int a, unsigned int b, unsigned int n){
    if(n <= 1){
        vector<unsigned int> d(2);
        d.at(0) = a; d.at(1) = b;
        return d;
    }
    else {
    int x = 0;
    while(!((a ^ b) & (1<<x)))x++;

    unsigned int s = ((a>>(x+1))<<x) | ((x>0)? ((a<<(32-x))>>(32-x)):0);
    unsigned int t = ((b>>(x+1))<<x) | ((x>0)? ((b<<(32-x))>>(32-x)):0);

    unsigned int c = s ^ 1;

    vector<unsigned int> q(1<<(n-1));
    q = perm(s, c, n-1);
    vector<unsigned int> r(1<<(n-1));
    r = perm(c, t, n-1);
    vector<unsigned int> ans(1<<n);

    for(int i = 0; i < (1<<n); i++)
    {
        if(i < (1<<(n-1))){
            ans.at(i) = ((q.at(i)>>x)<<(x+1)) | ((x>0)? ((q.at(i)<<(32-x))>>(32-x)):0) | (a & (1<<x));
        }
        else{
            ans.at(i) = ((r.at(i-(1<<(n-1)))>>x)<<(x+1)) | ((x>0)?((r.at(i-(1<<(n-1)))<<(32-x))>>(32-x)):0) | (b & (1<<x));
        }
    }
    return ans;
    }
}

int main() {
    unsigned int N, A, B;
