#include <bits/stdc++.h>
using namespace std;

const int B = 18;
int mark[B];
int numbers[1 << B];
int n, a, b;

void solve(int st, int en, int set_bit, int side){
    if(st >= en){
        return;
    }

    for(int i = st ; i <= en ; i++){
        numbers[i] |= set_bit;
    }    

    int find = -1;

    if(side){
        for(int j = 0 ; j < n ; j++){
            if(!mark[j]){
                find = j;
                numbers[st] = numbers[en] ^ (1 << j);
            }
        }
    }else{
        for(int j = 0 ; j < n ; j++){
            if(!mark[j]){
                find = j;
                numbers[en] = numbers[st] ^ (1 << j);
            }
        }
    }

    assert(find != -1);

    mark[find] = true;

    int mid = (st + en) >> 1;

    solve(st, mid, numbers[st] & (1 << find), 0);
    solve(mid + 1, en, numbers[en] & (1 << find), 1);

    mark[find] = false;
}

int main() {
    cin >> n >> a >> b;

    numbers[0] = a;
    numbers[(1 << n) - 1] = b;

    if(__builtin_popcount(a ^ b) & 1){
        for(int i = 0 ; i < n ; i++){
            if((a & (1 << i)) != (b & (1 << i))){
                mark[i] = true;
                solve(0, (1 << (n - 1)) - 1, (a & (1 << i)), 0);
                solve((1 << (n - 1)), (1 << n) - 1, (b & (1 << i)), 1);
                break;
            }
        }

        cout << "YES" << endl;

        for(int i = 0 ; i < (1 << n) ; i++){
            cout << numbers[i] << ' ';
        }

        cout << endl;
    }else{
        cout << "NO" << endl;
    }


	return 0;
}

