#define all(x) x.begin(),x.end()

i64 n;
i64 a,b;

vector<i64> solve(i64 EE) {
  vector<i64> ans;

  vector<i64> ba;

  vector<i64> OK((1 << n), true);

  ba.push_back(EE);
  {
    i64 now = EE;
    OK[now] = false;
    for(int i = 0;i < n;i++) {
      if(!(now & (1 << i))) {
        now |= (1 << i);
        ba.push_back(now);
        OK[now] = false;
      }
    }
  }

  OK[(1 << n) - 1] = true;
  ba.pop_back();

  vector<i64> cnt(n + 1, 0);
  for(int i = 0;i < (1 << n);i++) {
    cnt[__builtin_popcount(i)] += !!(OK[i]);
  }

  {
    i64 now = 0;
    i64 i = 0;
    ans.push_back(now);
    while(i < n) {
      while(1) {
        i64 next = -1;
        for(int j = 0;j < n;j++) {
          if(!(now & (1 << j)) && OK[now | (1 << j)]) {
            next = now | (1 << j);
            break;
          }
        }
        if(next == -1) return vector<i64>();
        cnt[i]--;
        OK[now] = false;

        now = next;

        ans.push_back(now);


        if(cnt[i] == 0) break;

        cnt[i + 1]--;
        OK[next] = false;

        for(int j = 0;j < n;j++) {
          if(now & (1 << j) && OK[now & ~(1 << j)]) {
            next = now & ~(1 << j);
            break;
          }
        }
        now = next;

        ans.push_back(now);
      }
      i++;
    }
  }

  reverse(all(ba));

  for(auto x: ba) {
    ans.push_back(x);
  }

  return ans;
}


