int p[320000], q[320000], ans[320000];
int k[30], l[30];

void dnc(int len) {
    if(len == 1) {
        p[0] = 0;
        p[1] = 1;
        return;
    }

    dnc(len - 2);

    int d[4] = {1 << (len - 2), 0, 0, 1 << (len - 2)};

    for(int i = 0; i < (1 << (len - 1)); i++) q[i] = 0;
    for(int i = 1 << (len - 1); i < (1 << len); i++) {
        q[i] += 1 << (len - 1);
        q[i] += p[(i - (1 << (len - 1))) / 2];
        q[i] += d[i % 4];
    }

    for(int i = 0; i < len - 1; i++) for(int j = 0; j < (1 << i); j++) q[(1 << (i + 1)) - j - 1] = q[j] + (1 << i);
    for(int i = 0; i < (1 << len); i++) p[i] = q[i];
}

