using namespace std;

#define N 131075
int bitCount(int bit) {
	int ret = 0;
	while (bit > 0) {
		++ret;
		bit = bit & (bit - 1);
	}
	return ret;
}

int ret[N];

void construct(int l, int r, int a, int b, int n, int bit, int myxor) {
	if (l + 1 == r) {
		ret[l] = a | myxor;
		ret[r] = b | myxor;
		return;
	}
	int mid = (l + r) / 2;
	int ind = -1;

	int axor = myxor, bxor = myxor;
	for (int i = 0; i < n; ++i) {
		if (bit&(1 << i)) {
			continue;
		}
		if ((a&(1 << i)) != (b&(1 << i))) {
			ind = i;
			if (a&(1 << i)) {
				axor |= (1 << i);
			}
			if (b&(1 << i)) {
				bxor |= (1 << i);
			}
			break;
		}
	}
	bit |= (1 << ind);
	int c = 0, f = -1, fInd = -1;
	for (int i = 0; i < n; ++i) {
		if (bit&(1 << i)) {
			continue;
		}
		c |= (1 << i);
		if (fInd == -1) {
			f = 0;
			fInd = i;
		}
	}
	c = (c & a);
	c = c ^ (1 << fInd);
	int tc = c;

	if (a&(1 << ind)) {
		tc |= (1 << ind);
		axor = myxor | (1 << ind);
	}
	construct(l, mid, a, tc, n, bit, axor);
	tc = c;
	if (b&(1 << ind)) {
		tc |= (1 << ind);
		bxor = myxor | (1 << ind);
	}
	construct(mid + 1, r, tc, b, n, bit, bxor);
}
void solve() {
	int n;
	scanf("%d", &n);
	int a, b; scanf("%d %d", &a, &b);
	b = a ^ b;
	int bc = bitCount(b);
	if (bc & 1) {
		printf("YES\n");
		b = a ^ b;
		int sz = (1 << n);
		construct(0, sz - 1, a, b, n, 0, 0);
		for (int i = 0; i < sz; ++i) {
			printf("%d ", ret[i]);
		}
	}
	else {
		printf("NO\n");
	}
}
