vector<int> grayCode(int lv) {
    if (lv == 1) return {0, 1};
    vector<int> ans = grayCode(lv - 1);
    for(int i = 1; i <= (1 << (lv -1)); i++) 
        ans.push_back(ans[(1 << (lv - 1)) - i] ^ (1 << (lv - 1)));
    return ans;
}
void swapBit(int u, int v, vector<int> &res) {
    int mask = (1 << u) ^ (1 << v);
    for(auto &i : res) {
        int s1 = (i >> u) & 1;
        int s2 = (i >> v) & 1;
        if (s1 != s2) i ^= mask;
    }
}
vector<int> build(int depth, int st, int en) {
    //cout << "Call " << depth << " " << st << " " << en << '\n';
    int nen = en ^ st;

    vector<int> diff;
    for(int i = 0; i < depth; i++) if ((nen >> i) & 1) 
        diff.push_back(i);
    int ndiff = diff.size();

    if (ndiff == 1) {
        vector<int> res = grayCode(depth);
        swapBit(diff[0], depth - 1, res);
        for(auto &i : res) i ^= st;
        return res;
    }
    int half = 0;
    for(int i = 0; i < ndiff / 2; i++) 
        half |= 1 << diff[i];

    //cout << depth << '\n';
    //cout << half << " " << ((1 << diff.back()) ^ nen) << '\n';
    vector<int> resL = build(depth - 1, 0, half); 
    vector<int> resR = build(depth - 1, half, (1 << diff.back()) ^ nen);
    for(auto &i : resR) i ^= 1 << (depth - 1);
    swapBit(diff.back(), depth - 1, resR);
    vector<int> res;
    for(auto i : resL) res.push_back(i ^ st); 
    for(auto i : resR) res.push_back(i ^ st); 
    return res;
}
