    cin >> n >> st >> en;
    if (__builtin_popcount(st ^ en) % 2 == 0) {
        cout << "NO";
        exit(0);
    }
    cout << "YES\n";
    auto res = build(n, st, en);
    for(auto i : res) cout << i << " ";
}

