	{
		int lbit=C&(-C);
		A^=lbit;
		write(A),putchar(32);
		C-=lbit;
	}
	for(int i=(1<<N)-1;i>cnt;--i)
	{
		B^=1;
		write(B),putchar(32);
	}
	return 0;
}

