int n, a, b;
int mask(int l, int r) {
  return (1 << r) - (1 << l);
}

int del(int val, int k) {
  return (val & mask(0, k)) | ((val & mask(k + 1, n)) >> 1);
}

int ins(int val, int k, int bit) {
  return (val & mask(0, k)) | ((val & mask(k, n)) << 1) | (bit << k);
}

vector<int> rec(int s, int t, int cnt) {
  assert(s != t);
  if (cnt == 1) return {s, t};
  int k = 0;
  while (!(((s ^ t) >> k) & 1)) ++k;
  int ns = del(s, k); 
  int nt = del(t, k);
  int nu = 0;
  while (bitset<64>(nu ^ ns).count() % 2 == 0) ++nu;
  vector<int> vs = rec(ns, nu, cnt - 1);
  vector<int> vt = rec(nu, nt, cnt - 1);
  vector<int> ret;
  for (int p : vs) ret.push_back(ins(p, k, (s >> k) & 1));
  for (int q : vt) ret.push_back(ins(q, k, (t >> k) & 1));
  return ret;
}

