ll encode(ll n){
  return n^(n>>1);
}
unsigned long long int decode(ll n){
  unsigned long long int b=pow(2,17);
  unsigned long long int m=b&n;
  while(b!=0){
    unsigned long long int c=(b&m)>>1;
    b>>=1;
    m|=c^(n&b);
  }
  return m;
}

