int main(){
  ll N,A,B;
  cin>>N>>A>>B;

  ll L[1<<N];
  for(ll i=0; i<pow(2,N-1); i++){
    ll E=encode(i);
    L[i]=E;
  }

  bool CAN=false;
  ll C=B^A,cnt=0;
  while(C>0){
    if(C%2==1){
      C--;
      cnt++;
    }
    C/=2;
  }
  if(cnt%2==0) CAN=true;

  if(CAN){
    CONO;
    return 0;
  }


  ll ANS[1<<N],t=1;
  ANS[0]=0;

  for(ll i=1; i<pow(2,N); ++i){
    if(i%4==1) ANS[i]=ANS[i-1]+pow(2,N-1);
    else if(i%4==3) ANS[i]=ANS[i-1]-pow(2,N-1);
    else  ANS[i]=ANS[i-1]+L[i/2]-L[i/2-1];

    if(ANS[i]==C){
      t=i;
      break;
    }
  }

  if(t%4==1){
    for(ll i=t; i<(pow(2,N)+t)/2; ++i) ANS[i]=L[i-t/2];
    for(ll i=(pow(2,N)+t)/2; i<pow(2,N); ++i) ANS[i]=pow(2,N-1)+L[(1<<(N-1))-1-(i-((1<<N)+t)/2)];
  }
  else{
    for(ll i=t; i<(pow(2,N)+t)/2; ++i) ANS[i]=pow(2,N-1)+L[i-t/2];
    for(ll i=(pow(2,N)+t)/2; i<pow(2,N); ++i) ANS[i]=L[(1<<(N-1))-1-(i-((1<<N)+t)/2)];
  }

  for(ll i=0; i<pow(2,N); ++i){
    cout<<(ANS[i]^A);
    cout<<" ";
  }
  cout<<endl;
  return 0;
}

