vector<int> solve(int diff, int useless) {
    int bit = (1 << __builtin_ctz(diff));
    vector<int> aa, bb;
    if (diff == bit) {
        vector<int> uu;
        int cur = useless;
        while (cur) {
            int o = (1 << __builtin_ctz(cur));
            cur ^= o;
            uu.push_back(o);
        }
        for (int i = 1; i < (1 << (uu.size() + 1)); ++i) {
            int q = __builtin_ctz(i);
            if (q == uu.size()) {
                aa.push_back(bit);
            } else {
                aa.push_back(uu[q]);
            }
        }
        return aa;
    } else {
        int z = (1 << __builtin_ctz(diff ^ bit));
        int d2 = diff ^ bit ^ z;
        aa = solve(diff ^ bit ^ z, useless ^ z);
        bb = solve(z, useless ^ diff ^ bit ^ z);
        aa.push_back(bit);
        for (auto u: bb) {
            aa.push_back(u);
        }
        return aa;
    }
}


