  }
  for (i64 i = 0; i < n; ++i) {
    if (!(x & (1 << i))) tab.push_back(i);
  }
  for (i64 i = 0; i < v.size(); ++i) {
    i64 y = 0;
    for (i64 j = 0; j < n; ++j) {
      if (v[i] & (1 << j)) y |= 1 << tab[j];
    }
    v[i] = y;
  }

  cout << "YES\n";
  for (i64 y : v) {
    cout << (y ^ a) << ' ';
  }
