const int maxn = (1 << 17) + 20;

int a[maxn] , b[maxn];

void solve(int n , int x)
{
	if(n == 1)
	{
		assert(x == 1);
		a[0] = 0 , a[1] = 1;
		return;
	}

	if(x & 1)
		solve(n - 1 , (x / 2) ^ 1);
	else
		solve(n - 1 , x >> 1);

	for(int i = 0; i < (1 << (n - 1)); i += 2)
	{
		b[i * 2] = a[i] * 2;
		b[i * 2 + 1] = a[i] * 2 + 1;
		b[i * 2 + 2] = a[i + 1] * 2 + 1;
		b[i * 2 + 3] = a[i + 1] * 2;
	}

	memcpy(a , b , sizeof b);

	if(x & 1)
	{
		for(int i = 0; i < (1 << n); i += 4)
		{
			assert(a[i] != x && a[i + 2] != x && a[i + 3] != x);
			if(a[i + 1] == x)
			{
				a[i + 1] = a[i + 3];
				for(int j = i + 3; j + 1 < (1 << n); j++)
					a[j] = a[j + 1]^1;
				a[(1 << n) - 1] = x;
				break;
			}
		}
	}
}

