#include <bits/stdc++.h>
using namespace std;
deque<int> seq = {0, 1};
deque<int> ans;

void calc(int ai, int bi, int n) {
    int in; bool front; bool rev;
    int l = ai+1; int r = (1 << n) - bi;
    //cout << ai << " " << bi << endl;
    //cout << " " << l << " " << r << endl;
    if (l > r) {
        for (int i = bi; i < (1 << n); i++) {
            ans.emplace_back(seq[i]);
        }
        for (int i = 0; i < r; i++) {
            ans.emplace_back(seq[i]);
        }
        in = ai;
        l = r; r = bi-1;
        front = false;
        rev = true;
    } else {
        for (int i = ai; i >= 0; i--) {
            ans.emplace_back(seq[i]);
        }
        for (int i = 1; i <= l+1; i++) {
            ans.emplace_back(seq[(1<<n)-i]);
        }
        in = bi; front = true;
        l = ai+1; r = (1 << n) - l-1;
        rev = false;
    }
    while (!(l == in && r == in)) {
        if (l > r) break;
        //cout << l << " " << r << " " << in << endl;
        if (front) {
            if (l != in) {
                ans.emplace_back(seq[l]);
                l++;
            }
        } else {
            if (r != in) {
                ans.emplace_back(seq[r]);
                r--;
            }
        }
        front = !front;
    }
    if (rev) reverse(ans.begin(), ans.end());
}

