    cin >> N;
    len = (int) pow(2, N);
    for (int i=0;i<len;i++){
        perm[i] = vector<bool>(N);
    }
    cin >> A >> B;
    perm[0] = getbin(A), perm[len-1] = getbin(B);  
    int cnt = 0;
    for (int i=0;i<N;i++){
        cnt += (perm[0][i]!=perm[len-1][i]);
    }
    if (cnt%2==0) {
        cout << "NO" << endl;
        return 0;
    }
    cout << "YES" << endl;
    fill(0, len-1, 0);
    for (int i=0;i<len;i++){
        cout << getval(perm[i]) << " ";
    }
    cout << endl;
}

