#include <bits/stdc++.h>

using namespace std;
typedef long long ll;
typedef long double ld;

const int maxn = 2e5 + 10;
const int mod = 1e9 + 7;

int n, pow2n;
vector<int> answer;
bool mark[20];

void find_answer(int a, int b, int m){
	if (m == 1){
		answer.push_back(a);
		answer.push_back(b);
		return;
	}
	int k = a ^ b;
	bool flag = 0;
	for (int i = 0; i < n; i++){
		if (mark[i] or (k & (1 << i)))
			continue;
		flag = 1;
		vector<int> vis;
		for (int j = 0; j < n; j++)
			vis.push_back(mark[j]);
		if (a & (1 << i)){
			mark[i] = 1;
			vis[i] = 1;
			find_answer(a, b, m - 1);
			int pre = answer[answer.size() - 2];
			answer.pop_back();
			for (int j = 0; j < n; j++)
				mark[j] = vis[j];
			find_answer(pre - (1 << i), b - (1 << i), m - 1);
			answer.push_back(b);
		}
		else{
			mark[i] = 1;
			vis[i] = 1;
			find_answer(a, b, m - 1);
			int pre = answer[answer.size() - 2];
			answer.pop_back();
			for (int j = 0; j < n; j++)
				mark[j] = vis[j];
			find_answer(pre + (1 << i), b + (1 << i), m - 1);
			answer.push_back(b);
		}
	}
	if (flag == 1)
		return;
	for (int i = 0; i < n; i++){
		if (k & (1 << i)){
			for (int j = i + 1; j < n; j++){
				if (k & (1 << j)){
					vector<int> vis;
					for (int x = 0; x < n; x++)
						vis.push_back(mark[x]);
					vis[j] = mark[j] = 1;
					find_answer(a, a ^ (1 << i), m - 1);
					for (int x = 0; x < n; x++)
						mark[x] = vis[x];
					find_answer(a ^ (1 << i) ^ (1 << j), b, m - 1);
					mark[i] = 1;
				}
			}
		}
	}
}

int main(){
	ios_base::sync_with_stdio(false);
	int a, b;
	cin >> n >> a >> b;
	b ^= a;
	int cnt = 0;
	for (int i = 0; i < n; i++)
		if (b & (1 << i))
			cnt ++;
	if (!(cnt & 1))
		return cout << "NO" << endl, 0;
	find_answer(0, b, n);
	cout << "YES" << endl;
	for (auto it : answer)
		cout << (it ^ a) << " ";
	cout << endl;
}

