vector<int> gray(int n) {
  vector<int> res(1 << n);
  for (int i = 0; i < 1 << n; i++) {
    res[i] = i ^ (i >> 1);
  }
  auto it = find(res.begin(), res.end(), 0);
  rotate(res.begin(), it, res.end());
  return res;
}

int popcnt(int x) {
  int res = 0;
  while (x > 0) {
    res++;
    x &= x - 1;
  }
  return res;
}

