    for(int i=0;i<n;i++){
        if(((a>>i)&1)!=((b>>i)&1)){
            cnt++;
        }
    }
    if(cnt%2==0){
        printf("NO\n");
        return 0;
    }
    printf("YES\n");
    if(n==1){
        printf("%d %d\n",a,b);
        return 0;
    }

    for(int i=0;i<(1<<n);i+=4) {
        G[i].push_back(i + 1);
        G[i].push_back(i + 2);
        G[i + 3].push_back(i + 1);
        G[i + 3].push_back(i + 2);

    }
    for(int i=2;i<n;i++){
        for(int j=0;j<(1<<n);j+=(2<<i)){
            int v1=G[j].back();
            int v2=G[j+(1<<i)].back();
            G[j].pop_back();
            G[j+(1<<i)].pop_back();
            G[j].push_back(j+(1<<i));
            G[v2].push_back(v1);
        }
    }

    for(int i=0;i<(1<<n);i++){
        for(int j=0;j<G[i].size();j++){
            G2[G[i][j]].push_back(i);
        }
    }
    for(int i=0;i<(1<<n);i++){
        for(int j=0;j<G2[i].size();j++){
            G[i].push_back(G2[i][j]);
        }
    }
    bool flag=false;
    for(int i=0;i<G[a].size();i++){
        if(G[a][i]==b)flag=true;
    }
    if(!flag){
        int v1=G[a].back();
        int v2=G[b].back();
        if(v1==v2){
            swap(G[a].back(),G[a][0]);
            v1=G[a].back();
        }
        if(G[v1].back()!=a){
            swap(G[a][0],G[a].back());
        }
        if(G[v2].back()!=b){
            swap(G[b][0],G[b].back());
        }
        G[a].pop_back();
        G[b].pop_back();
        G[v1].pop_back();
        G[v2].pop_back();
        G[a].push_back(b);
        G[b].push_back(a);
        G[v1].push_back(v2);
        G[v2].push_back(v1);
    }
    for(int i=0;i<(1<<n);i++){
        assert(G[i].size()==2);
    }
    bfs(a);
