int ones(ll x) {
    return __builtin_popcountll(x);
}

vector<int> res;


void solve(int n, int a, int b, int st, int e) {
    if (n == 1) {
        res[st] = a;
        res[st + 1] = b;
        return;
    }
    int id = 0;
    int c = a ^ b;
    while ((c & 1) == 0) {
        c /= 2;
        ++id;
    }
    c = (a >> id) & 1;
    a = (a & ((1 << id) - 1)) + ((a >> (id + 1)) << id);
    b = (b & ((1 << id) - 1)) + ((b >> (id + 1)) << id);
    int m = (st + e) / 2;
    solve(n - 1, a, a ^ 1, st, m);
    solve(n - 1, a ^ 1, b, m, e);
    for (int i = st; i < m; ++i) {
        res[i] = (res[i] & ((1 << id) - 1)) + ((res[i] >> id) << (id + 1)) + (c << id);

    }
    c ^= 1;
    for (int i = m; i < e; ++i) {
        res[i] = (res[i] & ((1 << id) - 1)) + ((res[i] >> id) << (id + 1)) + (c << id);
    }

}

void solve() {
    int n, a, b;
    cin >> n >> a >> b;
    int x = ones(a ^ b);

    if (x % 2 == 0) {
        cout << "NO\n";
        return;
    }
    int up = 1 << n;
    res.resize(up);

    cout << "YES\n";
    solve(n, a, b, 0, up);
    for (int i = 0; i < up; ++i) {
        cout << res[i] << " ";
    }
