	b ^= a;
	int cnt = 0;
	for (int i = 0; i < n; i++)
		if (b & (1 << i))
			cnt ++;
	if (!(cnt & 1)){
		printf("NO\n");
		return 0;
	}
	find_answer(0, b, n);
	printf("YES\n");
	for (int i = 0; i < ptr; i++)
		printf("%d ", (answer[i] ^ a));
}

