//配列の後ろのx個の要素をひっくり返して返す
vi behind_rev(vi vec,int x){
  int vs=vec.size();
  int temp[(const int)x];
  rep(i,x){
    temp[x-1-i]=vec[vs-x+i];
  }
  rep(i,x){
    vec[vs-x+i]=temp[i];
  }
  return vec;
}
//1番後ろがx(=2*n+1)であるGray Codeを作成する
vi Gray_Code(int n,int x){
  vi res;
  for(int i=0;i<(1<<n);i++){
    res.push_back(i^(i>>1));
  }
  int cnt=0;
  rep(i,n) if(x>>i&1) cnt++;//bitがいくつ立っているか
  int j=0,a=3,b=8;
  while(j<cnt/2){
    res=behind_rev(res,a);
    a+=b;
    b*=4;
    j++;
  }
  int k,rs=res.size();
  rep(i,rs){
    if(res[i]==x){
      k=i;
      break;
    }
  }
  //  rep(i,res.size()){
  //    std::cout<<res[i]<<" ";
  //  }
  //  std::cout<<"\n";  

  int temp=res[k];
  res[k]=res[rs-1];
  res[rs-1]=temp;
