#define vi vector<int>


inline int getSmall(int mask, int i){
	return ((mask >> (i + 1)) << i) | (mask & ((1 << i) - 1));
}

inline int getLarge(int mask, int i, int v){
	return ((mask >> i) << (i + 1)) + (v << i) + (mask & ((1 << i) - 1));
}

vi get(int mask, int i){
	if(i == 0) return {0};
	if(i == 1){
		assert(mask == 1);
		return {0, 1};
	}
	int pos1 = -1, pos2 = -1, absent = 0;
	int cnt = 0;
	for(int j = 0; j < i; j++){
		if(mask >> j & 1){
			if(pos1 == -1){
				pos1 = j;
			} else if(pos2 == -1){
				pos2 = j;
			}
			cnt++;
		} else absent = j;
	}
	// trace(mask, pos1, pos2, cnt, i);
	assert(cnt & 1);
	if(pos2 == -1){
		int toGet = getSmall(mask ^ (1 << pos1) ^ (1 << absent), pos1);
		// trace(toGet, pos1, absent, mask, i);
		vi rgt = get(toGet, i - 1);
		vi ret = rgt;
		int k = ret.size();
		// trace(k, ret[0], ret[1]);
		ret.resize(2 * k);
		for(int i = k; i < 2 * k; i++) ret[i] = ret[k - 1] ^ ret[i - k];

		for(int i = 0; i < 2 * k; i++) ret[i] = getLarge(ret[i], pos1, i / k);
		return ret;
	}

	else{
		vi v1 = get(getSmall(mask ^ (1 << pos1) ^ (1 << pos2), pos1), i - 1);
		vi v2 = get(getSmall(1 << pos2, pos1), i - 1);
		int k = v1.size();
		for(int i = 0; i< k; i++) v2[i] = v1[i] ^ v1[k - 1];
		vi ret(2 * k);
		for(int i = 0; i < 2 * k; i++) ret[i] = getLarge(i < k ? v1[i] : v2[i - k], pos1, i / k);
		return ret;
	}
}

