vector<int> solve(int n, int A, int B) {
	if (n == 1) {
		vector<int> ret;
		ret.push_back(A);
		ret.push_back(B);
		return ret;
	}
	int k = 0;
	while (k < n) {
		if ((A^B)&(1 << k)) break;
		k++;
	}
	int nxtA = 0, nxtB = 0;
	for (int i = n - 1; i >= 0; i--) {
		if (i == k) continue;
		nxtA <<= 1;
		if (A&(1 << i)) nxtA |= 1;
		nxtB <<= 1;
		if (B&(1 << i)) nxtB |= 1;
	}
	int C = nxtA ^ 1;
	vector<int> v1 = solve(n - 1, nxtA, C);
	vector<int> v2 = solve(n - 1, C, nxtB);
	vector<int> ret;
	for (int i = 0; i < v1.size(); i++) {
		int x = 0;
		for (int j = 0; j < n; j++) {
			if (j == k) {
				if (A&(1 << k)) x |= (1 << j);
			}
			else {
				if (v1[i] & 1) x |= (1 << j);
				v1[i] >>= 1;
			}
		}
		ret.push_back(x);
	}
	for (int i = 0; i < v2.size(); i++) {
		int x = 0;
		for (int j = 0; j < n; j++) {
			if (j == k) {
				if (B&(1 << k)) x |= (1 << j);
			}
			else {
				if (v2[i] & 1) x |= (1 << j);
				v2[i] >>= 1;
			}
		}
		ret.push_back(x);
	}
	return ret;
}
