V<int> construct(int a, int b, int mask, int N) {
	if (__builtin_popcount(mask) == 1) {
		return {a, b};
	}
	int p = -1;
	int ca, cb;

	rep(i, N) if ((mask >> i) & 1) {
		if (((a >> i) ^ (b >> i)) & 1) {
			ca = (a >> i) & 1;
			cb = (b >> i) & 1;
			p = i;
			break;
		}
	}
	int ch = -1;
	rep(i, N) if ((mask >> i) & 1) {
		if (i != p) {
			ch = i;
			break;
		}
	}

	int na = (ca ? (a ^ (1 << p)) : a);
	V<int> vl = construct(na, na ^ (1 << ch), mask ^ (1 << p), N);
	int nb = (cb ? (b ^ (1 << p)) : b);
	V<int> vr = construct(na ^ (1 << ch), nb, mask ^ (1 << p), N);

	V<int> vec;
	for (int x : vl) {
		int nx = x;
		if (ca) nx |= (1 << p);
		vec.pb(nx);
	}
	for (int x : vr) {
		int nx = x;
		if (cb) nx |= (1 << p);
		vec.pb(nx);
	}	
	return vec;
}

int main() {
	int N, A, B;
	cin >> N >> A >> B;
	int ca = (__builtin_popcount(A)) & 1;
	int cb = (__builtin_popcount(B)) & 1;
	if (ca == cb) {
		puts("NO");
		return 0;
	}
	puts("YES");
	auto res = construct(A, B, (1 << N) - 1, N);
	rep(i, res.size()) cout << res[i] << (i+1==res.size()?'\n':' ');

	return 0;
}

