vector<int> hoge(int C) {
	vector<int> R;
	int x,y;
	if(__builtin_popcount(C)==1) {
		FOR(x,N) if(C&(1<<x)) break;
		R.push_back(0);
		R.push_back(1<<x);
		return R;
	}
	FOR(x,N) if(C&(1<<x)) break;
	FOR(y,N) if(x!=y && (C&(1<<y))) break;
	vector<int> T=hoge(C^(1<<x)^(1<<y));

	R=T;
	reverse(ALL(T));
	FORR(t,T) R.push_back(t^(1<<x));
	reverse(ALL(T));
	int step=0;
	FORR(t,T) {
		if(step==0) {
			R.push_back(t^(1<<x)^(1<<y));
			R.push_back(t^(1<<y));
		}
		else {
			R.push_back(t^(1<<y));
			R.push_back(t^(1<<x)^(1<<y));
		}
		step^=1;
	}
	return R;

}

