int sub(int val,int x){
    int res=0;
    for(int i=0;i<30;i++){
        if(i==x) continue;
        if(val&(1<<i)){
            if(i<x) res+=(1<<i);
            else res+=(1<<(i-1));
        }
    }
    return res;
}

int add(int val,int x){
    int res=0;
    for(int i=0;i<30;i++){
        if(i==x) continue;
        if(i>x){
            if(val&(1<<(i-1))) res+=(1<<i);
        }else{
            if(val&(1<<i)) res+=(1<<i);
        }
    }
    return res;
}

vector<int> solve(int n,int start,int end){
    vector<int> res;
    if(n==1){
        res.push_back(start);
        res.push_back(end);
        return res;
    }

    int dif=0;
    for(int i=n-1;i>=0;i--){
        if((start&(1<<i))!=(end&(1<<i))){
            dif=i;
            break;
        }
    }

    int nexst=sub(start,dif);
    int nexed=sub(end,dif);
    int mid=nexst^(1<<(n-2));
    vector<int> lef=solve(n-1,nexst,mid);
    for(int i=0;i<lef.size();i++){
        int val=add(lef[i],dif);
        if(start&(1<<dif)) val+=(1<<dif);
        res.push_back(val);
    }
    vector<int> rig=solve(n-1,mid,nexed);
    for(int i=0;i<rig.size();i++){
        int val=add(rig[i],dif);
        if(end&(1<<dif)) val+=(1<<dif);
        res.push_back(val);
    }
    return res;
}

