namespace n91 {

	u32 pop(const usize n) {
		return static_cast<u32>(1) << n;
	}

	bool check(const u32 a, const usize n) {
		return (a&pop(n)) != 0;
	}

	u32 exc(const u32 a,const usize n, const usize m) {
		if (check(a, n) ^ check(a, m)) {
			return a ^ pop(n) ^ pop(m);
		}
		else {
			return a;
		}
	}

	std::vector<u32> solve2(const usize n, const u32 a, const u32 b);

	std::vector<u32> solve(const usize n, const u32 g) {
		const usize s = static_cast<usize>(1) << n;
		const usize lo = ctz32(g);
		if (popcount32(g) == 1) {
			std::vector<u32> ret(s);
			for (const auto i : rep(0, s)) {
				ret[i] = exc(i^(i >> 1), n - 1, lo);
			}
			return std::move(ret);
		}
		std::vector<u32> ret(s / 2);
		for (const auto i : rep(0, s / 2)) {
			ret[i] = i ^ (i >> 1);
		}
		const auto p = solve2(n - 1, pop(n - 2), exc(g, n - 1, lo) ^ pop(n - 1));
		for (const auto e : p) {
			ret.emplace_back(e ^ pop(n - 1));
		}
		for (auto &e : ret) {
			e = exc(e, lo, n - 1);
		}
		return std::move(ret);
	}
	std::vector<u32> solve2(const usize n, const u32 a, const u32 b) {
		auto ret = solve(n, a^b);
		for (auto &e : ret) {
			e ^= a;
		}
		return std::move(ret);
	}

