vector<int> solve(int a, int b, int n)
{
	if(n == 0) return vector<int> {a, b};
	int x = a ^ b;
	vector<int> ret;
	if(x & (1 << n))
	{
		auto lret = solve(a, a ^ 1, n - 1);
		auto rret = solve(a ^ 1 ^ (1 << n), b, n - 1);
		for(auto v : lret) ret.push_back(v);
		for(auto v : rret) ret.push_back(v);
		return ret;
	}
	else
	{
		auto sret = solve(a, b, n - 1);
		auto dret = solve(sret[0] ^ (1 << n), sret[1] ^ (1 << n), n - 1);
		ret.push_back(sret[0]);
		for(auto v : dret) ret.push_back(v);
		for(int i = 1; i < sret.size(); ++i) ret.push_back(sret[i]);
	}
	return ret;
}
