  rep(i,rs) if(res[i]==x) k=i;
  int temp=res[k];
  res[k]=res[0];
  res[0]=temp;
  rep(i,rs) if(res[i]==y) k=i;
  temp=res[k];
  res[k]=res[rs-1];
  res[rs-1]=temp;

