int main() {
	int n, a, b;
	scanf("%d %d %d", &n, &a, &b);

	auto cnton = [&](int x) {
		return __builtin_popcount(x);
	};

	auto ok = [&](int a,int b) {
		return (cnton(a) + cnton(b)) & 1;
	};

	if (!ok(a, b)) {
		puts("NO");
		return false;
	}

	auto bit = [&](int x,int id) {
		return (x >> id) & 1;
	};

	function<vector<int>(int,int,vector<int>)> solve = [&](int from,int to,vector<int> val) {
		if (val.size() == 2) {
			vector<int> ans;
			ans.push_back(from);
			ans.push_back(to);
			return ans;
		} else {
			int id = -1;
			for (int i = 0; i < n; ++i) {
				if (bit(from, i) != bit(to, i)) {
					id = i;
					break;
				}
			}
			vector<int> valL, valR;
			for (int v : val) {
				if (bit(v, id) == bit(from, id)) {
					valL.push_back(v);
				} else {
					valR.push_back(v);
				}
			}
			for (int v : valL) {
				if (ok(from, v)) {
					vector<int> ll = solve(from, v, valL);
					vector<int> rr = solve(v ^ (1 << id), to, valR);
					vector<int> ans;
					for (int u : ll) ans.push_back(u);
					for (int u : rr) ans.push_back(u);
					return ans;
				}
			}
		}
	};

	vector<int> val;
	for (int i = 0; i < (1 << n); ++i) val.push_back(i);
	auto ans = solve(a, b, val);
	puts("YES");
	for (int v : ans) printf("%d ", v);
}

