vector <int> Solve(int n, int u, int v)
{
    vector <int> res;
    if (n == 0) return res = {u, v};
    int Zu = u&(1<<n), Zv = v&(1<<n);
    if (Zu == Zv) {
        vector <int> vec = Solve(n-1, u^Zu, v^Zu);
        vector <int> _vec = Solve(n-1, vec[0], vec[1]);
        res.push_back(vec[0]^Zu);
        for (int i : _vec) res.push_back(i^Zu^(1<<n));
        for (int i = 1; i < vec.size(); i++) res.push_back(vec[i]^Zu);
    }
    else {
        vector <int> vec = Solve(n-1, u^Zu, __builtin_popcount(u^Zu)&1^1);
        vector <int> _vec = Solve(n-1, __builtin_popcount(v^Zv)&1^1, v^Zv);
        for (int i : vec) res.push_back(i^Zu);
        if (__builtin_popcount(u^Zu) != __builtin_popcount(v^Zv)) assert(0);
        for (int i : _vec) res.push_back(i^Zv);
    }
    return res;
}

