#include <bits/stdc++.h>
using namespace std;
using ll = int64_t;

ll popcount(ll x) {
    ll result = 0;
    for (ll i = 0; i < 64; i++) {
        if (x & (1LL << i)) {
            result++;
        }
    }
    return result;
}

//sとtは下位nビットの中で立っているbitの数の偶奇が異なることを前提
vector<ll> solve(ll s, ll t, ll n) {
    if (n == 1) {
        return { s, t };
    }

    vector<ll> result;

    //最上位ビットを考える
    ll l = (1LL << (n - 1));
    if ((s & l) == (t & l)) {
        //最上位ビットが同じ
        //例)
        //s:1000
        //t:1010
        //このときn-1ビット以下でs→tを考えると,sの次には
        //n-1ビット以下のどこか1箇所がsと異なる
        //ものcが得られる(s→c→...→t)
        //ここでそのcのnビット目を反転したものをc'として
        //sのnビット目を反転したs'との比較を考えると
        //やはりn-1ビット以下のどこか1箇所が異なるので
        //s'→c'という遷移が再帰的に考えられる
        //全体として
        //s→s'→...→c'→c→...→t
        //という遷移を考えれば良い

        //まずs→tを構築
        auto v1 = solve(s, t, n - 1);

        //2番目のものの最上位ビット反転へのパスを構築(c = v1[1])
        auto v2 = solve(s ^ l, v1[1] ^ l, n - 1);

        //初手はs
        result.push_back(s);

        //s'→c'
        result.insert(result.end(), v2.begin(), v2.end());

        //c→t
        result.insert(result.end(), v1.begin() + 1, v1.end());
    } else {
        //最上位ビットが異なる
        //例)
        //s:1000
        //t:0110
        //このとき間に挟むのは最下位ビットを反転した
        //c :1001
        //とこれの最上位ビットを反転したものを
        //c':0001
        //としてs→c→c'→tという遷移を考えれば良い
        ll c = s ^ 1;
        auto v1 = solve(s, c, n - 1);
        auto v2 = solve(c ^ l, t, n - 1);
        result.insert(result.end(), v1.begin(), v1.end());
        result.insert(result.end(), v2.begin(), v2.end());
    }
    return result;
}

int main() {
    ll N, A, B;
    cin >> N >> A >> B;

    if (popcount(A) % 2 == popcount(B) % 2) {
        cout << "NO" << endl;
        return 0;
    }

    cout << "YES" << endl;
    auto ans = solve(A, B, N);
    for (ll i = 0; i < ans.size(); i++) {
        cout << ans[i] << " \n"[i == ans.size() - 1];
    }
}

