using BS = bitset<64>;

ll add_dig(ll A, ll dig, bool enable_bit) {
    ll upper = (A & (~((1ll << dig) - 1))) * 2;
    ll lower = (A & ((1ll << dig) - 1));
    return upper + lower + (enable_bit ? (1ll << dig) : 0);
}

ll erase_dig(ll A, ll dig) {
    ll upper = (A & (~((1ll << (dig + 1)) - 1))) / 2;
    ll lower = (A & ((1ll << dig) - 1));
    return upper + lower;
}

V<ll> create(ll A, ll B, ll N) {
    DEBUG(make_pair(A, B));
    if(N == 1) return { A, B };
    ll dig;
    for(ll i = 0;; i++) {
        if((A & (1ll << i)) ^
           (B & (1ll << i))) {
            dig = i;
            break;
        }
    }
    ll AA = erase_dig(A, dig);
    ll BB = erase_dig(B, dig);
    V<ll> va = create(AA, (AA ^ 1), N - 1);
    V<ll> vb = create((AA ^ 1), BB, N - 1);
    V<ll> ret = move(va);
    for(ll e : vb) ret.push_back(add_dig(e, dig, !(A & (1ll << dig))));
    return move(ret);
}

