			UL L = buf2.size(); if (!L) return {};
			rep(i, L) buf2[i] |= (1 << (N - 1));
			rep(i, L) buf2[i] ^= 1;
			rep(i, L) buf1.push_back(buf2[i]);
			return move(buf1);
		}
	}

	void Solve() {
		UL N, A, B; cin >> N >> A >> B;
		vector<UL> ans = Solve2(N, A^B);
		if (ans.size() == 0) { cout << "NO" << endl; return; }
		rep(i, ans.size()) ans[i] ^= A;
		cout << "YES" << endl;
		rep(i, ans.size()) { if (i) cout << " "; cout << ans[i]; }
		cout << endl;
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
