vector<int> go(int a, int b, int k, int open) {
	//cout << a << ' ' << b << ' ' << k << ' ' << open << endl;
	if (k == 1)
		return {a, b};
	int ind = -1;
	for (int i = 0; i < n; ++i)
		if ((get(a, i) != get(b, i)) && get(open, i))
			ind = i;
	assert(ind != -1);
	int ind2 = -1;
	for (int i = 0; i < n; ++i)
		if (get(open, i) && (i != ind))
			ind2 = i;
	assert(ind2 != -1);
	vector<int> ans1 = go(a, a^(1<<ind2), k-1, open^(1<<ind));
	vector<int> ans2 = go(a^(1<<ind2)^(1<<ind), b, k-1, open^(1<<ind));
	for (int j : ans2)
		ans1.push_back(j);
	return ans1;
}

