int bit_count(int a) {
  int cnt = 0;
  while (a > 0) {
    if (a & 1) cnt++;
    a >>= 1;
  }
  return cnt;
}

int bit_swap(int a, vector<pii> &swaps) {
  int add = 0, sub = 0;
  rep (i, swaps.size()) {
    int i1 = swaps[i].first, i2 = swaps[i].second;
    if (a & (1 << i1)) {
      sub += 1 << i1;
      add += 1 << i2;
    }
    if (a & (1 << i2)) {
      sub += 1 << i2;
      add += 1 << i1;
    }
  }
  a -= sub;
  a += add;
  return a;
}

