int calc(int st, int ed)
{
	int ret = 0;
	for (int i = 0; i < N; i++)
		if ((st >> i & 1) ^ (ed >> i & 1))
			ret++;
	return ret;
}

void work(int pos)
{
	int len = 1;
	fn_per.push_back(per[N][tot - 1]);
	for (len = 3; tot - len >= pos; len += 2)
	{
		fn_per.push_back(per[N][tot - len + 1]);
		fn_per.push_back(per[N][tot - len]);
	}
	len -= 2;
	cout << "YES" << endl;
	for (int i = 0; i < tot - len; i++)
		cout << per[N][i] << ' ';
	for (int i = tot - len; i < tot; i++)
		cout << fn_per[i - tot + len] << ' ';
	cout << endl;
}

int main()
{
//	freopen("1.in", "r", stdin);
//	freopen("ans.txt", "w", stdout);
	cin >> N >> A >> B;
	if (calc(A, B) % 2 == 0)
	{
		cout << "NO" << endl;
		return 0;
	}
	per[1][0] = 0, per[1][1] = 1;
	for (int i = 2; i <= N; i++)
	{
		int cur = (1 << i);
		for (int j = 0; j < cur; j++)
			per[i][j] = per[i - 1][j >> 1];
		for (int j = 0; j < cur; j += 4)
		{
			per[i][j + 1] |= (1 << i - 1);
			per[i][j + 2] |= (1 << i - 1);
		}
	}
