int pops(int x)
{
    int ret = 0;
    while (x)
    {
        if (x % 2)
            ret++;
        x /= 2;
    }
    return ret;
}

int N, A, B;
bool check(vector<int> &ret)
{
    vector<vector<int>> g(1 << N);
    vector<int> ps(1 << N), used(1 << N, 0);
    for (int i = 0; i < (1 << N); i++)
    {
        ps[i] = pops(i);
        if (i == B)
            continue;
        for (int j = 0; j < N; j++)
        {
            int next = i ^ (1 << j);
            if (next == A || next == B)
                continue;
            g[i].push_back(next);
            // cout << i << " " << next << endl;
        }
        sort(g[i].begin(), g[i].end());
    }
    for (int j = 0; j < N; j++)
    {
        int st = B ^ (1 << j);
        g[st].push_back(B);
        // cout << st << " " << B << endl;
    }
    ret.push_back(A);
    used[A] = 1;
    bool f = true;
    for (int i = 1; i < (1 << N); i++)
    {
        int cur = ret[ret.size() - 1];
        int bef = -1, aft = -1;
        for (const auto &v : g[cur])
        {
            if (used[v])
                continue;
            if (ps[v] < ps[cur])
            {
                if (bef != -1)
                    continue;
                bef = v;
            }
            else
            {
                if (aft != -1)
                    continue;
                aft = v;
            }
        }
        if (bef == -1 && aft == -1)
        {
            f = false;
            break;
        }
        else if (bef == -1)
        {
            ret.push_back(aft);
            used[aft] = 1;
        }
        else if (aft == -1)
        {
            ret.push_back(bef);
            used[bef] = 1;
        }
        else
        {
            int next;
            if (abs(ps[B] - ps[bef]) < abs(ps[B] - ps[aft]))
            {
                next = aft;
            }
            else
            {
                next = bef;
            }
            ret.push_back(next);
            used[next] = 1;
        }
    }
    return f;
}

