int swap_bit (int mask, int i, int j) {
  if (i == j) return mask;

  int ith = (mask >> i) & 1;
  int jth = (mask >> j) & 1;
  mask -= ith << i;
  mask -= jth << j;

  mask += ith << j;
  mask += jth << i;

  return mask;
}

int blog (int x) {
  return 31 - __builtin_clz(x);
}

int split (int mask) {
  int target = __builtin_popcount(mask) / 2;
  while (__builtin_popcount(mask) != target) {
    mask -= mask & -mask;
  }
  return mask;
}

vector<int> gray (int n, int mask, int a, int b) {
  if (n == 1) return {a, b};

  if (__builtin_popcount(a ^ b) == 1) {
    int dbit = a ^ b;

    mask -= dbit;
    int mid = mask & -mask;

    vector<int> l = gray(n - 1, mask, a, mid ^ a);
    vector<int> r = gray(n - 1, mask, mid ^ b, b);
    for (int u : r) {
      l.push_back(u);
    }
    return l;
  }

  // now there are at least 3 different bits in a and b
  int diff = a ^ b;
  int dbit = diff & -diff;
  diff -= dbit;
  mask -= dbit;

  int half = diff & -diff;
  vector<int> l = gray(n - 1, mask, a, half ^ a);
  vector<int> r = gray(n - 1, mask, diff ^ half ^ b, b);
  for (int u : r) {
    l.push_back(u);
  }
  return l;
}

int main () {
  int n, a, b;
  cin >> n >> a >> b;

  if (__builtin_popcount(a ^ b) % 2 == 0) {
    failure();
