const int BITS = 20;
int cntbits(int x) {
	int cnt = 0;
	for(int i = 0; i < BITS; ++i) {
		cnt += x&1;
		x >>= 1;
	}
	return cnt;
}

int check(int A, int B) {
	return cntbits(A ^ B) & 1;
}

vector<int> build(int A, int B, int n) {
	if(n == 1) {
		if(A == 0 && B == 1) return {A, B};
		if(A == 1 && B == 0) return {A, B};
		assert(false);
	} else if((A&1) == (B&1)) {
		auto v = build(A>>1, B>>1, n - 1);
		DBG(v);
		vector<int> rez;
		int flag = A&1;
		for(auto& el: v) {
			rez.push_back(2*el+flag);
			flag ^= 1;
			rez.push_back(2*el+flag);
		}

		return rez;
	} else {
		auto v = build(A>>1, (A>>1)^1, n - 1);
		auto u = build((A>>1)^1, B>>1, n - 1);
		vector<int> rez;
		for(auto& el: v) rez.push_back(2*el+(A&1));
		for(auto& el: u) rez.push_back(2*el+(B&1));
		return rez;
	}
}

