set<int> E[200000];

vector<int> dfs(int v, int depth) {
    if(depth == (1 << N)) {
        if(v == B) return vector<int>(1, B);
        else return vector<int>(0);
    }

    bool flag = false;
    vector<int> path;
    for(int to : E[v]) E[to].erase(v);
    for(int to: E[v]) {
        path = dfs(to, depth + 1);
        if(path.size() == (1 << N) - depth) {
            flag = true;
            path.push_back(v);
            break;
        }
    }
    for(int s=0; s < N; ++s) E[v ^ (1LL << s)].insert(v);

    if(flag) return path;
    else return vector<int>(0);
}

