    for(int i=0; i<(1LL << N); ++i) {
        for(int s=0; s < N; ++s) {
            E[i].insert(i ^ (1 << s));
        }
    }

    vector<int> path = dfs(A, 1);
    if(path.size() == (1 << N)) {
        cout << "YES" << endl;
        for(int i=(1 << N) - 1; i>=0; --i) {
            cout << path[i];
            cout << (i == 0 ? '\n' : ' ');
        }
