int check(int N, int A, int B){
    for(int i = 0; i < 141414; i++)flg[i] = 0;
    flg[A] = 1;
    flg[B] = 1;
    int cnt = 2 - (1 << N);
    for(int i = 0; i < (1 << N) - 2; i++, cnt++){
        int tmpA = A;
        for(int j = 0, b = 1; j < N;j++, b <<= 1){
            if(flg[A ^ b])continue;
            flg[A ^ b] = 1;
            A ^= b;
            break;
        }
        if(tmpA == A)break;
    }
