void solve(int N, int A, int B, vector<int>& ret) {
    if(N == 1) {
        ret.push_back(A);
        ret.push_back(B);
        return;
    }

    int C = A ^ B;
    REP(i, N) {
        if(((C >> i) & 1) == 1) {
            int AA = ((A >> (i + 1)) << i) | (A & ((1 << i) - 1));
            int BB = ((B >> (i + 1)) << i) | (B & ((1 << i) - 1));
            vector<int> ret2;
            solve(N - 1, AA, AA ^ 1, ret);
            solve(N - 1, AA ^ 1, BB, ret2);

            REP(j, ret.size()) {
                int p = (A >> i) & 1;
                int x = ret[j], y = ret2[j];
                ret[j] = ((x >> i) << (i + 1)) | (p << i) | (x & ((1 << i) - 1));
                ret2[j] = ((y >> i) << (i + 1)) | ((p ^ 1) << i) | (y & ((1 << i) - 1));
            }
            ret.insert(ret.end(), ret2.begin(), ret2.end());
            break;
        }
    }
}

