int gray(int n, int* m, int depth) {
	int i, t = (1 << (depth - 1));

	if (depth == 0) {
		m[0] = 0;
	}
	else {
        for (i = 0; i < t; i++)
			m[t + i] = m[t - i - 1] + (1 << (depth - 1));
	}
	if (depth != n) {
		gray(n, m, depth + 1);
	}
	return 0;
}

