int f[1<<18];
void ex(int &x,int a,int b){if(a!=b&&((x>>a)&1)!=((x>>b)&1))x^=(1<<a)^(1<<b);}
void build(int l,int r,int s,int e,int n)
{
	if(l+1==r){f[l]=s;f[r]=e;return;}
	int m=(l+r)/2;
	e^=s;
	int k=18;
	while(~e&(1<<k))k--;
	ex(e,k,n-1);
	build(l,m,0,e^(1<<(n-1))^1,n-1);
	build(m+1,r,e^(1<<(n-1))^1,e^(1<<(n-1)),n-1);
	for(int i=r;i>m;i--)f[i]^=(1<<(n-1));
	for(int i=l;i<=r;i++)ex(f[i],k,n-1),f[i]^=s;
}
