void gray(int n, vector<int>& res)
{
    if (n == 0) {
        res.push_back(0); return;
    }
    vector<int> lower;
    gray(n - 1, lower);
    for (int i = 0; i < 1 << (n - 1); i++) {
        res.push_back(lower[i]);
    }
    reverse(lower.begin(), lower.end());
    for (int i = 0; i < 1 << (n - 1); i++) {
        res.push_back(lower[i] | (1 << (n - 1)));
    }
}

void all_on(int n, vector<int>& res)
{
    if (n == 1) {
        res.push_back(0); res.push_back(1); return;
    }
    if (n == 3) {
        res.push_back(0);
        res.push_back(4);
        res.push_back(5);
        res.push_back(1);
        res.push_back(3);
        res.push_back(2);
        res.push_back(6);
        res.push_back(7);
        return;
    }
    vector<int> gray_vec;
    gray(n - 3, gray_vec);
    vector<int> prev_vec;
    all_on(n - 2, prev_vec);
    for (int i = 0; i < (1 << (n - 3)); i++) res.push_back(gray_vec[i]);
    for (int i = 0; i < (1 << (n - 2)); i++) {
        res.push_back(prev_vec[i] ^ (1 << (n - 1)) ^ (1 << (n - 4)));
    }
    for (int i = 0; i < (1 << (n - 3)); i++) {
        res.push_back(gray_vec[i] ^ (1 << (n - 3)) ^ ((1 << (n - 4)) - 1));
    }
    reverse(prev_vec.begin(), prev_vec.end());
    for (int i = 0; i < (1 << (n - 2)); i++) {
        res.push_back(prev_vec[i] ^ (1 << (n - 2)));
    }
    reverse(prev_vec.begin(), prev_vec.end());
    for (int i = 0; i < (1 << (n - 2)); i++) {
        res.push_back(prev_vec[i] ^ (1 << (n - 2)) ^ (1 << (n - 1)));
    }
}

