#include <bits/stdc++.h>
using namespace std;

const int B = 18;
int mark[B];
int numbers[1 << B];
int n, a, b;

void solve(int st, int en, int set_bit, int rest){
    for(int i = st ; i <= en ; i++){
        if(numbers[i] & set_bit){
            numbers[i] ^= set_bit;
        }

        numbers[i] |= set_bit;
    }    

    if(rest <= 1){
        return;
    }

    int find = -1, se = -1;

    for(int j = 0 ; j < n ; j++){
        if(!mark[j]){
            if(find == -1)
                find = j;
            else
                se = j;
        }
    }

    assert(find != -1 && se != -1);

    mark[find] = true;

    int mid = (st + en) >> 1;

    numbers[mid] = numbers[mid + 1] = numbers[st] ^ (1 << se);

    if(numbers[mid] & (1 << find)){
        numbers[mid] ^= (1 << find);
        numbers[mid + 1] ^= (1 << find);
    }

    solve(st, mid, numbers[st] & (1 << find), rest - 1);
    solve(mid + 1, en, numbers[en] & (1 << find), rest - 1);

    mark[find] = false;
}

