    }

    if(__builtin_popcount(a ^ b) & 1){
        for(int i = 0 ; i < n ; i++){
            if((a & (1 << i)) != (b & (1 << i))){
                int ss = (i + 1) % n;

                mark[i] = true;
                int mid = ((1 << n) - 1) >> 1;

                numbers[mid] = numbers[mid + 1] = numbers[0] ^ (1 << ss);

                if(numbers[mid] & (1 << i)){
                    numbers[mid] ^= (1 << i);
                    numbers[mid + 1] ^= (1 << i);
                }

                solve(0, mid, (a & (1 << i)), n - 1);
                solve(mid + 1, (1 << n) - 1, (b & (1 << i)), n - 1);
                break;
            }
        }

        cout << "YES" << endl;

        for(int i = 0 ; i < (1 << n) ; i++){
            cout << numbers[i] << ' ';
        }

        cout << endl;
