vector < int > get(int b)
{
        int es = -1;
        for(int i = 0; i < n; i++){
                if(b & (1 << i)){
                        es = i;
                }
        }
        vector < int > res;
        res.push_back(0);
        for(int i = 0; i <= n; i++){
                if(ban[i]){
                        continue;
                }
                int x = i;
                if(i == es){
                        continue;
                }
                if(i == n){
                        x = es;
                }
                vector < int > g = res;
                reverse(g.begin(), g.end());
                for(int y: g){
                        res.push_back(y ^ (1 << x));
                }
        }
        return res;
}

vector < int > solve(int b)
{
        vector < int > g;
        for(int i = 0; i < n; i++){
                if(b & (1 << i)){
                        g.push_back(i);
                }
        }
        if(g.size() == 1){
                return get(b);
        }
        ban[g[0]] = 1;
        vector < int > res = get(1 << g[1]);
        b ^= (1 << g[0]);
        b ^= (1 << g[1]);
        vector < int > gg = solve(b);
        for(int x: gg){
                res.push_back(x ^ (1 << g[0]) ^ (1 << g[1]));
        }
        return res;
}

