vector<int> con(int s, int g, int l){
  if(l==1) return std::vector<int> {s, g};
  int x=0, pre=0;
  for(int i=l-1;i>=0;i--){
    if(g>>i!=s>>i) {
      x = i;
      pre = (s>>i)%2;
      break;
    }
  }
  int sd = ((s>>1)&(((1<<(l-x-1)))-1) << x)+(s&((1<<x)-1));
  int gd = ((g>>1)&(((1<<(l-x-1)))-1) << x)+(g&((1<<x)-1));
  int mid = sd + (sd%2==1?-1:1);
  //std::cout << sd << " " << gd << " " << mid << '\n';
  std::vector<int> a = con(sd, mid, l-1);
  std::vector<int> b = con(mid, gd, l-1);
  int prefix =  ((1<<(l-x-1))-1) << x, suffix = (1<<x) - 1;
  for(int i=0;i<a.size();i++) a[i] = ((prefix&a[i]) << 1) + (pre==1?1<<x:0) + (suffix&a[i]);
  for(int i=0;i<b.size();i++) a.push_back(((prefix&b[i]) << 1) + (pre==1?0:1<<x) + (suffix&b[i]));
  return a;
}
