int calc(int x){
  int nx = __builtin_popcount(x);
  ans.pb(x);
  st[nx].erase(x);
  if(x == b){
    return b;
  }
  if(nx > 0 && sz(st[nx-1]) > 0){
    for(int j = n - 1; j >= 0; j--){
      if((x >> j) % 2 == 1){
        int tmp = x & (~(1 << j));
        if(tmp == b){
          continue;
        }
        if(st[nx-1].find(tmp) != st[nx-1].end()){
          return calc(tmp);
        }
      }
    }
  }
  if(nx < n && sz(st[nx+1]) > 0){
    for(int j = n - 1; j >= 0; j--){
      if((x >> j) % 2 == 0){
        int tmp = x | (1 << j);
        if(tmp == b){
          continue;
        }
        if(st[nx+1].find(tmp) != st[nx+1].end()){
          return calc(tmp);
        }
      }
    }
  }
  if(abs(__builtin_popcount(b) - nx) == 1){
