void rec(int from, int to, int used) {
  assert(pop(from ^ to) % 2 == 1);
  assert((from & used) == (to & used));

  if (pop(used) == n - 1) {
    assert(pop(from ^ to) == 1);
    cout << from << " " << to << " ";
