      for (int j = 0; j < n; ++j) {
        if (!bit(used, j) && j != k) {
          int mid = from ^ (1 << j);
          assert(bit(mid, k) == bit(from, k));
          assert(bit(mid ^ (1 << k), k) == bit(to, k));
          rec(from, mid, used | (1 << k));
          rec(mid ^ (1 << k), to, used | (1 << k));
          return;
        }
      }
      assert(false);
    }
  }
}

