#define pow2(n) (1<<n)
#define rev(x,n) (x) ^= pow2(n);

int n, s, t, N;
vector<int> ans;

int popcount(int x) {
    int res = 0;
    while (x > 0) res+=x&1, x>>=1;
    return res;
}

int diffbit(int a, int b) {
    int res = 0;
    while ((a&pow2(res)) == (b&pow2(res))) res++;
    return res;
}

void solve(int l, int r, int a, int b, vector<int> used) {
    if (l == r-1) return;
    int mid = (l + r) / 2;

    int db = diffbit(a, b);
    rng(i,l,r) ans[i] = a;
    rng(i,mid,r) rev(ans[i], db);
    used[db] = 1;

    rep(i,n) if (!used[i]) {
        rev(ans[mid-1], i);
        rev(ans[mid], i);
        break;
    }
    solve(l, mid, a, ans[mid-1], used);
    solve(mid, r, ans[mid], b, used);
}

