}

#include <bits/stdc++.h>

using namespace std;

vector<int> solve(int mask, int a, int b) {
	assert(a != b);
	if (__builtin_popcount(mask) == 1) {
		return {a, b};
	}

	int bit = 0;
	while (((mask >> bit) & 1) == 0 || ((a >> bit) & 1) == ((b >> bit) & 1)) {
		bit++;
	}

	mask ^= (1 << bit);
	int sub = mask, target = __builtin_popcount(a & mask) % 2;
	while (__builtin_popcount(sub) % 2 == target || sub == (a & mask) || sub == (b & mask)) {
		sub = (sub - 1) & mask;
	}

	auto L = solve(mask, a, (a & ~mask) | sub);
	auto R = solve(mask, (b & ~mask) | sub, b);

	for (int x : R) L.push_back(x);
	return L;
}

