	int n, a, b;
	ignore = scanf("%d %d %d", &n, &a, &b);
	if (__builtin_popcount(a) % 2 == __builtin_popcount(b) % 2) {
		printf("%s\n", "NO");
		return 0;
	}

	auto ans = solve((1 << n) - 1, a, b);

	printf("%s\n", "YES");
	for (int x : ans) printf("%d ", x);
	printf("\n");

	return 0;
}

