	return n == 0;
}

vector<int> gray(int n) {
	vector<int> res(1 << n);
	for (int i = 0; i < 1 << n; i++) {
		res[i] = i ^ (i >> 1);
	}
	auto it = find(res.begin(), res.end(), 0);
	rotate(res.begin(), it, res.end());
	return res;
}

int popcnt(int x) {
	int res = 0;
	while (x > 0) {
		res++;
		x &= x - 1;
	}
	return res;
}

int rev(int x, int n) {
	int res = 0;
	for (int i = 0; i < n; i++) {
		res ^= (x >> i & 1) << (n - 1 - i);
	}
	return res;
}

vector<int> tomato(int n) {
	if (n == 1) return {0, 1};
	vector<int> g = gray(n - 2);
	vector<int> res;
	int x = 1 << n - 2;
	int y = 1 << n - 1;
	for (int i = 0; i < g.size(); i++) res.push_back(g[i]);
	for (int i = g.size() - 1; i >= 0; i--) res.push_back(g[i] ^ x);
	res.push_back(x ^ y);
	for (int i = 0; i < g.size(); i++) res.push_back(g[i] ^ y);
	auto f = tomato(n - 2);
	for (int i = 1; i < f.size(); i++) {
		res.push_back(rev(f[i], n - 2) ^ x ^ y);
	}
	return res;
}

