void make(int a, int b, int n, VI &ans){
    if (n == 1){
        if (a == 0){
            ans.push_back(0);
            ans.push_back(1);
        }else{
            ans.push_back(1);
            ans.push_back(0);
        }
        return;
    }
    if (a != 0){
        make(0, a ^ b, n, ans);
        REP(i,1<<n) ans[i] ^= a;
        return;
    }
    if (b & (1 << (n - 1))){
        VI tmp;
        make(0, 1, n - 1, ans);
        make(1, b - (1 << (n - 1)), n - 1, tmp);
        for (int x : tmp) ans.push_back(x + (1 << (n - 1)));
    }else{
        VI v1, v2;
        make(0, b, n - 1, v1);
        int p = v1[(1 << (n - 1)) - 2];
        make(p, b, n - 1, v2);
        REP(i,(1<<(n-1))-1) ans.push_back(v1[i]);
        for (int x : v2) ans.push_back(x + (1 << (n - 1)));
        ans.push_back(v1.back());
    }
}

