int pop_count(int x) {
    int ret = 0;
    while(x > 0) ret += x & 1, x >>= 1;
    return ret;
}

bool vis[200000];

int deg(int x) {
    int ret = 0;
    for(int i = 0 ; i < n ; i++) {
        if(!vis[x^(1<<i)]) ret++;
    }
    return ret;
}

