                for (int j = 0 ; j < n ; j++) {
                    int t = tmp ^ (1<<j);
                    if (t != target && !vis[t]) {
                        if (pick == -1) pick = t;
                        else if (deg(t ^ target) > deg(pick ^ target)) {
                            pick = t;
                        }
                    }
                }
                if (pick == -1) {
                    ans[i] = target;
                    break;
                }
                ans[i] = pick;
            }
            vis[ans[i]] = true;
        }

