vector<int> getAns(int lv, int a, int b) {
	if (lv == 0) {
		vector<int> v;
		v.push_back(a), v.push_back(b);
		return v;
	}
	if (((a >> lv) & 1) != ((b >> lv) & 1)) {
		int c = b ^ (1 << (lv - 1));
		vector<int> fr = getAns(lv - 1, a, c ^ (1 << lv)), sd = getAns(lv - 1, c, b);
		for (auto x : sd)
			fr.push_back(x);
		return fr;	
