int del_bit(int x, int p) {
	int y = 1 << p;
	return x / (y << 1) * y + x % y;
}

int add_bit(int x, int p, int b) {
	int y = 1 << p;
	return x / y * (y << 1) + x % y + y * b;
}

vi solve(int a, int b, int k) {
	int cnt = 0;
	Loop(i, k) {
		if (a & (1 << i)) cnt ^= 1;
		if (b & (1 << i)) cnt ^= 1;
	}
	if (cnt == 0) failed();
	if (k == 1) return { a, b };
	else {
		int pos;
		int bta, btb;
		Loop(i, k) {
			if ((a & (1 << i)) != (b & (1 << i))) {
				pos = i;
				bta = (a & (1 << i)) ? 1 : 0;
				btb = 1 - bta;
				break;
			}
		}
		int xb, xa;
		Loop(i, k) {
			if (i == pos) continue;
			int x = a ^ (1 << i);
			if ((x ^ (1 << pos)) != b) {
				xb = x;
				xa = x ^ (1 << pos);
				break;
			}
		}
		vi va = solve(del_bit(a, pos), del_bit(xb, pos), k - 1);
		vi vb = solve(del_bit(xa, pos), del_bit(b, pos), k - 1);
		vi ret(1 << k);
		Loop(i, 1 << (k - 1)) {
			ret[i] = add_bit(va[i], pos, bta);
			ret[i + (1 << (k - 1))] = add_bit(vb[i], pos, btb);
		}
		return ret;
	}
}

