    }
    if (n == 1) {
        cout << "YES" << endl;
        cout << a << " " << b << endl;
        return 0;
    }
    bool swapflag = false;
    deque<int> seq = {0, 1};
    int ai, bi;
    if (a == 0) ai = 0;
    if (a == 1) ai = 1;
    if (b == 0) bi = 0;
    if (b == 1) bi = 1;
    for (int i = 1; i < n; i++) {
        for (int j = seq.size()-1; j >= 0; j--) {
            seq.emplace_back((1 << i) + seq[j]);
            if (seq.back() == a) ai = seq.size()-1;
            if (seq.back() == b) bi = seq.size()-1;
        }
    }
    deque<int> ans;
    if (ai > bi) {
        swap(a, b);
        swap(ai, bi);
        swapflag = true;
    }
    for (int i = ai; i >= 0; i--) {
        ans.emplace_back(seq[i]);
    }
    ai++;
    int maxd = 20;
    for (int i = seq.size()-1; i >= bi; i--) {
        while (seq[i] < (1 << maxd)) maxd--;
        if (ai < bi && (seq[ai] | 1 << maxd) == seq[i]) {
            ans.emplace_back(seq[i]);
            ans.emplace_back(seq[ai]);
            ans.emplace_back(seq[ai+1]);
            ans.emplace_back(seq[i-1]);
            ai += 2; i--;
        } else {
            ans.emplace_back(seq[i]);
        }
    }
    if (swapflag) reverse(ans.begin(), ans.end());
    for (int i = 1; i < ans.size(); i++) {
        bitset<20> bit;
        bit = ans[i] ^ ans[i-1];
        assert(bit.count() == 1);
