    ans[(1 << n) - 1] = B;
    for(int i = 1; i < (1 << n) - 1; i++)
    {
        ans[i] = v[seq[i]].back();
        v[seq[i]].pop_back();
    }

    if(swapped)
        reverse(ans.begin(), ans.end());

    cout << "YES" << endl;
    for(int i = 0; i < (1 << n); i++)
        cout << ans[i] << " ";
    cout << endl;



    return 0;
}

