vector<int> solve(int from, int to, int d){
	if(d == 1){return {from, to};}
	if((from&1) == (to&1)){
		auto prv = solve(from>>1, to>>1, d - 1);
		vector<int> res;
		int y = (from&1) ? 1 : 0;
		I(x, prv){
			x <<= 1;
			res.pb(x^y);
			res.pb(x^y^1);
			y ^= 1;
		}
		ret res;
	}
	int nf = from>>1;
	int nt = to>>1;
	auto le = solve(nf, nf^1, d - 1);
	auto ri = solve(nf^1, nt, d - 1);
	int lastbit = from&1;
	for(auto&x : le)
		x = (x<<1)^lastbit;
	for(auto x : ri){
		x = (x<<1)^1^lastbit;
		le.pb(x);
	}
	ret le;
}

