vector<int> solve(int n, int a, int b)
{
	assert(__builtin_popcount(a)%2!=__builtin_popcount(b)%2);

	vector<int> ret;
	if (n==1)
	{
		ret.PB(a);
		ret.PB(b);
		return ret;
	}
	int c = -1, t = -1;
	for (int i=0; i<n; i++)
	{
		if (((a>>i)&1)!=((b>>i)&1))
		{
			if (c==-1)
			{
				c = i;
				t = ((a>>i)&1);
			}
		}
	}
	assert(c!=-1&&t>=0&&t<=1);
	vector<int> v0 = solve(n-1, rd(a, c), rd(a, c)^1);
	vector<int> v1 = solve(n-1, rd(a, c)^1, rd(b, c));
	for (auto x : v0) ret.PB(ad(x, c, t));
	for (auto x : v1) ret.PB(ad(x, c, t^1));
	return ret;
}
