  auto f
      = [](int x, int i) { return (x >> (i + 1)) * (1 << i) ^ (x % (1 << i)); };
  auto g = [](int x, int i, bool b) {
    return (x >> (i)) * (1 << (i + 1)) ^ (b << i) ^ (x % (1 << i));
  };
  function<vector<int>(int, int, int)> rec = [&](int n, int a, int b) {
    if (n == 1) return vector<int>({a, b});
    vector<int> ret(1 << n);
    for (int i = 0; i < n; i++) {
      if (((a ^ b) >> i) & 1) {
        int aa = f(a, i);
        int bb = f(b, i);
        auto l = rec(n - 1, aa, aa ^ 1);
        auto r = rec(n - 1, aa ^ 1, bb);
        for (int j = 0; j < (1 << (n - 1)); j++) {
          ret[j] = g(l[j], i, (a >> i) & 1);
          ret[j + (1 << (n - 1))] = g(r[j], i, (b >> i) & 1);
        }
      }
    }
    return ret;
  };
  auto ans = rec(N, A, B);
  cout << "YES" << '\n';
