void solve(int l, int r) {
  if (r - l == 2) return;
  int m = (l + r) / 2;
  rep(i, n) {
    if (v[m][i] != -1) continue;
    if (v[l][i] != v[r - 1][i]) {
      FOR(j, l, m) v[j][i] = v[l][i];
      FOR(j, m, r) v[j][i] = v[r - 1][i];
      break;
    }
  }
  rep(i, n) {
    if (v[m - 1][i] == -1) {
      rep(j, n) {
        if (v[m - 1][j] != -1) continue;
        if (j == i) v[m - 1][j] = v[l][j] ^ 1;
        else v[m - 1][j] = v[l][j];
        v[m][j] = v[m - 1][j];
      }
      break;
    }
  }
  solve(l, m);
  solve(m, r);
}

