    if(__builtin_popcount(A)%2==__builtin_popcount(B)){
        cout << "NO" << endl;
        return 0;
    }
    vector<int> ans = dfs(A,B,N);
    cout << "YES" << endl;
    for(auto x:ans) cout << x << " ";
    cout << endl;
}

