int sol[1 << MAXN], n;

void solve(int l, int r, int a, int b) {
    if(r - l == 1) {
        sol[l] = (a & 1);
        sol[r] = (b & 1);
        return ;
    }
    int mid = (l + r) / 2;
    for(int bit = 0; bit < n; bit++) {
        if((a & (1 << bit)) != (b & (1 << bit))) {
            int cura = ((a >> (bit + 1)) << bit) + (a & ((1 << bit) - 1));
            int curb = ((b >> (bit + 1)) << bit) + (b & ((1 << bit) - 1));
            int cur = (cura ^ 1);
            solve(l, mid, cura, cur);
            solve(mid + 1, r, cur, curb);
            int val = 0;
            if(a & (1 << bit)) {
                val = 1;
            }
            for(int i = l; i <= mid; i++) {
                sol[i] = (sol[i] & ((1 << bit) - 1)) + ((sol[i] >> bit) << (bit + 1)) + val * (1 << bit);
            }
            for(int i = mid + 1; i <= r; i++) {
                sol[i] = (sol[i] & ((1 << bit) - 1)) + ((sol[i] >> bit) << (bit + 1)) + (1 - val) * (1 << bit);
            }
            return ;
        }
    }
}

