int n;
vi solve(int nn,int l,int r,int bak){
	//printf("%d  %d %d %d\n",nn,l,r,bak);
	if(nn==1)return {l&bak,r&bak};
	vi L,R,res;
	REP(i,n)if((bak>>i&1)&&((l>>i&1)^(r>>i&1))){
		int vl=(l>>i&1),vr=(r>>i&1),fr=0;
		REP(j,n)if((bak>>j&1)&&(j!=i))fr=1<<j;
		L=solve(nn-1,l,l^fr,bak^(1<<i));
		R=solve(nn-1,l^fr,r,bak^(1<<i));
		res.resize(1<<nn);
		int semi=1<<(nn-1);
		REP(j,semi)
			res[j]=L[j]^(vl<<i);
		REP(j,semi)
			res[j+semi]=R[j]^(vr<<i);
	}
	return res;
}

