vector<vector<int> > build_same(int n){
	if(n==0)return {{}};
	auto v = build_same(n-1);
	auto v2 = v;
	reverse(ALL(v2));
	vector<vector<int> > ret;
	for(auto vi:v){
		ret.push_back(vi);
		ret.back().push_back(0);
	}
	for(auto vi:v2){
		ret.push_back(vi);
		ret.back().push_back(1);
	}
	return ret;
}

