#include <bits/stdc++.h>

using namespace std;

int n, a, b;

void solve(int mask, int a, int b, vector<int>& x) {
  assert(__builtin_parity(a ^ b) == 1);
  if (__builtin_popcount(mask) == 1) {
    x.push_back(a);
    x.push_back(b);
    return;
  }
  int d = (a ^ b) & mask;
  vector<int> ones;
  vector<int> zeros;
  for (int i = 0; i < n; i++) {
    if (mask & 1 << i) {
      if (d & 1 << i) {
        ones.push_back(1 << i);
      } else {
        zeros.push_back(1 << i);
      }
    }
  }
  int u = ones[0];
  int v = (ones.size() < 2 ? zeros[0] : ones[1]);
  solve(mask ^ u, a, b ^ u ^ v, x);
  solve(mask ^ u, b ^ v, b, x);
}

