std::vector<int> find(int a, int b, int n) {
	if (__builtin_popcountll(a) % 2 == __builtin_popcount(b) % 2) return {-1};
	if (n == 1) {
		if (a == 1) return {1, 0}; 
		else return {0, 1};
	}
	// print(a, b);
	int in = 0;
	for (int i = 0; i < n; ++i) {
		if ((a ^ b) & (1 << i)) {
			in = i;
			break;
		}
	}
	int aprime = (a & ((1 << in) - 1)) | ((a & (~((1 << (in + 1)) - 1))) >> 1);
	int bprime = (b & ((1 << in) - 1)) | ((b & (~((1 << (in + 1)) - 1))) >> 1);
	int ai = a & (1 << in);
	int bi = b & (1 << in);
	int c = aprime ^ 1;
	auto v1 = find(aprime, c, n - 1);
	auto v2 = find(c, bprime, n - 1);
	// print(aprime, c, v1);
	// print(c, bprime, v2);
	std::vector<int> v;
	for (int i = 0; i < (1 << (n - 1)); ++i) {
		int x = v1[i];
		v.pb((x & ((1 << in) - 1)) | ai | ((x & (~((1 << in) - 1))) << 1));
	}
	for (int i = 0; i < (1 << (n - 1)); ++i) {
		int x = v2[i];
		v.pb((x & ((1 << in) - 1)) | bi | ((x & (~((1 << in) - 1))) << 1));
	}
	// print(v);
	return v;
}

