int rdist(int a, int b) {
  int ret = 0;
  for (int i = 0; i < n; i++) {
    if (a % 2 != b % 2) ret++;
    a /= 2;
    b /= 2;
  }
  return ret;
}

vector<bool> getbit(int a) {
  vector<bool> ret(n, false);
  for (int i = 0; i < n; i++) {
    ret[i] = a % 2;
    a /= 2;
  }
  return ret;
}

int getnum(vector<bool> v) {
  int p = 1, ret = 0;
  for (int i = 0; i < n; i++) {
    ret += p * v[i];
    p *= 2;
  }
  return ret;
}

