inline void solve(int k, int l, int r){
	if(k==1){
		printf("%d %d ", l, r);
		return;
	}
	for(int i=0; i<n; ++i)
		if((l&(1<<i))^(r&(1<<i))){
			x[i]=1; int mid=l;
