    vector <int> adiff({diff.back()});
    diff.pop_back();

    gen(nmask, adiff);
    int sz = (int) v.size();

    gen(nmask, diff);
    for (int i = sz; i < (int) v.size(); i++)
            v[i] ^= (1 << adiff[0]) ^ (1 << id);

}

