void solve(vector<int>& v, int i)
{
    vector<int> x(2);
    x[0] = 0;
    x[1] = 1 << i;

    int n = v.size();
    vector<int> ans(2*n);
    for(int i=0; i<2*n; ++i){
        ans[i] = v[i/2];
        ans[i] |= x[(i+1)/2%2];
    }
    v = move(ans);
}

void solve(vector<int>& v, int i, int j)
{
    vector<int> x(4);
    x[0] = 0;
    x[1] = 1 << i;
    x[2] = (1 << i) ^ (1 << j);
    x[3] = 1 << j;

    int n = v.size();
    vector<int> ans(4*n);
    for(int i=0; i<4*n; ++i){
        ans[i] = v[i/4];
        if(i / 4 % 2 == 0)
            ans[i] |= x[i%4];
        else
            ans[i] |= x[3-i%4];
    }
    swap(ans[4*n-1], ans[4*n-3]);
    v = move(ans);
}

int main()
{
    int n, a, b;
    cin >> n >> a >> b;
    b ^= a;
    if(bitset<32>(b).count() % 2 == 0){
        cout << "NO" << endl;
        return 0;
    }

    vector<int> diff, same;
    for(int i=0; i<n; ++i){
        if(b & (1 << i))
            diff.push_back(i);
        else
            same.push_back(i);
    }

    vector<int> ans(1, 0);
    solve(ans, diff[0]);
    for(unsigned i=1; i<diff.size(); i+=2)
        solve(ans, diff[i], diff[i+1]);
    for(unsigned i=0; i<same.size(); ++i)
        solve(ans, same[i]);

    for(int i=0; i<(1<<n); ++i)
        ans[i] ^= a;

    cout << "YES" << endl << ans[0];
    for(int i=1; i<(1<<n); ++i)
        cout << ' ' << ans[i];
    cout << endl;

    return 0;
}

