void zh(int x, int y, int n) {
	p[0] = q[0] = 0;
	fo(j, 0, n - 1) if(x >> j & 1) p[++ p[0]] = j;
	fo(j, 0, n - 1) if(x >> j & 1) q[++ q[0]] = j;
	ff(i, 0, 1 << n) {
		int s = i;
		fo(j, 1, p[0]) if(i >> p[j] & 1) s += (1 << q[j]) - (1 << p[j]);
		z[i] = s;
	}
}

