int n,A,B;

vector<int> solve(int A, int B, int n){
    // dbg(A,B,n);
    if (n==1){
        vector<int> ans;
        ans.push_back(A);
        ans.push_back(B);
        // dbg(ans);
        return ans;
    }
    for (int i=0;i<n;i++){
        if ((A & (1<<i)) != (B & (1<<i))){
            int msk = (1<<n) - (1<<(i+1));
            // dbg(msk,i);
            int A2 = ((A & msk)>>1) + (A & ((1<<i) - 1));
            int B2 = ((B & msk)>>1) + (B & ((1<<i) - 1));
            int C = (A2 ^ 1);
            // dbg(A2,B2,C);
            vector<int> ans1 = solve(A2, C, n-1);
            vector<int> ans2 = solve(C, B2, n-1);
            vector<int> ans;
            for (auto it : ans1){
                if (A & (1<<i)) ans.push_back(((it << 1) & msk) | (1<<i) + (it & ((1<<i) - 1)));
                else ans.push_back(((it << 1) & msk) + (it & ((1<<i) - 1)));
            }

            for (auto it : ans2){
                if (B & (1<<i)) ans.push_back(((it << 1) & msk) | (1<<i) + (it & ((1<<i) - 1)));
                else ans.push_back(((it << 1) & msk) + (it & ((1<<i) - 1)));
            }
            // dbg(ans);
            return ans;
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin >> n >> A >> B;
    if (__builtin_popcount(A) % 2 == __builtin_popcount(B) % 2){
        cout << "NO\n";
    }
    else{
        vector<int> ans = solve(A,B,n);
        cout << "YES\n";
        for (auto it : ans) cout << it << ' ';
        cout << '\n'; 
    }

    return 0;
}

