using namespace std;

int n,A,B,pos;
int v[1 << 17];
int ans[1 << 17];
int tmp[1 << 17];

int popcount(int v)
{
	return v ? popcount(v - (v & -v)) + 1 : 0;
}

void solve(int l)
{
	if (l == 0)
		return;
	solve(l - 1);
	for (int i = 0;i < (1 << (l - 1));i++)
	{
		tmp[i << 1] = v[i] | ((i & 1) << (l - 1));
		tmp[i << 1 | 1] = v[i] | ((~i & 1) << (l - 1));
	}
	for (int i = 0;i < (1 << l);i++)
		v[i] = tmp[i];
}

int main()
{
	ios::sync_with_stdio(0);
	cin >> n >> A >> B;
	B ^= A;
	if (~popcount(B) & 1)
	{
		cout << "NO" << endl;
		return 0;
	}
	solve(n);
	for (int i = 0;i < (1 << n);i++)
		if (v[i] == B)
		{
			pos = i;
			break;
		}
	for (int i = 0;i < (1 << n);i++)
	{
		if (i < pos)
		{
			ans[i] = v[i];
			continue;
		}
		int t = (i - pos) / 2 + 1;
		if (t & 1)
			ans[(1 << n) - 1 - (t >> 1 << 1) - (~i & 1)] = v[i];
		else
			ans[i - t] = v[i];
	}
	cout << "YES" << endl;
	for (int i = 0;i < (1 << n);i++)
		cout << (ans[i] ^ A) << ' ';
	cout << endl;
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

vector <int> Solve(int n, int u, int v)
{
    vector <int> res;
    if (n == 0) return res = {u, v};
    int Z = (1<<n)&u, ZZ = Z^(1<<n);
    if ((u>>n) == (v>>n)) {
        vector <int> vec = Solve(n-1, u^Z, v^Z);
        vector <int> _vec = Solve(n-1, vec[0], vec[1]);
        res.push_back(vec[0]^Z);
        for (int i : _vec) res.push_back(i^ZZ);
        for (int i = 1; i < vec.size(); i++) res.push_back(vec[i]^Z);
    }
    else {
        vector <int> vec = Solve(n-1, u^Z, __builtin_popcount(u^Z)&1^1);
        vector <int> _vec = Solve(n-1, __builtin_popcount(v^ZZ)&1^1, v^ZZ);
        for (int i : vec) res.push_back(i^Z);
        for (int i : _vec) res.push_back(i^ZZ);
    }
    return res;
}

int main()
{
    int n, a, b; cin >> n >> a >> b;
    if (__builtin_popcount(a) == __builtin_popcount(b)) return cout << "NO\n", 0;
    cout << "YES\n";
    vector <int> ans = Solve(n-1, a, b);
    for (int i : ans) cout << i << " ";
    cout << "\n";

    return 0;
}

