#include <bits/stdc++.h>
using namespace std;

int bitcount(int x) {
    int ans = 0;
    while (x > 0) {
        ans += x & 1;
        x >>= 1;
    }
    return ans;
}

int bit(int x, int pos) {
    return (x >> pos) & 1;
}

// Insert bit i to position pos of number x
int insertBit(int x, int pos, int i) {
    int y = x & ((1 << pos) - 1);
    x ^= y;
    x <<= 1;
    x ^= y;
    if (i) x |= 1 << pos;
    return x;
}

// Delete pos-th bit of number x
int deleteBit(int x, int pos) {
    int y = x & ((1 << pos) - 1);
    x ^= y;
    x &= ~(1 << pos);
    x >>= 1;
    x ^= y;
    return x;
}

// find the position of the bit(0->n-1) that a and b is the same
int findp(int n, int a, int b) {
    for (int i = 0; i < n; i++) {
        if (bit(a, i) == bit(b, i))
            return i;
    }
    return -1;
}

vector<int> F(int n, int a, int b) {
    if (n == 1) {
        return vector<int> {a, b};
    }

    int p = findp(n, a, b);
    int val = bit(a, p);

    int x = deleteBit(a, p);
    int y = deleteBit(b, p);

    vector<int> v = F(n - 1, x, y);
    vector<int> res;
    for (auto i : v) {
        res.push_back(insertBit(i, p, val));
        val ^= 1;
        res.push_back(insertBit(i, p, val));
    }
    return res;
}

int main() {
    int n, a, b;
    cin >> n >> a >> b;

    if (bitcount(a) == bitcount(b)) {
        cout << "NO\n";
        return 0;
    }

    cout << "YES\n";

    vector<int> ans = F(n, a, b);
    for (auto i : ans) {
        cout << i << ' ';
    }
    cout << endl;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

// x の下から key 番目 (0-indexed) の bit を消す
int erase_bit(int x, int key) {
    int mask = pow(2, key);
    int low = x & (mask-1);
    x = (x / (mask*2)) * mask;
    return x + low;
}

// x の下から key 番目 (0-indexed) に bit を挿入
int insert_bit(int x, int key, int bit) {
    int mask = pow(2, key);
    int low = x & (mask-1);
    x = (x - low) * 2 + bit * mask;
    return x + low;
}

vector<int> solve(int a, int b, int n) {
    if(n == 1)
        return {a, b};
    int d = a ^ b;
    int key = __builtin_ctz(d); // このbitを消す
    int a_key = 0;
    int b_key = 0;
    if(a & (1 << key)) a_key = 1;
    if(b & (1 << key)) b_key = 1;
    // a_key != b_key
    a = erase_bit(a, key);
    b = erase_bit(b, key);
    int c = a ^ 1;
    auto ac = solve(a, c, n-1);
    for (int x: ac ) {
        x = insert_bit(x, key, a_key);
    }
    auto cb = solve(c, b, n-1);
    for (int x: cb ) {
        x = insert_bit(x, key, b_key);
        ac.push_back(x);
    }
    return ac;
}

int main() {
    int N, A, B;
    cin >> N >> A >> B;

    if (! __builtin_parity(A^B)) {
        cout << " ";
        return 0;
    }
    cout << "YES" << "\n";
    auto ans = solve(A, B, N);
    for (int x: ans ) {
        cout << x << " ";
    }
    return 0;
}

