int main() {
    int N;
    scanf(" %d", &N);

    char temp;
    for (int i=0; i<N; i++) {
        scanf(" %c", &temp);
        freq[temp - 'a']++;
    }

    for (int i = 0; i < DIGITS; i++) {
        for (int j = 0; j < DIGITS - 1; j++) {
            if (freq[j] == 0) {
                swap(freq[j], freq[j + 1]);
            }
        }
    }

    int different = 0;
    for (int i = 0; i < DIGITS; i++) {
        if (freq[i] != 0) {
            different++;
        }
    }

    long long res = 0;
    register int bitmask = 1;
    register int lastbitmask = 1 << different;

    for (; bitmask < lastbitmask; bitmask++) {
        long long acum = 1;

        for (int dig = 0; dig < different; dig++) {
            if ((bitmask & (1 << dig)) && freq[dig] > 0) {
                acum = (acum * freq[dig]) % MOD;
                #ifdef DEBUG
                    printf("freq[%d] = %d\n", dig, freq[dig]);
                #endif
                while (acum < 0LL) {
                    acum += MOD;
                }
            }
        }

        res = (res + acum) % MOD;
    }

    cout << res << endl;

    return 0;
}

