    }

    int cA = BitAlgo::popcount32(A);
    int cB = BitAlgo::popcount32(B);

    int cX, cY;
    int ptr = -1;
    bool swp = false;
    repeat(i, N - 1) {
        cX = BitAlgo::popcount32(code[i]);
        cY = BitAlgo::popcount32(code[i + 1]);
        if (cA == cX && cB == cY) { // 個数変化が同じ場所を探す．このグレイコードの値をX,Yとする．
            ptr = i;
            break;
        }
        if (cB == cX && cA == cY) {
            swp = true;
            swap(cA, cB);
            swap(A, B);
            ptr = i;
            break;
        }
    }
    int X = code[ptr];
    int Y = code[ptr+1];

    // あり得ないが念の為
    if (ptr == -1) abort();

    // 並び替え
    // 出力する際にperm[i]桁を見に行く
    int perm[20];
    iota(perm, perm + 20, 0);

    // AB のビットが違う位置
    int iAB = BitAlgo::ffs32(A ^ B) - 1;

    // XY のビットが違う位置
    int iXY = BitAlgo::ffs32(X ^ Y) - 1;

    // が言えるはず
    perm[iAB] = iXY;

