    // debug(iXY);
    // debug(iAB);
    {
        int a = A;
        repeat(i, 20) {
            if (iAB != i) {
                if (a & 1)
                    perm[i] = vX1.front(), vX1.pop();
                else
                    perm[i] = vX0.front(), vX0.pop();
            }
            a >>= 1;
        }
    }

    // RUN
    // debuga(perm, N);

    printer << "YES\n";
    if (swp) {
        repeat(_i, N) {
            int i = (ptr + _i + 1) % N;
            int v = 0;
