std::vector<int> digitcount(int a){ // Count the number of '1's
	std::vector<int> result;
	for(int i=0; i<32; i++) if((a&(1<<i)) != 0) result.push_back(i);
	return result;
}
int changebit(int x, int digit){ // Change x at bit digit
	return x ^ (1<<digit);
}

std::vector<int> changebits;

std::vector<bool> construct_changebits(int upbound, int changing){ // upbound = 3 -> 0 1 0 2 0 1 0 3 // but last wanted is preferred
// Basic: '0' * n -> '1' + '0' * (n-1) when changing == 1

	if(upbound+1 < changing) throw "ERROR";
	else if(upbound == 0){ // Only one change
		if(changing != 1){
			printf("Error occured. changing(given %d) is not 1 but upbound is zero\n", changing);
			throw "ERROR";
		}
		changebits[0] = 0;
		return {true};
	}
	else{
		// Construct previous
		std::vector<bool> changed = construct_changebits(upbound-1, changing>1 ? changing-2 : 1);

		// Find unchanged
		while(changed.size() < upbound) changed.push_back(false);
		std::vector<int> evens;
		for(int i=0; i<upbound; i++) if(!changed[i]) evens.push_back(i);

		// Swap upbound <-> evens[0]
		int limit = (1<<(upbound-1));
		if(changing > 1){
			for(int i=0; i<limit; i++) changebits[limit+i] = (changebits[i] == evens[0] ? upbound : changebits[i]);
			changebits[2*limit-1] = evens[0];
		}
		else{
			for(int i=0; i<limit; i++) changebits[limit+i] = changebits[i];
			changebits[2*limit-1] = evens[0];
		}

	}
}

void append(std::vector<int> &origin, const std::vector<int> &add){
	for(auto it: add) origin.push_back(it);
}

std::vector<int> newconstruct(int upbound, int changing){

	if(upbound+1 < changing){
		printf("Too large changing = %d for upbound = %d\n", changing, upbound);
		throw "ERROR";
	}
	else if(upbound == 2 && changing == 3) return {0, 1, 0, 2, 1, 0, 1};
	else if(upbound == 0){
		if(changing == 1) return {0};
		else{
			printf("upbound = 0, changing = %d ??\n", changing);
			throw "ERROR";
		}
	}
	else if(changing == 1){
		std::vector<int> result, half = newconstruct(upbound-1, 1);
		append(result, half);
		result.push_back(upbound);
		append(result, half);
		return result;
	}
	else{
		std::vector<int> quarter1 = newconstruct(upbound-2, changing-2);
		std::vector<int> pure = newconstruct(upbound-2, 1);
		std::vector<int> result;

		append(result, quarter1);
		result.push_back(upbound-1);
		append(result, pure);
		result.push_back(upbound);

		std::vector<int> backhalf;
		append(backhalf, pure);
		backhalf.push_back(upbound-1);
		append(backhalf, pure);
		for(int i=0; i<backhalf.size(); i++){
			if(backhalf[i] == upbound-1) backhalf[i] = upbound-2;
			else if(backhalf[i] == upbound-2) backhalf[i] = upbound-1;
		}
		append(result, backhalf);
		return result;
	}

}

