vi solve(int n, int x) {
    vi v1, v2;
    int f = -1;
    REP(i, 1 << n) {
        int y = i ^ (i >> 1);
        if (f != -1 && i % 2 == 1) f = !f;
        if (x == y) {
            f = 1;
        }
        (f != 1 ? v1 : v2).push_back(y);
    }
    RREP(i, v2.size()) v1.push_back(v2[i]);
    return v1;
}

void verify(int a, int b, const vi &ans) {
    if (a != ans[0]) {
        cerr << "first not correct" << endl;
        assert(false);
    }
    if (b != ans.back()) {
        cerr << "last not correct" << endl;
        assert(false);
    }
    set<int> s(ans.begin(), ans.end());
    if (s.size() != ans.size()) {
        cerr << "not distinct" << endl;
        assert(false);
    }

    REP(i, ans.size() - 1) {
        if (__builtin_popcount(ans[i] ^ ans[i + 1]) != 1) {
            cerr << "not grey "<<  i << ": " << ans[i] << ", " << ans[i + 1] << endl;
            assert(false);
        }
    }
}

