struct Problem {

	vector<UL> Solve2(UL N, UL B) {
		if (N == 1) {
			if ((B & 1) == 0) return {};
			else return { 0, 1 };
		}
		vector<UL> ans;
		if ((B & (1 << (N - 1))) == 0) {
			vector<UL> buf1 = Solve2(N - 1, B);
			UL L = buf1.size(); if (!L) return {};
			vector<UL> buf2 = Solve2(N - 1, buf1[1]);
			ans.push_back(buf1[0]);
			rep(i, buf2.size()) ans.push_back(buf2[i] ^ (1 << (N - 1)));
			rep(i, L - 1) ans.push_back(buf1[i + 1]);
		}
		else {
			vector<UL> buf1 = Solve2(N - 1, 1);
			UL f = buf1[1];
			vector<UL> buf2 = Solve2(N - 1, B ^ (1 << (N - 1)) ^ 1);
			UL L = buf2.size(); if (!L) return {};
			rep(i, L) buf2[i] |= (1 << (N - 1));
			rep(i, L) buf2[i] ^= 1;
			rep(i, L) buf1.push_back(buf2[i]);
			ans = move(buf1);
		}
		return move(ans);
	}

	void Solve() {
		UL N, A, B; cin >> N >> A >> B;
