        for (int high : part0) res.push_back(high << cnt1 | low);
        reverse(part0.begin(), part0.end()); 
    }
    for (int i = 0; i < (int)res.size() - 1; i++) assert(__builtin_popcount(res[i] ^ res[i + 1]) == 1);
    assert(*res.begin() == 0 && *res.rbegin() == (1 << cnt1) - 1);
    return res;
}
