vector<int> solve(int n, int a, int b) {
	if (n == 1){
		return {a, b};
	}
	assert(__builtin_popcount(a) != __builtin_popcount(b));
	int x;
	for (int i=0; i<n; i++) {
		if ((a & (1<<i)) != (b & (1<<i))) {
			x = i;
			break;
		}
	}
	int a1=0, b1=0;
	for (int i=0; i<x; i++) {
		a1 |= a & (1<<i);
		b1 |= b & (1<<i);
	}
	for (int i=x+1; i<n; i++) {
		a1 |= ((a & (1<<i))>>1);
		b1 |= ((b & (1<<i))>>1);
	}
	int c = a1 ^ 1;
	vector<int> res1 = solve(n-1, a1, c);
	vector<int> res2 = solve(n-1, c, b1);
	vector<int> res;
	for (int y : res1) {
		int cur = a & (1<<x);
		for (int i=0; i<x; i++) {
			cur |= y & (1<<i);
		}
		for (int i=x; i<n-1; i++) {
			cur |= ((y & (1<<i))<<1);
		}
		res.pb(cur);
	}
	for (int y : res2) {
		int cur = b & (1<<x);
		for (int i=0; i<x; i++) {
			cur |= y & (1<<i);
		}
		for (int i=x; i<n-1; i++) {
			cur |= ((y & (1<<i))<<1);
		}
		res.pb(cur);
	}
	return res;
}

