void solve(int l, int r, int x, int y, int f) {
	if (l + 1 == r) {
		ans[l] = x;
		ans[r] = y;
		return;
	}
	int b = bit((x ^ y));
	int X = x;
	int Y = y;
	if ((x >> b) & 1) X ^= (1 << b);
	if ((y >> b) & 1) Y ^= (1 << b);
	assert(__builtin_popcount(X) % 2 == __builtin_popcount(Y) % 2);
	int m = (l + r) / 2;
	int q = -1;
	f ^= (1 << b);
	rep(i, 0, n - 1)
		if (!((f >> i) & 1)) {
			q = i;
			break;
		}
	int z = (X ^ (1 << q));
	solve(l, m, X, z, f);
	solve(m + 1, r, z, Y, f);
	if ((x >> b) & 1) rep(i, l, m) ans[i] ^= (1 << b);
	if ((y >> b) & 1) rep(i, m + 1, r) ans[i] ^= (1 << b);
}

