    vector<i64> js(N);
    rep(i,0,N){
        js[i]=i;
    }

    i64 cnt=0;

    vector<vector<i64>> fail(N,vector<i64>(1<<N));

    function<bool(i64,i64,i64)> dfs=[&](i64 i,i64 prev,i64 pos){

        ans[i]=pos;
        visit[pos]=true;

        if(i==((1<<N)-1)){
            assert(pos==B);
