vector<int>built(int left,int right,int l){
	if (l == 1)return {left,right};
	vector<int>ret;
	int rec;
	int left_, right_, fl;
	left_ = 0;
	right_ = 0;
	fl = 0;
	for (int i = 0; i < 22; i++) {
		int msk = 1 << i;
		if (fl == 0) {
			if ((msk&left) != (msk&right)) { rec = i; fl = 1; }
			else { left_ += ((msk&left) ? msk : 0); right_ += ((msk&right) ? msk : 0); }
		}
		else { left_ += ((msk&left) ? (msk / 2) : 0); right_ += ((msk&right) ? (msk/2LL) : 0); }
	}
	int mid;
	mid = ((left_%2 == 0)?left_+1:left_-1);
	auto ret1 = built(left_,mid,l-1);
	auto ret2 = built(mid, right_,l-1);

	fore(x, ret1) {
		int x_ = 0;
		for (int i = 0; i < 22; i++) {
			int msk = (1LL << i);
			if(i < rec)x_ += ((msk&x) ? msk : 0);
			else if (i == rec)x_ += ((msk&left) ? msk : 0);
			else x_ += (((msk / 2) & x) ? msk:0);
		}
		ret.pb(x_);
	}
	fore(x, ret2) {
		int x_ = 0;
		for (int i = 0; i < 22; i++) {
			int msk = (1 << i);
			if (i < rec)x_ += ((msk&x) ? msk : 0);
			else if (i == rec)x_ += ((msk&right) ? msk : 0);
			else x_ += (((msk/2)&x) ? msk:0);
		}
		ret.pb(x_);
	}
	return ret;
}

