int n,a,b;
VI construct(int n,int a,int b) {
	if (n==1) {
		return VI{a,b};
	}
	b^=a;
	int sep=-1;
	rep(i,0,n) if (b&(1<<i)) {
		sep=i;
		break;
	}
	VI p=construct(n-1,0,1);
	VI q=construct(n-1,1,(b^(1<<sep))>>1);
	VI r;
	rep(i,0,SZ(p)) {
		int a=p[i]>>sep,b=p[i]&((1<<sep)-1);
		r.pb((a<<(sep+1))+b);
	}
	rep(i,0,SZ(q)) {
		int a=q[i]>>sep,b=q[i]&((1<<sep)-1);
		r.pb((a<<(sep+1))+(1<<sep)+b);
	}
	rep(i,0,SZ(r)) r[i]^=a;
	return r;
}

