using namespace std;

vector <int> Solve(int n, int u, int v)
{
    vector <int> res;
    if (n == 0) return res = {u, v};
    int Z = (1<<n)&u, ZZ = Z^(1<<n);
    if ((u>>n) == (v>>n)) {
        vector <int> vec = Solve(n-1, u^Z, v^Z);
        vector <int> _vec = Solve(n-1, vec[0], vec[1]);
        res.push_back(vec[0]^Z);
        if (__builtin_popcount(vec[0]^Z^_vec[0]^ZZ) != 1) assert(0);
        for (int i : _vec) res.push_back(i^ZZ);
        for (int i = 1; i < vec.size(); i++) res.push_back(vec[i]^Z);
    }
    else {
        vector <int> vec = Solve(n-1, u^Z, __builtin_popcount(u^Z)&1^1);
        vector <int> _vec = Solve(n-1, __builtin_popcount(v^ZZ)&1^1, v^ZZ);
        for (int i : vec) res.push_back(i^Z);
        for (int i : _vec) res.push_back(i^ZZ);
    }
    return res;
}

