constexpr int MAX_BIT = 17;

vector<int> Path(int s, int t, int mask, int base) {
  if (__builtin_popcount(mask) == 1) {
    return vector<int>({s, t});
  }

  for (int i = 0; i < MAX_BIT; i++) {
    if ((mask & (1 << i)) == 0) continue;
    if ((s & (1 << i)) != (t & (1 << i))) {
      // cout << "i: " << i << endl;;
      for (int j = 0; j < MAX_BIT; j++) {
        if ((mask & (1 << j)) == 0) continue;
        if (j == i) continue;
        // cout << "j: " << j << endl;
        int m_t = s ^ (1 << j);
        int m_s = m_t ^ (1 << i);
        auto p1 = Path(s, m_t, mask ^ (1 << i), base | (s & (1 << i)));
        auto p2 = Path(m_s, t, mask ^ (1 << i), base | (t & (1 << i)));
        p1.insert(p1.end(), p2.begin(), p2.end());
        return p1;
      }
      cerr << "Unexpected!" << endl;
    }
  }
  cerr << "Unexpected!" << endl;
  exit(1);
}

