void swap_bit(int &x, int i, int j) {
	if(i == j)
		return;
	D << "swapping " << i << " with " << j << " in " << x;
	bool bi = x & (1 << i),
		 bj = x & (1 << j);
	x -= x & (1 << i);
	x -= x & (1 << j);
	x += bj * (1 << i);
	x += bi * (1 << j);
	D << "set to " << x;
}

