		}
		p++;
	}

	int c_p = 0;
	while (!(sel & (1U << c_p)) || p == c_p) {
		c_p++;
	}

	uint32_t n_sel  = sel ^ (1U << p);
	uint32_t c      = a ^ (1U << c_p);
	uint32_t h_size = (1U << (n - 1));

	solve(a, c, n_sel, n - 1, it);
	solve(c, b, n_sel, n - 1, it + h_size);

	for (auto itf = it; itf < it + h_size; itf++) {
		*itf = set_bit(*itf, p, (a >> p) & 1);
	}
	for (auto itl = it + h_size; itl < it + h_size * 2; itl++) {
		*itl = set_bit(*itl, p, (b >> p) & 1);
	}
}

int main() {
