int g(int x, int i)
{
    return (x>>i)&1;
}
int divide(int x, int i)
{
    return (x>>(i+1)<<i) + (x&((1<<i)-1));
}
int join(int x, int i, int bit)
{
    x=(x>>i<<(i+1)) + (x&((1<<i)-1));
    if (bit) x^=(1<<i);
    return x;
}
void pl(vector<int> &c, vector<int> &a, vector<int> &b)
{
    for(auto x: a) c.push_back(x);
    for(auto x: b) c.push_back(x);
}
vector<int> build(int x, int y, int n)
{
    //cout<<x<<' '<<y<<' '<<n<<'\n';
    if (n==1) return {x, y};
    vector<int> v, v1, v2;
    for(int i=0; i<n; ++i) if (g(x, i) != g(y, i))
    {
        int newx=divide(x, i), newy=divide(y, i);
        int middle=newx^1;
        //cout<<x<<' '<<y<<' '<<n<<' '<<newx<<' '<<newy<<' '<<middle<<'\n';
        //cout<<newx<<' '<<newy<<' '<<middle<<'\n';
        v1=build(newx, middle, n-1);
        v2=build(middle, newy, n-1);
        for(int j=0; j<v1.size(); ++j) v1[j]=join(v1[j], i, g(x, i));
        for(int j=0; j<v2.size(); ++j) v2[j]=join(v2[j], i, g(y, i));
        pl(v, v1, v2);
        return v;
    }
}
