ll bitcnt(ll x)
{
    ll ret = 0;
    while (x) {
        x &= ~(x & -x);
        ret++;
    }
    return ret;
}

void solve(V<ll> &anslist, ll a, ll b, ll mask, ll n)
{
    if (n == 1) {
        anslist.pb(0);
        anslist.pb(mask);
        if (a & mask) reverse(ALL(anslist));
        return;
    }

    ll lsb = (a & mask) ^ (b & mask);
    lsb = (lsb & -lsb);
    mask &= ~lsb;

    ll lsb_mask = (mask & -mask);
    ll or_a = (a & lsb);
    ll or_b = (b & lsb);
    a &= ~lsb;
    b &= ~lsb;

    V<ll> xlist1;
    solve(xlist1, a, (a ^ lsb_mask), mask, n-1LL);
    V<ll> xlist2;
    solve(xlist2, (a ^ lsb_mask), b, mask, n-1LL);

