int parity(int A) {
  return __builtin_popcount(A) % 2;
}

int bit(int A, int i) {
  return (A >> i) & 1;
}

int extract(int A, int i) {
  int up = A >> (i + 1);
  int bt = A & ((1 << i) - 1);
  return (up << i) | bt;
}

int embed(int A, int i, int b) {
  int up = A >> i;
  int bt = A & ((1 << i) - 1);
  return (((up << 1) | b) << i) | bt;
}

vector<int> solve(int A, int B, int N) {
  if (N == 1) return {A, B};
  int k;
  for (int i = 0; i < N; i++) {
    if (bit(A, i) != bit(B, i)) {
      k = i;
      break;
    }
  }
  int X = extract(A, k);
  int Y = X ^ 1;
  int Z = extract(B, k);
  vector<int> res;
  for (int m : solve(X, Y, N - 1)) res.push_back(embed(m, k, bit(A, k)));
  for (int m : solve(Y, Z, N - 1)) res.push_back(embed(m, k, bit(B, k)));
  return res;
}

