using namespace std;

void swa(int &a,int i,int j)
{
	if ((a&(1<<i))&&!(a&(1<<j)))
	{
		a+=-(1<<i)+(1<<j);
	}
	else if (!(a&(1<<i))&&(a&(1<<j)))
	{
		a+=(1<<i)-(1<<j);
	}
}

vector<int> my(int n,int a,int b)
{
	if (n==1)
	{
		return {a,b};
	}
	int ex=n-1;
	while (!((a^b)&(1<<ex)))
	{
		--ex;
	}
	swa(a,n-1,ex);
	swa(b,n-1,ex);
	int na=a&~(1<<(n-1)),nb=b&~(1<<(n-1));
	auto l=my(n-1,na,na^1),r=my(n-1,na^1,nb);
	vector<int> ans;
	if (a&(1<<(n-1)))
	{
		for (auto v : l)
		{
			ans.push_back(v^(1<<(n-1)));
		}
		for (auto v : r)
		{
			ans.push_back(v);
		}
	}
	else
	{
		for (auto v : l)
		{
			ans.push_back(v);
		}
		for (auto v : r)
		{
			ans.push_back(v^(1<<(n-1)));
		}
	}
	for (auto &v : ans)
	{
		swa(v,n-1,ex);
	}
	return ans;
}

