void chemthan() {
    int n, a, b; cin >> n >> a >> b;
    int c = a ^ b;
    vi vals;
    FOR(i, 0, n) if (bit(c, i)) vals.pb(i);
    if (sz(vals) % 2 == 0) {
        cout << "NO\n";
        return;
    }
    function<vi(int)> func = [&] (int n) {
        if (n == 1) {
            vi res;
            res.pb(0);
            res.pb(1 << vals[0]);
            return res;
        }
        vi tmp = func(n - 2);
        vi res;
        for (int i = 0; i < sz(tmp); i += 2) {
            int a = tmp[i];
            int b = tmp[i + 1];
            int x = 1 << vals[n - 2];
            int y = 1 << vals[n - 1];
            if (i + 1 < sz(tmp) - 1) {
                res.pb(a);
                res.pb(a ^ x);
                res.pb(a ^ x ^ y);
                res.pb(a ^ y);
                res.pb(b ^ y);
                res.pb(b ^ x ^ y);
                res.pb(b ^ x);
                res.pb(b);
            }
            else {
                res.pb(a);
                res.pb(b);
                res.pb(b ^ x);
                res.pb(a ^ x);
                res.pb(a ^ x ^ y);
                res.pb(a ^ y);
                res.pb(b ^ y);
                res.pb(b ^ x ^ y);
            }
        }
        return res;
    };
    vi res = func(sz(vals));
    FOR(i, 0, n) if (!bit(c, i)) {
        vi tmp;
        for (int j = 0; j < sz(res); j += 2) {
            int a = res[j];
            int b = res[j + 1];
            int x = 1 << i;
            tmp.pb(a);
            tmp.pb(a ^ x);
            tmp.pb(b ^ x);
            tmp.pb(b);
        }
        res = tmp;
    }
    cout << "YES\n";
    FOR(i, 0, sz(res)) {
        cout << (res[i] ^ a) << " \n"[i == sz(res) - 1];
    }
}

