void solve() {
  int n, a, b; cin >> n >> a >> b;

  if (!CoutYN(__builtin_parity(a ^ b), "YES", "NO")) {
    return;
  }

  bitset<17> bs(a ^ b);
  vi tmp;
  rep(i,n) if (bs[i]) tmp.emplace_back(i);
  vi ds(n);
  iota(ALL(ds), 0);
  auto ds2 = ds;
  for (int i=1; i<tmp.size(); i+=2) {
    swap(ds2[tmp[i-1]], ds2[tmp[i]]);
  }
  ds.erase(ds.begin() + tmp.back());
  ds2.erase(ds2.begin() + tmp.back());
  ds2.emplace_back(tmp.back());

  vi ans(1<<n);
  ans[0] = a;

  rep1(i,1<<n) {
    int k = 31 - __builtin_clz(i ^ (i-1));
    if (i < (1<<n-1)) ans[i] = ans[i-1] ^ (1<<ds[k]);
    else ans[i] = ans[i-1] ^ (1<<ds2[k]);
  }

  cout << ans << endl;
}


