vector<int> dfs(int s, int g, int mask, int n){
	if(n == 1){
		return {s, g};
	}

	REP(i, 20){
		if(!(mask & (1<<i)))continue;
		int a = s & (1<<i);
		int b = g & (1<<i);
		if(a == b)continue;
		int nmask = mask ^ (1<<i);
		REP(j, 20){
			if(!(nmask & (1<<j)))continue;
			int tmp = (s & nmask) ^ (1<<j);
			auto l = dfs(s & nmask, tmp, nmask, n - 1); 
			auto r = dfs(tmp, g & nmask, nmask, n - 1); 
			vector<int> ret;
			REP(k, l.size())ret.PB(l[k] | (s & (1<<i)));
			REP(k, r.size())ret.PB(r[k] | (g & (1<<i)));
			return ret;
		}
	}	
}

