using namespace std;

vector<vector<int>> kalnough;

int N, A, B;
int C;
void build(int level) {
	if (level <= 1)return;
	for (int i = 1; i < level; i++) {
		for (int bit = 0; bit < (1 << i); bit++) {
			kalnough[i].push_back(kalnough[i - 1][bit]);
		}
		for (int bit = (1 << i); bit < (1 << (i + 1)); bit++) {
			kalnough[i].push_back(kalnough[i - 1][(1 << (i + 1)) - 1 - bit] + (1 << i));
		}
	}

}

int cntbit(int bits)
{
	bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
	bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
	bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
	bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
	return (bits & 0x0000ffff) + (bits >> 16 & 0x0000ffff);
}

int erase_head(int a, int b) {
	if (a & (1 << b))a -= (1 << b);
	return a;
}

int main() {
	cin >> N >> A >> B;
	N--;

	kalnough.resize(20);
	kalnough[0].push_back(0);
	kalnough[0].push_back(1);
	build(N);
	int C = A ^ B;
	//この作業で、0スタート,Cで終わると固定できる

	vector<int> ans;

	if (cntbit(C) % 2 == 0) {
		cout << "No" << endl;
		return 0;
	}
	int flg = 0;
	int pos = -1;

	for (int i = 0; i < kalnough[N - 1].size(); i++) {
		if (kalnough[N - 1][i] != erase_head(C, N) && flg == 0) {
			if (i % 2 == 0) {
				ans.push_back(kalnough[N - 1][i]);
				ans.push_back(kalnough[N - 1][i] + (1 << (N - 1)));
			}
			else {
				ans.push_back(kalnough[N - 1][i] + (1 << (N - 1)));
				ans.push_back(kalnough[N - 1][i]);
			}
		}
		else if (kalnough[N - 1][i] == erase_head(C, N) && flg == 0) {
			pos = i;
			if (i % 2 == 0) {
				ans.push_back(kalnough[N - 1][i]);
				flg = 1;
			}
			else {
				ans.push_back(kalnough[N - 1][i] + (1 << (N - 1)));
				flg = 2;
			}
		}
		else if(flg == 1){
			ans.push_back(kalnough[N - 1][i]);

		}
		else if (flg == 2) {
			ans.push_back(kalnough[N - 1][i] + (1 << (N - 1)));
		}
	}
	for (int i = (1 << N - 1);; i--) {
		if (flg == 1) {
			ans.push_back(kalnough[N - 1][i] + (1 << N));
		}
		else {
			ans.push_back(kalnough[N - 1][i]);
		}
		if (i == pos)break;
	}

	cout << "YES" << endl;
	for(int i = 0; i < ans.size();i++){
		cout << (ans[i] ^ A) << " " ;
	}
	cout << endl;
	return 0;
}

