using namespace std;

vector<bool> perm[131075];
int N, A, B;
int len;
vector<bool> getbin(int x){
    vector<bool> buff;
    while(x!=0){
        buff.push_back(x%2);
        x /= 2;
    }
    return buff;
}
int getval(vector<bool> buff){
    int t = 1, ret = 0;
    for (int i=0;i<buff.size();i++){
        ret += (int)buff[i] * t;
        t = t << 1;
    }
    return ret;
}

int find(int i, int j, int start){
    for (int k=start;k<N;k++){
        if (perm[i][k]!=perm[j][k]) return k;
    }
    return -1;
}

void fill(int i, int j, int start){
    if (start==N-1) return;
    if (i==j) return;
    if (i>j) return;
    if (start<0 || start>=N){
        cout << -1 << endl;
        exit(0);        
    }
    if (i<0 || i>=len) {
        cout << -1 << endl;
        exit(0);
    }
    if (j<0 || j>=len) {
        cout << -1 << endl;
        exit(0);
    }
    int pos = find(i, j, start);
    if (pos<0 || pos >= N){
        cout << -1 << endl;
        exit(0);
    }

    // cout << "pos: " << pos << endl;
    //swap pos row and start row
    bool temp = perm[i][start];
    perm[i][start] =  perm[i][pos];
    perm[i][pos] = temp;
    temp = perm[j][start];
    perm[j][start] =  perm[j][pos];
    perm[j][pos] = temp;
    // Now first row is different
    int mid = (i+j)/2;
    // cout << "mid: " << mid << endl;
    for(int k=i;k<=mid;k++){
        perm[k][start] = perm[i][start];
    }
    for(int k=j;k>mid;k--){
        perm[k][start] = perm[j][start];   
    }
    // Copy the rest and alter the next leading bit 
    if (start+1<N && mid+1<j){
        for (int k=start+1;k<N;k++){
            perm[mid][k] = perm[i][k];
            perm[mid+1][k] = perm[i][k];
        }
        perm[mid][start+1] = !perm[mid][start+1];
        perm[mid+1][start+1] = !perm[mid+1][start+1];        
    }
    fill(i, mid, start+1);
    fill(mid+1, j, start+1);
    // cout << "CHECK1" << endl;
    // Swap back
    for (int k=i;k<=j;k++){
        temp = perm[k][start];
        perm[k][start] =  perm[k][pos];
        perm[k][pos] = temp;
    }
}

int main(void){
    cin >> N;
    len = (int) pow(2, N);
    for (int i=0;i<len;i++){
        perm[i] = vector<bool>(N);
        for(int j=0;j<N;j++){
            perm[i][j] = 0;
        }
    }
    cin >> A >> B;
    perm[0] = getbin(A), perm[len-1] = getbin(B);  
    int cnt = 0;
    for (int i=0;i<N;i++){
        cnt += (perm[0][i]!=perm[len-1][i]);
    }
    if (cnt%2==0) {
        cout << "NO" << endl;
        return 0;
    }
    cout << "YES" << endl;
    if (N==1){
        cout << A << " " << B << endl;
        return 0;
    }
    cout << -1 << endl;
    exit(0);
    fill(0, len-1, 0);
    for (int i=0;i<len;i++){
        cout << getval(perm[i]) << " ";
    }
    cout << endl;
}

