				if (cnt < half) {
					continue;
				}
				int tmp = G[cur] ^ (1 << i);
				for (int j = 0; j < U; j++) {
					if (G[j] == tmp) {
						cur = j;
						break;
					}
				}
				vec[back++] = G[cur];
