{
    vector<int>res = {0, 1}, temp;
    for (int x = 1; x < n; x++)
    {
        temp.clear();
        for (int low : res) temp.push_back(low);
        reverse(res.begin(), res.end());
        for (int low : res) temp.push_back((1 << x) | low);
        res = temp;
    }
    for (int i = 0; i < (int)res.size() - 1; i++) assert(__builtin_popcount(res[i] ^ res[i + 1]) == 1);
    assert(*res.begin() == 0);
    return res;
}
