string tob(int x) {
	string s = "";
	while (x) {
		if (x % 2)
			s = '1' + s;
		else
			s = '0' + s;
		x /= 2;
	}
	while ((int)s.size() < sz)
		s = '0' + s;
	return s;
}
int dif(int x, int y) {
	string s = tob(x);
	string t = tob(y);
	int d = 0;
	for (int i = 0; i < sz; i++)
		if (s[i] != t[i])
			d++;
	return d;
}

void sml() {
	for (int i = 0; i < n; i++)
		res[i] = i;
	do {
		if (res[0] != a || res[n - 1] != b) 
			continue;
		bool ok = 1;
		for (int i = 0; i + 1 < n; i++)
			if (dif(res[i], res[i + 1]) > 1)
				ok = 0;
		if (ok) {
			cout << "YES" << '\n';
			for (int i = 0; i < n; i++)
				cout << res[i] << ' ';
			exit(0);
		}
	} while (next_permutation(res, res + n));
	cout << "NO";
	exit(0);
}
