vector<ll> make(int n)
{
  if (n == 1)
  {
    return {0, 1};
  }
  vector<ll> V = make(n - 1);
  int S = V.size();
  vector<ll> W;
  for (auto i = 0; i < S / 2; i++)
  {
    W.push_back(V[i]);
  }
  for (auto i = S / 2 - 1; i >= 0; i--)
  {
    W.push_back(V[i] + (1LL << (n - 1)));
  }
  for (auto i = S - 1; i >= S / 2; i--)
  {
    W.push_back(V[i] + (1LL << (n - 1)));
  }
  for (auto i = S / 2; i < S; i++)
  {
    W.push_back(V[i]);
  }
  return W;
}

void solve(int i)
{
  vector<ll> V = make(N);
  for (auto i = 0; i < (int)V.size(); i++)
  {
    ll x = V[i];
    ll y = (x << i);
    ll mod = y % (1LL << N);
    ll k = (y >> N);
    V[i] = mod + k;
    ans.push_back(A ^ V[i]);
  }
  flush();
}

