vector<int> gen(vector<int> d)
{
    if (d.size() == 0) return vector<int>{0};
    if (d.size() == 1) return vector<int>{0, POW2(d[0])};

    int a = POW2(d[SZ(d) - 2]), b = POW2(d[SZ(d) - 1]);
    d.pop_back();
    d.pop_back();
    vector<int> tmp = gen(d);
    int L = SZ(tmp);
    tmp.resize(L * 4);
    REP(i, L) tmp[i + L] = a xor tmp[L - 1 - i];
    REP(i, L)
    {
        if (i % 2 == 0)
        {
            tmp[L * 2 + i * 2] = tmp[i] xor a xor b;
            tmp[L * 2 + i * 2 + 1] = tmp[i] xor b;
        }
        else
        {
            tmp[L * 2 + i * 2] = tmp[i] xor b;
            tmp[L * 2 + i * 2 + 1] = tmp[i] xor b xor a;
        }
    }
    return tmp;
}
