bool Solve(int l,int r){
	if (r-l<2) return 1;
	int v,p=-1;
	for (int i=0;i<N;++i){
		if ((a[l]&(1<<i))==(a[r]&(1<<i))) continue;
		v=a[l]&(1<<i);p=i;break;
	}
	if (p==-1) return 0;
	for (int i=l;i<=r;++i)
	b[i]|=(1<<p);
	for (int i=l+1;i<mid;++i)
	a[i]|=v*(1<<p);
	for (int i=mid+2;i<r;++i)
	a[i]|=(v^1)*(1<<p);
	for (int i=0;i<N;++i){
		if (b[mid]&(1<<i)) continue;
		a[mid]=a[l]^(1<<i);break;
	}
	for (int i=0;i<N;++i){
		if (b[mid+1]&(1<<i)) continue;
		a[mid+1]=a[r]^(1<<i);break;
	}
	bool flag=1;
	flag&=Solve(l,mid);
	flag&=Solve(mid+1,r);
	return flag;
}

