    if (__builtin_popcount(mask) == 1) return {u, v};
    vector<int> res;
    rep (i, n) if ((mask>>i)&1 && ((u>>i)&1) != ((v>>i)&1)) {
        int nxt;
        rep (j, n) if ((mask>>j)&1 && i != j) {nxt = j; break;}
        vector<int> fis = dfs(u, u ^ (1<<nxt), mask - (1<<i));
        vector<int> sec = dfs(u ^ (1<<nxt) ^ (1<<i), v, mask - (1<<i));
        for (auto e : fis) res.pb(e);
        for (auto e : sec) res.pb(e);
        break;
    }
    return res;
}

void solve() {
    cin >> n >> a >> b;
    if (__builtin_popcount(a ^ b) % 2 == 0) {
        cout << "NO" << endl;
        return;
    }
    cout << "YES" << endl;
    DEBUG(dfs(a, b, (1<<n)-1));
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

