    cin >> a >> b;
    int A = 0, B = a ^ b;

    int cnt_diff = 0;
    for (int i = 0; i < n; ++i) {
      if (((A >> i) & 1) != ((B >> i) & 1)) cnt_diff++;
    }
    if (cnt_diff % 2 == 0) {
      cout << "NO" << endl;
      return;
    }
    cout << "YES" << endl;
    auto ans = calc_path(A, B, 0);
    for (auto x : ans) {
      cout << (x ^ a) << " ";
    }
    cout << endl;
  }

  vector<int> calc_path(int from, int to, int mask) {
    set<int> bits_diff, bits_mask;
    for (int i = 0; i < n; ++i) {
      if (((from >> i) & 1) != ((to >> i) & 1)) {
        bits_diff.insert(i);
      }
      if ((mask >> i) & 1) {
        bits_mask.insert(i);
      }
    }
    if (bits_mask.size() == n - 1) {
      return {from, to};
    }
    DBG(from, to, mask, bits_mask, bits_diff)
    if (bits_diff.size() == 0) {
      exit(0);
    }
    int i = *bits_diff.begin();
    int F = (from & (1 << i));
    int T = (to & (1 << i));
    int bound = 0;
    int tmpcnt = 0;
    vector<int> same0, same1;
    for (int j = 0; j < n; ++j) {
      if (j == i) continue;
      if (bits_mask.count(j)) {
        bound += (from & (1 << j));
      } else if (bits_diff.count(j)) {
        if (tmpcnt == 0) {
          bound += (from & (1 << j));
        } else {
          bound += (to & (1 << j));
        }
        tmpcnt++;
      } else {
        bound += (from & (1 << j));
        same0.push_back(j);
      }
    }
    DBG(bound)
    int cnt_diff = 0;
    for (int j = 0; j < n; ++j) {
      if (((from >> j) & 1) != (((bound + F) >> j) & 1)) {
        cnt_diff++;
      }
    }
    DBG(cnt_diff, same0)
    if (cnt_diff % 2 == 0) {
      bound -= ((((from >> same0[0]) & 1)) << same0[0]);
      bound += ((!((from >> same0[0]) & 1)) << same0[0]);
    }
    vector<int> res1, res2;
    DBG(from, to, mask, bound, F, T)
    res1 = calc_path(from, bound + F, mask | (1 << i));
    res2 = calc_path(bound + T, to, mask | (1 << i));
    for (auto x : res2) {
      res1.push_back(x);
    }
    DBG(from, to, mask, res1)
    return res1;
  }
};

