const int N = 17;
int ans[1 << N];
int gray[1 << N];
vector<int> grayCode(int lv) {
    if (lv == 1) return {0, 1};
    vector<int> ans = grayCode(lv - 1);
    for(int i = 1; i <= (1 << (lv -1)); i++) 
        ans.push_back(ans[(1 << (lv - 1)) - i] ^ (1 << (lv - 1)));
    return ans;
}
void swapBit(int u, int v, int L, int R) {
    int mask = (1 << u) ^ (1 << v);
    for(int i = L; i < R; i++){
        int s1 = (ans[i] >> u) & 1;
        int s2 = (ans[i] >> v) & 1;
        if (s1 != s2) ans[i] ^= mask;
    }
}
void build(int depth, int L, int R, int st, int en) {
    //cout << "Call " << depth << " " << st << " " << en << '\n';
    int nen = en ^ st;

    vector<int> diff;
    for(int i = 0; i < depth; i++) if ((nen >> i) & 1) 
        diff.push_back(i);
    int ndiff = diff.size();

    if (ndiff == 1) {
        for(int i = L; i < R; i++) ans[i] = gray[i - L];
        swapBit(diff[0], depth - 1, L, R);
        for(int i = L; i < R; i++) ans[i] ^= st;
        return;
    }
    int half = 0;
    for(int i = 0; i < ndiff / 2; i++) 
        half |= 1 << diff[i];

    //cout << depth << '\n';
    //cout << half << " " << ((1 << diff.back()) ^ nen) << '\n';
    int mid = (L + R) / 2;
    build(depth - 1, L, mid, 0, half); 
    build(depth - 1, mid, R, half, (1 << diff.back()) ^ nen);
    for(int i = mid; i < R; i++)
        ans[i] ^= 1 << (depth - 1);
    swapBit(diff.back(), depth - 1, mid, R);
    for(int i = L; i < R; i++) ans[i] ^= st;
}
