void swa(int &a, int i, int j) {
  if((a & (1<<i)) && !(a & (1<<j))) a += -(1<<i) + (1<<j);
  else if( !(a & (1<<i)) && (a & (1<<j))) a += (1<<i) - (1<<j);
}

vector<int> solve(int n, int a, int b) {
  if(n == 1) return {a, b};

  int c = a^b;
  int top = n-1;
  for(int i=0;i<n;++i) {
    if((c>>i)==1) {
      top = i;
      break;
    }
  }

  if(top != n-1) {
    swa(a, n-1, top), swa(b, n-1, top);
  }

  int na = a & ~(1<<(n-1));
  auto former = solve(n-1, na, na^1);

  int nb = b & ~(1<<(n-1));
  auto later = solve(n-1, na^1, nb);

  vi res;
  if(a & (1<<(n-1))) {
    for(auto &e: former) {
      res.push_back(e ^ (1<<(n-1)));
    }
    for(auto &e: later) {
      res.push_back(e);
    }
  } else {
    for(auto &e: former) {
      res.push_back(e);
    }
    for(auto &e: later) {
      res.push_back(e ^ (1<<(n-1)));
    }
  }

  for(auto &e: res) {
    swa(e, n-1, top);
  }
  return res;
}

