int N;
vector<int> v;

void func(int bit, int S1, int S2, int lock){
	//cout << bit << " " << S1 << " " << S2 << " " << lock << endl;
	if(bit <= 1){
		v.push_back(S1);
		v.push_back(S2);
		//cout << S1 << " " << S2 << " " << endl;
		return;
	}
	for(int i = 0; i < N; i++){
		if((S1 & (1 << i)) != (S2 & (1 << i))){
			lock += (1 << i);
			bool flag = true;
			for(int j = i + 1; j < N; j++){
				if((S1 & (1 << j)) != (S2 & (1 << j))){
					flag = false;
					int num;
					if(S1 & (1 << j)){
						num = S1 - (1 << j);
						func(bit - 1, S1, num, lock);
						func(bit - 1, num ^ (1 << i), S2, lock);
					}else{
						num = S2 - (1 << j);
						func(bit - 1, S1, num ^ (1 << i), lock);
						func(bit - 1, num, S2, lock);
					}
					break;
				}
			}
			if(flag){
				for(int j = 0; j < N; j++){
					if((lock & (1 << j)) == 0){
						func(bit - 1, S1, S1 ^ (1 << j), lock);
						func(bit - 1, S1 ^ (1 << j) ^ (1 << i), S2, lock);
						break;
					}
				}
			}
			break;
		}
	}
}

int main(){
	int A, B;
	cin >> N >> A >> B;
	int num = (A ^ B), cnt = 0;
	while(num > 0){
		if(num % 2){
			cnt += 1;
		}
		num /= 2;
	}
	if(cnt % 2 == 0){
		cout << "NO" << endl;
		return 0;
	}
	func(N, A, B, 0);
	cout << "YES" << endl;
	for(int i = 0; i < v.size() - 1; i++){
		cout << v[i] << " ";
	}
	cout << v[v.size() - 1] << endl;
	return 0;
}

