    ios::sync_with_stdio(false);
    cout << fixed << setprecision(20);

    int n, a, b;
    input(n, a, b);
    // 0 => b ^ a, 最後にaをxorすればよい
    if(__builtin_popcount(b ^ a) % 2 == 0){
        cout << "NO" << endl;
        return 0;
    }
    cout << "YES" << endl;

    b ^= a;
    vector<int> v;
    for(const auto& i : Range<>(1 << (n - 1)))
        v.emplace_back(i ^ (i >> 1));


    int x = 0, y = 0;
    auto g = [&](int xx, int yy){
        return v[xx] + (yy << (n - 1));
    };
    vector<int> ans(1, 0);
    auto mov = [&]{
        if(y & (x & 1)){
            --y;
            if(g(x, y) == b){++y; return false;}
        }else if(!y & !(x & 1)){
            ++y;
            if(g(x, y) == b){--y; return false;}
        }else{
            ++x;
            if(g(x, y) == b){--x; return false;}
        }
        return true;
    };

    auto down = [&]{
        if(x == (1 << (n - 1)) - 1){
            y ^= 1;
            return false;
        }
        ++x;
        return true;
    };

    auto up = [&]{
        --x;
        return g(x, y) != b;
    };

    while(mov())
        ans.emplace_back(g(x, y));
    while(down())
        ans.emplace_back(g(x, y));
    ans.emplace_back(g(x, y));
    while(up())
        ans.emplace_back(g(x, y));
    ans.emplace_back(g(x, y));

    for(const auto& i : Range<>(1 << n))
        cout << (a ^ ans[i]) << " \n"[i == (1 << n) - 1];

}

