template<class T = int> using VV = V< V<T> >;

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n, a, b; cin >> n >> a >> b;
  auto rec = [&](const auto& rec, int mask, int a, int b) -> V<> {
    if (__builtin_popcount(mask) == 1) {
      return a == b ? V<>{} : V<>{a, b};
    }
    for (int i = 0; i < n; ++i) if (mask & 1 << i and (a ^ b) & 1 << i) {
      mask ^= 1 << i;
      for (int bit = mask; ; bit = bit - 1 & mask) {
        if (__builtin_popcount(a & mask ^ bit) & 1 and __builtin_popcount(b & mask ^ bit) & 1) {
          auto va = rec(rec, mask, a & mask, bit);
          if (a & 1 << i) for (auto&& e : va) {
            e |= 1 << i;
          }
          auto vb = rec(rec, mask, bit, b & mask);
          if (b & 1 << i) for (auto&& e : vb) {
            e |= 1 << i;
          }
          move(begin(vb), end(vb), back_inserter(va));
          return va;
        }
        if (!bit) break;
      }
      return {};
    }
  };
  auto res = rec(rec, (1 << n) - 1, a, b);
  if (res.empty()) {
    cout << "NO" << '\n';
  } else {
    cout << "YES" << '\n';
    for (int i = 0; i < 1 << n; ++i) {
      cout << res[i] << " \n"[i == (1 << n) - 1];
    }
  }
}

