vector<ll> solve(ll n, ll a, ll b) {
	ll k = (1 << n);
	vector<ll> ans(k);
	if (n == 0) {
		ans[0] = 0;
		return ans;
	}
	if (n == 1) {
		ans[0] = a;
		ans[1] = b;
		return ans;
	}
	b ^= a;
	if ((k / 2) & b) {
		vector<ll> x = solve(n - 1, 0, 1);
		vector<ll> y = solve(n - 1, 1, b - k / 2);
		for (int i = 0; i < k / 2; i++) {
			ans[i] = x[i];
			ans[i + k / 2] = y[i] + k / 2;
		}
	}
	else {
		vector<ll> x = solve(n - 1, 0, b);
		vector<ll> y = solve(n - 1, x[k / 2 - 2], b);
		for (int i = 0; i < k / 2 - 1; i++) {
			ans[i] = x[i];
		}
		for (int i = 0; i < k / 2; i++) {
			ans[i + k / 2 - 1] = y[i] + k / 2;
		}
		ans[k - 1] = x[k / 2 - 1];
	}
	for (int i = 0; i < k; i++) {
		ans[i] = (ans[i] ^ a);
	}
	return ans;
}

