std::vector<int> dfs(int n,int a,int b){
    if(n==1) return {a,b};
    b^=a;
    int step=-1;
    for(int i=0;i<n;i++) if(b&(1<<i)) {step=i;break;}
    std::vector<int> p=dfs(n-1,0,1);
