void construct(int l,int r,int a,int b,int n,int bit,int myxor) {
  assert(bitCount(a^b)&1);
  if(l+1==r) {
    ret[l] = l^myxor;
    ret[r] = r^myxor;
    return;
  }
  int mid = (l+r)/2;
  int ind = -1;
  for(int i=0;i<n;++i) {
    if(bit&(1<<i)) {
