#include <bits/stdc++.h>
using namespace std;

int bitcount(int x) {
    int ans = 0;
    while (x > 0) {
        ans += x & 1;
        x >>= 1;
    }
    return ans;
}

int bit(int x, int pos) {
    return (x >> pos) & 1;
}

// Insert bit i to position pos of number x
int insertBit(int x, int pos, int i) {
    int y = x & ((1 << pos) - 1);
    x ^= y;
    x <<= 1;
    x ^= y;
    if (i) x |= 1 << pos;
    return x;
}

// Delete pos-th bit of number x
int deleteBit(int x, int pos) {
    int y = x & ((1 << pos) - 1);
    x ^= y;
    x &= ~(1 << pos);
    x >>= 1;
    x ^= y;
    return x;
}

// find the position of the bit(0->n-1) that a and b is different
int findp(int n, int a, int b) {
    for (int i = 0; i < n; i++) {
        if (bit(a, i) != bit(b, i))
            return i;
    }
    return -1;
}

vector<int> F(int n, int a, int b) {
    if (n == 1) {
        return vector<int> {a, b};
    }

    int p = findp(n, a, b);
    int val = bit(a, p);

    int x = deleteBit(a, p);
    int y = deleteBit(b, p);

    int z = x ^ 1;    

    vector<int> u = F(n - 1, x, z);
    vector<int> v = F(n - 1, z, y);

    vector<int> res;
    for (auto i : u)
        res.push_back(insertBit(i, p, val));
    for (auto i : v)
        res.push_back(insertBit(i, p, val ^ 1));

    return res;
}

