template<typename T>void read(T &x)
{
    static char rc;static int flag;
    x=0;rc=Getchar();flag=1;
    while(!isdigit(rc))
      flag=(rc=='-'?-1:1),rc=Getchar();
    while(isdigit(rc))
      x=x*10+rc-'0',rc=Getchar();
    x*=flag;
}

