int cutbit(int x, int bit){
    /// 11100000 1100
       //       ^ assume we want to cut this bit
  ///imagine 1111100001111 x 100
  /// | is 3rd bit
     ///1
    int now = (x - ((x >> bit) << bit));
    int res = ((x >> (bit + 1)) << bit) + now;
    return res;
}
int ins(int x, int bit, bool c){
    ///1110000 x ?????
    int now = x  - ((x >> bit) << bit);
    int res = ((x >> bit) << (bit + 1)) + now;
    return c ? (res ^ (1 << bit)) : res;
}
vector<int> rec(int a, int b, int curbit){
    if(curbit == 0){
        return {a, b};
    }
    int g = a ^ b, idx = -1;
    for(int i = 0 ; i < n ;i++){
        if(g & (1 << i)){
            idx = i;
            break;
        }
    }
    /**
    11
    01
    */
    int x = cutbit(a, idx); int y = cutbit(b, idx);
    int z = x ^ 1;

    auto u = rec(x, z, curbit - 1) ;
    auto v = rec(z, y, curbit - 1) ;
    eprintf("n = %d x = %d y = %d idx = %d\n", curbit, x , y, idx);
   // for(int i :u)
   //     eprintf("%d ", i);
   // eprintf("\n");
   // for(int i:v)
   //     eprintf("%d ",i);
   // eprintf("\n");

    if(a & (1 << x)){
        for(int &i : u)
            i = ins(i, idx, true);
        for(int i : v)
            u.push_back(ins(i, idx, false));
    }
    else{
        for(int &i : u)
            i = ins(i, idx, false);
        for(int i : v){
            u.push_back(ins(i, idx, true));
        }
    }
    return u;
}

