vi f(int mask, int a, int b) {
	if (__builtin_popcount(mask) == 1) {
		return {a, b};
	}

	int B = -1;
	FOR (i, 0, 16) if ((mask & (1 << i)) and ((a&(1<<i)) ^ (b&(1<<i)))) {
		B = i;
		break;
	}
	assert(B != -1);
	int na = a & (~(1 << B));
	int nb = b & (~(1 << B));
	int x = -1;

	mask ^= (1 << B);

	FOR (i, 0, 16) if ((mask & (1 << i)) and (na ^ (1 << i)) != nb) {
		x = na ^ (1 << i);
		break;
	}

	vi L = f(mask, na, x);
	vi R = f(mask, x, nb);
	if (b & (1 << B)) for (int &i: R) i |= (1 << B);
	else for (int &i: L) i |= (1 << B);

	copy(R.begin(), R.end(), back_inserter(L));
	return L;
}

