                ans[sz++] = upper | 0;
                ans[sz++] = upper | 1;
                break;
            }
            // あと1つうめる
            else if(N - pos == 2){
                ans[sz++] = upper | 0b00;
                ans[sz++] = upper | 0b01;
                ans[sz++] = upper | 0b11;
                ans[sz++] = upper | 0b10;
