                }
                else{
                    before &= ~(1 << ord[j]);
                }
            }
            // cout << before << ":" << after << endl;
            cout << (before ^ A) << " ";
        }
        cout << endl;
    }
    else{
        cout << "NO" << endl;
    }

    return 0;
}

