void solve(int m, int a, int b, int stb, int val){
    if(m == 1){
        sol[++s] = a;
        sol[++s] = b;
        return;
    }
    int i, ii, nr, x, j;
    for(ii = 0; ii < n; ii++){
        if(bit(a, ii) != bit(b, ii)){
            break;
        }
    }
    stb += (1 << ii);
    for(i = 0; i < (1 << m); i++){
        x = val;
        nr = 0;
        for(j = 0; j < n; j++){
            if(bit(stb, j) == 0){
                x += (1 << j) * bit(i, nr);
                nr++;
            }
        }
        if(p[x + (1 << ii) * bit(a, ii)] % 2 != p[a] % 2 && x + (1 << ii) * bit(a, ii) != a && x + (1 << ii) * bit(b, ii) != b){
            solve(m - 1, a, x + (1 << ii) * bit(a, ii), stb, val + (1 << ii) * bit(a, ii));
            solve(m - 1, x + (1 << ii) * bit(b, ii), b, stb, val + (1 << ii) * bit(b, ii));
            return;
        }
    }
}
