int dis(uint a, uint b, uint N) {
	uint C = a ^ b;
	int n = 0;
	for (int i = 0; i < N; ++i) {
		if (((C >> i) & 1LL) != 0) {
			++n;
		}
	}
	return n;
}

uint eraseBit(uint x, int n) {
	x &= (~(1 << n));
	uint tmp0 = (x & ((1LL << n) - 1));
	uint tmp1 = (x & ~((1LL << n) - 1));
	tmp1 >>= 1;
	return tmp1 | tmp0;
}

uint insertBit(uint x, int n, uint b) {
	uint tmp0 = (x & ((1LL << n) - 1));
	uint tmp1 = (x & ~((1LL << n) - 1));
	tmp1 <<= 1;
	if (b != 0) {
		tmp0 |= (1LL << n);
	}
	return tmp1 | tmp0;
}

uint bit(uint x, int n) {
	return (x >> n) & 1;
}

std::vector<uint> impl(uint A, uint B, int N) {
	std::vector<uint> res(1 << N);
	if (N == 1) {
		return { A,B };
	}
	int id = -1;
	for (int i = 0; i < N; ++i) {
		if (bit(A, i) != bit(B, i)) {
			id = i;
			break;
		}
	}
	assert(id != -1);
	uint Abit = bit(A, id);
	uint Bbit = bit(B, id);
	uint A1 = eraseBit(A, id);
	uint B1 = eraseBit(B, id);
	uint C = A1 ^ 1;
	auto res0 = impl(A1, C, N - 1);
	auto res1 = impl(C, B1, N - 1);
	for (int i = 0; i < (1LL << (N - 1)); ++i) {
		res[i] = insertBit(res0[i], id, Abit);
		res[i + (1LL << (N - 1))] = insertBit(res1[i], id, Bbit);
	}
	return res;
}


