ll contract(ll x, ll i) {
	return ((x >> (i+1)) << i) + (x % (1 << i));
}

ll expand(ll x, ll i) {
	return ((x >> i) << (i+1)) + (x % (1 << i));
}

bool ok(ll n, ll a, ll b) {
	return a < (1 << n) && b < (1 << n) && __builtin_popcount(a^b) % 2 == 1;
}

vl gray_code(ll n, ll a, ll b) {
	assert(ok(n,a,b));
	if (n == 1) return {a,b};

	ll i = 0;
	while ((a & (1 << i)) == (b & (1 << i))) i++;

	ll c = contract(a,i), d = contract(b,i);
	ll e = 0;
	do e = rand() % (1 << (n-1));
	while (!ok(n-1,c,e));

	vl v = gray_code(n-1,c,e), w = gray_code(n-1,e,d);

	vl res;
	for (ll x: v) res.pb(expand(x,i) ^ (a & (1 << i)));
	for (ll x: w) res.pb(expand(x,i) ^ (b & (1 << i)));
	return res;
}

