vector<int> solve(int n, int a, int b, int mask) {
    // cout << a << " " << b << " " << mask << endl;
    assert((a & mask) == a);
    assert((b & mask) == b);

    if (__builtin_popcount(mask) == 1) {
        assert((a ^ b) == mask);
        return {a, b};
    }
    vector<int> res;
    vector<int> bits;
    for (int i = 0; i < n; ++i) {
        if (mask & (1 << i)) {
            bits.push_back(i);
        }
    }

    for (int i : bits) {
        if ((b & (1 << i)) != (a & (1 << i)) ) {
            bool flag = false;
            if (a & (1 << i)) {
                flag = true;
                a ^= (1 << i);
                b ^= (1 << i);
            }

            int j = (i == bits[0] ? bits[1] : bits[0]);

            for (int el : solve(n, a, (1 << j) ^ a, mask ^ (1 << i))) {
                res.push_back(el);
            }
            for (int el : solve(n, (1 << j) ^ a, b ^ (1 << i), mask ^ (1 << i))) {
                res.push_back(el ^ (1 << i));
            }


            if (flag) {
                for (int k = 0; k < sz(res); ++k) {
                    res[k] ^= (1 << i);
                }
                a ^= (1 << i);
                b ^= (1 << i);
            }

            // cout << "! ";
            // for (int i = 0; i < sz(res); ++i) {
            //     cout << res[i] << " ";
            // }
            // cout << endl;

            assert(res[0] == a && res.back() == b);
            break;
        }

    }

    return res;
}

