						}
						p[i][j].pb(i);
						rep(0,l,minpow(2,i-1)-1){
							if(p[i-1][j][l]==i-1)p[i][j].pb(i-j);
							else if(p[i-1][j][l]>=i-j)p[i][j].pb(p[i-1][j][l]+1);
							else p[i][j].pb(p[i-1][j][l]);
						}		
					}				
				}
			}	
		}
