#include <bits/stdc++.h>
using namespace std;

const int B = 18;
int mark[B];
int numbers[1 << B];
int n, a, b;

void solve(int st, int en, int set_bit, int rest){
    for(int i = st ; i <= en ; i++){

        numbers[i] |= set_bit;
    }    

    if(rest <= 1){
        return;
    }

    int find = -1, se = -1;

    for(int j = 0 ; j < n ; j++){
        if(!mark[j]){
            if(find == -1)
                find = j;
            else
                se = j;
        }
    }

    assert(find != -1 && se != -1);

    mark[find] = true;

    int mid = (st + en) >> 1;

    numbers[mid] = numbers[mid + 1] = numbers[st] ^ (1 << se);

    if(numbers[mid] & (1 << find)){
        numbers[mid] ^= (1 << find);
        numbers[mid + 1] ^= (1 << find);
    }

    solve(st, mid, numbers[st] & (1 << find), rest - 1);
    solve(mid + 1, en, numbers[en] & (1 << find), rest - 1);

    mark[find] = false;
}

int main() {
    cin >> n >> a >> b;

    numbers[0] = a;
    numbers[(1 << n) - 1] = b;

    if(n == 1){
        cout << 1 << " " << 0 << endl;
        return 0;
    }

    if(__builtin_popcount(a ^ b) & 1){
        for(int i = 0 ; i < n ; i++){
            if((a & (1 << i)) != (b & (1 << i))){
                int ss = (i + 1) % n;

                mark[i] = true;
                int mid = ((1 << n) - 1) >> 1;

                numbers[mid] = numbers[mid + 1] = numbers[0] ^ (1 << ss);

                if(numbers[mid] & (1 << i)){
                    numbers[mid] ^= (1 << i);
                    numbers[mid + 1] ^= (1 << i);
                }

                solve(0, mid, (a & (1 << i)), n - 1);
                solve(mid + 1, (1 << n) - 1, (b & (1 << i)), n - 1);
                break;
            }
        }

        cout << "YES" << endl;

        for(int i = 0 ; i < (1 << n) ; i++){
            cout << numbers[i] << ' ';
        }

        cout << endl;
    }else{
        cout << "NO" << endl;
    }

	return 0;
}

