	Hopcroft_Karp H(n);
	For(i,0,n){
		For(j,0,N){
			ll y = (i^(1<<j));
			adj[i].pb(y);
			adj[y].pb(i);
			H.addEdge(i+1,y+1);
		}
	}

	ll dist[n];
	memset(dist,-1,sizeof(dist));
	dist[a]=0;
	queue<ll> q;
	q.push(a);

	while(q.size()>0){
		ll c = q.front();q.pop();
		for(ll x:adj[c]){
			if(dist[x]==-1){
				dist[x] = dist[c]+1;
				q.push(x);
			}
		}
	}

	ll size_matching = H.max_matching();

	// cout<<dist[b]<<" "<<size_matching<<endl;

	if(dist[b]%2==0){
		cout<<"NO"<<endl;return 0;
	}else{
		vector<ll> left,right;
		bool visited[n];
		memset(visited,0,sizeof(visited));
		bool isL = 0;
		ll temp = a;

		while(temp>0){
			if(temp%2==1) isL = !isL;
			temp = temp/2;
		}

		ll A=a,B=b;


		while(left.size()+right.size()!=n){
			ll x,y;
			if(isL){
				y = H.matchL[A+1]-1;
				x = H.matchR[B+1]-1;
				visited[A]=1;
				visited[B]=1;
				visited[x]=1;
				visited[y]=1;
				left.pb(A);
				right.pb(B);
				left.pb(y);
				right.pb(x);
				A=-1;
				B=-1;
				for(ll t:adj[y]){
					if(!visited[t] && !visited[H.matchL[t+1]-1]){
						A = t;
						visited[t]=1;
						break;
					}
				}
				for(ll t:adj[x]){
					if(!visited[t] && !visited[H.matchR[t+1]-1]){
						B = t;
