vector<int>solve(int N,int L,int R){
	if(N==1)return {L,R};
	int dif=(L^R)&-(L^R);
	vector<int>l,r;
	int ldif=(L&dif-1)+(L/dif/2*dif);
	int rdif=(R&dif-1)+(R/dif/2*dif);
	l=solve(N-1,ldif,ldif^1);
	r=solve(N-1,ldif^1,rdif);
	for(int &i:l){
		i=(i&dif-1)+(i/dif*dif<<1)+dif*(bool)(L&dif);
	}
	for(int &i:r){
		i=(i&dif-1)+(i/dif*dif<<1)+dif*(bool)(R&dif);
	}
	l.insert(l.end(),all(r));
	return l;
}
