//xにyをk桁目に挟みいれる(yは0か1)
inline int ibit(int k, int x, int y) {
	int lo = x % (1 << k);
	int hi = (x - lo) * 2;
	return hi + (y << k) + lo;
}
//xからk桁目を外す
inline int obit(int k, int x) {
	int lo = x % (1 << k);
	int hi = ((((x - lo) >> k) / 2) << k);
	return hi + lo;
}

vector<int> f(int x, int b) {
	vector<int>vec;
	if (b == 1) {
		vec.push_back(0);
		vec.push_back(1);
		return vec;
	}
	int k;
	for (k = 0; true; k++) {
		if ((x & (1 << k))) {
			break;
		}
	}
	int z = 1;
	int y = obit(k, x);
	vector<int>fi = f(z, b - 1);
	vector<int>se = f(z ^ y, b - 1);
	for (auto elm : fi) {
		vec.push_back(ibit(k, elm, 0));
	}
	for (auto elm : se) {
		vec.push_back(ibit(k, elm ^ z, 1));
	}
	assert(vec.back() == x);
	return vec;
}

inline int bitnum(int S) {
	int res = 0;
	for (int i = 0; i < 30; ++i) {
		res += ((S & (1 << i)) ? 1 : 0);
	}
	return res;
}

