int CHANGE(int from, int digit, int val) {
    int to = from % beki[digit];
    to += (from / beki[digit+1]) * beki[digit+1];
    to += val * beki[digit];
    //cerr << "CALLED CHANGE " << from << " " << digit << " "<< val << " " << to << endl;
    return to;
}

void query(int start, int diff, int digit, int val) {
    //cerr << "CALLED query " << start << " " << diff << " " << digit << " " << val << endl;
    int start_copy = start / beki[digit+1];
    start = start % beki[digit];
    start += start_copy * beki[digit];
    if(digit < diff) diff--;
    for(int i = 0; i < swap_first[N-2].size(); i++) {
        int copied = swap_first[N-2][i];
        int val_zero = copied & 1;
        int val_diff = (copied >> diff) & 1;
        copied = CHANGE(copied, 0, val_diff);
        copied = CHANGE(copied, diff, val_zero);
        int now = copied ^ start;
        now = (now % beki[digit]) + (now / beki[digit]) * beki[digit+1];
        now += beki[digit] * val;
        if(already.find(now) == already.end()) {
            ans.push_back(now);
            already.insert(now);
        }
        //cerr << " a " << now << endl;
    }
