int countDifferentBits(int num1, int num2)
{
	int value = num1 ^ num2;
	int ret = 0;
	while (value > 0) {
		if (value % 2 == 1) ++ret;
		value = value >> 1;
	}
	return ret;
}

int changeLeastSignificant(int num, int compare)
{
	int cnt = 0;
	int num_tmp = num;
	int cmp_tmp = compare;

	while (num_tmp % 2 == cmp_tmp % 2) {
		num_tmp = num_tmp >> 1;
		cmp_tmp = cmp_tmp >> 1;
		++cnt;
	}

	num = (num_tmp % 2) ? num - (1 << cnt) : num + (1 << cnt);

	return num;
}

