int bitcnt(int x)
{
	int pd=0;
	while(x){pd^=(x&1);x>>=1;}
	return pd;
}
int lowbit(int x){return x&(-x);}
int A,B,ans[MAXN+1][1<<MAXN];
void slove(int k,int A,int B,int *a,int l,int r)
{
	if(k==1){a[l]=A;a[r]=B;return ;}
	int C=A^B,t=lowbit(C);
	int tA=A%t+A/(t<<1)*t,tB=B%t+B/(t<<1)*t,tC=tA^1;
	int mid=(l+r)>>1;
	slove(k-1,tA,tC,ans[k-1],l,mid);
	slove(k-1,tC,tB,ans[k-1],mid+1,r);
	for(int i=l;i<=mid;i++)
	a[i]=ans[k-1][i]%t+ans[k-1][i]/t*(t<<1)+((A&t)?t:0);
	for(int i=mid+1;i<=r;i++)
	a[i]=ans[k-1][i]%t+ans[k-1][i]/t*(t<<1)+((B&t)?t:0);
}
