{
	scanf("%d",&n);
	scanf("%d%d",&A,&B);
	if(bitcnt(A)==bitcnt(B)){puts("NO");return 0;}
	slove(n,A,B,ans[n],0,(1<<n)-1);
	puts("YES");
	for(int i=0;i<(1<<n);i++)printf("%d ",ans[n][i]);
}

