        res[st] = a;
        res[st + 1] = b;
        return;
    }
    int id = 0;
    int c = a ^ b;
    while ((c & 1) == 0) {
        c /= 2;
        ++id;
    }
    a = (a & ((1 << id) - 1)) + ((a >> (id + 1)) << id);
    b = (b & ((1 << id) - 1)) + ((b >> (id + 1)) << id);
    int m = (st + e) / 2;
    solve(n - 1, a, a ^ 1, st, m);
    solve(n - 1, a ^ 1, b, m, e);
    c = (a >> id) & 1;
    for (int i = st; i < m; ++i) {
        res[i] = (res[i] & ((1 << id) - 1)) + ((res[i] >> id) << (id + 1)) + (c << id);

    }
    c ^= 1;
    for (int i = m; i < e; ++i) {
        res[i] = (res[i] & ((1 << id) - 1)) + ((res[i] >> id) << (id + 1)) + (c << id);
    }

}

