	vector<int> ngs;
	rep(i,17){
		if((1<<i)&a)ngs.push_back(i);
	}
	sss=ngs.size();
	if(sss%2==0){
		cout<<"NO"<<endl;
		return 0;
	}
	int all=1<<n;
	rep(i,n)v[i].resize(all);
	rep(i,n){
		int cur=0;
		rep(j,all){
			if((j%(1<<i))==0&&(j%(1<<(i+1)))!=0)cur=1-cur;
			v[i][j]=cur;
		}
	}
	rep(i,all)v[n-1][i]=1-v[n-1][i];
	swap(v[n-1],v[ngs[0]]);
	vector<int> ans(all);
	rep(i,all){
		rep(j,n)ans[i]+=(1<<j)*v[j][i];
	}
	vector<int> pos(all);
	rep(i,all)pos[ans[i]]=i;
	int kk=ngs.size();
	rep(w,kk/2){
		int y=ngs[2*w+1],z=ngs[2*w+2];
		rep(i,all/4){
			if((ans[i]>>y)%2==1||(ans[i]>>z)%2==1)continue;
			int nxt=ans[i]+(1<<y)+(1<<z);
			int idx=pos[nxt];
			swap(pos[nxt],pos[ans[i]]);
			swap(ans[idx],ans[i]);
		}
	}
	cout<<"YES"<<endl;
	rep(i,all)ans[i]=ans[i]^b;
	vector<int> cnt(all);
	rep(i,all-1){
		int ret=ans[i]^ans[i+1];
		assert(__builtin_popcount(ret)==1);
	}
	rep(i,all)cout<<ans[i]<<" ";
	cout<<endl;
	return 0;
}

