using namespace std;

int N, A, B;

vector<int> dfs(int bit, int a, int b){
    vector<int> ret;
    int dif = -1, cnt = 0;
    for(int i = 0; i < N; i++){
        if(bit & (1 << i))cnt++;
        if((bit & (a ^ b)) & (1 << i))dif = i;//difはここで固定するビット
    }
    if(cnt == 1){
        ret.push_back(dif);
        return ret;
    }
    //aとbの間のc(固定されてないビットでaのビットを一つ変えたもの)を求める
    int next = -1;
    for(int i = 0; i < N; i++){
        if(dif == i)continue;
        if(bit & (1 << i))next = i;
    }
    vector<int> res1 = dfs(bit ^ (1 << dif), a, a ^ (1 << next));
    ret.insert(ret.end(), res1.begin(), res1.end());

    ret.push_back(dif);

    vector<int> res2 = dfs(bit ^ (1 << dif), a ^ (1 << next) ^ (1 << dif), b);
    ret.insert(ret.end(), res2.begin(), res2.end());

    return ret;
}

int main(){
    cin >> N >> A >> B;
    int xr = (A ^ B);
    int cnt = 0;
    for(int i = 0; i < N; i++){
        if(xr & (1 << i))cnt++;
    }
    if(cnt % 2 == 0){
        printf("NO\n");
        return 0;
    }
    printf("YES\n");
    vector<int> ans = dfs((1 << N) - 1, A, B);
    int val = A;
    for(int i = 0; i < (int)ans.size(); i++){
        printf("%d ", val);
        val ^= (1 << ans[i]);
    }
    printf("%d\n", val);

    return 0;
}

