	if (c == 1) return std::vector<LL>{a, b};

	LL diff_bit;
	std::vector<LL>res;
	rep(i, N)
	{
		if (((a ^ b) >> i) & 1LL)
		{
			diff_bit = i;
			break;
		}
	}
	auto res1 = f(erase_bit(a, diff_bit), erase_bit(a, diff_bit) ^ 1LL, c - 1), res2 = f(erase_bit(a, diff_bit) ^ 1LL, erase_bit(b, diff_bit), c - 1);
	for (auto i : res1) res.push_back(push_bit(i, diff_bit, (a >> diff_bit) & 1LL));
	for (auto i : res2) res.push_back(push_bit(i, diff_bit, (b >> diff_bit) & 1LL));
	return res;
}

