long long n, a, b;
int memo[20] = {0};
vector<long long> v, ls;
int d[4] = {0, 1, 1, 0};
bool ch = 0;

void solve();

int main() {
  cin >> n >> a >> b;
  for(int i = 0; i < n; ++i) memo[i] = i;
  for(int i = 0; i < n; ++i)
    if((a >> i) % 2 != (b >> i) % 2) {
      ls.push_back(i);
      if(ch) {
        cout << "NO" << endl;
        return 0;
      }
      // swap(memo[n - 1], memo[i]);
      // ch = 1;
    }
  if(!ch) {
    cout << "NO" << endl;
    return 0;
  }
  cout << "YES" << endl;
  solve();
  for(int i = 0; i < v.size(); ++i) {
    cout << (a ^ v[i]);
    if(i != v.size() - 1) cout << " ";
  }
  cout << endl;
  return 0;
}

void solve() {
  v.assign((1 << n), 0);
  int vsize = v.size();
  for(int i = 0; i < n; ++i) {
    int cnt = 0, now = 0, mnum = (1 << i);
    for(int j = 0; j < vsize; ++j) {
      if(d[now]) v[j] += 1 << memo[i];
      ++cnt;
      if(cnt == mnum) {
        cnt = 0;
        ++now;
        now %= 4;
      }
    }
  }
  if(ls.size() == 1) {
    for(int i = 0; vsize; ++i) {
      v[i] ^= (1 << (n - 1)) + (1 << ls[0]);
    }
    ch = 1;
    return;
  }
  for(int i = 1; i < (1 << n) - 1; ++i) {
    int now = v[i + 1] ^ v[(1 << n) - 1], cnt = 0, x = 0;
    for(int j = 0; j < n; ++j)
      if((now >> j) % 2 == 1) ++cnt;
    if(cnt > 1) continue;
    now = v[i];
    for(int j = 0; j < n; ++j)
      if((now >> j) % 2 == 1) {
        x += (1 << j);
        ++cnt;
      }
    if(ls.size() != cnt) continue;
    for(int j = 0; j < ls.size(); ++i) {
      x ^= (1 << ls[j]);
    }
    for(int j = 0; j < vsize; ++j) v[i] ^= x;
    reverse(v.begin() + i + 1, v.end());
    ch = 1;
    return;
  }
}

