using namespace std;

uint32_t set_bit(uint32_t val, int pos, int b)
{
	uint32_t mask = (-1) ^ (1 << pos);
	return (val & mask) | (b << pos);
}

vector<uint32_t> solve_one(uint32_t a, uint32_t b)
{
	return {a, b};
}

vector<uint32_t> solve(uint32_t a, uint32_t b, uint32_t sel, uint32_t n)
{
	if (n == 1) {
		return solve_one(a, b);
	}

	int p = 0;
	while (true) {
		uint32_t mask = (1U << p);
		if (sel & mask && (a ^ b) & mask) {
			break;
		}
		p++;
	}

	int c_p = 0;
	while (!(sel & (1U << c_p)) || p == c_p) {
		c_p++;
	}

	uint32_t n_sel = sel ^ (1U << p);
	uint32_t c     = a ^ (1U << c_p);

	vector<uint32_t> first_half = solve(a, c, n_sel, n - 1);
	vector<uint32_t> last_half  = solve(c, b, n_sel, n - 1);

	for (auto& elem : first_half) {
		elem = set_bit(elem, p, (a >> p) & 1);
	}
	for (auto& elem : last_half) {
		elem = set_bit(elem, p, (b >> p) & 1);
	}

	first_half.insert(first_half.end(), last_half.begin(), last_half.end());

	return first_half;
}

int main() {
	uint32_t n, a, b; cin >> n >> a >> b;

	uint32_t d = a ^ b;
	int bits = 0;

	{
		for (int i = 0; i < 32; i++) {
			if (d & (1U << i)) bits++;
		}
	}

	if ((bits & 1) == 0) {
		cout << "NO" << endl;
		return 0;
	}

	cout << "YES" << endl;
	vector<uint32_t> series = solve(a, b, (1U << n) - 1, n);
	for (auto it = series.begin(); it != series.end(); it++) {
		cout << *it;
		if (it + 1 != series.end()) {
			cout << " ";
		}
	}
	cout << endl;

	return 0;
}

