#include<bits/stdc++.h>
using namespace std;

int N,A,B;

vector<int> unit(int bit, int A, int B)
{
    vector<int> ret;
    int cnt = 0, dif = -1;
    for(int i = 0; i < N; i++)
    {
        if(bit & (1 << i))cnt++;
        if(((A ^ B) & bit) & (1 << i))dif = i;
    }

    if(cnt == 1)
    {
        ret.push_back(dif);
        return ret;
    }

    int next;
    for(int i = 0; i < N; i++)if(i != dif && bit & (1 << i))next = i;

    vector<int> ret1 = unit(bit ^ (1 << dif), A, A ^ (1 << next));
    ret.insert(ret.end(), ret1.begin(), ret1.end());

    ret.push_back(dif);

    vector<int> ret2 = unit(bit ^ (1 << dif), A ^ (1 << next) ^ (1 << dif), B);
    ret.insert(ret.end(), ret2.begin(), ret2.end());

    return ret;
}

