vector<int> search(int a, int b, int n){
    vector<int> ans;
    if(n == 0){
        ans.push_back(a);
        ans.push_back(b);
        return ans;
    }
    int m = (1<<n);
    if((a&m)&&(b&m)){
        vector<int> tmp = search(a-m, b-m, n-1);
        vector<int> tmp1 = search(a-m, tmp[1], n-1);
        ans.push_back(a);
        for(int i = 0; i < tmp1.size(); i++) ans.push_back(tmp1[i]);
        for(int i = 1; i < tmp.size(); i++) ans.push_back(tmp[i]+m);
    }else if((!(a&m))&&(!(b&m))){
        vector<int> tmp = search(a, b, n-1);
        vector<int> tmp1 = search(a, tmp[1], n-1);
        ans.push_back(a);
        //cout << m << endl;
        for(int i = 0; i < tmp1.size(); i++) ans.push_back(tmp1[i]+m);
        for(int i = 1; i < tmp.size(); i++) ans.push_back(tmp[i]);
    }else if(a&m){
        int a_;
        if(a-m == 0) a_ = m+1;
        else a_ = a-1;
        vector<int> tmp = search(a-m, a_-m, n-1);
        vector<int> tmp1 = search(a_-m, b, n-1);
        for(int i = 0; i < tmp.size(); i++) ans.push_back(tmp[i]+m);
        for(int i = 0; i < tmp1.size(); i++) ans.push_back(tmp1[i]);
    }else{
        int a_;
        if(a == 0) a_ = 1;
        else a_ = a-1;
        vector<int> tmp = search(a, a_, n-1);
        vector<int> tmp1 = search(a_, b-m, n-1);
        for(int i = 0; i < tmp.size(); i++) ans.push_back(tmp[i]);
        for(int i = 0; i < tmp1.size(); i++) ans.push_back(tmp1[i]+m);
    }
    return ans;
}

