typedef vector<ll> vll;

vi Solve(int n, int a, int b) {
  vi result;
  b ^= a;
  vi x, y;
  for (int i = 0; i < n; ++i) if (b & (1 << i)) x.push_back(i); else y.push_back(i);
  //cerr << " x: "; for (int t : x) cerr << t << " "; cerr << endl;
  //cerr << " y: "; for (int t : y) cerr << t << " "; cerr << endl;
  if (x.size() % 2 == 0) return vi();
  if (y.empty()) {
    if (x.size() == 1) {
      result = {0, 1};
    } else {
      int l = 1 << (n - 1);
      int m = l - 2;
      vi v1 = Solve(n - 1, 0, m);
      vi v2 = Solve(n - 1, m, m + 1);
      assert(!v1.empty() && !v2.empty());
      for (int t : v1) result.push_back(t);
      for (int t : v2) result.push_back(l | t);
    }
  } else {
    int l = 1 << (n - 1);    
    int m = 0;
    for (int i = 0; i < x.size() - 1; ++i) m |= 1 << (n - 2 - i);
    vi v1 = Solve(n - 1, 0, m + 1);
    vi v2 = Solve(n - 1, m + 1, m);
    assert(!v1.empty() && !v2.empty());
    for (int t : v1) result.push_back(t);
    for (int t : v2) result.push_back(l | t);
    for (int& t : result) {
      int cur = 0;
      for (int j = 0; j < n; ++j) if (t & (1 << j)) {
        int i = n - 1 - j;
        if (i < x.size()) cur |= 1 << x[i]; else cur |= 1 << y[i - x.size()];
      }
      t = cur;
    }
  }
  for (int& t : result) t ^= a;
  return result;
}

int main()
{
  int n, a, b;
  cin >> n >> a >> b;
  vi ans = Solve(n, a, b);
  if (ans.empty()) {
    cout << "NO" << endl;
  } else {
    cout << "YES" << endl;
    for (int x : ans) cout << x << " ";
    cout << endl;
  }

  return 0;
}

