void Solve(int lvl, int a, int b, int got)
{
    for (int i = 0; i < n; i++) if ((a & 1 << i) != (b & 1 << i) && !(got & 1 << i)) {
        got |= 1 << i;
        int lst = a;
        for (int j = 1; j < 1 << lvl; j++) {
