	int n, a, b;
	cin >> n >> a >> b;
	if(__builtin_popcount(a ^ b) % 2 == 0){
		cout << "NO" << endl;
		return 0;
	}

	const int m = (1 << n);
	vector<int> r(m);
	for(int i = 0; i < m; ++i){
		r[i] = a ^ i ^ (i >> 1);
	}

	int p = 0;
	for(int i = 0; i < m; ++i){
		if(r[i] == b){ p = i; }
	}

	int offset = 0;
	for(int s = n - 1; s > 0; --s){
		const int step = (1 << s);
		if(p < offset + step){
			reverse(r.begin() + offset + 1, r.begin() + offset + 2 * step);
			for(int i = 0; i < m; ++i){
				if(r[i] == b){ p = i; }
			}
		}
		offset += step;
	}

	cout << "YES" << endl;
	for(int i = 0; i < m; ++i){
		cout << r[i] << " ";
	}
	cout << endl;
	return 0;
}

