int N;
vector<bool> itbi(int n){
	vector<bool> b(N);
	for(int i=0;i<N;i++){
		b[i]=n%2;
		n=n/2;
	}
	return b;
}
int bti(vector<bool> b){
	int i,r=0;
	for(i=0;i<N;i++){
		if(b[i]) r+=pow(2,i);
	}
	return r;
}
int main(){
