vector<int> one(int k) {
	if(k == 1) {
		vector<int> vec;
		vec.pb(0);
		vec.pb(1);
		return vec;
	}
	else {
		vi vec = one(k - 1);
		int n = sz(vec);
		vi res(n * 2);
		rep(i, 0, n) {
			res[i] = vec[i];
		}
		int bit = (1 << (k - 1)) ^ (1 << (k - 2));
		rep(i, 0, sz(vec)) {
			res[i + n] = vec[i] ^ bit;
		}
		return res;
	}
}

int sb(int bit, int a, int b) {
	int va = bit & (1 << a);
	int vb = bit & (1 << b);
	bit ^= va;
	bit ^= vb;
	va = min(va, 1);
	vb = min(vb, 1);
	swap(va, vb);
	bit ^= (1 << a) * va;
	bit ^= (1 << b) * vb;
	return bit;
}

vector<int> shift(int k, int a, const vi& vec) { //k bit, a bit is one
	int n = sz(vec);
	vector<int> res(n * 2);
	vector<int> on = one(k);
	rep(i, 0, n) res[i] = sb(on[i], k - a, k - 1);
	int bit = (1 << (k - a)) ^ (1 << k);
	rep(i, 0, n) res[i + n] = bit ^ vec[i];
	rep(i, 0, n * 2) res[i] = sb(res[i], k - a, k);
	return res;
}

vector<int> get(int k, int a) {
	if(a == 1) return one(k);
	vector<int> vec = shift(k - 2, a - 2, get(k - 2, a - 2));
	vector<int> res(1 << k);
	vector<int> on = one(k - 1);
	rep(i, 0, (1 << (k - 1))) {
		res[i] = on[i];
	}
	int bit = (1 << (k - 1)) ^ (1 << (k - 2));
	rep(i, 0, (1 << (k - 1))) {
		res[i + (1 << (k - 1))] = bit ^ vec[i];
	}
	return res;
}

