	if(pop(a) == pop(b)){
		cout << "NO" << endl;
		return 0;
	}

	vector<int> ans = calc(n, a, b);
	cout << "YES" << endl;
	for(int i = 0; i < ans.size(); i++) cout << ans[i] << " "; cout << endl;

	return 0;
}

