class UnionFind {
    public:
    //各頂点の親の番号を格納する。その頂点自身が親だった場合は-(その集合のサイズ)を入れる。
    vector<int> Parent;

    //クラスを作るときは、Parentの値を全て-1にする。
    //以下のようにすると全てバラバラの頂点として解釈できる。
    UnionFind(int N) {
        Parent = vector<int>(N, -1);
    }

    //Aがどのグループに属しているか調べる
    int root(int A) {
        if (Parent[A] < 0) return A;
        return Parent[A] = root(Parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    int size(int A) {
        return -Parent[root(A)];//先祖をrootで取っておきたい。
    }

    //AとBをくっ付ける
    bool connect(int A, int B) {
        //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        if (A == B) {
            //すでにくっついてるからくっ付けない
            return false;
        }

        //大きい方(A)に小さいほう(B)をくっ付けたい
        //大小が逆だったらAとBをひっくり返す。
        if (size(A) < size(B)) swap(A, B);

        //Aのサイズを更新する
        Parent[A] += Parent[B];
        //Bの親をAに変更する
        Parent[B] = A;

        return true;
    }
};

//dfs(n,a,b,0,(1<<n)-1);として呼ぶ
void dfs(int n, int a, int b, int start_i, int end_i, vector<int>& p){
  if(n==1){
    p[start_i]=a;
    p[end_i]=b;
    return;
  }
  int x;
  REP(i,n){
    if((a>>i)%2 != (b>>i)%2){//2^iの桁の値が異なる時
      x = i;
      break;
    }
  }
  int fa=0,fb=0;//a,bからxビット目を除いた値
  REP(i,n){
    if(i==x)continue;
    if(i<x){
      fa += ((a>>i)%2)<<i;
      fb += ((b>>i)%2)<<i;
    }else{
      fa += ((a>>i)%2)<<(i-1);
      fb += ((b>>i)%2)<<(i-1);
    }
  }
  int c;//fa,fbと立っているビットの数の偶奇が異なるもの
  int last_ = fa%2;
  c = (fa>>1)<<1 + (last_+1)%2;
  dfs(n-1, fa, c, start_i, start_i+(1<<(n-1))-1, p);
  dfs(n-1, c, fb, start_i+(1<<(n-1)), end_i, p);
  int temp;
  REP(i,1<<(n-1)){
    temp = 0;
    REP(j,n){
      if(j<x){
        temp += ((p[start_i+i]>>j)%2)<<j;
      }else if(j==x){
        temp += ((a>>x)%2)<<x;
      }else{
        temp += ((p[start_i+i]>>(j-1))%2)<<j;
      }
    }
    p[start_i+i] = temp;
  }
  for(int i=start_i+(1<<(n-1));i<=end_i;i++){
    temp = 0;
    REP(j,n){
      if(j<x){
        temp += ((p[i]>>j)%2)<<j;
      }else if(j==x){
        temp += ((b>>x)%2)<<x;
      }else{
        temp += ((p[i]>>(j-1))%2)<<j;
      }
    }
    p[i] = temp;
  }
  return;
}


