int del(int a, int x){
	return (a & ((1 << x) - 1)) | ((a & (~((1 << (x + 1)) - 1))) >> 1);
}

int ins(int a, int x, int val){
	return (a & ((1 << x) - 1)) | (val << x) | ((a & (~((1 << x) - 1))) << 1);
}

void calc(int l, int r, int a, int b){
	if (l == r - 2){
		ans[l] = a;
		ans[l + 1] = b;
		return;
	}
	int m = (l + r) / 2;
	int x = __builtin_ctz(a ^ b);
	int ax = del(a, x);
	int bx = del(b, x);
	int c = ax ^ 1;
	calc(l, m, ax, c);
	calc(m, r, c, bx);
	fore(i, l, m)
		ans[i] = ins(ans[i], x, (a >> x) & 1);
	fore(i, m, r)
		ans[i] = ins(ans[i], x, (b >> x) & 1);
}

