const int maxn = 17;

int swap(int v, int p1, int p2) {
	if (((v >> p1)&1) != ((v>>p2)&1)) {
		return v ^ (1<<p1) ^ (1<<p2);
	} else return v;
}

vector<int> build(int n, int A, int B) {
	if (n == 1) {
		vector<int> ret;
		ret.push_back(A); ret.push_back(B);
		return ret;
	} else {
		vector<int> ret;
		int cnt = 0, t = A^B;
		for (int i = 0; i < n; i++) {
			if (t & (1<<i)) {
				++ cnt;
			}
		}
		if (cnt == 1) {
			int p = 0;
			for (int i = 0; i < n; i++) {
				if (t & (1<<i)) {
					p = i;
					break;
				}
			}
			A = swap(A, p, n-1); B = swap(B, p, n-1);
			vector<int> a = build(n-1, 0, 1);
			for (int i = 0; i < a.size(); i++) ret.push_back(a[i]);
			for (int i = int(a.size()-1); i >= 0; i--) ret.push_back((1<<(n-1))|a[i]);
			for (int i = 0; i < ret.size(); i++) ret[i] ^= A;
			for (int i = 0; i < ret.size(); i++) ret[i] = swap(ret[i], p, n-1);
			return ret;
		} else if (cnt < n) {
			int p = 0;
			for (int i = 0; i < n; i++) {
				if (!(t & (1<<i))) {
					p = i;
					break;
				}
			}
			A = swap(A, p, 0); B = swap(B, p, 0);
			int q = 0;
			if (A & 1) {
				q = 1;
				A ^= q;
				B ^= q;
			}
			vector<int> a = build(n-1, A>>1, B>>1);
			vector<int> b = build(n-1, a[0], a[1]);
			vector<int> ret;
			ret.push_back(a[0]<<1);
			for (int i = 0; i < b.size(); i++) ret.push_back(b[i]<<1|1);
			for (int i = 1; i < a.size(); i++) ret.push_back(a[i]<<1);
			for (int i = 0; i < ret.size(); i++) ret[i] ^= q;
			for (int i = 0; i < ret.size(); i++) ret[i] = swap(ret[i], p, 0);
			return ret;
		} else {
			vector<int> ret;
			vector<int> a = build(n-1, 0, 1);
			vector<int> b = build(n-1, 1, (1<<(n-1))-1);
			for (int i = 0; i < a.size(); i++) ret.push_back(a[i]);
			for (int i = 0; i < b.size(); i++) ret.push_back((1<<(n-1)) | b[i]);
			for (int i = 0; i < ret.size(); i++) ret[i] ^= A;
			return ret;
		}
	}
}

int n, A, B;

int main() {
	scanf("%d%d%d", &n, &A, &B);
	int t = A^B, cnt = 0;
	for (int i = 0; i < n; i++) {
