const int N = 300100;
const int INF = (int) 1e9;

int n, a, b, dist[N], match[N];
vector <int> g[N];

bool bfs(int n) {
    queue <int> q;
    for (int i = 1; i <= n; i++) {
        if (match[i] == 0) {
            q.push(i);
            dist[i] = 0;
        } else {
            dist[i] = INF;
        }
    }
    dist[0] = INF;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (u == 0) {
            continue;
        }
        for (int i = 0; i < g[u].size(); i++) {
            int v = g[u][i];
            if (dist[match[v]] == INF) {
                q.push(match[v]);
                dist[match[v]] = dist[u] + 1;
            }
        }
    }
    return dist[0] != INF;
}

bool dfs(int u) {
    if (u == 0) {
        return true;
    }
    for (int i = 0; i < g[u].size(); i++) {
        int v = g[u][i];
        if (dist[match[v]] == dist[u] + 1 && dfs(match[v])) {
            match[v] = u;
            match[u] = v;
            return true;
        }
    }
    dist[u] = INF;
    return false;
}

int hopcroft_karp(int n, int m) {
    for (int i = 0; i <= n + m; i++) {
        match[i] = 0;
    }
    int ret = 0;
    while (bfs(n)) {
        for (int i = 1; i <= n; i++) {
            if (match[i] == 0 && dfs(i)) {
                ++ret;
            }
        }
    }
    return ret;
}

