vector<int> gray (int n) {
  if (n == 1) return {0, 1};

  vector<int> a = gray(n - 1);
  vector<int> b = a;
  reverse(b.begin(), b.end());
  for (int i = 0; i < (int) b.size(); i++) {
    a.push_back(b[i] | 1 << (n - 1));
  }

  return a;
}

int swap_bit (int mask, int i, int j) {
  if (i == j) return mask;

  int ith = (mask >> i) & 1;
  int jth = (mask >> j) & 1;
  mask -= ith << i;
  mask -= jth << j;

  mask += ith << j;
  mask += jth << i;

  return mask;
}

int main () {
  int n, a, b;
  cin >> n >> a >> b;

  if (__builtin_popcount(a ^ b) != 1) {
    failure();
  }

  vector<int> ans = gray(n);

  int dbit = 31 - __builtin_clz(a ^ b);

  for (int i = 0; i < (int) ans.size(); i++) {
    ans[i] = swap_bit(ans[i], dbit, n - 1);
  }

  for (int i = 0; i < (int) ans.size(); i++) {
    ans[i] ^= a;
  }

  cout << "YES" << endl;
  for (int i = 0; i < (int) ans.size(); i++) {
    cout << ans[i] << " ";
  }
  cout << endl;
}

