int swap_bits(int x, int i, int j) {
	if (((x & (1 << i)) > 0) == ((x & (1 << j)) > 0)) return x;
	return x ^ (1 << i) ^ (1 << j);
}

vector<int> solve(int n, int a, int b) {
	if (n <= 1) {
		vector<int> p(1 << n);
		f(i, 1 << n) {
			p[i] = i;
		}

		do {
			if (p[0] == a && p.back() == b) {
				bool fail = false;
				f(i, (1 << n) - 1) {
					if (__builtin_popcount(p[i] ^ p[i + 1]) != 1) {
						fail = true;
						break;
					}
				}
				if (!fail) {
					return p;
				}
			}
		} while (next_permutation(p.begin(), p.end()));
		assert(false);
	} else {
		int diff = -1;
		f(j, n) {
			if ((a ^ b) & (1 << j)) {
				diff = j;
			}
		}
		assert(diff != -1);
		int ST = ((a & (1 << diff))) > 0;

		int __a = (((swap_bits(a, diff, 0)) >> 1));
		int __b = (((swap_bits(b, diff, 0)) >> 1));


		vector<int> seq0 = solve(n - 1, __a, __a ^ 1);
		vector<int> seq1 = solve(n - 1, __a ^ 1, __b);
		// print diff, ST, "|", seq0, ":", seq1;
		vector<int> final;
		for (int x : seq0) {
			final.pb((x << 1) | ST);
		}
		for (int x : seq1) {
			final.pb((x << 1) ^ 1 ^ ST);
		}
		f(i, len(final)) {
			final[i] = swap_bits(final[i], 0, diff);
		}
		return final;
	}
}

