int del(int x, int i){
    int u=(x>>i)<<i, v=(x>>(i+1))<<(i+1);
    return x^u^(v>>1);
}

int add(int x, int i, int p){
    int u=(x>>i)<<i;
    return x^u^(u<<1)^(p<<i);
}

vector<int> dfs(int n, int a, int b){
    if(n==1) return {a, b};
    int pos;
    rep(i, n)if(((a>>i)&1)!=((b>>i)&1)) pos=i;
    int s=del(a, pos), t=del(b, pos);
    int u=s^1;
    vector<int> S=dfs(n-1, s, u), T=dfs(n-1, u, t);
    vector<int> ret;
    for(int x: S) ret.push_back(add(x, pos, (a>>pos)&1));
    for(int x: T) ret.push_back(add(x, pos, (b>>pos)&1));
    return ret;
}

