using namespace std;
ll read()
{
	ll x=0,f=1;
	char c=getchar();
	while(c>'9'||c<'0')
	{
		if(c=='-') f=-1;
		c=getchar();
	}
	while(c>='0'&&c<='9')
	{
		x=x*10+c-'0';
		c=getchar();
	}
	return f*x;
}
int n,A,B,top,col[N],num[20],as[N],now,len[20];
void work(int l,int r,int u,int v)
{
//	cout<<l<<" "<<r<<" "<<u<<" "<<v<<'\n';
	int mid=r+l>>1;
	if(r-l+1==2)
	{
		as[l]=u,as[r]=v;
		return ;
	}
	int pos,i,gate;
	for(pos=0;pos<n;++pos)
	{
		if((u&(1<<pos))^(v&(1<<pos))) break;
	}
	for(i=0;i<n;++i) if((u&(1<<i))||(v&(1<<i))) break;
	gate=(u&(~(1<<pos)))^(1<<i);
	work(l,mid,u&(~(1<<pos)),gate);work(mid+1,r,gate,v&(~(1<<pos)));
	if(u&1<<pos) for(int i=l;i<=mid;++i) as[i]|=1<<pos;
	else for(int i=mid+1;i<=r;++i)as[i]|=1<<pos; 
}

int main()
{
	n=read(),A=read(),B=read();
	if(n==1)
	{
		cout<<"YES"<<'\n';
		cout<<A<<" "<<B<<'\n';
		return 0;
	}
	top=1<<n;
	for(int i=1;i<top;++i) col[i]=col[i>>1]+(i&1);
	if(col[A]%2==col[B]%2) 
	{
		cout<<"NO"<<'\n';
		return 0;
	 } 
	 cout<<"YES"<<'\n';
	 work(1,top,A,B); 
	 for(int i=1;i<=top;++i) cout<<as[i]<<' ';
	return 0;
 }

