void dfs(vector<int>a,vector<int>b,vector<int>s){
    int n = s.size();
    int id = 0;
    if(s.size()==1){
        res.push_back(a);
        res.push_back(b);
        return;
    }
    for(int i=0;i<n;i++){
        if(a[s[i]]!=b[s[i]]){
            id = s[i];
            break;
        }
    }
    vector<int>t;
    for(int i=0;i<n;i++){
        if(s[i]!=id){
            t.push_back(s[i]);
        }
    }
    vector<int>c=a;
    for(int i=0;i<n;i++){
        if(s[i]!=id){
            c[s[i]] ^= 1;
            break;
        }
    }
    dfs(a,c,t);
    c[id] ^=1;
    dfs(c,b,t);
}

