vector <int> rec(int a, int b, int mask, int n) {
    if (n == 1) {
        return {a, b};
    } else {
        int id = 31 - __builtin_clz(a ^ b);
        //cout << a << ' ' << b << ' ' << (a & ~(1 << id)) << ' ' << (b & ~(1 << id)) << endl;
        int bt = (a >> id) & 1;
        mask |= (1 << id);
        int i;
        for (i = 0; ;++i) {
            if (!(mask & (1 << i))) {
                break;
            }
        }
        vector <int> f = rec(a & ~(1 << id), (a & ~(1 << id)) ^ (1 << i), mask, n - 1);
        vector <int> s = rec((a & ~(1 << id)) ^ (1 << i), b & ~(1 << id), mask, n - 1);
        vector <int> res;
        if (bt) {
            for (int x : f) res.push_back(x | (1 << id));
            for (int x : s) res.push_back(x);
        } else {
            for (int x : f) res.push_back(x);
            for (int x : s) res.push_back(x | (1 << id));
        }
        return res;
    }
}

