int popcount(int x) {
    int ret = 0;
    while (x) {
        ret += x & 1;
        x >>= 1;
    }
    return ret;
}

vector<int> solve(int n, int a, int b) {
    vector<int> ret;
    if (n == 1) {
        ret.push_back(a);
        ret.push_back(b);
        return ret;
    }
    if ((a & 1) != (b & 1)) {
        int x;
        for (int i = 0; i < (1 << n - 1); ++i) {
            if (i != (a >> 1) && i != (b >> 1) && (popcount(i ^ (a >> 1)) & 1) == 1) {
                x = i;
                break;
            }
        }
        vector<int> A = solve(n - 1, a >> 1, x);
        vector<int> B = solve(n - 1, x, b >> 1);
        for (int i : A) ret.push_back(i << 1 | (a & 1));
        for (int i : B) ret.push_back(i << 1 | (b & 1));
        return ret;
    }
    else {
        int x;
        vector<int> A = solve(n - 1, a >> 1, b >> 1);
        A.pop_back();
        vector<int> B = solve(n - 1, A.back(), b >> 1);
        for (int i : A) ret.push_back(i << 1 | (a & 1));
        for (int i : B) ret.push_back(i << 1 | ((a & 1) ^ 1));
        ret.push_back(b);
        return ret;
    }
}

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    int n, a, b;
    cin >> n >> a >> b;
    if ((popcount(a) + popcount(b) & 1) == 0) {
        printf("NO\n");
        return 0;
    }
    vector<int> ans = solve(n, a, b);
    printf("YES\n");
    for (int i : ans) printf("%d ", i);
    return 0;
}

