            while(x % k == 0) x /= k;
        }
    }
    if(x > 1) res.push_back(x);
    return res;
}


//コンビネーション
const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

vector<ll> solve(ll A, ll B, ll N){
  if(N == 1){
    return {A, B};
  }
  ll dif = -1;
  ll a_is_1 = 0;
  rep(i, N){
    if(((A>>i)&1) != ((B>>i)&1)){
      dif = i;
      if((A>>i)&1) a_is_1 = 1;
      else a_is_1 = 0;
    }
  }
  ll A_ = 0;
  ll B_ = 0;
  ll x = 0;
  rep(i, N){
    if(i == dif) continue;
    A_ += ((A>>i)&1)<<x;
    B_ += ((B>>i)&1)<<x;
    x++;
  }
  ll M = A_;
  if(M&1) M--;
  else M++;
  vector<ll> a = solve(A_, M, N-1);
  vector<ll> b = solve(M, B_, N-1);
  vector<ll> res;
  for(ll s: a){
    ll add = 0;
    ll point = 0;
    rep(i, N){
      if(i == dif){
        if(a_is_1 == 1) add += 1<<i;
      }else{
        add += ((s>>point)&1)<<i;
        point++;
      }
    }
    res.pb(add);
  }
  for(ll s: b){
    ll add = 0;
    ll point = 0;
    rep(i, N){
      if(i == dif){
        if(a_is_1 == 0) add += 1<<i;
      }else{
        add += ((s>>point)&1)<<i;
        point++;
      }
    }
    res.pb(add);
  }
  return res;
}

