      int tmp = now ^ (1 << j);
      if (!used[tmp]) {
        ans[i] = tmp;
        used[tmp] = true;
        now = tmp;
        kawatta = true;
        break;
      }
    }
  }
  REP(i, mx) cout << ans[i] << (i == mx - 1 ? '\n' : ' ');
  return 0;
}

