const int N = 18;

vector <int> make(int n, int diff){
	vector <int> res;
	if (n == 1){
		res.pb(0);
		res.pb(1);
		return res;
	}
	if (n == diff){
		vector <int> v = make(n-2, diff-2);
		for (int i = 0; i < v.size(); i++){
			if (i%2 == 0){
				res.pb(v[i]);
				res.pb(v[i] + (1 << (n-2)));
				res.pb(v[i] + (1 << (n-2)) + (1 << (n-1)));
				res.pb(v[i] + (1 << (n-1)));
			}
			else{
				res.pb(v[i] + (1 << (n-1)));
				res.pb(v[i] + (1 << (n-2)) + (1 << (n-1)));
				res.pb(v[i] + (1 << (n-2)));
				res.pb(v[i]);
			}
		}
		swap(res[res.size()-1], res[res.size()-3]);
	}
	else{
		vector <int> v = make(n-1, diff);
		for (int i = 0; i < v.size(); i++){
			if (i%2 == 0){
				res.pb(v[i]);
				res.pb(v[i] + (1 << (n-1)));
			}
			else{
				res.pb(v[i] + (1 << (n-1)));
				res.pb(v[i]);
			}
		}
		return res;
	}
}

