const int MAXN = (1 << 17);
bool used[MAXN];

vector<int> SolveRecursive(int N, int A, int B)
{
    DEBUG2("SOLVING " << N << " " << A << " " << B);
    if (N == 1)
    {
        vector<int> tmp;
        tmp.push_back(A);
        tmp.push_back(B);
        assert((A ^ B) == 1);
        return tmp;
    }

    int newB = B ^ A;

    int oneBit = -1;
    vector<int> p(N - 1);
    for (int i = 0, j = 0; i < N; i++)
    {
        if (oneBit == -1 && ((1 << i) & newB))
        {
            oneBit = i;
            continue;
        }
        p[j++] = i;
    }
    assert(oneBit != -1);

    sort(p.begin(), p.end(), [&](int a, int b){
        return ((newB >> a) & 1) > ((newB >> b) & 1);
    });

    int newBp = 0;
    for (int i = 0; i < N - 1; i++)
    {
        if (newB & (1 << p[i]))
        {
            newBp |= (1 << i);
        }
    }
    assert(newBp != (1 << (N - 2)));


    // Takeaway is one
    auto tmp = SolveRecursive(N - 1, 0, (1 << (N - 2)));
    // from (1 << (N - 2)) till newBp
    {
        auto tmp2 = SolveRecursive(N - 1, (1 << (N - 2)), newBp);
        tmp.insert(tmp.end(), tmp2.begin(), tmp2.end());
    }

    p.push_back(oneBit);

    assert(tmp.size() == (1 << N));
    for (int i = 0; i < (1 << N); i++)
    {
        int val = tmp[i];
        int& res = tmp[i];

        if (i >= (1 << (N - 1)))
        {
            val |= (1 << (N - 1));
        }

        res = 0;
        for (int j = 0; j < N; j++)
        {
            if (val & (1 << j))
            {
                res |= (1 << p[j]);
            }
        }

        res ^= A;
    }
    return tmp;
}

int main()
{
    int N, A, B;
    scanf("%d %d %d", &N, &A, &B);

    bool oddity = __builtin_popcount(A ^ B) & 1;

    if (oddity == false)
    {
        printf("NO\n");
        return 0;
    }

    auto answ = SolveRecursive(N, A, B);
    assert(answ[0] == A);
    assert(answ[(1 << N) - 1] == B);
    for (int i = 0; i < (1 << N); i++)
    {
        assert(used[answ[i]] == false);
        if (i > 0)
            assert(__builtin_popcount(answ[i] ^ answ[i - 1]) == 1);
        used[answ[i]] = true;
    }
    printf("YES\n");
    for (auto t : answ)
    {
        printf("%d ", t);
    }
    printf("\n");
}

