using namespace std;

#define N 131075
int bitCount(int bit) {
	int ret = 0;
	while (bit > 0) {
		++ret;
		bit = bit & (bit - 1);
	}
	return ret;
}

int ret[N];

void construct(int l, int r, int a, int b, int n, int bit, int myxor) {
	if (l + 1 == r) {
		ret[l] = a;// ^ myxor;
		ret[r] = b;// ^ myxor;
		return;
	}
	int mid = (l + r) / 2;
	int ind = -1;

	int axor = myxor, bxor = myxor;
	for (int i = 0; i < n; ++i) {
		if (bit&(1 << i)) {
			continue;
		}
		if ((a&(1 << i)) != (b&(1 << i))) {
			ind = i;
			if (a&(1 << i)) {
				axor |= (1 << i);
			}
			if (b&(1 << i)) {
				bxor |= (1 << i);
			}
			break;
		}
	}
	bit |= (1 << ind);
	int c = 0, f = -1, fInd = -1;
	for (int i = 0; i < n; ++i) {
		if (bit&(1 << i)) {
			continue;
		}
		c |= (1 << i);
		if (fInd == -1) {
			f = 0;
			fInd = i;
		}
	}
	c = (1 << n) - 1;
	c = (c & a);
	c = c ^ (1 << fInd);
	int tc = c;

	if (a&(1 << ind)) {
		tc |= (1 << ind);
	}
	construct(l, mid, a, tc, n, bit, axor);
	tc = c;
	if (b&(1 << ind)) {
		tc |= (1 << ind);
	}
	construct(mid + 1, r, tc, b, n, bit, bxor);
}
void solve() {
	int n;
	scanf("%d", &n);
	int a, b; scanf("%d %d", &a, &b);
	b = a ^ b;
	int bc = bitCount(b);
	if (bc & 1) {
		printf("YES\n");
		b = a ^ b;
		int sz = (1 << n);
		construct(0, sz - 1, a, b, n, 0, 0);
		for (int i = 0; i < sz; ++i) {
			printf("%d ", ret[i]);
		}
	}
	else {
		printf("NO\n");
	}
}
int main() {
	//freopen("input.txt", "r", stdin);
	solve();
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

// n の i ビット目と j ビット目を swap する
void swp(int &n, int i, int j) {
    if ((n >> i & 1) ^ (n >> j & 1) == 0) return;
    n ^= (1 << i);
    n ^= (1 << j);
}

// [0, n) ビット目を使って a を b にする
vector<int> dfs(int n, int a, int b) {
    if (n == 1) return {a, b};

    b ^= a;
    int highest = n - 1;
    for (int i = 0; i < n - 1; i++) {
        if (b >> i & 1) highest = i;
    }
    swp(b, n - 1, highest);

    int onehot = 1 << (n - 1);
    int mask = onehot - 1;
    auto first = dfs(n - 1, 0, 1);
    auto second = dfs(n - 1, 1, b & mask);

    vector<int> res;
    for (auto x : first) res.push_back(x);
    for (auto x : second) res.push_back(x | onehot);

    for (auto& x : res) swp(x, n - 1, highest);
    for (auto& x : res) x ^= a;
    return res;
}

int main() {
    int n, a, b;
    cin >> n >> a >> b;
    int g = a ^ b;
    if (__builtin_popcount(g) % 2 == 0) {
        cout << "NO" << endl;
        return 0;
    }
    cout << "YES" << endl;
    auto res = dfs(n, a, b);
    for (int i = 0; i < res.size(); i++) {
        cout << res[i] << ((i == res.size() - 1) ? "\n" : " ");
    }
}

