vi v1, v2;

vi rec_gen(int cnt) {
	vi ans;
	if (cnt == 1) {
		ans.pb(0);
		ans.pb(1);
		return ans;
	}
	REP(i, 0, 1 << (cnt - 1)) {
		ans.pb(i ^ (i >> 1));
	}
	vi tmp = rec_gen(cnt - 2);
	int cur = ((1 << (cnt - 1)) | (1 << (cnt - 2)));
	REP(i, 0, SZ(tmp)) {
		ans.pb(cur | tmp[i]);
		cur ^= (1 << (cnt - 2));
		ans.pb(cur | tmp[i]);
	}
	return ans;
}

