void go(int sz) {
    if(sz == N+1) return;
    for(auto& it: ans[sz-1]) ans[sz].push_back(it);
    reverse(ans[sz-1].begin(), ans[sz-1].end());
    for(auto& it: ans[sz-1]) ans[sz].push_back(it + (1 << (sz-1)));
    reverse(ans[sz-1].begin(), ans[sz-1].end());
    go(sz + 1);
}

