int64 rm_dig(int64 a, int64 dig) {
	int64 res = (a & ((1 << dig)-1)) | ((a >> (dig+1)) << dig);
	return res;
}

int64 insert_dig(int64 a, int64 dig, bool x) {
	int64 res = (a >> dig) << (dig+1);
	res |= (a & ((1 << dig)-1));
	res |= (x << dig);
	return res;
}

vector<int64> dfs(int64 A, int64 B, int64 bit){
	if (bit == 1) {
		vector<int64> ret = {A, B};
		return ret;
	}
	vector<int64> l, r;
	int64 d;
	REP(i, bit) {
		if ((A >> i & 1) != (B >> i & 1)) {
			d = i;
			break;
		}
	}
	int64 A_ = rm_dig(A, d), B_ = rm_dig(B, d);
	int64 C = (__builtin_popcount(A_)%2 ? 0 : 1);
	l = dfs(A_, C, bit-1), r = dfs(C, B_, bit-1);
	REP(i, l.size()) {
		l[i] = insert_dig(l[i], d, A >> d & 1);
	}
	REP(i, r.size()) {
		r[i] = insert_dig(r[i], d, B >> d & 1);
	}
	vector<int64> res;
	REP(i, l.size()) res.push_back(l[i]);
	REP(i, r.size()) res.push_back(r[i]);
	return res;
}

