int N, A, B;
vector<int> path[20];
vector<int> ans;

int calc(int st, int ed)
{
	int ret = 0;
	for (int i = 0; i < N; i++)
		if ((st >> i & 1) ^ (ed >> i & 1))
			ret++;
	return ret;
}

void init()
{
	path[0].push_back(1);
	for (int i = 1; i < N; i++)
	{
		path[i] = path[i - 1];
		vector<int> v = path[i - 1];
		reverse(v.begin(), v.end());
		path[i].push_back(1 << i);
		path[i].insert(path[i].end(), v.begin(), v.end());
	}
}

void work(int ed)
{
	int lstpos = -1;
	for (int i = 0; i < N; i++)
		if (ed >> i & 1)
		{
			if (lstpos == -1)
			{
				lstpos = i;
				ans = path[i];
			}
			else
			{
				ans.clear();
				for (int j = 0; j < path[i - lstpos - 1].size(); j++)
				{
					ans.insert(ans.end(), path[lstpos].begin(), path[lstpos].end());
					ans.push_back(path[i - lstpos - 1][j] << lstpos);
				}
			}
		}
}

int main()
{
	cin >> N >> A >> B;
	init();
	if (calc(A, B) % 2 == 0)
	{
		cout << "NO" << endl;
		return 0;
	}
	B ^= A;
	work(B);
	cout << "YES" << endl << A << ' ';
	int cur = A;
	for (int i = 0; i < ans.size(); i++)
		cout << (cur ^= ans[i]) << ' ';
	cout << endl;
	return 0;
}

