int nrbit(int x) {
    int k = 0;
    for (int i = 0; i < n; ++i)
        if ((1<<i) & x) k++;

    return k;
}

void grey(int k) {
    if (k == n) return;

    for (int i = (1<<k)-1; i >= 0; --i)
        nr[(1<<(k+1))-1-i] = nr[i] + x[k];

    grey(k+1);
}

