            rev = 1;
        }

        int k = 0;
        for (int i = 0; i < n; ++i)
            if ((1 << i) & b) x[k++] = (1 << i);

        x[k++] = a^b;

        for (int i = 0; i < n; ++i)
            if ((1 << i) & a) continue;
            else x[k++] = (1 << i);

        grey(0);

        int nb = nrbit(b);
