vector<int> GetPermutation(int start_num, const VI &bits_enabled, const VI &bits_to_flip) {
  assert(SZ(bits_to_flip) % 2 == 1);
  if (SZ(bits_enabled) == 1) {
    return {start_num, start_num ^ (1 << bits_enabled[0])};
  }

  const int S = SZ(bits_to_flip);
  int flip_mid = bits_to_flip[0];
  VI flip1, flip2;
  if (S >= 3) {
    flip1.PB(bits_to_flip[1]);
    flip2 = VI(bits_to_flip.begin() + 2, bits_to_flip.end());
  } else {
    int x = -1;
    for (int i = 0; i < SZ(bits_enabled); ++i) {
      if (flip_mid == bits_enabled[i]) { continue; }
      x = bits_enabled[i];
      break;
    }
    assert(x != -1);
    flip1.PB(x);
    flip2.PB(x);
  }

  VI rem_enabled;
  for (int x : bits_enabled) {
    if (x != flip_mid) {
      rem_enabled.PB(x);
    }
  }

  auto first_perm = GetPermutation(start_num, rem_enabled, flip1);
  const int next_num = first_perm.back() ^ (1 << flip_mid);
  for (int x : GetPermutation(next_num, rem_enabled, flip2)) {
    first_perm.PB(x);
  }

  return first_perm;
}

