        return (vector < int > {0, 1});
    if ((fn >> n - 1) & 1)
    {
        int md = (1 << n - 1) ^ 1;
        if (fn == md) md ^= 3;
        vector < int > R1 = Solve(n - 1, md ^ (1 << n - 1));
        vector < int > R2 = Solve(n - 1, fn ^ md);
        for (int r : R2)
            R1.push_back(r ^ md);
        return (R1);
    }
    vector < int > R1 = Solve(n - 1, fn);
    vector < int > R2 = Solve(n - 1, R1[1]);
    vector < int > R = {R1[0]};
    for (int r : R2)
        R.push_back(r ^ (1 << n - 1));
    for (int r : R1)
        if (r)
            R.push_back(r);
    return (R);
}
