    set<int> bits_diff, bits_mask;
    for (int i = 0; i < n; ++i) {
      if (((from >> i) & 1) != ((to >> i) & 1)) {
        bits_diff.insert(i);
      }
      if ((mask >> i) & 1) {
        bits_mask.insert(i);
      }
    }
    if (bits_mask.size() == n - 1) {
      return {from, to};
    }
    for (auto i : bits_diff) {
