string changeBase(int N, int b, int digit = -1) {
    string s = "";
    while (N != 0) {
        s = to_string(N % b) + s;
        N /= b;
    }
    if (digit != -1) {
        while (s.length() < digit) {
            s = "0" + s;
        }
    }
    return s;
}

int to10(string S) {
    reverse(S.begin(), S.end());
    int ret = 0;
    rep(i, S.length()) {
        ret += (S[i] - '0') << i;
    }
    return ret;
}

