//dfs(n,a,b,0,1<<n-1);として呼ぶ
void dfs(int n, int a, int b, int start_i, int end_i){
  if(n==1){
    p[start_i]=a;
    p[end_i]=b;
    return;
  }
  int x;
  REP(i,n){
    if((a>>i)%2 != (b>>i)%2){//2^iの桁の値が異なる時
      x = i;
      break;
    }
  }
  int fa=0,fb=0;//a,bからxビット目を除いた値
  REP(i,n){
    if(i<x){
      fa += ((a>>i)%2)<<i;
      fb += ((b>>i)%2)<<i;
    }else{
      fa += ((a>>i)%2)<<(i-1);
      fb += ((b>>i)%2)<<(i-1);
    }
  }
  int c;//fa,fbと立っているビットの数の偶奇が異なるもの
  last_ = fa%2;
  c = (fa>>1)<<1 + (last_+1)%2;
  dfs(n-1, fa, c, start_i, start_i+1<<(n-1)-1);
  dfs(n-1, c, fb, start_i+1<<(n-1), end_i);
  int temp;
  REP(i,1<<(n-1)){
    temp = 0;
    REP(j,n){
      if(j<x){
        temp += ((p[start_i+i]>>j)%2)<<j;
      }else if(j==x){
        temp += ((a>>x)%2)<<x;
      }else{
        temp += ((p[start_i+i]>>(j-1))%2)<<j;
      }
    }
    p[start_i+i] = temp;
  }
  for(int i=start_i+1<<(n-1);i<=end_i){
    temp = 0;
    REP(j,n){
      if(j<x){
        temp += ((p[i]>>j)%2)<<j;
      }else if(j==x){
        temp += ((b>>x)%2)<<x;
      }else{
        temp += ((p[i]>>(j-1))%2)<<j;
      }
    }
    p[i] = temp;
  }
  return;
}


