void solve(int mask, int last, int VAL) {
  if (__builtin_popcount(mask) == 1) {
    res.pb(VAL);
    res.pb(VAL ^ mask);
    return;
  }
  int bit = 1 << __builtin_ctz(last);
  int bit2 = 1 << __builtin_ctz(mask ^ bit);
  solve(mask ^ bit, bit2, VAL);
  solve(mask ^ bit, last ^ bit ^ bit2, VAL ^ bit2 ^ bit);
}

