const int maxN = 20;

void GrayCodes(int n, int* T)
{
	int s = 1 << n, q = 1, oldestBit = -1, mask = 0;
	FOR(i, 0, s)
	{
		if (i+1 == q)	q *= 2, T[i] = ++oldestBit;
		else 			T[i] = T[i - q/2];
		mask ^= 1 << T[i];
	}
}

int bit[1 << maxN], M[maxN];

int main()
{
	int n, a, b;
	scanf ("%d%d%d", &n, &a, &b);

	int c = a ^ b;
	if (__builtin_popcount(c) != 1)
	{
		printf("NO\n");
		return 0;
	}

	int j = __builtin_ctz(c);
	FOR(i, 0, n)
		M[i] = i;
	swap(M[j], M[n-1]);

	GrayCodes(n, bit);
	int m = a;
	printf("YES\n");	
	FOR(i, 0, 1<<n)
	{
		printf("%d ", m);
		m ^= 1 << M[bit[i]];
	}

	m ^= 1 << M[bit[(1<<n)-1]];
	assert(m == b);

	printf("\n");
    return 0;
}

