int removeb(int x, int i) {
    int tmp = x & ((1 << i) - 1);
    return ((x >> (i + 1)) << i) + tmp;
}

int insertb(int x, int i, int j) {
    int tmp = x & ((1 << i) - 1);
    return ((x >> i) << (i + 1)) + (j << i) + tmp;
}

vector<int> solve(int n, int a, int b) {
    if (n == 1) {
        return {a, b};
    }
    for (int i = 0; i < n; i++) {
        if ((a ^ b) & (1 << i)) {
            int c = removeb(a, i);
            int d = removeb(b, i);
            for (int j = 0; j < (1 << n); j++) {
                int x = removeb(j, i);
                if (x == c || x == d) {
                    continue;
                }
                if (__builtin_popcount(x ^ c) % 2 == 0 || __builtin_popcount(x ^ d) % 2 == 0) {
                    continue;
                }
                debug(c, x, d);
                vector<int> p = solve(n - 1, c, x);
                vector<int> q = solve(n - 1, x, d);
                for (int& v : p) {
                    v = insertb(v, i, (a >> i) & 1);
                }
                for (int& v : q) {
                    v = insertb(v, i, (b >> i) & 1);
                }
                p.insert(p.end(), q.begin(), q.end());
                return p;
            }
        }
    }
    return {};
}

