int n,A,B,pc[10000010];
vec ans;
vec solve(int S,int x){
	assert(pc[x]&1);
	assert((S&x)==x);
	if (pc[S]==1){
		assert((x==S));
		vec v;
		v.clear();
		v.pb(0);
		v.pb(S);
		return v;
	}
	int t=-1;
	FOR(i,0,n-1) if ((x>>i)&1) t=i;
	assert((t!=-1));
	if (pc[x]>=3){
		int tt;
		FOR(j,0,n-1){
			if (!((S>>j)&1)) continue;
			if (t==j) continue;
			if ((x>>j)&1) tt=j;
		}
		vec A=solve(S^(1<<t),(1<<tt));
		vec B=solve(S^(1<<t),x^(1<<t)^(1<<tt));
		vec ans=A;
		int tmp=ans[SZ(A)-1]^(1<<t);
		FOR(i,0,SZ(B)-1) ans.pb(B[i]^tmp);
		return ans;
	}
	else{
		int tt;
		FOR(j,0,n-1){
			if (!((S>>j)&1)) continue;
			if (t==j) continue;
			tt=j;
		}
		vec A=solve(S^(1<<t),(1<<tt));
		vec B=solve(S^(1<<t),(1<<tt));
		vec ans=A;
		int tmp=ans[SZ(A)-1]^(1<<t);
		FOR(i,0,SZ(B)-1) ans.pb(B[i]^tmp);
		return ans;
	}
}
