void gray_code(vector<int>& r, int n) {
  if (n == 1) {
    r[0] = 0;
    r[1] = 1;
    return;
  }
  gray_code(r, n - 1);
  for (int i = 0; i < (1 << n - 1); i++) {
    r[(1 << n) - 1 - i] = (1 << n - 1) | r[i];
  }
}

