int ans[1 << 17];
void solve(int a, int b, int l, int r, int n){
	if(l + 2 == r){
		assert(__builtin_popcount(a ^ b) == 1);
		ans[l] = a;
		ans[l + 1] = b;
		return;
	}
	b ^= a;

	vi ord(n, -1);
	int sortedb = 0, k = n, m = (l + r) / 2;

	for(int i = n - 1;i >= 0; i--){
		if(b >> i & 1){
			ord[i] = --k;
			sortedb |= 1 << k;
		}
	}
	for(int i = n - 1;i >= 0; i--){
		if(!(b >> i & 1)) ord[i] = --k;
	}

	assert(sortedb >> n - 1 & 1);
	sortedb ^= 1 << n - 1;

	solve(0, 1, l, m, n - 1);
	solve(1, sortedb, m, r, n - 1);

	for(int i = l; i < r; i++){
		if(i >= m) ans[i] ^= 1 << n - 1;
		int t = 0;
		rep(j, n) t |= (ans[i] >> ord[j] & 1) << j;
		ans[i] = t ^ a;
	}
}

