vector<int> diff(int a, int b, int n){
  if(n==1) return (vector<int>) {a,b};
  int n_2 = pow(2,n);
  int n_2_ = pow(2,n-1);
  int digit;
  for(digit = 1; digit<n_2;digit*=2){
    if((a&digit) != (b&digit)) break;
  }
  int a_ = a&digit, b_ = b&digit;
  int A = a%digit + (a/(digit*2))*(digit);
  int B = b%digit + (b/(digit*2))*(digit);
  int C = A^1;
  vector<int> l = diff(A,C,n-1);
  vector<int> r = diff(C,B,n-1);
  int i;
  vector<int> L(n_2);
  REP(i,n_2){
   if(i<n_2_){
     L[i] = l[i]%digit + (l[i]/digit)*2*digit + a_;
   }else{
     L[i] = r[i-n_2_]%digit + (r[i-n_2_]/digit)*2*digit + b_;
   }
  }
  return L;
}

