	vector<int> ret;
	REP(i,1<<sz){
		int cur=s;
		REP(j,sz){
			if(i&(1<<j)) cur|=(1<<idx[j]);
			else{
				if(cur&(1<<idx[j])) cur^=(1<<idx[j]);
