		if (1 & (C >> i)) {
			bits++;
		}
	}
	if (bits % 2 == 0) return 0;
	REP(i, N) {
		if (1 & (C >> i)) {
			v[1].pb(i);
		}
		else {
			v[0].pb(i);
		}
	}
	REP(i, 1 << v[1].size()) {
		FOR(j,1,1 << v[0].size()) {
			LL q = j & (-j);
			next(v[0][inv(q)]);
		}
		if (i == (1 << v[1].size()) - 1) break;
		for (int j = 0; j < v[1].size();j+=2) {
			if (ranks[j] == 3) {
				ranks[j] = 0;
				continue;
			}
			if (j + 1 == v[1].size()) {
				next(v[1][j]);
				break;
			}
			LL revt =( btimes[j] / 3 + 1 )== (1 << ((LL)v[1].size() - 2-j));
			//cout << revt <<" " << (j * 2 + (1 ^ revt))<< endl;
			if (btimes[j]%3==0 or btimes[j]%3==2) {
			//	assert(j * 2 ^ revt < v[1].size());
				next(v[1][j^revt]);
			}
			else {
				//assert((j * 2+(1 ^ revt)) < v[1].size());
				next(v[1][(j+ (1 ^ revt))]);
			}
			btimes[j]++;
			ranks[j]++;
			break;
		}	
	}
	return 1;
}
signed main() {
	ios_base::sync_with_stdio(false);
	cout << fixed << setprecision(10);
	if (solve()) {
		cout << "YES" << endl;

		REP(i, M) {
			if (i) cout << " ";
			cout << ((vals[i])^A);
		}
		cout << endl;
		sort(vals, vals + (1 << N));

		REP(i, M - 1) assert(vals[i] == vals[i + 1] - 1);

	}
	else {
		cout << "NO" << endl;
	}
	//cout << solve() << endl;
