int bit_count(unsigned x){
    int ret = 0;
    while(x > 0){
        ret += x & 1;
        x >>= 1;
    }
    return ret;
}

void solve(istream &cin) {
    ll choice[51][51];

    for (int i = 0; i < 51; ++i) {
        choice[i][0] = 1;
        choice[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            choice[i][j] = choice[i - 1][j] + choice[i - 1][j - 1];
        }
    }

    cin >> N >> A >> B;
    if(!cin) return;
    ull n2 = 1ull << N;
    int bit_a, bit_b;
    bit_a = bit_count(A); bit_b = bit_count(B);
    if(abs(bit_a - bit_b ) != 1){
        cout << "NO\n"; return;
    }
    vector<queue<int>> bits(N+1);
    vector<ll> count(N);
    for (int i = 0; i < N; ++i) {
        count[i] = choice[N-1][i] * 2;
    } // end i

    for (unsigned k = 0; k < n2; ++k) {
        if(k == A or k == B) continue;
        bits[bit_count(k)].push(k);
    } // end k
    count[min(bit_a, bit_b)]--;
    ll n_c = bit_a;
    ll cc = 2;
    cout << "YES\n" << A;
    while(cc < n2){
        if(n_c >= bit_b){
            if(count[n_c] > 0 and n_c < N){
                count[n_c]--;
                n_c++;
                ll next = bits[n_c].front(); bits[n_c].pop();
                cout << ' ' << next;
                cc++;
                continue;
            }
        }
        if(n_c > 0 and count[n_c-1] > 0){
            n_c--;
            count[n_c]--;
            ll next = bits[n_c].front(); bits[n_c].pop();
            cout << ' ' << next;
        }
        else{
            count[n_c]--;
            n_c++;
            ll next = bits[n_c].front(); bits[n_c].pop();
            cout << ' ' << next;
        }
        cc++;
    }
    cout << ' ' << B << endl;

}

