    if(t & (1 << (x - 1))){
        tt |= (1 << (y - 1));
    }else{
        tt &= (~(1 << (y - 1)));
    }
    if(t & (1 << (y - 1))){
        tt |= (1 << (x - 1));
    }else{
        tt &= (~(1 << (x - 1)));
    }
    return tt;
