typedef vector<int> Gre;
Gre GetGray(int n){Gre v;for(int i=0;i<(1<<n);i++) v.push_back(i^(i>>1));return v;}
const int N=1<<17;
int A,B,pA,pB;
int que[N],tail=0;
#define lowbit(a) ((a)&(-a))
int Cnt[N],bits[20],Ful=0;
int n;
inline void Solve(int Xor,int A,int sum){
	if(!(Cnt[sum^Ful]^1)) {printf("%d %d ",A,A^Xor);return;}
	for(int i=0;i<n;++i){
		if(!(sum&bits[i])&&(Xor&bits[i])){
			for(int j=0;j<n;++j) {
				if(i==j) continue;
				if(!(sum&bits[j])){
					Solve(bits[j],A,sum|bits[i]);
					Solve(Xor^bits[j]^bits[i],A^bits[i]^bits[j],sum|bits[i]);
					return;
				}
			}
		}
	}
}
int main()
{
    cin>>n>>A>>B;
	Gre v=GetGray(n);
	int sz=v.size();
	int len=1<<n;Ful=len-1;
	for(int i=0;i<len;++i) Cnt[i]=Cnt[i>>1]+(i&1);
	bits[0]=1;
	for(int i=1;i<=18;++i) bits[i]=bits[i-1]<<1;
	for(int i=0;i<sz;++i) if(v[i]==A) {pA=i;break;}
	for(int i=pA;i<sz;++i) que[++tail]=v[i];
