void solve (int n,int A,int B,int l,int r)
{
	if (n==1){ans[l]=A;ans[r]=B;return ;}
	int mid=(l+r)>>1;
	int C=A^B;
	int t=C&(-C);//找到一位大家不一样的
	int x=A%t+A/(t<<1)*t;//去掉这一位
	int y=B%t+B/(t<<1)*t;//去掉这一位
	int z=x^1;
	solve(n-1,x,z,l,mid);solve(n-1,z,y,mid+1,r); 
	for (int u=l;u<=mid;u++)
	{
		ans[u]=ans[u]%t+ans[u]/t*(t<<1)+(A&t);
	}
	for (int u=mid+1;u<=r;u++)
	{
		ans[u]=ans[u]%t+ans[u]/t*(t<<1)+(B&t);
	}
}
