string num2bit(ll num, ll len){
	string bit = "";
	REP(i, len){
	bit += char('0'+(num>>i & 1));
	}
	reverse(bit.begin(), bit.end());
	return bit;
}

vector<ll> res(1<<17, -1);
ll N;


void dfs(ll X, ll Y, ll mask, ll depth, ll id){

	//dump(num2bit(X, N))
	//dump(num2bit(Y, N))
	//dump(num2bit(mask, N))

	if(depth == N-1){
		res[(id<<1)] = X;
		res[(id<<1)+1] = Y;
		return;
	}

	ll idx = -1;
	REP(i, N){
		bool xi = (X>>i) & 1;
		bool yi = (Y>>i) & 1;
		bool mi = (mask>>i) & 1;
		//dump(xi)
		//dump(yi)
		//dump(mi)
		if(xi != yi and !mi){
			idx = i;
			break;
		} 
	}

	ll nmask = mask^(1ll<<idx);

	ll jdx = -1;
	REP(i, N){
		bool mi = (nmask>>i) & 1;
		if(!mi){
			jdx = i;
			break;
		}
	}

	//dump(idx)
	//dump(jdx)

	ll Z = -1, W = -1;
	Z = X^(1<<jdx);
	W = Z^(1<<idx);

	//dump(num2bit(Z, N))
	//dump(num2bit(W, N))

	dfs(X, Z, nmask, depth+1, (id<<1));
	dfs(W, Y, nmask, depth+1, (id<<1)+1);
	return;
}

