vector<int> isMatch(int a, int b, int c, int d, int n) {
	vector<int> P;
	if(__builtin_popcount(a) != __builtin_popcount(c)) return P;
	if(__builtin_popcount(b) != __builtin_popcount(d)) return P;

	vector<int> F[4];
	for(int i=0; i<n; i++) {
		int cb = (c >> i) & 1;
		int db = (d >> i) & 1;
		F[(cb << 1) | db].pb(i);
	}

	for(int i=0; i<n; i++) {
		int ab = (a >> i) & 1;
		int bb = (b >> i) & 1;
		int p = (ab << 1) | bb;
		if(F[p].size()) {
			P.pb(F[p].back());
			F[p].pop_back();
		}
		else {
			P.clear();
			return P;
		}
	}
	return P;
}

void solve(int n, int a, int b, int P[]) {
	for(int i=0; i<(1<<n); i++) {
		if(P[i] != a) continue;
		int j = i-1; if(j < 0) j += (1<<n);
		vector<int> per = isMatch(a, b, P[i], P[j], n);
		if(per.size()) {
			printThis(i, (1<<n), +1, P, per);
			exit(0);
		}
		j = i+1; if(j >= (1<<n)) j -= (1<<n);
		per = isMatch(a, b, P[i], P[j], n);
		if(per.size()) {
			printThis(i, (1<<n), -1, P, per);
			exit(0);
		}
	}
}

