int pw(int n,int k){
  int res=1;
  while(k){
    if(k&1)res*=n;
    n*=n;k>>=1;
  }
  return res;
}
int bitcount(int a){
  int res=0;
  while(a){
    res+=a&1;
    a>>=1;
  }
  return res;
}
