#include <bits/stdc++.h>
using namespace std;

// n の i ビット目と j ビット目を swap する
void swp(int &n, int i, int j) {
    if ((n >> i & 1) ^ (n >> j & 1) == 0) return;
    n ^= (1 << i);
    n ^= (1 << j);
}

// [0, n) ビット目を使って a を b にする
vector<int> dfs(int n, int a, int b) {
    if (n == 1) return {a, b};

    int highest = n - 1;
    int c = a ^ b;

    if (~c >> highest & 1) {
        for (int i = 0; i < n - 1; i++) {
            if (c >> i & 1) highest = i;
        }
    }
    swp(a, n - 1, highest);
    swp(b, n - 1, highest);

    int na = a & ~(1 << n - 1);
    auto first = dfs(n - 1, na, na ^ 1);
    int nb = b & ~(1 << n - 1);
    auto second = dfs(n - 1, na ^ 1, nb);

    vector<int> res;
    if (a >> (n - 1) & 1) {
        for (auto x : first) res.push_back(x ^ (1 << (n - 1)));
        for (auto x : second) res.push_back(x);
    } else {
        for (auto x : first) res.push_back(x);
        for (auto x : second) res.push_back(x ^ (1 << (n - 1)));
    }

    for (auto& x : res) swp(x, n - 1, highest);
    return res;
}

int main() {
    int n, a, b;
    cin >> n >> a >> b;
    int g = a ^ b;
    if (__builtin_popcount(g) % 2 == 0) {
        cout << "NO" << endl;
        return 0;
    }
    cout << "YES" << endl;
    auto res = dfs(n, a, b);
    for (int i = 0; i < res.size(); i++) {
        cout << res[i] << ((i == res.size() - 1) ? "\n" : " ");
    }
}

