#include <bits/stdc++.h>

using namespace std;

vector <int> base[2] = {{0, 1}, {1, 0}};

int ignore_bit(int x, int b) {
    int _left = x & ((1 << b) - 1);
    int _right = x >> (b + 1) << b;
    return _left + _right;
}
int add_bit(int x, int b) {
    int _left = x & ((1 << b) - 1);
    int _right = x >> b << (b + 1);
    return _left + _right;
}
int swap_bit(int x, int a, int b) {
    int r = x;
    if (x >> a & 1) r = r - (1 << a) + (1 << b);
    if (x >> b & 1) r = r - (1 << b) + (1 << a);
    return r;
}

vector <int> go(int n) {
    if (n == 1) return base[0];
    vector <int> v = go(n - 1), ret;
    for (int i = 0; i < v.size(); ++i) {
        if (i & 1) ret.push_back(v[i] * 2 + 1), ret.push_back(v[i] * 2);
        else ret.push_back(v[i] * 2), ret.push_back(v[i] * 2 + 1);
    }
    return ret;
}

vector <int> solve(int nbit, int s, int f) {
    if (nbit == 1) return base[s];
    int x = s ^ f;
    int b = log2(x & -x);
    if (__builtin_popcount(x) == 1) {
        vector <int> ret = go(nbit);
        for (auto &y: ret) y = swap_bit(y, nbit - 1, b) ^ s;
        return ret;
    }
    int xx = x ^ (1 << b);
    int c = log2(xx & -xx);
    int nx = ignore_bit(1 << c, b);
    vector <int> _left = solve(nbit - 1, 0, nx);
    for (auto &y: _left) y = add_bit(y, b);
    int nf = ignore_bit(x, b);
    vector <int> _right = solve(nbit - 1, nx, nf);
    for (auto &y: _right) y = add_bit(y, b) + (1 << b);
    vector <int> res = _left;
    for (auto y: _right) res.push_back(y);
    for (auto &y: res) y ^= s;
    return res;
}

int main(void) {
    ios_base::sync_with_stdio(0); cin.tie(NULL); cout.tie(NULL);
    int n, a, b;
    cin >> n >> a >> b;
    int x = a ^ b;
    if (__builtin_popcount(x) % 2 == 0) return cout << "NO" << endl, 0;
    vector <int> ans = solve(n, a, b);
    cout << "YES" << endl;
    for (auto x: ans) cout << x << ' ';
    cout << endl;
    return 0;
}

