vector<int> dfs(int n, int a, int b){
	if(n == 1) return {a,b};
	int pa = pcount(a);
	int pb = pcount(b);
	rep(bit,18){
		if((a>>bit & 1) != (b>>bit & 1)){
			int A = a, B = b;
			REP(b2,bit+1,20){
				int tmp = 1<<(b2-1);
				A &= ~tmp;
				A |= tmp * (a>>b2 & 1);
				B &= ~tmp;
				B |= tmp * (b>>b2 & 1);
			}
			bool f = a>>bit & 1;
			int t = 0;
			if(f) t = pa & 1;
			else t = pb & 1;
			auto l = dfs(n-1, A, t);
			auto r = dfs(n-1, t, B);
			for(auto &i : l) for(int b2=17; b2>=bit; b2--){
				i |= (1<<(b2+1)) * (i>>b2 & 1);
				i &= ~(1<<b2);
			}
			for(auto &i : r) for(int b2=17; b2>=bit; b2--){
				i |= (1<<(b2+1)) * (i>>b2 & 1);
				i &= ~(1<<b2);
			}
			if(f) for(auto &i : l) i += 1<<bit;
			else for(auto &i : r) i += 1<<bit;
			l.insert(l.end(), r.begin(), r.end());
			return l; 
		}
	}
}

