inline int cal(int x) {
    int ans = 0;
    while(x) {
        ans++;
        x -= x & (-x);
    }
    return ans;
}

inline int Abs(int x) {
    return x < 0 ? -x : x;
}

void solve(int bas) {
    if(!bas) {
        p[++top] = now;
        return;
    }
    int t = bas & (-bas);
    solve(bas ^ t);
    now ^= t;
    solve(bas ^ t);
    return;
}

