int en(int n, int i, int x) {
    int mask0 = ((1<<(n-i))-1)<<i;
    int mask1 = ((1<<(n-i-1))-1)<<(i+1);
    return (x&~mask0) | ((x&mask1)>>1) | ((x>>i&1)<<(n-1));
}

int de(int n, int i, int x) {
    int mask0 = ((1<<(n-i))-1)<<i;
    int mask1 = ((1<<(n-i-1))-1)<<i;
    return (x&~mask0) | ((x&mask1)<<1) | ((x>>(n-1)&1)<<i);
}

vector<int> rec(int n, int a, int b) {
    dump(n,a,b);
    if (n == 1) return { a, b };
    int ii = -1;
    rep (i,n) if ((a>>i&1) != (b>>i&1)) ii = i;
    assert(ii != -1);
    vector<int> v; v.reserve(1<<n);
    int jj = 0; if (ii == jj) jj++;

    auto v1 = rec(n-1, en(n,ii,a), en(n,ii,a^(1<<jj)));
    auto v2 = rec(n-1, en(n,ii,a^(1<<ii)^(1<<jj)), en(n,ii,b));
    for (int &x : v1) x = de(n,ii,x);
    for (int &x : v2) x = de(n,ii,x);
    v1.reserve(v1.size()+v2.size());
    copy(all(v2),back_inserter(v1));
    dump(n,a,b,v1);
    return v1;
}

