		answ.push_back(a);
		return;
	}
	rec2(x - 1);
	a ^= (1 << x);
	rec2(x - 1);
}

void rec1(int x) {
	if (x == -1) {
		answ.push_back(a);
		return;
	}
	if ((a & (1 << x)) == (b & (1 << x))) {
		answ.push_back(a);
		a ^= (1 << x);
		rec2(x - 1);
		a ^= (1 << x);
		rec1(x - 1);
	} else {
		rec2(x - 1);
		a ^= (1 << x);
		rec1(x - 1);
	}
}

