#include <bits/stdc++.h>
typedef long long lint;
using namespace std;

const int l = 17;

vector<bitset<l>> any2any(bitset<l> start, bitset<l> goal, int dim);
vector<bitset<l>> zero2any(bitset<l> goal, int dim);

int main() {
    int n, a, b;
    cin >> n >> a >> b;
    bitset<17> x(a), y(b);
    if (x.count() % 2 == y.count() % 2) {
        cout << "NO" << endl;
    } else {
        cout << "YES" << endl;
        auto res = any2any(a, b, n);
        for (auto e : res) {
            cout << e.to_ulong() << endl;
        }
    }
    return 0;
}

vector<bitset<l>> zero2any(bitset<l> goal, int dim) {
    if (dim == 1) {
        return {0, 1};
    }
    if (goal[dim - 1] == 0) {
        int replace = -1;
        for (int i = 0; i < l; i++) {
            if (goal[i] == 1) {
                replace = i;
                break;
            }
        }
        goal[dim - 1] = 1, goal[replace] = 0;
        auto res = zero2any(goal, dim);
        for (auto &e : res) {
            int a = e[dim - 1], b = e[replace];
            e[dim - 1] = b, e[replace] = a;
        }
        return res;
    }
    goal[dim - 1] = 0;
    auto y = goal ^ bitset<l>(1);
    auto half_0 = zero2any(y, dim - 1);
    auto half_1 = any2any(y, goal, dim - 1);
    for (auto e : half_1) {
        e[dim - 1] = 1;
        half_0.push_back(e);
    }
    return half_0;
}

vector<bitset<l>> any2any(bitset<l> start, bitset<l> goal, int dim) {
    auto res = zero2any(goal ^ start, dim);
    for (auto &e : res) {
        e ^= start;
    }
    return res;
}

