// start with 00...0, end with 11..1
vector<vector<int> > build_same(int n){
	if(n==0)return {{}};
	auto v = build_same(n-1);
	auto v2 = v;
	reverse(ALL(v2));
	vector<vector<int> > ret;
	for(auto vi:v){
		ret.push_back(vi);
		ret.back().push_back(0);
	}
	for(auto vi:v2){
		ret.push_back(vi);
		ret.back().push_back(1);
	}
	return ret;
}

vector<vector<int> > build_different(int n){
	assert(n%2==1);
	if(n==1)return {{0},{1}};
	auto v = build_different(n-2);
	vector<vector<int> > ret;
	REP(i,v.size()){
		bool end = false;
		if(i==v.size()-1)end = true;
		if(i%2==0){
			{
				auto v2(v[i]);
				v2.push_back(0);v2.push_back(0);
				ret.push_back(v2);
			}
			{
				auto v2(v[i]);
				v2.push_back(0);v2.push_back(1);
				ret.push_back(v2);
			}
			{
				auto v2(v[i]);
				v2.push_back(1);v2.push_back(1);
				ret.push_back(v2);
			}
			{
				auto v2(v[i]);
				v2.push_back(1);v2.push_back(0);
				ret.push_back(v2);
			}
		}else{
			if(end){
				{
					auto v2(v[i]);
					v2.push_back(1);v2.push_back(0);
					ret.push_back(v2);
				}
				{
