//000 -> 111
//0 -> 1
//000 -> 001 -> 011 -> 010 -> 110 -> 100 -> 101 -> 111
//0000 -> 0010 -> 0110 -> 0100 -> 1100 -> 1000 -> 1010 -> 1011
//-> 111
// 00 -> 01 -> 11 -> 10
// 10 -> 00 -> 01 -> 11
