void check(vector<uint> &ans){
	unordered_set<uint> s;
	for(auto a:ans){
		assert(0<=a and a<(1u<<N));
		assert(s.find(a)==s.end());
		s.insert(a);
	}
	REP(i,ans.size()-1){
		uint t = (ans[i]^ans[i+1]);
		assert(__builtin_popcount(t)==1);
	}
}

void solve(){
	vector<int> base;
	vector<int> diff, same;
	REP(i,N){
		Int b = (1ll<<i);
		if((A&b)!=(B&b))diff.push_back(i);
		else same.push_back(i);
		if(A&b)base.push_back(1);
		else base.push_back(0);
	}
	if(diff.size()%2==0){
		fout<<"NO"<<endl;
		return;
	}
	fout<<"YES"<<endl;
	auto vd = build_different(diff.size()), vs = build_same(same.size());
	vector<uint> ans;
	REP(i,vd.size()){
		REP(j,vs.size()){
			vector<int> v;
			if(i%2==0)v = vs[j];
			else v = vs[vs.size()-1-j];
			uint u = 0;
			REP(j,diff.size()){
				int k = diff[j];
				if(base[k]^vd[i][j]){
					u += (1u<<k);
				}
			}
			REP(j,same.size()){
				int k = same[j];
				if(base[k]^v[j]){
					u += (1u<<k);
				}
			}
			ans.push_back(u);
//			fout<<u<<" ";
		}
	}
//	check(ans);
	REP(i,ans.size()){
		fout<<ans[i];
		if(i<ans.size()-1)fout<<" ";
	}
	fout<<endl;
}

