#include <bits/stdc++.h>
using namespace std;

#define all(s) s.begin(), s.end()
#define vi vector<int>
#define pb push_back
#define ii pair<int, int>
#define x first
#define y second
#define bit(x, y) (x>>y)&1

vi solve(int n, int fr, int to) {
    vi res;
    if (n == 1) {
        return {fr, to};
    }
    bool bitfr, bitto;
    int pos;
    for (int i = 0; i < n; i++) {
        if ((bit(fr, i)) != (bit(to, i))) {
            bitfr = bit(fr, i);
            bitto = !bitfr;
            pos = i;
            break;
        }
    }
    int l = (fr>>(pos + 1)) + (fr&((1<<pos) - 1));
    int r = (to>>(pos + 1)) + (to&((1<<pos) - 1));
    int too = 0;
    for (int i = 0; i < (1 << (n - 1)); i++) {
        if (i != l && i != r) {
            too = i;
            break;
        }
    }
    vi vl = solve(n - 1, l, too);
    vi vr = solve(n - 1, too, r);
    for (auto u : vl) {
        int foo = u&((1 << pos) - 1);
        int bar = (u - foo) * 2;
        res.pb(foo + bar + (bitfr << pos));
    }
    for (auto u : vr) {
        int foo = u&((1 << pos) - 1);
        int bar = (u - foo) * 2;
        res.pb(foo + bar + (bitto << pos));
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0); cout.tie(0);
    int n, a, b;
    cin >> n >> a >> b; 
    if (__builtin_popcount(a) % 2 == __builtin_popcount(b)) {
        return cout << "NO", 0;
    }
    cout << "YES\n";
    vi ans = solve(n, a, b);
    for (auto u : ans) {
        cout << u << ' ';
    }
    return 0;
}

