#include <bits/stdc++.h>

using namespace std;

int lowbit(int x) {
  return x & -x;
}

int Bc(int x) {
  int r = 0;
  while (x) ++r, x -= lowbit(x);
  return r;
}

void Solve(int a, int b, int u, int ext) {
  if (a == b) {
    assert(!u);
    cout << (a | ext) << ' ';
    return;
  }
  assert(Bc(a ^ b) & 1);
  int xo = a ^ b;
  int y = lowbit(xo);
  u ^= y;
  if (a & y) {
    int c = a ^ y ^ lowbit(u);
    Solve(a ^ y, c, u, ext | y);
    Solve(c, b, u, ext);
  } else {
    int c = a ^ lowbit(u);
    Solve(a, c, u, ext);
    Solve(c, b ^ y, u, ext | y);
  }
}

int main() {
  int n, a, b;
  cin >> n >> a >> b;
  if (~Bc(a ^ b) & 1) {
    cout << "NO" << endl;
    return 0;
  }
  cout << "YES" << endl;
  Solve(a, b, (1 << n) - 1, 0);
  cout << endl;

  return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define finish(x) return cout << x << endl, 0
#define ll long long

int n, a, b;
vector <int> ans;

void solve(int l, int r, vector <int> c){
    if(r - l == 1) return;
    int mid = (l + r) / 2;
    int f = 0;
    for(auto &i : c){
        if(((ans[l] >> i) ^ (ans[r] >> i)) & 1){
            f = i;
            break;
        }
    }
    c.erase(find(c.begin(), c.end(), f));
    for(int i = l ; i <= r ; i++){
        if(i <= mid) ans[i] |= (((ans[l] >> f) & 1) << f);
        else ans[i] |= (((ans[r] >> f) & 1) << f);
    }
    bool b = 0;
    for(auto &i : c){
        if(b == 0){
            ans[mid] |= ((((ans[l] >> i) & 1) ^ 1) << i);
            ans[mid + 1] |= ((((ans[l] >> i) & 1) ^ 1) << i);
            b = 1;
        }
        else{
            ans[mid] |= (((ans[l] >> i) & 1) << i);
            ans[mid + 1] |= (((ans[l] >> i) & 1) << i);
        }
    }
    solve(l, mid, c);
    solve(mid + 1, r, c);
}
int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> n >> a >> b;
    if(__builtin_popcount(a ^ b) % 2 == 0) finish("NO");
