    ans[0] = a;
    ans[(1 << n) - 1] = b;
    vector <int> all;
    for(int i = 0 ; i < n ; i++){
        all.push_back(i);
    }
    solve(0, (1 << n) - 1, all);
    cout << "YES" << endl;
    for(auto &i : ans) cout << i << " ";
    cout << endl;
}

