void solve(int n, int a, int b, int P[]) {
	for(int i=0; i<(1<<n); i++) {
		if(P[i] != a) continue;
		int j = i-1; if(j < 0) j += (1<<n);
		if(P[j] == b) {
			printThis(i, (1<<n), +1, P);
			exit(0);
		}
		j = i+1; if(j >= (1<<n)) j -= (1<<n);
		if(P[j] == b) {
			printThis(i, (1<<n), -1, P);
			exit(0);
		}
	}
}

