vector<int> dfs(int n,int a,int b){
    //cout<<n<<" "<<a<<" "<<b<<endl;
    if(n==1)return {a,b};
    int d;
    for(int i=0;;i++){
        int y=1<<i;
        int aa=a/y,bb=b/y;
        if(aa%2!=bb%2){
            d=i;
            break;
        }
    }
    swa(a,n-1,d);
    swa(b,n-1,d);
    //cout<<a<<" "<<b<<endl;
    int na=a%(1<<(n-1));
    int nb=b%(1<<(n-1));
    //cout<<na<<" "<<nb<<endl;
    vector<int> v=dfs(n-1,na,na^1);
    vector<int> w=dfs(n-1,na^1,nb);
    int u=a/(1<<(n-1));
    if(u%2)rep(i,0,v.size())v[i]^=1<<(n-1);
    else rep(i,0,w.size())w[i]^=1<<(n-1);
    rep(i,0,w.size())v.push_back(w[i]);
    rep(i,0,v.size())swa(v[i],n-1,d);
    return v;

}
