		x = ~x;
		int i = log2(x & -x);
		mark |= (1 << i);
		int vis = mark;
		find_answer(a, b, m - 1);
		int pre = answer[ptr - 2];
		ptr --;
		mark = vis;
		find_answer(pre ^ (1 << i), b ^ (1 << i), m - 1);
		answer[ptr ++] = b;
		return;
	}
	for (int i = 0; i < n; i++){
		if (k & (1 << i)){
			for (int j = i + 1; j < n; j++){
				if (k & (1 << j)){
					mark |= (1 << j);
					int vis = mark;
					find_answer(a, a ^ (1 << i), m - 1);
					mark = vis;
					find_answer(a ^ (1 << i) ^ (1 << j), b, m - 1);
					mark |= (1 << i);
				}
			}
		}
	}
