int n, a, b;
void input() {
	cin >> n >> a >> b;
}

int solve() {
	vector<int> d;
	bitset<17> ar(a), br(b);
	int dif = 0, rem = POW(2, n)-2;
	FOR(i, 0, 17) {
		if(ar[i] != br[i]) ++dif, d.pb(i);
	}
	vector<bitset<17>> ans;
	ans.pb(ar);
	// 일단 가까이 가 (같아질 때까지)
	for(int x : d) {
		if(rem == 0) {
			if(dif != 1) {
				cout << "NO" << ENDL;
				return 0;
			}
			break;
		}
		bitset<17> cur = ans.back();
		cur[x] = br[x];
		ans.pb(cur);
		--rem;
		--dif;
	}
	// dif가 1인데 남은게 없으면 가능
	if(dif == 1) {
		ans.pb(br);
		cout << "YES" << ENDL;
		FOR(i, 0, ans.size()) {
			cout << ans[i].to_ulong() << ' ';
		}
		return 0;
	}
	// 같은데 남은게 짝수개 만큼 있으면 결국 같아져야 해서 안 돼
	if(rem % 2 == 0) {
		cout << "NO" << ENDL;
		return 0;
	}
	// 남은거 그냥 아래자리만 바꿔줘
	while(rem) {
		--rem;
		bitset<17> cur = ans.back();
		cur[0] =  cur[0] ^ 1;
		ans.pb(cur);
	}
	ans.pb(br);
	cout << "YES" << ENDL;
	FOR(i, 0, ans.size()) {
		cout << ans[i].to_ulong() << ' ';
	}
	cout << ENDL;
	return 0;
}

