void calc(int l, int r, int a, int b, int n){
	if (l == r - 1){
		ans[l] = a;
		return;
	}
	int m = (l + r) / 2;
	int x = __builtin_ctz(a ^ b);
	if (a & (1 << x)){
		calc(m, r, b ^ 1, b, n - 1);
		forn(i, m - l) ans[l + i] = (ans[r - i - 1] & ((1 << x) - 1)) ^ (1 << x) ^ ((ans[r - i - 1] & (~((1 << x) - 1))) << 1);
		fore(i, m, r) ans[i] = (ans[i] & ((1 << x) - 1)) ^ ((ans[i] & (~((1 << x) - 1))) << 1);
	}
	else{
		calc(l, m, a, a ^ 1, n - 1);
		forn(i, r - m) ans[m + i] = (ans[m - i - 1] & ((1 << x) - 1)) ^ (1 << x) ^ ((ans[m - i - 1] & (~((1 << x) - 1))) << 1);
		fore(i, l, m) ans[i] = (ans[i] & ((1 << x) - 1)) ^ ((ans[i] & (~((1 << x) - 1))) << 1);
	}
}

void solve(){
	int tmp = a;
	a ^= tmp;
	b ^= tmp;
	calc(0, 1 << n, a, b, n - 1);
	fore(i, 0, 1 << n) ans[i] ^= tmp;

	bool ok = sz(set<int>(ans, ans + (1 << n))) == (1 << n);
	ok &= *max_element(ans, ans + (1 << n)) == (1 << n) - 1;
	ok &= (ans[0] == (a ^ tmp));
	ok &= (ans[(1 << n) - 1] == (b ^ tmp));
	forn(i, (1 << n) - 1)
		ok &= (__builtin_popcount(ans[i] ^ ans[i + 1]) == 1);

