vector<int> genka(int n, int a, int b) {
    if (n == 1) {
        return {a, b};
    }
    assert(__builtin_popcount(a ^ b) & 1);
    int ca = (a >> (n - 1)) & 1;
    int cb = (b >> (n - 1)) & 1;
    if (ca != cb) {
        int wb = 0;
        if (ca)  {
            a ^= (1 << (n - 1));
            b ^= (1 << (n - 1));
            wb = 1;
        }
        for (int mid = 0; mid < (1 << (n - 1)); mid++) {
            if (__builtin_popcount(mid ^ a) % 2 == 0) continue;
            if (__builtin_popcount((1 << (n - 1)) ^ mid ^ b) % 2 == 0) continue;
            {
                vector<int> f = genka(n - 1, a, mid);
                vector<int> s = genka(n - 1, mid, b ^ (1 << (n - 1)));
                for (auto t : s) {
                    f.push_back(t ^ (1 << (n - 1)));
                }
                if (wb) {
                    for (auto &t : f) {
                        t ^= (1 << (n - 1));
                    }
                }
                return f;
            }
        }
    } else {
        int wb = 0;
        if (ca)  {
            a ^= (1 << (n - 1));
            b ^= (1 << (n - 1));
            wb = 1;
        }
        vector<int> f = genka(n - 1, a, b);
        {
            int i = 0; 
            int x = f[i];
            int y = f[i + 1];
            vector<int> s = genka(n - 1, x, y);
            vector<int> ans = {f[0]};
            for (auto t : s) {
                ans.push_back(t ^ (1 << (n - 1)));
            }
            for (int j = 1; j < (int)f.size(); j++) {
                ans.push_back(f[j]);
            }
            if (wb) {
                for (auto &t : ans) {
                    t ^= (1 << (n - 1));
                }
            }
            return ans;
        }
    }
}

