int n;

vector<int> calc(int a, int b, int mask){
  vector<int> res;
  if(__builtin_popcount(mask) == 1){
    res.pb(a);
    res.pb(b);
    return res;
  }
  int i;
  for(; i < n; i++)if((mask >> i) & 1){
    if(((a >> i) & 1) != ((b >> i) & 1))break;
  }
  mask ^= bit(i);
  int j;
  for(; j < n; j++)if((mask >> j) & 1){
    break;
  }
  int c = a ^ bit(j);
  vector<int> sub1 = calc(a, c, mask);
  vector<int> sub2 = calc(c, b, mask);
  for(auto e: sub1){
    if((a >> i) & 1)res.pb(e | bit(i));
    else res.pb(e & (~bit(i)));
  }
  for(auto e: sub2){
    if((a >> i) & 1)res.pb(e & (~bit(i)));
    else res.pb(e | bit(i));
  }
  return res;
}

