void solve(int l, int r, int s, int t, int c){
	int i,x=-1,m;
	if(r-l==2){
		ans[l] += s;
		ans[l+1] += t;
		return;
	}
	for(i=0; i<n; ++i){
		if(c&(1<<i)){
			continue;
		}
		if((s&(1<<i))^(t&(1<<i)) && x<0){
			x = i;
		}else{
			m = s^(1<<i);
		}
	}
	if(s&(1<<x)){
		for(i=l; i<(l+r)/2; ++i){
			ans[i] += (1<<x);
		}
	}else{
		for(i=(l+r)/2; i<r; ++i){
			ans[i] += (1<<x);
		}
	}
	s -= (s&(1<<x));
	t -= (t&(1<<x));
	m -= (m&(1<<x));
	c += (1<<x);
	solve(l,(l+r)/2,s,m,c);
	solve((l+r)/2,r,m,t,c);
}

