int without(int V, int inx) {
    return (V % (1 << inx)) + ((V >> (inx + 1)) << inx);
}

int insert(int V, int inx, int val) {
    return (V % (1 << inx)) + ((V >> inx) << (inx + 1)) + (val << inx);
}

vi go(int N, int A, int B) {
    if (N == 1) {
        assert(A != B);
        return { A, B };
    }

    for (int i = 0; i < N; i++) {
        if ((A^B) & (1 << i)) {
            int AA = without(A, i),
                BB = without(B, i);

            vi left  = go(N - 1, AA, AA^1),
               right = go(N - 1, AA^1, BB);

            vi res;
            for (int v : left)
                res.push_back(insert(v, i, (A >> i)&1));
            for (int v : right)
                res.push_back(insert(v, i, (B >> i)&1));
            return res;
        }
    }

    assert(false);
}

