vector<int> gray(int N)
{
    if (N == 1)
        return { 0,1 };

    auto tmp = gray(N - 1);
    auto reflected = tmp; reverse(reflected.begin(), reflected.end());

    // z tmp nic nie rob - 0 na poczatku bardzo latwo dodac
    for (int &g : reflected)
        g += 1 << (N - 1);

    std::move(reflected.begin(), reflected.end(), std::back_inserter(tmp));
    return tmp;
}

