int ileB(int x)
{
    int res = 0;
    while (x)
    {
        x &= (x - 1);
        res++;
    }

    return res;
}

void check(vector<int> &tmp, vector<int> &rest, int A, int B)
{
    // sprobuj wcisnac rest i odwrocony rest
    REP(i, tmp.size() - 1)
    {
        if (ileB(rest.front() ^ tmp[i]) == 1 && ileB(rest.back() ^ tmp[i + 1]) == 1)
        {
            tmp.insert(tmp.begin() + i + 1, rest.begin(), rest.end());
            if (A != tmp.front())
                reverse(tmp.begin(), tmp.end());
            output(tmp);
        }
        if (ileB(rest.back() ^ tmp[i]) == 1 && ileB(rest.front() ^ tmp[i + 1]) == 1)
        {
            reverse(rest.begin(), rest.end());
            tmp.insert(tmp.begin() + i + 1, rest.begin(), rest.end());
            if (A != tmp.front())
                reverse(tmp.begin(), tmp.end());
            output(tmp);
        }
    }
}

int main()
{
