    scanf("%d%d%d", &N, &A, &B);

    auto G = gray(N);
    if (A == G.front() && B == G.back())
        output(G);
    else if (A == G.back() && B == G.front())
    {
        reverse(G.begin(), G.end());
        output(G);
    }
    else
    {
        REP(i, G.size() - 1)
            if (A == G[i] && B == G[i + 1])
            {
