                    printf("%d ", G[j]);
                REP(j, i + 1)
                    printf("%d ", G[j]);
                printf("\n");
                return 0;
            }
    }

    // sprobuj rozciac kod
    int posA, posB;
    REP(i, G.size())
    {
        if (G[i] == A)
            posA = i;
        if (G[i] == B)
            posB = i;
    }

    // wykroj srodek
    {
        vector<int> tmp, rest;
        FORQ(i, min(posA, posB), max(posA, posB))
            tmp.push_back(G[i]);
        FORD(i, min(posA, posB), 0)
            rest.push_back(G[i]);
