int delBit(int x, int bit) {
  return (x & ((1 << bit) - 1)) + ((x >> (bit + 1)) << bit);
}

int addBit(int x, int bit, int val) {
  return (x & ((1 << bit) - 1)) + (val << bit) + ((x >> bit) << (bit + 1));
}

vector<int> rec1(int n, int a) {
  if (n == 1) {
    return {a, a ^ 1};
  }
  int bit = 0;
  vector<int> l = rec1(n - 1, delBit(a, bit));
  for (int i = 0; i < sz(l); i++) {
    l[i] = addBit(l[i], bit, ((a >> bit) & 1));
  }
  int c = l.back();
  c ^= (1 << bit);
  vector<int> r = rec1(n - 1, delBit(c, bit));
  for (int i = 0; i < sz(r); i++) {
    r[i] = addBit(r[i], bit, ((c >> bit) & 1));
  }
  vector<int> res = l;
  for (int i = 0; i < sz(r); i++) {
    res.push_back(r[i]);
  }
  return res;
}

vector<int> rec(int n, int a, int b) {
  if (n == 1) {
    return {a, b};
  }
  int bit = 0;
  while ((a & (1 << bit)) == (b & (1 << bit))) {
    bit++;
  }
  vector<int> l = rec1(n - 1, delBit(a, bit));
  for (int i = 0; i < sz(l); i++) {
    l[i] = addBit(l[i], bit, ((a >> bit) & 1));
  }
  int c = l.back();
  c ^= (1 << bit);
  vector<int> r = rec(n - 1, delBit(c, bit), delBit(b, bit));
  for (int i = 0; i < sz(r); i++) {
    r[i] = addBit(r[i], bit, ((b >> bit) & 1));
  }
  vector<int> res = l;
  for (int i = 0; i < sz(r); i++) {
    res.push_back(r[i]);
  }
  return res;
}

void solve() {
  if (!(__builtin_popcount(a ^ b) & 1)) {
    printf("NO\n");
    return;
  }
  vector<int> ans = rec(n, a, b);
  printf("YES\n");
  for (int i = 0; i < sz(ans); i++) {
    printf("%d ", ans[i]);
  }
  printf("\n");
}

