int N, A, B;

void solve(int s, int t, int mask, vector<int> &ret)
{
	if (__builtin_popcount(mask) == 1) {
		ret.push_back(s);
		ret.push_back(t);
		return;
	}
	int d = (s ^ t) & mask;
	vector<int> ones, zeros;
	for (int i = 0; i < N; ++i) if ((mask >> i) & 1) {
		if ((d >> i) & 1) {
			ones.push_back(i);
		} else {
			zeros.push_back(i);
		}
	}
	//printf("%d %d %d %d %d\n", s, t, mask, ones.size(), zeros.size());
	if (ones.size() >= 2) {
		solve(s, t ^ (1 << ones[0]) ^ (1 << ones[1]), mask ^ (1 << ones[0]), ret);
		solve(t ^ (1 << ones[1]), t, mask ^ (1 << ones[0]), ret);
	} else {
		solve(s, s ^ (1 << zeros[0]), mask ^ (1 << ones[0]), ret);
		solve(s ^ (1 << zeros[0]) ^ (1 << ones[0]), t, mask ^ (1 << ones[0]), ret);
	}
}

int main()
{
	scanf("%d%d%d", &N, &A, &B);

	if ((__builtin_popcount(A) % 2) == (__builtin_popcount(B) % 2)) {
		puts("NO");
