ll N;

vector<ll> solve(ll mask, ll A, ll B) {
    ll tmp = A;
    vector<ll> ans;
    ll masknum = 0;
    REP(i, 0, N) {
        if (mask & (1 << i)) {
            masknum++;
        }
    }
    ll id = -1;
    REP(i, 0, N) {
        if ((A & (1 << i)) != (B & (1 << i))) {
            id = i;
            break;
        }
    }
    if (masknum == 1) {
        ans.push_back(tmp);
        return ans;
    }
    ll difnum[masknum - 1];
    ll ind = 0;
    REP(i, 0, N) {
        if (mask & (1 << i)) {
            if (i != id) {
                difnum[ind] = i;
                ind++;
            }
        }
    }
    REP(i, 0, (1 << (masknum - 1))) {
        ans.push_back(tmp);
        if (i != (1 << (masknum - 1)) - 1) {
            ll lastbit = 0;
            REP(j, 0, N) {
                if ((i + 1) & (1 << j)) {
                    lastbit = j;
                    break;
                }
            }
            tmp ^= (1 << difnum[lastbit]);
        }
    }
    vector<ll> suf = solve(mask ^ (1 << id), tmp ^ (1 << id), B);
    ans.insert(ans.end(), suf.begin(), suf.end());
    return ans;
}

