vec make(int n, int a, int b){
    if(n == 1) return {a, b};
    int diff = a ^ b, bit = -1;
    int a_bit, b_bit;
    rep(i,n) if((diff>>i) & 1) {
        bit = i;
        a_bit = ((a>>bit)&1)<<bit;
        b_bit = ((b>>bit)&1)<<bit;
    }
    int la = ((a >> (bit + 1))<<bit) + a % (1<<bit);
    int rb = ((b >> (bit + 1))<<bit) + b % (1<<bit);
    vec left = make(n - 1, la, la ^ 1), right = make(n - 1, la ^ 1, rb);
    vec res(1<<n);
    rep(i, 1<<(n - 1)){
        res[i] = ((left[i] >> bit)<<(bit + 1)) + left[i] % (1<<bit) + a_bit;
    }
    rep(i, 1<<(n - 1)){
        res[i + (1 << (n - 1))] = ((right[i]>>bit)<<(bit + 1)) + right[i] % (1<<bit) + b_bit;
    }
    return res;
}

