int popcount(int bits) {
	bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
	bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
	bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
	bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
	return (bits & 0x0000ffff) + (bits >> 16 & 0x0000ffff);
}

long long fact[18] = {1};
inline int comb(int n, int k) {
	return fact[n] / fact[n - k] / fact[k];
}

int N, A, B;

bool searchUpdown(std::vector<int>& res, int i) {
	static int count[18] = {};

	int cur = res.back();
	if (cur < 0 || N < cur)
		return false;

	++count[cur];
	if (count[cur] > comb(N, cur)) {
		--count[cur];
		return false;
	}

	if (i == (1 << N) - 1) {
		if (cur != popcount(B)) {
			--count[cur];
			return false;
		}

		return true;
	}

	res.push_back(cur + 1);
	if (searchUpdown(res, i + 1))
		return true;

	res.pop_back();
	res.push_back(cur - 1);
	if (searchUpdown(res, i + 1))
		return true;

	res.pop_back();
	--count[cur];
	return false;
}

int main() {
	for (int i = 1; i <= 17; ++i)
		fact[i] = i * fact[i - 1];

	std::cin >> N >> A >> B;

	int a = popcount(A), b = popcount(B);

	if (std::abs(a - b) % 2 == 0) {
		std::cout << "NO" << std::endl;
		return 0;
	}

	std::vector<int> numBits;
	numBits.reserve(1 << N);
	numBits.push_back(a);
	if (!searchUpdown(numBits, 0)) {
		std::cout << "NO" << std::endl;
		return 0;
	}

	std::vector<int> ans;
	ans.reserve(1 << N);
	ans.push_back(A);
	std::set<int> used;
	used.insert(A);
	used.insert(B);
	for (int i = 1; i <= (1 << N) - 2; ++i) {
		bool resolved = false;
		for (int j = 0; j < N; ++j) {
			int next;
			if (numBits[i] > numBits[i - 1]) {
				next = ans.back() | (1 << j);
				if (next == ans.back())
					continue;
			}
			else {
				next = ans.back() & ~(1 << j);
				if (next == ans.back())
					continue;
			}

			if (used.count(next) == 0) {
				ans.push_back(next);
				used.insert(next);
				resolved = true;
				break;
			}
		}

		if (!resolved) {
			std::cout << "NO" << std::endl;
			return 0;
		}
	}
	ans.push_back(B);

	std::cout << "YES" << std::endl;
	std::cout << ans.front();
	for (int i = 1; i < ans.size(); ++i)
		std::cout << " " << ans[i];

	std::cout << std::endl;
}

