#define REP(NAME, NUM) for (int NAME = 0; NAME < (NUM); ++NAME)
#define BREP(NAME, NUM) for (int NAME = (NUM)-1; NAME >= 0; --NAME)
#define ALL(NAME) (NAME).begin(), (NAME).end()

#define bpll __builtin_popcountll
#define bi( NAME, i ) ( NAME & 1 << i )

void dfs( int start, int end, int mask, int n )
{
	//cout << start << "&" << end << "&" << mask << endl;
	REP(i,n)
	{
		if( bi(start, i) != bi( end, i ) && bi( mask, i ) == 0 )
		{
			mask += 1 << i;

			if( bpll(mask) == n )
			{
				cout << start << " ";
				return;
			}

			int k=0;
			for(;k<n;++k) if( bi(mask,k)==0 ) break;
			int mid = start ^ ( 1 << k );
			if( ( mid ^ 1 << i ) == end )
			{
				for(k=k+1;k<n;++k) if( bi(mask,k)==0 ) break;
				mid = start ^ ( 1 << k );
			}

			dfs( start, mid, mask, n );
			cout << mid << " ";
			mid ^= 1 << i;
			dfs( mid, end, mask, n );
			break;
		}
	}
}

int main()
{
	ll n, a, b;
	cin >> n >> a >> b;

	if( ( bpll(a) + bpll(b) ) % 2 == 0 )
	{
		cout << "NO" << endl;
	}
	else
	{
		cout << "YES" << endl;
		dfs( a, b, 0, n );
		cout << b;
	}

	return 0;
}

