using namespace std;
typedef long long ll;
typedef long double ld;

const int maxn = (1 << 17) + 100;
const int mod = 1e9 + 7;

int n, pow2n;
int answer[maxn], ptr = 0;
int mark;

void find_answer(int a, int b, int m){
	if (m == 1){
		answer[ptr ++] = a;
		answer[ptr ++] = b;
		return;
	}
	int k = a ^ b;
	bool flag = 0;
	for (int i = 0; i < n; i++){
		if ((mark & (1 << i)) or (k & (1 << i)))
			continue;
		flag = 1;
		mark |= (1 << i);
		int vis = mark;
		find_answer(a, b, m - 1);
		int pre = answer[ptr - 2];
		ptr --;
		mark = vis;
		find_answer(pre ^ (1 << i), b ^ (1 << i), m - 1);
		answer[ptr ++] = b;
	}
	if (flag == 1)
		return;
	for (int i = 0; i < n; i++){
		if (k & (1 << i)){
			for (int j = i + 1; j < n; j++){
				if (k & (1 << j)){
					mark |= (1 << j);
					int vis = mark;
					find_answer(a, a ^ (1 << i), m - 1);
					mark = vis;
					find_answer(a ^ (1 << i) ^ (1 << j), b, m - 1);
					mark |= (1 << i);
				}
			}
		}
	}
}

