#include <bits/stdc++.h>

using namespace std;

const int N = 200 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n, A, B;

bool read() {
    if (!(cin >> n >> A >> B))
        return false;

    return true;
}

vector<int> calc(int A, int B, int mask) {
    if (__builtin_popcount(mask) == 1)
        return { A, B };

    for (int i = 0; i < n; ++i)
        if (((mask >> i) & 1) && (((A ^ B) >> i) & 1)) {
            mask ^= (1 << i);
            auto A1 = (A & mask);
            auto B1 = (B & mask);

            for (int C = mask; ; C = ((C - 1) & mask))
                if (__builtin_popcount(C) % 2 != __builtin_popcount(A1) % 2) {
                    auto left = calc(A1, C, mask);
                    auto right = calc(C, B1, mask);

                    for (auto& r : (((A >> i) & 1) ? left : right))
                        r |= (1 << i);

                    left.insert(left.end(), right.begin(), right.end());
                    return left;
                }
        }
}

void solve() {
    if (__builtin_popcount(A) % 2 == __builtin_popcount(B) % 2) {
        cout << "NO\n";
        return ;
    }

    auto ans = calc(A, B, (1 << n) - 1);
    cout << "YES\n";

    for (const auto& i : ans)
        cout << i << ' ';

    cout << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

