  return n == 0 ? 0 : count(n & n - 1) + 1;
}

vector<int> f(int m, int a, int b) {
  if (m == 0) return {a};
  if (m == 1) return {a, b};
  int x = (a ^ b) & m;
  x = x & -x;
  int y = m ^ x;
  y = y & -y;
  auto l = f(m ^ x, a, a ^ y);
  auto r = f(m ^ x, a ^ y ^ x, b);
  l.insert(l.end(), r.begin(), r.end());
  return l;
}

