vector<int> calc(int a, int b, int n) {
    if (n == 1) return {a, b};
    int s = __builtin_ffs(a^b);
    int t = 0;
    if ((a & (1 << (s-1))) != 0) t = (1 << (s-1));
    int aa = a % (1 << (s-1)) + ((a >> s) << (s-1));
    int bb = b % (1 << (s-1)) + ((b >> s) << (s-1));
    int d = aa ^ 1;
    //cout << a << b << " " << aa << " " << bb << " " << d <<  endl;
    vector<int> e = calc(aa, d, n-1), f = calc(d, bb, n-1);
    for (int i = 0; i < (int)e.size(); i++) e[i] = ((e[i] >> (s-1)) << s) + t + e[i] % (1 << (s-1));
    for (int q : f) e.push_back(((q >> (s-1)) << s) + (1 << (s-1))-t + q % (1 << (s-1)));
    return e;
}

int main(){
    int N, A, B;
    cin >> N >> A >> B;
    if (__builtin_parity(A^B) == 0) {
        cout << "NO" << endl;
        return 0;
    }

    vector<int> ans = calc(A, B, N);

    cout << "YES\n";
    for (int i = 0; i < (1<<N); i++) {
        if (i < (1<<N)-1) printf("%d ", ans[i]);
        else printf("%d\n", ans[i]);
    }
    return 0;
}

