using namespace std;

int lowbit(int x) {
  return x & -x;
}

int Bc(int x) {
  int r = 0;
  while (x) ++r, x -= lowbit(x);
  return r;
}

void Solve(int a, int b, int ext) {
  if (a == b) {
    cout << (a | ext) << ' ';
    return;
  }
  int xo = a ^ b;
  int y = lowbit(xo);
  if (a & y) {
    int c = a ^ y ^ lowbit(a ^ y);
    Solve(a ^ y, c, ext | y);
    int d = b ^ lowbit(b);
    Solve(d, b, ext);
  } else {
    int c = a ^ lowbit(a);
    Solve(a, c, ext);
    int d = b ^ y ^ lowbit(b ^ y);
    Solve(d, b ^ y, ext | y);
  }
}

