int n;
vector<int> Go(int m1, int m2, int a, int b) {
	int i;
	vector<int>T, res;
	for (i = 0; i < n; i++) {
		if (!((m1 >> i) & 1))T.push_back(i);
	}
	if (T.size() == 1) {
		res.push_back(a);
		res.push_back(b);
		return res;
	}
	int pv = T[0];

	int ck = (a >> pv) & 1;
	int ck2 = (b >> pv) & 1;

	if (ck != ck2) {
		vector<int>U = Go(m1 | (1 << pv), m2 | (ck << pv), a, a ^ (1<<T[1]));
		vector<int>V = Go(m1 | (1 << pv), m2 | (ck2 << pv), a^(1<<T[1])^(1<<pv), b);
		for (auto &t : U)res.push_back(t);
		for (auto &t : V)res.push_back(t);
		return res;
	}
	else {
		vector<int>U = Go(m1 | (1 << pv), m2 | (ck << pv), a, b);
		vector<int>V = Go(m1 | (1 << pv), m2 | ((1 - ck) << pv), U[0] ^ (1 << pv), U[1] ^ (1 << pv));
		res.push_back(U[0]);
		for (auto &t : V)res.push_back(t);
		for (i = 1; i < U.size(); i++)res.push_back(U[i]);
	}
	return res;
}
