		if((sn[f][cur] = xsn)) fa[xsn] = f;
		fa[xsn = f] = x;
		Up(f), Up(x);
	}
	void splay(int x, int goal) {
		int f;
		while((f = fa[x]) != goal) {
			Down(fa[f]), Down(f), Down(x);
			if(fa[f] != goal) {
				if(dotira(x) == dotira(f)) rotate(f);
				else rotate(x);
			}
			rotate(x);
		}
		if(!goal) rt = x;
	}
	int tonari(int x, int cur) {
		splay(x, 0);
		x = sn[x][cur];
		while(Down(x), sn[x][cur ^ 1]) x = sn[x][cur ^ 1];
		return x;
	}
	inline int findkth(int k) {
		int x = rt, totsz;
	findst:
		Down(x);
		totsz = sz[sn[x][0]] + 1;
		if(k > totsz) x = sn[x][1], k -= totsz;
		else if(k <= sz[sn[x][0]]) x = sn[x][0];
		else return x;
		goto findst;
	}
	void print(int x, int n) {
		if(x == 0) return;
		Down(x);
		print(sn[x][0], n);
		if(x > 1 && x < n + 2)
			printf("%d ", x - 1);
		print(sn[x][1], n);
	}
	int split(int x, int y) {
		splay(x, 0), splay(y, x);
		int p = sn[y][0];
		sn[y][0] = 0;
		fa[p] = 0;
		Up(y), Up(x);
		return p;
	}
	inline void New(int x, int cur, int p) {
		int f = tonari(x, cur);
		splay(x, 0);
		if(f) splay(f, x), sn[f][cur ^ 1] = p, Up(f), Up(x);
		else if(x) sn[f = x][cur] = p, Up(x);
		fa[p] = f;
		splay(p, 0);
	}
}
