int pc(int n) { return __builtin_popcount(n); }

int ith(int n) {
  for (int i = 0; i < 17; ++i)
    if (n >> i & 1) return i;

  return -1;
}

void verify(std::vector<int> res, int A, int B) {
  assert(res.front() == A);
  assert(res.back() == B);
  int M = res.size();
  for (int i = 1; i < M; ++i)
    assert(pc(res[i]^res[i-1]) == 1);

  std::sort(res.begin(), res.end());
  for (int i = 0; i < M; ++i)
    assert(res[i] == i);
}

std::vector<int> cons_by_gray(int N, int A, int B) {
  int M = (1 << N);
  std::vector<int> gray(M);
  for (int i = 0; i < M; ++i)
    gray[i] = i ^ (i>>1);

  int pa = pc(A);
  int pb = pc(B);

  int b = -1;
  std::vector<int> bin(N, -1);
  for (int i = 0; i < M; ++i) {
    int pi = i-1;
    if (pi < 0) pi += M;

    if (!(pc(gray[pi]) == pa && pc(gray[i]) == pb)) continue;

    std::set<int> unused;
    for (int j = 0; j < N; ++j) unused.insert(j);

    bin[ith(gray[pi]^gray[i])] = ith(A^B);
    fprintf(stderr, "- [%d] <- %d\n", ith(gray[pi]^gray[i]), ith(A^B));
    unused.erase(ith(A^B));

    int gg = gray[pi] & gray[i];
    int ab = A & B;
    std::vector<int> gp;
    std::vector<int> ap;
    for (int j = 0; j < N; ++j) {
      if (gg >> j & 1) gp.push_back(j);
      if (ab >> j & 1) ap.push_back(j);
    }

    assert(gp.size() == ap.size());
    fprintf(stderr, "size(): %zu\n", gp.size());

    for (size_t j = 0; j < gp.size(); ++j) {
      bin[gp[j]] = ap[j];
      fprintf(stderr, "0 [%d] <- %d\n", gp[j], ap[j]);
      unused.erase(ap[j]);
    }
    for (int j = 0; j < N; ++j) {
      for (int k = 0; k < N; ++k)
      if (bin[j] == -1) {
        auto it = unused.begin();
        bin[j] = *it;
        unused.erase(it);
      }
    }
    b = i;
    break;
  }

  assert(b != -1);
  // 1 0, 0 1

  for (int i = 0; i < M; ++i)
    fprintf(stderr, "%d -> %d\n", i, gray[(i+b)%M]);

  for (int i = 0; i < N; ++i)
    fprintf(stderr, "%d-th -> %d\n", i, bin[i]);

  std::vector<int> res;
  for (int i = 0; i < M; ++i) {
    int cur = 0;
    for (int j = 0; j < N; ++j)
      if (gray[(i+b)%M] >> j & 1) cur |= 1 << bin[j];

    res.push_back(cur);
  }

  std::reverse(res.begin(), res.end());
  return res;
}

int main() {
  int N, A, B;
  scanf("%d %d %d", &N, &A, &B);

  std::vector<int> res;
  if (pc(A ^ B) == 1)
    res = cons_by_gray(N, A, B);

  if (res.empty()) {
    assert(!(A == 0 || B == 0));

    return puts("NO"), 0;
  }

  verify(res, A, B);

  puts("YES");
  int M = (1 << N);
  for (int i = 0; i < M; ++i)
    printf("%d%c", res[i], i+1<M? ' ':'\n');
}

