vector<int> code(int n) {
	if (n == 1) {
		return {0, 1};
	}
	vector<int> l = code(n - 1);
	vector<int> r = l;
	reverse(r.begin(), r.end());
	for (auto &i : r) {
		l.pb(i + (1 << (n - 1)));
	}
	return l;
}

