const int MAXBITS = 18;
const int MAXN    = 1 << MAXBITS;

int res[MAXN];
int link[MAXN];

int main() {
    int N, A, B;
    scanf(" %d %d %d", &N, &A, &B);

    for (int bit = 0; bit < MAXBITS; bit++) {
        int seqsz = 1 << (bit + 1);
        int remains = seqsz >> 1;
        int cur = 0;
        for (int num = 0; num < MAXN; num++) {
            res[num] |= cur * (1 << bit);
            remains--;

            if (!remains) {
                remains = seqsz;
                cur ^= 1;
            }
        }
    }

    for (int i = 0; i < MAXN; i++) {
        link[res[i]] = i;
    }

    int start     = link[A];
    int end       = link[B];
    int positions = 1 << N;

    #ifdef LOCAL
        cout << start << " | " << end <<endl;
    #endif

    bool possible = false;

    if ((start + 1) % positions == end)
        possible = true;

    bool inverse = false;

    if (((start - 1 + positions) % positions)  == end) {
        possible = true;
        inverse = true;
    }


    if (!possible) {
        printf("NO\n");
    } else {
        printf("YES\n");

        int step = -1;

        if (inverse)
            step *= -1;

        while (start != end) {
            printf("%d ", res[start]);

            start = (start + step) % positions;
            while (start < 0) {
                start += positions;
            }
        }

        printf("%d\n", res[start]);
    }



    return 0;
}

