/* subroutines */

int bitp(int a) {
  int p = 0;
  for (int bi = 1; bi <= a; bi <<= 1)
    if (a & bi) p ^= 1;
  return p;
}

void rec(int a, int b, int msk, int c) {
  if (msk == 0) {
    v[vn++] = c;
    return;
  }

  int bi = 1;
  for (;; bi <<= 1)
    if ((msk & bi) && (a & bi) != (b & bi)) break;
  int abi = (a & bi), bbi = (b & bi);
  int mski = msk ^ bi;
  int ac = c | abi, bc = c | bbi;

  if (mski == 0) {
    v[vn++] = ac;
    v[vn++] = bc;
  }
  else {
    int bj = 1;
    for (; ! (mski & bj); bj <<= 1);
    int d = (a & mski) ^ bj;
    rec(a, d, mski, ac);
    rec(d, b, mski, bc);
  }
}

