    vector<int> p = solve(n, a, b);
    if (p.empty()) {
        cout << "NO" << endl;
    } else {
        cout << "YES" << endl;
        for (int p_i : p) {
            cout << p_i << ' ';
        }
        cout << endl;
    }
    return 0;
}

