vector<int> solve(int A,int B,int n) {
	if(n==1) {
		return {A,B};
	}
	int p=0;
	for(int i=0;i<n;i++)
		if((A>>i&1)!=(B>>i&1)) { p=i;break; }
	int C=p==0?A^2:A^1;
	auto l=solve(erase(A,p),erase(C,p),n-1);
	auto r=solve(erase(C,p),erase(B,p),n-1);
	vector<int> ret;
	for(auto x:l) ret.pb(insert(x,p,A>>p&1));
	for(auto x:r) ret.pb(insert(x,p,B>>p&1));
	return ret;
}

