/*-----8<-----template-----8<-----*/
inline ll up(ll bit, ll i) { return bit | (1LL<<i); }
inline ll down(ll bit, ll i) { return bit & ~(1LL<<i); }
inline ll inverse(ll bit, ll i) { return bit ^ (1LL<<i); }
inline bool isup(ll bit, ll i) { return bit & (1LL<<i); }
inline bool isdown(ll bit, ll i) { return !(bit & (1LL<<i)); }
//__builtin_popcount(bit); -> bitの立っている個数を返す
/*-----8<-----library-----8<-----*/

void solve() {
	ll N,A,B;
	cin>>N>>A>>B;
	if(__builtin_popcount(A)%2==__builtin_popcount(B)%2){
		p("NO");return;
	}
	p("YES");

	//0->Cを考える
	ll C=B^A;
	vector<ll> ans;

	auto f = [&](auto&& f, ll x, ll y, ll s,vector<ll> &ans){
		debug(x,y,s);
		if(__builtin_popcount(s)==N-1)return;

		//x,yのうち片方だけビットが立っている位置を探す
		ll bit;
		rrep(i,N){
			if(isup(s,i))continue;
			ll t=isup(x,i)+isup(y,i);
			if(t==1){
				bit=i;
				break;
			}
		}
		s=up(s,bit);

		ll invbit;
		rep(i,N){
			if(isdown(s,i)){
				invbit=i;break;
			}
		}

		//x,yとビットの偶奇が異なるビットを作る(zz)
		//z0,z1 x,yのうち片方だけビットが立っている位置のz0立ってない,z1立っているビット
		ll zz=inverse(x,invbit);
		ll z0=down(zz,bit);
		ll z1=up(zz,bit);
		debug(bit,invbit,z0,z1);

		//x->z0 -> z1->y もしくは x->z1 -> z0->y を再帰的に構成
		if(isdown(x,bit)){
			f(f,x,z0,s,ans);
			ans.push_back(z0);
			ans.push_back(z1);
			f(f,z1,y,s,ans);
		}else{
			f(f,x,z1,s,ans);
			ans.push_back(z1);
			ans.push_back(z0);
			f(f,z0,y,s,ans);
		}

	};

	ans.push_back(0);
	f(f,0,C,0,ans);
	ans.push_back(C);

	rep(i,ans.size())ans[i]^=A;
	pv(ans);
}

signed main() {
	solve();
	return 0;
}

