// wbit整数Aを左に回す
inline int lslide(int A, int w, int k) {
    return ((A & ((1 << (w - k)) - 1)) << k) + (A >> (w - k));
}

// wbit整数Aを右に回す
inline int rslide(int A, int w, int k) {
    return (A >> k) + ((A & ((1 << k) - 1)) << (w - k));
}

vector<int> dp[20];

// [0, 2^w)全体を回るようなサイクルを作る
vector<int> cycle(int w) {
    if (w == 0) return {0};
    if (!dp[w].empty()) return dp[w];

    vector<int> head = cycle(w - 1);
    vector<int> tail = head;
    reverse(tail.begin(), tail.end());
    for (auto& t : tail) t += (1 << (w - 1));
    copy(tail.begin(), tail.end(), back_inserter(head));
    return dp[w] = head;
}

vector<int> solve(int A, int B, int N) {
    if (N == 1) return {A, B};

    int k;
    for (k = 0; k < N; ++k) {
        if (((A >> (N - 1 - k)) & 1) != ((B >> (N - 1 - k)) & 1)) break;
    }
    A = lslide(A, N, k), B = lslide(B, N, k);

    vector<int> ch = cycle(N - 1);
    for (auto& c : ch) c ^= A;

    auto res = solve(ch.back() & ((1 << (N - 1)) - 1), B & ((1 << (N - 1)) - 1), N - 1);
    for (auto& c : res) c ^= B & (1 << (N - 1));
    copy(res.begin(), res.end(), back_inserter(ch));

    for (auto& a : ch) a = rslide(a, N, k);
    return ch;
}

int main() {
    int N, A, B;
    cin >> N >> A >> B;

    cerr << bitset<20>(A) << endl;
    cerr << bitset<20>(B) << endl;

    if (__builtin_popcount(A ^ B) % 2 == 0) {
        cout << "NO" << endl;
        return 0;
    }

    cout << "YES" << endl;
    auto ans = solve(A, B, N);
    for (auto& a : ans) {
        cout << a << " ";
    }
    cout << endl;
    set<int> s(ans.begin(), ans.end());
    if (s.size() != (1 << N)) terminate();
    return 0;
}

