const int N=(1<<17)+5;

int n,A,B,p[N],cnt[N];

void solve(int w,int l,int r,int A,int B) {
	if (l+1==r) {
		p[l]=A;p[r]=B;
		return;
	}
	int mid=l+r>>1,id=0;
	fo(i,0,w) if ((A^B)&(1<<i)) {id=i;break;}
	int t=(A&(1<<id))>0;
	int aa=A^(A&(1<<w))^(A&(1<<id));
	aa=aa^(((A&(1<<w))>0)*(1<<id));
	int bb=B^(B&(1<<w))^(B&(1<<id));
	bb=bb^(((B&(1<<w))>0)*(1<<id));
	if (cnt[aa]&1) {
		solve(w-1,l,mid,aa,0);
		solve(w-1,mid+1,r,0,bb);
	} else {
		solve(w-1,l,mid,aa,1);
		solve(w-1,mid+1,r,1,bb);
	}
