using namespace std;
int Diff_bit(int a, int b, int digit)
{
	if (!((a >> digit) % 2) && (b >> digit) % 2)
		return 1;
	else if ((a >> digit) % 2 && !((b >> digit) % 2))
		return -1;
	else return 0;
}

int Pm_bit(int num, int digit)
{
	if ((num >> digit) % 2)
		return 1;
	else return -1;
}

void num_write(num_bit num)
{
	if (num.digit_val == 1)
	{
		cout << num.a << " " << num.b << " ";
	}
	else
	{
		int i = 0, j = 0;
		while (1)
		{
			if (Diff_bit(num.a, num.b, i) != 0 && !(num.fix[i]))
				break;
			i++;
		}
		num.fix[i] = true;
		while (1)
		{
			if (!(num.fix[j]))
				break;
			j++;
		}

		num_bit a, b;
		a.a = num.a;
		a.b = num.a - pow(2, j) * Pm_bit(num.a, j);
		b.a = a.b + pow(2, i) * Diff_bit(num.a, num.b, i);
		b.b = num.b;
		a.digit_val = num.digit_val - 1;
		b.digit_val = num.digit_val - 1;
		for (i = 0; i < Nmax; i++)
		{
			a.fix[i] = num.fix[i];
			b.fix[i] = num.fix[i];
		}
		num_write(a);
		num_write(b);
	}
}
