void dfs(int A, int B, int mask)
{
  if (cnt(mask) == N - 1)
  {
    ans.push_back(A);
    ans.push_back(B);
    return;
  }
  int ind;
  for (ind = 0; ind < N; ind++)
  {
    if (mask >> ind & 1)
    {
      continue;
    }
    if ((A >> ind & 1) != (B >> ind & 1))
    {
      break;
    }
  }
  int new_mask = mask | 1 << ind;
  int next;
  for (next = 0; next < N; next++)
  {
    if (mask >> next & 1)
    {
      continue;
    }
    break;
  }
  int C = A ^ 1 << next;
  int D = C ^ 1 << ind;
  dfs(A, C, new_mask);
  dfs(D, B, new_mask);
}

