	{
		cout << b << endl;
		return ;
	}
	flag[a] = 1;
	for(int i = 0; i < n; i ++)
		if(!flag[a ^ (1 << i)] && i != y)
		{
			work(a ^ (1 << i), t + 1);
			return ;
		}
	work(a ^ (1 << y), t + 1);
}
