vector <int> get(int l, int r, int mask, int num) {
	vector <int> res;
	if (num == 1) {
		res.push_back(l);
		res.push_back(r);
		return res;
	}

	int id = __builtin_ctz(l ^ r);
	int id2 = 0;
	for (int i = 0; i < n; i++)
		if ((((mask >> i) & 1) == 0) && i != id) {
