void rec(int *seq, int len, int cnt){
    if(cnt == 0) return;
    for(int i = 0; i < len; i++)
        seq[2 * len - 1 - i] = seq[i] * 2 + 1;
    rec(seq, len * 2, cnt - 1);
}

