const int Nmax = (1<<17);

int N, A, B, ans[Nmax];

void solve(int N, int A, int B, int mask, int pos = 0)
{
    if(N == 2)
    {
        ans[pos] = A & mask;
        ans[pos+1] = B & mask;
        return;
    }

    int bit = ((A ^ B) & mask);
    bit &= (-bit);
    mask ^= bit;

    int bt;
    for(bt=1; !(mask & bt); bt <<= 1);

    solve(N>>1, A, A ^ bt, mask, pos);
    solve(N>>1, A ^ bt, B, mask, pos + (N>>1));

    int i;
    if(B & bit)
        for(i = pos + (N>>1); i < pos + N; ++i) ans[i] ^= bit;
    else for(i = pos; i < pos + (N>>1); ++i) ans[i] ^= bit;
}

