#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const string YES = "YES";
const string NO = "NO";


struct Bits {
    int length;
    vector<int> bs;

    Bits expand() {
        Bits nb;
        for (int i = 0; i < bs.size(); i++) {
            nb.bs.push_back(bs[i]);
        }
        for (int i = bs.size() - 1; i >= 0; i--) {
            nb.bs.push_back(bs[i] | (1 << length));
        }
        nb.length = length + 1;
        return nb;
    }

    static Bits identity() {
        return {1, {0, 1}};
    }

};


int shift(int x, int n, int a) {
    int sub = x & ((1 << a) - 1);
    return (x >> a) + (sub << (n - a));
}


Bits compute(int n, int c, int shift_v) {
    Bits s;
    if (c == 1) {
        s = Bits::identity();
        for (int i = 0; i < n - 1; i++) {
            s = s.expand();
        }
    } else {
        s = compute(n, c - 2, 0);
        s.bs.resize(s.bs.size() / 2);
        auto sol = compute(n - 1, c - 2, 1);
        for (int b : sol.bs) {
            s.bs.push_back((1 << (n - 1)) ^ (1 << (n - 2)) ^ b);
        }
    }

    for (int &b : s.bs) {
        b = shift(b, n, shift_v);
    }
    return s;
}


void solve(long long N, long long A, long long B) {

    long long goal = A ^B;
    int c = __builtin_popcount(goal);
    if (c % 2 == 0) {
        cout << NO << endl;
        return;
    }
    auto ans = compute(N, __builtin_popcount(A ^ B), 0);

    vector<int> org[2] = {};
    vector<int> nxt[2] = {};
    int k = 0;
    for (int i = 0; i < 17; i++) {
        org[goal >> i & 1].push_back(i);
        nxt[ans.bs.back() >> i & 1].push_back(i);
    }
    int conv[17];

    for (int p = 0; p < 2; p++) {
        for (int i = 0; i < org[p].size(); i++) {
            conv[nxt[p][i]] = org[p][i];
        }
    }
    cout << YES << endl;
    bool fst = true;
    for (auto &b : ans.bs) {
        int res = 0;
        for (int i = 0; i < N; i++) {
            res |= (b >> i & 1) << conv[i];
        }
        if(!fst){
            cout << " ";
        }
        fst = false;
        b = res ^ A;
        cout << b;
    }
    cout << endl;


}

