#include<bits/stdc++.h>
using namespace std;
#define bp __builtin_popcount
int del(int n, int x, int p) {
    int ans = 0;
    int f = 1;
    for (int i = 0; i < n; ++i) {
        if (i == p) continue;
        ans += f * ((x >> i) & 1);
        f <<= 1;
    }   
    return ans;
}   
int ins(int n, int x, int p, bool t) {
    int ans = 0;
    ans += x & ((1 << p) - 1);
    ans += (1 << p) * t;
    ans += (x >> p) << (p + 1);
    return ans;
}   
vector <int> solve(int n, int a, int b) {
    if (n == 1) {
        return {a, b};
    }   

    int p = -1;
    for (int i = 0; i < n; ++i) {
        if (((a >> i) & 1) != ((b >> i) & 1)) {
            p = i;
        }   
    }   

    int x, y;

    if (p) {
        x = a ^ (1 << (p - 1));
    }
    else {  
        x = a ^ (1 << (p + 1));
    }   

    y = x ^ (1 << p);

    vector <int> l = solve(n - 1, del(n, a, p), del(n, x, p)), r = solve(n - 1, del(n, y, p), del(n, b, p));
    vector <int> ans;
    for (int e : l) {
        ans.push_back(ins(n, e, p, (a >> p) & 1));
    }   
    for (int e : r) {
        ans.push_back(ins(n, e, p, (b >> p) & 1));
    }   
    return ans;
}   
