vector<LL> gen_gray(LL n){
    vector<LL> ans;
    LL cur = 0;
    for(LL i = 0; i < (1<<n); ++i){
        ans.push_back(cur ^ (cur>>1));
        cur += 1;
    }
    return ans;
}

vector<LL> reassign(LL n, vector<LL>& diff_idx){
    vector<LL> assign(n);
    for(LL i = 0; i < n; ++i){
        assign[i] = i;
    }
    for(LL i = 0; i < diff_idx.size(); ++i){
        swap(assign[diff_idx[i]], assign[i]);
    }
    return assign;
}

LL apply_assign(LL v, vector<LL>& assign){
    LL ans = 0;
    for(LL i = 0; i < assign.size(); ++i){
        ans += ((v>>assign[i])&1) << i;
    }
    return ans;
}

LL invert_assign(LL v, vector<LL>& assign){
    LL ans = 0;
    for(LL i = 0; i < assign.size(); ++i){
        ans += ((v>>i)&1) << assign[i];
    }
    return ans;
}

vector<LL> solve(LL n, LL a, LL b){
    vector<LL> diff_idx;
    for(LL i = 0; i < n; ++i){
        LL ab = (a>>i) & 1;
        LL bb = (b>>i) & 1;
        if(ab != bb){
            diff_idx.push_back(i);
        }
    }
    LL cnt = diff_idx.size();
    if(cnt != 1 && cnt != 3){
        return vector<LL>();
    }
    vector<LL> ans;
    vector<LL> assign = reassign(n, diff_idx);
    cerr << "reassign: " << assign << endl;
    if(cnt %2 == 1){
        vector<LL> gray = gen_gray(n-cnt);
        //cerr << "gray:" << gray << endl;
        LL a2 = apply_assign(a, assign);
        LL mask = 0;
        vector<LL> gray2 = gen_gray(cnt);
        gray2.push_back(0);
        for(LL i = 0; i < (1<<cnt); ++i){
            for(LL g: gray){
                ans.push_back(invert_assign(a2 ^ (g<<cnt) ^ mask, assign));
            }
            reverse(gray.begin(), gray.end());
            mask = mask ^ gray2[i+1] ^ gray2[i];
        }
        return ans;
    }
    return vector<LL>();
}

int main(){
    LL n, a, b;
    cin >> n >> a >> b;
    vector<LL> ans = solve(n, a, b);
    if(ans.empty()){
        cout << "NO" << endl;
    }else{
        cout << "YES" << endl;
        for(LL i = 0; i < ans.size(); ++i){
            cout << ans[i];
            if(i+1 == ans.size()){
                cout << endl;
            }else{
                cout << " ";
            }
        }
    }
    return 0;
}

