int main() {

    scanner >> M >> A >> B;
    N = 1 << M;

    if (BitAlgo::popcount32(A ^ B) != 1) {
        bye("NO");
    }

    repeat(i, N) {
        code[i] = i ^ (i >> 1);
    }

    int cA = BitAlgo::popcount32(A);
    int cB = BitAlgo::popcount32(B);

    int cX, cY;
    int ptr = -1;
    repeat(i, N - 1) {
        cX = BitAlgo::popcount32(code[i]);
        cY = BitAlgo::popcount32(code[i + 1]);
        if (cA == cX && cB == cY) { // 個数変化が同じ場所を探す．このグレイコードの値をX,Yとする．
            ptr = i;
            break;
        }
    }
    int X = code[ptr];
    int Y = code[ptr+1];

    // あり得ないが念の為
    if (ptr == -1) bye("NO");

    // 並び替え
    // 出力する際にperm[i]桁を見に行く
    int perm[20];
    iota(perm, perm + 20, 0);

    // AB のビットが違う位置
    int iAB = BitAlgo::ffs32(A ^ B) - 1;

    // XY のビットが違う位置
    int iXY = BitAlgo::ffs32(X ^ Y) - 1;

    // が言えるはず
    perm[iAB] = iXY;

    // 他の位置については？0のいち，1の位置を記憶
    queue<int> vX0, vX1;
    {
        int x = X;
        repeat(i, 20) {
            if (iXY != i) {
                if (x & 1)
                    vX1.push(i);
                else
                    vX0.push(i);
            }
            x >>= 1;
        }
    }
    // debug(ptr);
    // debug(X);
    // debug(A);
    // debug(iXY);
    // debug(iAB);
    {
        int a = A;
        repeat(i, 20) {
            if (iAB != i) {
                if (a & 1)
                    perm[i] = vX1.front(), vX1.pop();
                else
                    perm[i] = vX0.front(), vX0.pop();
            }
            a >>= 1;
        }
    }

    // RUN
    // debuga(perm, N);

    printer << "YES\n";
    repeat(_i, N) {
        int i = (ptr - _i + N) % N;
        int v = 0;
        repeat(k, 20) {
            v |= !!(code[i] & (1 << perm[k])) << k;
        }
        printer << v << ' ';
    }
    printer << '\n';


    return 0;
}

