using namespace std;
const int N=2e5+10;
int n,vis[N],d[N],p[N];
int tot=0,he[N],t[N*10],ne[N*10],py=0,pyy;
void link(int x,int y)
{
	tot++;
	ne[tot]=he[x];
	he[x]=tot;
	t[tot]=y;
	tot++;
	ne[tot]=he[y];
	he[y]=tot;
	t[tot]=x;
}
void dfs(int y)
{
	if (py) return;
	if (y==(1<<n)) 
	{
		py=1;
		return;
	}
	int fl=0;
	if (pyy) 
	{
		if (d[y-1]+4<(1<<n))
		{
			d[y]=d[y-1]+4;
			vis[d[y-1]+4]=1;
			pyy=0;
			dfs(y+1);
		}else
		{
			d[y]=d[y-1]-4;
			vis[d[y-1]-4]=1;
			pyy=0;
			dfs(y+1);
		}
	}
	for (int i=he[d[y-1]];i;i=ne[i]) 
	{
		if (!vis[t[i]]) 
		{
			vis[t[i]]=1;
			d[y]=t[i];
			fl=1;
			dfs(y+1);
			if (py) return;
		}
	}
	if (!fl) 
	{
		d[y]=d[y-1]+4;
		vis[d[y-1]+4]=1;
		dfs(y+1);
		if (py) return;
	}
}
int main()
{
	int a,b;
	scanf("%d%d%d",&n,&a,&b);
	if (n==1) 
	{
		puts("YES");
		printf("%d %d\n",a,b);
		return 0;
	}
	for (int i=1;i<=(1<<n-2);i++)
	{
		//if (i&1) p[(i-1)*4+1]=p[(i-1)*4+2]=1;else p[(i-1)*4]=p[(i-1)*4+3]=1;
		link((i-1)*4+1,(i-1)*4);
		link((i-1)*4+1,(i-1)*4+3);
		link((i-1)*4+2,(i-1)*4+3);
		link((i-1)*4+2,(i-1)*4);
		link((i-1)*4+1,(i-1)*4);
		link((i-1)*4+1,(i-1)*4+3);
		link((i-1)*4+2,(i-1)*4+3);
		link((i-1)*4+2,(i-1)*4);
	}
	p[1]=p[2]=1;
	for (int i=2;i<=(1<<n-2);i++) 
	{
		if (i>>1&1) p[(i-1)*4]=p[(i-1)*4+3]=1;else p[(i-1)*4+1]=p[(i-1)*4+2]=1;
	}
	if (p[a]==p[b]) 
	{
		puts("NO");
		return 0;
	}
	if (a/4==b/4&&n>2) pyy=1;
	vis[a]=1;
	vis[b]=1;
	d[1]=a;
	d[1<<n]=b;
	dfs(2);
	puts("YES");
	for (int i=1;i<=(1<<n);i++) printf("%d ",d[i]);
}

