using namespace std;

bool vis[140005];
int N,A,B;
vector<int> ans;
int cnt;

bool solve(int cur) {
    vis[cur] = true;
    ans.push_back(cur);

    if (cur == B) {
        if (ans.size() == (1 << N))
            return true;
        else {
            cnt++;
            return false;
        }
    }

    int i;

    for (i = 0;i < N;i++) {
        if (!vis[cur ^ (1 << i)]) {
            if (solve(cur ^ (1 << i)))
                return true;
        }
    }

    ans.pop_back();
    vis[cur] = false;

    return false;
}

int main() {
    scanf("%d%d%d",&N,&A,&B);

    if (abs(A - B) == (1 << (N - 1))) {
        printf("YES\n");
        if (!solve(A))
          abort();
        for (int a : ans)
            printf("%d ",a);
        printf("\n");
    }
    else
        printf("NO\n");

    return 0;
}

