using namespace std;

int n, a, b;

int ans[1 << 17];

inline void Solve (int n, int a, int b, int l, int r) {
	if (n == 1) { ans[l] = a, ans[r] = b; return; }
	int mid = (l + r) >> 1, x;
	for (x = 0; x < n; ++x) if (((a >> x) & 1) != ((b >> x) & 1)) break;
	int xa = (a >> (x + 1) << x) | (a & ((1 << x) - 1));
	int xb = (b >> (x + 1) << x) | (a & ((1 << x) - 1));
	Solve (n - 1, xa, xa ^ 1, l, mid);
	Solve (n - 1, xa ^ 1, xb, mid + 1, r);
	for (int i = l; i <= mid; ++i) ans[i] = (ans[i] >> x << (x + 1)) | (ans[i] & ((1 << x) - 1)) | (a & (1 << x));
	for (int i = mid + 1; i <= r; ++i) ans[i] = (ans[i] >> x << (x + 1)) | (ans[i] & ((1 << x) - 1)) | (b & (1 << x));
}

int main () {
	scanf ("%d%d%d", &n, &a, &b);

	int numa = 0, numb = 0;
	for (int i = 0; i < n; ++i) {
		if ((a >> i) & 1) ++numa;
		if ((b >> i) & 1) ++numb;
	}
	if ((numa & 1) == (numb & 1)) { printf ("NO\n"); return 0; }

	Solve (n, a, b, 0, (1 << n) - 1);

	printf ("YES\n");
	for (int i = 0; i < (1 << n); ++i) printf ("%d%c", ans[i], " \n"[i == (1 << n) - 1]);

	return 0;
}

