int rem(int A, int bit) {
	int fi = A & ((1 << bit) - 1);
	int se = (A >> (bit + 1)) << bit;
	return fi | se;
}

int add(int A, int bit, int x) {
	int fi = A & ((1 << bit) - 1);
	int se = (A >> bit) << (bit + 1);
	if (x) se |= (1 << bit);
	return fi | se;
}

vector<int> solve(int A, int B, int n) {
	if (n == 1) {
		return {A, B};
	}
	vector<int> ret;
	int x = -1;
	for (int bit = 0; bit < n; bit++) {
		if (Bit(A, bit) != Bit(B, bit)) {
			x = bit;
			break;
		}
	}	
	assert(x != -1);
	int nA = rem(A, x), nB = rem(B, x);
	int C = nA;
	C ^= 1;
	vector<int> first = solve(nA, C, n - 1), second = solve(C, nB, n - 1);
	for (auto i : first) ret.pb(add(i, x, Bit(A, x)));
	for (auto i : second) ret.pb(add(i, x, Bit(B, x)));
	return ret;
}

