const int N = 2e5 + 5;

bool vis[N];
int n, ans[N];

int cont(int a) {
    int cnt = 0;
    while (a) {
        cnt += a & 1;
        a >>= 1;
    }
    return cnt;
}

bool dfs(int a, int gol, int cnt) {
    if (a == gol) {
        if (cnt == (1 << n)) {
            ans[cnt] = gol;
            return 1;
        }
        return 0;
    }
    vis[a] = 1;
    for (int i = 0; i < n; ++i) {
        int I = 1 << i;
        if (!vis[a ^ I]) {
            if (dfs(a ^ I, gol, cnt + 1)) {
                ans[cnt] = a;
                vis[a] = 0;
                return 1;
            }
        }
    }
    vis[a] = 0;
    return 0;
}

int main() {
    int a, b;
    read(n), read(a), read(b);
    if (dfs(a, b, 1)) {
        puts("YES");
        for (int i = 1; i <= (1 << n); ++i) {
            printf("%d ", ans[i]);
        }
    } else puts("NO");
    return 0;
}

