const int N = 2e5 + 10;
const int MOD = 1e9 + 7;

int popcnt(int x) {
	if (x == 0) return 0;
	return 1 + popcnt(x & (x - 1));
}

vector <int> build_gray(int n) {
	if (n == 0) {
		return { 0 };
	}
	if (n == 1) {
		return { 0, 1 };
	}
	auto v = build_gray(n - 1);
	vector <int> res = v;
	reverse(v.begin(), v.end());
	for (auto& x : v) {
		x ^= (1 << (n - 1));
		res.push_back(x);
	}
	return res;
}

vector <int> solve(int n, int a, int b) {
	if (popcnt(a ^ b) % 2 == 0) {
		return {};
	}
	vector <int> eqbit;
	vector <int> neqbit;
	int start = 0;
	for (int i = 0; i < n; ++i) {
		if ((a & (1 << i)) == (b & (1 << i))) {
			eqbit.push_back(i);
			start ^= (a & (1 << i));
		} else {
			neqbit.push_back(i);
		}
	}
	vector <int> vv = build_gray(eqbit.size());
	for (auto& x : vv) {
		int l = 0;
		for (int i = 0; i < eqbit.size(); ++i) {
			if (x & (1 << i)) {
				l ^= (1 << eqbit[i]);
			}
		}
		x = l;
	}
	vector <int> res;
	for (int id = 0; id < vv.size(); ++id) {
		if (vv[id] == start) {
			for (int x = id; x < vv.size(); ++x) {
				res.push_back(vv[x]);
			}
			for (int x = 0; x < id; ++x) {
				res.push_back(vv[x]);
			}
		}
	}
	for (int i = 0; i < neqbit.size(); ++i) {
		vector <int> newres;
		if (b & (1 << neqbit[i])) {
			for (auto x : res) {
				newres.push_back(x);
			}
			reverse(res.begin(), res.end());
			for (auto& x : res) {
				x ^= (1 << neqbit[i]);
				newres.push_back(x);
			}
		} else {
			for (auto& x : res) {
				x ^= (1 << neqbit[i]);
				newres.push_back(x);
			}
			reverse(res.begin(), res.end());
			for (auto& x : res) {
				x ^= (1 << neqbit[i]);
				newres.push_back(x);
			}

		}
		res.swap(newres);
	}
	return res;
}

int main() {
	int n, a, b;
	cin >> n >> a >> b;
	auto res = solve(n, a, b);
	if (res.size() != 0) {
		cout << "YES\n";
		assert(res[0] == a && res.back() == b);
		for (auto x : res) {
			cout << x << " ";
		}
		cout << endl;
	}
	return 0;
}

