typedef vector<int> vi;
const vi c[3]={{3,1,0,2},{2,0,1,3},{0,1,3,2}};
vi ngray(int n){
	vi s(1<<n);
	int i,j,k,x;
	s[1]=1;
	for(j=1;j<n;j+=2){
		for(i=(1<<j)-1;i>=0;i--){
			x=s[i];
			const vi&c=::c[i?i&1:2];
			for(k=0;k<4;k++)s[i<<2|k]=x<<2|c[k];
		}
	}
	return s;
}
vi cgray(int n){
	if(!n)return{0};
	vi s(1<<n);
	int i,j;
	s[1]=1;
	for(j=1;j<n;j++){
		for(i=0;i<1<<j;i++)s[(1<<(j+1))-1-i]=(1<<j)|s[i];
	}
	return s;
}
int main(){
	int n,i,j,k,a,b;
	vi p1,p0,pn,pc;
	int n1,n0,nn,nc;
	scanf("%d%d%d",&n,&a,&b);
	b^=a;
	for(i=0;i<n;i++)(b>>i&1?p1:p0).push_back(i);
	n1=p1.size();
	n0=p0.size();
	if(~n1&1){
		printf("NO");
		return 0;
	}
	pn=ngray(n1);
	pc=cgray(n0);
	nn=pn.size();
	nc=pc.size();
