	for(i=0;i<nn;i++){
		for(j=0;j<nc;j++){
			b=0;
			for(k=0;k<n0;k++)b|=(pc[i&1?nc-1-j:j]>>k&1)<<p0[k];
			for(k=0;k<n1;k++)b|=(pn[i]>>k&1)<<p1[k];
			printf("%d ",b^a);
		}
	}
}

