const int MAXN = 1000010;
const int MOD = 1000000007;
const f80 MI = f80(1)/MOD;
const int INV2 = (MOD+1)/2;

bitset<32> g[MAXN];

void solve(int n)
{
	if (n == 0) return;
	if (n == 1)
	{
		g[0][0] = 0;
		g[1][0] = 1;
		return;
	}
	solve(n-1);
	for (int i = 0; i < 1<<(n-1); ++ i)
	{
		g[(1<<n)-i-1] = g[i];
		g[(1<<n)-i-1][n-1] = 1;
	}
}

int main()
{

	int n, a, b;
	cin >> n >> a >> b;
	int c = a^b;
	if (__builtin_popcount(c) == 1)
	{
		solve(n);
		int k = __builtin_ctz(c);
		bitset<32> mask = a&b;
		for (int i = 0; i < 1<<n; ++ i)
		{
			//printf("1:%d ", g[i].to_ulong());
			int x = g[i][n-1];
			int y = g[i][k];
			swap(x, y);
			g[i][n-1] = x;
			g[i][k] = y;
			//printf("2:%d ", g[i].to_ulong());
			g[i] ^= mask;
			//printf("3:%d\n", g[i].to_ulong());
		}
		puts("YES");
		for (int i = 0; i < 1<<n; ++ i)
		{
			//printf("%d ", g[i].to_ulong());
			cout << g[i].to_ulong() << " ";
		}
	}
	else if (__builtin_popcount(c) == 3)
	{
		solve(n-3);
		int x[] = {0, 1, 3, 2, 6, 4, 5, 7};
		bitset<32> mask = a&b;
		for (int j = 0; j < 8; ++ j)
		{
			for (int i = 0; i < 1<<(n-3); ++ i)
			{
				if (j&1)
				{
					g[i+(j<<(n-3))] = g[(1<<(n-3))-i-1];
				}
				else
				{
					g[i+(j<<(n-3))] = g[i];
				}
				for (int k = 0; k < 3; ++ k)
					g[i+(j<<(n-3))][n-3+k] = x[j]>>k&1;
			}
		}
		vector<int> v;
		for (int k = 0; k < n; ++ k)
			if (c>>k&1) v.push_back(k);
		puts("YES");
		for (int i = 0; i < 1<<n; ++ i)
		{
			for (int k = 0; k < 3; ++ k)
			{
				int x = g[i][n-3+k];
				int y = g[i][v[k]];
				swap(x, y);
				g[i][n-3+k] = x;
				g[i][v[k]] = y;
			}
			g[i] ^= mask;
			cout << g[i].to_ulong() << " ";
		}
	}
	else
	{
		puts("NO");
	}

    return 0;
}

