int has1bit(int number){
  if(0 < (number & (number - 1)))
    return -1;
  else {
    for(int h = 0; h < 20; h++)
      if(0 < ((1 << h) & number))
        return h;
  }
}
int const nmax = 17;
int coef[1 + nmax];

vector<int> gen(int number, int k, int n){
  if(k == n) {
    vector<int> sol;
    sol.push_back(number);
    return sol;
  } else{
    vector<int> sol = gen(number, k + 1, n);
    vector<int> sol2 = sol;
    reverse(sol2.begin(), sol2.end());
    for(int i = 0; i < sol2.size(); i++)
      sol2[i] ^= (1 << coef[k]);
    sol.insert(sol.end(), sol2.begin(), sol2.end());
    return sol;
  }
}

int main()
{
  int n, a, b;
  cin >> n >> a >> b;
  for(int i = 0; i < n; i++)
    coef[i] = i;
  if(has1bit(a ^ b) == -1)
    cout << "NO\n";
  else {
    cout << "YES\n";
    swap(coef[0], coef[has1bit(a ^ b)]);
    vector<int> sol = gen(a, 0, n);
    for(int i = 0; i < sol.size(); i++)
      cout << sol[i] << " ";
    cout << '\n';
  }
  return 0;
}

