		if((a&(1<<i)) != (b&(1<<i))){
			vector<ll> g=v;
			if(a&(1<<i)) for(auto&j:v)j|=1<<i;
			else for(auto&j:g)j|=1<<i;
			// for(auto j:g) cerr<<j<<' '; cerr<<'\n';
			// for(auto j:v) cerr<<j<<' '; cerr<<'\n';
			while(g.size())v.eb(g.back()),g.pop_back();
		}else{
			vector<ll>g;
			for(ll j=0;j<v.size();j+=2){
				bool have=a&(1<<i);
				g.eb(v[j] + (1<<i) * have);
				g.eb(v[j] + (1<<i) * (!have));
				g.eb(v[j+1] + (1<<i) * have);
				g.eb(v[j+1] + (1<<i) * (!have));
			}
			v=g;
		}
		assert(siz(v)==(1<<(i+1)));
	}
	cout<<"YES\n";
	for(auto i:v) cout<<i<<' ';cout<<'\n';
}

