int n, s, t, cnt, a[MAXN], ans[MAXN], lft[18], bit[18];
void work(int depth, int pos) {
	if (lft[depth]) {
		lft[depth]--;
		if (depth % 2) a[pos] = depth + 1;
		else a[pos] = depth - 1;
	} else a[pos] = depth;
	if (depth == 1) return;
	work(depth - 1, pos - (1 << (depth - 2)));
	work(depth - 1, pos + (1 << (depth - 2)));
}
int main() {
	read(n), read(s), read(t);
	for (int val = s ^ t; val; cnt++)
		val ^= val & -val;
	if (cnt % 2 == 0) {
		puts("NO");
		return 0;
	}
	puts("YES");
	for (int i = 2; i <= cnt; i += 2) {
		lft[n - i + 1] = 1;
		lft[n - i] = 2;
	}
	work(n, 1 << (n - 1));
	int l = 1, r = n;
	for (int i = 0; i < n; i++) {
		int tmp = 1 << i;
		if ((s ^ t) & tmp) bit[r--] = tmp;
		else bit[l++] = tmp;
	}
	ans[0] = s;
	for (int i = 1; i < (1 << n); i++)
		ans[i] = ans[i - 1] ^ bit[a[i]];
