vector<LL> gen_gray(LL n){
    vector<LL> ans;
    LL cur = 0;
    for(LL i = 0; i < (1<<n); ++i){
        ans.push_back(cur ^ (cur>>1));
        cur += 1;
    }
    return ans;
}

vector<LL> reassign(LL n, vector<LL>& diff_idx){
    vector<LL> assign(n);
    for(LL i = 0; i < n; ++i){
        assign[i] = i;
    }
    for(LL i = 0; i < diff_idx.size(); ++i){
        swap(assign[diff_idx[i]], assign[i]);
    }
    return assign;
}

LL apply_assign(LL v, vector<LL>& assign){
    LL ans = 0;
    for(LL i = 0; i < assign.size(); ++i){
        ans += ((v>>assign[i])&1) << i;
    }
    return ans;
}

LL invert_assign(LL v, vector<LL>& assign){
    LL ans = 0;
    for(LL i = 0; i < assign.size(); ++i){
        ans += ((v>>i)&1) << assign[i];
    }
    return ans;
}

vector<LL> solve(LL n, LL a, LL b){
    vector<LL> diff_idx;
    for(LL i = 0; i < n; ++i){
        LL ab = (a>>i) & 1;
        LL bb = (b>>i) & 1;
        if(ab != bb){
            diff_idx.push_back(i);
        }
    }
    LL cnt = diff_idx.size();
    if(cnt != 1 && cnt != 3){
        return vector<LL>();
    }
    vector<LL> ans;
    vector<LL> assign = reassign(n, diff_idx);
    //cerr << "reassign: " << assign << endl;
    if(cnt == 1){
        vector<LL> gray = gen_gray(n-1);
        //cerr << "gray:" << gray << endl;
        LL a2 = apply_assign(a, assign);
        for(LL g: gray){
            ans.push_back(invert_assign(a2 ^ (g<<1), assign));
        }
        reverse(gray.begin(), gray.end());
        for(LL g: gray){
            ans.push_back(invert_assign(a2 ^ (g<<1) ^ 1, assign));
        }
        return ans;
    }else{
        vector<LL> gray = gen_gray(n-3);
        //cerr << "gray:" << gray << endl;
        LL a2 = apply_assign(a, assign);
        for(LL g: gray){ ans.push_back(invert_assign(a2 ^ (g<<3), assign)); }
        reverse(gray.begin(), gray.end());
        for(LL g: gray){ ans.push_back(invert_assign(a2 ^ (g<<3) ^ 1, assign)); }
        reverse(gray.begin(), gray.end());
        for(LL g: gray){ ans.push_back(invert_assign(a2 ^ (g<<3) ^ 3, assign)); }
        reverse(gray.begin(), gray.end());
        for(LL g: gray){ ans.push_back(invert_assign(a2 ^ (g<<3) ^ 2, assign)); }
        reverse(gray.begin(), gray.end());
        for(LL g: gray){ ans.push_back(invert_assign(a2 ^ (g<<3) ^ 6, assign)); }
        reverse(gray.begin(), gray.end());
        for(LL g: gray){ ans.push_back(invert_assign(a2 ^ (g<<3) ^ 4, assign)); }
        reverse(gray.begin(), gray.end());
        for(LL g: gray){ ans.push_back(invert_assign(a2 ^ (g<<3) ^ 5, assign)); }
        reverse(gray.begin(), gray.end());
        for(LL g: gray){ ans.push_back(invert_assign(a2 ^ (g<<3) ^ 7, assign)); }
        return ans;
    }
}

int main(){
    LL n, a, b;
    cin >> n >> a >> b;
