int search(int n,int A,int B){
	int nn=n;
	int a=0;
	REP(i,N){
		if(((n>>i)&1)==0){
			int C=(A|n)^(1<<a);
			int D=(B|n);
			if(C!=D)return A^(1<<a);
		}
		nn%=2;
	}
	return -1;
}

void dfs(int A,int B,int n){
	//cout<<A<<" "<<B<<" "<<n<<endl;
	int c=0;
	int nn=n;
	while(nn!=0){
		c+=(nn%2);
		nn/=2;
	}
	if(c==N-1){
		ans.push_back(P(A,B));
		return;
	}
	int a=-1;
	int C=A;
	int D=B;
	REP(i,N){
		if((C%2!=D%2)&&(((n>>i)&1))==0){
			int X;
			int Y;
			if(C%2==0){
				X=search(n,A,B);
				Y=X|(1<<i);
				dfs(A,X,n|(1<<i));
				ans.push_back(P(X,Y));
				dfs(Y,B,n|(1<<i));
			}else{
				X=search(n|(1<<i),A,B);
				Y=X^(1<<i);
				dfs(A,X,n|(1<<i));
				ans.push_back(P(X,Y));
				dfs(Y,B,n|(1<<i));
			}
			break;
		}
		C/=2;
		D/=2;
	}
}

