vector<int> solve(int a, int b, int T){
    if (T==1) return {0};
    int common = -1;
    for (int i=0; i < T; i++){
        int ba = a & (1<<i);
        int bb = b & (1<<i);
        if (ba != 0) ba=1;
        if (bb != 0) bb=1;
        if (ba != bb) continue;
        common = i;
    }
    if (common != -1){
        int na = 0, nb = 0;
        int cur=0;
        for (int i=0; i < T; i++){
            if (i==common) continue;
            int ba = a & (1<<i);
            int bb = b & (1<<i);
            if (ba != 0) ba=1;
            if (bb != 0) bb=1;
            na += (1<<cur)*ba, nb += (1<<cur)*bb;
            cur++;
        }
        vector<int> res = solve(na, nb, T-1);
        vector<int> nres = {common};
        for (int i=0; i < res.size(); i++){
            if (res[i]>=common) nres.push_back(res[i]+1);
            else nres.push_back(res[i]);
            nres.push_back(common);
        }
        return nres;
    }
    int na = a & ((1<<(T-1)) - 1), nb = b & ((1<<(T-1)) - 1);
    int nc = na ^ 1;
    vector<int> A = solve(a, nc, T-1), B = solve(nc, b, T-1);
    //cout << a << " " << nc << " " << T-1 << endl;
    vector<int> res;
    for (int i=0;i<A.size();i++) res.push_back(A[i]);
    res.push_back(T-1);
    for (int i=0;i<B.size();i++) res.push_back(B[i]);
    return res;
}
