V<string> solve(string a, string b, int k) {
   if (k == 1) {
      return V<string>({a, b});
   }

   int x = -1;
   for (int i = 0; i < k; i++) {
      if (a[i] != b[i]) {
         x = i; break;
      }
   }
   if (x == -1) {
      return V<string>();
   }

   string a_ = remove(a, x);
   string b_ = remove(b, x);
   string c_ = remove(a_, k-2) + (a_[k-2] == '0' ? "1" : "0");
   V<string> Q = solve(a_, c_, k-1);
   V<string> R = solve(c_, b_, k-1);
   if (Q.size() == 0 || R.size() == 0) {
      return V<string>();
   }

   V<string> P(1<<k);
   for (int i = 0; i < 1<<k-1; i++) {
      P[i] = insert(Q[i], x, a[x]);
      P[i + (1<<k-1)] = insert(R[i], x, b[x]);
   }
   return P;
}

