	int p=0;
	for(;p<n;p++){
		if(!put[p]&&(a>>p&1)!=(b>>p&1))break;
	}
	int m=(l+r)/2;
	if(a>>p&1){
		for(int i=l;i<=m;i++)ans[i]+=(1<<p);
	}
	if(b>>p&1){
		for(int i=m+1;i<=r;i++)ans[i]+=(1<<p);
