void solve() {
  int N, A, B; cin >> N >> A >> B;
  if (abs(__builtin_popcount(A) - __builtin_popcount(B)) % 2 == 0) {
    cout << "NO" << '\n';
    return;
  }
  cout << "YES" << '\n';
  int V = bit(N);
  function<vector<int>(int, int, int)> build = [&](int a, int b, int mask) {
    a &= mask;
    b &= mask;
    int n = __builtin_popcount(mask);
    if (n == 1) {
      return vector<int>({ a, b });
    }
    int k;
    for (int i = 0; i < N; i++) {
      if ((mask & bit(i)) && (a & bit(i)) != (b & bit(i))) {
        k = i;
      }
    }
    mask &= ~bit(k);
    int c;
    for (int i = 0; i < N; i++) {
      if (mask & bit(i)) {
        c = a ^ bit(i);
      }
    }
    vector<int> ac = build(a, c, mask);
    vector<int> cb = build(c, b, mask);
    for (int i = 0; i < bit(n - 1); i++) {
      ac[i] |= bit(k) & a;
      cb[i] |= bit(k) & b;
    }
    vector<int> ret;
    for (int i = 0; i < bit(n - 1); i++) {
      ret.push_back(ac[i]);
    }
    for (int i = 0; i < bit(n - 1); i++) {
      ret.push_back(cb[i]);
    }
    return ret;
  };
  auto ans = build(A, B, bit(N) - 1);
  cout << ans << '\n';
}

