int main(int argc, char *argv[]) {
  // read inputs
  long N, A, B;
  scanf("%ld %ld %ld", &N, &A, &B);

  // check if it is possible
  long cnt_diff = 0, i_diff = -1;
  for (long i = 0; i < N; i++) {
    if ((A ^ B) & (1 << i)) {
      cnt_diff++;
      i_diff = i;
    }
  }
  if (cnt_diff != 1) {
    printf("NO\n");
    exit(0);
  }
  // printf("A = 0x%08lx, B = 0x%08lx, i_diff = %ld\n", A, B, i_diff);

  // create sequence
  long ps[1L << MAX_N] = {};
  ps[0] = 0;
  ps[1] = 1L << i_diff;
  for (long k = 2; k <= N; k++) {
    // mirror
    const long two_pow_k = 1L << k, two_pow_km1 = 1L << (k - 1);
    for (long i = 0; i < two_pow_km1; i++) {
      ps[two_pow_k - 1 - i] = ps[i];
    }
    // printf("after mirror\n");
    // for (long i = 0; i < two_pow_k; i++) {
    //   printf("%ld\n", ps[i]);
    // }
    // fill 1s
    const long i_fill = N + 1 - k <= i_diff ? N - k : N + 1 - k;
    // printf("k = %ld, i_fill = %ld\n", k, i_fill);
    for (long i = two_pow_km1; i < two_pow_k; i++) {
      ps[i] |= 1L << i_fill;
    }
    // check
    // printf("after fill\n");
    // for (long i = 0; i < two_pow_k; i++) {
    //   printf("%ld\n", ps[i]);
    // }
  }

  // find A
  long i0 = -1, b = -1;
  for (long i = 0, i_end = 1L << N; i < i_end; i++) {
    if (ps[i] == A) {
      i0 = i;
      if (ps[mod(i + 1, 1L << N)] == B) {
        b = 0;  // go to the negative side
      } else if (ps[mod(i - 1, 1L << N)] == B) {
        b = 1;  // go to the positive side
      } else {
        printf("something is wrong...\n");
        while (1) {
          ;
        }
      }
    }
  }
  // printf("i0 = %ld, b = %ld\n", i0, b);

  // print answer
  printf("YES\n");
  if (b) {
    printf("%ld", ps[i0]);
    for (long i = 1, i_end = 1L << N; i < i_end; i++) {
      printf(" %ld", ps[mod(i0 + i, 1L << N)]);
    }
    printf("\n");
  } else {
    printf("%ld", ps[i0]);
    for (long i = 1, i_end = 1L << N; i < i_end; i++) {
      printf(" %ld", ps[mod(i0 - i, 1L << N)]);
    }
    printf("\n");
  }

  return 0;
}

