using namespace std;
typedef long long li;

vector<int> solve(int freemask, int a, int b, int mask) {
    const int n = __builtin_popcount(freemask);
    a = a & freemask;
    b = b & freemask;
    const int weight_diff = __builtin_popcount(a ^ b);

    if (weight_diff % 2 == 0) {
        return vector<int>();
    }

    if (n == 1) {
        if (weight_diff != 1) {
            return vector<int>();
        }
        return {mask ^ a, mask ^ b};
    }

    const int msb = 1 << __builtin_ctz(a ^ b);
    const int second_msb = 1 << __builtin_ctz(freemask ^ msb);

    const int first_newmaskbit = msb & a;
    const int second_newmaskbit = msb & b;

    auto first = solve(freemask ^ msb, a, b ^ second_msb, mask ^ first_newmaskbit);
    auto second = solve(freemask ^ msb, b ^ second_msb, b , mask ^ second_newmaskbit);
    first.insert(first.end(), second.begin(), second.end());
    return first;
}

