#define in std::cin
#define out std::cout
#define rep(i,N) for(LL i=0;i<N;++i)
typedef long long int LL;

LL N;

LL erase_bit(LL n, LL m)
{
	LL upper = (n >> (m + 1)) << m, lower = n % (1LL << m);
	return upper + lower;
}

LL push_bit(LL n, LL m, LL k)
{
	LL upper = (n - n % (1LL << m)) << 1, lower = n % (1LL << m);
	return upper + k * (1LL << m) + lower;
}

std::vector<LL>f(LL a, LL b, LL c)
{
	if (c == 1) return std::vector<LL>{a, b};

	LL diff_bit;
	std::vector<LL>res;
	rep(i, N)
	{
		if (((a ^ b) >> i) & 1)
		{
			diff_bit = i;
			break;
		}
	}
	auto res1 = f(erase_bit(a, diff_bit), erase_bit(a, diff_bit) ^ 1, c - 1), res2 = f(erase_bit(a, diff_bit) ^ 1, erase_bit(b, diff_bit), c - 1);
	for (auto i : res1) res.push_back(push_bit(i, diff_bit, (a >> diff_bit) & 1));
	for (auto i : res2) res.push_back(push_bit(i, diff_bit, (b >> diff_bit) & 1));
	return res;
}

int main()
{
	LL A, B;
	in >> N >> A >> B;

	LL cnt1 = 0, cnt2 = 0;
	rep(i, N)
	{
		if ((A >> i) & 1) ++cnt1;
		if ((B >> i) & 1) ++cnt2;
	}
	if (cnt1 == cnt2)
	{
		out << "NO" << std::endl;
		return 0;
	}

	out << "YES" << std::endl;
	auto ans = f(A, B, N);
	rep(i, (1LL << N)) out << ans[i] << (i < (1LL << N) - 1 ? " " : "\n");
}

