using namespace std;

int n, a, b;

int GetBit(int a, int b)
{
    return a >> b & 1;
}

void Change(int &a, int b)
{
    a ^= (1 << b);
}

vector<int> vt[21];

vector<int> Prepare(int x)
{
    vector<int> ans = {};
    for(auto i: vt[x - 1])
    {
        ans.push_back(i + 1);
    }
    ans.push_back(0);
    for(auto i: vt[x - 1])
    {
        ans.push_back(i + 1);
    }
    return ans;
}

int32_t main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    if(fopen("test.inp", "r")) freopen("test.inp", "r", stdin), freopen("test.out", "w", stdout);
    cin >> n >> a >> b;
    vt[0] = {0};
    for(int i = 1; i <= 17; i++)
    {
        vt[i] = Prepare(i);
    }
    vector<int> ans = {a};
    for(int i = n - 1; i >= 1; i--)
    {
        if(GetBit(a, i) == GetBit(b, i))
        {
            Change(a, i);
            ans.push_back(a);
            for(auto j: vt[i - 1])
            {
                Change(a, j);
                ans.push_back(a);
            }
            Change(a, i);
            ans.push_back(a);
        }
        else
        {
            for(auto j: vt[i - 1])
            {
                Change(a, j);
                ans.push_back(a);
            }
            Change(a, i);
            ans.push_back(a);
        }
    }
    if(GetBit(a, 0) != GetBit(b, 0)) Change(a, 0), ans.push_back(a);
    if(ans.size() != (1 << n)) cout << "NO";
    else
    {
        cout << "YES" << '\n';
        for(auto i:ans) cout << i << ' ';
    }
