void solve(int x, int y, int mask, int l, int r)
{
    if(!mask) return;
    int bit=0, t=0, mid=(l+r)>>1;
    for(rint i=0; i<n; ++i)
        if(((x>>i)&1)!=((y>>i)&1) && (mask>>i)&1) bit=1<<i;
    for(rint i=0; i<n; ++i)
        if((mask>>i)&1 && bit!=1<<i) t=1<<i;
    solve(x, x^t, mask^bit, l, mid);
    solve(x^t, y, mask^bit, mid, r);
    for(rint i=l; i<mid; ++i) ans[i]|=x&bit;
    for(rint i=mid; i<r; ++i) ans[i]|=y&bit;

}

