int get(int num, int i) {
    return (num >> i) & 1;
}

int N, A, B;

int toNumber(const std::vector<int>& bits) {
    int res = 0;
    for (int i = 0; i < N; i++) {
        res += (1 << i) * bits[i];
    }
    return res;
}

void func2(std::vector<int>& bits, int idx) {
    int cnt = (1 << (idx + 1)) - 1;
    int carry = -1;

    // std::cerr << "cnt: " << cnt << std::endl;

    if (cnt == 1) {
        bits[0] = bits[0] ^ 1;
        ans.push_back(toNumber(bits));
        return;
    }

    while (cnt > 0) {
        cnt--;

        if (carry < 0) {
            if (bits[0] == 0) {
                bits[0] = 1;
            } else {
                bits[idx] = bits[idx] ^ 1;
                carry = 0;
            }
        } else {
            if (bits[carry] == 0) {
                bits[carry] = 1;
                carry = -1;
            } else {
                bits[carry] = 0;
                carry++;
            }
        }

        if (carry >= idx) {
            carry = -1;
        }

        ans.push_back(toNumber(bits));
        // std::cerr << "add " << toNumber(bits) << std::endl;
    }
}

// 反転した段階でpush_backする
void func(std::vector<int>& bits, int idx) {
    if (idx < 0) return;

    // std::cerr << "idx: " << idx << std::endl;

    if (bits[idx] != get(B, idx)) {
        // std::cerr << "a" << std::endl;
        func(bits, idx - 1);
        bits[idx] = bits[idx] ^ 1;
        ans.push_back(toNumber(bits));
        func(bits, idx - 1);
        return;
    }
    // std::cerr << "b" << std::endl;

    func2(bits, idx);
}

