using namespace std;

vector<int> dfs(int to,int use){
	vector<int> ret,add;
	if(use == 0 || __builtin_popcount(to&use)%2==0){
		return ret;
	}
	int dif = 0;
	while((use&(1<<dif))==0 || (to&(1<<dif))==0)
		dif++;
	if(__builtin_popcount(use)==1){
		ret.push_back(dif);
		return ret;
	}
	int nuse = use^(1<<dif);
	int change = 0;
	while((use&(1<<change))==0 || (change==dif) )
		change++;
	int mid = (1<<change);
	ret = dfs(mid,nuse);
	ret.push_back(dif);
	add = dfs((to^mid),nuse);
	ret.insert(ret.end(),add.begin(),add.end());
	return ret;
}

