typedef long long ll;

#define pc __builtin_popcount

void rec(int A, int B, int mask) {
    if(pc(mask) == 1) {
        printf("%d %d ", A, B);
        return;
    }
    // for(int i = 0; i < 17; ++i) {
        // if((A ^ (1 << i)) == B) {
            // printf("%d %d ", A, B);
            // return;
        // }
    // }
    for(int i = 0; i < 17; ++i) {
        if((mask & (1 << i)) && (((A & (1 << i)) != (B & (1 << i))))) {
            int m2 = mask ^ (1 << i);
            int s = m2;
            while(true) {
                debug() << imie(A) imie(B) imie(i) imie(m2) imie(s);
                debug() << imie(s) imie(B & m2) imie(A & m2) imie(pc(s)) imie(pc(A&m2));
                if((B & m2) != s && (A & m2) != s && pc(s) % 2 != pc(A & m2) % 2) {
                    int tmp = (A ^ (A & mask)) | s;
                    rec(A, tmp, m2);
                    rec(tmp ^ (1 << i), B, m2);
                    return;
                }
                assert(s != 0);
                s = (s - 1) & m2;
            }
        }
    }
}

