  if (n==1) {
    return vector<string>({ss, es});
  }

  int d;
  rep(i, n){
    if (ss[i]!=es[i]){
      d=i;
      break;
    }
  }

  string ns="";
  string mm="";
  string ne="";
  rep(i, n){
    if (i==d) continue;
    else {
      ns += ss[i];
      mm += (ss[i]=='1'?'0':'1');
      ne += es[i];
    }
  }
  if (mm==ne){
    mm = (mm[0]=='1'?'0':'1');
    mm += mm.substr(1);
  }

  dump(ns, mm, ne);
  vector<string> pres = calc(n-1, ns, mm);
  dump(pres);
  vector<string> ares = calc(n-1, mm, ne);
  dump(ares);
  vector<string> res;
  for(auto x:pres){
    string tmp="";
    tmp += x.substr(0, d);
    tmp += ss[d];
    tmp += x.substr(d, n-d);
    res.pb(tmp);
  }
  for(auto x:ares){
    string tmp="";
    tmp += x.substr(0, d);
    tmp += es[d];
    tmp += x.substr(d, n-d);
    res.pb(tmp);
  }
  return res;
}

