int n, a, b;
vector<vector<int>> g(200000 + 5);
vector<int> c(200000 + 5);
vector<int> ans;
vector<bool> visited(200000 + 5);

void dfs(int now, int color) {
  c[now] = color;
  for (auto nx : g[now]) {
    if (c[nx] != -1) continue;
    dfs(nx, color^1);
  }
}

bool dfs2(int now, int ed, int color, int cnt) {
  int nx_color = color^1;
  visited[now] = true;
  bool flag = false;
  for (auto nx : g[now]) {
    if (c[nx] != nx_color || visited[nx]) continue;
    if (nx == ed) {
      flag = true;
      continue;
    }
    bool ok = dfs2(nx, ed, nx_color, cnt + 1);
    if (ok) {
      ans.push_back(now);
      return true;
    }
    visited[nx] = false;
  }
  if (flag && cnt == (1LL<<n) - 1) {
    ans.push_back(ed);
    ans.push_back(now);
    return true;
  }
  return false;
}

