void solve() {
    //const i64 mod = 1'000'000'007;

    i64 N,A,B;
    cin >> N >> A >> B;

    const i64 maxn=17;
    vector<i64> diff;
    rep(i,0,N){
        i64 k=1<<i;
        if((A&k)!=(B&k)){
            diff.emplace_back(i);
        }
    }

    if(diff.size()%2!=1){
        cout << "NO" << endl;
        return;
    }

    vector<i64> ans(1<<N),eo(N),use(N),org;
    for(auto d:diff){
        eo[d]=1;
    }

    org=eo;

    static bool visit[1<<maxn];
    fill_n((bool*)visit,1<<maxn,false);

    /*
    i64 prev=-1,pos=A;
    rep(i,0,(1<<N)-1){
        ans[i]=pos;
        visit[pos]=true;
        vector<i64> es,os;
        vector<pair<i64,i64>> ps;
        rep(j,0,N){
            ps.push_back(make_pair(use[j],j));
        }
        sort(begin(ps),end(ps));
        for(auto p:ps){
            i64 j=p.second;

            if(j==prev) continue;

            i64 np=pos^(1<<j);
            if(visit[np]) continue;
            if(np==B and (i!=((1<<N)-2))){
                continue;
            }

            if(org[j]==0){
                if(use[j]+1>2) continue;
            }else{
                if(use[j]+1>3) continue;
            }
            if(eo[j]==0) es.emplace_back(j);
            else os.emplace_back(j);
        }
        if(!os.empty()){
            i64 j=os.front();
            eo[j]=(eo[j]+1)%2;
            ++use[j];
            prev=j;
            pos^=1<<j;
        }else{
            i64 j=es.front();
            eo[j]=(eo[j]+1)%2;
            ++use[j];
            prev=j;
            pos^=1<<j;
        }
        print(pos);
    }
     */

    function<bool(i64,i64,i64)> dfs=[&](i64 i,i64 prev,i64 pos){
        ans[i]=pos;
        visit[pos]=true;

        if(i==((1<<N)-1)){
            assert(pos==B);
            return true;
        }

        rep(j,0,N){
            if(j==prev) continue;

            i64 np=pos^(1<<j);
            if(visit[np]) continue;
            if(np==B and (i+1!=((1<<N)-1))){
                continue;
            }

            eo[j]=(eo[j]+1)%2;
            ++use[j];
            if(dfs(i+1,j,pos^(1<<j))) return true;
            else{
                --use[j];
                eo[j]=(eo[j]+1)%2;
            }
        }

        visit[pos]=false;
        return false;
    };

    if(!dfs(0,-1,A)){
        cout << "NO" << endl;
        return;
    }

    cout << "YES" << endl;
    rep(i,0,1<<N){
        cout << ans[i];
        if(i==((1<<N)-1)) cout << endl;
        else cout << " ";
    }
}

