V solve(int n, int a, int b) {
  int c = a^b;
  if (__builtin_popcount(c) % 2 == 0) 
    return V();

  if (n == 1) 
    return V({a, b});

  int d = 0;
  while (c%2 == 0) {
    c >>= 1;
    ++d;
  }
  int a1 = (a>>(d+1));
  int a2 = ((a>>d)&1);
  int a3 = a % (1<<d);
  int b1 = (b>>(d+1));
  int b2 = ((b>>d)&1);
  int b3 = b % (1<<d);

  auto res1 = solve(n-1, (a1<<d)+a3, ((a1<<d)+a3)^1);
  for (auto &e : res1) {
    e = ((e>>d)<<(d+1)) + (a2<<d) + e % (1<<d);
