  auto res2 = solve(n-1, ((a1<<d)+a3)^1, (b1<<d)+b3);
  for (auto &e : res2) {
    e = ((e>>d)<<(d+1)) + ((a2^1)<<d) + e % (1<<d);
  }
  res1.insert(res1.end(), all(res2));
  return res1;
}


