vi mg(int n) {
	vi cnt = gc(n);
	if(n == 1) return cnt;
	int sw = (1<<(n-2));
	int sz = cnt.size();
	while(sw) {
		int ch = sw|(sw/2);
		int mp = 0;
		int fr = sz-2*sw+1;
		for(int i=fr;i<sz;i++) {
			cnt[i] ^= mp;
			int ko = cnt[i]^cnt[i-1];
			if(ko&ch) {
				cnt[i] ^= ch;
				mp ^= ch;
			}
		}
		sw >>= 2;
	}
	return cnt;
}
