void cal(int a, int b, int S) {
    if(__builtin_popcount(S) == 1) {
	printf("%d %d ", a, b);
	return;
    }
    REP(i, 0, n) {
	if((S >> i) & 1 && ((a >> i) & 1) ^ ((b >> i) & 1)) {
	    REP(j, 0, n) {
		if((S >> j) & 1 && !((a >> j) & 1) ^ ((b >> j) & 1)) {
		    cal(a, a ^ (1 << j), S ^ (1 << i));
		    cal(b ^ (1 << j), b, S ^ (1 << i));
		    break;
		}
	    }
	    break;
	}
    }
}

