int n;
int a;
int b;

vector<int> ans;

bool used[MAX_MASK];

void gen(int k)
{
    if (k == (1 << n))
    {
        if (ans.back() == b)
        {
            cout << "YES\n";
            for (int it : ans)
            {
                cout << it << ' ';
            }
            exit(0);
        }
        return;
    }
    int cur = ans.back();
    if (__builtin_popcount(cur ^ b) > ((1 << n) - k))
    {
        return;
    }
    for (int i = 0; i < n; ++i)
    {
        if (!used[cur ^ (1 << i)])
        {
            ans.pb(cur ^ (1 << i));
            used[cur ^ (1 << i)] = true;
            gen(k + 1);
            ans.pop_back();
            used[cur ^ (1 << i)] = false;
        }
    }
}

int solve()
{
    cin >> n >> a >> b;
    if (n == 1)
    {
        cout << "YES\n";
        cout << a << ' ' << b << '\n';
        return 0;
    }
    if (__builtin_popcount(a) == __builtin_popcount(b))
    {
        cout << "NO\n";
        return 0;
    }
    used[a] = true;
    ans.pb(a);
    gen(1);
    cout << "NO\n";
    return 0;
}

