using namespace std;

int n, a, b;

int swap_bits(int x, int i, int j) {
    int iv = (x >> i) & 1;
    int jv = (x >> j) & 1;
    if (iv) x ^= (1 << i);
    if (jv) x ^= (1 << j);

    x ^= iv << j;
    x ^= jv << i;

    return x;
}

int main() {
    scanf(" %d %d %d", &n, &a, &b);

    if (__builtin_popcount(a ^ b) != 1) {
        printf("NO\n");
        return 0;
    }

    vector<int> gray(1 << n);
    for (int i = 0; i < (1 << n); ++i) {
        gray[i] = (i ^ (i >> 1));
    }

    int desired_bit = __builtin_ctz(a ^ b);

    for (int i = 0; i < (1 << n); ++i) {
        gray[i] = swap_bits(gray[i], n - 1, desired_bit);
        gray[i] ^= a;
    }

    printf("YES\n");
    for (int i = 0; i < (1 << n); ++i) {
        printf("%d ", gray[i]);
    }
    printf("\n");

    return 0;
}

