vector<int> solveFor(int n, int a, int b) {
	if(n == 1) {
		if(a == 0) return {0, 1};
		else return {1, 0};
	}
	int x;
	for(int i=0; ; i++) {
		if(((a >> i) & 1) != ((b >> i) & 1)) {
			x = i;
			break;
		}
	}
	int na = 0, nb = 0, ati = 0;
	for(int i=0; i<n; i++) {
		if(i == x) continue;
		if((a >> i) & 1) na |= (1 << ati);
		if((b >> i) & 1) nb |= (1 << ati);
		ati++;
	}
	int nc = na ^ 1;
	vector<int> A = solveFor(n-1, na, nc);
	vector<int> B = solveFor(n-1, nc, nb);
	vector<int> C;
	for(auto it : A) {
		int ati = 0, num = 0;
		for(int i=0; i<n; i++) {
			if(i == x) {
				if((a >> i) & 1) num |= (1 << i);
				continue;
			}
			if((it >> ati) & 1) num |= (1 << i);
			ati++;
		}
		C.pb(num);
	}
	for(auto it : B) {
		int ati = 0, num = 0;
		for(int i=0; i<n; i++) {
			if(i == x) {
				if((b >> i) & 1) num |= (1 << i);
				continue;
			}
			if((it >> ati) & 1) num |= (1 << i);
			ati++;
		}
		C.pb(num);
	}
	return C;
}

