vector<int> cal(int f, int g, int mask) {
	int z = -1, zz = -1;
	for (int i = 0; i < MAXN; i++) if ((f ^ g) & (1 << i))	{
		z = i;
		break;
	}
	if (z == -1) return {f};
	for (int i = 0; i < MAXN; i++) if (i != z && mask & (1 << i)) {
		zz = i;
		break;
	}
	if (zz == -1) return {f, g};
	return cal(f, f ^ (1 << zz), mask ^ (1 << z)) + cal(f ^ (1 << zz) ^ (1 << z), g, mask ^ (1 << z));
}




