int rui(int n) { 
	if (n == 0) { return 1; }
	return 2 * rui(n - 1);
}
void add(int &num, int i,int bit) {
	num = 2 * (rui(i)*(num / rui(i))) + num % rui(i) + bit * rui(i);
}
int  del(int &num, int i) {
	return rui(i)*(num / rui(i + 1)) + num % rui(i);
}
int ord(int n) {
	if (n % 2 == 1) { return 0; }
	return ord(n / 2) + 1;
}
vel ret(int a, int b, int n) {
	int goa = a xor b;
	if (n == 1) {
		if (a == 0) { return { 0,1 }; }
		else { return { 1,0 }; }
	}
	int che;
	for (int i = 0; i < n; i++) {
		if ((goa & 1 << i) != 0) {
			che = i;
		}
	}
	int mn = n - 1;
	vel gray(rui(mn),0);
	for (int i = 1; i < rui(mn); i++) {
		gray[i] = gray[i - 1] xor rui(ord(i));
	}
	for (int i = 0; i < rui(mn); i++) {
		add(gray[i], che, 0);
	}
	vel q = ret(rui(mn - 1), del(goa, che), mn);
	for (int i = 0; i < rui(mn); i++) {
		add(q[i], che, 1);
	}
	vel ans(rui(n));
	for (int i = 0; i < rui(mn); i++) { ans[i] = gray[i] xor a; }
	for (int i = 0; i < rui(mn); i++) { ans[i + rui(mn)] = q[i] xor a; }
	return ans;
}
