vector<int> subsolve(int n, int a, int b, int mask) {
    for (int i = 0; i < n; i++) {
        int bit = (1 << i);
        if ((mask & bit) && (a & bit) == (b & bit)) {
            auto res = subsolve(n, (a & ~bit), (b & ~bit), mask ^ bit);
            int have = a & bit;
            vector<int> nres;
            for (int i = 0; i < (int)res.size(); i += 2) {
                nres.push_back(res[i] ^ have);
                nres.push_back(res[i] ^ have ^ bit);
                nres.push_back(res[i + 1] ^ have ^ bit);
                nres.push_back(res[i + 1] ^ have);
            }
            return nres;
        }
    }

    int active = __builtin_popcount(mask);
    assert(active % 2 == 1);
    if (active == 1) {
        return vector<int>({a, b});
    }
    int b1 = 0;
    while (!((mask >> b1) & 1)) b1++;

    int b2 = b1 + 1;
    while (!((mask >> b2) & 1)) b2++;

    int na = a & ~(1 << b1);
    int nb = b & ~(1 << b1);

    if ((na ^ (1 << b2)) == nb) {
        b2++;
        while (!((mask >> b2) & 1)) b2++;
    }

    auto res1 = subsolve(n, na, na ^ (1 << b2), mask ^ (1 << b1));
    auto res2 = subsolve(n, na ^ (1 << b2), nb, mask ^ (1 << b1));

    int c1 = a & (1 << b1);
    int rc1 = c1 ^ (1 << b1);

    vector<int> res;
    for (int x : res1) res.push_back(x ^ c1);
    for (int x : res2) res.push_back(x ^ rc1);
    return res;
