vector<int> solve(int n, int a, int b) {
    if (__builtin_popcount(a) % 2 == __builtin_popcount(b) % 2) {
        return vector<int>();
    }

    auto res = subsolve(n, a, b, (1 << n) - 1);
    assert(res.size() == (1 << n));
    assert(res[0] == a);
    assert(res.back() == b);
    for (int i = 1; i < (int) res.size(); i++) assert(__builtin_popcount(res[i] ^ res[i - 1]) == 1);
    assert(set<int>(res.begin(), res.end()).size() == (1 << n));
    return res;
}

