        assert((__builtin_popcount(ans[i - 1] xor ans[i])) == 1);

    vector<char> used(1 << n, 0);
    for (int el: ans) {
        assert(0 <= el and el < (1 << n));

        assert(not used[el]);
        used[el] = 1;
    }
}

