    for(int i = 0; i < (1 << n); i++) q[i] = 0;
    for(int i = 0; i < n; i++) {
        if(c & (1 << i)) {
            k[m++] = 1 << i;
            if(a & (1 << i)) for(int j = (1 << n) - 1; j >= 0; j--) p[j] ^= (1 << i);
