    for(int i = 0; i < s; i++) {
        for(int j = 0; j < (1 << i); j++) {
            q[(1 << (i + 1)) - j - 1] = q[j] ^ l[i];
        }
    }
    for(int i = 0; i < (1 << s); i++) q[(1 << (s + 1)) - i - 1] = q[i];
    for(int i = 0; i < (1 << n); i++) ans[i] = q[i % (1 << (s + 1))] + p[i / (1 << s)];
