vector<int> generate(int N, int d) {
    assert(d % 2 == 1);
    if (d == 1) {
        if (N == 1) return {0, 1};
        auto vec1 = generate(N-1, 1);
        auto vec2 = vec1;
        reverse(vec2.begin(), vec2.end());
        for (int& x : vec2) x += 1<<(N-1);
        for (int x : vec2) vec1.push_back(x);
        return vec1;
    }
    auto vec = generate(N-2, d-2);
    vector<int> c1 = {0,1,3,2};
    vector<int> c2 = {2, 0, 1, 3};
    vector<int> c3 = {2, 3, 1, 0};
    for (int& x : c1) x <<= N-2;
    for (int& x : c2) x <<= N-2;
    for (int& x : c3) x <<= N-2;
    vector<int> res;
    for (int it = 0; it < SZ(vec); it++) {
        int x = vec[it];
        if (it%2 == 0) for (int z : c1) res.push_back(x + z);
        else if (it < SZ(vec)-1) for (int z : c3) res.push_back(x + z);
        else for (int z : c2) res.push_back(x + z);
    }
    return res;
}

