bool get(int n,ll a,ll b){
	vector<set<ll>> num(n+1);
	rep(i,1<<n){
		num[popcnt(i)].insert(i);
	}
	vl a1,a2,a3;
	while(1){
		a1.push_back(a);
		num[popcnt(a)].erase(a);
		if(a==0)break;
		a&=(a-1);
	}
	while(1){
		a3.push_back(b);
		num[popcnt(b)].erase(b);
		if(popcnt(b)==n)break;
		b|=(b+1);
	}
	int p=1;
	ll v=-1;
	while(1){
		if(num[p].size()==0)break;
		if(v==-1)v=*num[p].begin();
		a2.push_back(v);
		num[p].erase(v);
		if(num[p-1].size()!=0){
			p--;
			rep(i,n){
				if(num[p].find(v&(~(1<<i)))!=num[p].end()){
					v&=(~(1<<i));
					break;
				}
			}
			if(popcnt(v)==p)continue;
			p++;
		}
		if(num[p+1].size()!=0){
			p++;
			rep(i,n){
				if(num[p].find(v|(1<<i))!=num[p].end()){
					v|=(1<<i);
					break;
				}
			}
			if(popcnt(v)==p)continue;
			p--;
		}
		break;
	}
	if(a1.size()+a2.size()+a3.size()!=(1<<n)){
		return false;
	}
	reverse(all(a3));
	puta("YES");
	puta(a1,a2,a3);
	return true;
}

