void swap_bytes(int& num, int a, int b)
{
    int x = num;
    x &= (1 << 30) - 1 - (1 << a);
    x &= (1 << 30) - 1 - (1 << b);
    x |= (1 << a) * (((1 << b) & num) > 0);
