int N, A, B, bit;

bool calc()
{
	bit = 1;
	int x = 1;
	int a = A;
	int b = B;
	int c = 0;
	while (a + b) {
		if ((a ^ b) & 1) {
			bit = x;
			c++;
		}
		x <<= 1;
		a >>= 1;
		b >>= 1;
	}
	return c % 2;
}

vector<int> res(3000000);

void dfs(set<int>& s, int b, int l, int r)
{
	if (r - l == 4) {
		int t = *s.begin();
		int u = *(next(s.begin(), 1));
		int x = t ^ res[l];
		if (x != (x & -x)) {
			swap(t, u);
		}
		res[l+1] = t;
		res[l+2] = u;
		return;
	}
	set<int> x, y;
	int t = res[l] ^ res[r-1];
	t = t & -t;
	for (auto a : s) {
		if ((a & t) ^ (t & res[r-1])) {
			x.insert(a);
		} else {
			y.insert(a);
		}
	}
	int t2 = *x.begin();
	int t3 = t2 ^ t;
	res[(r+l)/2-1] = t2;
	res[(r+l)/2] = t3;
	x.erase(t2);
	y.erase(t3);
	dfs(x, b+1, l, (r+l)/2);
	dfs(y, b+1, (r+l)/2, r);
}

int cm(int a, int b) {
	bit = 1;
	int x = 1;
	int c = 0;
	while (a + b) {
		if ((a ^ b) & 1) {
			bit = x;
			c++;
		}
		x <<= 1;
		a >>= 1;
		b >>= 1;
	}
	return c == 1;
}

