		const int last = r.back();
		int p = -1;
		for(int i = 0; i < m; ++i){
			if(r[i] == g){ break; }
			if(__builtin_popcount(last ^ r[i]) == 1){ p = i + 1; }
		}
		reverse(r.begin() + p, r.end());
	}

	cout << "YES" << endl;
	for(int i = 0; i < m; ++i){
		cout << (a ^ r[i]) << " ";
	}
	cout << endl;
	return 0;
}

