	rep(i, N)
	{
		if ((A >> i) & 1) ++cnt1;
		if ((B >> i) & 1) ++cnt2;
	}
	if (cnt1 % 2 == cnt2 % 2)
	{
		out << "No" << std::endl;
		return 0;
	}

	out << "Yes" << std::endl;
	auto ans = f(A, B, N);
	rep(i, (1LL << N)) out << ans[i] << (i < (1LL << N) - 1 ? " " : "\n");
}

