// wbit整数Aを左に回す
inline int lslide(int A, int w) {
    return ((A << 1) + (A >> (w - 1))) & ((1 << w) - 1);
}

// wbit整数Aを右に回す
inline int rslide(int A, int w) {
    return ((A >> 1) + (A << (w - 1))) & ((1 << w) - 1);
}

vector<int> dp[20];

// [0, 2^w)全体を回るようなサイクルを作る
vector<int> cycle(int w) {
    if (w == 0) return {0};
    if (!dp[w].empty()) return dp[w];

    vector<int> head = cycle(w - 1);
    vector<int> tail = head;
    reverse(tail.begin(), tail.end());
    for (auto& t : tail) t += (1 << (w - 1));
    copy(tail.begin(), tail.end(), back_inserter(head));
    return dp[w] = head;
}

vector<int> solve(int A, int B, int N) {
    if (N == 1) return {A, B};

    vector<int> ch = cycle(N - 1);
    if (((A >> (N - 1)) & 1) != ((B >> (N - 1)) & 1)) {
        for (auto& c : ch) c ^= A;
        auto res = solve(ch.back() ^ (1 << (N - 1)), B, N - 1);
        copy(res.begin(), res.end(), back_inserter(ch));
        cerr << make_pair(A, B) << ch << endl;
        return ch;
    } else {
        auto res = solve(lslide(A, N), lslide(B, N), N);
        for (auto& a : res) a = rslide(a, N);
        return res;
    }
}

