    int cnt = 0, now = 0, mnum = (1 << i);
    for(int j = 0; j < vsize; ++j) {
      if(d[now]) v[j] += 1 << memo[i];
      ++cnt;
      if(cnt == mnum) {
        cnt = 0;
        ++now;
        now %= 4;
      }
    }
  }
  if(ls.size() == 1) {
    for(int i = 0; i < vsize; ++i) {
      v[i] ^= (1 << (n - 1)) ^ (1 << ls[0]);
    }
    ch = 1;
    return;
  }
  for(int i = 1; i < vsize - 1; ++i) {
    int now = v[i] ^ v[vsize - 1], cnt = 0, x = 0;
    for(int j = 0; j < n; ++j)
      if((now >> j) % 2 == 1) ++cnt;
    if(cnt > 1) continue;
    cnt = 0;
    now = v[i + 1];
    for(int j = 0; j < n; ++j)
      if((now >> j) % 2 == 1) {
        x += (1 << j);
        ++cnt;
      }
    if(ls.size() != cnt) continue;
    for(int j = 0; j < ls.size(); ++j) {
      x ^= (1 << ls[j]);
    }
    for(int j = 0; j < vsize; ++j) v[i] ^= x;
    reverse(v.begin() + i + 1, v.end());
    ch = 1;
    return;
  }
}

