#include <bits/stdc++.h>

using namespace std;

const int N = 18;
int ans[1 << N];
int gray[1 << N];
int h[1 << N];

void swapBit(int u, int v, int L, int R) {
    int mask = (1 << u) ^ (1 << v);
    for(int i = L; i < R; i++){
        int s1 = (ans[i] >> u) & 1;
        int s2 = (ans[i] >> v) & 1;
        if (s1 != s2) ans[i] ^= mask;
    }
}
void build(int depth, int L, int R, int st, int en) {
    //cout << depth << " " << L << " " << R << " " << st << " " << en << '\n';
    assert(st < (1 << depth));
    assert(en < (1 << depth));
    int nen = en ^ st;

    vector<int> diff;
    for(int i = 0; i < depth; i++) if ((nen >> i) & 1) 
        diff.push_back(i);
    int ndiff = diff.size();

    if (ndiff == 1) {
        for(int i = L; i < R; i++) ans[i] = gray[i - L];
        swapBit(diff[0], depth - 1, L, R);
        for(int i = L; i < R; i++) ans[i] ^= st;
        return;
    }
    int half2 = nen ^ (1 << diff[ndiff - 1]);
    int half1 = half2 ^ (1 << diff[ndiff - 2]);

    int mid = (L + R) / 2;
    build(depth - 1, L, mid, 0, half1); 
    build(depth - 1, mid, R, half1, half2);
    for(int i = mid; i < R; i++)
        ans[i] ^= 1 << (depth - 1);
    swapBit(diff.back(), depth - 1, L, R);
    for(int i = L; i < R; i++) ans[i] ^= st;
}
int main() {
    gray[1] = 1;
    for(int i = 1; i < N; i++) 
        for(int j = 0; j < (1 << i); j++) 
            gray[(1 << i) + j] = gray[(1 << i) - j - 1] ^ (1 << i);
    int n, st, en;
    cin >> n >> st >> en;
    if (__builtin_popcount(st ^ en) % 2 == 0) {
        cout << "NO";
        exit(0);
    }
    cout << "YES\n";
    build(n, 0, (1 << n), st, en);
    for(int i = 0; i < (1 << n); i++) cout << ans[i] << " ";
    for(int i = 0; i < (1 << n); i++) h[ans[i]]++;
    assert(count(h, h + (1 << n), 1) == (1 << n));
    assert(ans[(1 << n) - 1] == en);
    assert(ans[0] == st);
    for(int i = 1; i < (1 << n); i++) assert(__builtin_popcount(ans[i] ^ ans[i - 1]) == 1);
}

