void solve() {
  v.assign((1 << n), 0);
  int vsize = v.size();
  for(int i = 0; i < n; ++i) {
    int cnt = 0, now = 0, mnum = (1 << i);
    for(int j = 0; j < vsize; ++j) {
      if(d[now]) v[j] += 1 << memo[i];
      ++cnt;
      if(cnt == mnum) {
        cnt = 0;
        ++now;
        now %= 4;
      }
    }
  }
  if(ls.size() == 1) {
    for(int i = 0; i < vsize; ++i) {
