vector<int> solve(int st,int en,int lev){
	if(lev == 0)	return {st,en};
	int idx = __builtin_ctz(st^en);
	int base = 1<<idx;
	int nxtst = st%base + st/base/2*base;
	int nxten = en%base + en/base/2*base;
	auto ls = solve(nxtst,nxtst^1,lev-1);
	auto rs = solve(nxtst^1,nxten,lev-1);
	vector<int> res;
	for(int it:ls)
		res.emplace_back(it%base+it/base*2*base);
	for(int it:rs)
