class SegmentTree {
private:
	int n;
	Array node;

public:
	SegmentTree(Array &v) {
		int sz = v.size();
		n = 1; while (n < sz)n *= 2;
		node.resize(2 * n - 1, 0);
		REP(i, sz) {
			node[i + n - 1] = v[i];
		}
		for (int i = n - 2; i >= 0; i--) {
			node[i] = gcd(node[i * 2 + 1], node[i * 2 + 2]);
		}
	}
	ll getSum(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		if (r <= a || b <= l)return 0;
		if (a <= l && r <= b)return node[k];

		ll vl = getSum(a, b, 2 * k + 1, l, (l + r) / 2);
		ll vr = getSum(a, b, 2 * k + 2, (l + r) / 2, r);
		ll ret = gcd(vl, vr);
		return ret;
	}
};




void solve(ll c, Array& p, ll &a, ll now) {
	if (now == 0) {
		ll temp = a ^ c;
		bitset<17> bit = temp;
		ll ans = 0;
		REP(j, bit.size()) {
			if (bit[j] == 1)ans += (ll)pow(2, p[j]);
		}
		cout << ans << ' ';
		return;
	}
	solve(c, p, a, now - 1);
	a ^= (1 <<( now-1));
	solve(c, p, a, now - 1);
}

void solve3(ll l, ll d, Array& p, ll &a, ll c, ll s) {
	if (l == 0)solve(c, p, a, d);
	else {
		solve3(l - 1, d, p, a, c, s);
		a ^= (1 << (d + (s - l) - 1));
		solve3(l - 1, d, p, a, c, s);
	}


}

void solve2(ll l, ll d, Array& p, ll &a, ll c,ll flag) {
	if(l==0)solve(c, p, a, d);
	else if(flag==0){
		solve2(l - 1, d, p, a, c,0);
		a ^= (1 << (l + d - 1));
		solve2(l - 1, d, p, a, c,0);
	}
	else {
		solve2(l - 1, d, p, a, c, 0);
		a ^= (1 << (l + d - 1));
		solve3(l - 1, d, p, a, c, l);
	}
}




