vi solve(int N, int A, int B) {
    if ((__builtin_popcount(A)-__builtin_popcount(B)) % 2 == 0) return {};
    if (N == 1) {
        // ps("ZZ",A);
        return {A,A^1};
    }
    if (A != 0) {
        auto a = solve(N,0,B^A); 
        trav(t,a) t ^= A;
        // ps("AA",N,A,B,a);
        return a;
    }
    if (!(B&(1<<(N-1)))) {
        int t = 0; while (!(B&(1<<t))) t ++;
        int bad = (1<<t)^(1<<(N-1));
        auto a = solve(N,A,B^bad); 
        trav(x,a) {
            int X = x;
            if (X&(1<<t)) x ^= bad;
            if (X&(1<<(N-1))) x ^= bad;
            // if ((x&(1<<t)) || (x&(1<<(N-1)))) x ^= bad;
        }
        // ps("BB",N,A,B,a); exit(0);
        return a;
    }
    vi z = {0};
    FOR(i,1,1<<(N-1)) {
        int t = 0; while (!(i&(1<<t))) t ++;
        z.pb(z.back()^(1<<t));
    }
    auto t = solve(N-1,A^(1<<(N-2)),B^(1<<(N-1)));
    trav(x,t) x ^= 1<<(N-1);
    z.insert(z.end(),all(t)); 
    // ps("HUH",A,z[0]);
    // ps("CC",N,A,B,z);
    return z;
}

