	solve(l,m,dep+1),solve(m+1,r,dep+1);
	if(dep&1)
	{
		for(int i=m+1;i<=r;i++)p[i<<st]^=b[dep]|b[dep+1];
	}
	else 
	{
		for(int i=m+1;i<=r;i++)p[i<<st]^=b[dep]|b[dep+1];int t=r-m;
		for(int i=l;i<=m;i++)if((i-l)&1)swap(p[i<<st],p[(i+t)<<st]);
	}
}
void solve2(int l,int r,int dep)
{
	if(l==r)return ;if(l==r-1){u[r]^=t[dep];return ;}int m=(l+r)>>1;
	solve2(l,m,dep+1),solve2(m+1,r,dep+1);
	for(int i=m+1;i<=r;i++)u[i]^=t[dep]|t[dep+1];
}
