#include <bits/stdc++.h>
#define FOR(i,k,n)  for(int i = (k);i < (n);++i)
#define REP(i,n)    FOR(i,0,n)
#define ALL(x)      begin(x),end(x)

using namespace std;
using vecint = vector<int>;
using ll = int64_t;

vector<ll> solve(ll n, ll a, ll b) {
  if (n == 1) {
    vector<ll> res;
    res.push_back(a);
    res.push_back(b);
    return res;
  }
  ll x = a^b;
  ll d = 0;
  REP(i,n) {
    if ((x >> i) & 1) d = i;
  }
  vector<ll> va, vb;
  REP(i,n) {
    if (i != d) {
      va.push_back((a >> i) & 1);
      vb.push_back((b >> i) & 1);
    }
  }
  ll ra = 0, rb = 0;
  REP(i,n-1) {
    ra |= va[i] << i;
    rb |= vb[i] << i;
  }
  auto r1 = solve(n-1, ra, ra^1);
  auto r2 = solve(n-1, ra^1, rb);
  vector<ll> res;
  for(ll r : r1) {
    vector<ll> v;
    REP(i,n-1) {
      v.push_back((r >> i) & 1);
    }
    ll s = 0;
    REP(i,d) {
      s |= v[i] << i;
    }
    s |= a & (1 << d);
    FOR(i,d,n-1) {
      s |= v[i] << (i+1);
    }
    res.push_back(s);
  }
  for(ll r : r2) {
    vector<ll> v;
    REP(i,n-1) {
      v.push_back((r >> i) & 1);
    }
    ll s = 0;
    REP(i,d) {
      s |= v[i] << i;
    }
    s |= b & (1 << d);
    FOR(i,d,n-1) {
      s |= v[i] << (i+1);
    }
    res.push_back(s);
  }
  return res;
}

int main()
{
  ll n,a,b;
  cin>>n>>a>>b;
  ll x = a^b;
  if (__builtin_popcount(x) % 2 != 1) {
    cout << "NO" << endl;
    return 0;
  }
  cout << "YES" << endl;
  vector<ll> res = solve(n, a, b);
  REP(i,1<<n) {
    if(i)cout<<' ';
    cout<<res[i];
  }
  cout<<endl;
  return 0;
}

