vector<int> st;
vector<int> top;

vector<int> calc(int a, int b, int n) {
    if (n == 1) return {a, b};
    int s = __builtin_ffs(a^b);
    int t = 0;
    if ((a & (1 << (s-1))) != 0) t = (1 << (s-1));
    int u = (1 << (s-1)) - 1;
    int aa = (a & u) + ((a >> 1) & ~u);
    int bb = (b & u) + ((b >> 1) & ~u);
    int d = aa ^ 1;
    //cout << a << b << " " << aa << " " << bb << " " << d <<  endl;
    vector<int> e = calc(aa, d, n-1), f = calc(d, bb, n-1);
    for (int i = 0; i < (int)e.size(); i++) e[i] = ((e[i] & ~u) << 1) + t + (e[i] & u);
    for (int q : f) e.push_back(((q & ~u) << 1) + u + 1 - t + (q & u));
    return e;
}

int main(){
    int N, A, B;
    cin >> N >> A >> B;
    B ^= A;
    if (__builtin_parity(B) == 0) {
        cout << "NO" << endl;
        return 0;
    }
    vector<int> base;
    base.push_back(0);
    for (int i = 0; i < N; i++) {
        int t = 1 << i;
        if ((B & t) == 0) {
            for (int j = (int)base.size()-1; j >= 0; j--) {
                base.push_back(base[j]+t);
            }
        }
    }

    for (int i = 0; i < N; i++) {
        if (((B>>i) & 1) != 0) st.push_back(i);
    }

    top = calc(0, (1<<(int)st.size()) - 1, (int)st.size());

    for (int i = 0; i < (int)top.size(); i++) {
        int nt = 0;
        for (int j = 0; j < (int)st.size(); j++) {
            if ((top[i] >> j)&1) nt += (1 << (st[j]));
        }
        top[i] = nt;
    }

    //for (int x : top) cout << x << endl;
    vector<int> ans;
    for (int i = 0; i < (int)top.size(); i++) {
        if (i%2 == 0) {
            for (int j = 0; j < (int)base.size(); j++) {
                ans.push_back(A^top[i]^base[j]);
            }
        }else {
            for (int j = (int)base.size()-1; j >= 0; j--) {
                ans.push_back(A^top[i]^base[j]);
            }
        }
    }
    cout << "YES\n";
    for (int i = 0; i < (1<<N); i++) {
        if (i < (1<<N)-1) printf("%d ", ans[i]);
        else printf("%d\n", ans[i]);
    }
    return 0;
}

