vi rek(int k)
{
	if (!k)
		return {0};
	vi wez=rek(k-1);
	vi ret;
	for (int i=0; i<(int)wez.size(); i++)
	{
		if (!(i&1))
		{
			ret.push_back(2*wez[i]);
			ret.push_back(2*wez[i]+1);
		}
		else
		{
			ret.push_back(2*wez[i]+1);
			ret.push_back(2*wez[i]);
		}
	}
	return ret;
}

