#include <bits/stdc++.h>
using namespace std;

#define int long long

const int N = 18;
int n, A, B;
vector <int> ans;

void f(int mask, int v, int u) {
	if (v == u)
		return;
	if (__builtin_popcount(mask) == 1) {
		ans.push_back(v);
		ans.push_back(u);
		return;
	}

	int indx = 0;
	for (int i = 0; i < n; i++)
		if ((mask & (1LL << i)) && (((1LL << i) & v) != ((1LL << i) & u)))
			indx = i;

	int w = v;
	for (int i = 0; i < n; i++)
		if ((mask & (1LL << i)) && i != indx) {
			w ^= (1LL << i);
			break;
		}

	mask ^= (1LL << indx);
	f(mask, v, w);
	f(mask, w ^ (1LL << indx), u);
}

int32_t main() {
	cin >> n >> A >> B;
