int n,a,b;
int ans[201000];
void work(int x,int y,int l,int r,int n,int det) {
	ans[l] = x^det; ans[r] = y^det;
	if(n == 1) {
		if(x == 0) ans[l+2] = 3,ans[l+1] = 2^(y==1?0:3);
		else if(x == 2) ans[l+2] = 1,ans[l+1] = 3^(y==0?0:3);
		else if(x == 3) ans[l+2] = 0,ans[l+1] = 1^(y==2?0:3);
		else if(x == 1) ans[l+2] = 2,ans[l+1] = (y==3?0:3);
		return;
	}
	int f1 = (x>>n&1) , f2 = (y>>n&1) , toy;
	toy = (f1==f2) ? y : y^(1<<n);
	repp(i,n-1,0) if( (toy^(1<<i)) != x ) {toy = y ^ (1<<i);break;} 
	if( f1^f2 ) {
		work( x-(f1?(1<<n):0) , toy - (f2?(1<<n):0) , l , l+(1<<n-1)-1 , n-1 , det+(f1?(1<<n):0) );
		work( toy , y , l+(1<<n-1) , r , n-1 , det+(f2?(1<<n):0) );
	}
	else {
		work( x-(f1?(1<<n):0) , y - (f2?(1<<n):0) , l+(1<<n-1) , r , n-1 , det+(f1?(1<<n):0) );
		work( x^(1<<n) , ans[l+(1<<n-1)+1]^(1<<n) , l+1 , l+(1<<(n-1)) , n-1 , det+(f1?0:(1<<n)) );
	}
}
