    if (evenBit(A) == evenBit(B)) {
        cout << "NO" << endl;
        return 0;
    }
    cout << "YES" << endl;
    B ^= A;

    int n1 = count1(B);
    int n0 = N-n1;
    makeP0(n0);
    makeP1(n1);

    REP (i, 1<<n1) {
        REP (j, 1<<n0) {
            int r1 = P1[i];
            int r0 = (i&1) ? P0[(1<<n0)-j-1] : P0[j];
            cout << ((r1+r0)^A) << ((i+1==(1<<n1) && (j+1==(1<<n0))) ? "\n" : " ");
        }
    }
}

