void po( ll n, ll mask, ll s, ll g ) {
  ll p = 0;

  if( n == 1 ) {
    rep( i, N ) if( mask>>i&1 )
    { ans.emplace_back( i ); break; }

    return;
  }

  ll sm = s&mask, gm = g&mask;

  rep( i, N ) if( mask>>i&1 ) {
    if( (sm>>i&1) != (gm>>i&1) )
    { p = i; break; }
  }

  rep( i, N ) if( mask>>i&1 && p != i ) {
    sm ^= 1<<i;
    gm ^= 1<<i;

    break;
  }

  po( n-1, mask^(1<<p), s, sm );
  ans.emplace_back( p );
  po( n-1, mask^(1<<p), gm, g );
}

