  if(cntx%2==1&&cnty%2==0) res=front_rev(res,rs);
  int j=0,a=3,b=8;
  while(j<cntx/2){
    res=front_rev(res,a);
    a+=b;
    b*=4;
    j++;
  }
  j=0;a=3;b=8;
  while(j<cnty/2){
    res=behind_rev(res,a);
    a+=b;
    b*=4;
    j++;
  }
  int k;
  rep(i,rs) if(res[i]==x) k=i;
  int temp=res[k];
  res[k]=res[0];
  res[0]=temp;
  rep(i,rs) if(res[i]==y) k=i;
  temp=res[k];
  res[k]=res[rs-1];
  res[rs-1]=temp;

  return res;
}
