inline bool count(int x){
	bool s=0;
	while(x){
		x^=x&-x;
		s=!s;
	}
	return s;
}
inline void walk(int x,int h){
	int i,j,res=x;
	set<int> s;
	for(i=0;i<(1<<h);++i){
		s.insert(res);a[++cnt]=res;
		for(j=0;j<h;++j)if(s.find(res^(1<<j))==s.end()){
			res^=1<<j;
			break;
		}
	}
}
void go(int x,int y,int h){
	if(h==1){a[++cnt]=x;a[++cnt]=y;return;}
	if((x&(1<<h-1))!=((y&(1<<h-1)))){
		walk(x,h-1);
		x=a[cnt]^(1<<h-1);
		go(x,y,h-1);
	}else{
		go(x,y,h-1);--cnt;
		go(a[cnt]^(1<<h-1),y^(1<<h-1),h-1);
		a[++cnt]=y;
	}
}
int main(){
	int n,s,t,i;
