int n,a,b,sum;
void dfs(int x,int y,int ban){
    if(__builtin_popcount(ban^sum)==1){
        printf("%d %d ",y,x^y);
        return;
    }
    for(int i=0;i<n;i++)
        if((~(ban>>i)&1)&&(x>>i&1))
            for(int j=0;j<n;j++)
                if((~(ban>>j)&1)&&i!=j){
                    dfs(1<<j,y,ban|1<<i);
                    dfs(x^(1<<i)^(1<<j),y^(1<<i)^(1<<j),ban|1<<i);
                    return;
                }
}
/*dfs(x,y,ban)表示需要从状态0走到状态x，ban是一个长度为n的二进制串，其中第i位为1表示这一维已经不存在了，即若这个二进制串总共有p个0，则表示当前需要处理的是在p维空间下从0走到x这件事情。
划分的时候先找到某个二进制位满足x在这一位上为1（也就是代码里的i），然后在随便选一个在第i位上是0且有奇数个1的数，代码里为了方便我就直接选了某个2^j，然后递归构造0 -> 2^j -> 2^j+2^i -> x的路径就行了。
那个y是指表明接下来处理的所有数在输出时都要异或上y，这样在划分问题的时候可以比较方便地把子问题归为“从0出发走到x”这种形式。*/
int main(){
    scanf("%d%d%d",&n,&a,&b);
    sum=(1<<n)-1;
    if(__builtin_popcount(a^b)&1){
        printf("YES\n");
        dfs(a^b,a,0);
    }
    else
        printf("NO");
    return 0;
}
/*要从0走到AxorB，可以选出一个二进制位p满足AxorB在第p位上值为1，遍历二进制第p位为0的所有点组成的n−1维超立方体后，再去遍历二进制位第p位为1的所有点组成的n−1维超立方体。两个n−1维超立方体之间的连接点的选取是任意的，只需要满足起点终点二进制位不同的位数是奇数。*/

#include <bits/stdc++.h>
using namespace std;
#define modulo 1000000007
#define mod(mod_x) ((((long long)mod_x+modulo))%modulo)
#define Inf 1000000000

int N;
vector<int> ans;

void dfs(int x,int y,vector<bool> used){
	//cout<<x<<','<<y<<endl;
	int c = 0;
	for(int i=0;i<N;i++){
		if(!used[i])c++;
	}
	if(c==1){
		ans.push_back(x);
		ans.push_back(y);
		return;
	}
	for(int i=0;i<N;i++){
		if(used[i])continue;
		if(((x>>i)&1)==((y>>i)&1))continue;
		used[i] = true;
		int u0 = x;
		int u1;
		int v1 = y;
		int v0;
		for(int j=0;j<N;j++){
			if(used[j])continue;
			u1 = x ^ (1<<j);
			v0 = u1 ^ (1<<i);
			break;
		}
		dfs(u0,u1,used);
		dfs(v0,v1,used);
		break;
	}
}



