#include <bits/stdc++.h>
using namespace std;

queue<unsigned int> dat[30];

unsigned int bit_cnt(unsigned int n){
    unsigned int ans = 0;
    while(n > 0){
        ans += (n % 2);
        n /= 2;
    }

    return ans;
}

signed main(){
    unsigned int n, a, b;
    cin >> n >> a >> b;

    if(bit_cnt(a) % 2 == bit_cnt(b) % 2){
        cout << "NO" << endl;
        return 0;
    }

    for(int i = 0;i < (1 << n);i++){
        if(i != a && i != b){
            dat[bit_cnt(i)].push(i);
        }
    }

    queue<unsigned int> fi;
    stack<unsigned int> se;

    bool fip = false;
    bool sep = false;
    int ficnt = bit_cnt(a);
    int secnt = bit_cnt(b);

    fi.push(a);
    se.push(b);
    for(int i = 0;i < (1 << n)-2;i++){
        if(i % 2 == 0){
            if(fip){
                if(ficnt+1 > n || dat[ficnt+1].empty()){
                    fip = false;
                    ficnt--;
                }else{
                    ficnt++;
                }
            }else{
                if(ficnt-1 < 0 || dat[ficnt-1].empty()){
                    fip = true;
                    ficnt++;
                }else{
                    ficnt--;
                }
            }

            fi.push(dat[ficnt].front());
            dat[ficnt].pop();

        }else{
            if(sep){
                if(secnt+1 > n || dat[secnt+1].empty()){
                    sep = false;
                    secnt--;
                }else{
                    secnt++;
                }
            }else{
                if(secnt-1 < 0 || dat[secnt-1].empty()){
                    sep = true;
                    secnt++;
                }else{
                    secnt--;
                }
            }

            se.push(dat[secnt].front());
            dat[secnt].pop();
        }
    }

    vector<unsigned int> vec;

    while(!fi.empty()){
        vec.push_back(fi.front());
        fi.pop();

    }

    while(!se.empty()){
        vec.push_back(se.top());
        se.pop();
    }

    cout << "YES" << endl;

    for(int i = 0;i < vec.size();i++){
        cout << vec[i];
        if(i != vec.size() -1){
            cout << " ";
        }else{
            cout << endl;
        }
    }

    return 0;
}

