int main() {
    int n, a, b; cin >> n >> a >> b;
    if(__builtin_popcount(a) % 2 == __builtin_popcount(b)) {
        cout << "NO" << endl;
    } else {
        vector<vector<int>> nCr(20, vector<int>(20));
        for(int i = 0; i < 20; ++i) {
            for(int j = 0; j <= i; ++j) {
                if(i == j || j == 0) nCr[i][j] = 1;
                else                 nCr[i][j] = nCr[i - 1][j] + nCr[i - 1][j - 1];
            }
        }
        int sum = -1;
        vector<int> ans = {a};
        vector<int> cnt(n);
        vector<bool> used(1 << n);
        used[a] = true;
        for(int i = 0; i <= n; ++i) {
            cnt[i] = nCr[n][i];
            sum += cnt[i];
        }
        cnt[__builtin_popcount(a)] -= 1;
        cnt[__builtin_popcount(b)] -= 1;
        while((int)ans.size() != (1 << n)) {
            const int cur = ans.back();
            bool found = false;
            if(cur == 0 || cur == (1 << n) - 1) {
                for(int i = 0; i < n; ++i) {
                    const int nv = cur ^ (1 << i);
                    if(used[nv]) continue;
                    if(nv == b) {
                        if(sum == 1) {
                            ans.push_back(b);
                            found = true;
                            break;
                        }
                        continue;
                    } else {
                        ans.push_back(nv);
                        used[nv] = true;
                        sum -= 1;
                        cnt[(cur == 0 ? 1 : n - 2)] -= 1;
                        found = true;
                        break;
                    }
                }
            } else {
                const int cpcnt = __builtin_popcount(cur);
                if(cnt[cpcnt - 1] <= cnt[cpcnt + 1]) { // nxt upper
                    for(int i = 0; i < n && (int)ans.size() != (1 << n); ++i) {
                        const int nv = cur ^ (1 << i);
                        if(used[nv] || __builtin_popcount(nv) != cpcnt + 1) continue;
                        if(nv == b) {
                            if(sum == 1) {
                                ans.push_back(b);
                                found = true;
                                break;
                            }
                            continue;
                        } else {
                            ans.push_back(nv);
                            used[nv] = true;
                            sum -= 1;
                            cnt[cpcnt + 1] -= 1;
                            found = true;
                            break;
                        }
                    }
                }
                if(!found) {
                    for(int i = 0; i < n; ++i) {
                        const int nv = cur ^ (1 << i);
                        if(used[nv] || __builtin_popcount(nv) != cpcnt - 1) continue;
                        if(nv == b) {
                            if(sum == 1) {
                                ans.push_back(b);
                                found = true;
                                break;
                            }
                            continue;
                        } else {
                            ans.push_back(nv);
                            used[nv] = true;
                            sum -= 1;
                            cnt[cpcnt - 1] -= 1;
                            found = true;
                            break;
                        }
                    }
                }
            }
            if(!found) {
                break; // Wrong Answer
            }
        }

        //cout << "debug: " << endl;
