vector<int>solve(int mask,int st,int fin,int len){
	if(len==1)return vector<int>{st,fin};
	int pos=-1;
	rep(i,n)if((mask>>i)&1)if(((st>>i)&1)!=((fin>>i)&1))pos=i;
