vector<ll> graycode(int k) {
	vector<ll> res;
	for (ll v = 0LL; v < (1LL << k); ++v)
		res.push_back(v ^ (v >> 1));
	return res;
}

int h, w;
vector<ll> line, colum; // カルノーマップ
// 0からtまでの経路
vector<pair<ll, ll>> route(pair<ll, ll> t) {
	assert((t.first + t.second) % 2);
	ll x = t.second, y = t.first;
	vector<pair<ll, ll>> res;
	if (x % 2) {
		for (ll xx = 0; xx < x; ++xx)
			for (ll yy = (xx % 2) ? colum.size() - 1 : 0; yy >= 0 && yy < colum.size(); yy += (xx % 2) ? -1 : 1)
				res.emplace_back(yy, xx);
		for (ll yy = colum.size() - 1; yy > y; --yy)
			for (ll xx = (yy % 2) ? x : line.size() - 1; xx >= x && xx < line.size(); xx += (yy % 2) ? 1 : -1)
				res.emplace_back(yy, xx);
		for (ll xx = line.size() - 1; xx >= x; --xx)
			for (ll yy = (xx % 2) ? y : 0; yy >= 0 && yy <= y; yy += (xx % 2) ? -1 : 1)
				res.emplace_back(yy, xx);
	}
	else {
		for (ll yy = 0; yy < y; ++yy)
			for (ll xx = (yy % 2) ? line.size() - 1 : 0; xx >= 0 && xx < line.size(); xx += (yy % 2) ? -1 : 1)
				res.emplace_back(yy, xx);
		for (ll xx = line.size() - 1; xx > x; --xx)
			for (ll yy = (xx % 2) ? y : colum.size() - 1; yy >= y && yy < colum.size(); yy += (xx % 2) ? 1 : -1)
				res.emplace_back(yy, xx);
		for (ll yy = colum.size() - 1; yy >= y; --yy)
			for (ll xx = (yy % 2) ? x : 0; xx >= 0 && xx <= x; xx += (yy % 2) ? -1 : 1)
				res.emplace_back(yy, xx);
	}
	return res;
}
// cの指す値を取得
ll number(pair<ll, ll> c) {
	return ((colum[c.first] << w) | line[c.second]);
}

signed main() {
	int n; ll a, b;
	cin >> n >> a >> b;
	if (n == 1) {
		if (a == b)	cout << "NO" << endl;
		else cout << a << " " << b;
	}
	else if (bitcount(a) % 2 == bitcount(b) % 2) {
		cout << "NO" << endl;
	}
	else {
		// カルノーマップを生成
		h = (n + 1) / 2; w = n / 2;
		line = graycode(w); colum = graycode(h);
		// a^bの座標を求める
		pair<ll, ll> c = { -1LL,-1LL };
		for (ll i = 0; i < (1LL << h); ++i) {
			for (ll j = 0; j < (1LL << w); ++j) {
				if (number({ i,j }) == (a ^ b)) c = { i,j };
			}
		}
		// 0からa^bのルートを求める
		vector<pair<ll, ll>> r = route(c);
		// 答えの出力
		cout << "YES" << endl;
		for (auto p : r)
			cout << (a ^ number(p)) << " ";
		cout << endl;
	}
	return 0;
}

