int n, A, B;

int del(int x, int p) {
  int d = x & (1 << p) - 1;
  int u = x & (1 << 20) - (1 << p + 1);
  return (u >> 1) + d;  
}

int ins(int x, int p, int v) {
  int d = x & (1 << p) - 1;
  int u = x & (1 << 20) - (1 << p);
  return (u << 1) + v + d;
}

vector<int> solve(int n, int a, int b) {
  if (n == 1) {
    vector<int> res;
    res.push_back(a);
    res.push_back(b);
    return res;
  }
  int p = 0;
  for (; (a & (1 << p)) == (b & (1 << p)); p++);
  int x = del(a, p), y = del(b, p), z = x ^ 1;
  vector<int> resl = solve(n - 1, x, z);
  vector<int> resr = solve(n - 1, z, y);
  vector<int> res;
  for (int i = 0; i < (1 << (n - 1)); i++) res.push_back(ins(resl[i], p, a & (1 << p)));
  for (int i = 0; i < (1 << (n - 1)); i++) res.push_back(ins(resr[i], p, b & (1 << p)));
  return res;
}

int main() {
  cin >> n >> A >> B;
  if (__builtin_popcount(A ^ B) % 2 == 0) {
    puts("NO");
    return 0;
  }
  puts("YES");
  vector<int> ans = solve(n, A, B);
  for (int i = 0; i < (1 << n); i++) {
    printf("%d ", ans[i]);
  }
  puts("");
  return 0;
}

