        if(a&(1<<i))na^=1<<(i-1);
        if(b&(1<<i))nb^=1<<(i-1);
    }
    auto p = solve(n-1,na,na^1);
    auto q = solve(n-1,na^1,nb);
    vector<int>res(1<<n);
    for(int i = 0; i < (1<<(n-1))-1; i++){
        for(int j = 0; j < t; j++){
            res[i] ^= (p[i]>>j&1)<<j;
        }
        res[i] ^= (a>>t&1)<<t;
        for(int j = t + 1 ; j < n; j++){
            res[i] ^= (p[i]>>(j-1)&1)<<j;
        }
    }
    for(int i = 1<<(n-1); i < 1<<n; i++){
        for(int j = 0; j < t; j++){
            res[i] ^= (q[i-(1<<(n-1))]>>j&1)<<j;
        }
        res[i] ^= (b>>t&1)<<t;
        for(int j = t + 1 ; j < n; j++){
            res[i] ^= (p[i-(1<<(n-1))]>>(j-1)&1)<<j;
        }
    }
    return res;
}
