using namespace std;
typedef long long ll;

int n;

int popcnt(int m) {
	int cnt = 0;
	for (int i = 0; i < n; i++) cnt += (m >> i) & 1;
	return cnt;
}

string makebits(int m) {
	string ret;
	for (int i = 0; i < n; i++) ret += (m >> i) & 1 ? '1' : '0';
	reverse(ret.begin(), ret.end());
	return ret;
}

int dec(string s) {
	int ret = 0;
	for (int i = 0; i < n; i++) {
		ret *= 2;
		ret += s[i] == '1';
	}
	return ret;
}

void makeord(const string &s, const string &t, vector<string> &ord) {
	if (s.size() == 1) {
		ord.push_back(s);
		ord.push_back(t);
		return;
	}
	int m = s.size(), pos = 0;
	for (int i = 0; i < m; i++) {
		if (s[i] != t[i]) {
			pos = i;
			break;
		}
	}
	string snxt = s.substr(0, pos) + s.substr(pos + 1, m);
	string tnxt = t.substr(0, pos) + t.substr(pos + 1, m);
	string mid = snxt;
	if (snxt[0] == tnxt[0]) mid[0] = snxt[0] == '0' ? '1' : '0';
	else mid[1] = snxt[1] == '0' ? '1' : '0';
	vector<string> fst, scd;
	makeord(snxt, mid, fst);
	makeord(mid, tnxt, scd);

	for (string v : fst) {
		ord.push_back(v.substr(0, pos) + string(1, s[pos]) + v.substr(pos, m));
	}
	for (string v : scd) {
		ord.push_back(v.substr(0, pos) + string(1, t[pos]) + v.substr(pos, m));
	}
}

int main() {
	int a, b; cin >> n >> a >> b;
	if (popcnt(a) % 2 == popcnt(b) % 2) {
		cout << "NO" << endl;
		return 0;
	}
	cout << "YES" << endl;
	string s = makebits(a), t = makebits(b);
	vector<string> ans;
	makeord(s, t, ans);
	for (int i = 0; i < (int)ans.size(); i++) {
		cout << dec(ans[i]) << " \n"[i == (int)ans.size() - 1];
	}
	return 0;
}

