    vector<int> G(150000);
    for (int i = 0; i < pow(2, N); i++) {
        G[i] = i ^ (i >> 1);
    }
    bitset<17> AB_XOR(A ^ B);
    int cnt1 = 0;
    int bit1 = 0;
    for (int i = 0; i < 17; i++) {
        if (AB_XOR[i]) {
            cnt1++;
            bit1 = i;
        }
