        cout << "YES" << endl;
        for (int i = 0; i < pow(2, N); i++) {
            int tmp = G[i] >> (N - bit1);
            G[i] *= pow(2, bit1);
            G[i] += tmp;
            tmp = pow(2, N) - 1;
			G[i] = G[i] & tmp;
        }

        int flag = 0;
        int str = 0;
        for (int i = 1; i < pow(2, N); i++) {
            if (G[i - 1] == A && G[i] == B) {
                flag = 1;
                str = i - 1;
            }
