vi gray_code(int dig, int start, int end) {
  int n = (1 << dig);
  int sz = end - start;
  vi ret(sz);
  rep (i, sz) {
    int j = start + i;
    ret[i] = (j ^ (j >> 1));
  }
  return ret;
}

vi gc1 = {0, 1};
vi gc2 = {0, 1, 3, 2};

int main() {
  int n, a, b;
  scan(n, a, b);
  bool swapped = false;
  if (a > b) {
    swap(a, b);
    swapped = true;
  }
  m = (1 << n);
  ans.assign(m, 0);
  ans[0] = a;
  ans[m-1] = b;
  int diff = __builtin_popcount(a ^ b);
  if (diff % 2 == 0) {
    no();
  }
  vi codes;
  if (diff == 1) {
    codes = {0, 1};
  } else {
    function<vi(int)> lam = [&lam](int d) {
      if (d == 3) {
        vi ret = {0, 1, 3, 2, 6, 4, 5, 7};
        return ret;
      }
      int d2 = d - 2;
      auto base = lam(d2);
      int n_ = (1 << d);
      vi ret(n_);
      rep (i, (1 << d2)) {
        rep (j, 2) {
          ret[i*2 + j] = base[i] + (gc1[(i + j) % 2] << d2);
        }
      }
      auto later = gray_code(d, 0, n_/2);
      reverse(all(later));
      rep (i, n_/2) {
        later[i] ^= ((1 << d) - 1);
      }
      copy(all(later), begin(ret) + n_ / 2);
      return ret;
    };
    codes = lam(diff);
  }
  debug(codes);

  int nb = (1 << (n - diff));
  vi gcn(nb);
  rep (i, nb) {
    gcn[i] = (i ^ (i >> 1));
  }
  vi ans0 = ans;

  rep (i, (1 << diff)) {
    rep (j, nb) {
      ans0[i*nb + j] = codes[i] + (gcn[(i + j) % nb] << diff);
    }
  }
  debug(ans0);
  int target = (a ^ b);
  vvi swaps(2);
  rep (i, n) {
    int j = (ans0[m-1] >> i);
    int k = (target >> i);
    if (j == k) {
      continue;
    }
    if (j == 1) {
      swaps[0].push_back(i);
    }
    if (k == 1) {
      swaps[1].push_back(i);
    }
  }
  assert(swaps[0].size() == swaps[1].size());
  int sz = swaps[0].size();
  debug(swaps);

  vi dig(n, 0);
  rep (i, m) {
    rep (j, n) {
      dig[j] = ((ans0[i] >> j) & 1);
    }
    debug(dig);
    rep (j, sz) {
      swap(dig[swaps[0][j]], dig[swaps[1][j]]);
    }
    ans[i] = 0;
    rep (j, n) {
      ans[i] += (1 << j) * dig[j];
    }
  }
  int flip = a ^ ans[0];
  rep (i, m) {
    ans[i] ^= flip;
  }
  if (swapped) {
    reverse(all(ans));
  }
  yes();

  return 0;
}

