vector<int> f(int nbit, int b) {
    if (nbit == 1) {
        return vector<int>{ 0, 1 };
    }
    int x = ((b ^ (b - 1)) + 1) >> 1;
    int overx = ((1 << nbit) - 1) ^ (x | (x - 1));
    int c = (b & (x - 1)) | ((b & overx) >> 1);
    int m = 1;

    vector<int> p = f(nbit - 1, m);
    vector<int> q = f(nbit - 1, c ^ m);
    for (int& a : p) {
        a = (a & (x - 1)) | ((a & (overx >> 1)) << 1);
    }
    for (int a : q) {
        a ^= m;
        a = (a & (x - 1)) | ((a & (overx >> 1)) << 1) | x;
        p.push_back(a);
    }
    return p;
}

