int getsw(int x, int a, int b)
{
    int t1 = (x >> a) & 1;
    int t2 = (x >> b) & 1;
    x -= (t1 << a);
    x -= (t2 << b);
    x += (t2 << a);
    x += (t1 << b);
    return x;
}

vector<int> func(int n, int x)
{
    if (n == 1)
        return {0, x};
    int t = 0;
    for (int i = 0; i < n; i++)
        if ((x >> i) & 1)
        {
            t = i;
            break;
        }
    int xn = getsw(x, t, n - 1);
    xn ^= (1 << (n - 1));
    vector<int> p1 = func(n - 1, 1);
    vector<int> p2 = func(n - 1, xn ^ 1);
    for (int &u : p2)
        u ^= 1;
    for (int &u : p2)
        u = getsw(u + (1 << (n - 1)), t, n - 1);
    for (int &u : p1)
        u = getsw(u, n - 1, t);
    for (int u : p2)
        p1.push_back(u);
    return p1;
}

