vi calc_perm(ll a, ll b, ll n) {
  // cerr << a << " " << b << endl;
  vi a_zero, a_one, b_one, b_zero;
  rep(i, n) {
    if ((a >> i) & 1LL) {
      a_one.push_back(i);
    } else {
      a_zero.push_back(i);
    }
  }
  rep(i, n) {
    if ((b >> i) & 1LL) {
      b_one.push_back(i);
    } else {
      b_zero.push_back(i);
    }
  }
  assert(a_zero.size() == b_zero.size());
  assert(a_one.size() == b_one.size());

  vi bit_perm(n);
  rep (i, a_zero.size()) {
    bit_perm[a_zero[i]] = b_zero[i];
  }
  rep (i, a_one.size()) {
    bit_perm[a_one[i]] = b_one[i];
  }
  return bit_perm;
}

ll apply_perm(ll x, const vi& bit_perm) {
  ll ans = 0;
  rep(i, bit_perm.size()) {
    ll b = (x >> i) & 1LL;
    ans |= b << bit_perm[i];
  }
  return ans;
}

vl solve_bit(ll n, ll last);

vl solve_count(ll n, ll k) {
  assert(k <= n and k % 2 == 1);
  if (n == 1) {
    return {0, 1};
  }

  vl ans(1LL << n);
  if (k == 1) {
    ll hn = 1LL << (n-1);
    vl half = solve_count(n - 1, 1);
    rep(i, hn) {
      ans[i] = half[i];
    }
    rep(i, 1LL << (n-1)) {
      ans[i + hn] = half[hn - 1 - i] | hn;
    }
  } else {
    ll hn = 1LL << (n-1);
    vl half1 = solve_count(n - 1, 1);
    rep(i, hn) {
      ans[i] = half1[i];
    }

    ll bit = ((1LL << (k-1)) - 1LL) ^ half1.back();
    vl half2 = solve_bit(n - 1, bit);
    rep(i, hn) {
      ans[i + hn] = (half2[i] ^ half1.back()) | hn;
    }
  }
  return ans;
}

vl solve_bit(ll n, ll last) {
  ll N = 1LL << n;
  ll k = __builtin_popcountll(last);
  vl perm = solve_count(n, k);
  /*
  for (ll a : perm) {
    cerr << a << " ";
  }
  cerr << endl;
  */

  vi bit_perm = calc_perm(perm.back(), last, n);

  vl ans(N);
  rep(i, N) {
    ans[i] = apply_perm(perm[i], bit_perm);
  }

  return ans;
}

