void dfs(ll s, ll t, ll m) {
    if (pcnt(m) == n - 1) {
        ans.pb(s);
        ans.pb(t);
        return;
    }
    //s -> tで利用する必要がある軸
    ll x = s ^t;
    //bは増えた物の内、低軸
    //tへ行くうえで必ず必要
    ll b = x & -x;
    //mはこれまで切ってきた軸
    //b軸を切った
    m |= b;
    //miは残ってる軸
    ll mi = n1 ^m;
    //残ってる軸で最も下
    ll d = mi & -mi;
    //次はdへ行く
    mi -= d;
    //今行くものも含めて最も低次のもの
    ll e = mi & -mi;
    //移動先
    ll w = s ^d;
    if ((w ^ b) == t) w = s ^ e;
    dfs(s, w, m);
    dfs(w ^ b, t, m);
}

