typedef std::vector<int> V;

V solve(int a, int b, int S)
{
	V ans;
	if(S == 1)
	{
		ans.push_back(a);
		ans.push_back(b);
		return ans;
	}
	int id = -1, cnt = 0, c;
	for(int i = 0; i < S; i++)
	{
		if(((a >> i) & 1) != ((b >> i) & 1)) id = i;
		if((a >> i) & 1) cnt++;
	}

	int k = (a >> id) & 1;
	if(k) cnt--, a ^= 1 << id;
	else b ^= 1 << id;
	if(cnt & 1) c = 0;
	else c = 1;

	int A = a & ((1 << id) - 1);
	int _a = (a - A) >> 1;

	int B = b & ((1 << id) - 1);
	int _b = (b - B) >> 1;

	ans = solve(A + _a, c, S - 1);
	V cur = solve(c, B + _b, S - 1);

	int siz = ans.size();
	for(int i = 0; i < siz; i++)
	{
		int v = ans[i] & ((1 << id) - 1);
		ans[i] = ((ans[i] - v) << 1) + (k << id) + v;
	}

	siz = cur.size();
	for(int i = 0; i < siz; i++)
	{
		int v = cur[i] & ((1 << id) - 1);
		ans.push_back(((cur[i] - v) << 1) + ((k ^ 1) << id) + v);
	}

	return ans;
}

int main()
{
	int n, a, b; scanf("%d%d%d", &n, &a, &b);
	int cnt = 0;
	for(int i = 0; i < n; i++)
	{
		if(((a >> i) & 1) != ((b >> i) & 1)) cnt++;
	}
	if(!(cnt & 1)) return 0 * puts("NO");
	V ans = solve(a, b, n);
	int S = ans.size();
	puts("YES");
	for(int i = 0; i < S; i++) printf("%d ", ans[i]);
}

