void work(int l, int r, int t)
{
	if(l == r)
	{
		op[l] = t;
		return ;
	}
	int k = __builtin_ctz(t);
	int g = id[int(log2(r - l))];
	work(l, mid - 1, t ^ 1 << k ^ 1 << g);
	op[mid] = 1 << k;
	memcpy(op + mid + 1, op + l, sizeof (int) * (mid - l));
}
int main()
{
