	int x = a ^ b;
	memset(flag, true, sizeof flag);
	cnt = n;
	while(x)
	{
		int k = __builtin_ctz(x);
		id[cnt --] = k;
		x ^= 1 << k;
		flag[k] = false;
	}
	open(i, 0, n)
		if(flag[i])
			id[cnt --] = i;
