vector<int> work(int na, int nb, int dep, int totd ) {
	if (dep == n-1) return{na, nb};
	if (totd == 1) {
		int ta = na / 2;
		assert(ta == nb / 2);
		int ea = na % 2;
		int eb = nb % 2;
		auto r0 = work(ta, ta ^ 1, dep + 1, 1);
		auto r1 = work(ta ^ 1, ta, dep + 1, 1);
		vector<int> zr;
		//zr.push_back(na);
		for (auto x : r0) {
			zr.push_back(x * 2 + ea);
		}
		for (auto x : r1) {
			zr.push_back(x * 2 + eb);
		}
		//zr.push_back(nb);
		return move(zr);
	}

	int ta = na / 4;
	int tb = nb / 4;
	int ea = na % 4;

	auto r0 = work(ta, ta^1, dep + 2, 1);
	auto r1 = work(ta^1, tb^1, dep + 2, totd-2);
	auto r2 = work(tb^1, tb, dep + 2, 1);


	vector<int> zr;

	for (auto x : r0) {
		zr.push_back(x * 4 + ea );
	}
	for (auto x : r1) {
		zr.push_back(x * 4 + ea ^ 1);
	} 
	int i;
	for (i = 0; i < r2.size(); ++i)  {
		int x = r2[i];
		if (i > 0 && x & 1 != r2[i - 1] & 1) break;
		zr.push_back(x * 4 + ea ^ 3);
	}

	auto r3 = work(r2[i-1], r2[i-1], dep + 2, 1);
	for (auto x : r3) {
		zr.push_back(x * 4 + ea ^ 2);
	}

	for (; i < r2.size(); ++i) {
		int x = r2[i];
		zr.push_back(x * 4 + ea ^ 3);
	}
	return zr;
}

int getbit(int g, int t) {
	return (g >> t) & 1;
}

int swapback(int g, int t) {
	int a = getbit(g, t);
	int b = getbit(g, 0);
	if (a == b) return g;
	g = g ^ (1 << t);
	return g ^ 1;
}

