int rec1(int g) {
	int r0  = 0;
	int r1  = 0;
	Loop_r(i, n) {
		if (dif[i]) {
			r0= r0*2 + getbit(g, i);
		}
		else {
			r1 = r1 * 2 + getbit(g, i);
		}
	}
	return (r1 << totd) + r0;
}
int rec2(int g) {
	int nd = totd-1;
	int ns = n-1;
	int r = 0;
	Loop_r(i, n) {
		int x;
		if (dif[i]) {
			x = getbit(g, nd);
			--nd;
		}
		else {
			x = getbit(g, ns);
			--ns;
		}
		r = r * 2 + x;
	}
	return r;
}

