		else
			s = '0' + s;
		x /= 2;
	}
	while ((int)s.size() < sz)
		s = '0' + s;
	return s;
}
int dif(int x, int y) {
	string s = tob(x);
	string t = tob(y);
	int d = 0;
	for (int i = 0; i < sz; i++)
		if (s[i] != t[i])
			d++;
	return d;
}

