unsigned int BinaryToGray(unsigned int num)
{
    return num ^ (num >> 1);
}
unsigned int GrayToBinary(unsigned int num)
{
    unsigned int mask = num >> 1;
    while (mask != 0)
    {
        num = num ^ mask;
        mask = mask >> 1;
    }
    return num;
}
int lsb(int x) {
  x &= -x;
  int i = 0;
  while (x > 1) {
    x >>= 1;
    i += 1;
  }
  return i;
}
int swap_bits(int x, int i, int j) {
  int y = x & ~(1 << i) & ~(1 << j);
  return y | (((x >> i) & 1) << j) | (((x >> j) & 1) << i);
}
