bool check(int n, int a) {
    if (n == 1) return a == 1;
    if (a >= (1<<(n-1))) return !check(n-1, a^(1<<(n-1)));
    else return check(n-1, a);
}

vector<int> construct(int n, int a) {
    if (n == 1) return {a, a^1};
    if (a >= (1<<(n-1))) {
        int b = a ^ (1<<(n-1)) ^ 1;
        auto v1 = construct(n-1, b);
        for (int &x : v1) x ^= (1<<(n-1)) | 1;
        auto v2 = construct(n-1, 1);
        v1.insert(v1.end(), v2.begin(), v2.end());
        return v1;
    } else {
        auto v1 = construct(n-1, a);
        auto v2 = construct(n-1, *next(v1.rbegin()));
        for (int &x : v2) x ^= (1<<(n-1));
        v1.insert(v1.end()-1, v2.begin(), v2.end());
        return v1;
    }
}

