vi ans;

int popcount(int bits)
{
	bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
	bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
	bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
	bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
	return (bits & 0x0000ffff) + (bits >> 16 & 0x0000ffff);
}

void odd(int d, int add, bool rev)
{
	if (d > 3)
	{
		if (!rev)
		{
			// 000
			odd(d - 2, add, false);					 // 001
			ans.push_back((1 << (d - 1)) - 1 + add); // 011
			odd(d - 2, add + (1 << (d - 2)), true);  // 010
			ans.push_back((3 << (d - 2)) + add);	 // 110
			ans.push_back((2 << (d - 2)) + add);	 // 100
			odd(d - 2, add + (1 << (d - 1)), false); // 101
			ans.push_back((1 << d) - 1 + add);		 // 111
		}
		else
		{
			// 111
			ans.push_back((1 << d) - 1 - (1 << (d - 2)) + add); // 101
			odd(d - 2, add + (1 << (d - 1)), true);				// 100
			ans.push_back((3 << (d - 2)) + add);				// 110
			ans.push_back((1 << (d - 2)) + add);				// 010
			odd(d - 1, add + (1 << (d - 2)), false);			// 011
			ans.push_back((1 << (d - 2)) - 1 + add);			// 001
			odd(d - 2, add, true);								// 000
		}
	}
	else if (d == 3)
	{
		if (!rev)
		{
			ans.push_back(1 + add);
			ans.push_back(3 + add);
			ans.push_back(2 + add);
			ans.push_back(6 + add);
			ans.push_back(4 + add);
			ans.push_back(5 + add);
			ans.push_back(7 + add);
		}
		else
		{
			ans.push_back(5 + add);
			ans.push_back(4 + add);
			ans.push_back(6 + add);
			ans.push_back(2 + add);
			ans.push_back(3 + add);
			ans.push_back(1 + add);
			ans.push_back(0 + add);
		}
	}
	else if (d == 1)
	{
		if (!rev)
		{
			ans.push_back(1 + add);
		}
		else
		{
			ans.push_back(add);
		}
	}
}

void solve(int d, int od)
{
	vi grey(1 << d);
	grey[0] = 0;
	repr(i, 1, 1 << d)
	{
		int v = (1 << d) - i;
		grey[i] = v ^ (v >> 1);
	}
	ans.push_back(0);
	repr(i, 1, 1 << d)
	{
		if (((grey[i] ^ grey[i - 1]) & 1) == 0)
		{
			// 1桁目変化なし
			if (((grey[i]) & 1) == 0)
			{
				ans.push_back(grey[i] << (od - 1));
			}
			else
			{
				ans.push_back((grey[i] << (od - 1)) + (1 << (od - 1)) - 1);
			}
		}
		else
		{
			// 1桁目変化あり
			int add = ((grey[i] >> 1) << 1) << (od - 1);
			bool rev = ((grey[i] & 1) == 0);
			odd(od, add, rev);
		}
	}
}

int bit_change(int n, int a, int s, int trans)
{
	int ans = 0;
	int e = n, d = 0;
	rep(i, 20)
	{
		if ((trans & (1 << i)) == 0)
		{
			if ((s & (1 << e)) != 0)
			{
				ans += 1 << i;
			}
			e++;
			if (e > a)
				break;
		}
		else
		{
			if ((s & (1 << d)) != 0)
			{
				ans += 1 << i;
			}
			d++;
			if (d > n)
				break;
		}
	}
	return ans;
}

int main(void)
{
	int N, A, B;
	cin >> N >> A >> B;
	int C = A ^ B;
	if (popcount(C) % 2 == 0)
	{
		cout << "NO" << endl;
		return 0;
	}
	cout << "YES" << endl;
	ans.reserve(1 << N);

	int od = popcount(C);
	solve(N - od + 1, od);
	/*
	cout << C << endl;
	for (auto i : ans)
	{
		cout << bitset<8>(bit_change(od, N, i, C) ^ A) << endl;
	}
	*/
	rep(i, ans.size())
	{
		if (i != ans.size() - 1)
		{
			printf("%d ", bit_change(od, N, ans[i], C) ^ A);
		}
		else
		{
			printf("%d\n", bit_change(od, N, ans[i], C) ^ A);
		}
	}

