template<int mod>
struct ModInt{
    int x;
    ModInt():x(0){}
    ModInt(long long y):x(y>=0?y%mod:(mod-(-y)%mod)%mod){}
    ModInt &operator+=(const ModInt &p){
        if((x+=p.x)>=mod)x-=mod;
        return *this;
    }
    ModInt &operator-=(const ModInt &p){
        if((x+=mod-p.x)>=mod)x-=mod;
        return *this;
    }
    ModInt &operator*=(const ModInt &p){
        x=(int)(1LL*x*p.x%mod);
        return *this;
    }
    ModInt &operator/=(const ModInt &p){
        *this*=p.inverse();
        return *this;
    }
    ModInt operator-()const{return ModInt(-x);}
    ModInt operator+(const ModInt &p)const{return ModInt(*this)+=p;}
    ModInt operator-(const ModInt &p)const{return ModInt(*this)-=p;}
    ModInt operator*(const ModInt &p)const{return ModInt(*this)*=p;}
    ModInt operator/(const ModInt &p)const{return ModInt(*this)/=p;}
    bool operator==(const ModInt &p)const{return x==p.x;}
    bool operator!=(const ModInt &p)const{return x!=p.x;}
    explicit operator int() const { return x; }                           // added by QCFium
    ModInt operator=(const int p) {x = p; return ModInt(*this);} // added by QCFium
    ModInt inverse()const{
        int a=x,b=mod,u=1,v=0,t;
        while(b>0){
            t=a/b;
            a-=t*b;
            swap(a,b);
            u-=t*v;
            swap(u,v);
        }
        return ModInt(u);
    }
    friend ostream &operator<<(ostream &os,const ModInt<mod> &p){
        return os<<p.x;
    }
    friend istream &operator>>(istream &is,ModInt<mod> &a){
        long long x;
        is>>x;
        a=ModInt<mod>(x);
        return (is);
    }
};
typedef ModInt<MOD> mint;

mint mpow(s64 num, s64 times) { // O(log(times))
    mint next = num%MOD;
	mint res = 1;
	while (times) {
		if (times%2)
            res *= next;
		next *= next;
		times /= 2;
	}
	return res;
}

struct MComb {
    vector<mint> fact;
    vector<mint> inversed;
    MComb(int n) { // O(n+log(mod))
        fact = vector<mint>(n+1,1);
        UPTO(i,1,n) fact[i] = fact[i-1]*mint(i);
        inversed = vector<mint>(n+1);
        inversed[n] = mpow((int)fact[n], MOD-2);
        DOWN(i,n) inversed[i]=inversed[i+1]*mint(i+1);
    }

    mint ncr(int n, int r) {
        return (fact[n] * inversed[r] * inversed[n-r]);
    }

    mint npr(int n, int r) {
        return (fact[n] * inversed[n-r]);
    }

    mint nhr(int n, int r) {
        assert(n+r-1 < (int)fact.size());
        return ncr(n+r-1, r);
    }
};

vector<int> stdpath = { 0 };

std::vector<int> solve(int level, int x) {
	if (!level) {
		assert(!x);
		return {0};
	}
	if (level == 1) {
		assert(x == 1);
		return {0,1};
	}
	assert(x);
	if (x < (1 << (level-1))) {
		auto left = solve(level-1, x);
		if (x == left[1]) {
			int last = left.back();
			std::vector<int> res = {0};
			std::vector<int> tmp = solve(level-1, last);
			for (auto i : tmp) {
				res.push_back(i + (1<<(level-1)));
			}
			reverse(all(left));
			FOR(i,(1<<(level-1)) - 1) res.push_back(left[i]);
			return res;
		}
		// fly from 0, land to 1
		auto right = solve(level-1, left[1]);
		std::vector<int> res = {0};
		for (auto i : right) res.push_back(i + (1<<(level-1)));
		UPTO(i,1,(1<<(level-1))-1) res.push_back(left[i]);
		return res;
	} else if (x == (1 << (level-1))) {
		vector<int> res(stdpath.begin(), stdpath.begin() + (1<<level));
		return res;
	} else {
		std::vector<int> res(stdpath.begin(), stdpath.begin() + (1<<(level-1)));
		int last = res.back();
		auto right = solve(level-1, (x - (1 << (level-1))) ^ last);
		for (auto i : right) res.push_back((i ^ last) + (1 << (level-1)));
		return res;
	}
}

