    n ^= (1 << j);
}


vector<int> dfs(int n, int a, int b) 
{
    if (n == 1) 
    {
        return {a, b};
    }
    b ^= a;
    int last;
    if (b)
    {
        last = 31 - __builtin_clz(b);
    }
    else
    {
        last = n - 1;
    }
    change(b, n - 1, last);
    int mask = (1 << (n - 1)) - 1;
    auto first = dfs(n - 1, 0, 1);
    auto second = dfs(n - 1, 1, b & mask);
    vector<int> ans;
    for (auto x : first) 
    {
        ans.push_back(x);
    }
    for (auto x : second) 
    {
        ans.push_back(x | (1 << (n - 1)));
    }
    for (auto& x : ans) 
    {
        change(x, n - 1, last);
    }
    for (auto& x : ans) 
    {
        x ^= a;
    }
    return ans;
}

