using namespace std;

class CDifferBy1Bit {

	void solve(io::input_reader &in, io::output_writer &out) {
		int n, a, b;
		in.read(n, a, b);
		int x = a ^b;
		if (!x || (x & (x - 1))) {
			out << "NO";
			return;
		}
		int dI = 0;
		while (!((1 << dI) & x)) dI++;
		vector<int> res(1);
		res[0] = a;
		vector<int> i_s;
		fori(i, n) if (i != dI) i_s.push_back(i);
		i_s.push_back(dI);
		for (int i : i_s) {
			int s = res.size();
			repr(j, s - 1, 0) {
				res.push_back(res[j] ^ (1 << i));
			}
		}

		out << res;
	}

public:
	void solve(std::istream &in, std::ostream &out) {
		io::input_reader input(in);
		io::output_writer output(out);
		solve(input, output);
	}
};


int main() {
	std::ios_base::sync_with_stdio(false), cin.tie(0);
	CDifferBy1Bit solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

