}

vector<int> ans;
bool if_exists = true;

void Solve_simple(int a, int change, int cur_change, int change_count){
    if (change_count == 1){
        ans.push_back(a);
        ans.push_back(Change_bit(a, cur_change));
        return;
    }
    change_count--;
    int old_change = cur_change;
    change = Change_bit(change, cur_change);
    cur_change = MSB(change, cur_change);
//    while (!Get_bit(change, cur_change))
//        cur_change++;
    Solve_simple(a, change, cur_change, change_count);
    a = Change_bit(ans.back(), old_change);
    Solve_simple(a, change, cur_change, change_count);
}

void Solve(int n, int a, int b){
    int change = (1 << n) - 1, change_count = n - 1;
    while (change_count > 0){
        if (a == b){
            if_exists = false;
            return;
        }
        FOR (i, n)
            if (Get_bit(change, i) && Get_bit(a, i) != Get_bit(b, i)){
                change = Change_bit(change, i);
                Solve_simple(a, change, MSB(change, 0), change_count);
                a = Change_bit(ans.back(), i);
                change_count--;
                break;
            }
    }
    if (a == b){
        if_exists = false;
        return;
    }
    ans.push_back(a);
    ans.push_back(b);
}

