    }
  }
  int fa=0,fb=0;//a,bからxビット目を除いた値
  REP(i,n){
    if(i==x)continue;
    if(i<x){
      fa += ((a>>i)%2)<<i;
      fb += ((b>>i)%2)<<i;
    }else{
      fa += ((a>>i)%2)<<(i-1);
