vector < string > f(string a,string b) {
    if (a.length() == 1)
        return vector < string > {a,b};
    int cnt = -1;
    const int sz = a.length();
    for (int i = 0;i < sz;++i)
        if (a[i] != b[i])
            cnt = i;
    string a0 = a.substr(0,cnt) + a.substr(cnt + 1,sz - cnt - 1);
    string b0 = b.substr(0,cnt) + b.substr(cnt + 1,sz - cnt - 1);
    string b1 = b0;
    b1[0] = '1' + '0' - b1[0];
    auto A = f(a0,b1);
    auto B = f(b1,b0);
    vector < string > answer;
    for (auto it : A)
        answer.pb(it);
    for (auto it : B)
        answer.pb(it);
    for (int i = 0;i < (1 << sz);++i) {
        answer[i] = answer[i].substr(0,cnt) + (i < (1 << (sz - 1)) ? a[cnt] : b[cnt]) + answer[i].substr(cnt,sz - 1 - cnt);
    }
    return answer;
}
