vector<int> solve(int a, int b, int n, int mask){
  if(n == 1) return {a,b};

  int x,y,z;

  REP(i,n){
    if((mask&(1<<i)) and (a&(1<<i)) != (b&(1<<i))){
      x = a^(a&(1<<i));
      y = b^(b&(1<<i));

      int new_mask = mask^(1<<i);
      REP(j,n){
	if(new_mask&(1<<j)) z = a^(1<<j);
      }

      auto ret1 = solve(x,z,n-1,new_mask);
      auto ret2 = solve(z,y,n-1,new_mask);

      for(auto &p : ret1) p |= (a&(1<<i));
      for(auto &p : ret2){
	p |= (b&(1<<i));
	ret1.push_back(p);
      }

      return ret1;
    }
  }
}

