vector<ll> ans, rem, rem2;
void solve(ll a, ll b, ll n){
	if(n == 1){
		ans.pb(a);
		ans.pb(b);
		return ;
	}
	ll dif = a ^ b;
	ll bit;
	for(int i = 0; i < n; i++){
		if(dif & bt[rem[i]]) bit = rem[i];
