            ret.push_back("1");
            return ret;
        }
        if (n <= 0) {
            ret.push_back("0");
            return ret;
        }

        vector<string> post = getGray(n - 1);
        bool direction = true;
        for (vector<string>::iterator itr = post.begin(); itr != post.end();
             itr++) {
            if (direction) {
                ret.push_back(*itr + "0");
                ret.push_back(*itr + "1");
                direction = false;
            } else {
                ret.push_back(*itr + "1");
                ret.push_back(*itr + "0");
                direction = true;
            }
        }
        return ret;
    }
};

string tobin(int x) {
    string res;
    while (x) {
        if (x & 1)
            res += "1";
        else
            res += '0';
        x >>= 1;
    }
    int len = res.length();
    for (int i = 0; i < n - len; i++) {
        res += '0';
    }
    reverse(res.begin(), res.end());
    return res;
}

int toint(const string &x) {
    int res = 0;
    for (auto s : x) {
        res = res * 2 + s - '0';
    }
    return res;
}
