    if (x % 2 == 0) {
        cout << "NO\n";
        return;
    }
    int up = 1 << n;
    res.resize(up);

    cout << "YES\n";
    solve(n, a, b, 0, up);
    for (int i = 0; i < up; ++i) {

        cout << res[i] << " ";
    }
    cout << endl;




}

