{
	if(count(mask) == n - 1)
	{
		printf("%d %d ", a, b);
		return;
	}

	int i, j;
	FOR(i, 0, n)
		if ((a & (1 << i)) != (b & (1 << i)))
			FOR(j, 0, n)
				if(j != i && (mask & (1 << j)) == 0)
				{
					f(n, a, a ^ (1 << j), mask ^ (1 << i));
					f(n, a ^ (1 << i) ^ (1 << j), b, mask ^ (1 << i));
					return;
				}

	throw 0;
}

