    function<bool(i64,i64,i64)> dfs=[&](i64 i,i64 prev,i64 pos){
        ans[i]=pos;
        visit[pos]=true;

        if(i==((1<<N)-1)){
            assert(pos==B);
            return true;
        }

        rep(j,0,N){
            if(j==prev) continue;

            i64 np=pos^(1<<j);
            if(visit[np]) continue;
            if(np==B and (i+1!=((1<<N)-1))){
