void trans(int c) {
    int b1 = (c&(1<<p))>0;
    int b2 = (c&(1<<(N-1)))>0;
    if (b1 != b2) c^=((1<<p)|(1<<(N-1)));

    cout << (c^A) << ' ';
}

void print(int s, int b) {
    if (s == 1) {
        trans(b);
        trans(b^1);
        return;
    }

    print(s-1, b);
    print(s-1, b^(3<<(s-2)));
}

