void ch(int k, int i) {
    int x = xx[k].back();
    x ^= (1LL<<s[k][i]);
    xx[k].push_back(x);
}

void rec0(int m = 0) {
    if (m == int(s[0].size())-1) { ch(0,m); return; }
    rec0(m+2);
    ch(0,m+1);
    rec0(m+2);
    ch(0,m);
    ch(0,m+1);
    rec0(m+2);
    ch(0,m+1);
}

void rec1(int m = 0) {
    if (s[1].empty()) return;
    if (m == int(s[1].size())-1) { ch(1,m); return; }
    rec1(m+1);
    ch(1,m);
    rec1(m+1);
}
