int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, oa, ob;

    cin >> n >> oa >> ob;

    int a = 0;
    int b = 0;

    for (int i = 0; i < n; i++)
    {
        if ((oa & (1 << i)) != (ob & 1 << i))
            b += 1 << i;
    }

    int dcnt = 0;

    for (int i = 0; i < n; i++)
        dcnt += (a & (1 << i)) != (b & (1 << i));

    if (dcnt % 2 == 0)
    {
        cout << "NO" << endl;
        return 0;
    }

    V p;
    V q;

    q.push_back(a);

    bool used[1 << 18];

    for (int i = 0; i < (1 << n); i++)
    {
        used[i] = false;
        if (i == a)
            continue;
        if (i == b)
            continue;

        int cnt = 0;
        for (int j = 0; j < n; j++)
            if (i & (1 << j))
                cnt++;

        if (cnt % 2)
            p.push_back(i);
    }

    p.push_back(b);

    used[a] = true;

    for (int i = 0; i < p.size() - 1; i++)
    {
        V v;
        for (int j = 0; j < n; j++)
        {
            if ((p[i] & (1 << j)) != (p[i + 1] & (1 << j)))
                v.push_back(j);
        }

        int tmp = p[i] ^ (1 << v[0]);

        if (used[tmp])
        {
            tmp = p[i] ^ (1 << v[1]);
        }

        q.push_back(tmp);

        used[tmp] = true;
    }

    for (int i = 0; i < p.size(); i++)
    {
        for (int j = 0; j < n; j++)
        {
            if (((oa & (1 << j)) == true) != ((a & (1 << j)) == true))
            {
                p[i] ^= (1 << j);
                q[i] ^= (1 << j);
            }
        }
    }

    cout << "YES" << endl;
    for (int i = 0; i < p.size(); i++)
    {
        cout << q[i] << " " << p[i];
        if (i < p.size() - 1)
            cout << " ";
    }
    cout << endl;

    return 0;
}

