const string NO = "NO";

void solve(long long N, long long A, long long B) {
  vector<int> ans;
  for (int i = 0; i < (1 << N); i++) ans.push_back(i ^ (i >> 1));

  int diff = B ^ A;
  int cnt = 0;
  while (diff % 2 == 0) diff /= 2, cnt++;
  int mask = 0;
  if (diff != 1) {
    cout << "NO" << endl;
    return;
  }

  for (int i = 0; i < cnt; i++) {
    mask *= 2;
    mask++;
  }
  if (diff == 1) {
    for (int i = 0; i < ans.size(); i++) {
      int ok = (ans[i] >= (1 << (N - 1)));
      ans[i] = (ans[i] % (1 << (N - 1))) * 2 + ok;
    }

    for (int i = 0; i < ans.size(); i++) {
      int a = ans[i] & mask;
      int b = (ans[i] - a) >> cnt;
      ans[i] = A ^ (b + a * (1 << (N - cnt)));
    }
  }
  cout << "YES" << endl;
  for (int i = 0; i < ans.size(); i++) {
    cout << ans[i];
    if (i < ans.size() - 1)
      cout << " ";
    else
      cout << endl;
  }
}

