    for (int i = 0; i<temp.size(); i++) if (temp[i]>=pos) temp[i]++;
    vector<ll> res;
    for (int i = 0; i<temp.size(); i++) res.push_back(temp[i]);
    res.push_back(pos);
    for (int i = int(temp.size())-1; i>=0; i--) res.push_back(temp[i]);
    return res;
}

vector<ll> changer1(int n)
{
    if (n==1) return {0};
    vector<ll> res;
    for (int i = n-1; i>0; i--)
    {
        vector<ll> temp = changer(i, i-1);
        for (int j = 0; j<temp.size(); j++) res.push_back(temp[j]+(n-i));
        res.push_back(n-i-1);
    }
    res.push_back(n-1);
    return res;
}

