vector<int> gen(int n, int a, int b)
{
    if (n == 1) return {a, b};
    int toxor = a;
    a ^= toxor;
    b ^= toxor;
    vector<int> ans;
    bool needswap = false;
    int bitneed, bithave;
    if (!(b & (1 << (n - 1))))
    {
        bithave = 0;
        while (!(b & (1 << bithave))) bithave++;
        bitneed = n - 1;
        needswap = true;
        b ^= ((1 << bithave) ^ (1 << bitneed));
    }
    ans = gen(n - 1, 0, (1 << (n - 2)));
    auto r = gen(n - 1, (1 << (n - 2)), b ^ (1 << (n - 1)));
    for (auto t : r) ans.pb(t ^ (1 << (n - 1)));
