            ++use[j];
            prev=j;
            pos^=1<<j;
        }
        print(pos);
    }
     */

    function<bool(i64,i64,i64)> dfs=[&](i64 i,i64 prev,i64 pos){
        ans[i]=pos;
        visit[pos]=true;

        if(i==((1<<N)-1)){
            assert(pos==B);
            return true;
        }

        rep(d,0,N){
            i64 j=((prev==-1?0:prev)+d)%N;

            if(j==prev) continue;

            i64 np=pos^(1<<j);
            if(visit[np]) continue;
            if(np==B and (i+1!=((1<<N)-1))){
                continue;
            }

            if(dfs(i+1,j,pos^(1<<j))) return true;
        }

        visit[pos]=false;
        return false;
