    if (n == 1) {
        p[0] = a;
        p[1] = b;
        return;
    }
    int l = 1 << (n - 1);
    if ((a & l) == (b & l)) {
        f(p + l, n - 1, a, b);
        f(p + 1, n - 1, l ^ a, l ^ p[l + 1]);
        p[0] = a;
    } else {
        int c = a ^ 1;
        f(p, n - 1, a, c);
        f(p + l, n - 1, l ^ c, b);
    }
}

