int popcnt(ll x) { return __builtin_popcountll(x); }

vector<vector<int>> rec(int n, vector<int> const& a, vector<int> const& b) {
    vector<vector<int>> ret;
    if (n == 1) {
        ret.eb(a);
        ret.eb(b);
        return ret;
    }
    int pos = -1;
    rep (i,n) if (a[i] != b[i]) {
        pos = i;
        break;
    }
    assert(pos >= 0);

    auto aa = a, bb = b;
    aa.erase(aa.begin()+pos);
    bb.erase(bb.begin()+pos);
    auto cc = aa;
    cc[0] ^= 1;

    auto s = rec(n-1,aa,cc);
    for (auto &v : s) {
        v.eb(a[pos]);
        rotate(v.begin()+pos,--v.end(),v.end());
        ret.eb(move(v));
    }
    auto t = rec(n-1,cc,bb);
    for (auto &v : t) {
        v.eb(b[pos]);
        rotate(v.begin()+pos,--v.end(),v.end());
        ret.eb(move(v));
    }

    return ret;
}

int32_t main() {
    int n,A,B; cin >> n >> A >> B;

    if (popcnt(A^B)%2 == 0) quit("NO");
