#include <bits/stdc++.h>
using namespace std;

ulong diff(ulong a, ulong b){
    return __builtin_ctzl(a^b);
}

ulong hd(ulong a, ulong b){
    return __builtin_popcountl(a^b);
}

ulong bit_remove(ulong a, ulong n){
    ulong low  = a & ((1<<n)-1);
    ulong high = (a >> (n+1)) << n;
    return high | low;
}

ulong bit_insert(ulong a, ulong n, ulong b){
    ulong low  = a & ((1<<n)-1);
    ulong high = (a >> n) << (n+1);
    return high | (b<<n) | low;
}

vector<long> solve(const ulong n, const ulong a, const ulong b){
    vector<long> v;
    if(n==1){
        v.push_back(a);
        v.push_back(b);
        return v;
    }
    ulong d = diff(a, b);
    ulong aa = bit_remove(a, d);
    ulong ab = bit_remove(a, d) ^ 1;
    ulong bb = bit_remove(b, d);
    auto v0 = solve(n-1, aa, ab);
    auto v1 = solve(n-1, ab, bb);
    for(auto& e : v0){
        e = bit_insert(e, d, (a&(1<<d)) >> d);
    }
    for(auto& e : v1){
        e = bit_insert(e, d, (b&(1<<d)) >> d);
    }
    v0.insert(v0.end(), v1.begin(), v1.end());
    return v0;
}

int main(void){
    ulong n, a, b;
    cin >> n >> a >> b;
    if(__builtin_popcountl(a)%2 == __builtin_popcountl(b)%2){
        std::cout << "NO" << std::endl;
        return 0;
    }
    auto v = solve(n, a, b);
    size_t m = v.size();
    std::cout << "YES" << std::endl;
    for(size_t i=0; i<m-1; i++){
        std::cout << v[i] << " ";
    }
    std::cout << v[m-1] << std::endl;
    return 0;
}

