int main() {
  int N, A, B;
  cin >> N >> A >> B;

  int C = A ^ B;
  int ct = 0;
  for (int i = 0; i < N; i++) {
    if ((C & (1 << i)) > 0) {
      ct++;
    }
  }

  if (ct % 2 == 0) {
    cout << "NO" << endl;
    return 0;
  } else {
    cout << "YES" << endl;
  }

  int m = 1 << N;
  vector<bool> added(m);
  vector<int> seq(m);
  vector<int> count0(N + 1), count1(N + 1);
  seq[0] = A;
  added[A] = true;
  for (int k = 0; k < N; k++) {
    if ((A & (1 << k)) > 0) {
      count1[k]++;
    } else {
      count0[k]++;
    }
  }

  for (int i = 1; i < m; i++) {
    int cur = seq[i - 1];
    for (int j = 0; j < N; j++) {
      int next = cur ^ (1 << j);
      if (next == B && i < m - 1) {
        continue;
      }
      if (!added[next]) {
        int temp = next & (1 << j);
        int temp2 = B & (1 << j);
        if (temp > 0) {
          if (temp != temp2 || count0[j] != m / 2 - 1) {
            added[next] = true;
            seq[i] = next;
            for (int k = 0; k < N; k++) {
              if ((next & (1 << k)) > 0) {
                count1[k]++;
              } else {
                count0[k]++;
              }
            }
            break;
          }
        } else {
          if (temp != temp2 || count1[j] != m / 2 - 1) {
            added[next] = true;
            seq[i] = next;
            count0[j]++;
            for (int k = 0; k < N; k++) {
              if ((next & (1 << k)) > 0) {
                count1[k]++;
              } else {
                count0[k]++;
              }
            }
            break;
          }
        }
      }
    }
  }

  for (int i = 0; i < m; i++) {
    cout << seq[i] << endl;
  }

  return 0;
}

