#define ll long long

int main () {
  ll n;
  cin >> n;
  ll a, b;
  cin >> a >> b;
  ll reseta = a;
  ll resetb = b;

  // a→bへの最短回数を求める．
  ll ans = 0;
  ll aa[18], bb[18];
  for (ll i = 0; i < 18; i++) {
    aa[i] = 0;
    bb[i] = 0;  
  }
  ll itr = 0;
  while (a != 0 ) { 
    if (a % 2 == 1) {
      aa[itr] = 1;
    }  
    a = (a >> 1);
    itr++;
  }
  itr = 0;
  while (b != 0) {
    if (b % 2 == 1) {
      bb[itr] = 1;  
    }     
    b = (b >> 1);
    itr++;
  }
  a = reseta;
  b = resetb;
  ll two[18];
  itr = 1;
  for (ll i = 0; i < 18; i++) {
    two[i] = itr;
    itr = itr * 2;    
  }
  vector<ll> katei;
  katei.push_back(a);
  while (a != b) {
    ans++;
    if (a < b) {
      for (ll i = 17; i >= 0; i--) {
        if (bb[i] == 1 && aa[i] == 0) {
          aa[i] = 1;
          a += two[i];
          break;  
        }    
      }
    }  
    else {
      for (ll i = 17; i >= 0; i--) {
        if (aa[i] == 1 && bb[i] == 0) {
          aa[i] = 0;
          a -= two[i];
          break;  
        }  
      }  
    }
    katei.push_back(a);
  }
  ll nokori = two[n] - 1;
  ans = nokori - ans;
  if (ans < 0 || (ans % 2) == 1) {
    cout << "NO" << endl;  
  }
  else {
    cout << "YES" << endl;    
    for (ll i = 0; i < katei.size(); i++) {
      cout << katei[i];
      if (i != katei.size() - 1) {
        cout << " ";  
      }  
    }
    for (ll i = 0; i < ans; i++) { 
      if (i == 0) cout << " ";
      if (i % 2 == 0) {
        cout << katei[katei.size() - 2];  
      }  
      else {
        cout << katei[katei.size() - 1];
      }
      if (i != ans - 1) {
        cout << " " ;  
      }
      else {
        cout << endl;  
      }
    }
  }


}

