void dfs(vector<int>& ans, int a, int b, int cn, int mask) {
    if (cn == 1) {
        ans.push_back(a);
        ans.push_back(b);
        return;
    }

    int c, d;

    for (int i = 0; i < n; i++) {
        if (!(mask & (1 << i)) && ((a ^ b) & (1 << i))) {
            c = i;
            break;
        }
    }

    for (int i = 0; i < n; i++) {
        if (!(mask & (1 << i)) && i != c) {
            d = i;
            break;
        }
    }

    dfs(ans, a, a ^ (1 << d), cn - 1, mask + (1 << c));
    dfs(ans, a ^ (1 << c) ^ (1 << d), b, cn - 1, mask + (1 << c));
}

