        tmp >>= 1;
    }

    tmp = b;
    while (tmp) {
        if (tmp & 1) cnt_b++;
        tmp >>= 1;
    }

    if ((cnt_a % 2) == (cnt_b % 2)) {
        cout << "NO";
        return 0;
    }

    cout << "YES" << endl;
    vector<int> ans;
