void solve() {
    //const i64 mod = 1'000'000'007;

    i64 N,A,B;
    cin >> N >> A >> B;

    const i64 maxn=17;
    vector<i64> diff;
    rep(i,0,N){
        i64 k=1<<i;
        if((A&k)!=(B&k)){
            diff.emplace_back(i);
        }
    }

    if(diff.size()%2!=1){
        cout << "NO" << endl;
        return;
    }

    vector<i64> ans(1<<N),eo(N),use(N),org;
    for(auto d:diff){
        eo[d]=1;
    }

    org=eo;

    static bool visit[1<<maxn];
    fill_n((bool*)visit,1<<maxn,false);

    /*
