        }
        sort(begin(ps),end(ps));
        for(auto p:ps){
            i64 j=p.second;

            if(j==prev) continue;

            i64 np=pos^(1<<j);
            if(visit[np]) continue;
            if(np==B and (i!=((1<<N)-2))){
                continue;
            }

            if(org[j]==0){
                if(use[j]+1>2) continue;
            }else{
                if(use[j]+1>3) continue;
            }
            if(eo[j]==0) es.emplace_back(j);
            else os.emplace_back(j);
        }
        if(!os.empty()){
            i64 j=os.front();
            eo[j]=(eo[j]+1)%2;
            ++use[j];
            prev=j;
            pos^=1<<j;
        }else{
            i64 j=es.front();
            eo[j]=(eo[j]+1)%2;
            ++use[j];
            prev=j;
            pos^=1<<j;
        }
        print(pos);
    }
     */

    vector<i64> js(N);
    rep(i,0,N){
        js[i]=i;
    }

    i64 cnt=0;

    function<bool(i64,i64,i64)> dfs=[&](i64 i,i64 prev,i64 pos){
        ans[i]=pos;
        visit[pos]=true;

        if(i==((1<<N)-1)){
            assert(pos==B);
            return true;
        }

        ++cnt;
        if(cnt%10==0){
            random_shuffle(begin(js),end(js));
        }

        rep(d,0,N){
            i64 j=js[((prev==-1?0:prev)+d)%N];

            if(j==prev) continue;

            i64 np=pos^(1<<j);
            if(visit[np]) continue;
            if(np==B and (i+1!=((1<<N)-1))){
                continue;
            }

            if(dfs(i+1,j,pos^(1<<j))) return true;
        }

        visit[pos]=false;
        return false;
    };

    if(!dfs(0,-1,A)){
        cout << "NO" << endl;
        return;
    }

    cout << "YES" << endl;
    rep(i,0,1<<N){
        cout << ans[i];
        if(i==((1<<N)-1)) cout << endl;
        else cout << " ";
    }
}

