bool neighbor(int a, int b) {
	int diff = 0;

	while ( a or b ) {
		if ( ( a & 1 ) != ( b & 1 ) ) diff++ ;
		a >>= 1; b >>= 1;
	}

	return diff == 1;
}

bool bin(int a, int b) {
	int diff = 0;

	while ( a or b ) {
		if ( ( a & 1 ) != ( b & 1 ) ) diff++ ;
		a >>= 1; b >>= 1;
	}

	return diff % 2;
}

