vector<int> solve(int n,int a,int b) {
	if (__builtin_parity(a)==__builtin_parity(b)) return {};

	if (n==1) return {a,b};

	int bit=1<<(n-1);
	if ((bit&a)!=(bit&b)) {
		auto p=solve(n-1,a,a^1);
		auto q=solve(n-1,a^1^bit,b);
		p.insert(p.end(),q.begin(),q.end());
		return p;
	} else {
		auto p=solve(n-1,a,b);
		auto q=solve(n-1,a^bit,p[1]^bit);
		p.insert(p.begin()+1,q.begin(),q.end());
		return p;
	}
}

