void solve(int n, int p, int a, int b){
	if(n==1){
		ans.push_back(p|a);
		ans.push_back(p|b);
		return;
	}
	n--;

	int pa = a&(1<<n);
	int pb = b&(1<<n);
	int qa = a&((1<<n)-1);
	int qb = b&((1<<n)-1);

	if(pa==pb){
		solve(n, p|pa, qa, qb);
		ans.pop_back();
		int rb = ans.back();
		solve(n, p|(pa^(1<<n)), rb&((1<<n)-1), qb);
		ans.push_back(p|b);
	} else {
		solve(n, p|pa, qa, qa^1);
		solve(n, p|pb, qa^1, qb);
	}
}

