int main() {
    int N, A, B;
    cin >> N >> A >> B;
    set<int> used;
    V<int> ans;

    int cur = A;
    used.insert(A);
    for (int i = 0; i < (1 << N); ++i) {
        ans.push_back(cur);
        if (i == (1 << N) - 1)break;

        bool update = false;
        for (int j = 0; j < N; ++j) {
            int nx = cur;
            if ((cur >> j)&1) {
                nx -= (1 << j);
            } else {
                nx += (1 << j);
            }
            if (used.count(nx) == 0) {
                if(i==(1<<N)-2 or nx!=B) {
                    used.insert(nx);
                    cur = nx;
                    update = true;
                    break;
                }
            }
        }
        if (!update) {
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;
    for (int x : ans)cout << x << " ";
    cout << endl;

    return 0;
}

