void work(int l, int r, int t)
{
	if(l == r)
	{
		op[l] = t;
		return ;
	}
	int k = __builtin_ctz(t);
	flag[k] = false;
	int g = 0;
	if(__builtin_popcount(t) == 1)
	{
		while(!flag[g])
			g ++;
	}
	else
		flag[g] = __builtin_ctz(t ^ 1 << k);
	work(l, mid - 1, t ^ 1 << k ^ 1 << g);
	op[mid] = 1 << k;
	memcpy(op + mid + 1, op + l, sizeof (int) * (mid - l - 1));
	flag[k] = true;
}
