int p[(1<<17)];

void gen(int n){
	memset(p, 0, sizeof(p));
	for(int i = 0; i < n; i++){
		int len = (1<<(i+1));
		int flg = 0;
		for(int j = 0; j < (1<<n); j += len){
			if(flg){
				for(int k = 0; k < (len>>1); k++){
					p[j+k] |= (1<<i);
				}
			}else{
				for(int k = (len>>1); k < len; k++){
					p[j+k] |= (1<<i);
				}
			}
			flg ^= 1;
		}
	}
}

int rotVal(int c, int n){
	int ans = 0;
	while(c != (1<<(n-1))){
		c <<= 1;
		ans++;
	}
	return ans;
}

inline void rotate(int &c, int n){
	int mask = (1<<n)-1;
	c = ((c<<1)&mask)|(c&(1<<(n-1)));
}

inline void rotate(int &c, int rv, int n){
	while(rv--){
		rotate(c, n);
	}
}

