void Swap(int &x,int i,int j){if ((x>>i&1)^(x>>j&1)) x^=(1<<i)|(1<<j);}
vector<int> work(int A,int B,int n)
{
	if (n==1) return vector<int>({A,B});
	if (B==0) { vector<int>v=work(B,A,n); reverse(v.begin(),v.end()); return v; }
	if (A!=0) { vector<int>v=work(0,A^B,n); for (int &x:v) x^=A; return v; }
	int p=0;rep(i,0,n-1) if (B>>i&1) p=i;
	Swap(A,n-1,p),Swap(B,n-1,p);
	vector<int>L,R;
	rep(i,0,(1<<(n-1))-1) L.push_back(A^(i^(i>>1)));
	R=work(A^(1<<(n-2)),B^(1<<(n-1)),n-1);
	vector<int>v;for (auto x:L) v.push_back(x);for (auto x:R) v.push_back(x^(1<<(n-1)));
	for (int &x:v) Swap(x,n-1,p);
	return v;
}

