vector<int> ans;

void solve(int left, int right, int a, int b, int n){
    if(n == 1){
        ans[left] = a;
        ans[right - 1] = b;
        return;
    }

    int x;
    rep(i, n){
        if((a >> i & 1) != (b >> i & 1)){
            x = i;
            break;
        }
    }

    int la = 0, c, rb = 0;
    REP(i, x + 1, n){
        la += (a & (1 << i));
        rb += (b & (1 << i));
    }
    la >>= 1;
    rb >>= 1;
    rep(i, x){
        la += (a & (1 << i));
        rb += (b & (1 << i));
    }
    c = la ^ 1;

    solve(left, (left + right) / 2, la, c, n - 1);
    solve((left + right) / 2, right, c, rb, n - 1);

    REP(i, left, (left + right) / 2){
        int t = 0;
        REP(j, x, n - 1){
            t += (ans[i] & (1 << j));
        }
        t <<= 1;
        t += (a & (1 << x));
        rep(j, x){
            t += (ans[i] & (1 << j));
        }
        ans[i] = t;
    }
    REP(i, (left + right) / 2, right){
        int t = 0;
        REP(j, x, n - 1){
            t += (ans[i] & (1 << j));
        }
        t <<= 1;
        t += (b & (1 << x));
        rep(j, x){
            t += (ans[i] & (1 << j));
        }
        ans[i] = t;
    }

    return;
}

