vector<int>f(int N, int A, int B) {
	if (N == 1) {
		vector<int>ret;
		ret.eb(A);
		ret.eb(B);
		return ret;
	}
	int x;
	int aa, bb;
	rep(i, 0, N) {
		if (((A >> i) & 1) != ((B >> i) & 1)) {
			x = i;
			int mask = (1ll << N) - (1ll << (i + 1));
			aa = ((A & mask) >> 1) | (A&((1ll << i) - 1));
			bb = ((B & mask) >> 1) | (B&((1ll << i) - 1));
			break;
		}
	}
	int c = aa ^ 1;
	auto l = f(N - 1, aa, c);
	auto r = f(N - 1, c, bb);
	for (auto &y : l) {
		int mask = (1ll << N) - (1ll << x);
		y = ((y&mask) << 1) | (A&(1ll << x)) | y & ((1ll << x) - 1);
	}
	for (auto &y : r) {
		int mask = (1ll << N) - (1ll << x);
		y = ((y&mask) << 1) | (B&(1ll << x)) | y & ((1ll << x) - 1);
	}
	l.insert(l.end(), all(r));
	return l;
}
