namespace Problem {
using namespace std;

class Solver {
 public:
  int n, a, b;
  Solver(LL n) : n(n){};

  void solve() {
    cin >> a >> b;
    int A = 0, B = a ^ b;

    int cnt_diff = 0;
    for (int i = 0; i < n; ++i) {
      if (((A >> i) & 1) != ((B >> i) & 1)) cnt_diff++;
    }
    if (cnt_diff % 2 == 0) {
      cout << "NO" << endl;
      return;
    }
    cout << "YES" << endl;
    auto ans = calc_path(A, B, 0);
    for (auto x : ans) {
      cout << (x ^ a) << " ";
    }
    cout << endl;
  }

  vector<int> calc_path(int from, int to, int mask) {
    set<int> bits_diff, bits_mask;
    for (int i = 0; i < n; ++i) {
      if (((from >> i) & 1) != ((to >> i) & 1)) {
        bits_diff.insert(i);
      }
      if ((mask >> i) & 1) {
        bits_mask.insert(i);
      }
    }
    if (bits_mask.size() == n - 1) {
      return {from, to};
    }
    DBG(from, to, mask, bits_mask, bits_diff)
    for (auto i : bits_diff) {
      if (!((mask >> i) & 1)) {
        int F = (from & (1 << i));
        int T = (to & (1 << i));
        int bound = 0;
        int tmpcnt = 0;
        vector<int> same;
        for (int j = 0; j < n; ++j) {
          if (j == i) continue;
          if (bits_mask.count(j)) {
            bound += (from & (1 << j));
          } else if (bits_diff.count(j)) {
            if (tmpcnt == 0) {
              bound += (from & (1 << j));
            } else {
              bound += (to & (1 << j));
            }
            tmpcnt++;
          } else {
            same.push_back(j);
          }
        }
        int cnt_diff = 0;
        for (int j = 0; j < n; ++j) {
          if (((from >> j) & 1) != (((bound + F) >> j) & 1)) {
            cnt_diff++;
          }
        }
        for (auto x : same) {
          if (cnt_diff % 2 == 0) {
            bound += ((!((from >> x) & 1)) << x);
            break;
          }
        }

        vector<int> res1, res2;
        DBG(from, to, mask, bound, F, T)
        res1 = calc_path(from, bound + F, mask | (1 << i));
        res2 = calc_path(bound + T, to, mask | (1 << i));
        for (auto x : res2) {
          res1.push_back(x);
        }
        DBG(from, to, mask, res1)
        return res1;
      }
    }
    throw new exception();
  }
};

