int n, a, b, z, x[262144];

int lsb (int I) {return (I & (-I));}

void solve (int I, int K, int D) {
    if(I == 1) return;
    if(z == 0) {
        int X = lsb(~D);
        x[K+(1<<(I-2))-1] = X;
        x[K+(1<<(I-1))+(1<<(I-2))-1] = X;
        solve(I-1, K, D+X);
        solve(I-1, K+(1<<(I-1)), D+X);
    }
    else {
        int X = lsb(z);
        z -= X;
        int Y = lsb(z);
        z -= Y;
        x[K+(1<<(I-2))-1] = X;
        x[K+(1<<(I-1))+(1<<(I-2))-1] = Y;
        solve(I-1, K, D+X);
        solve(I-1, K+(1<<(I-1)), D+Y);
    }
}

