using namespace std;
const int B = 18;
const int N = 1 << B;

int parity(int x)
{
    int cnt = 0;
    while (x)
        x -= (x & -x), cnt++;
    return cnt & 1;
}
int isBitOn(int x, int k)
{
    return (x & (1 << k)) > 0;
}
int remBit(int x, int k)
{
    if (k == 0)
        return x >> 1;
    int kones = (1 << k) - 1;
    int kzeros = ~kones;
    int rem = x & kones;
    x >>= 1;
    x &= kzeros;
    x |= rem;
    return x;
}
int insertBit(int x, int k, int bit)
{
    if (k == 0)
    {
        x <<= 1;
        x |= bit;
        return x;
    }

    int kones = (1 << k) - 1;
    int kzeros = ~kones;
    int rem = x & kones;
    x &= kzeros;
    x <<= 1;
    x |= rem;
    if (bit)
        x |= (1 << k);
    return x;
}
vector<int> hamiltonian(int n, int a, int b)
{
    if (n == 1)
        return {a, b};

    int k = 0;
    while (isBitOn(a, k) == isBitOn(b, k))
        k++;
    int na = remBit(a, k), nb = remBit(b, k);
    int c = na ^ 1;
    vector<int> lpath = hamiltonian(n - 1, na, c);

    vector<int> rpath = hamiltonian(n - 1, c, nb);
    for (int &x : lpath)
        x = insertBit(x, k, isBitOn(a, k));
    for (int x : rpath)
        x = insertBit(x, k, isBitOn(b, k)), lpath.push_back(x);
    return lpath;
}

int main()
{
    int i, n, a, b;
    cin >> n >> a >> b;

    if (parity(a) == parity(b))
        cout << "NO\n";
    else
    {
        cout << "YES\n";

        for (int x : hamiltonian(n, a, b))
            cout << x << " ";
    }

    return 0;
}

