const int BIT_MAX = 17;

bool nth_bit_differs(int a, int b, int n) {
    return (a & (1 << n)) != (b & (1 << n));
}

void insert_bit(vector<int>& arr, int idx, int num) {
    int mul = 1;
    while (idx > 0) {
        mul *= 2;
        --idx;
    }
    for(auto& e: arr) {
        e = ((e / mul) * 2) + (num * mul) + (e % mul);
    }
}

vector<int> solve(int from, int to, int N) {
    if (N == 1) {
        vector<int> ret{from, to};
        return ret;
    } else {

        int n = -1;
        REP(n_, N) {
            if (nth_bit_differs(from, to, n_)) {
                n = n_;
            }
        }
        // 全部違うビットの場合適当
        if (n == -1) {
            n = 0;
        }


        int new_from = 0;
        int new_to = 0;
        REP(n2, N) {
            if (n != n2) {
                new_from *= 2;
                new_to *= 2;
                new_from += (from & (1 << n2));
                new_to += (to & (1 << n2));
            }
        }
        REP(n2, N) {
            int tmp = new_from;
            tmp ^= (1 << n2);
            if (tmp != new_to) {
                auto ret1 = solve(new_from, tmp, N - 1);
                auto ret2 = solve(tmp, new_to, N - 1);
                insert_bit(ret1, n, (from & (1 << n)) > 0  );
                insert_bit(ret2, n, (to & (1 << n)) > 0 );

                for(auto e: ret2) ret1.push_back(e);
                return ret1;
            }
        }

    }
}


