#define MAX_BIN 17
bitset<MAX_BIN> crop(bitset<MAX_BIN> num, int a){
    for(int i=a;i<MAX_BIN-1;i++){
        num[i]=num[i+1];
    }
    num[MAX_BIN-1]=0;
    return num;
}
bitset<MAX_BIN> insert(bitset<MAX_BIN> num, int bit,int a){
    for(int i=MAX_BIN-1;i>=a+1;i--){
        num[i]=num[i-1];
    }
    num[a]=bit;
    return num;
}

vector<bitset<MAX_BIN>> GrayCodeGenerator(bitset<MAX_BIN> a,bitset<MAX_BIN> b,int binary_digit){
    //printf("###hoge [%ld:%ld]\n",a.to_ulong(),b.to_ulong());
    if(binary_digit==1){
        vector<bitset<MAX_BIN>> ans;
        ans.push_back(a);
        ans.push_back(b);
        return ans;
    }
    int dig;
    for(int i=binary_digit-1;i>=0;i--){
        if(a[i]!=b[i])dig=i;
    }
    //printf("%d\n",dig);
    bitset<MAX_BIN> adash=crop(a,dig);
    bitset<MAX_BIN> bdash=crop(b,dig);
    //printf("%lld %lld\n",a.to_ullong(),adash.to_ullong());
    bitset<MAX_BIN> c=adash;
    c=c.flip(binary_digit-2);
    vector<bitset<MAX_BIN>> p=GrayCodeGenerator(adash,c,binary_digit-1);
    vector<bitset<MAX_BIN>> q=GrayCodeGenerator(c,bdash,binary_digit-1);
    REP(i,p.size())p[i]=insert(p[i],a[dig],dig);
    REP(i,q.size())q[i]=insert(q[i],b[dig],dig);
    std::copy(q.begin(),q.end(),std::back_inserter(p));
    return p;
}

int main()
{
    int n,a,b;
    scanf("%d %d %d",&n,&a,&b);
    std::bitset<17> aa(a);
    std::bitset<17> bb(b);
    std::bitset<17> dif=aa^bb;
    if(dif.count()%2==0){
        printf("NO\n");
        return 0;
    }
    printf("YES\n");
    vector<bitset<MAX_BIN>> ans=GrayCodeGenerator(aa,bb,n);
    for(bitset<MAX_BIN> i : ans){
        printf("%lld\n",i.to_ullong());
    }
    return 0;
}

