inline int topbit(unsigned long long x){
    return x?63-__builtin_clzll(x):-1;
}

inline int botbit(unsigned long long x){
    return x?__builtin_ctzll(x):64;
}

inline int popcount(unsigned long long x){
    return __builtin_popcountll(x);
}

inline int parity(unsigned long long x){
    return __builtin_parity(x);
}


vint gray(int N,int D){
    int k=topbit(D);
    vint ret(1<<N);
    for(int i=0;i<1<<N;i++)ret[i]=i^(i>>1);

    if(k!=N-1){
        for(int i=0;i<1<<N;i++){
            int x=0,y=0;
            if((ret[i]>>N-1)&1){
                ret[i]^=1<<N-1;
                x=1;
            }
            if((ret[i]>>k)&1){
                ret[i]^=1<<k;
                y=1;
            }
            swap(x,y);
            ret[i]|=x<<N-1;
            ret[i]|=y<<k;
        }
    }
    return ret;
}

vint solve(int N,int D){
    if(popcount(D)==1){
        return gray(N,D);
    }

    int t=topbit(D);
    D^=1<<t;
    int s=topbit(D);
    D^=1<<s;
    vint ret=gray(N-1,1<<s);
    vint tmp=solve(N-1,D);

    ret.insert(ret.end(),all(tmp));
    for(int i=1<<N-1;i<1<<N;i++){
        ret[i]^=ret[(1<<N-1)-1];
    }
    for(int i=0;i<1<<N;i++){
        int b=ret[i]&((1<<t)-1);
        int u=ret[i]-b;
        ret[i]=u*2+b;
    }
    for(int i=1<<N-1;i<1<<N;i++)ret[i]^=1<<t;
    return ret;
}

