  for(int i=0;i<20;i++){
    char c='0'+n%2;
    ans=ans+c;
    n/=2;
  }
  return ans;
}

int two(int n){
  int ans=1;
  for(int i=0;i<n;i++){
    ans*=2;
  }
  return ans;
}

int my_xor(int n,int m){
  string a=bit(n);
  string b=bit(m);
  int ans=0;
  for(int i=0;i<20;i++){
    int x=a.at(i)-'0';
    int y=b.at(i)-'0';
    if(x+y==1){
      ans+=two(i);
    }
  }
  return ans;
}   

