#include <bits/stdc++.h>
using namespace std;
int pc(int i) {
	return __builtin_popcount(i);
}
int arr[1<<17];
int rmbit(unsigned n, int i) {
	return ((n<<(32-i))>>(32-i)) | (((n >> (i+1)))<<i);
}
int addbit(unsigned n, int i, bool p) {
	unsigned t = (n>>i) << (i+1), s = (n<<(32-i))>>(32-i);
	t |= s;
	if(p)
		t |= (1<<i);
	return t;
}
void f(int n, int a, int b, int l) {
	if(n == 1) {
		arr[l] = a;
		arr[l+1] = b;
		return;
	}
	for(int i=0; i<n; i++) {
		if((a&(1<<i)) == (b&(1<<i))) continue;
		int ap = rmbit(a, i), bp = rmbit(b, i), c = ap^1;
		f(n-1, ap, c, l);
		f(n-1, c, bp, l+(1<<(n-1)));
		for(int j=l; j<l+(1<<n); j++)
			arr[j] = addbit(arr[j], i, j<(l+(1<<(n-1))) ? a&(1<<i) : b&(1<<i));
		return;
	}
	assert(0);
}
