int cur = 0, A, B, n, dif;
void gray(deque<int> pos, deque<int> care) {
    int sz = pos.size();
    if(sz == 0) return;
    // if(sz == 1) { 
    //     cur ^= (1 << pos[0]);
    //     gray(care, deque<int>());
    //     printf("%d ", cur); 
    //     return; 
    // }

    int fr = pos.front();
    pos.pop_front();
    gray(pos, care);

    gray(care, deque<int>());
    cur ^= (1 << fr);
    printf("%d ", cur ^ A);

    gray(pos, care);
}

void mono(deque<int> ones, deque<int> care) {
    if(ones.size() == 0) return;
    bool more = ones.size() > 1;
    int fr = ones.front();
    ones.pop_front();
    gray(ones, care);

    int se = 0;
    if(more) se = ones.front();

    gray(care, deque<int>());
    cur ^= (1 << fr);
    printf("%d ", cur ^ A);
    if(more) {
        deque<int> nch;
        nch.push_back(se);
        ones.pop_front();
        mono(ones, nch);
    } else mono(ones, deque<int>());
}

void solve() {
    deque<int> cg, ncg;
    for(int i = 0; i < n; ++i) {
        if(dif >> i & 1) cg.push_back(i);
        else ncg.push_back(i);
    }
    mono(cg, ncg);
}

