int g[N],a[N * 10][3],vh[N],dis[N],di[N],pre[N],his[N];
vector<int>gg[N];
bool bz[N];
void ins(int x,int y,int z){
    a[++sum][0]=y,a[sum][1]=z,a[sum][2]=g[x],g[x]=sum;
    a[++sum][0]=x,a[sum][1]=0,a[sum][2]=g[y],g[y]=sum;
}
void clear(){
    for (int i=0;i<N;i++)
        vh[i]=dis[i]=0;
}
void sap(int s,int t){
    static int x,argue,mn,k;
    static bool p;
    clear();
    flow=0;
    argue=MAXN,x=s;
    vh[0]=t+1;
    while (dis[s]<=t+1){
        p=0;
        his[x]=argue;
        for (int i=di[x];i;i=a[i][2])
            if (a[i][1]&&dis[x]==dis[a[i][0]]+1){
                p=1,argue=min(argue,a[i][1]),di[x]=i,pre[a[i][0]]=x;
                x=a[i][0];
                if (x==t){
                    flow+=argue;
                    while (x!=s){
                        x=pre[x];
                        a[di[x]][1]-=argue;
                        a[di[x]^1][1]+=argue;
                    }
                    argue=MAXN;
                }
                break;
            }
        if (!p){
            if (!(--vh[dis[x]]))break;
            mn=t+2;
            for (int i=g[x];i;i=a[i][2])
                if (a[i][1]&&dis[a[i][0]]<mn)
                    mn=dis[a[i][0]],k=i;
            ++vh[dis[x]=++mn];
            di[x]=k;
            if (x!=s)
                x=pre[x],argue=his[x];
        }
    }
}
