    for (ll i = N; i > 0; i--) {
        cerr << (x >> (i - 1) & 1);
    }
    cerr << endl;
}

vector<ll> path;

void rec(ll d, ll f) {
    if (f == 0)
        return;
    ll x = d & -d; // mrb
    ll nd = d ^ x, nf = f ^ x;

    if (nd == 0) {
        rec(nf & -nf, nf);
        path.push_back(x);
        rec(nf & -nf, nf);
    } else {
        ll y = nd & -nd;
        ll z = nd ^ y;
        rec(y, nf);
        path.push_back(x);
        rec(z, nf);
    }
}

void solve() {
    ll haminglen = A ^ B;
    ll eo = 0;
    for (ll i = 0; i < N; i++) {
        if ((haminglen >> i) & 1)
            eo ^= 1;
