        cout << "NO" << endl;
        return;
    }
    cout << "YES" << endl;
//    bitshow(A);
    cout << A << endl;

    path.reserve(1ull << N);
    rec(A ^ B, (1ull << N) - 1);

    for (auto p : path) {
//        bitshow(A ^= p);
        cout << (A ^= p) << endl;
    }

}

