int popcount(int a){
    return __builtin_popcount(a);
}

vector<int> solve(int n, int a, int b){
    if(n==1){
        return {a,b};
    }
    int bit = (1 << (n-1));
    if((a & bit) != (b & bit)){
        vector<int> s1, s2;
        s1 = solve(n-1, a, a ^ 1);
        s2 = solve(n-1, (a ^ 1) ^ bit, b);
        for(auto p : s2)
            s1.push_back(p);
        return s1;
    }
    else{
        vector<int> s1, s2;
        s1 = solve(n-1, a, b);
        s2 = solve(n-1, a ^ bit, (s1[1] ^ bit));
        vector<int> vv = {s1[0]};
        for(auto x : s2) vv.push_back(x);
        for(int i = 1; i < s1.size(); i ++ ) vv.push_back(s1[i]);
        return s1;
    }
}

