void readx(inp_t& x)
{
	x=0; int k=1; char ch=0;
	while (ch<'0' || ch>'9') { ch=getchar(); if (ch=='-') k=-1; }
	while (ch>='0' && ch<='9') { x=x*10+ch-'0'; ch=getchar(); }
	x*=k;
}

int Bits(int val)
{
	int ret=0;
	while (val)
	{
		ret+=val&1;
		val>>=1;
	}
	return ret;
}

int lowbit(int x)
{
	return x&(-x);
}

// 这tm就是个分治
void Solve(int step,int na,int nb,int mask)
{
	if (step==1) 
	{
		ans.push_back(na);
		ans.push_back(nb);
		return;
	}

	int nowbit= lowbit( mask&(na^nb) );
	mask^=nowbit;
	int nc=na;
	for (int i=0;i<n;i++) if (mask&(1<<i))
	{
		nc^=1<<i;
		break;
	}

	Solve(step-1,na,nc,mask);
	nc^=nowbit;
	Solve(step-1,nc,nb,mask);
}

