vector<int> gray_code(int n) {
    vector<int> res;
    if (n == 1) {
        res = {0, 1};
        return res;
    }

    vector<int> codes = gray_code(n - 1);
    res = codes;
    reverse(codes.begin(), codes.end());
    for (int x : codes) {
        res.push_back((1 << (n - 1)) + x);
    }
    return res;
}

