#include <bits/stdc++.h>
using namespace std;

int nth_bit(int64_t num, int n){
    return (num >> n) & 1;
}

int main(){
    int N, A, B;
    cin >> N >> A >> B;
    B ^= A;
    int total = 1<<N;

    int sz = 0;
    vector<int> perm(N, -1);
    int pt1 = N-1, pt0 = 0;
    for(int i=0; i<N; i++){
        if(nth_bit(B, i)){
            sz++;
            perm[pt1] = i;
            pt1--;
        }else{
            perm[pt0] = i;
            pt0++;
        }
    }
    if(sz%2 == 0){
        cout << "NO" << endl;
        return 0;
    }

    vector<int> path[17];
    path[0] = {0};
    for(int i=1; i<N; i++){
        int prv = 1<<(i-1);
        for(int j=0; j<prv; j++) path[i].push_back(path[i-1][j]*2);
        for(int j=prv-1; j>=0; j--) path[i].push_back(1 + path[i-1][j]*2);
    }

    vector<int> ans;
    int offset = 0;
    int bitlen = N-1;
    bool rvs = false, fin = false;
    for(int i=0; ; i++){
        if(!rvs){
            for(int j=0; j<path[bitlen].size(); j++){
                ans.push_back(offset + path[bitlen][j]);
            }
        }else{
            for(int j=path[bitlen].size()-1; j>=0; j--){
                ans.push_back(offset + path[bitlen][j]);
            }
        }
        if(fin) break;
        offset += 1<<bitlen;
        rvs = !rvs;
        if(i == sz-1){
            fin = true;
        }else{
            bitlen--;
        }
    }

    int Ans[1<<17];
    for(int i=0; i<total; i++){
        int a = 0;
        for(int k=0; k<N; k++) if(nth_bit(ans[i], k)) a += 1<<(perm[k]);
        Ans[i] = a^A;
    }

    cout << "YES" << endl;
    for(int i=0; i<total; i++) cout << Ans[i] << " \n"[i==total-1];
    return 0;
}

