int haiti(int x,int y,int z){
	int i,j;
	int lim=(1<<(y-1));

	if(x==even&&y!=even+1){
		haiti(y-1,y-1,z);
	}else if(x==even+1){
		haiti(even-1,y-1,z);
	}else if(x!=-1){
		haiti(x-1,y-1,z);
	}

	if(x!=-1){
		for(i=lim;i<lim*2;i++){
			for(j=0;j<20;j++){
				keta[z+i][j]=keta[z+2*lim-i-1][j];
			}
			keta[z+i][x]=(keta[z+i][x]^1);
		}
	}

	return 0;
}

