const int B = 10000, T = 30;
bool can(int number, int rest){
    choosed[number] = true;

    if(rest == 0){
        if(__builtin_popcount(number ^ b) == 1){
            resp.push_back(number);
            return true;
        }else{
            choosed[number] = false;
            return false;
        }
    }

    int tent = 0;
    int tmp = number;
    int find = -1;

    for(int i = 0 ; i < n ; i++){
        if(!choosed[number ^ (1 << i)]){
            find = i;
            break;
        }
    }

    if(!find){
        choosed[number] = false;
        return false;
    }

    while(choosed[tmp] && tent <= T){
        // cout << tmp << endl;
        int choosed_bit = rng() % n;
        tmp = number ^ (1 << choosed_bit);
        tent++;
    }
    // cout << "tmp = " << tmp << endl;
