        // cout << tmp << endl;
        if(can(tmp, rest - 1)){
            resp.push_back(number);
            return true;
        }
    }else{
        tmp = number ^ (1 << find);

        if(can(tmp, rest - 1)){
            resp.push_back(number);
            return true;
        }
    }

    choosed[number] = false;

    return false;
}

