using namespace std;

int n;
int a, b;

vector<bitset<18>> Find(bitset<18> a, bitset<18> b, int n) {
    if (n == 1) {
        vector<bitset<18>> ans;
        ans.push_back(a);
        ans.push_back(b);
        return ans;
    }

    int x = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] != b[i]) {
            x = i;
            break;
        }
    }

    bitset<18> ap;
    bitset<18> bp;
    for (int i = 0; i < x; i++) {
        if (a[i]) {
            ap[i] = 1;
            bp[i] = 1;
        }
    }

    for (int i = x + 1; i < n; i++) {
        if (a[i]) {
            ap[i - 1] = 1;
        }
        if (b[i]) {
            bp[i - 1] = 1;
        }
    }

    bitset<18> cp = ap;
    cp[0] = cp[0] ^ 1;
    vector<bitset<18>> first = Find(ap, cp, n - 1);
    vector<bitset<18>> second = Find(cp, bp, n - 1);

    vector<bitset<18>> ans;
    for (int i = 0; i < first.size(); i++) {
        for (int j = n - 1; j > x; j--) {
            first[i][j] = first[i][j - 1];
        }
        first[i][x] = a[x];
    }

    for (int i = 0; i < second.size(); i++) {
        for (int j = n - 1; j > x; j--) {
            second[i][j] = second[i][j - 1];
        }
        second[i][x] = b[x];
    }

    for (int i = 0; i < first.size(); i++) ans.push_back(first[i]);
    for (int i = 0; i < second.size(); i++) ans.push_back(second[i]);

    return ans;
}

int main() {

    cin >> n >> a >> b;

    int tmp = a;
    int cnt_a, cnt_b;

    while (tmp) {
        if (tmp & 1) cnt_a++;
        tmp >>= 1;
    }

    tmp = b;
    while (tmp) {
        if (tmp & 1) cnt_b++;
        tmp >>= 1;
    }

    if ((cnt_a % 2) == (cnt_b % 2)) {
        cout << "NO";
        return 0;
    }

    cout << "YES" << endl;
    bitset<18> as(a);
    bitset<18> bs(b);

    vector<bitset<18>> res = Find(as, bs, n);
    for (int i = 0; i < res.size(); i++) {
        int num = 0;
        for (int j = 0; j < 18; j++) {
            if (res[i][j]) {
                num |= 1 << j;
            }
        }
        cout << num << ' ';
    }
}

#include <bits/stdc++.h>

using namespace std;

int Dif(int a, int b) {return __builtin_popcount(a^b);}
vector <int> Solve(int n, int u, int v)
{
    vector <int> res;
    if (n == 0) return res = {u, v};
    int Z = (1<<n)&u, ZZ = Z^(1<<n);
    if ((u>>n) == (v>>n)) {
        vector <int> vec = Solve(n-1, u^Z, v^Z);
        vector <int> _vec = Solve(n-1, vec[0], vec[1]);
        res.push_back(vec[0]^Z);
        for (int i : _vec) res.push_back(i^ZZ);
        for (int i = 1; i < vec.size(); i++) res.push_back(vec[i]^Z);
    }
    else {
        vector <int> vec = Solve(n-1, u^Z, __builtin_popcount(u^Z)&1^1);
        vector <int> _vec = Solve(n-1, __builtin_popcount(v^ZZ)&1^1, v^ZZ);
        for (int i : vec) res.push_back(i^Z);
        if (Dif(__builtin_popcount(u^Z), __builtin_popcount(v^ZZ))) != 1) assert(0);
        for (int i : _vec) res.push_back(i^ZZ);
    }
    return res;
}

int main()
{
    int n, a, b; cin >> n >> a >> b;
    if (__builtin_popcount(a) == __builtin_popcount(b)) return cout << "NO\n", 0;
    vector <int> ans = Solve(n-1, a, b);
    cout << "YES\n";
    for (int i : ans) cout << i << " ";
    cout << "\n";

    return 0;
}

