bool make_ord(string d, int cnt, const string &targ, vector<string> &out) {
	if (d == targ) {
		if (cnt >= (1 << targ.size()) - 1) {
			out.push_back(d);
			return true;
		}
		else {
			return false;
		}
	}
	used[d] = true;
	bool ret = false;
	for (int t = 0; t < (int)targ.size(); t++) {
		string nxt = d;
		nxt[t] = nxt[t] == '1' ? '0' : '1';
		if (used[nxt]) continue;
		ret |= make_ord(nxt, cnt + 1, targ, out);
		if (ret) {
			out.push_back(d);
			used[d] = false;
			return true;
		}
	}
	used[d] = false;
}

void store() {
	string cur = "";
	for (int i = 0; i < nseg; i++) {
		cur += ord[i][segpos[i]];
	}
	int k = 0;
	for (char c : cur) {
		k <<= 1;
		k += c == '1';
	}
	ans.push_back(k);
}

