		cout << "NO" << endl;
		return 0;
	}
	cout << "YES" << endl;

	string a = "", b = "";
	for (int i = 0; i < N; i++) {
		a += (A >> i) & 1 ? "1" : "0";
		b += (B >> i) & 1 ? "1" : "0";
	}
	reverse(a.begin(), a.end());

	nseg = (N + 3) / 4;

	for (int i = 0; i < nseg; i++) {
		string d = a.substr(4 * i, 4);
		string targ = d;
		targ[0] = targ[0] == '1' ? '0' : '1';
		make_ord(d, 0, targ, ord[i]);
		reverse(ord[i].begin(), ord[i].end());
	}
	int top = nseg - 1;
	for (int iter = 0; iter < (1 << N); iter++) {
		for (int iseg = 0; iseg < nseg; iseg++) {
			if (segcnt[iseg] >= (1 << 4)) continue;
			if (iseg == top) {
				if (segcnt[iseg] == 0) {
					string d = ord[iseg][segpos[iseg]];
					string targ = b.substr(4 * iseg, 4);
