					segpos[iseg] = 0;
				}
				store();
				segcnt[iseg]++;
				segpos[iseg] = (segpos[iseg] + 1) % ord[iseg].size();
				if (segcnt[iseg] >= ord[iseg].size()) {
					top--;
				}
			}
			else {
				store();
				segcnt[iseg]++;
				segpos[iseg] = (segpos[iseg] + 1) % ord[iseg].size();
			}
			for (int j = 0; j < iseg; j++) segcnt[j] = 0;
			break;
		}
	}

	for (int i = 0; i < (int)ans.size(); i++) cout << ans[i] << " \n"[i == (int)ans.size() - 1];
	return 0;
}

