int getl(int n, int i) {
	return (n >> (i+1)) << (i+1);
}
int getr(int n, int i) {
	return n ^ ((n >> i) << i);
}
int rmbit(int n, int i) {
	return (getl(n, i) >> 1) | getr(n, i);
}
int addbit(int n, int i, bool p) {
	return ((n >> i) << (i+1)) | getr(n, i) | (p ? (1 << i) : 0);
}
void f(int n, int a, int b, int l) {
	if(n == 1) {
		arr[l] = a;
		arr[l+1] = b;
		return;
	}
	for(int i=0; i<n; i++) {
		if((a&(1<<i)) == (b&(1<<i))) continue;
		int ap = rmbit(a, i), bp = rmbit(b, i), c = ap^1;
		f(n-1, ap, c, l);
		f(n-1, c, bp, l+(1<<(n-1)));
		for(int j=l; j<l+(1<<n); j++)
			arr[j] = addbit(arr[j], i, j<(l+(1<<(n-1))) ? a&(1<<i) : b&(1<<i));
