  else {
    int m = l + r >> 1;
    int lb = (A^B)&-(A^B);
    for (int SS = S; SS; SS = (SS - 1)&S) {
      int target = A^SS;
      if ((target&lb) == (A&lb)) {
        if (__builtin_parity(target^A) % 2 and __builtin_popcount(target^A) <= r - m - 1 and
            __builtin_parity(target^lb^B) % 2 and __builtin_popcount(target^lb^B) <= r - m - 1) {
          return solve(A, target, l, m, S^lb), solve(target^lb, B, m, r, S^lb);
        }
      }
    }
  }
}

