using namespace std;

vector < int > solve (int N, int A, int pA, int B, int pB)
{
    if (N == 1)
        return {A, B};
    int bitA = (A >> (N - 1)) & 1, bitB = (B >> (N - 1) & 1);
    if (bitA != bitB)
    {
        int mid = 0, pMid = 0;
        if (!(pA ^ bitA))
            mid ++, pMid ^= 1;
        vector < int > firstHalf, secondHalf, ans;
        firstHalf = solve (N - 1, A & ((1 << N) - 1), pA ^ bitA, mid, pMid);
        secondHalf = solve (N - 1, mid, pMid, B & ((1 << N) - 1), pB ^ bitB);
        for (auto it : firstHalf)
            if (bitA) ans.push_back (it | (1 << (N - 1)));
            else ans.push_back (it);
        for (auto it : secondHalf)
            if (bitB) ans.push_back (it | (1 << (N - 1)));
            else ans.push_back (it);
        return ans;
    }
    else
    {
        vector < int > onlyHalf, ans;
        onlyHalf = solve (N - 1, A & ((1 << N) - 1), pA ^ bitA, B & ((1 << N) - 1), pB ^ bitB);
        int currBg = bitA;
        for (auto it : onlyHalf)
        {
            if (currBg) ans.push_back (it | (1 << (N - 1)));
            else ans.push_back (it);
            currBg ^= 1;
            if (currBg) ans.push_back (it | (1 << (N - 1)));
            else ans.push_back (it);
        }
        return ans;
    }
}

