vector<ll> dfs(vector<bool>& used, ll tgt) {
	bitset<20> bi(tgt);
	vector<ll> c;
	for(ll i = n - 1; i >= 0; i--) {
		if(used[i]) continue;
		if(bi[i]) c.pb(i);
	}
	vector<ll> ret;
	if((ll)c.size() == 1) {
		ll p = c[0];
		ret.pb(0);
		REP(i, n) {
			if(p == i || used[i]) continue;
			vector<ll> nret = ret;
			for(ll j = (ll)ret.size() - 1; j >= 0; j--) {
				bitset<20> bii(ret[j]);
				bii[i] = 1;
				nret.pb(bii.to_ullong());
			}
			ret = nret;
		}
		vector<ll> nret = ret;
		for(ll j = (ll)ret.size() - 1; j >= 0; j--) {
			bitset<20> bii(ret[j]);
			bii[p] = 1;
			nret.pb(bii.to_ullong());
		}
		ret = nret;
	} else {
		ll p = c[0], q= c[1], r = c[2];
		bi[p] = 0; bi[q] = 0;
		used[q] = true;
		vector<ll> ret1 = dfs(used, bi.to_ullong());
		used[q] = false;
		bi[p] = 1; bi[q] = 1;
		vector<ll> ret2;
		ret2.pb(0);
		REP(i, n) {
			if(i == p || i == q || used[i]) continue;
			vector<ll> nret = ret2;
			for(ll j = (ll)ret2.size() - 1; j >= 0; j--) {
				bitset<20> bii(ret2[j]);
				bii[i] = 1;
				nret.pb(bii.to_ullong());
			}
			ret2 = nret;
		}
		vector<ll> nret = ret2;
		for(ll i = (ll)ret2.size() - 1; i >= 0; i--) {
			bitset<20> bii(ret2[i]);
			bii[p] = 1;
			nret.pb(bii.to_ullong());
		}
		ret2 = nret;
		REP(i, ret2.size()) {
			ret2[i] = ret2[i] ^ (1ll << q);
			ret2[i] = ret2[i] ^ ret1[(ll)ret1.size() - 1];
		}
		REP(i, ret1.size()) ret.pb(ret1[i]);
		REP(i, ret2.size()) ret.pb(ret2[i]);
	}
	return ret;
}

