#define popCnt(x) (__builtin_popcountll(x))
typedef unsigned long long Long;

int n;

int getLSB(int x) {
  return x & ~(x - 1);
}

vector<int> solve(int a, int b, int unused_mask) {
  if (popCnt(unused_mask) == 1) {
    return {a , b};
  }

  int diff = -1;
  for (int i = 0; i < n; ++i) {
    if ((~unused_mask >> i) & 1) continue;
    if (((a ^ b) >> i) & 1) {
      diff = i;
      break;
    }
  }

  vector<int> res;

  unused_mask ^= (1 << diff);

  int c = a ^ getLSB(unused_mask);

  res = solve(a, c, unused_mask);

  auto tmp = solve(c ^ (1 << diff), b, unused_mask);
  res.insert(res.end(), tmp.begin(), tmp.end());

  return res;
}

