typedef long long ll;
ll convert(ll x,ll kt){
  ll res=0;
  for(int i=18;i>kt;i--){
    res+=(((x>>i)&1)<<(i-1));
  }
  for(int i=kt-1;i>=0;i--){
    res+=(((x>>i)&1))<<i;
  }
  return res;
}
ll g_convert(ll x,ll kt,ll bt){
  ll res=0;
  for(int i=18;i>=kt;i--){
    res+=(((x>>i)&1)<<(i+1));
  }
  for(int i=kt-1;i>=0;i--){
    res+=(((x>>i)&1)<<i);
  }
  res+=(bt<<kt);
  return res;
}
vector<ll> f(ll a,ll b,ll n){
  vector<ll> res;
  if(n==1) {
    res.push_back(a);
    res.push_back(b);
    return res;
  }
  ll N=(1<<n);
  ll kt=0;
  for(int i=0;i<=17;i++){
    if((((a^b)>>i)&1)==1){
      kt=i;
      break;
    }
  }

  ll a_kt=(a>>kt)&1,b_kt=(a_kt+1)%2;
  ll na=convert(a,kt),nb=convert(b,kt);
  ll nc=na^1;

  vector<ll> L=f(na,nc,n-1),R=f(nc,nb,n-1);
  for(int i=0;i<N/2;i++){
    res.push_back(g_convert(L[i],kt,a_kt));
  }
  for(int i=N/2;i<N;i++){
    res.push_back(g_convert(R[i-N/2],kt,b_kt));
  }
  return res;
}
