ll N, A, B;
bool output = false;
vector<int> answer;

bool f(const set<int> &used, int next, int i) {
	if (i == 0) {
		if (next == A && !output) {
			output = true;
			return true;
		}
		return false;
	}

	rep(t, N) {
		int cur = next ^ (1 << t);
		if (used.find(cur) == used.end()) {
			auto tmp = used;
			tmp.insert(cur);
			if (f(tmp, cur, i - 1)) {
				answer.push_back(cur);
				return true;
			}
		}
	}

	return false;
}

int main() {

	scanf("%lld %lld %lld", &N, &A, &B);

	{
		int a = 0, b = 0;

		rep(i, 17) {
			if ((A >> i) & 1) ++a;
			if ((B >> i) & 1) ++b;
		}
		if (a % 2 == b % 2) {
			printf("NO\n");
			return 0;
		}
	}

	if (f({ (int)B }, B, (1 << N) - 1)) {
		printf("YES\n");
		for (auto ans : answer) {
			printf("%d ", ans);
		}
		printf("%d\n", B);
	}
	else printf("NO\n");

	return 0;
}

