void swp(int& a, int i, int j) {
    int bi = (a>>i) & 1, bj = (a>>j) & 1;
    a -= (bi << i) + (bj << j);
    a += (bi << j) + (bj << i);
}

//0 ~ n - 1 bit目に着目
vector<int> resolve(int n, int a, int b) {
    if(n == 1) {
        return {a, b};
    }
    int exchange = n - 1;
    for(int k = 0; k <= n - 1; ++k) {
        if(((a>>k) & 1) != ((b>>k) & 1)) {
            exchange = k;
            break;
        }
    }
    swp(a, exchange, n - 1);
    swp(b, exchange, n - 1);
    int c = a ^ 1; // n >= 2
    int d = c ^ (1<<(n - 1));
    auto zenhan = resolve(n - 1, a, c);
    auto kohan = resolve(n - 1, d, b);
    vector<int> res;
    for(auto& v: zenhan) {
        res.push_back(v);
    }
    for(auto& v: kohan) {
        res.push_back(v);
    }
    for(auto& v: res) {
        swp(v, exchange, n - 1);
    }
    return res; 
}

