int N, A, B, bit;

bool calc()
{
	bit = 1;
	int x = 1;
	int a = A;
	int b = B;
	int c = 0;
	while (a + b) {
		if ((a ^ b) & 1) {
			bit = x;
			c++;
		}
		x <<= 1;
		a >>= 1;
		b >>= 1;
	}
	return c % 2;
}

vector<int> res(3000000);

void dfs(set<int>& s, int b, int l, int r, bool f = false)
{
	if (b == bit && !f) {
		dfs(s, b << 1, l, r);
		return;
	}
	if (r - l == 4) {
		int t = *s.begin();
		int u = *(next(s.begin(), 1));
		int x = t ^ res[l];
		if (x != (x & -x)) {
			swap(t, u);
		}
		res[l+1] = t;
		res[l+2] = u;
		return;
	}
	set<int> x, y;
	for (auto a : s) {
		if ((a & b) ^ (A & b)) {
			y.insert(a);
		} else {
			x.insert(a);
		}
	}
	int t = *x.begin();
	x.erase(t);
	y.erase(t^b);
	res[(r+l)/2-1] = t;
	res[(r+l)/2] = t+b;
	if (b == bit) b = 1;
	else b <<= 1;
	dfs(x, b, l, (r+l)/2);
	dfs(y, b, (r+l)/2, r);
}

