int n;
void work(int dif,int A,int x){
	if(__builtin_popcount(x)==1){
		printf("%d %d ",A,A^dif);
		return;
	}
	REP(i,0,n-1) if((dif&(1<<i))>0 && (x&(1<<i))>0)
		REP(j,0,n-1) if((x&(1<<j))>0 && i!=j){
			work(1<<j,A,x^(1<<i));
			work(dif^(1<<i)^(1<<j),A^(1<<i)^(1<<j),x^(1<<i));
		}
}
