bool d[1<<17];
bool vis[1<<17];
vi ans;

vi next_nodes(int u) {
  vi ret;
  for (int i = 0; i < n; i++) {
    if (u & (1<<i)) {
      ret.push_back(u & ~(1<<i) & ((1<<n)-1));
    } else {
      ret.push_back(u | (1<<i));
    }
  }
  return ret;
}

void bfs() {
  queue<pii> q({mp(b,0)});

  while (!q.empty()) {
    pii p = q.front(); q.pop();
    for (int v : next_nodes(p.fst)) {
      if (v != b && d[v] == 0) {
        d[v] = p.snd+1;
        q.push(mp(v,p.snd+1));
      }
    }
  }
}

void search() {
  int u = a;
  while ((int)ans.size() < (1<<n)) {
    vis[u] = true;
    ans.push_back(u);
    int v = -1, y = -1;
    for (int x : next_nodes(u)) {
      if (!vis[x] && y < d[x]) {
        y = d[x];
        v = x;
      }
    }
    u = v;
  }
}

