using namespace std;

unsigned long long popcount(unsigned long long x) {
    x = ((x & 0xaaaaaaaaaaaaaaaaUL) >> 1) +
        (x & 0x5555555555555555UL);
    x = ((x & 0xccccccccccccccccUL) >> 2) +
        (x & 0x3333333333333333UL);
    x = ((x & 0xf0f0f0f0f0f0f0f0UL) >> 4) +
        (x & 0x0f0f0f0f0f0f0f0fUL);
    x = ((x & 0xff00ff00ff00ff00UL) >> 8) +
        (x & 0x00ff00ff00ff00ffUL);
    x = ((x & 0xffff0000ffff0000UL) >> 16) +
        (x & 0x0000ffff0000ffffUL);
    x = ((x & 0xffffffff00000000UL) >> 32) +
        (x & 0x00000000ffffffffUL);
    return x;
}

long long n, a, b;
vector<long long> ans;

vector<long long> solve(long long st, long long fin, long long rem);

int main(){
    cin >> n >> a >> b;
    if(popcount(a^b)%2) {
        ans = solve(0, a ^ b, (1LL << n) - 1);
        cout << "YES" << endl;
        for(int i = 0;i < ans.size();++i){
            if(i != 0)cout << " ";
            cout << (ans[i] ^ a);
        }
    }
    else cout << "NO" << endl;
    return 0;
}

vector<long long> solve(long long st, long long fin,long long rem){
    vector<long long> now,nowans;
    long long nowsize = 0;
    if(popcount(rem) == 1){
        nowans.push_back(st);
        nowans.push_back(fin);
        return nowans;
    }
    for(int i = 0;i < n;++i)
        if(((st ^ fin) >> i) & (rem >> i) & 1){
            for(int j = 0;j < n;++j)
                if(i != j && (rem >> j) & 1){
                    long long med = st ^ (1 << j);
                    nowans = solve(st,med,rem - (1 << i));
                    now = solve(med ^ (1 << i),fin,rem - (1 << i));
                    nowsize = now.size();
                    for(int k = 0;k < nowsize;++k)nowans.push_back(now[k]);
                    break;
                }
            break;
        }
    return nowans;
}

