int cutbit(int x, int bit){
    int now = (x - ((x >> bit) << bit));
    int res = ((x >> (bit + 1)) << bit) + now;
    return res;
}
int ins(int x, int bit, bool c){
    int now = (x >> bit) << bit;
    x += (now << 1)  - now;
    return c ? (x ^ (1 << bit)) : x;
}
vector<int> go(int a, int b, int curbit){
    if(curbit == 0){
        return {a , b};
    }
    int idx = __builtin_ctz(a ^ b);
    int x = cutbit(a, idx); int y = cutbit(b, idx);
    int z = x ^ 1;
    auto u = go(x, z, curbit - 1) ;
    auto v = go(z, y, curbit - 1) ;
	bool d = a & (1 << idx); 
    for(int &i : u)
        i = ins(i, idx, a);
    for(int i : v)
        u.push_back(ins(i, idx, a ^ 1));
    return u;
}

