using namespace std;
using ll = long long;

int swap_bits(int x,int i,int j) {
	int bit_i=x>>i&1;
	int bit_j=x>>j&1;
	return x^(bit_i<<i)^(bit_j<<j)^(bit_i<<j)^(bit_j<<i);
}

vector<int> solve(int n,int a,int b) {
	if (__builtin_parity(a) == __builtin_parity(b)) return {};

	if (n==1) return {a,b};

	int k=0;
	while ((a>>k&1)==(b>>k&1)) k++;
	a=swap_bits(a,k,0);
	b=swap_bits(b,k,0);
	assert((a&1)!=(b&1));

	int c=a>>1, d=b>>1;
	auto p=solve(n-1,c,c^1);
	auto q=solve(n-1,c^1,d);

	vector<int> res;
	for (auto x:p) {
		int nx=swap_bits(x<<1|(a&1),k,0);
		res.push_back(nx);
	}
	for (auto x:q) {
		int nx=swap_bits(x<<1|(b&1),k,0);
		res.push_back(nx);
	}

	return res;
}

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(0);
	cout<<fixed<<setprecision(10);

	int N,A,B;
	cin>>N>>A>>B;
	auto res=solve(N,A,B);
	if (res.empty()) {
		cout<<"NO\n";
	} else {
		cout<<"YES\n";
		for (int x:res) cout<<x<<" ";
		cout<<"\n";
	}
}

