    {
        if(i != A && i != B)
            v[pc(i)].pb(i);
        cnt[pc(i)]++;
    }

    if(pc(A) % 2 == pc(B) % 2)
    {
        cout << "NO" << endl;
        return 0;
    }

    int last = -1;
    for(int i = 0; i < (1 << n); i++)
        for(int j = 0; j <= n; j++)
            if(cnt[j] && j != last)
            {
                cnt[j]--;
                last = j;
                seq.pb(j);
                break;
            }


    bool swapped = false;
    if(pc(A) & 1)
    {
        swapped = true;
        swap(A, B);
    }

    int seek;
    if(n & 1)
        seek = n - 2;
    else
        seek = n - 3;
    for(int i = (1 << n) - 2; i >= 0 && seek >= pc(B); i--)
        if(seq[i] == seek)
        {
            reverse(seq.begin() + i, seq.end());
            seek -= 2;
        }

    seek = 2;
    for(int i = 1; i < (1 << n) && seek <= pc(A); i++)
        if(seq[i] == seek)
