#include <bits/stdc++.h>
using namespace std;

int bit_remove(int bit, int i){// A*B -> AB
    int A = bit >> (i+1);
    int B = bit & ((1<<i) - 1);
    return (A << i) + B;
}

int bit_insert(int bit, int i, int x){// AB -> A*B
    int A = bit >> i;
    int B = bit & ((1<<i) - 1);
    return (A << (i+1)) + (x << i) + B;
}

vector<int> DFS(int a, int b, int n){
    if(n == 1) return {a,b};

    for(int i=0; i<n; i++){
        if((a >> i & 1) ^ (b >> i & 1)){
            int na = bit_remove(a,i);
            int nb = bit_remove(b,i);

            for(int j=0; j<(1<<n); j++){
                int x = bit_remove(j, i);

                if(__builtin_popcount(na) % 2 != __builtin_popcount(x) % 2
                && __builtin_popcount(nb) % 2 != __builtin_popcount(x) % 2){
                    vector<int> ans1 = DFS(na, x, n-1);
                    vector<int> ans2 = DFS(x, nb, n-1);

                    for(auto& a1 : ans1) a1 = bit_insert(a1, i, (a >> i) & 1);
                    for(auto& a2 : ans2) a2 = bit_insert(a2, i, (b >> i) & 1);

                    ans1.insert(ans1.end(), ans2.begin(), ans2.end());
                    return ans1;
                }
            }
        }
    }
    //assert(false);
    return {};
}

