using namespace std;
int res[maxn], tmp[maxn];
void solve(int st, int n, int a, int b)
{
	if (n == 1)
	{
		res[st] = a;
		res[st + 1] = b;
		return;
	}
	int len = 1 << n, A, B, tag = a;
	a ^= tag; b ^= tag;
	if ((b >> n - 1) & 1)
	{
		int x = b - (1 << n - 1), tmp = x ^ (1 << n - 2);
		solve(st, n - 1, 0, tmp);
		A = tmp + (1 << n - 1);
		B = b;
		solve(st + len / 2, n - 1, A, B);
	}
	else
	{
		solve(st, n - 1, a, b);
		A = 1 << n - 1;
		B = res[st + 1] ^ (1 << n - 1);
		solve(st + len / 2, n - 1, A, B);
		int cur = st;
		tmp[st] = res[st];
		for (int i = len / 2 + 1; i <= len; i++)
			tmp[++cur] = res[st + i - 1];
		for (int i = 2; i <= len / 2; i++)
			tmp[++cur] = res[st + i - 1];
		for (int i = 1; i <= len; i++)
			res[st + i - 1] = tmp[st + i - 1];
	}
	for (int i = 1; i <= len; i++)
		res[st + i - 1] ^= tag;
}
