		for(int j=(1<<i);j<(1<<(i+1));j++){
			Mask[j] = Mask[2*(1<<i)-j-1] + (1 << i);
		}
	}
	int next = A;
	int mask = 0;
	int p = 0;
	int x = N-1;
	for(int i=0;i<N;i++){
		if(((1 << i) & A) != ((1 << i) & B)){
			cout << next << endl;
			mask += 1 << i;
			Start(p,next,mask);
			p += (1 << x);
			next = (Answer[p-1] ^ (1 << i));
			x--;
		}
	}
	while(x >= 0){
		for(int i=0;i<N;i++){
			if(((1 << i) & next) != ((1 << i) & B)){
