void construct(LL n, LL a, LL b, LL used, vector<LL>& ans){
    LL b1 = 0, b2 = -1;
    for(LL i = 0; i < n; ++i){
        if((used>>i) & 1) continue;
        LL ab = (a>>i) & 1;
        LL bb = (b>>i) & 1;
        if((ab ^ bb) == 1){
            b1 = i;
        }else{
            b2 = i;
        }
    }
    if(b2 == -1){
        ans.push_back(a);
        ans.push_back(b);
        return;
    }
    //cerr << "a=" << a << ", b=" << b << ", b1=" << b1 <<", b2=" << b2 << endl;
    construct(n, a, a^(1<<b2), used|(1<<b1), ans);
    construct(n, a^(1<<b2)^(1<<b1), b, used|(1<<b1), ans);
}

vector<LL> solve(LL n, LL a, LL b){
    LL ca = 0, cb = 0;
    for(LL i = 0; i < n; ++i){
        ca += (a>>i) & 1;
        cb += (b>>i) & 1;
    }
    if((ca + cb) % 2 == 0){
        return vector<LL>();
    }
    vector<LL> ans;
    construct(n, a, b, 0, ans);
    return ans;
}

