int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    using bits = bitset<17>;
    int n; cin >> n;
    int x, y; cin >> x >> y;
    bits a = x, b = y;
    if ((a.count() + b.count()) % 2 == 0) {
        cout << "NO\n";
        return 0;
    }
    int sw = -1;
    auto bitswap = [&](auto a, auto b) -> void {
        bool c = a; a = b; b = c;
    };
    for (int i = n-1; i >= 0; i--) {
        if (a[i] != b[i]) {
            sw = i;
            bitswap(a[n-1], a[i]);
            bitswap(b[n-1], b[i]);
            break;
        }
    }
    auto bv = [&](int n) {
        vector<bits> v; bits msk = 0;
        v.emplace_back(msk);
        for (int i = 0; i < n; i++) {
            msk[i] = 1;
            int c = v.size();
            for (int j = 0; j < c; j++) {
                v.emplace_back(~v[j] & msk);
            }
        }
        v.emplace_back(0);
        reverse(v.begin(), v.end());
        return v;
    };

    vector<bits> ans; bits curr = a;
    for (int i = n-1; i >= 0; i--) {
        assert(curr[i] != b[i]);
        int s = (i && curr[i-1] == b[i-1]) ? i-1 : 0;
        auto v = bv(i);
        for (int j = 0; j < (1 << i); j++) {
            bits w = v[j];
            bitswap(w[s], w[0]);
            ans.emplace_back(w ^ curr);
        }
        curr = ans.back();
        curr[i] = !curr[i];
    }
    ans.emplace_back(curr);
    cout << "YES\n";
    for (int i = 0; i < (1 << n); i++) {
        auto &c = ans[i];
        bitswap(c[sw], c[n-1]);
        if (i) cout << " "; 
        cout << c.to_ulong();
    }
    cout << "\n";
    return 0;
}

