void init()
{
	int N;
	int A;
	int B;
	cin >> N >> A >> B;
//	int C = (A ^ B) ^ (1 << (N-1));
	int C = (A ^ B);
	int D = 0;
	while (C) {
		if (C % 2 == 0) {
			D = D * 2 + 1;
		}
		C /= 2;
	}
	C = (A ^ B);
	vector<set<int>> m(N+10);
	reps(i, 1, 1 << N) {
		int j = i & -i;
		int t = 0;
		while (j != 1) {
			j >>= 1;
			t++;
		}
		m[t].insert(i);
	}
	if (N == 1) {
		if (A == 0) {
			cout << "0 1" << endl;
		} else {
			cout << "1 0" << endl;
		}
		return;
	}
	int x = 1;
	int bit = 1 << (N-1);
	while (x < N) {
		if ((bit & D) == 1) {
			if (x == 1) {
				x--;
				int a = *m[x].begin();
				int b = *(next(m[x].begin(), 1));
				int c = *m[x+1].begin();
				m[x].erase(a);
				m[x].erase(b);
				m[x].insert(c);
				m[x+1].insert(a);
				m[x+1].insert(b);
				m[x+1].erase(c);
			} else {
				x--;
				int a = *(next(m[x].end(),-1));
				int b = *(next(m[x].end(),-2));
				int c = *(next(m[x+1].end(),-1));
				m[x].erase(a);
				m[x].erase(b);
				m[x].insert(c);
				m[x+1].insert(a);
				m[x+1].insert(b);
				m[x+1].erase(c);
			}
			D ^= bit;
			D ^= (bit >> 1);
			x++;
		}
		bit >>= 1;
		x++;
	}
	vector<int> res(1 << N, 0);
	vector<int> R(N, 0);
	vector<int> BI(N, 0);
	res[0] = A;
	rep(i, N) {
		for (int a : m[i]) {
			res[a] = 1 << (N-1-i);
			R[i]++;
		}
		BI[i] = 1 << i;
	}
	rep(i, N) {
		if (R[i] % 2 != ((C >> i) % 2)) {
			reps(j, i+1, N) {
				if (R[i] % 2 != R[j] % 2) {
					swap(R[i], R[j]);
					swap(BI[i], BI[j]);
					C ^= 1 << j;
					C ^= 1 << i;
				}
			}
		}
	}
	res[0] = A;
	rep(i, N) {
		for (int a : m[i]) {
			res[a] = BI[i];
		}
	}
	reps(i, 1, 1 << N) {
		res[i] ^= res[i-1];
	}
	if (res.back() != B) {
		cout << "NO" << endl;
		return;
	}
	cout << "YES" << endl;
	rep(i, (1 << N) - 1) {
		cout << res[i] << " ";
	}
	cout << res.back() << endl;
}

