vector <int> get(int n) {
    if (n == 0) return {0};
    vector <int> a = get(n / 2);
    vector <int> res;
    for (int x : a) res.push_back(2 * x);
    reverse(a.begin(), a.end());
    for (int x : a) res.push_back(2 * x + 1);
    return res;
}

