    ios_base::sync_with_stdio(false); cin.tie(0); cout.setf(ios::fixed); cout.precision(20);
    #ifdef LOCAL
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
    #endif
    int n, a, b;
    cin >> n >> a >> b;
    if (__builtin_popcount(a ^ b) != 1) {
        cout << "NO\n";
        return 0;
    }
    vector <int> res = get(n);
    vector <int> ans;
    for (int i = 0; i < (1 << n); ++i) {
        int j = (i + 1) % (1 << n);
        if ((res[i] ^ res[j]) == (a ^ b)) {
            int xr = res[i] ^ a;
            int cur = i;
            for (int k = 0; k < (1 << n); ++k) {
                ans.push_back(res[cur] ^ xr);
                --cur;
                if (cur == -1) cur = (1 << n) - 1;
            }
            break;
        }
    }
    cout << "YES\n";
    for (int i : ans) cout << i << ' ';
}

