void solve(int l, int r, int A, int B) {
	if(r - 1 == l) {
		ans[l] = A;
		ans[r] = B;
		return;
	}

	int x;
	for(int i = 0; i < n; ++i)
		if((A & (1 << i)) ^ (B & (1 << i))) {
			x = i;
			break;
		}

	int _A, _B, C;
	_A = ((A >> (x + 1)) << x) + (A & ((1 << x) - 1));
	_B = ((B >> (x + 1)) << x) + (B & ((1 << x) - 1));
	C = _A ^ 1;
	int mid = (l + r) >> 1;
	solve(l, mid, _A, C);
	solve(mid + 1, r, C, _B);

	for(int i = l, num = (1 << x) & A; i <= mid; ++i)
		ans[i] = ((ans[i] >> x) << (x + 1)) + num + (ans[i] & ((1 << x) - 1));
	for(int i = mid + 1, num = (1 << x) & B; i <= r; ++i)
		ans[i] = ((ans[i] >> x) << (x + 1)) + num + (ans[i] & ((1 << x) - 1));
}

bool check(int A, int B) {
	int ret1 = 0, ret2 = 0;
	while(A) {
		if(A & 1) ++ret1;
		A >>= 1;
	}
	while(B) {
		if(B & 1) ++ret2;
		B >>= 1;
	}
	return (ret1 & 1) ^ (ret2 & 1);
}

