bool nth_bit_differs(int a, int b, int n) {
    return (a & (1 << n)) != (b & (1 << n));
}

void insert_bit(vector<int>& arr, int idx, int num) {
    int mul = 1;
    while (idx > 0) {
        mul *= 2;
        --idx;
    }
    for(auto& e: arr) {
        e = ((e / mul) * 2) + (num * mul) + (e % mul);
    }
}

