        //}


        int new_from = 0;
        int new_to = 0;
        REP(n2, N) {
            if (n != n2) {
                new_from *= 2;
                new_to *= 2;
                new_from += (from & (1 << n2)) > 0;
                new_to += (to & (1 << n2)) > 0;
            }
        }
        REP(n2, N) {
            int tmp = new_from;
            tmp ^= (1 << n2);
            if (tmp != new_to) {
                auto ret1 = solve(new_from, tmp, N - 1);
                auto ret2 = solve(tmp, new_to, N - 1);
                insert_bit(ret1, n, (from & (1 << n)) > 0  );
                insert_bit(ret2, n, (to & (1 << n)) > 0 );

                for(auto e: ret2) ret1.push_back(e);
                return ret1;
            }
        }

    }
}


