void go(int sz, int bit) {
    if(sz == N+1) return;
    if((1 << bit) == t) go(sz, bit+1);
    else {
        int M = C[sz-1].size();
        for(int i=0; i<M/2; i++) C[sz].push_back(C[sz-1][i]);
        for(int i=M/2-1; i>=0; i--) C[sz].push_back(C[sz-1][i] + (1<<bit));
        for(int i=M-1; i>=M/2; i--) C[sz].push_back(C[sz-1][i] + (1<<bit));
        for(int i=M/2; i<M; i++) C[sz].push_back(C[sz-1][i]);
        go(sz + 1, bit + 1);
    }
}

