int countbits(LL bits)
{
    bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
    bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
    bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
    bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
    return (bits & 0x0000ffff) + (bits >>16 & 0x0000ffff);
}

void solve() {
    int n,a,b;
    cin >> n >> a >> b;
    if (countbits(a ^ b) % 2 == 0) {
        cout << "NO" << endl;
        return;
    }
    cout << "YES" << endl;
    VI s,t;
    s.push_back(a);
    t.push_back(b);
    vector<bool> visited(1<<n);
    visited[a] = visited[b] = true;
    int si = a, ti = b;
    REP(i,0,(1<<n)/2-1) {
        REP(j,0,n) {
            int c = si ^ (1 << j);
            if (!visited[c]) {
                visited[c] = true;
                s.push_back(c);
                si = c;
                break;
            }
        }
        REP(j,0,n) {
            int c = ti ^ (1 << j);
            if (!visited[c]) {
                visited[c] = true;
                t.push_back(c);
                ti = c;
                break;
            }
        }
    }
    reverse(all(t));
    REP(i,0,s.size()) {
        if (i) cout << " ";
        cout << s[i];
    }
    REP(i,0,t.size()) {
        cout << " " << t[i];
    }
    cout << endl;
}

