vector<int> solve(int a, int b, int n) {
	if (n == 1) {
		return {a, b};
	}
	int x = 0;
	while ((a & (1 << x)) == (b & (1 << x))) {
		++x;
	}
	int u = delete_bit(a, x);
	int v = delete_bit(b, x);
	int c = u ^ 1;
	vector<int> l = solve(u, c, n - 1);
	vector<int> r = solve(c, v, n - 1);
	for (auto &i : l) {
		i = add_bit(i, x, (a >> x) & 1);
	}
	for (auto &i : r) {
		i = add_bit(i, x, (b >> x) & 1);
		l.pb(i);
	}
	return l;
}

int add_bit(int a, int p, int b) {
	return ((((a >> p) << 1) | b) << p) | (a & ((1 << p) - 1));
}

int delete_bit(int a, int p) {
	return ((a >> (p + 1)) << p) | (a & ((1 << p) - 1));
}

