int p[1000000];
void gray(int s,int n,int g) {
	if(n==0) return;
	for(int i=0;i<(1<<(n-1));i++) {
		p[s+i]^=(g<<(n-1));
		p[s+i+(1<<(n-1))]^=((g^1)<<(n-1));
	}
	gray(s,n-1,0);
	gray(s+(1<<(n-1)),n-1,1);
}
void solve(int s,int n,int a,int b) {
	if((__builtin_popcount(b))==1) { //Bazni slucaj
		gray(s,n,0);
		int t1=(1<<(n-1));
		int t2=b;
		for(int i=0;i<(1<<n);i++) {
			if(((p[i+s]&t1)^(p[i+s]&t2)) && ((((p[i+s]&t1)^(p[i+s]&t2)))^(t1^t2))) p[i+s]^=(t1^t2);
		}
		for(int i=0;i<(1<<n);i++) p[i+s]^=a;
		return;
	}
	int t1=(1<<(n-1));
	int t2=t1;
	while((b&t2)==0) t2>>=1;
	gray(s,n-1,0);
	solve(s+t1,n-1,t1^(t1>>1),(b^t2^(t1>>1)));
	for(int i=0;i<(1<<n);i++) {
		if(((p[i+s]&t1)^(p[i+s]&t2)) && ((((p[i+s]&t1)^(p[i+s]&t2)))^(t1^t2))) p[i+s]^=(t1^t2);
	}
	for(int i=0;i<(1<<n);i++) p[i+s]^=a;
}
