using namespace std;

vector<vector<int> > Solve(vector<int>& L, vector<int>& R, int K) {
	vector<vector<int> > ANS(1 << K, vector<int>(K));
	if (K == 1) {
		ANS[0] = L, ANS[1] = R;
		return ANS;
	}
	int D;
	for (int i = 0; i < K; i++) {
		if (L[i] != R[i]) {
			D = i;
			break;
		}
	}
	vector<int> Left, Mid, Right;
	for (int i = 0; i < K; i++) {
		if (i != D) Left.push_back(L[i]), Right.push_back(R[i]);
	}
	Mid = Left;
	Mid[0] = 1 - Mid[0];
	vector<vector<int> > VL = Solve(Left, Mid, K - 1), VR = Solve(Mid, Right, K - 1);
	for (int i = 0; i < 1 << (K - 1); i++) {
		for (int j = 0; j < K; j++) {
			if (j < D) ANS[i][j] = VL[i][j];
			if (j == D) ANS[i][j] = L[D];
			if (j > D) ANS[i][j] = VL[i][j - 1];
		}
	}
	for (int i = 0; i < 1 << (K - 1); i++) {
		for (int j = 0; j < K; j++) {
			if (j < D) ANS[i + (1 << (K - 1))][j] = VR[i][j];
			if (j == D) ANS[i + (1 << (K - 1))][j] = R[D];
			if (j > D) ANS[i + (1 << (K - 1))][j] = VR[i][j - 1];
		}
	}
	return ANS;
}

int main() {
	int N, A, B;
	cin >> N >> A >> B;
	vector<int> L(N), R(N);
	for (int i = 0; i < N; i++) L[i] = A % 2, A /= 2, R[i] = B % 2, B /= 2;
	int COUNT = 0;
	for (int i = 0; i < N; i++) if (L[i] != R[i]) COUNT++;
	if (COUNT % 2 == 0) {
		cout << "NO" << endl;
		return 0;
	}
	cout << "YES" << endl;
	vector<vector<int> > V = Solve(L, R, N);
	for (int i = 0; i < (1 << N); i++) {
		int ANS = 0;
		for (int j = N - 1; j >= 0; j--) {
			ANS <<= 1;
			ANS += V[i][j];
		}
		cout << ANS << (i == (1 << N) - 1 ? '\n' : ' ');
	}
}

