int N, A, B;

int Insert(int t, int i, int b) {
  return (t >> i << (i+1)) + (b << i) + (t & ((1 << i)-1));
}

int Remove(int t, int i) {
  return (t >> (i+1) << i) | (t & ((1 << i)-1));
}

vector<int> Create(int n, int a, int b) {
  vector<int> ret;
  assert(n > 0);

  if (n == 1) {
    if (a == 0) assert(b == 1);
    if (a == 1) assert(b == 0);
    ret.eb(a);
    ret.eb(b);
    return ret;
  }

  rep(i, n) {
    int p = a >> i & 1;
    int q = b >> i & 1;
    assert(Insert(Remove(a, i), i, p) == a);
    assert(Insert(Remove(b, i), i, q) == b);
    if (p == q) {
      auto res = Create(n-1, Remove(a, i), Remove(b, i));
      for (int v : res) {
        ret.eb(Insert(v, i, p));
        ret.eb(Insert(v, i, p^1));
        p ^= 1;
      }
      assert(ret.front() == a);
      assert(ret.back() == b);
      return ret;
    }
  }

  auto res = Create(n-2, a >> 2, b >> 2);
  deque<int> gray = {0, 1, 3, 2};
  while (1) {
    int v = gray.front();
    if (v == a&3) break;
    gray.pop_front();
    gray.eb(v);
  }

  rep(i, 4) {
    gray.eb(gray[(i+3)%4]);
  }

  int m = res.size();
  assert(m%2 == 0);
  rep(i, m/2) {
    rep(i, 4) {
      ret.eb((res[i*2] << 2) | gray[i]);
    }

    rep(i, 4) {
      ret.eb((res[i*2+1] << 2) | gray[i+4]);
    }
    reverse(all(gray));
  }
  assert(ret.front() == a);
  assert(ret.back() == b);
  return ret;
}

int main() {
  scanf("%d%d%d", &N, &A, &B);

  if (__builtin_popcount(A^B)%2 == 0) {
    puts("NO");
    return 0;
  }

  puts("YES"); 
  auto ans = Create(N, A, B); 
  rep(i, 1 << N) {
    if (i) cout << " ";
    cout << ans[i];
  }
  cout << "\n";
}

