int numberOfSetBits(uint32_t i){
     i = i - ((i >> 1) & 0x55555555);
     i = (i & 0x33333333) + ((i >> 2) & 0x33333333);
     return (((i + (i >> 4)) & 0x0F0F0F0F) * 0x01010101) >> 24;
}
int findBit(int x, int N){
    for(int i=0;i<N;i++)
        if((x>>i)&1){
            return i;
        }
    throw(1);
}
void solve(int sizeOfFix, int N, int free, int A, int B){
    // printf("solve(%d,%d,%x,%x,%x);\n",sizeOfFix,N,free,A,B);
    int sizeOfRest=N-sizeOfFix;
    if(sizeOfRest==1){
        cout<<A<<endl;
        cout<<B<<endl;
    }else{
        int freeDifferBit=findBit(free&(A^B),N);
        int freeBit=findBit(free&(~(1<<freeDifferBit)), N);
        int A1=A^(1<<freeBit);
        int B1=A1^(1<<freeDifferBit);
        solve(sizeOfFix+1,N,free^(1<<freeDifferBit),A,A1);
        solve(sizeOfFix+1,N,free^(1<<freeDifferBit),B1,B);
    }
}
int main(){
    int N,A,B;
    cin>>N>>A>>B;
    if((numberOfSetBits(A) - numberOfSetBits(B))%2==0){
        cout<<"NO"<<endl;
    }else{
        solve(0,N,(1<<N)-1, A, B);
    }
}

