//	cout << m << endl;
	if(m==2){
		char c, d;
		string sol;
		c=y[0]+'0';
		d=y[1]+'0';
		sol+=c;
		sol+=d;
		return sol;
	}
	memset(bio, 0, sizeof(bio));
	bool l[2][maxn];
	queue < int > q[2];
	q[0].push(y[0]);
	q[1].push(y[1]);
	vector < int > dobri;
	unordered_map < int, bool > dob;
	int sz;
	int x;
	int xs;
	int br=0;
	bio[y[0]]=1;
	bio[y[1]]=1;
	while(!q[0].empty()){
		sz=q[0].size();
		for(int i=0; i<2; i++){
			for(int j=0; j<sz; j++){
				x=q[i].front();
				q[i].pop();
				for(int k=0; k<n; k++){
					xs=x^(1<<k);
					if(smijem[xs] && !bio[xs]){
//						cout << i << " " << xs << endl;
						l[i][xs]=1;
						bio[xs]=1;
						q[i].push(xs);
						if(br%2==0){
							if(i){
								dob[xs]=1;
							}
							else{
								dobri.push_back(xs);
							}
						}
					}
				}
			}
		}
		br++;
	}
	int dalje1[2], dalje2[2];
	for(int i=0; i<dobri.size(); i++){
		x=dobri[i];
		for(int j=0; j<n; j++){
			xs=x^(1<<j);
			if(dob[xs]){
//				cout << y[0] << " " << x << " " << xs << " " << y[1] << endl;
				dalje1[0]=y[0];
				dalje1[1]=x;
				dalje2[0]=xs;
				dalje2[1]=y[1];
				return rek(m/2, dalje1, l[0])+rek(m/2, dalje2, l[1]);
			}
		}
	}
}

