i64 N;
i64 A, B;

i64 MSB(i64 x, i64 n) {
    return x & (1<<(n-1));
}

i64 CLEAR_MSB(i64 x, i64 n) {
    return x & ~(1<<(n-1));
}

pair<bool,vector<i64>> f(i64 n, i64 a, i64 b) {
    if(n == 1) {
        if(a == b) return { false, {} };
        return { true, { a, b } };
    }

    i64 ha = MSB(a,n);
    i64 hb = MSB(b,n);
    i64 la = CLEAR_MSB(a,n);
    i64 lb = CLEAR_MSB(b,n);

    if(!ha  && !hb) {
        bool ok1; vector<i64> route1; tie(ok1,route1) = f(n-1,la,lb);
        if(!ok1) return { false, {} };
        bool ok2; vector<i64> route2; tie(ok2,route2) = f(n-1,la,route1[1]);
        if(!ok2) return { false, {} };

        vector<i64> res;
        res.reserve(1<<n);
        res.emplace_back(la);
        for(auto e : route2) {
            res.emplace_back((1<<(n-1)) | e);
        }
        FOR(i, 1, SIZE(route1)) {
            res.emplace_back(route1[i]);
        }
        return { true, res };
    }
    else if(!ha && hb) {
        if((la^1) == lb) return { false, {} };
        bool ok1; vector<i64> route1; tie(ok1,route1) = f(n-1,la^1,lb);
        if(!ok1) return { false, {} };
        bool ok2; vector<i64> route2; tie(ok2,route2) = f(n-1,la,la^1);
        if(!ok2) return { false, {} };

        vector<i64> res;
        res.reserve(1<<n);
        for(auto e : route2) {
            res.emplace_back(e);
        }
        for(auto e : route1) {
            res.emplace_back((1<<(n-1)) | e);
        }
        return { true, res };
    }
    else if(ha && !hb) {
        if((la^1) == lb) return { false, {} };
        bool ok1; vector<i64> route1; tie(ok1,route1) = f(n-1,la^1,lb);
        if(!ok1) return { false, {} };
        bool ok2; vector<i64> route2; tie(ok2,route2) = f(n-1,la,la^1);
        if(!ok2) return { false, {} };

        vector<i64> res;
        res.reserve(1<<n);
        for(auto e : route2) {
            res.emplace_back((1<<(n-1)) | e);
        }
        for(auto e : route1) {
            res.emplace_back(e);
        }
        return { true, res };
    }
    else if(ha && hb) {
        bool ok1; vector<i64> route1; tie(ok1,route1) = f(n-1,la,lb);
        if(!ok1) return { false, {} };
        bool ok2; vector<i64> route2; tie(ok2,route2) = f(n-1,la,route1[1]);
        if(!ok2) return { false, {} };

        vector<i64> res;
        res.reserve(1<<n);
        res.emplace_back((1<<(n-1)) | la);
        for(auto e : route2) {
            res.emplace_back(e);
        }
        FOR(i, 1, SIZE(route1)) {
            res.emplace_back((1<<(n-1)) | route1[i]);
        }
        return { true, res };
    }

    assert(false);
}

void solve() {
    bool ok; vector<i64> ans; tie(ok,ans) = f(N, A, B);

    if(!ok) {
        PRINTLN("NO");
    }
    else {
        PRINTLN("YES");
        PRINTLN(ans);
    }
}

signed main() {
    RD(N);
    RD(A); RD(B);

    solve();

    return 0;
}

#include<bits/stdc++.h>
using namespace std;

vector < int > solve1(int len){
	if(len == -1) return {0};
	vector < int > tmp1 = solve1(len - 1) , tmp2 = tmp1;
	reverse(tmp2.begin() , tmp2.end());
	for(auto t : tmp2) tmp1.push_back(t + (1 << len));
	return tmp1;
}

vector < int > solve(int len){
	if(len == 0) return {0 , 1};
	if(len == 2) return {0 , 1 , 3 , 2 , 6 , 4 , 5 , 7};
	vector < int > tmp1 = solve(len - 2) , tmp2;
	for(int i = 0 ; i < tmp1.size() ; ++i)
		if(tmp1[i] >> (len - 2) & 1){
			tmp2.push_back(tmp1[i]);
			tmp2.push_back(tmp1[i] | (1 << (len - 1)));
			tmp2.push_back(tmp1[++i] | (1 << (len - 1)));
			tmp2.push_back(tmp1[i]);
		}
		else tmp2.push_back(tmp1[i]);
	reverse(tmp1.begin() , tmp1.end());
	for(auto t : tmp1) tmp2.push_back(t | 1 << len);
	reverse(tmp1.begin() , tmp1.end());
	for(auto t : tmp1) tmp2.push_back(t | 1 << len | 1 << (len - 1));
	return tmp2;
}

int main(){
	int N , X , Y; cin >> N >> X >> Y; Y ^= X;
	if(!(__builtin_popcount(Y) & 1)){puts("NO"); return 0;}
	puts("YES"); vector < int > p , q;
	for(int i = 0 ; i < N ; ++i) Y >> i & 1 ? p.push_back(i) : q.push_back(i);
	vector < int > stp = solve(p.size() - 1) , tmp = solve1(q.size() - 1);
	for(auto t : stp){
		for(auto x : tmp){
			int val = 0;
			for(int i = 0 ; i < p.size() ; ++i)
				val |= (t >> i & 1) << p[i];
			for(int i = 0 ; i < q.size() ; ++i)
				val |= (x >> i & 1) << q[i];
			cout << (val ^ X) << ' ';
		}
		reverse(tmp.begin() , tmp.end());
	}
	return 0;
}

