int countbits(int bits)
{
    bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
    bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
    bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
    bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
    return (bits & 0x0000ffff) + (bits >>16 & 0x0000ffff);
}

VI solve() {
    int n,a,b;
    cin >> n >> a >> b;
    dump(n);
    dump(a);
    dump(b);
    if (countbits(a ^ b) % 2 == 0) {
        cout << "NO" << endl;
        return {};
    }
    cout << "YES" << endl;

    VI graycode(1<<(n-1)), rev(1<<(n-1));
    REP(i,0,1<<(n-1)) {
        graycode[i] = i ^ (i >> 1);
        rev[graycode[i]] = i;
    }

    //int au = graycode[a>>1], bu = graycode[b >> 1], al = a & 1, bl = b & 1;
    int au = a>>1, bu = b >> 1, al = a & 1, bl = b & 1;
    bool ltr = al == 0;
    int index = a>>1;

    VI ary;

    while (index != rev[bu]) {
        ary.push_back((graycode[index] << 1) + 1 - ltr);
        ary.push_back((graycode[index] << 1) + ltr);
        ltr = !ltr;
        index = (index + 1) % (1 << (n-1));
    }
    if (au == bu) {
        ary.push_back(a);
        index = (index + 1) % (1 << (n-1));
    }

    while (index != rev[au]) {
        ary.push_back((graycode[index] << 1) + 1 - ltr);
        index = (index + 1) % (1 << (n-1));
    }
    index = (index - 1 + (1 << (n-1))) % (1 << (n-1));
    ltr = !ltr;
    while (index != rev[bu]) {
        ary.push_back((graycode[index] << 1) + 1 - ltr);
        index = (index - 1 + (1 << (n-1))) % (1 << (n-1));
    }
    ary.push_back((graycode[index] << 1) + 1 - ltr);

    return ary;
}

