void make_poslist(V<ll> &samepos, V<ll> &diffpos, ll diffbits, ll n)
{
    rep (i, n) {
        if (diffbits & (1LL<<i)) diffpos.pb(i);
        else samepos.pb(i);
    }
}

void make_bitslist(V<ll> &bitslist, ll bitscnt)
{
    assert(bitscnt > 0LL);

    if (bitscnt == 1LL) {
        bitslist.pb(0LL);
        bitslist.pb(1LL);
        return;
    }

    V<ll> bitslist_base;
    make_bitslist(bitslist_base, bitscnt - 2LL);

    V<ll> rbitslist_base = bitslist_base;
    reverse(ALL(rbitslist_base));

    for (auto bits : bitslist_base) bitslist.pb((bits<<2LL) | 0LL);
    for (auto bits : rbitslist_base) bitslist.pb((bits<<2LL) | 1LL);
    rep (i, bitslist_base.size()) {
        ll bits = bitslist_base[i];
        if (i & 1LL) {
            bitslist.pb((bits<<2LL) | 2LL);
            bitslist.pb((bits<<2LL) | 3LL);
        }
        else {
            bitslist.pb((bits<<2LL) | 3LL);
            bitslist.pb((bits<<2LL) | 2LL);
        }
    }
}
void make_anslist_base(V<ll> &anslist,
                       const V<ll> &diffpos, const V<ll> &bitslist)
{
    for (auto bits : bitslist) {
        ll ans = 0LL;
        rep (i, diffpos.size()) {
            if (bits & (1LL << i)) ans |= (1LL << diffpos[i]);
        }
        anslist.pb(ans);
    }
}

void apply_samepos(V<ll> &anslist, ll pos)
{
    V<ll> anslist_new;

    rep (i, anslist.size()) {
        ll ans = anslist[i];
        if (!(i & 1LL)) {
            anslist_new.pb(ans);
            anslist_new.pb(ans | (1LL << pos));
        }
        else {
            anslist_new.pb(ans | (1LL << pos));
            anslist_new.pb(ans);
        }
    }

    anslist = anslist_new;
}

