using namespace std;

int n, a, b;

int pop(int x)
{
	int ret = 0;
	for(;x;x/=2) ret += x%2;
	return ret;
}

int ins(int x, int i, int v)
{
	int m = 1<<i;
	int ret = x / m * m * 2 + x % m + v * m;
	return ret;
}

int del(int x, int i)
{
	int m = 1<<i;
	int ret = x / (m*2) * m + x % m;
	return ret;
}

vector<int> calc(int n, int a, int b)
{
	vector<int> ret;
	if(n == 1){
		ret.push_back(a);
		ret.push_back(b);
		return ret;
	}

	int p;
	vector<int> res1, res2;
	for(int i = 0; i < n; i++){
		if( (a^b) & (1<<i) ){
			p = i;
			int na = del(a, p), nb = del(b, p), m = na^1;
			res1 = calc(n-1, na, m);
			res2 = calc(n-1, m, nb);
			break;
		}
	}
	for(int i = 0; i < res1.size(); i++) ret.push_back(res1[i]);
	for(int i = 0; i < res2.size(); i++) ret.push_back(res2[i]);

	for(int i = 0; i < ret.size()/2; i++) ret[i] = ins(ret[i], p, (a>>p)&1);
	for(int i = ret.size()/2; i < ret.size(); i++) ret[i] = ins(ret[i], p, 1 - ((a>>p)&1));
	return ret;
}

int main(void)
{
	cin >> n >> a >> b;

	if(pop(a)%2 == pop(b)%2){
		cout << "NO" << endl;
		return 0;
	}

	vector<int> ans = calc(n, a, b);
	cout << "YES" << endl;
	for(int i = 0; i < ans.size(); i++) cout << ans[i] << " "; cout << endl;

	return 0;
}

