int count(int x)
{
    int sum = 0;
    while (x)
    {
        sum += (x & 1);
        x >>= 1;
    }
    return sum;
}
void work(int*a, int n, int A, int B)
{
    if (!n)
    {
        a[0] = A;
        return;
    }
    if (n == 1)
    {
        a[0] = A;
        a[1] = B;
        return;
    }
    int sig = 0;
    while (((1 << sig) & A) == ((1 << sig) & B)) sig++;
    work(a, n - 1, (A & ((1 << (sig)) - 1)) + ((A >> (sig + 1)) << (sig)),((A & ((1 << (sig)) - 1)) + ((A >> (sig + 1)) << (sig))) ^ 1);

    work(a + (1 << (n - 1)), n - 1, ((A & ((1 << (sig)) - 1)) + ((A >> (sig + 1)) << (sig))) ^ 1, ((B & ((1 << (sig)) - 1)) + ((B >> (sig + 1)) << (sig))));
    for (int i = 0; i < (1 << (n - 1)) ; i ++)
        a[i] = ((a[i] >> (sig)) << (sig + 1)) + (a[i] & ((1 << (sig)) - 1)) + (A & (1 << sig));
    for (int i = (1 << (n - 1)); i < (1 << n) ; i ++)
        a[i] = ((a[i] >> (sig)) << (sig + 1)) + (a[i] & ((1 << (sig)) - 1)) + (B & (1 << sig));
}
