    scanf("%d%d%d", &n, &a, &b);
    if (!(__builtin_popcount(b ^ a) & 1))
        return !printf("NO");
    vector < int > R = Solve(n, b ^ a);
    printf("YES\n");
    for (int r : R)
        printf("%d ", r ^ a);
    return 0;
}

