using namespace std;

int n, a, b;

bool check_bit (int _a, int _bit) { return (_a >> _bit) & 1; }

int remove_bit (int _a, int _bit) {
    return (_a & ( (1 << _bit) - 1) ) | ( (_a >> (_bit + 1) ) << _bit);
}

int insert_bit (int _a, int _bit, bool val) {
    int tmp = (_a & ( (1 << _bit) - 1) ) | ( (_a >> (_bit) ) << (_bit + 1) );
    if (val) tmp |= (1 << _bit);
    return tmp;
}

vector<int> solve (int LOG, int be, int en) {
    if (LOG == 1) return vector<int>{ be, en };
    int diff = 0;
    while (diff < LOG) {
        if (check_bit(be, diff) != check_bit(en, diff) ) break ;
        ++diff;
    }
    bool diff_left = check_bit(be, diff);

    be = remove_bit(be, diff);
    en = remove_bit(en, diff);

    vector<int> left = solve(LOG - 1, be, be ^ 1),
                right = solve(LOG - 1, be ^ 1, en),
                ret;
    for (int _ : left) ret.push_back(insert_bit(_, diff, diff_left) );
    for (int _ : right) ret.push_back(insert_bit(_, diff, diff_left ^ 1) );

    return ret;
}

int main () {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

    cin >> n >> a >> b;

    if (!(__builtin_popcount(a ^ b) & 1) ) return cout << "NO\n", 0;
    cout << "YES\n";

    vector<int> ans = solve(n, a, b);

    for (auto _ : ans) cout << _ << ' '; cout << '\n';

    return 0;
}

