    for (int i = (1 << (bit - 1)) - 1; i >= 0; -- i){
        vec.push_back(1 << (bit - 1) | vec[i]);
    }
    return vec;
}

std::vector <int> solve(int bit, bool flag){
    std::vector <int> vec;
    for (int i = 0; i < n; ++ i){
