bool find2(int N, int A, int B)
{
	vector<char>used(1 << N);
	used[A] = true;

	vector<bitset<17>>order;
	order.push_back(A);

	vector<int>changed(N);

	int dame = 0;
	int cnt = 1;
	int bit = 0;
	for (int i = 0; i < N; i++)if (A&(1 << i))bit++;

	while (A != B)
	{
		int r = rnd.nextInt() % N;
		//if (cnt == (1 << (N - 1)))r = 0;

		//int nbit = 0;
		//if (A&(1 << r))nbit = bit-1;
		//else nbit = bit+1;

		int b = A ^ (1 << r);

		if (used[b] || (cnt != (1 << N) - 1 && b == B))
		{
			dame++;
			if (dame > 3 * N)break;
			continue;
		}

		changed[r]++;
		for (int i = 0; i < N; i++)
		{
			cerr << i << " " << changed[i] << endl;
		}cerr << endl;

		//if (A&(1 << r))bit--;
		//else bit++;
		//cerr<<cnt<<" "<<bit<<endl;

		A = b;
		used[A] = true;
		cnt++;
		dame = 0;
		order.push_back(A);
	}

	if (dame <= 3 * N)
	{
		for (int i = 0; i < N; i++)
		{
			cerr << i << " " << changed[i] << endl;
		}
		for (int i = 0; i < order.size(); i++)
		{
			cerr << order[i].to_string() << endl;
		}
		return true;
	}

	return false;
}

void find(int N, int A, int B)
{
	Timer tmr(1.1);
	while (tmr.Over() == false)
	{
		if (find2(N, A, B))break;
	}

