void solve(int N, int A, int B, int r, int c)
{
	cerr<<r<<" " <<c<<" "<<A<<" "<<B<<endl;
	int cnt = 0;
	vector<int>index1;
	for (int i = 0; i < N; i++)
	{
		bool a = (A >> i) & 1;
		bool b = (B >> i) & 1;

		if (a^b)
		{
			index1.push_back(i);
			cnt++;
		}
	}

	int nA = 0;
	int nB = (1 << cnt) - 1;

	for (int i = (1 << (N - 1)); i < (1 << N); i++)
	{
		ans[r][c + i] = 1;
	}

	if (N == 1)
	{

		for (int i = (int)index1.size() - 1; i >= 0; i--)
		{
			int i2 = index1[i];

			for (int j = 0; j < (1 << N); j++)
			{
				swap(ans[r + i2][c + j], ans[r + cnt - 1][c + j]);
			}
			cnt--;
		}

		for (int i = 0; i < N; i++)
		{
			for (int j = 0; j < (1 << N); j++)
			{
				ans[r + i][c + j] = ((A >> i) & 1) ^ ans[r + i][c + j];
			}
		}

		return;
	}

	solve(N - 1, 0, 1, r + 1, c);
	solve(N - 1, 1, nB >> 1, r + 1, c + (1 << (N - 1)));

	for (int i = (int)index1.size() - 1; i >= 0; i--)
	{
		int i2 = index1[i];

		for (int j = 0; j < (1 << N); j++)
		{
			swap(ans[r + i2][c + j], ans[r + cnt - 1][c + j]);
		}
		cnt--;
	}

	for (int i = 0; i < N; i++)
	{
		for (int j = 0; j < (1 << N); j++)
		{
			ans[r + i][c + j] = ((A >> i) & 1) ^ ans[r + i][c + j];
		}
	}
}

