					continue;
				}
				int fail = 0;
				for (int j = 1; j < back; j++) {
					if (!check(vec[j - 1], vec[j])) {
						fail = 1;
						break;
					}
				}
				if (fail) {
				//	printf(" Case 4\n");
					continue;
