vector <int> get(int n, int mask, int fixMask, int st, bool khare) {
	if(st == n) {
		vector <int> res;
		res.push_back(mask);
		return res;
	}
	if(fixMask >> st & 1)
		return get(n, mask, fixMask, st + 1, khare);
	vector <int> L = get(n, mask, fixMask, st + 1, khare);
	revxor(L, (1 << st));
	if(khare)
		reverse(L.begin(), L.end());
	cerr << n << ", " << mask << ", " << fixMask << ", " << st << ": ";
	for(int x : L)
		cerr << x << " ";
	cerr << endl;
	return L;
}

vector <int> solve(int n, int st, vector <int> bits, int mask = 0, int fixMask = 0, bool khare = false) {
	if(st == 0) {
		int i =	bits[st];
		cerr << "ST: " << i << endl;
		vector <int> A = solve(n, st + 1, bits, mask, fixMask | (1 << i), false);
		vector <int> B = A;
		reverse(B.begin(), B.end());

		for(int &x : B)
			x ^= (1 << bits[st]);
		for(int i = 1; i < bits.size(); i += 2) {
			int a = bits[i];
			int b = bits[i + 1];
			for(int &x : B) {
				x ^= (1 << bits[st]);
				if((x >> b & 1) && (x >> a & 1)==0)
					continue;
				x ^= (1 << a);
				x ^= (1 << b);
			}
		}
//		cerr << "ST -" << endl;
//		vector <int> B = solve(n, st + 1, bits, mask | (1 << i), fixMask | (1 << i), true);
		for(int x : B)
			A.push_back(x);
		return A;
	}
	if(st == bits.size()){
		vector <int> A = get(n, mask, fixMask, 0, false);
		if(khare && bits.size()<3)
			reverse(A.begin(), A.end());
		return A;
	}
	int i =	bits[st];
	int j = bits[st + 1];
	cerr << "Here! " <<  i << ", " << j << endl;
	vector <int> A;
	if(khare == false) {
		A = solve(n, st + 2, bits, mask, (fixMask | (1 << i) | (1 << j)), khare);
		revxor(A, (1 << i));
		revxor(A, (1 << j));
	}
	else {
		A = solve(n, st + 2, bits, mask | (1 << j), (fixMask | (1 << i) | (1 << j)), khare);
		revxor(A, (1 << j));
		revxor(A, (1 << i));
	}
	cerr << i << " => ";
	for(int x : A)
		cerr << x << " ";
	cerr << endl;
	return A;
}

