    ll size = 1LL << (n - okbit);
    for (ll j = 0; j < size * 2; j++) {
      if (j % size == 0)
        continue;
      if (j % (size >> 2) == 0) {
        ans[j] = diff[i + c % 2];
        c++;
      }
    }
    for (ll j = size * 2; j < (1LL << n); j++) {
      if (j % size == 0)
        continue;
      if (j % (size >> 1) == 0) {
        ans[j] = diff[i];
      } else if (j % (size >> 2) == 0) {
        ans[j] = diff[i + 1];
      }
    }
    okbit += 2;
  }
  for (int i = 0; i < same.size(); i++) {
    ll size = 1LL << (n - okbit);
    for (ll j = 0; j < (1LL << n); j++) {
      if (j % size == 0)
        continue;
      if (j % (size >> 1) == 0) {
        ans[j] = same[i];
      }
    }
    okbit++;
  }

