  used[ans[0]] = true;
  cout << "YES" << endl;
  cout << ans[0];
  for (int i = 1; i < (1LL << n); i++) {
    ans[i] = ans[i - 1] ^ (1LL << (ans[i]));
    used[ans[i]] = true;
    cout << " " << ans[i];
  }
  cout << endl;

  return true;
  if (ans[(1LL << n) - 1] == b) {
    cerr << "same" << endl;
    bool ok = true;
    for (int i = 0; i < (1LL << n); i++)
      if (!used[i])
        ok = false;
    if (!ok) {
      cerr << "ng" << endl;
      return false;
    }
  } else {
    cerr << ans[(1LL << n) - 1] << endl;
    return false;
  }
  return true;
}

