void swapBit(int u, int v, int L, int R) {
    int mask = (1 << u) ^ (1 << v);
    for(int i = L; i < R; i++){
        int s1 = (ans[i] >> u) & 1;
        int s2 = (ans[i] >> v) & 1;
        if (s1 != s2) ans[i] ^= mask;
    }
}
void build(int depth, int L, int R, int st, int en) {
    assert(st < (1 << depth));
    assert(en < (1 << depth));
    int nen = en ^ st;

    vector<int> diff;
    for(int i = 0; i < depth; i++) if ((nen >> i) & 1) 
        diff.push_back(i);
    int ndiff = diff.size();

    if (ndiff == 1) {
        for(int i = L; i < R; i++) ans[i] = gray[i - L];
        swapBit(diff[0], depth - 1, L, R);
        for(int i = L; i < R; i++) ans[i] ^= st;
        return;
    }
    int half = 0;
    for(int i = 0; i < ndiff / 2; i++) 
        half |= 1 << diff[i];

    int mid = (L + R) / 2;
    build(depth - 1, L, mid, 0, half); 
    build(depth - 1, mid, R, half, (1 << diff.back()) ^ nen);
    for(int i = mid; i < R; i++)
        ans[i] ^= 1 << (depth - 1);
    swapBit(diff.back(), depth - 1, L, R);
    for(int i = L; i < R; i++) ans[i] ^= st;
}
