using namespace std;

vector<int> solve(int l, int r, int ind){
	vector<int> ans;
	if(ind == 0){
		ans={l&1,r&1};
		return ans;
	}
	if(((l>>ind)&1) == ((r>>ind)&1)){
		ans.resize(1<<(ind+1));

		auto sub = solve(l,r,ind-1);
		if((l>>ind)&1){
			for(int i=0; i<sub.size();i+=2){
				ans[2*i]=sub[i]+(1<<ind);
				ans[2*i+1]=sub[i];
				ans[2*i+2]=sub[i+1];
				ans[2*i+3]=sub[i+1]+(1<<ind);
			}
		}
		else{
			for(int i=0; i<sub.size();i+=2){
				ans[2*i]=sub[i];
				ans[2*i+1]=sub[i]+(1<<ind);
				ans[2*i+2]=sub[i+1]+(1<<ind);
				ans[2*i+3]=sub[i+1];
			}

		}
	}
	else{
		auto subl = solve(l,l^1,ind-1), subr = solve(l^1,r,ind-1);
		ans.insert(ans.end(),subl.begin(),subl.end());
		ans.insert(ans.end(),subr.begin(),subr.end());
		for(int i=(1<<ind); i<(1<<(ind+1)); i++){
			ans[i]+=(1<<ind);
		}
	}
	return ans;
}

