#define fo(i,j,k) for(int i=j;i<=k;++i)
#define fd(i,j,k) for(int i=j;i>=k;--i)
using namespace std;
const int N=1<<17;
int a[N];
void wap(int &t,int x,int y){
	int t1=(t&(1<<x))>0,t2=(t&(1<<y))>0;
	t=t^(t1<<x)^(t2<<y)^(t2<<x)^(t1<<y);
}
int count(int k,int t){
	int cnt=0;
	fo(i,0,k-1) if(t>>i&1) ++cnt;
	return cnt;
}
int cut(int k,int t){
	return t^(t&(1<<k));
}
void solve(int k,int A,int B,int l,int r){
	if(k==1){
		a[l]=A,a[r]=B;
		return;
	}
	int p;
	fd(i,k-1,0)
	if((A>>i&1)!=(B>>i&1)) {p=i;break;}
	wap(A,p,k-1),wap(B,p,k-1);
	int num=count(k-1,A),mid=(l+r)>>1;
	int t=num&1?0:1,P=A&(1<<(k-1)),Q=B&(1<<(k-1));
	solve(k-1,cut(k-1,A),t,l,mid);
	solve(k-1,t,cut(k-1,B),mid+1,r);
	fo(i,l,mid) a[i]^=P;
	fo(i,mid+1,r) a[i]^=Q;
	fo(i,l,r) wap(a[i],p,k-1);
}
int main()
{
	int n,S,T;
	scanf("%d %d %d",&n,&S,&T);
	int cnt=0;
	fo(i,0,n-1) if((S>>i&1)!=(T>>i&1)) ++cnt;
	if(!(cnt&1)) return printf("NO"),0;
	solve(n,S,T,0,(1<<n)-1);
	printf("YES\n");
	fo(i,0,(1<<n)-1) printf("%d ",a[i]); 
}

