class CDifferBy1Bit {
	class Solver {
		io::input_reader in;
		io::output_writer out;

	public:
		Solver(std::istream &in, std::ostream &out) : in(in), out(out) {}

		vector<int> indexesOfOne(int x) {
			vector<int> indexes;
			int i = 0;
			while (x) {
				if (x & 1) indexes.push_back(i);
				i++;
				x >>= 1;
			}
			return indexes;
		}

		int printComplete(int mask, int a) {
			vector<int> res, indexes = indexesOfOne(mask);
			res.push_back(a);
			for (int i: indexes) {
				int s = res.size();
				fori(j, s) res.push_back(res[s - 1 - j] ^ (1 << i));
			}
			out << res << ' ';
			return res.back();
		}

		void printSeq(int mask, int a, int b) {
			int x = a ^b;
			if ((mask & (mask - 1)) == 0) {
				out << a << ' ' << b;
				return;
			}
			fori(i, 30) {
				if ((1 << i) & x) {
					int bit = 1 << i;
					mask ^= bit;
					a = printComplete(mask, a);
					printSeq(mask, a ^ bit, b);
					return;
				}
			}
		}

		void solve() {
			int n, a, b;
			in.read(n, a, b);
			{
