const int N = (1 << 17);
int p[N];

int cut(int n, int k) {
    int l = (n >> (k + 1)) << k;
    int r = n & ((1 << k) - 1);
    return l | r;
}

int glue(int n, int k, int val) {
    int l = (n >> k) << (k + 1);
    int r = n & ((1 << k) - 1);
    int res = l | r;
    if (val) {
        res |= (1 << k);
    }
    return res;
}

void solve(int n, int a, int b, int pos) {
    if (n == 1) {
        p[pos] = a;
        p[pos + 1] = b;
        return;
    }
    int k = -1;
    for (int i = 0; i < n; i++) {
        if ((a ^ b) >> i & 1) {
            k = i;
            break;
        }
    }
    assert(k != -1);
    int c = cut(a, k) ^ 1;
    solve(n - 1, cut(a, k), c, pos);
    solve(n - 1, c, cut(b, k), pos + (1 << (n - 1)));
    for (int i = pos; i < pos + (1 << (n - 1)); i++) {
        p[i] = glue(p[i], k, (a >> k & 1));
    }
    for (int i = pos + (1 << (n - 1)); i < pos + (1 << n); i++) {
        p[i] = glue(p[i], k, (b >> k & 1));
    }
}

