typedef vector<ll> Array;

ll popcount(ll x) {
	x = (x & 0x5555555555555555) + (x >> 1 & 0x5555555555555555);
	x = (x & 0x3333333333333333) + (x >> 2 & 0x3333333333333333);
	x = (x & 0x0F0F0F0F0F0F0F0F) + (x >> 4 & 0x0F0F0F0F0F0F0F0F);
	x = (x & 0x00FF00FF00FF00FF) + (x >> 8 & 0x00FF00FF00FF00FF);
	x = (x & 0x0000FFFF0000FFFF) + (x >> 16 & 0x0000FFFF0000FFFF);
	x = (x & 0x00000000FFFFFFFF) + (x >> 32 & 0x00000000FFFFFFFF);

	return x;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	ll n, a, b;
	cin >> n >> a >> b;
	if (popcount(a) % 2 == popcount(b) % 2) {
		cout << "NO" << "\n";
		return 0;
	}
	Array ans;
	ans.push_back(a);
	auto solve = [&](auto solve, ll a, ll b, ll used)->void {
		REP(i, n) {
			if (used & (1LL << i))continue;
			if ((a ^ b) & (1LL << i)) {
				used += 1LL << i;
				ll t = -1;
				REP(j, n) {
					if (used & (1LL << j)) continue;
					t = 1LL << j;
					break;
				}
				if (t != -1) {
					solve(solve, a, a ^ t, used);
					ll d = a ^ t ^ (1LL << i);
					ans.push_back(d);
					solve(solve, d, b, used);
				}
				else ans.push_back(b);
				break;
			}
		}
