using namespace std;

typedef vector<int> vi;

int bc(int x) {
    int r = 0;
    while (x) {
        r += x % 2;
        x /= 2;
    }
    return r;
}

void proc(int n, int b, int x, vi &v) {
    cout << n << " " << b << " " << x << endl;

    if (n == 0) {
        v.push_back(x);
        v.push_back(b ^ x);
        return;
    }

    if ((b >> n) == 0) {
        proc(n - 1, b, x, v);
        int l1 = v[v.size()-1] ^ x;
        int l2 = v[v.size()-2] ^ x;
        v.resize(v.size()-1);
        b = l1 ^ l2;
        x ^= l2 ^ (1 << n);
        proc(n - 1, b, x, v);
        v.push_back(l1);
    } else {
        proc(n - 1, 1, x, v);
        b ^= (1 ^ (1 << n));
        x ^= (1 ^ (1 << n));
        proc(n - 1, b, x, v);
    }
}

