int n;
ll a, b;

void NO() {
  cout << "NO" << endl;
  exit(0);
}

int popcount(int x) {
  x = (x & 0x55555555) + ((x & 0xAAAAAAAA) >> 1);
  x = (x & 0x33333333) + ((x & 0xCCCCCCCC) >> 2);
  x = (x & 0x0F0F0F0F) + ((x & 0xF0F0F0F0) >> 4);
  x = (x & 0x00FF00FF) + ((x & 0xFF00FF00) >> 8);
  x = (x & 0x0000FFFF) + ((x & 0xFFFF0000) >> 16);
  return x;
}

int op0(int e, int p) {
  int mask = (1 << (p - 1)) - 1;
  int mask2 = ~mask;
  return (
      (mask & e)
      ) | (
        (mask2 & e) << 1
        );
}
void op(int &e, int p) {
  e = op0(e, p);
}

vector<int> solve(int a, int b, int n) {
  b ^= a;
  vector<int> v;
  dump(n, b);
  if(n == 1) {
    if(b == 0) NO();
    v = {0, 1};
  }
  if(n == 2) {
    if(b == 0b01) v = {0, 2, 3, 1};
    else if(b == 0b10) v = {0, 1, 3, 2};
    else NO();
  }
  if(n >= 3) {
    int bc = popcount(b);
    dump(bc);
    if(bc == 0) {
      NO();
    } else if(bc == 1) {
      int bo = 0;
      for(int i = 0; i < n; i++) if(b & (1 << i)) bo = i;
      v = solve(0, (1 << (n - 1)) - 1, n - 1);
      auto w = v;
      dump(v);
      reverse(begin(w), end(w));
      for(auto &e : w) op(e, bo + 1);
      for(auto &e : w) e ^= 1 << bo;
      for(auto &e : v) op(e, bo + 1);
      v.insert(v.end(), w.begin(), w.end());
    } else if(bc == n) {
      if(n % 2 == 0) NO();
      v = solve(0, 1, n - 1);
      auto u = solve(1, (1 << (n - 1)) - 1, n - 1);
      dump(n, u);
      for(auto &e : u) e ^= 1 << (n - 1);
      // dump(u);
      // dump(v);
      v.insert(v.end(), u.begin(), u.end());
    } else {
      int re = n - bc;
      // dump(b, n, bc, re);
      auto w = re >= 3 ? solve(0, (1 << re) - 1, re) : solve(0, 1, re);
      for(int i = 0; i < n; i++) if((b & (1 << i))) {
        // dump(i);
        for(auto &e : w) op(e, i + 1);
      }
      auto u = solve(0, (1 << bc) - 1, bc);
      for(int i = 0; i < n; i++) if(!(b & (1 << i))) for(auto &e : u) op(e, i + 1);
      auto wrev = w;
      reverse(wrev.begin(), wrev.end());
      dump(w);
      dump(u);

      int c = 0;
      for(auto e1 : u) {
        c ^= 1;
        auto &x = c ? w : wrev;
        for(auto e2 : x) {
          v.push_back(e1 ^ e2);
        }
      }
    }
  }

  dump(v);
  for(auto &e : v) e ^= a;
  return v;
}

