std::vector<int> combine(std::vector<int> &a, std::vector<int> &b)
{
	std::vector<int> res;
	for (int i = 0; i < a.size(); i++)
	{
		if (i & 1)
			res.push_back(b[i]);
		res.push_back(a[i]);
		if (i & 1 ^ 1)
			res.push_back(b[i]);
	}
	return res;
}
