int main() {
	int N, A, B;
	cin >> N >> A >> B;

	set< int > used;
	set< int > neg;
	for (int i=0; i<N; ++i) neg.insert(B ^ (1 << i));

	used.insert(B);

	vector< int > perm;
	int cur = A;

	while (1) {
		used.insert(cur);
		neg.erase(cur);
		perm.push_back(cur);

		int nxt = -1;
		for (int i=0; i<N; ++i) {
			int p = cur ^ (1 << i);
			if (neg.count(p) == 1 && neg.size() == 1 && (int)used.size() < (1<<N)-1) continue;
			if (used.count(p) == 0) {
				nxt = p;
				break;
			}
		}

		if (nxt == -1) break;
		cur = nxt;
	}
	perm.push_back(B);

	if ((int)used.size() != (1<<N)) {
		cout << "NO" << endl;
	}
	else {
		cout << "YES" << endl;
		for (int i=0; i<(1<<N); ++i) cout << perm[i] << (i < (1<<N)-1 ? " " : "\n");
	}
}
