pair<int,int> reduce(int a, int b)
{
    for (int d=17; d>=0; d--) {
        if ((a&(1<<d)) == (b&(1<<d))) {
            if ((a&(1<<d)) and (b&(1<<d))) {
                a ^= 1<<d; 
                b ^= 1<<d; 
            }
        }
        else 
            break; 
    }
    return {a,b}; 
}

vector<int> build_path(int a, int b, int lv, int offset)
{
    pr("build_path") pr(a) pr(b) pr(lv) pr(offset) nl 
    // assert(a < (1<<lv)); 
    // assert(b < (1<<lv)); 
    if (a == b) {
        // not possible 
        return vector<int>(); 
    }
    int dif = a^b; 
    int common_lv = 0; 
    for (; dif >= (1<<common_lv); common_lv++) ; 

    int aa, bb;
    tie(aa,bb) = reduce(a,b);
    // offset += a - aa; 
    int new_offset = a - aa; 
    bool swapped = false; 
    if (aa > bb) {
        swap(aa,bb);
        swapped = true; 
    }
    pr("reduced to") pr(aa) pr(bb) pr(common_lv) pr(offset+new_offset) nl 

    vector<int> path;
    if (common_lv == 1) {
        // base case 
        path.pb(aa + offset+new_offset); 
        path.pb(bb + offset+new_offset); 
    }
    else {
        vector<int> part1 = build_path(aa, aa^1, common_lv-1, offset+new_offset); 
        vector<int> part2 = build_path((aa^1)^(1<<(common_lv-1)), bb, common_lv-1, offset+new_offset); 
        if (part1.empty() or part2.empty())
            return vector<int>(); 
        for (int x : part1)
            path.pb(x);
        for (int x : part2)
            path.pb(x); 
    }    

    // nl pr(a) pr(b) nl 
    // printv(path) 
    for (; common_lv < lv; common_lv++) {
        int start = (path[sz(path)-2]-offset) ^ (1<<(common_lv)); 
        int end = (path[sz(path)-1]-offset) ^ (1<<(common_lv)); 
        pr("inserting path") pr(start) pr(end) pr(common_lv) nl 
        vector<int> subpath = build_path(start, end, common_lv, offset); 
        path.insert(path.end()-1, all(subpath)); 
    }

    if (swapped) {
        reverse(all(path)); 
    }
    return path; 
}

