void put_res(int value, int first) {
	if(first==0) printf(" ");
	int ret=0;
	int dig = 0;
	for(int i=0;i<nndiff;i++) {
		if(value&(1<<dig)) ret+=(1<<N_diff[i]);
		dig++;
	}
	for(int i=0;i<nnsame;i++) {
		if(value&(1<<dig)) ret+=(1<<N_same[i]);
		dig++;
	}
	printf("%d", A ^ ret);
}
int run[100008];
int main() {
	scanf("%d%d%d", &N, &A, &B);
	for(int i=0;i<N;i++) {
		if((A^B)&(1<<i)) {
			N_diff[nndiff++] = i;
		} else {
			N_same[nnsame++] = i;
		}
	}
	if((nndiff % 2) == 0) {
		printf("NO\n");
		return 0;
	}
	printf("YES\n");
	int cur = 0;
	for(int i=0;i<(1<<(N-1));i++) {
		visited[cur] = 1;
		run[i] = cur;
		int dig = 0;
		while(visited[cur ^ (1<<dig)]) dig++;
		cur ^= (1<<dig);
	}
	int ng = (1<<(nndiff-1)) - 1;
	put_res(0, 1);
	if(ng == 0) {
		int cnt = (1<<(N-1)) - 1;
		cur = run[cnt] * 2;
		int flg = 0;
		while(cnt) {
			put_res(cur + flg, 0);
			flg = 1 - flg;
			put_res(cur + flg, 0);
			cnt--;
			cur = run[cnt] * 2;
		}
		put_res(1, 0);
	} else {
		int cnt = 0;
		int next = run[cnt + 1];
		while(next != ng) {
			put_res(next * 2, 0);
			cnt++;
			next = run[cnt + 1];
		}
		for(int j=cnt;j>=0;j--) put_res(run[j] * 2 + 1, 0);
		int cnt2 = (1<<(N-1)) - 1;
		int flg = 1;
		while(cnt < cnt2) {
			put_res(run[cnt2] * 2 + flg, 0);
			flg = 1 - flg;
			put_res(run[cnt2] * 2 + flg, 0);
			cnt2--;
		}
	}
	printf("\n");
	return 0;
}

