    cout << v << endl;
    visited[v] = true;
    if(v == B){
        return;
    }
    auto max_ham_tuple = make_tuple(-1, 0, 0);
    for(int i=0;i<N;i++){
        int nv = v ^ (1 << i);
        if(visited[nv]) continue;
        if((v >> i)&1){
            max_ham_tuple = max(max_ham_tuple, make_tuple(__builtin_popcount(nv ^ B), 1, i));
        }else{
            max_ham_tuple = max(max_ham_tuple, make_tuple(__builtin_popcount(nv ^ B), 0, i));
        }
    }
    int i = get<2>(max_ham_tuple);
    dfs(v ^ (1 << i));
}

