bool resuelveCaso() {
	int n;
	cin >> n;
	if (!cin) return false;
	int a, b;
	cin >> a >> b;

	int tot = pow(2, n);

	vb marcaje(tot, true);
	marcaje[a] = false;
	marcaje[b] = false;

	//Construimos la solución
	int cont = 2;
	vi sol; sol.push_back(a);
	int nAct = a;

	while (true) {
		if (cont == tot) break;

		for (int i = 1; i <= tot; i *= 2) {
			if (i <= nAct && (nAct & i) != 0) {
				int nSig = (nAct & ~i);
				if (marcaje[nSig]) {
					sol.push_back(nSig);
					marcaje[nSig] = false;
					nAct = nSig;
					goto sig;
				}
			}
			else if (nAct + i < tot && (nAct & i) == 0) {
				int nSig = (nAct | i);
				if (marcaje[nSig]) {
					sol.push_back(nSig);
					marcaje[nSig] = false;
					nAct = nSig;
					goto sig;
				}
			}
		}

		break;
	sig:;
		++cont;
