vector<int> grayCode(int n) {
  int temp = 1;
  vector<int> ans{0};
  while (n--) {
    for (int i = ans.size() - 1; i >= 0; i--) {
      ans.push_back(temp | ans[i]);
    }
    temp <<= 1;
  }
  return ans;
}

int get(int num, int n, int d, int a) {
  bool bn = num & n, bd = num & d;
  if (bn) num |= d;
  else num &= ~d;
  if (bd) num |= n;
  else num &= ~n;
  return num ^ a;
}

