void work(int pos)
{
	for (int i = 0; i < tot; i++)
	{
		if (pos > i)
		{
			ans[i] = per[N][i];
			continue;
		}
		int t = (i - pos) / 2 + 1;
		if (t & 1)
			ans[(1 << N) - 1 - (t >> 1 << 1) - (~i & 1)] = per[N][i];
		else
			ans[i - t] = per[N][i];
	}
}

