vector<ll> find_ans(ll c,vector<ll> bits){
	vector<ll> ans,tmp;
	if(bits.size()==1){
		ans.pb(0);
		ans.pb(c);
		return ans;
	}
	if(__builtin_popcount(c)==1){
		ll sef;
		for(auto e:bits){
			if(((c>>e)&1)==0){
				sef=e;
				break;
			}
		}
		for(auto e:bits){
			if((c>>e)&1){
				vector<ll> bits2;
				for(auto ee:bits){
					if(ee!=e){
						bits2.pb(ee);
					}
				}
				ans=find_ans(1<<sef,bits2);
				tmp=ans;
				ll base=(1<<e)^(1<<sef);
				for(auto r:tmp){
					ans.pb(r^base);	
				}
				return ans;
			}
		}	
	}else{
		for(ll i=0;i<bits.size();i++){
			ll a=bits[i];
			if((c>>a)&1){
				for(ll j=i+1;j<bits.size();j++){
					ll b=bits[j];
					if((c>>b)&1){
						vector<ll> bits2;
						for(auto e:bits){
							if(e!=a){
								bits2.pb(e);
							}
						}
						ll cc=(c^(1<<a)^(1<<b));

						ans=find_ans(cc,bits2);
						ll base=ans.back()^(1<<a);
						tmp=find_ans((1<<b),bits2);
						for(auto e:tmp){
							ans.pb(e^base);
						}
						return ans;
					}
				}
			}
		}

	}
}
