int bit_count(unsigned x){
    int ret = 0;
    while(x > 0){
        ret += x & 1;
        x >>= 1;
    }
    return ret;
}

vector<int> code(int N, int A, int B){
    if(N == 1) return {A, B};
    int dif = A^B;
    dif = dif & -dif;
    int mask = dif;
    int e = 1 << (N-1);
    while(mask < e){
        mask <<= 1;
        mask |= dif;
    }
    int pA = (A & ~mask) + (((A & mask) >> 1) & mask);
    int C = pA ^ 1;
    int pB = (B & ~mask) + (((B & mask) >> 1) & mask);

    auto Q = code(N-1, pA, C);
    auto R = code(N-1, C, pB);
    for (auto &&q : Q) {
        q = (q & ~mask) + (A & dif) +((q & (mask)) << 1);
    } // end q
    for (auto &&r : R) {
        r = (r & ~mask) + (B & dif) +((r & (mask)) << 1);
        Q.push_back(r);
    } // end r

    return Q;
}

