ull decode(GrayCode x){
    // gray -> bit
    GrayCode ans;
    int i = N-1;
    ans[i] = x[i];
    while(i >= 0){
        ans[i] = ans[i+1] ^ x[i];
        i--;
    }
    return ans.to_ullong();
}

