vector<int> get(int a, int b, int n) {
	if (n == 1) {
		//cout << a << ' ' << b << endl;
		if (a + b != 1) {
			cout << "NO\n";
			exit(0);	
		}
		vector<int> res;
		res.pb(a);
		res.pb(b);
		return res;
	}
	int a1 = 0, b1 = 0;
	int pos = -1;
	vector<int> g;
	for (int i = 0; i < n; i++) {
		if ((a ^ b) & (1 << i)) {
			pos = i;
			int uk = 0;
			for (int j = 0; j < n; j++) {
				if (i != j) {
					if (a & (1 << j)) {
						a1 += 1 << uk;
					}
					if (b & (1 << j)) {
						b1 += 1 << uk;
					}
					g.pb(j);
					uk++;
				}
			}
			break;
		} 
	}
	vector<int> res1 = get(a1, a1 ^ 1, n - 1);
	vector<int> res2 = get(a1 ^ 1, b1, n - 1);
	vector<int> res;
	for (auto x: res1) {
		int nx = 0;
		for (int f = 0; f < n - 1; f++) {
			if (x & (1 << f)) {
				nx += 1 << g[f];
			}
		}
		if (a & (1 << pos)) {
			nx += 1 << pos;
		}
		res.pb(nx);
	}
	for (auto x: res2) {
		int nx = 0;
		for (int f = 0; f < n - 1; f++) {
			if (x & (1 << f)) {
				nx += 1 << g[f];
			}
		}
		if (b & (1 << pos)) {
			nx += 1 << pos;
		}
		res.pb(nx);
	}
	return res;
}

