vi findAns(vi bits,int A,int B) {
    if (bits.size() == 1) {
        vi r;
        r.pb(A),r.pb(B);
        return r;
    }

    int i;
    for (i = 0; i < bits.size(); i++) {
        if ((A^B) & (1 << bits[i])) break;
    }
    int p = i;
    vi bits2;
    for (i = 0; i < bits.size(); i++) {
        if (i != p) bits2.pb(bits[i]);
    }
    vi f,s;
    if ((A^(1 << bits2[0])) == B) {
        f = findAns(bits2,A,A^(1 << bits2[1]));
        s = findAns(bits2,A^(1 << bits2[1]),B);
    }
    else {
        f = findAns(bits2,A,A^(1 << bits2[0]));
        s = findAns(bits2,A^(1 << bits2[0]),B);
    }
    vi ans;
    for (i = 0; i < f.size(); i++) {
        if ((A^f[i]) & (1 << bits[p])) f[i] ^= (1 << bits[p]);
        ans.pb(f[i]);
    }
    for (i = 0; i < s.size(); i++) {
        if ((B^s[i]) & (1 << bits[p])) s[i] ^= (1 << bits[p]);
        ans.pb(s[i]);
    }
    return ans;
}
