vector<int> rec(int n,int a,int b){
    if (n==1) return {a,b};
    vector<int> res(1<<n),F,B;
    for (int i=n-1;i>=0;--i) if ((a^b)&(1<<i)){
        int c=((a>>(i+1))<<i)^(a&((1<<i)-1))
            ,d=((b>>(i+1))<<i)^(b&((1<<i)-1));
        F=rec(n-1,c,c^1); B=rec(n-1,c^1,d);
        for (int j=0;j<(1<<(n-1));++j){
            res[j]=((F[j]>>i)<<(i+1))^(a&1<<i)^(F[j]&(1<<i)-1);
            res[j+(1<<(n-1))]=((B[j]>>i)<<(i+1))^(b&1<<i)^(B[j]&(1<<i)-1);
        } break;
    }
    return res;
}

