void dfs(ll n,ll Bit,ll a,ll b,ll dif){
    //cout<<n<<" "<<Bit<<" "<<a<<" "<<b<<" "<<dif<<endl;
    if(n==1){
        ans.push_back(a);
        ans.push_back(b);
