    ll X=a^b;
    ll next=E;
    ll next2=E;
    if(dif==1){
        for(int i=0;i<n;i++){
            if((X>>i&1) && (Bit>>i&1)){
                next=i;
            }
        }
        for(int i=0;i<n;i++){
            if(i!=next && (Bit>>i&1)){next2=i;}
        }
        ll w=a^(1LL<<next2);
        dfs(n-1,Bit^(1LL<<next),a,w,1);
        dfs(n-1,Bit^(1LL<<next),w^(1LL<<next),b,1);
        return;
    }
    for(int i=0;i<n;i++){
        if((X>>i&1) && (Bit>>i&1)){
            next2=next;
            next=i;
        }
    }
    ll w=a^(1LL<<next2);
    dfs(n-1,Bit^(1LL<<next),a,w,dif-2);
    dfs(n-1,Bit^(1LL<<next),w^(1LL<<next),b,dif-2);
}



