    auto dfs=[](auto&& self, int n, bit a, bit b)->vector<bit> {
        if (!n) {
            vector<bit> ret = {a,b};
            return ret;
        }
        if (a.test(n)^b.test(n)) {
            auto c = a;
            c.flip(0);
            auto P = self(self,n-1,a,c);
            c.flip(n);
            auto Q = self(self,n-1,c,b);
            vector<bit> ret;
            int L = P.size();
            rep(i,L) ret.emplace_back(P[i]);
            rep(i,L) ret.emplace_back(Q[i]);
            return ret;
        } else {
            auto P = self(self,n-1,a,b);
            a.flip(n);
            auto c = P[1];
            c.flip(n);
            auto Q = self(self,n-1,a,c);
            vector<bit> ret;
            int L = P.size();
            ret.emplace_back(P[0]);
            rep(i,L) ret.emplace_back(Q[i]);
            for (int i = 1; i < L; i++) ret.emplace_back(P[i]);
            return ret;
        }
    };
