void swap_bit(int &x, int i, int j) {
	bool bi = x & (1 << i),
		 bj = x & (1 << j);
	x -= bi * (1 << i);
	x -= bj * (1 << j);
	x += bj * (1 << i);
	x += bi * (1 << j);
}

