}

void mono(deque<int> ones, deque<int> care) {
    if(ones.size() == 0) return;
    if(ones.size() == 1) {
        care.push_front(ones.front());
        gray(care, deque<int>());
        return;
    }
    int fr = ones.front();
    ones.pop_front();
    gray(ones, care);

    int se = ones.front();

    gray(care, deque<int>());
    cur ^= (1 << fr);
    ans.push_back(cur ^ A);
    care.push_back(se);
    ones.pop_front();
    mono(ones, care);
}

