// i < j
int swap_bit(int x, int i, int j) {
    int mask_i = x & (1 << i);
    int mask_j = x & (1 << j);
    x ^= mask_i;
    x ^= mask_j;
    x ^= mask_i << (j - i);
    x ^= mask_j >> (j - i);
    return x;
}

int flip(int x, int i) {
    int mask = x & (1 << i);
    x ^= mask;
    if (mask == 0) {
        x ^= (1 << i);
    }
    return x;
}


