int f[17];
int g[17];

vector <int> calc(int n, int a, int b) {
    int x = a ^ b, c = __builtin_popcount(x), i, j, k;
    vector <int> v;

    if (c == 1) {
        v.push_back(0);

        for (i = 0; i < n; i++) {
            for (j = 0; j < (1 << i); j++) {
                v[(1 << i) - j - 1] <<= 1;
                v.push_back(v[(1 << i) - j - 1] | 1);
            }
        }
    } else {
        vector <int> w, z;

        w = calc(n - 1, 0, 1);
        z = calc(n - 1, 1, (1 << (c - 1)) - 1);

        for (i = 0; i < w.size(); i++) v.push_back(w[i]);
        for (i = 0; i < z.size(); i++) v.push_back(z[i] | (1 << (n - 1)));
    }

    for (i = 0; i < n; i++) {
        f[i] = (v.back() >> i) & 1;
        g[i] = (x >> i) & 1;
    }

    for (i = 0; i < n; i++) {
        if (f[i] == g[i]) continue;

        for (j = i + 1; j < n; j++) {
            if (f[i] == g[j] && f[j] == g[i]) break;
        }

        for (k = 0; k < v.size(); k++) {
            int p = (v[k] >> i) & 1;
            int q = (v[k] >> j) & 1;

            if (p + q == 1) v[k] ^= ((1 << i) | (1 << j));
        }

        swap(f[i], f[j]);
    }

    for (i = 0; i < v.size(); i++) v[i] ^= a;

    return v;
}

