vector<int> work(int na, int nb, int dep ) {
	if (dep == n-1) return{na, nb};
	int ta = na / 2;
	assert(ta == nb / 2);

	int ea = na % 2;
	int eb = nb % 2;

	auto r0 = work(ta, ta ^ 1, dep+1);
	auto r1 = work(ta ^ 1, ta, dep +1);
	vector<int> zr;
	//zr.push_back(na);
	for (auto x : r0) {
		zr.push_back(x * 2 + ea);
	}
	for (auto x : r1) {
		zr.push_back(x * 2 + eb);
	}
	//zr.push_back(nb);
	return move(zr);
}

int getbit(int g, int t) {
	return (g >> t) & 1;
}

int swapback(int g, int t) {
	int a = getbit(g, t);
	int b = getbit(g, 0);
	if (a == b) return g;
	g = g ^ (1 << t);
	return g ^ 1;
}
