void calc(ll n,ll a,ll b,ll msk){
    if(n==1){
        printf("%lld %lld ", a, b);
        return;
    }
    ll abx = a ^ b;
    ll i = 0;
    ll c = 0, d = 0, flg = 3;
    fornum(i,0,N){
        if(msk&(1<<i)){
            c |= a & (1 << i);
            continue;
        }
        if(abx&(1<<i)){
            if(flg&1){
                c |= a & (1 << i);
                d = (1 << i);
                flg &= 2;
            }else if(flg&2){
                c |= ~a & (1 << i);
                flg &= 1;
            }else{
                c |= a & (1 << i);
            }
        }else{
            if(flg&2){
                c |= ~a & (1 << i);
                flg &= 1;
            }else{
                c |= a & (1 << i);
            }
        }
    }
    calc(n - 1, a, c, msk | d);
    calc(n - 1, c ^ d, b, msk | d);
}

