        for (int x : p) {
            pp.push_back(x | (c << i));
            c = 1 - c;
            pp.push_back(x | (c << i));
        }
        p = pp;
    }

    while (v1.size() > 0) {
        int i = v1.back();
        v1.pop_back();
        int j = v1.back();
        v1.pop_back();

        int ci = (a >> i) & 1;
        int cj = (a >> j) & 1;

        vector<int> pp;
        for (int x : p) {
            pp.push_back(x | (ci << i) | (cj << j));
            ci = 1 - ci;
            pp.push_back(x | (ci << i) | (cj << j));
            cj = 1 - cj;
            pp.push_back(x | (ci << i) | (cj << j));
            ci = 1 - ci;
            pp.push_back(x | (ci << i) | (cj << j));
        }
        p = pp;

        if (((p.back() >> i) & 1) != (((b >> i) & 1))) {
            std::swap(p[p.size() - 3], p[p.size() - 1]);
        }
    }

    cout << "YES\n";
    for (int x : p) {
        cout << x << " ";
    }
    cout << "\n";

    return 0;
}

