void solve (int r, int a, int b, int x) {
    a %= (1<<(r+1));
    b %= (1<<(r+1));
    if (r == 0) {
        ans.push_back(b+x);
        return;
    }

    if ((a&(1<<r)) == (b&(1<<r))) {
        if (r == 1) {
            if (a&(1<<r)) {
                ans.push_back(a-(1<<r)+x);
                ans.push_back(b-(1<<r)+x);
                ans.push_back(b+x);
            } else {
                ans.push_back(a+(1<<r)+x);
                ans.push_back(b+(1<<r)+x);
                ans.push_back(b+x);
            }
        } else {
            if (a&(1<<r)) solve(r-1, a, b, x+(1<<r));
            else solve(r-1, a, b, x);
            ans.pop_back();
            int tmp = ans.back();
            tmp %= (1<<r);
            if (a&(1<<r)) {
                ans.push_back(tmp+x);
                solve(r-1, tmp, b, x);
                ans.push_back(b+x);
            } else {
                ans.push_back(tmp+(1<<r)+x);
                solve(r-1, tmp, b, x+(1<<r));
                ans.push_back(b+x);
            }
        }
    } else {
        int t = 0;
        rep(i,r) {
            t = a^(1<<i);
            if (t%(1<<r) != t) break;
        }
        if (a < b) {
            solve(r-1, a, t, x);
            ans.push_back(t+(1<<r)+x);
            solve(r-1, t, b, x+(1<<r));
        } else {
            solve(r-1, a, t, x+(1<<r));
            ans.push_back(t-(1<<r)+x);
            solve(r-1, t, b, x);
        }
    }
}

