int shift(int x, int len, int pos, int cf){
  int res = 0;
  for(int i = 0; i < len; ++i){
    if(cf == -1 && i == pos) continue;
    int to = (1 << (i + (i >= pos) * cf));
    res += ((x >> i) & 1) * to;
  }
  return res;
}

vector < int > solve(int n, int f, int s){
  if(n == 1){
    return {f, s};
  }
  int pos = -1;
  for(int i = 0; i < n; ++i){
    if(((f >> i) & 1) == ((s >> i) & 1)){
      continue;
    }
    pos = i;
    break;
  }
  int fx = shift(f, n, pos, -1);
  int sx = shift(s, n, pos, -1);
  int c = 0;
  for(int i = 0; i < n - 1; ++i){
    c = fx ^ (1 << i);
    if(c != fx && c != sx){
      break;
    }
  }
  vector < int > part1 = solve(n - 1, fx, c);
  vector < int > part2 = solve(n - 1, c, sx);
  vector < int > res;
  for(int i : part1){
    int val = shift(i, n - 1, pos, 1);
    if((f >> pos) & 1){
      val += (1 << pos);
    }
    res.push_back(val);
  }
  for(int i : part2){
    int val = shift(i, n - 1, pos, 1);
    if((s >> pos) & 1){
      val += (1 << pos);
    }
    res.push_back(val);
  }
  return res;
}

