std::vector<ll> seq(ll n,ll a,ll b){
  if(n==1){
    return {a,b};
  }

  ll hold;

  rep(i,0,n){
    if((a^b)&(1ll<<i)){
      hold=i;
      break;
    }
  }

  ll na=0,nb=0;
  rep(i,0,hold){
    if(a&(1ll<<i))na+=(1ll<<i);
    if(b&(1ll<<i))nb+=(1ll<<i);
  }
  rep(i,hold+1,n){
    if(a&(1ll<<i))na+=(1ll<<(i-1));
    if(b&(1ll<<i))nb+=(1ll<<(i-1));
  }

  std::vector<ll> first=seq(n-1,na,na^1),second=seq(n-1,na^1,nb);

  rep(i,0,1ll<<(n-1)){
    first.push_back(second[i]);
  }

  rep(i,0,1ll<<(n-1)){
    ll num=first[i];
    first[i]=0;
    rep(j,0,hold){
      if(num&(1ll<<j))first[i]+=(1ll<<j);
    }
    rep(j,hold,n){
      if(num&(1ll<<j))first[i]+=(1ll<<(j+1));
    }
    if(a&(1ll<<hold))first[i]+=(1ll<<hold);
  }
  rep(i,1ll<<(n-1),1ll<<n){
    ll num=first[i];
    first[i]=0;
    rep(j,0,hold){
      if(num&(1ll<<j))first[i]+=(1ll<<j);
    }
    rep(j,hold,n){
      if(num&(1ll<<j))first[i]+=(1ll<<(j+1));
    }
    if(b&(1ll<<hold))first[i]+=(1ll<<hold);
  }

  return first;
}

