bool is_power_two(int x) {
    return x > 0 && ((x & (x - 1)) == 0);
}

bool get_bit(int mask, int pos) {
    return (bool) (mask & (1 << pos));
}

int get_cnt(int n, int x) {
    int res = 0;
    for (int i = 0; i < n; ++i) {
        res += get_bit(x, i);
    }
    return res;
}

int upd(int n, int x, const vector<int> &p) {
    int res = 0;
    for (int i = 0; i < n; ++i) {
        res += get_bit(x, i) * (1 << p[i]);
    }
    return res;
}

vector<int> solve(int n, int a, int b) {
    // cout << n << " " << a << " " << b << endl;
    if (n == 1) {
        return {a, b};
    }
    b ^= a;
    vector<int> pos, p(n);
    for (int i = 0; i < n; ++i) {
        if (get_bit(b, i)) {
            pos.push_back(i);
            p[n - pos.size()] = i;
        }
    }
    int cur = 0;
    for (int i = 0; i + pos.size() < n; ++i) {
        while (get_bit(b, cur)) {
            ++cur;
        }
        p[i] = cur;
        ++cur;
    }
    int x = 0;
    for (int i = n - 1; i >= (int) (n - pos.size()); --i) {
        x += (1 << i);
    }
    vector<int> v1, v2;
    int to = x;
    to ^= (1 << (n - 1));
    to ^= (1 << (n - 2));
    v1 = solve(n - 1, 0, to);
    v2 = solve(n - 1, to, x ^ (1 << (n - 1)));
    for (int i = 0; i < v2.size(); ++i) {
        v2[i] ^= (1 << (n - 1));
    }
    vector<int> v;
    for (int x : v1) {
        v.push_back(a ^ upd(n, x, p));
    }
    for (int x : v2) {
        v.push_back(a ^ upd(n, x, p));
    }
    return v;
}

void check(int n, int a, int b, const vector<int> &ans) {
    if (ans.size() != (1 << n)) {
        exit(1);
    }
    if (ans[0] != a) {
        exit(2);
    }
    if (ans.back() != b) {
        exit(2);
    }
    for (int i = 0; i + 1 < ans.size(); ++i) {
        if (!is_power_two(ans[i] ^ ans[i + 1])) {
            exit(3);
        }
        if (!(0 <= ans[i] && ans[i] < ans.size())) {
            exit(4);
        }
    }
}

void go(int n, int a, int b) {
    if (get_cnt(n, a ^ b) % 2 == 0) {
        puts("NO");
        return;
    }
    const vector<int> &ans = solve(n, a, b);
    puts("YES");
    for (int x : ans) {
        printf("%d ", x);
    }
    puts("");
    check(n, a, b, ans);
}

