int main() {
    int N,A,B,C; cin >> N >> A >> B;
    C=A^B;
    corner(!(__builtin_popcount(C)%2),"NO");
    vector<vector<int>> vv(N);
    vv[0]={0,1};
    for(int i=1;i<N;++i) {
        int M=vv[i-1].size();
        for(int j=0;j<M;++j) vv[i].push_back(2*vv[i-1][j]);
        for(int j=M-1;0<=j;--j) vv[i].push_back(2*vv[i-1][j]+1);
    }
    vector<int> bf(N),af;
    for(int i = 0; i < N; ++i) bf[i]=((C>>i)&1);
    af = bf;
    sort(ALL(af));
    vector<int> idx(N,-1);
    for(int i=0; i<N; ++i) {
        for(int j=0;j<N;++j) {
            if(idx[j]!=-1)continue;
            if(af[i]!=bf[j]) continue;
            idx[j]=i;
            break;
        }
    }
    int pre=0;
    vector<int> cnt;
    for(int i=N-1;1<=i;--i) {
        if(!af[i]) break;
        if((N-1-i)&1) reverse(ALL(vv[i-1]));
        for(int x:vv[i-1]) cnt.push_back(pre|x);
        // print(i,bitset<10>(pre),vv[i-1]);

        pre ^= (1<<i);

        reverse(ALL(vv[i-1]));
        // print(i,bitset<10>(pre),vv[i-1]);
        for(int x:vv[i-1]) cnt.push_back(pre|x);
    }
    vector<int> ans;
    for(int& x:cnt) {
        int y = 0;
        for(int i = 0; i < N; ++i) {
            int j=idx[i];
            int b=((x>>j)&1);
            y ^= (b<<i);
        }
        ans.push_back(y);
    }
    for(int& x:ans) {
        x ^= A;
    }
    assert(ans.front() == A);
    assert(ans.back() == B);
    cout << "YES" << endl;
    for(int x:ans) cout << x << " ";
    cout << endl;
    return 0;
}

