const int maxN = (1 << 17);
int n, A, B;

int q[maxN];

void solve(int L, int R, int S) {
	if(L >= R || L + 1 == R) return;
	int M = (L + R) >> 1;
	int d = 0;
	while(S >> d & 1 || (q[L] >> d & 1) == (q[R] >> d & 1)) ++d;
	int c = 0;
	while(c == d || (S >> c & 1)) ++c;
	q[M] = q[L] ^ (1 << c);
	q[M + 1] = q[M] ^ (1 << d);
	solve(L, M, S | (1 << d));
	solve(M + 1, R, S | (1 << d));
}

