bool to_left(vector<ll> &gm, ll ind)
{
	ll cur_val = gm[ind];
	ll lval = gm[0];
	ll l_i = 0;
	ll m_i = ind;
	ll r_i = 0;
	bool check = false;
	for (int i = ind + 1; i < gm.size(); ++i)
	{
		if (cnt_hd(lval, gm[i]) == 1)
		{
			reverse(gm.begin() + l_i, gm.begin() + m_i + 1);
			reverse(gm.begin() + m_i + 1, gm.begin() + i + 1);
			lval = gm[i];
			l_i = i;
			if(i == gm.size() - 1 || cnt_hd(gm[i],gm[i+1]) == 1)
				check = true;
			break;
		}
	}
	for (int i = l_i + 1; i < gm.size() && !check; ++i)
	{
		if (cnt_hd(lval, gm[i]) == 1)
		{
			reverse(gm.begin() + l_i + 1, gm.begin() + i + 1);
			lval = gm[i];
			if (i == gm.size() - 1 || cnt_hd(gm[i], gm[i + 1] == 1))
			{
				check = true;
			}
		}
	}
	return check;
}

bool to_right(vector<ll> &gm, ll ind)
{
	ind = gm.size() - 1 - ind;
	reverse(all(gm));
	bool check = to_left(gm, ind);
	reverse(all(gm));
	return check;
}

