int main()
{
    int n, a, b;
    cin >> n >> a >> b;
    int x = a^b;
    vector<int> ans;

    vector<vector<int>> perm(20);
    int tmp = x;
    int cnt = 0;
    while(tmp > 0)
    {
        if(tmp & 1) cnt++;
        tmp >>= 1;
    }
    if(cnt % 2 != 1)
    {
      cout << "NO" << endl;
      return 0;
    }
    perm[1].push_back(0);
    perm[1].push_back(1);
    for(int i = 1; i < 20; i++)
    {
        int size = perm[i-1].size();
        for(int j = 0; j < size; j++)
        {
            perm[i].push_back(perm[i-1][j] * 2);
        }
        for(int j = 0; j < size; j++)
        {
            perm[i].push_back(perm[i-1][size-1-j]*2+1);
        }
    }

    for(int i = 0; i < cnt; i++)
    {
        int pre = 0;
        for(int j = 0; j < i; j++)
        {
            pre += 1 << (n-1-j);
        }
        int ss = n-1-i;
        if(i % 2 == 1)
        {
            reverse(perm[ss].begin(), perm[ss].end());
        }
        int size = perm[ss].size();
        for(int j = 0; j < size; j++)
        {
            ans.push_back(perm[ss][j] + pre);
        }
        if(i == cnt-1)
        {
            pre += 1 << (n-cnt);
            if(ss == 0)
            {
              ss = 1;
              size = 2;
              pre -= 1 << (n-cnt);
            }
            reverse(perm[ss].begin(), perm[ss].end());
            for(int j = 0; j < size; j++)
            {
                ans.push_back(perm[ss][j] + pre);
            }
        }
    }
    int asize = ans.size();
    for(int i = 0; i < asize; i++)
    {
        ans[i] ^= a;
    }
    cout << "YES" << endl;
    for(int i = 0; i < asize-1; i++)
    {
        if(ans[i] == b)
        {
            ans[i] = ans[asize-1];
            ans[asize-1] = b;
        }
        cout << ans[i] << " ";
    }
    cout << ans[asize-1] << endl;
}

