/*-----------------------------------------*/
// n = 今見ているビットの数
vector<int> solve(int n, int a, int b) {
  if (n == 1) return {a, b};

  // ・最上位ビットが同じ
  // a = 0aaaaa, b = 0bbbbb とする
  // solve(n - 1, a, b)       において 0xxxxx の形でとりうる値を全列挙
  // solve(n - 1, 1aaaaa, 1yyyyy)          1xxxxx
  // 条件を満たすようにこの二者をつなげるには
  // (0aaaaa -> 1aaaaa) は条件を満たすので
  // (1yyyyy -> 前者の要素の二番目) が条件を満たすようにすればよい
  if ((a >> (n - 1) & 1) == (b >> (n - 1) & 1)) {
    vector<int> res1 = solve(n - 1, a, b);
    vector<int> res2 = solve(n - 1, a ^ (1 << (n - 1)), res1[1] ^ (1 << (n - 1)));
    vector<int> res{res1.front()};
    copy(ALL(res2), back_inserter(res));
    copy(res1.begin() + 1, res1.end(), back_inserter(res));
    return res;
  }

  // ・最上位ビットが異なる
  // a = 0aaaaa, b = 1bbbbb とする
  // solve(n - 1, a, a ^ 1) において 0xxxxx の形でとりうる値を全列挙
  // a ^ 1 = 0aaaa1 とすると
  // solve(n - 1, 1aaaa1, b)         1xxxxx
  // (0aaaa1 -> 1aaaa1) は条件を満たす
  else {
    vector<int> res = solve(n - 1, a, a ^ 1), res2 = solve(n - 1, a ^ 1 ^ (1 << (n - 1)), b);
    copy(ALL(res2), back_inserter(res));
    return res;
  }
  // 0xxxxx, 1xxxxx
  // それぞれの形でとりうる数を条件を満たす形で全列挙できる
}

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int n, a, b; cin >> n >> a >> b;

  // 0 <= i <= 2^n-1 を満たす整数は 2^n 個ある
  // 条件を満たす順列の隣接する要素において立っているビットの数の差は1
  // よって, P_0 と P_2^n-1 では立っているビットの数の偶奇が異なる
  if (__builtin_popcount(a) == __builtin_popcount(b)) {
    cout << "NO\n";
    return 0;
  }

  vector<int> ans = solve(n, a, b);
  cout << "YES\n";
  REP(i, 1 << n) cout << ans[i] << (i == (1 << n) - 1 ? '\n' : ' ');
  return 0;
}

