		ans.push_back(a);ans.push_back(b);
		return;
	}
	int dif=a^b,bit1=lowbit(dif);
	dif^=bit1;sta^=bit1;
	int bit2=lowbit(sta);
	dif^=bit2;
	solve(n-1,a,a^dif,sta);
	solve(n-1,a^dif^bit1,b,sta);
}

