const int kMaxn = (1 << 17) + 5, kD[] = {-1, 1};

int N, A, B, G[kMaxn], vis[kMaxn], vec[kMaxn];

bool check(int a, int b) {
	int cnt = 0;
	for (int i = 0; i < N; i++) {
		cnt += (a >> i & 1) ^ (b >> i & 1);
	}
	return cnt == 1;
}

int main() {
	scanf("%d%d%d", &N, &A, &B);

	int U = 1 << N, pa, pb;
	for (int i = 0; i < U; i++) {
		int & gi = G[i];
		gi = i >> N - 1 & 1;
		for (int j = N - 2; j >= 0; j--) {
			gi <<= 1;
			gi |= (i >> j & 1) ^ (i >> j + 1 & 1);
		}
		if (gi == A) pa = i;
		if (gi == B) pb = i;
	}

	if (std::abs(pa - pb) & 1 ^ 1) {
		puts("NO");
		return 0;
	}

	int half = U >> 1;
	for (int i = 0; i < N; i++) {
		if ((A >> i & 1) == (B >> i & 1)) continue;
	//	printf("%d\n", i);
		for (int k1 = 0, d1; k1 < 2; k1++) {
			d1 = kD[k1];
			for (int k2 = 0, d2; k2 < 2; k2++) {
				d2 = kD[k2];
			//	printf(" d1 = %d, d2 = %d\n", d1, d2);
				memset(vis, 0, sizeof vis);
				int cur = pa, cnt = 1, back = 0;
				vec[back++] = A;
				for (vis[pa] = 1; cnt < half; ) {
					cur += d1;
					if (cur < 0) {
						cur = U - 1;
					}
					if (cur == U) {
						cur = 0;
					}
					if ((G[cur] >> i & 1) == (A >> i & 1)) {
						if (vis[cur]) {
							break;
						}
						vec[back++] = G[cur];
						vis[cur] = 1;
						++cnt;
					}
				}
			//	printf(" cnt = %d\n", cnt);
				if (cnt < half) {
					continue;
				}
				int tmp = G[cur] ^ (1 << i);
				for (int j = 0; j < U; j++) {
					if (G[j] == tmp) {
						cur = j;
						break;
					}
				}
				vec[back++] = G[cur];
				for (vis[cur] = 1, cnt = 1; cnt < half; ) {
					cur += d2;
					if (cur < 0) {
						cur = U - 1;
					}
					if (cur == U) {
						cur = 0;
					}
					if ((G[cur] >> i & 1) == (B >> i & 1)) {
						if (vis[cur]) {
							break;
						}
						vec[back++] = G[cur];
						vis[cur] = 1;
						++cnt;
					}
				}
				if (cnt < half || vec[back - 1] != B) {
				//	puts("Case 3");
					for (int i = 0; i < back; i++) {
						printf("%d ", vec[i]);
					}
				//	printf("\n Case 3, cnt = %d, vec[back - 1] = %d\n", cnt, vec[back - 1]);
					continue;
				}
				int fail = 0;
				for (int j = 1; j < back; j++) {
					if (!check(vec[j - 1], vec[j])) {
						fail = 1;
						break;
					}
				}
				if (fail) {
				//	printf(" Case 4\n");
					continue;
				}
				puts("YES");
				for (int j = 0; j < back; j++) {
					printf("%d ", vec[j]);
				}
				putchar('\n');
				return 0;
			}
		}
	}

	puts("NO");
	return 0;
}

