const int MAX_N = 17;

int N, A, B;

int count(int x) {
    int ret = 0;
    for (int i = 0; i < N; i++) {
        if (x & (1 << i)) {
            ret++;
        }
    }

    return ret;
}

void dfs(int a, int b, int s, int l, int mask, vector<int> &ans) {
    if (l == 1) {
        ans[s] = a | mask;
        ans[s + 1] = b | mask;
        return;
    }

    int m = -(a ^ b) & (a ^ b);

    dfs((a & ~m), (a & ~m) ^ 1, s, l - 1, mask | (m & a), ans);
    dfs((a & ~m) ^ 1, (b & ~m), s + (1 << (l - 1)), l - 1, mask | (m & b), ans);
}

void solve() {
    if (count(A) % 2 == count(B) % 2) {
        cout << "NO" << endl;
        return;
    }
    cout << "YES" << endl;

    vector<int> ans(1 << N);
    dfs(A, B, 0, N, 0, ans);

    for (int i = 0; i < (1 << N); i++) {
        cout << ans[i];
        if (i == (1 << N) - 1) {
            cout << endl;
        } else {
            cout << " ";
        }
    }
}

int main() {
    cin >> N >> A >> B;

    solve();

    return 0;
}

