#define N 200010
int n, a, b;
int vis[N];

bool adj(int a, int b)
{
	int cnt = 0;
	for (int i = 0; i <= n; ++i)
	{
		int x = (a >> i) & 1;
		int y = (b >> i) & 1;
		if (x != y) ++cnt;
	}
	return cnt == 1;
}

int get(int x)
{
	for (int i = 0; i <= n; ++i)
	{
		x ^= (1 << i);
		if (vis[x] == 0)
		{
			vis[x] = 1;
			return x;
		}
		x ^= (1 << i);
	}
	return -1;
}	

int main()
{
	while (scanf("%d%d%d", &n, &a, &b) != EOF)
	{
		memset(vis, 0, sizeof vis);
