		vector <int> l, r; l.push_back(a); r.push_back(b);
		int tot = 2;
		int len = 1 << n;
		bool flag = 1;
		while (tot < len)
		{
			a = get(a);
			b = get(b);
			l.push_back(a);
			r.push_back(b);
			tot += 2;
			if (a == -1 || b == -1 || (tot == len && !adj(a, b)))
			{
				flag = 0;
				break;
			}
		}
		if (flag == 0)
