  cin >> n >> a >> b;

  if(__builtin_popcount(a ^ b) != 1){
    cout << "NO" << endl;
    return 0;
  }

  puts("YES");

  vector<int> vec[5];

  vec[0].push_back(0);
  vec[0].push_back(1);

  for(int i=0;i<4;i++){
    for(int p=0;p<vec[i].size();p++){
      for(int q=0;q<vec[i].size();q++){
        int r;
        if(p % 2 == 0) r = q;
        else r = vec[i].size() - q - 1;

        vec[i+1].push_back((vec[i][p] << (1<<i)) + vec[i][r]);
      }
    }
  }

  vector<int> vec1;

  for(int i=0;i<5;i++){
    if(n & (1 << i)) {
      if(vec1.size() == 0) {
        vec1 = vec[i];
        continue;
      }

      vector<int> vec2;

      for(int p=0;p<vec[i].size();p++){
        for(int q=0;q<vec1.size();q++){
          int r;
          if(p % 2 == 0) r = q;
          else r = vec1.size() - q - 1;

          vec2.push_back((vec1[r] << (1<<i)) + vec[i][p]);
        }
      }

      vec1 = vec2;
    }
  }

  int t = -1, start = 0;

  for(int j=0;j<vec1.size();j++){
    for(int i=0;i<n;i++){
      int m = vec1.size();
      int p = vec1[j] & (1<<i);
      int q = vec1[(m-1+j)%m] & (1<<i);

      int r = a & (1<<i);
      int s = b & (1<<i);

      if(p != q && r != s) {
        t = i;
        start = j;
        break;
      }
    }

    if(t != -1) break;
  }

  assert(t != -1);

  bool f[20];

  for(int i=0;i<n;i++){
    int p = vec1[start] & (1<<i);
    int q = a & (1<<i);

    f[i] = p ^ q;
  }

  int prev = -1;

  debug(vec1.size());

  for(int i=0;i<vec1.size();i++){
    int res = vec1[(i + start)%vec1.size()];

    for(int j=0;j<n;j++){
      if(f[j]) res ^= 1<<j;
    }

    printf("%d ", res);

    assert(prev == -1 || __builtin_popcount(res ^ prev) == 1);
    prev = res;
  }

  puts("");

  return 0;
}

