	for(int i=0;i<(1<<(n-1));i++)
	{
//		cout<<rht[i]<<" "<<(rht[i]%(1<<pos))<<" "<<((b>>pos&1)<<pos)<<" "<<((rht[i]/(1<<pos))<<(pos+1))<<endl;
