vector<ll> findPath(ll n, ll fi, ll se){
	vector<ll> jav;
	if (n == 1){
		jav.pb(fi);
		jav.pb(se);
		return jav;
	}
	ll f = 0;
	ll poi = 0;
	ll fi1 = 0, fi2 = 0, se1 = 0, se2 = 0;
	for (int i = n - 1; i >= 0; i--){
		if ((fi & (1 << i)) ^ (se & (1 << i)) != 0){
			poi = i;
			if (se & (1 << i)){
				f = 1;
			}
			break;
		}else{
			if (fi & (1 << i)){
				fi += (1 << (i - 1));
			}
			if (se & (1 << i)){
				se += (1 << (i - 1));
			}
		}
	}
	for (int i = poi - 1; i >= 0; i--){
		fi1 += (1 << i) & fi;
		se1 += (1 << i) & se;
	}
	vl jav1, jav2;
	for (ll i = 0; i < (1 << (n - 2)); i++){
		ll cnt =__builtin_popcountll(i);
		ll cnt1 = __builtin_popcountll(fi1);
		if (cnt != cnt1){
			jav1 = findPath(n - 1, fi1, i);
			jav2 = findPath(n - 1, i, se1);
			break;
		}
	}
	for (int i = 0; i < jav1.size(); i++){
		ll adad = 0;
		for (int j = n - 2; j >= poi; j--){
			if ((1 << j) & jav1[i]){
				adad += (1 << (j + 1));
			}
		}
		for (int j = poi - 1; j >= 0; j--){
			adad += (1 << j) & jav1[i];
		}
		ll ff = f ^ 1;
		adad += (1 << poi) * ff;
		jav.pb(adad);
	}

	for (int i = 0; i < jav2.size(); i++){
		ll adad = 0;
		for (int j = n - 2; j >= poi; j--){
			if ((1 << j) & jav2[i]){
				adad += (1 << (j + 1));
			}
		}
		for (int j = poi - 1; j >= 0; j--){
			adad += (1 << j) & jav2[i];
		}
		ll ff = f;
		adad += (1 << poi) * ff;
		jav.pb(adad);
	}
	return jav;


}







