using ll = long long;
using P = pair<int, int>;
int main()
{
    int n, a, b;
    cin >> n >> a >> b;
    int x = a^b;
    vector<int> ans;

    vector<vector<int>> perm(17);
    int tmp = x;
    int cnt = 0;
    while(tmp > 0)
    {
        if(tmp & 1) cnt++;
        tmp >>= 1;
    }
    if(cnt % 2 != 1)
    {
      cout << "NO" << endl;
      return 0;
    }
    perm[1].push_back(0);
    perm[1].push_back(1);
    for(int i = 1; i < 17; i++)
    {
        int size = perm[i-1].size();
        for(int j = 0; j < size; j++)
        {
            perm[i].push_back(perm[i-1][j] * 2);
        }
        for(int j = 0; j < size; j++)
        {
            perm[i].push_back(perm[i-1][size-1-j]*2+1);
        }
    }

    for(int i = 0; i < cnt; i++)
    {
        int pre = 0;
        for(int j = 0; j < i; j++)
        {
            pre += 1 << (n-1-j);
        }
        int ss = n-1-i;
        if(i % 2 == 1)
        {
            reverse(perm[ss].begin(), perm[ss].end());
        }
        int size = perm[ss].size();
        for(int j = 0; j < size; j++)
        {
            ans.push_back(perm[ss][j] + pre);
        }
        if(i == cnt-1)
        {
            pre += 1 << (n-cnt);
            if(ss == 0)
            {
              ss = 1;
              size = 2;
              pre -= 1 << (n-cnt);
            }
            reverse(perm[ss].begin(), perm[ss].end());
            for(int j = 0; j < size; j++)
            {
                ans.push_back(perm[ss][j] + pre);
            }
        }
    }
    int asize = ans.size();
    for(int i = 0; i < asize; i++)
    {
        ans[i] ^= a;
    }
    cout << "YES" << endl;
    for(int i = 0; i < asize; i++)
    {
        if(ans[i] == b)
        {
            ans[i] = ans[asize-1];
            ans[asize-1] = b;
        }
        cout << ans[i] << " ";
    }
}

#include <bits/stdc++.h>
using namespace std;
int n,ans[(1<<17)];
void solve(int a,int b,int l,int r,vector<int> v)
{
	ans[l]=a;
	ans[r]=b;
	if (l+1==r)
	return;
	int b1=-1,b2,mid=(l+r)/2;
	for (int i=0;i<n;i++)
	{
		if (!v[i])
		continue;
		if (b1==-1 && (a&(1<<i))!=(b&(1<<i)))
		b1=i;
		else
		b2=i;
	}
	if (a&(1<<b1))
	{
		for (int i=l;i<=mid;i++)
		ans[i]|=(1<<b1);
	}
	else
	{
		for (int i=mid+1;i<=r;i++)
		ans[i]|=(1<<b1);
	}
	v[b1]=0;
	solve(a,(b^(1<<b1)^(1<<b2)),l,mid,v);
	solve((b^(1<<b2)),b,mid+1,r,v);
}
int main()
{
	int a,b;
	scanf("%d%d%d",&n,&a,&b);
	if (__builtin_popcount(a)%2==__builtin_popcount(b)%2)
	{
		printf("NO");
		return 0;
	}
	vector<int> v(n,1);
	solve(a,b,0,(1<<n)-1,v);
	printf("YES\n");
	for (int i=0;i<(1<<n);i++)
	printf("%d ",ans[i]);
}

