bool check(vector<int> &p){
    int n = (int)p.size();
    rep(i,n-1){
        int s = abs(p[i]-p[i+1]);
        int k = (int)log2(s);
        if(s!=(1<<k))return false;
        if(min(p[i],p[i+1])&(1<<k))return false;
    }
    return true;
}
