inline ll gcd(ll a, ll b) {
	while (b) {
		ll c = a;
		a = b; b = c % b;
	}
	return a;
}
inline ll lcm(ll a, ll b) {
	return a / gcd(a, b) * b;
}
bool isprime(ll n) {
	if (n == 1)return false;
	for (int i = 2; i * i <= n; i++) {
		if (n % i == 0)return false;
	}
	return true;
}
ll mypow(ll a, ll b) {
	if (!b)return 1;
	if (b & 1)return mypow(a, b - 1) * a;
	int memo = mypow(a, b >> 1);
	return memo * memo;
}
int n, a, b;
int bit[1 << 16];
void func(int m, int e, int c, int d, int l, int r) {
	bit[l] = c;
	bit[r - 1] = d;
	if (m == 1)return;
	int dbit;
	rep(i, n) {
		if ((e & (1 << i)) && (c & (1 << i)) != (d & (1 << i))) {
			dbit = i;
			break;
		}
	}
	int md = c;
	rep(i, n) {
		if ((e & (1 << i)) && i != dbit) {
			md ^= (1 << i);
			break;
		}
	}
	func(m - 1, e - (1 << dbit), c, md, l, (l + r) / 2);
	func(m - 1, e - (1 << dbit), md, d, (l + r) / 2, r);
	for (int i = l; i < (l + r) / 2; i++) {
		if (bit[i] & (1 << dbit))bit[i] -= 1 << dbit;
		bit[i] += c & (1 << dbit);
	}
	for (int i = (l + r) / 2; i < r; i++) {
		if (bit[i] & (1 << dbit))bit[i] -= 1 << dbit;
		bit[i] += d & (1 << dbit);
	}
}
