    vector<int> nxt(gray);
    if (i == N-1) prev = gray;
    reverse(all(gray));
    nxt.insert(nxt.end(), all(gray));
    int di = 1 << i;
    int d = gray.size();
    rep(j, d) {
      nxt[j+d] += di;
    }
    gray.swap(nxt);
  }
  int M =  1 << N;
  assert(gray.size() == M);
  rep(i, M) {
    int x = gray[i] ^ gray[(i+1)%M];
    assert(__builtin_popcount(x) == 1);
  }

  int v = A^B;
  rep(i, N) {
    cnt[v >> i & 1]++;
    cnt2[gray[M-1] >> i & 1]++;
  }

  bool ok = true;
  rep(i, 2) {
    if (cnt[i] != cnt2[i]) {
      ok = false;
    }
  }

  if (ok) {
    rep(i, N) {
      indices[gray[M-1] >> i & 1].eb(i);
    }

    rep(i, N) {
      assert(!indices[v >> i & 1].empty());
      perm[indices[v >> i & 1].back()] = i;
      indices[v >> i & 1].pop_back();
    }

    rep(i, M) {
      int v = 0;
      rep(j, N) {
        int t = gray[i] >> j & 1;
        int idx = perm[j];
        v += t << idx;
      }
      gray[i] = v;
      gray[i] ^= A;
    }
    assert(gray[0] == A);
    assert(gray[M-1] == B);
    rep(i, M) {
      int x = gray[i] ^ gray[(i+1)%M];
      assert(__builtin_popcount(x) == 1);
    }

    puts("YES");
    rep(i, M) {
      printf("%d%c", gray[i], " \n"[i==M-1]);
    }
  }

  if ((B^A) != M-1) {
    puts("NO");
    return 0;
  }

  puts("YES");
  int t = prev[M/2-1];
  rep(i, N) {
    perm[i] = i;
  }
  rep(i, N) {
    if (t >> i & 1) {
      perm[i] = (i+1)%N;
      perm[(i+1)%N] = i;
    }
  }
  ans = prev;
  reverse(all(prev));
  for (int t : prev) {
    int v = 0;
    rep(i, N) {
      v += t >> i & 1 << perm[i];
    }
    ans.eb(v);
  }
  Out(ans);

}

