using namespace std;

typedef long long ll;

bool B[1 << 17][18];

int n, a, b;

void Solve(int l, int r, int mask) {
    if(r == l + 1) return;
    int md = (l + r) / 2;
    for(int i = 0; i < n; i++) if((mask >> i & 1) && (B[l][i] != B[r][i])) {
        for(int j = l; j <= md; j++) B[j][i] = B[l][i];
        for(int j = md + 1; j <= r; j++) B[j][i] = B[r][i];
        for(int j = 0; j < n; j++) if(j != i && (mask >> j & 1)) {
            memcpy(B[md], B[l], sizeof B[l]);
            B[md][j] ^= 1;
            memcpy(B[md + 1], B[md], sizeof B[md]);
            B[md + 1][i] ^= 1;
            Solve(l, md, mask ^ (1 << i));
            Solve(md + 1, r, mask ^ (1 << i));
            return;
        }
        return;
    }
}

int main() {
    scanf("%d%d%d", &n, &a, &b);
    for(int i = 0; i < n; i++) {
        B[0][i] = a >> i & 1;
        B[(1 << n) - 1][i] = b >> i & 1;
    }
    int tmp = a ^ b;
    if(!(__builtin_popcount(tmp) & 1)) {
        puts("NO");
        return 0;
    }
    Solve(0, (1 << n) - 1, (1 << n) - 1);
    puts("YES");
    for(int i = 0; i < 1 << n; i++) {
