vector<int> EulerianTrail(const int s, vector<vector<int>> &g, const bool directed) {
    function<void (int, vector<int> &)> dfs = [&](int u, vector<int> &trail) {
        while (!g[u].empty()) {
            int v = g[u].back();
            g[u].pop_back();
            if (!directed) {
                for (int i = 0; i < g[v].size(); i ++) {
                    if (g[v][i] == u) {
                        g[v].erase(g[v].begin() + i);
                        break;
                    }
                }
            }
            dfs(v, trail);
        }
        trail.push_back(u);
    };
    vector<int> trail;
    dfs(s, trail);
    reverse(trail.begin(), trail.end());
    return trail;
}


signed main() {
    int N, A, B;
    cin >> N >> A >> B;
    int NN = 1LL << N;

    vector<vector<int>> table(NN);
    vector<vector<int>> sub_table(NN);
    for (int i = 0; i < NN; i++) {
        for (int k = 1; i + k <= NN - 1; k *= 2) {
            if (__builtin_popcountll(i ^ (i + k)) != 1) continue;
            table[i].push_back(i + k);
            table[i + k].push_back(i);

            if ((i == A && (i + k) == B) || (i == B && (i + k) == A)) continue;
            sub_table[i].push_back(i + k);
            sub_table[i + k].push_back(i);
        }
    }

    // オイラー経路を構築可能かの判定
    for (int i = 0; i < NN; i++) {
        if (i == A || i == B) continue;
        if (table[i].size() % 2 == 1) {
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;

    bool start_is_odd = table[A].size() % 2 == 1;
    bool goal_is_odd = table[B].size() % 2 == 1;

    vector<int> ans;
    if (goal_is_odd) {
        ans = EulerianTrail(A, table, false);
    } else if (start_is_odd) {
        ans = EulerianTrail(B, table, false);
        reverse(ans.begin(), ans.end());
    } else {
        ans = EulerianTrail(A, sub_table, false);
    }

    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i];
        if (i != ans.size() - 1) cout << " ";
    }
    cout << endl;

    return 0;
}

