//!============================================!//
//!    8888ba.88ba             oo              !//
//!    88  '8b  '8b                            !//
//!    88   88   88  .d8888b.  dP  88d888b.    !//
//!    88   88   88  88'  '88  88  88'  '88    !//
//!    88   88   88  88.  .88  88  88    88    !//
//!    dP   dP   dP  '88888P8  dP  dP    dP    !//
//!============================================!//
int main()
{
    int N, A, B;
    std::cin >> N >> A >> B;
    const int C = A ^ B;
    int pc = 0;
    for (int i = 0; i < N; i++) { pc += (C & (1 << i)) ? 1 : 0; }
    if (pc % 2 == 0) { return std::cout << "NO" << std::endl, 0; }
    std::vector<int> z, o;
    for (int i = 0; i < N; i++) { ((C & (1 << i)) ? o : z).push_back(i); }
    std::vector<int> pos(N);
    for (int i = 0; i < z.size(); i++) { pos[z[i]] = i; }
    for (int i = 0; i < o.size(); i++) { pos[o[i]] = i + z.size(); }
    auto encode = [&](const int n) {
        int ans = 0;
        for (int i = 0; i < N; i++) { ans |= ((n & (1 << i)) ? 1 : 0) << pos[i]; }
        return ans;
    };
    int D = 0;
    for (int i = 0; i < o.size(); i++) { D |= 1 << (z.size() + i); }
    assert(C == encode(D));
    auto z2o = [&](auto&& self, const int d) -> std::vector<int> {
        if (d == 1) {
            return std::vector<int>{0, 1};
        } else {
            std::vector<int> ans;
            auto route = self(self, d - 1);
            for (const auto r : route) { ans.push_back(r << 1); }
            std::reverse(route.begin(), route.end());
            for (const auto r : route) { ans.push_back(r << 1 | 1); }
            return ans;
        }
    };
    std::vector<int> ans;
    auto route = [&](auto&& self, int D, const int d) -> void {
        if (d == 0) {
            ans.push_back(1), ans.push_back(0);
            return;
        }
        if (D & (1 << d)) {
            const auto way = z2o(z2o, d);
            for (const int w : way) { ans.push_back(w ^ D); }
            (D ^= 1) ^= (1 << d);
            self(self, D, d - 1);
        } else {
            auto way = z2o(z2o, d);
            std::reverse(way.begin(), way.end());
            for (const int w : way) { ans.push_back(w); }
        }
    };
    route(route, D, N - 1);
    std::cout << "YES" << std::endl;
    for (int i = 0; i < (1 << N); i++) { std::cout << (encode(ans[(1 << N) - i - 1]) ^ A) << " "; }
    std::cout << std::endl;
    return 0;
}

