void solve() {
  int n, a, b; cin >> n >> a >> b;

  if (!CoutYN(__builtin_parity(a ^ b), "YES", "NO")) {
    return;
  }

  bitset<17> bs(a ^ b);
  vi ds;
  rep(i,n) if (bs[i]) ds.emplace_back(i);
  int tmp = ds.back(); ds.pop_back();
  rep(i,n) if (!bs[i]) ds.emplace_back(i);
  ds.emplace_back(tmp);

  vi ans(1<<n);
  ans[0] = a;
  tmp = 2;

  rep1(i,1<<n) {
    int k = 31 - __builtin_clz(i ^ (i-1));
    ans[i] = ans[i-1] ^ (1<<ds[k]);
    if (i == 1<<tmp) {
      swap(ds[tmp - 1], ds[tmp - 2]);
      tmp += 2;
      if (tmp > bs.count()) tmp = 0;
    }
  }

  cout << ans << endl;
}


