//--GLOBAL---------------------------------
ll locker[32];
ll N;
vector<ll> solve(ll n, ll a, ll b){
    if(n==1) return {a,b};
    // a,bで異なるkbit目を探す。
    ll k=0;
    rep(i,N) if((a>>i&1)^(b>>i&1)) k=i;
    locker[k]=1;
    // 今まで選んだkbit以外のxbitを変えたものまでの移動
    ll x;
    rep(i,N){
        if(locker[i]==1) continue;
        x=i; break;
    }
    ll c=a^(1<<x);
    auto res1=solve(n-1,a,c);
    // kbitを変えてもとに戻す
    c^=1<<k;
    auto res2=solve(n-1,c,b);
    // 連結してreturn
    res1.insert(res1.end(),ALL(res2));
    locker[k]=0;
    return res1;
}
