vector<int> cycle(int add, int len)
{
	if (len == 0)
	{
		return {add};
	}
	VI V1 = cycle(add + (1<<(len - 1)), len - 1);
	VI V2 = cycle(add, len - 1);
	reverse(ALL(V2));
	for (auto x : V2)
	{
		V1.PB(x);
	}
	return V1;
}

VI mov(VI V, int ind)
{
	VI R;
	FOR(i, ind, ind + SIZ(V) - 1)
	{
		R.PB(V[i % SIZ(V)]);
	}
	return R;
}

