int bitcnt(unsigned int x) {
    x = (x & 0x55555555) + (x >> 1 & 0x55555555);
    x = (x & 0x33333333) + (x >> 2 & 0x33333333);
    x = (x & 0x0f0f0f0f) + (x >> 4 & 0x0f0f0f0f);
    x = (x & 0x00ff00ff) + (x >> 8 & 0x00ff00ff);
    x = (x & 0x0000ffff) + (x >> 16 & 0x0000ffff);
    return (int)x;
}

vi f(int n, int a, int b) {
    if (n == 1) {
        RT vi{ a,b };
    }
    int C = 1 << (n - 1);
    if ((a&C) != (b&C)) {
        vi u = f(n - 1, a, a^1);
        vi v = f(n - 1, a ^ 1 ^ C, b);
        u.insert(u.end(), all(v));
        RT u;
    } else {
        vi u = f(n - 1, a, b);
        vi v = f(n - 1, a^C, u[1] ^ C);
        u.insert(u.begin() + 1, all(v));
        RT u;
    }
}

void solve() {
    int N, A, B;
    cin >> N >> A >> B;

    if (bitcnt(A) % 2 == bitcnt(B) % 2) {
        cout << "NO" << endl;
        return;
    }

    cout << "YES" << endl;
    vi ans = f(N, A, B);
    rep(i, 1 << N)cout << ans[i] << (i != (1 << N) - 1 ? ' ' : '\n');
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

