void gi(int &sum){
    sum = 0;char c = getchar();bool flag = true;
    while(c < '0' || c > '9') {if(c == '-') flag = false;c = getchar();}
    while(c >= '0' && c <= '9') sum = sum * 10 + c - 48,c = getchar();
    if(!flag) sum = -sum;
}
int n,a,b;
int ans[201000];
void work(int x,int y,int l,int r,int n,int det) {
	ans[l] = x^det; ans[r] = y^det;
	if(n == 1) {
		if(x == 0) ans[l+1+(y==1?1:0)] = 3^det ,  ans[l+3-(y==1?2:0)] = 2^det;
		else if(x == 2) ans[l+1+(y==0?1:0)] = 1^det , ans[l+3-(y==0?2:0)] = 3^det;
		else if(x == 3) ans[l+1+(y==2?1:0)] = det , ans[l+3-(y==2?2:0)] = 1^det;
		else if(x == 1) ans[l+1+(y==3?1:0)] = 2^det , ans[l+3-(y==3?2:0)] = det;
		return;
	}
	int f1 = (x>>n&1) , f2 = (y>>n&1) , toy;
	toy = (f1==f2) ? y : y^(1<<n);
	repp(i,n-1,0) if( (toy^(1<<i)) != x ) {toy = y ^ (1<<i);break;} 
	if( f1^f2 ) {
		work( x-(f1?(1<<n):0) , toy - (f2?(1<<n):0) , l , l+(1<<n-1)-1 , n-1 , det+(f1?(1<<n):0) );
		work( toy , y , l+(1<<n-1) , r , n-1 , det+(f2?(1<<n):0) );
	}
	else {
		work( x-(f1?(1<<n):0) , y - (f2?(1<<n):0) , l+(1<<n-1) , r , n-1 , det+(f1?(1<<n):0) );
		work( x^(1<<n) , ans[l+(1<<n-1)+1]^(1<<n) , l+1 , l+(1<<(n-1)) , n-1 , det+(f1?0:(1<<n)) );
	}
}
int main(){
	gi(n); gi(a); gi(b);
	if(n == 1) {
		printf("YES\n");
		printf("%d %d\n",a,b);
		return 0;
	}
	a ^= b;int cnt = 0;rep(i,0,n-1) cnt += a>>i&1;
	if(!(cnt&1)) {printf("NO\n");return 0;} a ^= b;
	work(a,b,1,(1<<n),n-1,0);
	printf("YES\n");
	rep(i,1,(1<<n)) printf("%d ",ans[i]);
	return 0;
}

