using namespace std;
const int N=(1<<17)+10;
int A[20][N],B[N],h1,h2;
void Gray(int n){
    vector<int> res;
    res.clear();
    int c=1,i,j;
    res.push_back(0);
    h2=0;
    for (i=0;i<n;i++){
        for (j=res.size()-1;j>=0;j--){
            res.push_back(res[j]+c);
        }
        c<<=1;
    }
    for (i=0;i<(int)res.size();i++){
    	B[h2++]=res[i];
    }
}
int Rev(int x,int y){
	int i,res=0;
	for (i=0;i<x;i++){
		res=(res<<1)|((y>>i)&1);
	}
	return res;
}
void Zero_To_One(int n){
	int i,j;
	A[1][0]=0,A[1][1]=1;
	for (i=3;i<=n;i+=2){
		Gray(i-1);
		int hh=0;
		for (j=0;j<h2;j++){
			A[i][hh++]=B[j];
		}
		int t=A[i][hh++]=(1<<(i-1))|(1<<(i-2));
		Gray(i-2);
		for (j=0;j<h2;j++){
			A[i][hh++]=B[j]|(1<<(i-1));
		}
		for (j=1;j<(1<<(i-2));j++){
			A[i][hh++]=t|Rev(i-2,A[i-2][j]);
		}
	}
}
int Ans[N],rec[20],bit[20];
int main(){
	int n,i,j,h=0,A_,B_;
	scanf("%d%d%d",&n,&A_,&B_);
	int t=A_^B_;
	int p=__builtin_popcount(t);
	if (p%2==0){
		printf("NO\n");
		return 0;
	}
	if (p==1){
		Gray(n);
		for (i=0;i<h2;i++){
			Ans[i]=B[i]^A_;
		}
		h=h2;
	}else{
		Gray(n-p+1);
		Zero_To_One(p-1);
		for (i=0;i<(1<<(n-p+1));i++){
			for (j=0;j<h2;j++){
				Ans[h++]=(A[n-p+1][i]|(B[j]<<(p-1)))^A_;
			}
		}
	}
	for (i=0;i<n;i++){
		int p=((Ans[h-1]>>i)&1),q=((B_>>i)&1);
		if (p!=q){
			rec[i]=p;
		}else{
			rec[i]=-1;
			bit[i]=i;
		}
	}
	for (i=0,j=n-1;i<n;i++){
		if (rec[i]==1){
			while (rec[j]!=0){
				j--;
			}
			bit[i]=j;
			bit[j]=i;
			j--;
		}
	}
	printf("YES\n");
	for (i=0;i<h;i++){
		int res=0;
		for (j=0;j<n;j++){
			res=res|(((Ans[i]>>j)&1)<<bit[j]);
		}
		printf("%d%c",res," \n"[i==h-1]);
	}
	return 0;
}

