void solve(int N, int A, int B, int mask, int *ans) {
    assert(A != B);
    assert(popcount(A) % 2 != popcount(B) % 2);
    assert((A & ~mask) == (B & ~mask));
    if (N == 1) {
        ans[0] = A;
        ans[1] = B;
    } else {
        REP(i, 17) {
            if (has_bit(mask, i) && has_bit(A, i) != has_bit(B, i)) {
                mask ^= 1 << i;
                int mid = mask;
                while (mid == (A & mask) || mid == (B & mask)
                    || popcount(mid) % 2 == popcount(A & mask) % 2) {
                    mid = (mid - 1) & mask;
                }
                solve(N-1, A & mask, mid, mask, ans);
                solve(N-1, mid, B & mask, mask, ans + shift(N-1));
                if (has_bit(A, i)) {
                    REP(j, 1 << (N-1)) {
                        ans[j] ^= 1 << i;
                    }
                } else {
                    REP(j, 1 << (N-1)) {
                        ans[(1 << N) - 1 - j] ^= 1 << i;
                    }
                }
                assert(ans[(1 << N) - 1] == B);
                break;
            }
        }
    }
}

