#include <bits/stdc++.h>

using namespace std;

void op(vector<int>&v, int yes) {
    if(yes)
        reverse(begin(v), end(v));
}
vector<int>solve(int n, int a, int b) {
    if(n < 1)
        return {};
    bool rev = 0;
    if(a > b)
        swap(a, b), rev = 1;
    if(n == 1) {
        vector<int>c = {a, b};
        op(c, rev);
        return c;
    }
    if(b < (1 << (n - 1))) {
        vector<int>v = solve(n - 1, a, b);
        assert(v[v.size() - 2] != b);
        vector<int>u = solve(n - 1, v[v.size() - 2], b);
        v.pop_back();
        for(int x : u)
            v.push_back(x ^ (1 << (n - 1)));
        v.push_back(b);
        op(v,rev);
        return v;
    } else if(a >= (1 << (n - 1))) {
        vector<int>v = solve(n - 1, a - (1 << (n - 1)), b - (1 << (n - 1)));
        vector<int>u = solve(n - 1, v[v.size() - 2], b - (1 << (n - 1)));
        v.pop_back();
        for(int &val : v)
            val ^= (1 << (n - 1));
        assert(!v.empty());
        for(int x : u)
            v.push_back(x);
        v.push_back(b);
        op(v,rev);
        return v;
    }

    for(int p = 0; p <= 20; p++) {
        int interm = a ^ (1 << p);
        if(interm < (1 << (n - 1)) && interm != b) {
            vector<int>v = solve(n - 1, a, interm);
            vector<int>u = solve(n - 1, interm, b - (1 << (n - 1)));
            for(int& val : u) {
                val ^= (1 << (n - 1));
                v.push_back(val);
            }

            op(v,rev);
            return v;
        }
    }
    assert(5 == 3);
    return {};
}
int main() {
    int n, a, b;
    cin >> n >> a >> b;
    if(__builtin_popcount(a) % 2 == __builtin_popcount(b) % 2) {
        cout << "NO";
        return 0;
    }cout<<"YES\n";
    auto res = solve(n, a, b);
    for(auto it : res)
        cout << it << ' ';
}

