int f(int a, int b, int i, int m, int u) {
  if (i >= 0) {
    int d = __builtin_ctz(a ^ b);
    int x = a & ~(1 << d);
    int y = b & ~(1 << d);
    u |= 1 << d;
    int k = __builtin_ctz(~u);
    f(x, x ^ (1 << k), i - 1, m | (a & (1 << d)), u);
    f(x ^ (1 << k), y, i - 1, m | (b & (1 << d)), u);
  } else {
    cout << m << " ";
  }
}
