bool adj(int a, int b)
{
	int cnt = 0;
	for (int i = 0; i <= 17; ++i)
	{
		int x = (a >> i) & 1;
		int y = (b >> i) & 1;
		if (x != y) ++cnt;
	}
	return cnt == 1;
}

int get(int x)
{
	for (int i = 0; i <= 17; ++i)
	{
		x ^= (1 << i);
		if (vis[x] == 0)
		{
			vis[x] = 1;
			return x;
		}
		x ^= (1 << i);
	}
	return -1;
}	

