int popcnt(int x){return __builtin_popcount(x);}
int popcnt(ll x){return __builtin_popcountll(x);}
int bitdig(int x){return 32 - __builtin_clz(x);}
int bitdig(ll x){return 64 - __builtin_clzll(x);}
