int ex(int x){
    int res = 1;
    while(x > 0){
        res*=2;
        x--;
    }
    return res;
}

int main(){
    int N, A, B;
    cin >> N >> A >> B;

    bool check[210000];
    fill(check, check+210000, false);
    check[A] = true;
    check[B] = true;

    vector<int> hist;
    hist.push_back(A);
    int x = A;
    while(hist.size() < ex(N) - 1){
        bool ok = false;
        for(int i = 0; i < N; i++){
            int tmp;
            if((x >> i) % 2 == 1){
                tmp = x - (1 << i);
            }
            else {
                tmp = x + (1 << i);
            }
            if(!check[tmp]){
                x = tmp;
                check[tmp] = true;
                hist.push_back(x);
                ok = true;
                break;
            }
        }
        if(!ok){
            break;
        }
    }

    if(hist.size() < ex(N) - 1){
        cout << "NO" << endl;
    }
    else{
        cout << "YES" << endl;
        for(auto h: hist){
            cout << h << " ";
        }
        cout << B << endl;
    }


    return 0;
}

