unsigned int popcnt(unsigned int x) {
    x = (x & 0x55555555) + ((x >>  1) & 0x55555555);
    x = (x & 0x33333333) + ((x >>  2) & 0x33333333);
    x = (x & 0x0F0F0F0F) + ((x >>  4) & 0x0F0F0F0F);
    x = (x & 0x00FF00FF) + ((x >>  8) & 0x00FF00FF);
    x = (x & 0x0000FFFF) + ((x >> 16) & 0x0000FFFF);
    return x;
}

unsigned int ntz(unsigned int x) {
    unsigned int n = 1;
    if ((x & 0x0000FFFFull) == 0) { n += 16; x >>= 16; }
    if ((x & 0x000000FFull) == 0) { n +=  8; x >>=  8; }
    if ((x & 0x0000000Full) == 0) { n +=  4; x >>=  4; }
    if ((x & 0x00000003ull) == 0) { n +=  2; x >>=  2; } 
    return n - (x & 1);
}

unsigned int low_bit(unsigned int x, int k) {
    return x & ((1 << k) - 1);
}

unsigned int high_bit(unsigned int x, int k) {
    return x & (~((1 << k) - 1));
}


vector<int> f(int N, int A, int B) {
    vector<int> P(1 << N);
    if (N == 1) {
        P[0] = A;
        P[1] = B;
        return P;
    }
    int x = ntz(A ^ B);
    int A0 = (high_bit(A, x + 1) >> 1) ^ low_bit(A, x);
    int B0 = (high_bit(B, x + 1) >> 1) ^ low_bit(B, x);
    int C;
    if (A0 & 1) {
        C = A0 - 1;
    } else {
        C = A0 + 1;
    }
    vector<int> Q = f(N - 1, A0, C);
    vector<int> R = f(N - 1, C, B0);
    REP(i, 1 << (N - 1)) {
        P[i]                  = (high_bit(Q[i], x) << (x + 1)) ^ (A & (1 << x)) ^ low_bit(Q[i], x);
        P[(1 << (N - 1)) + i] = (high_bit(R[i], x) << (x + 1)) ^ (B & (1 << x)) ^ low_bit(R[i], x);
    }
    return P;
}

