vector<int> solve(int n, int a, int b) {
    if (a != 0) {
        vector<int> res = solve(n, 0, a ^ b);
        for (int& x : res) x ^= a;
        return res;
    }
    if (n == 1) {
        return {0, 1};
    }

    int idx = 0;
    while ((b & (1 << idx)) == 0) {
        idx++;
    }

    int tar = b;
    tar = ((tar >> (idx + 1)) << idx);

    vector<int> v1 = solve(n - 1, 0, 1);
    vector<int> v2 = solve(n - 1, 1, tar);

    vector<int> res;
    for (int x : v1) {
        int foo = (x & ((1 << idx) - 1));
        int bar = ((x >> idx) << (idx + 1));
        x = foo + bar;  
        res.push_back(x);      
    }

    for (int x : v2) {
        int foo = (x & ((1 << idx) - 1));
        int bar = ((x >> idx) << (idx + 1));
        x = foo + bar + (1 << idx);      
        res.push_back(x); 
    }
    return res;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, a, b;
    cin >> n >> a >> b;

    if (n == 1) {
        cout << "YES" << endl;
        cout << a << " " << b << endl;
        return 0;
    }

    if (__builtin_popcount(a ^ b) % 2 == 0) {
        cout << "NO" << endl;
        return 0;
    }

    vector<int> ans = solve(n, a, b);
    cout << "YES" << endl;
    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i] << " \n"[i + 1 == ans.size()];
    }
    return 0;
}

