vector<int> solve(int n, int A, int B) {
	if(n == 1) return {A, B};
	auto x = A ^ B;
	x = x & (-x);
	auto l = __lg(x);
	auto f = [&](int y) {
		return ((y >> (l+1)) << l) ^ (y & (x - 1));
	};

	auto _A = f(A), _B = f(B);
	auto&& p = solve(n-1, _A, _A^1), q = solve(n-1, _A^1, _B);
	auto& change = (A & x ? p : q), &mv = (A & x ? q : p);

	auto g = [&](int y) {
		return ((y >> l) << (l+1)) ^ (y & (x - 1));
	};

	//cerr << "solving for: " << n << ", " << make_pair(A, B) << " converted to: " << make_pair(_A, _B) << " x, l = " << x << ", " << l << endl;
	//cerr << "received: ";
	//for(auto x:p) cerr << x << " ";
	//cerr << " and ";
	//for(auto x:q) cerr << x << " ";
	//cerr << endl;

	for(auto& val:change) {
		val = g(val);
		val ^= x;
	}
	for(auto& val:mv)
		val = g(val);

	//cerr << "converted to: ";
	//for(auto x:p) cerr << x << " ";
	//cerr << " and ";
	//for(auto x:q) cerr << x << " ";
	//cerr << endl;

	for(auto val:q)
		p.push_back(val);

	return p;
}

