int n, s, t, cnt, a[MAXN], ans[MAXN], lft[18], bit[18];
void work(int depth, int pos) {
	if (lft[depth]) {
		lft[depth]--;
		if (depth % 2) a[pos] = depth + 1;
		else a[pos] = depth - 1;
	} else a[pos] = depth;
	if (depth == 1) return;
	work(depth - 1, pos - (1 << (depth - 2)));
	work(depth - 1, pos + (1 << (depth - 2)));
}
