int N,A,B;
int BM[1<<17];

vector<int> hoge(int C) {
	vector<int> R;
	int x,y;
	if(__builtin_popcount(C)==1) {
		FOR(x,N) if(C&(1<<x)) break;
		R.push_back(0);
		R.push_back(1<<x);
		return R;
	}
	FOR(x,N) if(C&(1<<x)) break;
	FOR(y,N) if(x!=y && (C&(1<<y))) break;
	vector<int> T=hoge(C^(1<<x)^(1<<y));

	R=T;
	reverse(ALL(T));
	FORR(t,T) R.push_back(t^(1<<x));
	reverse(ALL(T));
	int step=0;
	FORR(t,T) {
		if(step==0) {
			R.push_back(t^(1<<x)^(1<<y));
			R.push_back(t^(1<<y));
		}
		else {
			R.push_back(t^(1<<y));
			R.push_back(t^(1<<x)^(1<<y));
		}
		step^=1;
	}
	return R;

}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>A>>B;

	int num[2]={};
	for(int mask=0;mask<1<<N;mask++) {
		BM[mask]=__builtin_popcount(mask)%2;
	}
	if(BM[A]==BM[B]) {
		cout<<"NO"<<endl;
		return;
	}
	int C=A^B;
	int sub=C^((1<<N)-1);
	vector<int> V;
	V.push_back(0);
	FOR(i,N) if(sub&(1<<i)) {
		vector<int> V2=V;
		reverse(ALL(V));
		FORR(v,V) V2.push_back((1<<i)|v);
		swap(V,V2);
	}

	vector<int> W=hoge(C);

	vector<int> R;
	FORR(w,W) {
		FORR(v,V) R.push_back(w^v^A);
		reverse(ALL(V));
	}
	FOR(i,R.size()-1) {
		assert(__builtin_popcount(R[i]^R[i+1])==1);
	}
	assert(R[0]==A);
	assert(R.back()==B);

	cout<<"YES"<<endl;
	FORR(r,R) cout<<r<<" ";
	cout<<endl;
}


