vector<int> solve(int n, int a, int b) {
    if (a != 0) {
        vector<int> res = solve(n, 0, a ^ b);
        for (int& x : res) x ^= a;
        return res;
    }
    if (n == 1) {
        return {0, 1};
    }

    int idx = 0;
    while ((b & (1 << idx)) == 0) {
        idx++;
    }

    int tar = b;
    tar = ((tar >> (idx + 1)) << idx);
    //cerr << n << "," << tar << "," << idx << endl;

    if (tar == 0) {
        vector<int> res;
        vector<int> codes = gray_code(n - 1);
        res = codes;
        for (int& x : res) {
            int foo = (x & ((1 << idx) - 1));
            int bar = ((x >> idx) << (idx + 1));
            x = foo + bar;            
        }
        reverse(codes.begin(), codes.end());
        for (int x : codes) {
            int foo = (x & ((1 << idx) - 1));
            int bar = ((x >> idx) << (idx + 1));
            x = foo + bar + (1 << idx);   
            res.push_back(x);
        }
        return res;
    }

    int idx2 = 0;
    while ((tar & (1 << idx2)) == 0) {
        idx2++;
    }

    vector<int> v1 = solve(n - 1, 0, (1 << idx2));
    vector<int> v2 = solve(n - 1, (1 << idx2), tar);

    vector<int> res;
    for (int x : v1) {
        int foo = (x & ((1 << idx) - 1));
        int bar = ((x >> idx) << (idx + 1));
        x = foo + bar;  
        res.push_back(x);      
    }

    for (int x : v2) {
        int foo = (x & ((1 << idx) - 1));
        int bar = ((x >> idx) << (idx + 1));
        x = foo + bar + (1 << idx);      
        res.push_back(x); 
    }
    return res;
}

