    cin >> n >> s >> t, N = pow2(n);
    ans.assign(N,0);
    if ((popcount(s)^popcount(t)%2) == 0) {
        cout << "NO" << endl;
        return 0;
    }
    solve(0,N,s,t,vector<int>(n,0));
    cout << "YES" << endl;
    rep(i,N) cout << ans[i] << " \n"[i==N-1];
    return 0;
}

