}

void binaryprint(int x, int minlen){
	std::vector<char> dig;
	while(x>0){
		dig.push_back(x%2 == 0 ? '0':'1');
		x>>=1;
	}
	while(dig.size() < minlen) dig.push_back('0');
	while(!dig.empty()){
		printf("%c", dig.back());
		dig.pop_back();
	} return;
}

std::vector<int> newconstruct(int upbound, int changing){

	if(upbound+1 < changing){
		printf("Too large changing = %d for upbound = %d\n", changing, upbound);
		throw "ERROR";
	}
	else if(upbound == 2 && changing == 3) return {0, 1, 0, 2, 1, 0, 1};
	else if(upbound == 0){
		if(changing == 1) return {0};
		else{
			printf("upbound = 0, changing = %d ??\n", changing);
			throw "ERROR";
		}
	}
	else if(changing == 1){
		std::vector<int> result, half = newconstruct(upbound-1, 1);
		append(result, half);
		result.push_back(upbound);
		append(result, half);
		return result;
	}
	else{
		std::vector<int> quarter1 = newconstruct(upbound-2, changing-2);
		std::vector<int> pure = newconstruct(upbound-2, 1);
		std::vector<int> result;

		append(result, quarter1);
		result.push_back(upbound-1);
		append(result, pure);
		result.push_back(upbound);

		std::vector<int> backhalf;
		append(backhalf, pure);
		backhalf.push_back(upbound-1);
		append(backhalf, pure);
		for(int i=0; i<backhalf.size(); i++){
			if(backhalf[i] == upbound-1) backhalf[i] = upbound-2;
			else if(backhalf[i] == upbound-2) backhalf[i] = upbound-1;
		}
		append(result, backhalf);
		return result;
	}

}

