ll rem(ll x, ll k){
    ll t1 = x >> (k + 1);
    x &= (1LL << k) - 1;
    return (t1 << k) + x;
}

ll ins(ll x, ll k, ll one){
    ll t1 = x >> k;
    x &= (1LL << k) - 1;
    return (t1 << (k+1)) + x + (one << k);
}
