            // 最下位桁からビット反転
            now = now ^ (1 << i);
            cout << " " << now;
        }
        for (int i = 0; i < n; i++) {
            if (!bs[i]) {
                // 最下位桁からビット反転
                now = now ^ (1 << i);
                cout << " " << now;
            }
        }
        cout << endl;
    } else {
        cout << "NO" << endl;
    }

