		b += (B >> i) & 1 ? "1" : "0";
	}
	reverse(a.begin(), a.end());
	reverse(b.begin(), b.end());

	nseg = N / 4;
	vector<int> seglen;
	for (int i = 0; i < nseg; i++) seglen.push_back(4);
	if (N < 4) seglen.push_back(N), nseg++;
	else if (N % 4 <= 1) seglen.back() += 1;
	else seglen.push_back(N % 4), nseg++;

	for (int i = 0; i < nseg; i++) {
		string d = a.substr(4 * i, seglen[i]);
		string targ = d;
