VI gendiff(int n){
	if (n==1) {VI v(2,0); v[1]=1<<difs[0]; return v;}
	VI base=gendiff(n-2);
	int sb=base.size();
	int st=0;
	VI res(0);
	int j=0;
	int nn=1<<difs[n-1];
	int nn2=1<<difs[n-2];
	REP(i,sb){res.PB(base[i]);}
	REP(i,sb){res.PB(base[sb-1-i]+nn);}
	VI t={nn+nn2,nn2};
	int last=0;
	while (j<sb){
		res.PB(base[j]+t[st]);
		if ((st+1)%2==last){j++;last=st;}
		else {st++; st%=2; }
	}
	return res;
}

