const int bit[18] = {1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536, 131072};

void recursion(int n, int flag[], int a, int b, int ans[])
{
	if (n == 1) {
		ans[0] = a;
		ans[bit[n]-1] = b;
		return;
	}

	int i, j, k, l;
	for (i = a, j = b, k = 0; flag[k] != 0 || (i & 1) == (j & 1); i >>= 1, j >>= 1, k++);
	flag[k] = 1;
	for (l = 0; flag[l] != 0; l++);
	recursion(n - 1, flag, a, a ^ bit[l], ans);
	recursion(n - 1, flag, a ^ bit[l] ^ bit[k], b, &(ans[bit[n-1]]));
	flag[k] = 0;
}

int main()
{
	int N, A, B;
	scanf("%d %d %d", &N, &A, &B);

	int i, j , count = 0;
	for (i = A, j = B; i > 0 || j > 0; i >>= 1, j >>= 1) if ((i & 1) != (j & 1)) count++;
	if (count % 2 == 0) {
		printf("NO\n");
		fflush(stdout);
		return 0;
	}

	int ans[131072], flag[18] = {};
	recursion(N, flag, A, B, ans);
	printf("YES\n");
	for (i = 0; i < bit[N] - 1; i++) printf("%d ", ans[i]);
	printf("%d\n", ans[bit[N]-1]);
	fflush(stdout);
	return 0;
}

