#define BASE ((int)10)
#define MAX_LEN ((size_t)11)
    static char c[MAX_LEN];
    size_t i=MAX_LEN-1;
    do{
        c[i]=n%BASE+'0';
        n/=BASE;
        i--;
    }while(n>0);
    len+=MAX_LEN-1-i;
    do{
        ++i;
        buf[len+i-MAX_LEN] = c[i];
    }while(i<MAX_LEN-1);
#undef MAX_LEN
#undef BASE
}

