bool isodd(ll a, int N){
  ll mask = 1;
  int cnt = 0;
  rep(i, N){
    if(a & mask) cnt++;
    mask = mask << 1;
  }
  return cnt % 2;
}

int diff_idx(ll a, ll b, int N){
  ll mask = 1;
  ll axorb  = a ^ b;
  rep(i, N){
    if(axorb & mask) return i;
    mask = mask << 1;
  }
  return -1;
}

v differ_by_1bit(ll a, ll b, int N){
  v ans;
  if(N == 1){
    ans.push_back(a);
    ans.push_back(b);
  }else{
    int atail = a % 2;
    int btail = b % 2;
    ll a_ = a / 2;
    ll b_ = b / 2;

    if(atail == btail){
      v ch = differ_by_1bit(a_, b_, N-1);
      int tail = atail;
      rep(i, 1 << (N-1)){
        ans.push_back(ch[i] * 2 + tail);
        ans.push_back(ch[i] * 2 + 1 - tail);
        tail = 1 - tail;
      }
    }else{
      v ch1 = differ_by_1bit(a_, a_^1, N-1);
      v ch2 = differ_by_1bit(a_^1, b_, N-1);
      rep(i, 1 << (N-1)) ans.push_back(ch1[i] * 2 + atail);
      rep(i, 1 << (N-1)) ans.push_back(ch2[i] * 2 + btail);
    }
  }
  return ans;
}

