void bitswap (sll *x, ull a, ull b) {
	if (((*x & (1LL << a)) ? 1 : 0) ^ ((*x & (1LL << b)) ? 1 : 0)) {
		*x ^= (1LL << a);
		*x ^= (1LL << b);
	}
}

void make (ull all, ull ones) {
	sll i;
	if (ones == 1) {
		for (i = 0; !(i >> all); i++) {
			a[i] = i ^ (i >> 1);
		}
		return;
	}

	make(all - 1, ones - 2);
	ull border = (1LL << (all - 1));
	for (i = 0; i < border; i++) {
		bitswap(&a[i], all - ones, all - 2);
	}
	ull mask = a[border - 1] + (1LL << (all - 1));
	for (i = 0; i < border; i++) {
		a[border + i] = mask ^ (i ^ (i >> 1));
	}
}

