void reverse(int *a,int l,int r){
  for(int i=l;i<r-1-(i-l);i++){
    int swap=a[i];
    a[i]=a[r-1-(i-l)];
    a[r-1-(i-l)]=swap;
  }
}

void run(void){
  int n,a,b;
  scanf("%d%d%d",&n,&a,&b);
