  int c=a^b;
  int k=popcnt(c);
  for(int cnt=3;cnt<=k;cnt+=2){
    for(i=len-2;i>=0;i--){
      if(diff(code[len-1],code[i-1])==1 && popcnt(code[i])==cnt){
