fun toBin(n : Int, a : Int) : List<Int>{
    val bin = mutableListOf<Int>()
    var x = a
    for(i in 1..n){
        bin.add(x % 2)
        x /= 2
    }
    return bin.reversed()
}

fun toInt(n : Int, bin : MutableList<Int>) : Int{
    val revBin = bin.reversed()
    var ret = 0
    for(i in 0..(n - 1)){
        ret += Math.pow(2.0, i.toDouble()).toInt() * revBin[i]
    }
    return ret
}

