public class Main {

    static int N, A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextInt();
        B = sc.nextInt();

        int[] ans = solve();
        PrintWriter pw = new PrintWriter(System.out);
        if( ans != null ) {
            // check(ans);
            pw.println("Yes");
            StringJoiner j = new StringJoiner(" ");
            for (int i : ans) {
                j.add(String.valueOf(i));
            }
            pw.println( j.toString() );

        } else {
            pw.println("No");
        }
        pw.flush();
