import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    BufferedReader in = new BufferedReader(new InputStreamReader(System.in), 1000000);
    StringTokenizer tok = new StringTokenizer("");
    StringBuilder out = new StringBuilder();

    String next() throws IOException {
        if (!tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine());
        }
        return tok.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    int n = 0;
    int k = 0;

    void go(int a, int b, int mask, char removed) {
        if (removed == k - 1) {
            out.append(a + " " + b + " ");
        } else {
            int k1 = 0;
            for (int i = 0; i < k; i++) {
                if ((mask & (1 << i)) == 0 && ((a ^ b) & (1 << i)) > 0) {
                    mask |= (1 << i);
                    removed++;
                    k1 = i;
                    break;
                }
            }
            int a1 = 0;
            for (int j = 0; j < k; j++) {
                if ((mask & (1 << j)) == 0) {
                    a1 = a ^ (1 << j);
                    break;
                }
            }
            go(a, a1, mask, removed);
            go((a1 ^ (1 << k1)), b, mask, removed);
        }
    }

    void slave() throws IOException {
        k = nextInt();
        int A = nextInt();
        int B = nextInt();
        n = 1 << k;
        if (Integer.bitCount(A ^ B) % 2 == 0) {
            out.append("NO");
        } else {
            out.append("YES\n");
            go(A, B, 0, (char) 0);
        }
        System.out.print(out);
    }

    public static void main(String[] args) throws IOException {
        new Main().slave();
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
	Scanner sc = new Scanner(System.in);

	public static void main(String[] args) {
		Main m = new Main();
		m.run();
	}

	void run() {
		int n = sc.nextInt();

		int a = sc.nextInt();
		int b = sc.nextInt();

		int target  = a^b;

		int bc = Integer.bitCount(target);
		if(bc % 2 ==0 ) {
			System.out.println("NO");
			return;
		}

		System.out.println("YES");

		System.out.print(a);

		int[][] xx = new int[n][2];
		for(int i = 0 ; i < n; i++) {
			xx[i][0] = (target>>i)%2;
			xx[i][1] = i;					
		}
		Arrays.sort(xx, (x1,x2) -> x1[0]-x2[1]);

		int g[] = new int[n];

		for(int i = 0 ; i < (1 << n) -1; i++) {			
			int x = Integer.numberOfTrailingZeros(Integer.lowestOneBit(i));
			if(x == 32) {
				x=0;
			}

			for(int j = 1 ; j <= bc/2; j++) {
				int jj = 1<<(j*2);
				if(jj <= (1<<n)-i) {
					x = x ^ 1;
				}
			}
			int y = xx[x][1];
			g[x] = 1-g[y];


			int r = 0;
			for(int k = 0; k < n; k++) {
				r*=2;
				r+=g[k];
			}
			System.out.print(" "+(r^a));
		}
	}



}

import java.io.*;
import java.util.*;

class Solver {
  final int n, a, b;

  Solver(int n, int a, int b) {
    this.n = n;
    this.a = a;
    this.b = b;
  }

  private List<Integer> insertSameBit(List<Integer> path, int mask) {
    List<Integer> newPath = new ArrayList<>();
    for (int i = 0; i < path.size(); i += 2) {
      int v1 = path.get(i);
      int v2 = path.get(i + 1);
      newPath.add(v1);
      newPath.add(v1 ^ mask);
      newPath.add(v2 ^ mask);
      newPath.add(v2);
    }
    return newPath;
  }

  private List<Integer> insertDifferentBits(List<Integer> path, int mask1, int mask2) {
    List<Integer> newPath = new ArrayList<>();
    for (int i = 0; i < path.size(); i += 2) {
      int v1 = path.get(i);
      int v2 = path.get(i + 1);
      newPath.add(v1);
      newPath.add(v1 ^ mask1);
      newPath.add(v2 ^ mask2);
      newPath.add(v2 ^ (mask1 | mask2));
      newPath.add(v2 ^ mask1);
      newPath.add(v1 ^ mask2);
      newPath.add(v1 ^ (mask1 | mask2));
      newPath.add(v2);
    }
    return newPath;
  }

  private List<Integer> buildPath(int a, int b) {
    List<Integer> sameBitIndexes = new ArrayList<>();
    List<Integer> differentBitIndexes = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      int aBit = (a >> i) & 1;
      int bBit = (b >> i) & 1;
      if (aBit != bBit) {
        differentBitIndexes.add(i);
      } else {
        sameBitIndexes.add(i);
      }
    }
    if (differentBitIndexes.size() % 2 == 0) {
      return null;
    }

    List<Integer> path = Arrays.asList(a, b);
    for (int i = 0; i + 1 < differentBitIndexes.size(); i += 2) {
      path = insertDifferentBits(path, 1 << differentBitIndexes.get(i), 1 << differentBitIndexes.get(i + 1));
    }
    for (int i : sameBitIndexes) {
      path = insertSameBit(path, 1 << i);
    }
    return path;
  }

  public List<String> solve() {
    List<Integer> path = buildPath(a, b);
    if (path == null) {
      return Arrays.asList("NO");
    }
    StringBuffer sb = new StringBuffer();
    sb.append(path.get(0));
    for (int i = 1; i < path.size(); i++) {
      sb.append(" ");
      sb.append(path.get(i));
    }
    return Arrays.asList("YES", sb.toString());
  }
}

