            return Integer.parseInt(string());
        }

    }

    static final class BitMath {
        private BitMath() {
        }

        public static int count(int v) {
            v = (v & 0x55555555) + ((v >> 1) & 0x55555555);
            v = (v & 0x33333333) + ((v >> 2) & 0x33333333);
            v = (v & 0x0f0f0f0f) + ((v >> 4) & 0x0f0f0f0f);
            v = (v & 0x00ff00ff) + ((v >> 8) & 0x00ff00ff);
            v = (v & 0x0000ffff) + ((v >> 16) & 0x0000ffff);
            return v;
        }

    }
}

public class Main {

  private static void solve() {
    int n = ni();
    int a = ni();
    int b = ni();

    if (Integer.bitCount(a) % 2 == Integer.bitCount(b) % 2) {
      System.out.println("NO");
      return;
    }

    int[] ret = dfs(a, b, n, 0, (1 << n) - 1);


    System.out.println("YES");
    for (int v : ret) {
      System.out.print(v + " ");
    }
    System.out.println();
  }


  private static int[] dfs(int a, int b, int n, int k, int mask) {
    a &= mask;
    b &= mask;

    if (k == n - 1) {
      return new int[] {a, b};
    }
    int diff = -1;
    int change = -1;
    boolean aOne = false;
    for (int i = 0; i < n; i++) {
      if (((mask >> i) & 1) == 0)
        continue;

      int ba = (a >> i) & 1;
      int bb = (b >> i) & 1;

      if (diff < 0 && ba != bb) {
        diff = i;
        if (ba == 1) {
          aOne = true;
        }
      } else {
        change = i;
      }
    }
    if (change < 0) {
      throw new RuntimeException();
    }

    int c = a ^ (1 << change);

    int[] l = dfs(a, c, n, k + 1, mask ^ (1 << diff));
    int[] r = dfs(c ^ (1 << diff), b, n, k + 1, mask ^ (1 << diff));
    int m = l.length;
    int[] ret = new int[m * 2];
    int p = 0;
    for (int i = 0; i < m; i++) {
      if (aOne) {
        l[i] |= 1 << diff;
      }
      ret[p++] = l[i];
    }
    for (int i = 0; i < m; i++) {
      if (!aOne) {
        r[i] |= 1 << diff;
      }
      ret[p++] = r[i];
    }
    return ret;
  }

