import java.io.*;
import java.util.*;

class Solver {
  final int n, a, b;

  Solver(int n, int a, int b) {
    this.n = n;
    this.a = a;
    this.b = b;
  }

  private List<Integer> insert(List<Integer> path, int mask) {
    List<Integer> newPath = new ArrayList<>();
    for (int i = 0; i < path.size(); i += 2) {
      int v1 = path.get(i);
      int v2 = path.get(i + 1);
      newPath.add(v1);
      newPath.add(v1 ^ mask);
      newPath.add(v2 ^ mask);
      newPath.add(v2);
    }
    return newPath;
  }

  private List<Integer> buildPath(int a, int b) {
    List<Integer> path = Arrays.asList(a, b);
    for (int i = 0; i < n; i++) {
      int aBit = (a >> i) & 1;
      int bBit = (b >> i) & 1;
      if (aBit != bBit) {
        continue;
      }
      path = insert(path,  1 << i);
    }
    return path;
  }

  public List<String> solve() {
    List<Integer> path = buildPath(a, b);
    if (path.size() < (1 << n)) {
      return Arrays.asList("NO");
    }
    StringBuffer sb = new StringBuffer();
    sb.append(path.get(0));
    for (int i = 1; i < path.size(); i++) {
      sb.append(" ");
      sb.append(path.get(i));
    }
    return Arrays.asList("YES", sb.toString());
  }
}

