import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	InputStream is;
	PrintWriter out;
	String INPUT = "";

	void solve() {
		solve(ni(),ni(),ni());
	}

	StringBuffer sb = new StringBuffer();

	void solve(int n, int A, int B) {
		if (Integer.bitCount(A) == Integer.bitCount(B)) {
			System.out.println("NO");
			return;
		}

		sb.append("YES").append("\r\n");
		go(A, B, (1 << n) - 1);
		System.out.println(sb);
	}

	private void go(int a, int b, int f) {
//		Helper.tr(a, b, f);
		if (a == b) {
			sb.append(a).append(" ");
			return;
		}
		int d = a ^ b;
		int l = d & -d;
		f ^= l;
		int n = f & -f;
		go(a, a ^ n, f);
		go(a ^ n ^ l, b, f);
	}

	void run() throws Exception {
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);
		Thread t = new Thread(null, null, "~", Runtime.getRuntime().maxMemory()) {
			@Override
			public void run() {
				long s = System.currentTimeMillis();
				solve();
				out.flush();
				if (!INPUT.isEmpty())
					tr(System.currentTimeMillis() - s + "ms");
			}
		};
		t.start();
		t.join();

		// long s = System.currentTimeMillis();
		// solve();
		// out.flush();
		// if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
	}

	public static void main(String[] args) throws Exception {
		new Main().run();
	}

	private byte[] inbuf = new byte[1024];
	public int lenbuf = 0, ptrbuf = 0;

	private int readByte() {
		if (lenbuf == -1)
			throw new InputMismatchException();
		if (ptrbuf >= lenbuf) {
			ptrbuf = 0;
			try {
				lenbuf = is.read(inbuf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (lenbuf <= 0)
				return -1;
		}
		return inbuf[ptrbuf++];
	}

	private boolean isSpaceChar(int c) {
		return !(c >= 33 && c <= 126);
	}

	private int skip() {
		int b;
		while ((b = readByte()) != -1 && isSpaceChar(b))
			;
		return b;
	}

	private double nd() {
		return Double.parseDouble(ns());
	}

	private char nc() {
		return (char) skip();
	}

	private String ns() {
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != ' ')
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private char[] ns(int n) {
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while (p < n && !(isSpaceChar(b))) {
			buf[p++] = (char) b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private char[][] nm(int n, int m) {
		char[][] map = new char[n][];
		for (int i = 0; i < n; i++)
			map[i] = ns(m);
		return map;
	}

	private int[] na(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = ni();
		return a;
	}

	private int ni() {
		int num = 0, b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private long nl() {
		long num = 0;
		int b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}
}

import java.io.*;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.Function;

public class Main {

    static int N, A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextInt();
        B = sc.nextInt();

        int[] ans = solve();
        PrintWriter pw = new PrintWriter(System.out);
        if( ans != null ) {
            pw.println("Yes");
            StringJoiner j = new StringJoiner(" ");
            for (int i : ans) {
                j.add(String.valueOf(i));
            }
            pw.println( j.toString() );

        } else {
            pw.println("No");
        }
        pw.flush();
    }

    static int[] solve() {
        if( !isAdj(A, B) ) return null;

        int[] path = new int[1 << N];
        // 00 01 11 10
        int[] seq = gen();

        // 000 001 011 010
        for (int i = 0; i < 1 << (N-1); i++) {
            path[i] = seq[i];
        }
        // 110 111 101 100
        for (int i = 0; i < 1 << (N-1); i++) {
            path[(1 << N)-i-1] = seq[i] | (1 << (N-1));
        }

        return modify(path);
    }

    static int[] modify(int[] path) {
        int[] ret = new int[path.length];
        ret[0] = A;

        for (int i = 1; i < path.length; i++) {
            int prev = path[i-1];
            int cur = path[i];

            ret[i] = ret[i-1] ^ prev ^ cur;
        }
        return ret;
    }

    static int[] gen() {
        int bit = N-1;
        int[] ret = new int[1 << bit];
        ret[0] = 0;
        for (int i = 0; i < bit; i++) {
            ret[i+1] = ret[i] | (1 << i);
        }
        for (int i = 0; i < bit - 1; i++) {
            ret[i+bit+1] = ret[i+bit] ^ (1 << i);
        }
        return ret;
    }

    static int differ(int a, int b) {
        for (int i = 0; i < N; i++) {
            int c = 1 << i;

            boolean aon = (a & c) > 0;
            boolean bon = (b & c) > 0;
            if( aon != bon ) {
                return i;
            }

        }
        throw new IllegalArgumentException("wtf");
    }

    static boolean isAdj(int a, int b) {
        int cnt = 0;
        for (int i = 0; i < N; i++) {
            int c = 1 << i;

            boolean aon = (a & c) > 0;
            boolean bon = (b & c) > 0;
            if( aon != bon ) {
                cnt++;
            }

        }
        // 奇数だとよい
        return cnt % 2 == 1;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

import java.util.*;

public class Main {

	int N;
	long A, B;
	char[] aBit, bBit;
	boolean isEnable = false;
	boolean nowTrans = true;

	Main() {
		Scanner in = new Scanner(System.in);
		N = in.nextInt();
		A = in.nextLong();
		B = in.nextLong();
		in.close();
		this.aBit = toBitArray(A);
		this.bBit = toBitArray(B);
		if (this.getDiff(aBit, bBit) % 2 == 1) {
			this.isEnable = true;
		} else {
			this.isEnable = false;
		}
	}

	void show() {
		long val = Long.parseLong(new String(aBit), 2);
		System.out.print(val + " ");

		if (getDiff(aBit, bBit) > 0) {
			// 近づける
			int index = -1;
			for (int i = N; i >= 0; --i) {
				if (aBit[i] != bBit[i]) {
					index = i;
					break;
				}
			}
			aBit[index] = bBit[index];
		} else {
			// 最後だけ変える
			if (aBit[aBit.length - 1] == '0') {
				aBit[aBit.length - 1] = '1';
			} else {
				aBit[aBit.length - 1] = '0';
			}
		}
	}

	char[] toBitArray(long val) {
		char[] result = new char[N + 1];
		Arrays.fill(result, '0');
		for (int i = N; i >= 0; --i) {
			if (val % 2 == 1) {
				result[i] = '1';
			}
			val >>= 1;
		}
		return result;
	}

	int getDiff(char[] aBit, char[] bBit) {
		int diff = 0;
		for (int i = 0; i < aBit.length; ++i) {
			if (aBit[i] != bBit[i]) {
				++diff;
			}
		}
		return diff;
	}

	public static void main(String[] args) {
		Main ins = new Main();
		if (!ins.isEnable) {
			System.out.println("NO");
		} else {
			System.out.println("YES");
			long max = (long) (Math.pow(2.0, (double) (ins.N)));
			for(long i = 0; i < max; ++i) {
				ins.show();
			}
			System.out.println("");
		}

	}

}

