            int idx = 0;
            for (int i = 0; i < full.length; i++) {
                for (int j = 0; j < suf.length; j++) {
                    changes[idx++] = suf[j];
                }
                changes[idx++] = full[i];
            }
            for (int i = 0; i < suf.length; i++) {
                changes[idx++] = suf[i];
            }
            pw.println("YES");
            pw.print(a);
            for (int i = 0; i < changes.length; i++) {
                a ^= 1 << changes[i];
                pw.print(" " + a);
            }
