/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author anand.oza
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CDifferBy1Bit solver = new CDifferBy1Bit();
        solver.solve(1, in, out);
        out.close();
    }

    static class CDifferBy1Bit {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int k = in.nextInt();
            int n = 1 << k;
            int a = in.nextInt(), b = in.nextInt();

            if (Integer.bitCount(a ^ b) % 2 == 0) {
                out.println("NO");
                return;
            }

            out.println("YES");
            int[] answer = solveAbsolute(a, b, n);

            StringBuilder sb = new StringBuilder();
            for (int x : answer) {
                sb.append(x + " ");
            }
            sb.deleteCharAt(sb.length() - 1);
            out.println(sb);
        }

        private static int[] solveAbsolute(int a, int b, int n) {
            int d = a ^ b;
            int[] answer = solveRelative(d, n, n - 1);

            for (int i = 0; i < n; i++) {
                answer[i] ^= a;
            }

            return answer;
        }

        private static int[] solveRelative(int d, int n, int bitsToUse) {
            int[] answer = new int[n];

            if (Integer.bitCount(bitsToUse) == 1) {
                return new int[]{0, bitsToUse};
            }

            d &= bitsToUse;

            int bit;
            if (d == 0) {
                bit = Integer.lowestOneBit(bitsToUse);
            } else {
                bit = Integer.lowestOneBit(d);
                d ^= bit;
            }

            int[] half = solveRelative(d, n / 2, bitsToUse ^ bit);
            for (int i = 0; i < n / 2; i++) {
                answer[i] = half[i];
            }
            for (int i = 0; i < n / 2; i++) {
                answer[i + n / 2] = half[n / 2 - 1 - i] | bit;
            }

            return answer;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * @author Don Li
 */
public class Main {
    void solve() {
        int n = in.nextInt();
        int a = in.nextInt(), b = in.nextInt();

        if (Integer.bitCount(a) % 2 == Integer.bitCount(b) % 2) {
            out.println("NO");
            return;
        }

        out.println("YES");
        int[] res = build(n, a, b);
        for (int i = 0; i < 1 << n; i++) {
            if (i > 0) out.print(' ');
            out.print(res[i]);
        }
    }

    int[] build(int n, int a, int b) {
        if (n == 1) {
            return new int[]{a, b};
        }

        int x = Integer.numberOfTrailingZeros(a ^ b);

        int aa = (a >> x + 1) << x | (a & (1 << x) - 1);
        int bb = (b >> x + 1) << x | (b & (1 << x) - 1);
        int cc = aa ^ 1;
        int[] p = build(n - 1, aa, cc), q = build(n - 1, cc, bb);

        int[] res = new int[1 << n];
        for (int i = 0; i < 1 << n - 1; i++) {
            int u = p[i] & ~((1 << x) - 1);
            int v = p[i] & (1 << x) - 1;
            res[i] = u << 1 | (a & 1 << x) | v;
        }
        for (int i = 0; i < 1 << n - 1; i++) {
            int u = q[i] & ~((1 << x) - 1);
            int v = q[i] & (1 << x) - 1;
            res[(1 << n - 1) + i] = u << 1 | (b & 1 << x) | v;
        }
        return res;
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new Main().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

    int n, a, b;

    void run() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        a = sc.nextInt();
        b = sc.nextInt();

        if (Integer.bitCount(a^b) % 2 == 0) {
            System.out.println("NO");
            return;
        }
        System.out.println("YES");
        boolean[] used = new boolean[1 << n];
        int[] ans = new int[1<<n];

        for (int i = 0; i < (1 << n) - 2; i++) {
            used[a] = true;
            ans[i] = a;
            boolean br = false;
            int r = 2;
            while (!br) {
                for (int j = 0; j < n; j++) {
                    int next = a ^ (1 << j);
                    if (used[next] || next == b) continue;
                    a = next;
                    br = true;
                    break;
                }
                if (!br) {
                    reverse(ans, i - (1 << r), i);
                    a = ans[i];
                    r += 2;
                }
            }
        }
        ans[(1 << n) - 2] = a;
        ans[(1 << n) - 1] = b;
        boolean check = true;
        for (int i = 0; i < (1 << n) - 1; i++) {
            System.out.print(ans[i] + " ");
            check &= Integer.bitCount(ans[i]^ans[i + 1]) == 1;
        }
        debug(check);
        System.out.println(b);
    }

    void reverse(int[] ar, int l, int r) {
        int c = (l + r) / 2 - l;
        for (int i = 0; i < c; i++) {
            int tmp = ar[l + i];
            ar[l + i] = ar[r - i];
            ar[r - i] = tmp;
        }
    }

    void debug(Object...os) {
        System.err.println(Arrays.deepToString(os));
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

