    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int from = in.readInt();
            int to = in.readInt();

            if (Integer.bitCount(from ^ to) % 2 == 0) {
                out.printLine("NO");
                return;
            }

            out.printLine("YES");
            boolean[] used = new boolean[1 << n];
            used[from] = true;
            int cur = from;
            for (int i = 0; i < (1 << n) - 1; i++) {
                out.print(cur + " ");
                for (int j = 0; j < n; j++) {
                    if ((cur ^ (1 << j)) != to && !used[cur ^ (1 << j)]) {
                        cur ^= 1 << j;
                        used[cur] = true;
                        break;
                    }
                }
            }

            out.printLine(to);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }
}

import java.util.*;

public class Main {

	int N;
	long A, B;
	char[] aBit, bBit;
	boolean isEnable = false;
	boolean nowTrans = true;

	Main() {
		Scanner in = new Scanner(System.in);
		N = in.nextInt();
		A = in.nextLong();
		B = in.nextLong();
		in.close();
		this.aBit = toBitArray(A);
		this.bBit = toBitArray(B);
		if (this.getDiff(aBit, bBit) % 2 == 1) {
			this.isEnable = true;
		} else {
			this.isEnable = false;
		}
	}

	void show() {
		long val = Long.parseLong(new String(aBit), 2);
		System.out.print(val);

		if (getDiff(aBit, bBit) > 0) {
			// 近づける
			int index = -1;
			for (int i = N; i >= 0; --i) {
				if (aBit[i] != bBit[i]) {
					index = i;
					break;
				}
			}
			aBit[index] = bBit[index];
		} else {
			// 最後だけ変える
			if (aBit[aBit.length - 1] == '0') {
				aBit[aBit.length - 1] = '1';
			} else {
				aBit[aBit.length - 1] = '0';
			}
		}
	}

	char[] toBitArray(long val) {
		char[] result = new char[N + 1];
		Arrays.fill(result, '0');
		for (int i = N; i >= 0; --i) {
			if (val % 2 == 1) {
				result[i] = '1';
			}
			val >>= 1;
		}
		return result;
	}

	int getDiff(char[] aBit, char[] bBit) {
		int diff = 0;
		for (int i = 0; i < aBit.length; ++i) {
			if (aBit[i] != bBit[i]) {
				++diff;
			}
		}
		return diff;
	}

	public static void main(String[] args) {
		Main ins = new Main();
		if (!ins.isEnable) {
			System.out.println("NO");
		} else {
			System.out.println("YES");
			long max = (long) (Math.pow(2.0, (double) (ins.N)));
			for (long i = 0; i < max; ++i) {
				ins.show();
				if (i != max - 1) {
					System.out.print(" ");
				}
			}
			System.out.println("");
		}

	}

}

