        List<Integer> f(int n, int a, int b) {
            if (Integer.bitCount(a) % 2 == Integer.bitCount(b) % 2) {
                return null;
            }

            b ^= a;
            List<int[]> sw = new ArrayList<>();
            for (int i = 0, j = n - 1; ; ) {
                while (j > i && (b >>> j & 1) == 1) j--;
                while (j > i && (b >>> i & 1) == 0) i++;
                if (j <= i) break;
                b ^= (1 << i) | (1 << j);
                sw.add(new int[]{i, j});
            }
            List<Integer> ans = new ArrayList<>();
            Set<Integer> used = new HashSet<>();
            ans.add(b);
            used.add(b);
            for (int i = 0; i < n; i++) {
                b |= 1 << i;
                if (used.add(b)) {
                    ans.add(b);
                }
            }
            List<Integer> ans2 = new ArrayList<>();
            ans2.add(0);
            used.add(0);
            LOOP:
            for (int i = 0; ; ) {
                for (int j = 0; j < n; j++) {
                    final int k = i ^ 1 << j;
                    if (Integer.bitCount(i) < Integer.bitCount(k)) {
                        continue;
                    }
                    if (used.add(k)) {
                        i = k;
                        ans2.add(k);
                        continue LOOP;
                    }
                }
                for (int j = 0; j < n; j++) {
                    final int k = i ^ 1 << j;
                    if (Integer.bitCount(i) > Integer.bitCount(k)) {
                        continue;
                    }
                    if (used.add(k)) {
                        i = k;
                        ans2.add(k);
                        continue LOOP;
                    }
                }
                break;
            }
            Collections.reverse(ans);
            ans2.addAll(ans);
            ans2 = flip(ans2, a);
            for (int i = 0; i < ans2.size(); i++) {
                for (int[] s : sw) {
                    int v = ans2.get(i);
                    int v1 = v >>> s[0] & 1;
                    int v2 = v >>> s[1] & 1;
                    v &= ~(1 << s[0]);
                    v &= ~(1 << s[1]);
                    ans2.set(i, v | (v1 << s[1]) | (v2 << s[0]));
                }
            }
            return ans2;
        }

        List<Integer> flip(List<Integer> ans, int v) {
            for (int i = 0; i < ans.size(); i++) {
                ans.set(i, ans.get(i) ^ v);
            }
            return ans;
        }

        static void printList(PrintWriter out, List<?> p) {
            for (int i = 0; i < p.size(); i++) {
                out.print(p.get(i) + (i == p.size() - 1 ? "\n" : " "));
