import java.util.InputMismatchException;

public class Main {
	InputStream is;
	PrintWriter out;
	String INPUT = "";

	void solve() {
		solve(ni(), ni(), ni());
	}

	StringBuffer sb = new StringBuffer();

	void solve(int n, int A, int B) {
		if (Integer.bitCount(A ^ B) % 2 == 0) {
			System.out.println("NO");
			return;
		}

		sb.append("YES").append("\r\n");
		go(A, B, (1 << n) - 1);
		System.out.println(sb);
	}

	private void go(int a, int b, int f) {
		if (a == b) {
			sb.append(a).append(" ");
			return;
		}
		int d = a ^ b;
		int l = d & -d;
		f ^= l;
		int n = f & -f;
//		Helper.tr(a, b, f, l, n);
		go(a, a ^ n, f);
		go(a ^ n ^ l, b, f);
	}

	void run() throws Exception {
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);
		Thread t = new Thread(null, null, "~", Runtime.getRuntime().maxMemory()) {
			@Override
			public void run() {
				long s = System.currentTimeMillis();
				solve();
				out.flush();
				if (!INPUT.isEmpty())
					tr(System.currentTimeMillis() - s + "ms");
			}
		};
		t.start();
		t.join();

		// long s = System.currentTimeMillis();
		// solve();
		// out.flush();
		// if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
	}

	public static void main(String[] args) throws Exception {
		new Main().run();
	}

	private byte[] inbuf = new byte[1024];
	public int lenbuf = 0, ptrbuf = 0;

	private int readByte() {
		if (lenbuf == -1)
			throw new InputMismatchException();
		if (ptrbuf >= lenbuf) {
			ptrbuf = 0;
			try {
				lenbuf = is.read(inbuf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (lenbuf <= 0)
				return -1;
		}
		return inbuf[ptrbuf++];
	}

	private boolean isSpaceChar(int c) {
		return !(c >= 33 && c <= 126);
	}

	private int skip() {
		int b;
		while ((b = readByte()) != -1 && isSpaceChar(b))
			;
		return b;
	}

	private double nd() {
		return Double.parseDouble(ns());
	}

	private char nc() {
		return (char) skip();
	}

	private String ns() {
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != ' ')
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private char[] ns(int n) {
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while (p < n && !(isSpaceChar(b))) {
			buf[p++] = (char) b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private char[][] nm(int n, int m) {
		char[][] map = new char[n][];
		for (int i = 0; i < n; i++)
			map[i] = ns(m);
		return map;
	}

	private int[] na(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = ni();
		return a;
	}

	private int ni() {
		int num = 0, b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private long nl() {
		long num = 0;
		int b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args){

        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int a = sc.nextInt();
        int b = sc.nextInt();
        int m = (1<<n);
        int diff = 0;
        int pos = 0;
        for(int i=0; i<n; i++) {
            if((a>>i)%2 != (b>>i)%2) {
                diff++;
                pos = i;
            }
        }
        int maxbit = 1<<(n-1);
        int posbit = 1<<pos;
        StringBuilder sb = new StringBuilder();
        if(diff == 1) {
            sb.append("YES\n");
            for(int i=0; i<m; i++) {
                if(i>0) {
                    sb.append(" ");
                }
                int base = i ^ (i>>1);
                int max = (base & maxbit) != 0 ? 1 : 0;
                int p = (base & posbit) != 0 ? 1 : 0;
                if(max == 1 && p == 0) {
                    base -= maxbit;
                    base += posbit;
                }
                if(max == 0 && p == 1) {
                    base -= posbit;
                    base += maxbit;
                }
                sb.append(base ^ a);
            }
            System.out.println(sb.toString());
        } else {
            System.out.println("NO");
        }

    }


