/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Egor Kulikov (egor@egork.net)
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        CDifferBy1Bit solver = new CDifferBy1Bit();
        solver.solve(1, in, out);
        out.close();
    }

    static class CDifferBy1Bit {
        int[] answer;
        int at;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int a = in.readInt();
            int b = in.readInt();
            if (Integer.bitCount(a) % 2 == Integer.bitCount(b) % 2) {
                out.printLine("NO");
                return;
            }
            out.printLine("YES");
            answer = new int[1 << n];
            answer[0] = a;
            at = 1;
            int dif = a ^ b;
            int same = (1 << n) - 1 - dif;
            while (Integer.bitCount(dif) > 1) {
                int one = Integer.lowestOneBit(dif);
                int other = Integer.highestOneBit(dif);
                doCode(dif + same - one, other);
                answer[at] = answer[at - 1] ^ one;
                at++;
                dif -= one + other;
                same += other;
            }
            doCode(same + dif, dif);
            out.printLine(answer);
        }

        private void doCode(int onBits, int last) {
            if (onBits == 0) {
                return;
            }
            int start = at - 1;
            doCode(onBits - last, Integer.lowestOneBit(onBits - last));
            for (int i = at - 1; i >= start; i--) {
                answer[at++] = answer[i] ^ last;
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void print(int[] array) {
            for (int i = 0; i < array.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(array[i]);
            }
        }

        public void printLine(int[] array) {
            print(array);
            writer.println();
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }
}

import java.util.Scanner;


public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int a = sc.nextInt();
		int b = sc.nextInt();





		int[] ans = construct(n,a,b);
		if (ans == null) {
			System.out.println("NO");

		} else {
			System.out.println("YES");
			for (int i=0;i<ans.length;i++) {
				System.out.print(ans[i]);
				if (i<ans.length-1) {
					System.out.print(" ");
				} else {
					System.out.println("");
				}
			}
		}



	}
	static int[] construct(int n, int a, int b) {
		int diff = a^b;
		int size = 1<<n;
		/*
		ArrayList<Integer> arl = new ArrayList<>();
		for (int i=0;i<n;i++) {
			if ((diff>>i)%2!=0) {
				arl.add(i);
			}
		}*/
		int first = Integer.highestOneBit(diff);
		if (first == 0) {
			return null;
		}
		int second = Integer.highestOneBit(diff^first);
		if (second == 0) {
			// gray code

			int[] gray = new int[size];
			for (int i=0;i<size;i++) {
				gray[i]=a^i^(i>>1);

				// swap digits
				int tmp = gray[i] & diff;
				int tmp2 = gray[i] & (1<<(n-1));

				gray[i]=gray[i]^tmp^tmp2
						^((tmp/diff)<<(n-1))
						^((tmp2>>(n-1))*diff);

			}

			return gray;

		} else {
			int[] tmp1 = construct (n-1,a,b^first^second);
			int[] tmp2 = construct (n-1,b^first,b);
			if (tmp1 == null || tmp2 == null) {
				return null;
			}

			int[] ans = new int[size];
			System.arraycopy(tmp1, 0, ans, 0, size/2);
			System.arraycopy(tmp2, 0, ans, size/2, size/2);
			return ans;
		}
	}


}

