        Scanner sc = new Scanner(in);

        int n = sc.nextInt();
		long a = sc.nextInt();
		long b = sc.nextInt();

		int ac=0, bc=0;
		for(long i=a; i>0; i>>=1) if((i&1) > 0) ac++;
	    for(long i=b; i>0; i>>=1) if((i&1) > 0) bc++;
		//out.println(ac + " " + bc);


		int[] num = new int[n+1];
		Arrays.fill(num, 0);
		num[0] = 1;
		for(int i=0; i<n; i++) 
			for(int j=i; j>=0; j--) num[j+1] += num[j];
        //for(int i=0; i<=n; i++) out.print(num[i] + " ");
		//out.println();

		for(int i=Math.min(ac,bc); i<=Math.max(bc,ac); i++) 
			num[i]--;

		for(int i=0; i<n; i++) num[i+1] -= num[i];


		if(num[n] != 0) out.println("NO");
		else {
			out.println("YES");
			search(n, a, b, 0);
		}
    }

	static void search(int n, long a, long b, long m) {
		//out.println(a + " " + b + " " + m);
		if((m|(m+1)) == (1<<n)-1) {
			out.println(a);
			out.println(b);
			return;
		}

	    for(long i=1; i<(1<<n); i<<=1) {
			if((m&i) ==0 && ((a&i) ^ (b&i)) != 0) {
				m |= i;
				search(n, a, a^((m|m+1)-m), m);
				search(n, (a^((m|m+1)-m))^i, b, m);
				break;
			}
		}
	}

}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {

	static BufferedReader reader;

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		reader = new BufferedReader(new InputStreamReader(System.in));
		String[] s = readLine().split(" ");
		int N = Integer.parseInt(s[0]);
		int A = Integer.parseInt(s[1]);
		int B = Integer.parseInt(s[2]);
		boolean[] A_b = new boolean[N];
		boolean[] B_b = new boolean[N];
		int diff_cnt = 0;
		for(int i=0;i<N;i++){
			A_b[i] = ((A&bit(N-i-1))!=0);
			B_b[i] = ((B&bit(N-i-1))!=0);
			if(A_b[i]!=B_b[i]){diff_cnt++;}
		}
		if(diff_cnt%2==0){print("NO");}
		else{
			print("YES");
			for(int k=0;k<bit(N)-1;k++){
				long out = 0;
				for(int i=0;i<N;i++){
					out=out*2+(A_b[i]?1:0);
				}
				print_success(out+" ");
				int change_pointer = A_b.length-1;
				boolean changed = false;
				for(int i=change_pointer-1;i>=0;i--){
					if(A_b[i]!=B_b[i]){
						A_b[i]=B_b[i];
						changed = true;
						change_pointer = i;
						break;
					}
				}
				if(!changed){
					A_b[A_b.length-1]=!A_b[A_b.length-1];
				}
			}
			long out = 0;
			for(int i=0;i<N;i++){
				out=out*2+(A_b[i]?1:0);
			}
			print(out);
		}
	}

	private static long bit(long d){
		if(d<=0){return 1;}
		return bit(d-1)*2;
	}

	private static String readLine(){
		try{
			return reader.readLine();
		}catch(Exception e){
			return e.getMessage();
		}
	}
	private static void print(Object o){
		System.out.println(o);
	}
	private static void print(){
		System.out.println();
	}
	private static void print_success(Object o){
		System.out.print(o);
	}

}

