import java.util.InputMismatchException;
import java.io.IOException;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author cunbidun
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CDifferBy1Bit solver = new CDifferBy1Bit();
        solver.solve(1, in, out);
        out.close();
    }

    static class CDifferBy1Bit {
        private ArrayList<Integer>[] adj = new ArrayList[131075];
        private boolean[] visited = new boolean[131075];
        private int[] p = new int[131075];
        int a;
        int b;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            a = in.nextInt();
            b = in.nextInt();
            for (int i = 0; i < 131073; i++) {
                p[i] = -1;
                adj[i] = new ArrayList<>();
            }
            for (int i = 0; i <= ((1 << n) - 1); i++) {
                for (int j = 0; j < n; j++) {
                    adj[i].add(i ^ (1 << j));
                }
            }
            visited[a] = visited[b] = true;
            dfs(a);
            int pos = -1;
            for (int i : adj[b]) {
                if (p[i] != -1) {
                    pos = i;
                }
            }
            if (pos == -1) {
                out.println("NO");
                return;
            }
            ArrayList<Integer> num = new ArrayList<>();
            while (pos != a) {
                num.add(pos);
                pos = p[pos];
            }

            if (num.size() != (((1 << n) - 1) - 1)) {
                out.println("NO");
                return;
            }
            out.println("YES");
            out.print(a + " ");
            for (int i = num.size() - 1; i >= 0; i--) {
                out.print(num.get(i) + " ");
            }
            out.println(b);
        }

        private void dfs(int u) {
            visited[u] = true;
            for (int v : adj[u]) {
                if (!visited[v]) {
                    p[v] = u;
                    dfs(v);
                }
            }
        }

    }

    static class InputReader extends InputStream {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

import java.io.BufferedReader;
