    void reverse(int[] ar, int l, int r) {
        int c = (l + r) / 2 - l;
        for (int i = 0; i < c; i++) {
            int tmp = ar[l + i];
            ar[l + i] = ar[r - i];
            ar[r - i] = tmp;
        }
    }

    void solve(int A, int B, int mask) {
//        debug(Integer.toBinaryString(A), Integer.toBinaryString(B), mask);

        if (Integer.bitCount(mask) == 1) {
            ans.add(A);
            ans.add(B);
            return;
        }

        int div = -1;
        for (int i = 0; i < n; i++) if ((((A ^ B) & mask) & (1 << i)) > 0) {
            div = i;
        }
        mask ^= 1 << div;

        int c = -1;
        for (int i = 0; i < n; i++) if (((~(A ^ B) & mask) & (1 << i)) > 0) {
            c = i;
        }
        int C = A ^ (1 << c);
        solve(A, C, mask);
        solve(C^ (1 << div), B, mask);
    }

    void debug(Object...os) {
        System.err.println(Arrays.deepToString(os));
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

import java.util.ArrayList;
import java.util.Scanner;


public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int a = sc.nextInt();
		int b = sc.nextInt();

		ArrayList<Integer> diffList = new ArrayList<>();
		ArrayList<Integer> sameList = new ArrayList<>();

		int diff = a^b;

		for (int i=0;i<n;i++) {
			if ((diff&(1<<i)) > 0) {
				diffList.add(i);
			} else {
				sameList.add(i);
			}
		}
		if (diffList.size()%2==0) {
			System.out.println("NO");
		} else {


			int[] ans = construct(n,diffList.size());

			//digit swap
			System.out.println("YES");
			for (int i=0;i<ans.length;i++) {
				int tmp = 0;
				for (int j=0;j<diffList.size();j++) {
					//上からj桁目を下からget(j)桁目に
					tmp += ((ans[i]>>(n-j-1))%2)<<diffList.get(j);
				}
				for (int j=0;j<sameList.size();j++) {
					tmp += ((ans[i]>>j)%2)<<sameList.get(j);
				}

				System.out.print(tmp^a);
				if (i<ans.length-1) {
					System.out.print(" ");
				} else {
					System.out.println("");
				}
			}
		}



	}
	static int[] construct(int n, int a) {

		int size = 1<<n;

		if (a == 1) {
			// gray code

			int[] gray = new int[size];
			for (int i=0;i<size;i++) {
				gray[i]=i^(i>>1);

			}

			return gray;

		} else {
			int[] tmp = construct (n-1,a-2);



			int[] ans = new int[size];
			System.arraycopy(tmp, 0, ans, 0 ,size/2);
			for (int i=size/2;i<size;i++) {
				ans[i]=tmp[i-size/2]/2+(size/2)+(1-tmp[i-size/2])*size/4;
			}
			return ans;
		}
	}


}

import java.io.*;
import java.util.*;

public class Main {
  private static int dropBit(int n, int index) {
    int higher = (n >> (index + 1)) << index;
    int lower = (n & (1 - (1 << index)));
    return higher | lower;
  }

  private static int insertBit(int n, int index, int v) {
    int higher = ((n >> index) << (index + 1));
    int lower = (n & (1 - (1 << index)));
    return higher | lower | v;
  }

  private static List<Integer> solveSub(int n, int a, int b) {
    if (n == 1) {
      if (a != b) {
        return Arrays.asList(a, b);
      } else {
        return null;
      }
    }

    for (int i = 0; i < n; i++) {
      int aBit = (a >> i) & 1;
      int bBit = (b >> i) & 1;
      if (aBit != bBit) {
        int aDash = dropBit(a, i);
        int bDash = dropBit(b, i);
        int c = aDash ^ 1;
        List<Integer> path1 = solveSub(n - 1, aDash, c);
        List<Integer> path2 = solveSub(n - 1, c, bDash);
        if (path1 != null && path2 != null) {
          List<Integer> path = new ArrayList<>();
          for (int v : path1) {
            path.add(insertBit(v, i, aBit << i));
          }
          for (int v : path2) {
            path.add(insertBit(v, i, bBit << i));
          }
          return path;
        }
        return null;
      }
    }
    return null;
  }

  private static List<String> solve(int n, int a, int b) {
    List<Integer> path = solveSub(n, a, b);
    if (path == null) {
      return Arrays.asList("NO");
    }
    StringBuffer sb = new StringBuffer();
    sb.append(path.get(0));
    for (int i = 1; i < path.size(); i++) {
      sb.append(" ");
      sb.append(path.get(i));
    }
    return Arrays.asList("YES", sb.toString());
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int a = reader.nextInt();
    int b = reader.nextInt();
    for (String line : new Solver(n, a, b).solve()) {
      out.println(line);
    }
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

