import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    private static int[] path;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int a = sc.nextInt();
        int b = sc.nextInt();
        path = new int[1 << n];
        if (Integer.bitCount(a ^ b) % 2 != 0) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
            return;
        }
        path(a, b, 0, (1 << n) - 1);
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < path.length; i++) {
            pw.print(path[i] + " ");
        }
        pw.println();
        pw.flush();
    }

    private static void path(int a, int b, int st, int mask) {
        int diffBit = Integer.highestOneBit(mask & (a ^ b));
        mask = mask ^ diffBit;
        int size = Integer.bitCount(mask);
        if (size == 0) {
            path[st] = a;
            path[st + 1] = b;
        } else {
            int otherBit = Integer.highestOneBit(mask);
            path(a, a ^ otherBit, st, mask);
            path(a ^ diffBit ^ otherBit, b, st + (1 << size), mask);
        }
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		C_DifferByOneBit solver = new C_DifferByOneBit();
		solver.solve(1, in, out);
		out.close();
	}

	static class C_DifferByOneBit {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int a = in.nextInt();
			int b = in.nextInt();
			int[] path = build(n, a, b);
			if (path == null) {
				out.println("NO");
				return;
			}
			out.println("YES");
			for (int i = 0; i < path.length; i++) {
				if (i > 0) {
					out.print(" ");
				}
				out.print(path[i]);
			}
			out.println();
		}

		private int[] build(int n, int a, int b) {
			int diff = Integer.bitCount(a ^ b);
			if (diff % 2 == 0) {
				return null;
			}
			if (n == 1) {
				return new int[]{a, b};
			}

			int[] differentBitPositions = new int[n];
			int[] differentBitValuesA = new int[n];
			int[] differentBitValuesB = new int[n];
			int numDifferentBits = 0;
			for (int i = 0; i < n; i++) {
				int bitA = (a >> i) & 1;
				int bitB = (b >> i) & 1;
				if (bitA != bitB) {
					differentBitPositions[numDifferentBits] = i;
					differentBitValuesA[numDifferentBits] = bitA;
					differentBitValuesB[numDifferentBits] = bitB;
					++numDifferentBits;
				}
			}

			if (diff == 1) {
				int[] g = gray(n - 1);
				g = insert(n - 1, g, differentBitPositions[0], differentBitValuesA[0]);
				g = rotate(g, a);
				g = remove(n, g, differentBitPositions[0]);
				int[] path = new int[2 * g.length];
				for (int i = 0; i < g.length; i++) {
					path[i] = insert(n - 1, g[i], differentBitPositions[0], differentBitValuesA[0]);
					path[i + g.length] = insert(n - 1, g[g.length - i - 1], differentBitPositions[0], differentBitValuesB[0]);
				}
				return path;
			}

			int a00 = remove(n, a, differentBitPositions[numDifferentBits - 1]);
			int a01 = a00 ^ (1 << differentBitPositions[numDifferentBits - 2]);
			int[] p1 = build(n - 1, a00, a01);
			if (p1 == null) {
				throw new AssertionError();
			}
			p1 = insert(n - 1, p1, differentBitPositions[numDifferentBits - 1], differentBitValuesA[numDifferentBits - 1]);

			int b01 = a01;
			int b11 = remove(n, b, differentBitPositions[numDifferentBits - 1]);

			int[] p2 = build(n - 1, b01, b11);
			if (p2 == null) {
				throw new AssertionError();
			}
			p2 = insert(n - 1, p2, differentBitPositions[numDifferentBits - 1], differentBitValuesB[numDifferentBits - 1]);

			int[] p3 = Arrays.copyOf(p1, 2 * p1.length);
			System.arraycopy(p2, 0, p3, p1.length, p1.length);
			return p3;
		}

		private int[] insert(int n, int[] g, int pos, int val) {
			int[] ng = new int[g.length];
			for (int i = 0; i < g.length; i++) {
				ng[i] = insert(n, g[i], pos, val);
			}
			return ng;
		}

		private int[] remove(int n, int[] g, int pos) {
			int[] ng = new int[g.length];
			for (int i = 0; i < g.length; i++) {
				ng[i] = remove(n, g[i], pos);
			}
			return ng;
		}

		private int insert(int n, int x, int pos, int val) {
			int full = (1 << n) - 1;
			int low = (1 << pos) - 1;
			int high = full ^ low;
			int valLow = x & low;
			int valHigh = (x & high) >> pos;
			return (valHigh << (pos + 1)) | (val << pos) | valLow;
		}

		private int remove(int n, int x, int pos) {
			int full = (1 << n) - 1;
			int low = (1 << pos) - 1;
			int high = full ^ low;
			int valLow = x & low;
			int valHigh = (x & high) >> pos;
			return ((valHigh >> 1) << pos) | valLow;
		}

		private int[] rotate(int[] g, int first) {
			int s = -1;
			for (int i = 0; i < g.length; i++) {
				if (g[i] == first) {
					s = i;
					break;
				}
			}
			if (s < 0) {
				throw new AssertionError();
			}
			int[] ng = new int[g.length];
			for (int i = 0; i < g.length; i++) {
				ng[i] = g[(i + s) % g.length];
			}
			return ng;
		}

		private int[] gray(int n) {
			int[] g = new int[1 << n];
			for (int i = 0; i < g.length; i++) {
				g[i] = i ^ (i >> 1);
//			String s = Integer.toBinaryString(g[i]);
//			while (s.length() < n) {
//				s = "0" + s;
//			}
//			System.out.println(s);
			}
			return g;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.List;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		List<int[]> one =new ArrayList<>();
		List<int[]> max = new ArrayList<>();
		{
			int[] a = {0};
			one.add(null);
			one.add(a);
			for(int i = 1;i < 18;i++){
				int[] b = con(con(a, new int[]{i}), a);
				one.add(b);
				a = b;
			}

			a = new int[]{0};
			max.add(null);
			max.add(a);
			for(int i = 2;i <= 17;i++){
				if(i % 2 == 0){
					int[] b = con(con(con(new int[]{i-1}, rev(one.get(i-1), i-1)), new int[]{i-1}), rem(a, 1));
					max.add(b);
					a = b;
				}else{
					int[] q = con(con(a, new int[]{i-1}), one.get(i-1));
					q = rot(q, i-q[0], i);
					max.add(q);
					a = q;
				}
			}
		}

		int n = ni(), a = ni(), b = ni();
		int c = Integer.bitCount(a^b);
		if(c % 2 == 0){
			out.println("NO");
		}else{
			int[] A = max.get(c);
			for(int i = c+1;i <= n;i++){
				int[] B = con(con(con(new int[]{i-1}, rot(rev(one.get(i-1), i-1), A[0], i-1)), new int[]{i-1}), rem(A, 1));

//				int u = 0;
//				for(int v : B){
//					u ^= 1<<v;
//				}
//				tr(u);
//				tr(A);
//				tr(B);
				A = B;
			}
			int[] map = new int[n];
			int p = 0, q = c;
			for(int i = 0;i < n;i++){
				if((a^b)<<~i<0){
					map[p++] = i;
				}else{
					map[q++] = i;
				}
			}
			out.println("YES");
			out.print(a);
			for(int i = 0;i < A.length;i++){
				a ^=1<<map[A[i]];
				out.print(" " + a);
			}
			out.println();
		}

		// 0 1 3 2
		// 0 2 3 1
		// 0 2 3 1 5 4 6 7
	}

	static int[] rem(int[] a, int f)
	{
		return Arrays.copyOfRange(a, f, a.length);
	}

	static int[] rev(int[] a, int d)
	{
		a = Arrays.copyOf(a, a.length);
		for(int i = 0;i < a.length;i++){
			a[i] = d-1-a[i];
		}
		return a;
	}

	static int[] rot(int[] a, int k, int d)
	{
		a = Arrays.copyOf(a, a.length);
		for(int i = 0;i < a.length;i++){
			a[i] = (a[i]+k)%d;
		}
		return a;
	}

	static int[] con(int[] a, int[] b)
	{
		int[] c = Arrays.copyOf(a, a.length+b.length);
		for(int i = 0;i < b.length;i++)c[i+a.length] = b[i];
		return c;
	}

	public static int[] rev_(int[] a)
	{
		for(int i = 0, j = a.length-1;i < j;i++,j--){
			int c = a[i]; a[i] = a[j]; a[j] = c;
		}
		return a;
	}


	static int[] copy(int[] a)
	{
		return Arrays.copyOf(a, a.length);
	}

	static int[] xor(int[] a, int v)
	{
		for(int i = 0;i < a.length;i++)a[i] ^= v;
		return a;
	}

	static int D = 5;

	static boolean dfs(int a, int b, int ptn)
	{
		if(ptn<<~a<0)return false;
		ptn |= 1<<a;
		if(a == b){
			return ptn+1 == 1<<(1<<D);
		}
		for(int i = 0;i < D;i++){
			if(dfs(a^1<<i, b, ptn))return true;
		}
		return false;
	}

	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
