        int zeroIndex = -1;
        int oneIndex = -1;
        int[] SubstituteTable = new int[nab[0]];
        for (int i = 0; i < nab[0]; i++)
        {
            if (((diffBit >> i) & 1) == 1)
            {
                do
                {
                    oneIndex++;
                } while (((last >> oneIndex) & 1) != 1);
                SubstituteTable[oneIndex] = i;
            }
            else
            {
                do
                {
                    zeroIndex++;
                } while (((last >> zeroIndex) & 1) != 0);
                SubstituteTable[zeroIndex] = i;
            }
        }

        Console.WriteLine(string.Join(" ", res.Select(x => Substitution(nab[0], x, SubstituteTable) ^ nab[1])));
    }

