namespace Program
{
    public static class AGC031C
    {
        static public void Solve()
        {
            var N = NN;
            var A = NN;
            var B = NN;
            var grayList = new List<long>();
            grayList.Add(0);
            grayList.Add(1);
            var mask = 1L;
            for (var i = 1; i < N; i++)
            {
                var cnt = grayList.Count;
                mask <<= 1;
                for (var j = 1; j <= cnt; j++)
                {
                    grayList.Add(mask | grayList[cnt - j]);
                }
            }
            var aIdx = grayList.FindIndex(e => e == A);
            var bIdx = grayList.FindIndex(e => e == B);
            if (aIdx > bIdx)
            {
                grayList.Reverse();
                aIdx = grayList.FindIndex(e => e == A);
                bIdx = grayList.FindIndex(e => e == B);
            }
            if (bIdx - aIdx == 1 || (aIdx == 0 && bIdx == grayList.Count - 1))
            {
                Console.WriteLine("YES");
                if (aIdx == 0 && bIdx == grayList.Count - 1)
                {
                    Console.WriteLine(string.Join(" ", grayList));
                }
                else
                {
                    var res = new List<long>();
                    for (var i = aIdx; i >= 0; i--)
                    {
                        res.Add(grayList[i]);
                    }
                    for (var i = grayList.Count - 1; i >= bIdx; i--)
                    {
                        res.Add(grayList[i]);
                    }
                    Console.WriteLine(string.Join(" ", res));
                }
                return;
            }
            var midPoint2 = grayList.Count / 2;
            var midPoint1 = midPoint2 - 1;
            if (bIdx <= midPoint1 || midPoint2 <= aIdx)
            {
                if (midPoint2 <= aIdx)
                {
                    grayList.Reverse();
                    var t1 = grayList.Take(midPoint2);
                    var t2 = grayList.Skip(midPoint2);
                    grayList = t1.Reverse().Concat(t2.Reverse()).ToList();
                    aIdx = grayList.FindIndex(e => e == A);
                    bIdx = grayList.FindIndex(e => e == B);
                }
                if ((bIdx - aIdx) % 2 == 0)
                {
                    Console.WriteLine("NO");
                    return;
                }
                Console.WriteLine("YES");
                var res = new List<long>();
                for (var i = aIdx; i >= 0; i--)
                {
                    res.Add(grayList[i]);
                }
                for (var i = grayList.Count - 1; i >= grayList.Count - aIdx - 1; i--)
                {
                    res.Add(grayList[i]);
                }
                var point = grayList.Count - aIdx - 2;
                while (point > grayList.Count - bIdx - 1)
                {
                    res.Add(grayList[point]);
