        {
            int[] nab = ReadInts();
            int n = nab[0];
            int a = nab[1];
            int b = nab[2];
            int delta = 0;
            int div = 1;
            for(int i = 0; i < n; i++)
            {
                if ((a & div) != (b & div)) delta++;
                div *= 2;
            }
            if (delta % 2 ==0)
            {
                WriteLine("NO");
                return;
            }
            WriteLine("YES");
            var dict = new Dictionary<int, bool>();
            dict.Add(a,true);
            dict.Add(b,true);
            int all = 1 << n;
            int val = a;
            int[] res = new int[1 << n];
            res[0] = Min(a, b);
            res[(1 << n) - 1] = Max(a, b);
            bool down = true;
            for(int i = 1; i < all-1; i++)
            {
                int k = 1;
                for (int j = 0; j < n; j++)
                {
                    if (down || val > res[1 << n - 1])
                    {
                        if ((val & k) == 1 && !dict.ContainsKey(val - k))
                        {
                            val -= k;
                            break;
                        }
                    }
                    else
                    {
                        if ((val & k) == 0 && !dict.ContainsKey(val + k))
                        {
                            val += k;
                            break;
                        }
                    }
                    k *= 2;
                }
                res[i] = val;
                dict.Add(val, true);
                if (val == 0) down = false;
            }
            if (b < a) Array.Reverse(res);
            for(int i = 0; i < 1 << n; i++)
