					for(int t=0;t<4;t++){
						dp[nt][j * 4 + t] = (dp[now][j] << 2) + a[t];
					}
				} else if(j == dp[now].Length - 1){
					for(int t=0;t<4;t++){
						dp[nt][j * 4 + t] = (dp[now][j] << 2) + aa[t];
					}
				} else {
					for(int t=0;t<4;t++){
						dp[nt][j * 4 + t] = (dp[now][j] << 2) + ax[t];
					}
				}
			}
			now = nt;
