abstract class BaseIterator
{
    public abstract void Next();
    public abstract int GetCode();
}

class CodeIterator : BaseIterator
{
    int Total = 0;
    int Count = 0;
    bool DoLastReverse = false;
    int Order = 1;
    int State = 0;//00 → 01 → 11 → 10
    BaseIterator NextIter;


    public CodeIterator(int total, bool doLastReverse, BaseIterator nextIter)
    {
        Total = total;
        DoLastReverse = doLastReverse;
        NextIter = nextIter;
    }
    public override void Next()
    {
        if (Count % 4 == 3) NextIter.Next();
        else if (Total - Count <= 4 && DoLastReverse)
        {
            switch (State)
            {
                case 0b00:
                    State = 0b10;
                    break;
                case 0b01:
                    State = 0b00;
                    break;
                case 0b10:
                    State = 0b11;
                    break;
                case 0b11:
                    State = 0b01;
                    break;
            }
        }
        else
        {
            switch (State)
            {
                case 0b00:
                    State = 0b01;
                    break;
                case 0b01:
                    State = 0b11;
                    break;
                case 0b10:
                    State = 0b00;
                    break;
                case 0b11:
                    State = 0b10;
                    break;
            }
        }
        Count++;
    }
    public override int GetCode()
    {
        return (NextIter.GetCode() << 2) + State;
    }
}

class SingleIterator : BaseIterator
{
    int state = 0;
    public override void Next()
    {
        state ^= 1;
    }
    public override int GetCode()
    {
        return state;
    }
}

class NothingIterator : BaseIterator
{
    public override void Next(){}
    public override int GetCode()
    {
        return 0;
    }
}

