class Program
{
	static void Main(string[] args)
	{
		string[] str = Console.ReadLine().Split();
		int N = int.Parse(str[0]);
		int A = int.Parse(str[1]);
		int B = int.Parse(str[2]);
		int c = 1;
		int ct0 = 0;
		int ct1 = 0;
		int ct1i = -1;
		int[] LNa = new int[N];
		int[] LNb = new int[N];
		int[] D = new int[N];
		int[] ctL = new int[N];
		for(var i=0;i<N;i++){
			D[i] = c;
			int a1 = (A/c)%2;
			int b1 = (B/c)%2;
			LNa[i] = a1;
			LNb[i] = b1;
			if(Math.Abs(a1-b1)%2==1){
				ct1++;
				ctL[i]=1;
				ct1i = i;
			} else {
				ct0++;
			}
			c *= 2;
		}
		if(ct1%2==0){
			Console.WriteLine("NO");
		} else {
			Console.WriteLine("YES");
			List<int> ans = Ar(N,A,B);
			Console.Write(ans[0]);
			for(var i=1;i<ans.Count;i++){
				Console.Write(" "+ans[i]);
			}
		}
	}
	static List<int> Ar(int n,int a,int b){
		int L = (int)Math.Pow(2,n);		
		List<int> A = new List<int>();
		if(n==1){
			A.Add(a);
			A.Add(b);
		} else {
			int c = 1;
			for(var i=0;i<n;i++){
				int a1 = a/c%2;
				int b1 = b/c%2;
				if(a1!=b1){
					int a2 = a%c+a/(c*2)*c;
					int b2 = b%c+b/(c*2)*c;
					int a3 = (a2+1)%2;
					A.AddRange(Ar(n-1,a2,a3));
					for(var j=0;j<L/2;j++){
						int a4 = A[j]/c;
						A[j] = a4*2+a1*c+A[j]%c;
					}
					A.AddRange(Ar(n-1,a3,b2));
					for(var j=L/2;j<L;j++){
						int a4 = A[j]/c;
						A[j] = a4*2+b1*c+A[j]%c;
					}
					break;
				} else {
					c *= 2;
				}
			}
		}
		return A;
	}
}

using System.Collections.Generic;
using System.Linq;
using static System.Console;
class K
{
	static void Main()
	{
		var I = ReadLine().Split().Select(int.Parse).ToArray();
		int N = I[0], A = I[1], B = I[2];
		if (C(A ^ B) % 2 < 1) WriteLine("NO");
		else WriteLine("YES\n" + string.Join(" ", G(N, A, B)));
	}
	static IEnumerable<int> G(int N, int A, int B)
	{
		if (N == 1) return new[] { A, B };
		var p = new int[N];
		int o = N - 1, z = 0;
		for (var i = 0; i < N; i++) p[i] = (B & (1 << i)) > 0 ? o-- : z++;
		B = ((1 << (N - z)) - 1) << z;
		var l = new List<int>();
		var M = 1 << (N - 1);
		for (var i = 0; i < M; i++) l.Add(i ^ (i >> 1));
		foreach (var i in G(N - 1, 1 << (N - 2), B ^ M)) l.Add(i ^ M);
		return l.Select(x =>
		{
			var s = A;
			for (var j = 0; j < N; j++) s ^= ((x >> p[j]) & 1) << j;
			return s;
		});
	}
	static int C(int n)
	{
		n = (n & 0x55555555) + ((n >> 1) & 0x55555555);
		n = (n & 858993459) + ((n >> 2) & 858993459);
		n = (n & 252645135) + ((n >> 4) & 252645135);
		n = (n & 16711935) + ((n >> 8) & 16711935);
		return (n & 65535) + ((n >> 16) & 65535);
	}
}

