class Program
{
    static int N;
    static long A;
    static long B;

    static void Main()
    {
        string[] input = Console.ReadLine().Split();
        N = int.Parse(input[0]);
        A = long.Parse(input[1]);
        B = long.Parse(input[2]);


        int d = dis(A, B);
        if (d % 2 == 0)
        {
            Console.WriteLine("NO");
            return;
        }
        Console.WriteLine("YES");
        /* 0,...,AxorBになるものを求める */
        B ^= A;
        List<long> l;
        for (int i = 0; i < N; i++)
        {
            try
            {
                l = Solv(B, N, i);
                foreach (var k in l)
                    Console.Write("{0} ", k ^ A);
                Console.WriteLine("\b");
                return;
            }
            catch { continue; }
        }
        Console.WriteLine("NO");
    }

    static List<long> Solv(long x, int n, int k)
    {
        List<long> ans = new List<long>();
        List<long> r1 = Nums(k);
        List<long> r2 = Nums(n - k);
        int p = -1;
        int q = -1;
        for (int i = 0; i < r1.Count; i++)
        {
            if ((x >> (k)) == r1[i])
            {
                p = i;
                continue;
            }
        }
        for (int i = 0; i < r2.Count; i++)
        {
            if (x % ((long)Pow(2, k)) == r2[i])
            {
                q = i;
                continue;
            }
        }
        int r = n / 2;
        int l = k;
        if (p % 2 == q % 2) throw new Exception();
        if (q % 2 == 1)
        {
            var t = p;
            p = q;
            q = t;
            var t2 = r1;
            r1 = r2;
            r2 = t2;
            t = r;
            r = l;
            l = t;
        }
        for (int i = 0; i < p; i++)
        {
            if (i % 2 == 0)
            {
                for (int j = 0; j < r2.Count; j++)
                {
                    ans.Add((r1[i] << (l)) | r2[j]);
                }
            }
            else
            {
                for (int j = r2.Count - 1; j >= 0; j--)
                {
                    ans.Add((r1[i] << (l)) | r2[j]);
                }
            }
        }
        for (int i = p; i < r1.Count; i++)
        {
            if (i % 2 == 0)
            {
                for (int j = q + 1; j < r2.Count; j++)
                {
                    ans.Add((r1[i] << (l)) | r2[j]);
                }
            }
            else
            {
                for (int j = r2.Count - 1; j > q; j--)
                {
                    ans.Add((r1[i] << (l)) | r2[j]);
                }
            }
        }
        for (int j = q; j >= 0; j--)
            ans.Add((r1[r1.Count - 1] << (l)) | r2[j]);
        for (int j = 0; j <= q; j++)
        {
            if (j % 2 == 0)
            {
                for (int i = r1.Count - 2; i >= p; i--)
                    ans.Add((r1[i] << (l)) | r2[j]);
            }
            else
            {
                for (int i = p; i < r1.Count - 1; i++)
                {
                    ans.Add((r1[i] << (l)) | r2[j]);
                }
            }
        }
        return ans;
    }

    /* a,bのハミング距離を求める */
    static int dis(long a, long b)
    {
        long d = a ^ b;
        int i = 0;
        while (d != 0)
        {
            d &= d - 1;
            i++;
        }
        return i;
    }

    static List<long> Nums(int k)
    {
        List<long> r = new List<long>();
        if (k == 0) return r;
        if (k == 1)
        {
            r.Add(0);
            r.Add(1);
            return r;
        }
        if (k == 2)
        {
            r.Add(0);
            r.Add(1);
            r.Add(3);
            r.Add(2);
            return r;
        }
        int kh = k / 2;
        List<long> r1 = Nums(kh);
        List<long> r2 = Nums(k - kh);
        for (int i = 0; i < r1.Count; i++)
        {
            if (i % 2 == 0)
            {
                for (int j = 0; j < r2.Count; j++)
                {
                    long a = (r1[i] << (k - kh)) | r2[j];
                    r.Add(a);
                }
            }
            else
            {
                for (int j = 1; j <= r2.Count; j++)
                {
                    long a = (r1[i] << (k - kh)) | r2[r2.Count - j];
                    r.Add(a);
                }
            }
        }
        return r;
    }
}

