        int y = 0;
        int ta = a;
        int tb = b;
        for(int i=0; i<n; i++){
            if(ta % 2 == 1) x++;
            if(tb % 2 == 1) y++;
            ta /= 2;
            tb /= 2;
        }
        if(x % 2 == y % 2){
            Console.WriteLine("NO");
            return;
        }
        Console.WriteLine("YES");
        int[] t = new int[n+1];
        t[0] = 1;
        for(int i=1; i<=n; i++){
            t[i] = t[i-1] * 2;
        }

        int[] z = new int[t[n]];
        z[0] = 0;
        z[1] = 1;
        for(int i=1; i<n; i++){
            for(int j=t[i]; j<t[i+1]; j++){
                z[j] = z[t[i+1] - j - 1];
                z[j] += t[i];
            }
        }
        int[] z1 = new int[t[n-1]];
        int[] z2 = new int[t[n-1]];
        for(int i=0; i<t[n]; i++){
            if(a % 2 == 0){
                if(i % 2 == 0) z1[i/2] = z[i];
                if(i % 2 == 1) z2[i/2] = z[i];
            }
            if(a % 2 == 1){
                if(i % 2 == 0) z2[i/2] = z[i];
                if(i % 2 == 1) z1[i/2] = z[i];
            }
        }
        int start = 0;
        while(z1[start] != a) start++;
        int p = start;
        while(true){
            Console.Write(z1[p]+" ");
            if(z2[p] == b) break;
            Console.Write(z2[p]+" ");
            p++;
            if(p>=t[n-1]) p = 0;
        }
        int f = 0;
        while(true){
            if(p + 1 == start || (p + 1 == t[n-1] && start == 0)){
                f = 1;
                break;
            }
            p++;
            if(p>=t[n-1]) p = 0;
            Console.Write(z2[p]+" ");

            if(p + 1 == start || (p + 1 == t[n-1] && start == 0)){
                f = 2;
                break;
            }
            p++;
            if(p>=t[n-1]) p = 0;
            Console.Write(z1[p]+" ");
        }

        if(f == 1){
            p++;
            if(p>=t[n-1]) p = 0;
            while(true){
                p--;
                if(p<0) p = t[n-1] - 1;
                if(z2[p] == b) break;
                Console.Write(z2[p]+" ");
                p--;
                if(p<0) p = t[n-1] - 1;
                Console.Write(z1[p]+" ");
            }
        }
        if(f == 2){
            p++;
            if(p>=t[n-1]) p = 0;
            while(true){
                p--;
                if(p<0) p = t[n-1] - 1;
                Console.Write(z1[p]+" ");
                p--;
                if(p<0) p = t[n-1] - 1;
                if(z2[p] == b) break;
                Console.Write(z2[p]+" ");
            }
        }
        Console.WriteLine(b);
    }

