    class Program
    {
        private const long Mod = 1000000007;
        private int N, A, B;
        private int NN;

        int BitCount(int n)
        {
            n = (n & 0x55555555) + (n >> 1 & 0x55555555);
            n = (n & 0x33333333) + (n >> 2 & 0x33333333);
            n = (n & 0x0f0f0f0f) + (n >> 4 & 0x0f0f0f0f);
            n = (n & 0x00ff00ff) + (n >> 8 & 0x00ff00ff);
            return (n & 0x0000ffff) + (n >> 16 & 0x0000ffff);
        }

        public void Solve()
        {
            var sc = new Scanner();
            N = sc.NextInt();
            A = sc.NextInt();
            B = sc.NextInt();
            NN = 1 << N;
            if (BitCount(A) % 2 == BitCount(B) % 2)
            {
                Console.WriteLine("NO");
                return;
            }
            Console.WriteLine("YES");
            Console.WriteLine(string.Join(" ", S(N, A, B)));
        }

        private int[] S(int n, int a, int b)
        {
            //Console.WriteLine($"{n} {a} {b}");
            if (n == 1)
            {
                return new int[] { a, b };
            }
            int cpA = 0;
            int cpB = a ^ b;
            int diffBit;
            for (diffBit = 0; diffBit < n; diffBit++)
            {
                if ((cpB & (1 << diffBit)) > 0) break;
            }

            int aa = 0;
            int bb = Skip(n, cpB, diffBit);
            var left = S(n - 1, aa, aa ^ 1);
            var right = S(n - 1, aa ^ 1, bb);
            int nn = 1 << n;
            var ans = new int[nn];
            for (int i = 0; i < (nn >> 1); i++)
            {
                ans[i] = Add(n, left[i], diffBit);
                ans[i + (nn >> 1)] = Add(n, right[i], diffBit) | (1 << diffBit);
            }

            for (int i = 0; i < nn; i++)
            {
                ans[i] ^= a;
            }

            return ans;
        }

        /// <summary>
        /// 2進n桁のbit桁目が0の数を作る
        /// </summary>
        /// <param name="n"></param>
        /// <param name="i"></param>
        /// <param name="bit"></param>
        /// <returns></returns>
        private int Add(int n, int i, int bit)
        {
            int res = 0;
            for (int j = 0; j < n; j++)
            {
                int b = 1 << j;
                if (j < bit)
                {
                    res |= i & b;
                }
                else if (j > bit)
                {
                    res |= (i & (b >> 1)) << 1;
                }
            }

            return res;
        }

        /// <summary>
        /// 二進n桁のiのbit桁目を飛ばす
        /// </summary>
        /// <param name="n"></param>
        /// <param name="i"></param>
        /// <param name="bit"></param>
        /// <returns></returns>
        private int Skip(int n, int i, int bit)
        {
            int res = 0;
            for (int j = 0; j < n; j++)
            {
                if (j < bit)
                {
                    res |= i & (1 << j);
                }
                else if (j > bit)
                {
                    res |= (i & (1 << j)) >> 1;
                }
            }

            return res;
        }


        static void Main(string[] args) => new Program().Solve();
    }
