class Solver
{
    Scanner sc = new Scanner();
    //
    int N, A, B;
    public void Solve()
    {
        sc.Make(out N, out A, out B);
        int a = 0, b = 0;
        for(var i=20;i>=0;i--)
        {
            a += 1 & A >> i;
            b += 1 & B >> i;
        }
        if (Abs(a - b) % 2 == 0) Fail("No");
        WriteLine("Yes");
        Console.WriteLine(string.Join(" ", dfs(N,A,B)));
    }
    List<int> dfs(int n, int a, int b)
    {
        if (n == 1) return new List<int> { a, b };
        var rt = new List<int>();
        int sb;
        for (sb = n; sb >= 0; sb--)
            if ((1 & (a ^ b) >> sb) == 1)
                break;
        bs(ref a, sb, n - 1);bs(ref b, sb, n - 1);
        int na = a & (~(1 << (n - 1))), nb = b & (~(1 << (n - 1)));
        foreach (var v in dfs(n - 1, na, na ^ 1))
        {
            var p = v | (a & (1 << (n - 1)));
            bs(ref p, sb, n - 1);
            rt.Add(p);
        }
        foreach (var v in dfs(n - 1, na ^ 1, nb))
        {
            var p = v | (b & (1 << (n - 1)));
            bs(ref p, sb, n - 1);
            rt.Add(p);
        }
        return rt;
    }
    void bs(ref int v,int a,int b)
    {
        int aa = 1 & (v >> a), bb = 1 & (v >> b);
        if (aa > 0) v ^= 1 << a;
        if (bb > 0) v ^= 1 << b;
        v |= bb << a;
        v |= aa << b;
    }
}

