package main
import "fmt"
func main() {
  var n,a,b uint
  fmt.Scan(&n,&a,&b)
  if popcnt(a)%2 == popcnt(b)%2 { fmt.Println("NO");return }
  fmt.Println("YES")
  p := compose(n,a,b)
  fmt.Print(p[0])
  for i:=1;i<len(p);i++ { fmt.Print(" ");fmt.Print(p[i]) }
  fmt.Println()
}
func compose(n,a,b uint) []uint {
  if n == 1 { return []uint{a,b} }
  d := a^b
  var x,y,c,k uint
  for i:=uint(0);i<n;i++ {
    if (d>>i)&1 == 0 { continue }
    l := uint(0)
    for j:=uint(0);j<n;j++ {
      if j == i { l++;continue }
      if (a>>j)&1 == 1 { x |= 1<<(j-l) }
      if (b>>j)&1 == 1 { y |= 1<<(j-l) }
    }
    c = x|1
    if x&1 == 1 { c = x^1 }
    k = i
    break
  }
  q := compose(n-1,x,c)
  r := compose(n-1,c,y)
  m := len(q)
  p0 := make([]uint,m)
  p1 := make([]uint,m)
  for i:=0;i<m;i++ {
    l := uint(0)
    for j:=uint(0);j<n;j++ {
      if j == k {
        if (a>>j)&1 == 1 { p0[i] |= 1<<j }
        if (b>>j)&1 == 1 { p1[i] |= 1<<j }
        l++
        continue
      }
      if (q[i]>>(j-l))&1 == 1 { p0[i] |= 1<<j }
      if (r[i]>>(j-l))&1 == 1 { p1[i] |= 1<<j }
    }
  }
  return append(p0,p1...)
}
func popcnt(n uint) int {
  m := 0
  for i:=uint(0);i<32;i++ {
    if (n>>i)&1 == 1 { m++ }
  }
  return m
}

