int[] solve(int n, int a, int b) {
    if (n == 1) {
        return a ? [1, 0] : [0, 1];
    }

    int dif = -1;
    int bs;

    foreach (i ; 0 .. n) {
        if (gb(a, i) ^ gb(b, i)) {
            dif = i;
            bs = gb(a, i);
            break;
        }
    }

    int ap = removeBit(a, dif);
    int bp = removeBit(b, dif);
    int c = ap ^ 1;
    auto mae = solve(n - 1, ap, c).map!(x => insertBit(x, dif, bs)).array;
    auto ato = solve(n - 1, c, bp).map!(x=> insertBit(x, dif, bs ^ 1)).array;
    return mae ~ ato;
}

int gb(int x, int i) {
    return (x >> i) & 1;
}

// x から i 番目のbitを抜く
int removeBit(int x, int i) {
    // ex. removeBit(10110101, 8, 3) = 01011101
    int u = (x >> (i + 1)) << i; // u = 01011000
    int v = x & ((1 << i) - 1);  // v = 00000101
    return u | v; // u | v = 01011101
}

// x の i 番目に状態bのbitを挿入する
int insertBit(int x, int i, int b) {
    // ex. insertBit(01011101, 3, 1) = 10111101
    int u = (x >> i) << (i + 1); // u = 10110000
    int v = x & ((1 << i) - 1);  // v = 00000101
    return u | v | (b << i);     // u | v | (b << i) = 10111101
}























int[][] readGraph(int n, int m, bool isUndirected = true, bool is1indexed = true) {
    auto adj = new int[][](n, 0);

    foreach (i; 0 .. m) {
        int u, v;
        scan(u, v);
        if (is1indexed) {
            u--, v--;
        }
        adj[u] ~= v;
        if (isUndirected) {
            adj[v] ~= u;
        }
    }

    return adj;
}

alias Edge = Tuple!(int, "to", int, "cost");

Edge[][] readWeightedGraph(int n, int m, bool isUndirected = true, bool is1indexed = true) {
    auto adj = new Edge[][](n, 0);

    foreach (i; 0 .. m) {
        int u, v, c;
        scan(u, v, c);
        if (is1indexed) {
            u--, v--;
        }
        adj[u] ~= Edge(v, c);
        if (isUndirected) {
            adj[v] ~= Edge(u, c);
        }
    }

    return adj;
}

