void main() {
  long N, A, B;
  scanln(N, A, B);
  if (popcnt(A^B)%2 == 0) {
    "NO".writeln;
    return;
  }
  "YES".writeln;

  long[] f(long dim, long a, long b) {
    assert(popcnt(a^b)%2 == 1);
    if (dim == 1) {
      return [a, b];
    } else {
      foreach(i; 0..dim) {
        if ((a>>i&1)^(b>>i&1)) {
          long x = (a>>(i+1)<<i)|(a&((1<<i)-1));
          long y = x ^ (1<<(i==dim-1 ? i-1 : i));
          long[] ps = f(dim - 1, x, y);
          return ps.map!(
            p => (p>>i<<(i+1)) | (a&1<<i) | (p&((1<<i)-1))
          ).array ~ ps.retro.map!(
            p => (p>>i<<(i+1)) | (b&1<<i) | (p&((1<<i)-1))
          ).array;
        }
      }
      assert(false);
    }
  }
  f(N, A, B).map!(to!string).join(" ").writeln;
}

