def numof1(n):
    c = 0
    for i in range(1, 19):
        m = n % 2
        if m == 1:
            c += 1
        n = n // 2
    return c

def distance(n1, n2):
    c = 0
    for i in range(0, 19):
        n1b = n1 & (2 ** i)
        n2b = n2 & (2 ** i)
        if n1b != n2b:
            c += 1
    return c

def next1(n1, n2):
    for i in range(0, 19):
        n1b = n1 & (2 ** i)
        n2b = n2 & (2 ** i)
        if n1b != n2b:
            return n1 ^ (2 ** i)
    return n1 ^ 1

