def grey(n):
    if n <= 0:
        return []

    arr = ['0', '1']

    i, j = 2, 0
    while True:
        if i >= (1 << n):
            break

        for j in range(i - 1, -1, -1):
            arr.append(arr[j])
        for j in range(i):
            arr[j] = "0" + arr[j]
        for j in range(i, 2 * i):
            arr[j] = "1" + arr[j]

        i = i << 1

    return arr


def main():
    n, a, b = map(int, input().split())
    code = [int(i, 2) for i in grey(n)]

    start, mid, end = [], [], []
    flag1, flag2 = False, False
    for i in code:
        if (not flag1) and (not flag2):
            if (i == a) or (i == b):
                flag1 = True
            else:
                start.append(i)
        elif flag1 and (not flag2):
            if (i == a) or (i == b):
                flag2 = True
            else:
                mid.append(i)
        else:
            end.append(i)

    c = []

    c += [[a] + start + mid + end + [b]]
    c += [[a] + start + mid + end[::-1] + [b]]
    c += [[a] + start + mid[::-1] + end + [b]]
    c += [[a] + start[::-1] + mid + end + [b]]
    c += [[a] + start + mid[::-1] + end[::-1] + [b]]
    c += [[a] + start[::-1] + mid + end[::-1] + [b]]
    c += [[a] + start[::-1] + mid[::-1] + end + [b]]
    c += [[a] + start[::-1] + mid[::-1] + end[::-1] + [b]]

    def is_grey(x):
        for i in range(1, len(x)):
            y = x[i] ^ x[i - 1]
            if y & (y - 1) != 0:
                return False
        return True

    for ci in c:
        if is_grey(ci):
            print('YES')
            print(*ci)
            return

