def i_to_b(n, N):
    A = [0] * N
    for i in range(N):
        A[i] = (n // 2**i) % 2
    return A


fact = [1] * 18
for i in range(1, 18):
    fact[i] = fact[i-1] * i


def combination(n, r):
    return fact[n] // fact[r] // fact[n-r]


def main():
    N, A, B = map(int, input().split())
    binA = i_to_b(A, N)
    binB = i_to_b(B, N)
    if abs(sum(binA) - sum(binB)) % 2 == 0:
        print("NO")
        return
    visited = set()
    cnt = [0] * (N+1)
    for i in range(N+1):
        cnt[i] = combination(N, i)
    ans = [-1] * (2**i)
    b = i_to_b((2**N-1)-B, N)
    idx = 2**N - 1
    visited.add(B)
    ans[idx] = B
    cnt[sum(i_to_b(B, N))] -= 1
    for i in range(N):
        if b[i] == 1:
            idx -= 1
            B += 2**i
            visited.add(B)
            ans[idx] = B
            cnt[sum(i_to_b(B, N))] -= 1
    end = idx
    current = A
    idx = 0
    while idx < end:
        visited.add(current)
        ans[idx] = current
        b = i_to_b(current, N)
        c = sum(b)
        cnt[c] -= 1
        idx += 1
        if c >= 1 and cnt[c-1] >= 1:
            for i in range(N):
                if b[i] == 1:
                    nxt = current - 2**i
                    if nxt not in visited:
                        current = nxt
                        break
        else:
