def swap_digit(num:int, i:int, j:int):
    if num & (1<<i) and not (num & (1<<j)):
        return num - (1<<i) + (1<<j)

    elif not (num & (1<<i)) and num & (1<<j):
        return num + (1<<i) - (1<<j)

    else:
        return num


