def doit(aa, bb, mask):
    bits   = filter(lambda b: mask & (1 << b) == 0, range(n))
    differ = filter(lambda b: (aa ^ bb) & (1 << b), bits)[-1]
    change = filter(lambda b: differ != b, bits)
    if not change:
        return [aa, bb]
    ab = aa ^ (1 << change[0])
    ba = ab ^ (1 << differ)
    return doit(aa, ab, mask | (1 << differ)) + doit(ba, bb, mask | (1 << differ))

