# -*- coding: utf-8 -*-
from collections import defaultdict
from itertools import product, cycle, chain

def Gray_code(N):
    for i in range(2**N):
        yield format(i^(i>>1), "0>"+str(N)+"b")

def code(N):
    L0 = ["10", "00", "01", "11"]
    if N == 0:
        return []
    elif N == 2:
        return L0
    else:
        L1 = list(Gray_code(2))
        L2 = code(N-2)
        L = ["".join(l) for L_ in zip([[l] for l in L2], chain([L1,],cycle([L0, L0[::-1]]))) for l in product(*L_)]
        return L

def solve():
    N, A, B = map(int, input().split())
    C = A^B
    d = 0
    D = []
    E = []
    b = 0
    while b < N:
        if C&1:
            d += 1
            D.append(b)
        else:
            E.append(b)
        b += 1
        C >>= 1

    if d % 2 == 0:
        res = "NO"
        return res 
    else:
        X = D[:1]+E
        Y = D[1:]
        Z = list(Gray_code(len(X)))
        W = code(len(Y))
        L = ["".join(l) for L_ in zip([[l] for l in Z], chain([list(Gray_code(len(Y))),],cycle([W, W[::-1]]))) for l in product(*L_)]
        res = " ".join(str(sum(int(b)*2**n for n,b in zip(X+Y, l))) for l in L)

        return str(res)
if __name__ == '__main__':
    print(solve())

