def bitcount(a, N):
  return sum((a & (1 << i)) > 0 for i in range(N))

def bitwhere(a, N):
  return next(i for i in range(N) if (a & (1 << i)) > 0)

def graycode(N):
  a = []
  for i in range(1 << N):
    a.append(i ^ (i >> 1))
  return a

def swap(x, i, j):
  y = x & ~(1 << i) & ~(1 << j)
  if (x & (1 << i)) > 0:
    y |= 1 << j
  if (x & (1 << j)) > 0:
    y |= 1 << i
  return y

def solve():
