import sys

def make_representation(N):
    num_list = [0]
    num = 0
    for n in range(1, 2**N):
        bit = 0
        while True:
            if n & 1 == 1:
                break
            else:
                bit += 1
                n = n >> 1
        num = reverse_bit(num, bit)
        num_list.append(num)
    return num_list

def reverse_bit(num, bit):
    mask = 1 << bit
    return (num & ~mask) + (~num & mask)

def convert4A(A):
    def convert(num):
        return (~num & A) + (num & ~A)
    return convert

def dif_bits(B, BB):
    diffs = []
    bit = 0
    while B > 0 and BB > 0:
        if B & 1 != BB & 1:
            diffs.append(bit)
        bit += 1
        B = B >> 1
        BB = BB >> 1
    return diffs

def swap_bits(num, swap):
    new_num = num
    new_num -= num & (1<<swap[0] + 1<<swap[1])
    new_num += (num & 1<<swap[0]) << abs(swap[1] - swap[0])
    new_num += (num & 1<<swap[1]) >> abs(swap[1] - swap[0])
    return new_num

def convert4B(diffs):
    def convert(num):
        i = 0
        while i+1 < len(diffs):
            swap = [diffs[i], diffs[i+1]]
            num = swap_bits(num, swap)
        return num
    return convert

def search(N, A, B):
    num_list = make_representation(N)
    convA = convert4A(A)
    BB = convA(num_list[-1])

    diffs = dif_bits(B, BB)
    if len(diffs) % 2 != 0:
        print('N0')
        sys.exit(0)
    print('YES')
    convB = convert4B(diffs)
    for num in num_list:
        print(convA(convB(num)))

