import numpy as np

def extract(a, i):
  return (a>>(i+1) << i) | (a&((1<<i)-1))

def space(a, i):
  return ((a>>i) << (i+1)) | (a&((1<<i)-1))

def compose(n, a, b):
  if n==1:
    return [a, b]
  for i in range(n):
    if (a>>i&1) ^ (b>>i&1):
      x = i
      a_bool = (a>>i & 1) << i
      b_bool = a_bool ^ (1 << i)
      a_dash = extract(a, i)
      b_dash = extract(b, i)
      c = a_dash ^ 1
      break
  Q = np.array(compose(n-1, a_dash, c), dtype=np.int64)
  R = np.array(compose(n-1, c, b_dash), dtype=np.int64)
  n_Q = space(Q, x) | a_bool
  n_R = space(R, x) | b_bool
  return n_Q.tolist() + n_R.tolist()

