    ($($xs:expr),*) => { trace!(($($xs),*)) }
}
macro_rules! put {
    ($x:expr) => { println!("{}", $x) };
    ($x:expr, $($xs:expr),*) => { print!("{} ", $x); put!($($xs),*) }
}

fn cut(a: usize, m: usize) -> usize {
    // cut m-th bit
    (a & ((1 << m) - 1)) | ((a >> (m + 1)) << m)
}

fn ins(a: usize, m: usize, b: usize) -> usize {
    // insert b as m-th bit
    ((a >> m) << (m + 1)) |
        (b << m) |
        (a & ((1 << m) - 1))
}

fn difbit(n: usize, a: usize, b: usize) -> Option<(usize, usize, usize)> {
    if a == b { return None }
    for i in 0..n {
        let x = (a & (1 << i)) >> i;
        let y = (b & (1 << i)) >> i;
        if x != y {
            return Some((i, x, y))
        }
    }
    None
}

fn solve(n: usize, a: usize, b: usize) -> Option<Vec<usize>> {

    // trace!("solve", n, a, b);
    if (a ^ b).count_ones() % 2 == 0 {
        None
    } else if a == b {
        None
    } else if n == 1 {
        Some(vec![a, b])
    } else {
        match difbit(n, a, b) {
            None => None,
            Some((i, x, y)) => {
                let a2 = cut(a, i);
                let b2 = cut(b, i);
                let mut c = 0;
                for v in 0..(1 << (n-1)) {
                    if v != a2 && v != b2 {
                        c = v;
                        break;
                    }
                }
                match (solve(n - 1, a2, c), solve(n - 1, c, b2)) {
                    (Some(xs), Some(ys)) => {
                        let mut res = vec![];
                        for &z in xs.iter() {
                            res.push(ins(z, i, x));
                        }
                        for &z in ys.iter() {
                            res.push(ins(z, i, y));
                        }
                        Some(res)
                    },
                    _ => None
                }
            }
        }
    }
}

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
