use kyoproio::*;
use std::{
    collections::*,
    io::{self, prelude::*},
    iter,
    mem::{replace, swap},
};

fn main() -> io::Result<()> {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024)
        .spawn(|| {
            let stdin = io::stdin();
            let stdout = io::stdout();
            run(KInput::new(stdin.lock()), io::BufWriter::new(stdout.lock()))
        })?
        .join()
        .unwrap();
    Ok(())
}

fn run<I: Input, O: Write>(mut kin: I, mut out: O) {
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+).unwrap(); }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush().unwrap(); } }
    }

    let (n, a, b): (i32, i32, i32) = kin.input();
    let c = a ^ b;

    if c.count_ones() % 2 == 0 {
        outputln!("NO");
        return;
    }

    let pat0 = [0, 1, 1, 0];
    let pat1low = [0, 0, 1, 1];
    let pat1high = [1, 0, 0, 1];

    let mut p = vec![0; 1 << n];
    let mut scale = 0;

    // 0
    for d in 0..n {
        if c & 1 << d == 0 {
            for i in 0..1 << n {
                p[i] |= pat0[(i >> scale) % 4] << d;
            }
            scale += 1;
        }
    }

    // 1
    let mut f = false;
    for d in 0..n {
        if c & 1 << d != 0 {
            let r = if scale == n - 1 {
                1 << n
            } else {
                (1 << n) - 4 * if f { 1 << scale - 1 } else { 1 << scale }
            };
            for i in 0..r {
                p[i] |= pat0[(i >> scale) % 4] << d;
            }
            for i in r..1 << n {
                if f {
                    p[i] |= pat1high[(i >> scale - 1) % 4] << d;
                } else {
                    p[i] |= pat1low[(i >> scale) % 4] << d;
                }
            }
            f = !f;
            scale += 1;
        }
    }

    for &x in &p {
        eprintln!("{:08b}", x ^ a);
    }

    outputln!("YES");
    for x in p {
        output!("{} ", x ^ a);
    }
    outputln!();
}

