// 0 -> C (< 2^N) をつくる
fn calc(n: usize, c: usize) -> Vec<usize> {
    assert!(c.count_ones() % 2 == 1);
    if n == 1 {
        return vec![0, 1];
    }
    if (c >> (n - 1)) & 1 == 0 {
        let mut i = n - 1;
        while (c >> i) & 1 == 0 {
            i -= 1;
        }
        let mut ans = calc(n, (c ^ (1 << i)) | (1 << (n - 1)));
        for a in ans.iter_mut() {
            let x = *a >> (n - 1) & 1;
            let y = *a >> i & 1;
            *a &= !(1 << (n - 1)) & !(1 << i);
            *a |= (x << i) | (y << (n - 1));
        }
        return ans;
    }
    let mut f = calc(n - 1, 1 << (n - 2));
    let t = calc(n - 1, c ^ (1 << (n - 1)) ^ (1 << (n - 2)));
    for t in t {
        f.push(t ^ (1 << (n - 2)) ^ (1 << (n - 1)));
    }
    f
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let a: usize = it.next().unwrap().parse().unwrap();
    let b: usize = it.next().unwrap().parse().unwrap();
    let c = a ^ b;
    if c.count_ones() % 2 == 0 {
        println!("NO");
        return;
    }
    let ans = calc(n, c);
    assert!(ans.windows(2).all(|a| (a[0] ^ a[1]).count_ones() == 1));
    let mut out = String::from("YES\n");
    for x in ans {
        out.push_str(&format!("{} ", x ^ a));
    }
    out.pop();
    println!("{}", out);
}

