#![allow(unused_imports)]
#![allow(unused_macros)]
use std::cmp::{ min, max };

macro_rules! ewriteln {
    ($($args:expr),*) => { let _ = writeln!(&mut std::io::stderr(), $($args),*); };
}
macro_rules! trace {
    ($x:expr) => { ewriteln!(">>> {} = {:?}", stringify!($x), $x) };
    ($($xs:expr),*) => { trace!(($($xs),*)) }
}
macro_rules! put {
    ($x:expr) => { println!("{}", $x) };
    ($x:expr, $($xs:expr),*) => { print!("{} ", $x); put!($($xs),*) }
}

fn cut(a: usize, m: usize) -> usize {
    // cut m-th bit
    (a & ((1 << m) - 1)) | ((a >> (m + 1)) << m)
}

fn ins(a: usize, m: usize, b: usize) -> usize {
    // insert b as m-th bit
    ((a >> m) << (m + 1)) |
        (b << m) |
        (a & ((1 << m) - 1))
}

fn difbit(n: usize, a: usize, b: usize) -> Option<(usize, usize, usize)> {
    if a == b { return None }
    for i in 0..n {
        let x = (a & (1 << i)) >> i;
        let y = (b & (1 << i)) >> i;
        if x != y {
            return Some((i, x, y))
        }
    }
    None
}

fn odd(a: usize, b: usize) -> bool {
    (a ^ b).count_ones() % 2 == 1
}

fn subgoal(n: usize, a: usize, b: usize) -> Option<usize> {
    for i in 0..(1<<n) {
        if odd(i, a) && odd(i, b) {
            return Some(i);
        }
    }
    None
}

fn solve(n: usize, a: usize, b: usize) -> Option<Vec<usize>> {

    // trace!("solve", n, a, b);
    if !odd(a, b) {
        None
    } else if a == b {
        None
    } else if n == 1 {
        Some(vec![a, b])
    } else {
        match difbit(n, a, b) {
            None => None,
            Some((i, x, y)) => {
                let a2 = cut(a, i);
                let b2 = cut(b, i);
                match subgoal(n - 1, a2, b2) {
                    None => None,
                    Some(c) => {
                        match (solve(n - 1, a2, c), solve(n - 1, c, b2)) {
                            (Some(xs), Some(ys)) => {
                                let mut res = vec![];
                                for &z in xs.iter() {
                                    res.push(ins(z, i, x));
                                }
                                for &z in ys.iter() {
                                    res.push(ins(z, i, y));
                                }
                                Some(res)
                            },
                            _ => None
                        }
                    }
                }
            }
        }
    }
}

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let a: usize = sc.cin();
    let b: usize = sc.cin();

    let solvable = (a ^ b).count_ones() % 2 == 1;

    match solve(n, a, b) {
        Some(ans) => {
            assert!(solvable);
            put!("YES");
            for i in 0..ans.len() {
                if i < ans.len() - 1 {
                    print!("{} ", ans[i]);
                } else {
                    println!("{}", ans[i]);
                }
            }
        },
        None => {
            assert!(!solvable);
            put!("NO");
        }
    }
}

