fn rec(x: usize, emp: usize) -> Vec<usize> {
    if emp.count_ones() == 1 {
        vec![0, x]
    } else {
        let u = x & !x + 1;
        let next_emp = emp ^ u;
        let b = next_emp & !next_emp + 1;
        rec(b, next_emp)
            .into_iter()
            .chain(rec(x ^ u ^ b, next_emp).into_iter().map(|i| i ^ u ^ b))
            .collect::<Vec<_>>()
    }
}

