fn different_bit(a: u32, b: u32) -> (u32, bool) {
    for i in 0.. {
        if a & (1<<i) != b & (1<<i) {
            return (i, a & (1<<i) != 0);
        }
    }
    panic!();
}

fn remove_bit(x: u32, position: u32) -> u32 {
    let mask = (0..position).fold(1, |acc, _| (acc << 1) | 1);
    x & (mask>>1) | (x & !mask) >> 1
}

fn add_bit(x: u32, position: u32, is_one: bool) -> u32 {
    let mask = match position.checked_sub(1) {
        None => 0,
        Some(p) => (0..p).fold(1, |acc, _| (acc << 1) | 1)
    };
    let b = if is_one { 1 << position } else { 0 };
    x & mask | b | (x & !mask) << 1
}

fn solve(n: usize, a: u32, b: u32) -> Vec<u32> {
    assert!(a.count_ones() % 2 != b.count_ones() % 2);

    if n == 1 {
        vec![a, b]
    } else {
        let (d, is_a_bit_one) = different_bit(a, b);
        let a_sub = remove_bit(a, d);
        let b_sub = remove_bit(b, d);
        let mid = a_sub ^ 1; // differs from b_sub

        let sub1 = solve(n-1, a_sub, mid);
        let sub2 = solve(n-1, mid, b_sub);

        sub1.into_iter().map(|x| add_bit(x, d, is_a_bit_one)).chain(
            sub2.into_iter().map(|x| add_bit(x, d, !is_a_bit_one))
        ).collect()
    }
}

fn main() {
    read!(n = usize, a = u32, b = u32);
    if a.count_ones() % 2 == b.count_ones() % 2 {
        println!("NO");
    } else {
        println!("YES");
        println!("{}", solve(n, a, b).into_iter().join(" "));
    }
}

