fn run() {
    let (n, a, b) = read!(usize, usize, usize);
    if (a ^ b).count_ones() != 1 {
        println!("NO");
        return;
    }

    let mut last = usize::max_value();
    let mut cnt = 0;
    let mut to_bit = vec![usize::max_value(); n];
    for i in 0..n {
        if (a ^ b) == (1 << i) {
            last = i;
        } else {
            to_bit[i] = cnt;
            cnt += 1;
        }
    }
    to_bit[last] = cnt;

    println!("YES");
    for s in (0..1 << n) {
        let mut ans = a;
        let gray = s ^ (s >> 1);
        for i in 0..n {
            let j = to_bit[i];
            if ((gray >> j) & 1) != 0 {
                ans ^= (1 << i);
            }
        }
        print!("{} ", ans);
    }
    println!("");
}

