fn find(n: usize, a: usize) -> Vec<usize> {
    let mut ret = Vec::new();
    let mut mask = 1;
    let mut m = n;
    let mut ones = vec![];
    while mask <= a {
        if a & mask == 0 {
            mask <<= 1;
            continue;
        }
        if mask == 1 << n - 1 {
            let mut vec = grays(m).iter().map(|x| add_ones(*x, &ones)).map(|x| add_topone(x, n, ones.len() % 2 == 1)).collect();
            ret.append(&mut vec);
            m = 0;
            break;
        }
        m -= 1;
        let mut vec = grays(m).iter().map(|x| add_ones(*x, &ones)).map(|x| add_zero(x, mask)).map(|x| add_topone(x, n, ones.len() % 2 == 1)).collect();
        ones.push(mask);
        ret.append(&mut vec);
        mask <<= 1;
    }
    if m > 0 {
        let mut vec = grays(m).iter().map(|x| add_ones(*x, &ones)).map(|x| add_topone(x, n, ones.len() % 2 == 1)).collect();
        ret.append(&mut vec);
    }
    ret
}

fn add_ones(x: usize, ones: &Vec<usize>) -> usize {
    let mut ret = x;
    for mask in ones {
        let y = ret & mask - 1;
        ret = (ret - y << 1) | mask | y;
    }
    ret
}

fn add_topone(x: usize, n: usize, flag: bool) -> usize {
    if flag {
        x ^ 1 << n - 1
    } else {
        x
    }
}

fn add_zero(n: usize, mask: usize) -> usize {
    let y = n & mask - 1;
    (n - y << 1) + y
}

fn grays(n: usize) -> Vec<usize> {
    (0..1<<n).map(|x| x ^ (x >> 1)).collect()
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let a: usize = sc.read();
    let b: usize = sc.read();

    let (a, b, reversed) = if a > b { (b, a, true) } else { (a, b, false) };

    match solve(n, a, b) {
        Some(_) => {
            println!("YES");

            let m = 1 << n;
            let mut ans = vec![0; m];
            let mut vis = vec![false; m];

            let mut cur = b;
            vis[b] = true;
            ans[m - 1] = b;
            let mut pos = m - 1;
            while cur != m - 1 {
                for i in 0..n {
                    let next = cur ^ (1 << i);
                    if !vis[next] && cur < next {
                        cur = next;
                        pos -= 1;
                        vis[cur] = true;
                        ans[pos] = cur;
                        break;
                    }
                }
            }
            assert_eq!(cur, m - 1);

            let mut cur = a;
            vis[a] = true;
            ans[0] = a;
            let mut pos = 0;
            while cur != 0 {
                for i in 0..n {
                    let next = cur ^ (1 << i);
                    if !vis[next] && cur > next {
                        cur = next;
                        pos += 1;
                        vis[cur] = true;
                        ans[pos] = cur;
                        break;
                    }
                }
            }

            assert_eq!(cur, 0);
            loop {
                match (0..n)
                    .map(|i| cur ^ (1 << i))
                    .filter(|&next| next < cur)
                    .filter(|&next| !vis[next])
                    .next()
                {
                    Some(next) => {
                        pos += 1;
                        cur = next;
                        ans[pos] = cur;
                        vis[cur] = true;
                        continue;
                    }
                    None => {}
                }
                match (0..n)
                    .map(|i| cur ^ (1 << i))
                    .filter(|&next| !vis[next])
                    .next()
                {
                    Some(next) => {
                        assert!(next > cur);
                        pos += 1;
                        cur = next;
                        ans[pos] = cur;
                        vis[cur] = true;
                    }
                    None => {
                        break;
                    }
                }
            }
            assert!(pos == m - 1 || ans[pos + 1] != 0);

            if reversed {
                ans = ans.into_iter().rev().collect();
            }

            let (a, b) = if reversed { (b, a) } else { (a, b) };

            for (i, p) in ans.into_iter().enumerate() {
                if i > 0 {
                    print!(" ");
                }
                print!("{}", p);
            }
            println!();
        }
        None => println!("NO"),
    }
}

