fn solve(n: usize, a: i32, b: i32) -> Option<Vec<i32>> {
    if n == 0 {
        return Some(vec![a]);
    }
    let difference = (0..18).filter(|i| (1 << i) & a != (1 << i) & b).count();
    if difference & 1 == 0 {
        return None;
    }

    let k = (0..).find(|i| (1 << i) & a != (1 << i) & b).unwrap();
    assert!((1 << k) & a != (1 << k) & b);
    let mask = (1 << k) - 1;

    let new_a = ((a >> (k + 1)) << k) + (a & mask);
    let new_b = ((b >> (k + 1)) << k) + (b & mask);
    let x = new_a ^ 1;
    let prefix = if n == 1 {
        Some(vec![new_a])
    } else {
        solve(n - 1, new_a, x)
    };
    let suffix = if n == 1 {
        Some(vec![new_b])
    } else {
        solve(n - 1, x, new_b)
    };
    match (prefix, suffix) {
        (Some(prefix), Some(suffix)) => {
            let mut ans = vec![];
            for p in prefix.into_iter() {
                let prefix = (p >> k) << (k + 1);
                let suffix = p & mask;
                let v = prefix + suffix + ((1 << k) & a);
                ans.push(v);
            }
            for p in suffix.into_iter() {
                let prefix = (p >> k) << (k + 1);
                let suffix = p & mask;
                let v = prefix + suffix + ((1 << k) & b);
                ans.push(v);
            }
            Some(ans)
        }
        _ => None,
    }
}

