fn binary_to_num(binary: &Vec<i32>) -> u64 {
    let mut ret = 0u64;
    let mut coef = 1;
    for i in 0..17 {
        ret += binary[i] as u64 * coef;
        coef *= 2;
    }
    ret
}

fn toggle_binary(i: usize, binary: &mut Vec<i32>) {
    if binary[i] == 1 {
        binary[i] = 0;
    } else {
        binary[i] = 1;
    }
}

fn calc_toggle_index(n: usize, i: usize) -> usize {
    if i % 2 == 1 {
        return 0;
    }

    for j in (0..n - 1).rev() {
        let candidate_const = 1 << j;
        let candidate_coef = 1 << (j + 1);
        if i >= candidate_const && (i - candidate_const) % candidate_coef == 0 {
            return j;
        }
    }
    assert!(false);
    0
}

fn main() {
    let v: Vec<u64> = read_vec();
    let (n, a, b) = (v[0], v[1], v[2]);
    let mut a_binary = vec![0; 17];
    let mut b_binary = vec![0; 17];

    let mut a_copy = a;
    for i in 0..17 {
        if a_copy % 2 == 1 {
            a_binary[i] = 1;
        }
        a_copy /= 2;
    }

    let mut b_copy = b;
    for i in 0..17 {
        if b_copy % 2 == 1 {
            b_binary[i] = 1;
        }
        b_copy /= 2;
    }

    let mut different_digit_idx = 0usize;
    let mut different_digit_count = 0;

    for i in 0..17 {
        if a_binary[i] != b_binary[i] {
            different_digit_count += 1;
            different_digit_idx = i;
        }
    }
    if different_digit_count != 1 {
        println!("NO");
        return;
    }
    println!("YES");

    let mut etc_indexes: Vec<usize> = Vec::new();
    for i in 0..n as usize {
        if i != different_digit_idx {
            etc_indexes.push(i);
        }
    }
    // println!("diff bit {}", different_digit_idx);

    let mut answers = Vec::new();
    let mut answers_num = Vec::new();
    answers.push(binary_to_num(&a_binary).to_string());
    answers_num.push(binary_to_num(&a_binary));
    print!("{} ", binary_to_num(&a_binary).to_string());
    for i in 1..(1 << n) {
        let mut toggle_index;
        if i == 1 << (n - 1) {
            toggle_index = different_digit_idx;
        } else {
            toggle_index = etc_indexes[calc_toggle_index(n as usize, i)];
        }
        // println!("toggle {}", toggle_index);
        toggle_binary(toggle_index, &mut a_binary);
        answers.push(binary_to_num(&a_binary).to_string());
        answers_num.push(binary_to_num(&a_binary));
        if i != (1 << n) - 1 {
            print!("{} ", binary_to_num(&a_binary).to_string());
        } else {
            println!("{}", binary_to_num(&a_binary).to_string());
        }
    }
    assert_eq!(*answers_num.iter().max().unwrap(), (1 << n) - 1);
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let a: usize = sc.read();
    let b: usize = sc.read();

    let (a, b, reversed) = if a > b { (b, a, true) } else { (a, b, false) };

    match solve(n, a, b) {
        Some(_) => {
            println!("YES");

            let m = 1 << n;
            let mut ans = vec![0; m];
            let mut vis = vec![false; m];

            let mut cur = b;
            vis[b] = true;
            ans[m - 1] = b;
            let mut pos = m - 1;
            while cur != m - 1 {
                for i in 0..n {
                    let next = cur ^ (1 << i);
                    if !vis[next] && cur < next {
                        cur = next;
                        pos -= 1;
                        vis[cur] = true;
                        ans[pos] = cur;
                        break;
                    }
                }
            }
            assert_eq!(cur, m - 1);

            let mut cur = a;
            vis[a] = true;
            ans[0] = a;
            let mut pos = 0;
            while cur != 0 {
                for i in 0..n {
                    let next = cur ^ (1 << i);
                    if !vis[next] && cur > next {
                        cur = next;
                        pos += 1;
                        vis[cur] = true;
                        ans[pos] = cur;
                        break;
                    }
                }
            }

            assert_eq!(cur, 0);
            loop {
                match (0..n)
                    .map(|i| cur ^ (1 << i))
                    .filter(|&next| next < cur)
                    .filter(|&next| !vis[next])
                    .next()
                {
                    Some(next) => {
                        pos += 1;
                        cur = next;
                        ans[pos] = cur;
                        vis[cur] = true;
                        continue;
                    }
                    None => {}
                }
                match (0..n)
                    .map(|i| cur ^ (1 << i))
                    .filter(|&next| !vis[next])
                    .next()
                {
                    Some(next) => {
                        assert!(next > cur);
                        pos += 1;
                        cur = next;
                        ans[pos] = cur;
                        vis[cur] = true;
                    }
                    None => {
                        break;
                    }
                }
            }
            if pos != m - 1 && ans[pos + 1] == 0 {
                println!("NO");
                return;
            }

            if reversed {
                ans = ans.into_iter().rev().collect();
            }

            let (a, b) = if reversed { (b, a) } else { (a, b) };
            validate(ans.clone(), a, b);

            for (i, p) in ans.into_iter().enumerate() {
                if i > 0 {
                    print!(" ");
                }
                print!("{}", p);
            }
            println!();
        }
        None => println!("NO"),
    }
}

fn validate(ans: Vec<usize>, a: usize, b: usize) {
    let n = ans.len();
    assert_eq!(ans[0], a);
    assert_eq!(ans[n - 1], b);
    for i in 1..n {
        assert_eq!((ans[i - 1] ^ ans[i]).count_ones(), 1);
    }
}

fn solve(n: usize, a: usize, b: usize) -> Option<Vec<usize>> {
    let mut count: [i32; 18] = [0; 18];
    for mask in 0..(1 << n) {
        count[(mask as u32).count_ones() as usize] += 1;
    }

    let max_bit = count
        .iter()
        .enumerate()
        .filter(|&(_, &c)| c > 0)
        .map(|(i, _)| i)
        .max()
        .unwrap();

    let goal_bit = b.count_ones() as usize;

    let mut vis = [0; 18];
    let mut cur = a.count_ones() as usize;
    let mut path = vec![cur];
    vis[cur] += 1;
    if vis[cur] > count[cur] {
        return None;
    }
    while cur > 0 {
        cur -= 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    assert_eq!(cur, 0);
    if vis == count {
        return Some(path);
    }
    cur += 1;
    path.push(cur);
    vis[cur] += 1;
    while cur < goal_bit {
        if vis[cur - 1] > count[cur - 1] {
            return None;
        }
        if vis[cur - 1] < count[cur - 1] {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }

    while cur < max_bit {
        cur += 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if vis == count {
        return Some(path);
    }
    assert_eq!(cur, max_bit);
    cur -= 1;
    path.push(cur);
    vis[cur] += 1;
    while vis != count {
        if vis[cur + 1] > count[cur + 1] {
            return None;
        }
        if vis[cur + 1] < count[cur + 1] {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if path[path.len() - 1] != goal_bit {
        None
    } else {
        Some(path)
    }
}

