    for i in 0..17 {
        ret += binary[i] as u64 * coef;
        coef *= 2;
    }
    ret
}

fn toggle_binary(i: usize, binary: &mut Vec<i32>) {
    if binary[i] == 1 {
        binary[i] = 0;
    } else {
        binary[i] = 1;
    }
}

fn calc_toggle_index(n: usize, i: usize) -> usize {
    if i % 2 == 1 {
        return 0;
    }

    for j in (0..n - 1).rev() {
        let candidate_const = 1 << j;
        let candidate_coef = 1 << (j + 1);
        if i >= candidate_const && (i - candidate_const) % candidate_coef == 0 {
            return j;
        }
    }
    assert!(false);
    0
}

fn main() {
    let v: Vec<u64> = read_vec();
