            different_digit_idx.push(i);
        }
    }
    if different_digit_count % 2 != 1 {
        println!("NO");
        return;
    }
    println!("YES");

    let mut etc_indexes: Vec<usize> = Vec::new();
    for i in 1..different_digit_idx.len() {
        etc_indexes.push(different_digit_idx[i]);
    }
    let different_digit_dixt = different_digit_idx.iter().cloned().collect::<HashSet<_>>();
    for i in 0..n as usize {
