fn chain_same(list: Vec<usize>, a: usize, b: usize, nth: usize) -> Vec<usize> {
    let mut new_list = vec![];
    let n = list.len();
    assert!(n % 2 == 0);

    let mut upper = ifv!(bit(a, nth), 1, 0)<<nth;
    let mut lower = upper ^ (1<<nth);

    for i in 0..n/2 {
        let a = list[i*2];
        let b = list[i*2+1];
        new_list.push(upper|a);
        new_list.push(lower|a);
        new_list.push(lower|b);
        new_list.push(upper|b);
    }
    new_list
}

fn chain_diff(list: Vec<usize>, a: usize, b: usize, uth: usize, vth: usize) -> Vec<usize> {
    let mut new_list = vec![];
    let mut n = list.len();
    let mut upper0 = ifv!(bit(a, uth), 1, 0)<<uth;
    let mut upper1 = ifv!(bit(a, vth), 1, 0)<<vth;
    let mut lower0 = upper0 ^ (1<<uth);
    let mut lower1 = upper1 ^ (1<<vth);

    for i in 0..n {
        new_list.push(list[i] | upper0 | upper1);
    }
    for i in (0..n).rev() {
        new_list.push(list[i] | upper0 | lower1);
    }
    let mut later_half = chain_same(list, a ^ (1<<uth) ^ (1<<vth), b, vth);
    for i in 0..2*n {
        later_half[i] |= lower0;
    }
    new_list.append(&mut later_half);
    new_list
}

fn bit(a: usize, nth: usize) -> bool {
    (a >> nth) & 1 == 1
}

fn solve(n: usize, a: usize, b: usize) -> Option<Vec<usize>> {
    let mut same_bit = vec![];
    let mut diff_bit = vec![];
    for i in 0..n {
        if (a >> i) & 1 == (b >> i) & 1 {
            same_bit.push(i);
        } else {
            diff_bit.push(i);
        }
    }
    assert!(diff_bit.len() >= 1);

    if diff_bit.len() % 2 == 0 {
        return None;
    }
    let d0 = diff_bit[0];
    let mut list = ifv!(bit(a, diff_bit[0]), vec![1<<d0, 0], vec![0, 1<<d0]);
    diff_bit.remove(0);
    let dn = diff_bit.len();
    for i in 0..dn/2 {
        list = chain_diff(list, a, b, diff_bit[i*2], diff_bit[i*2+1]);
    }
    for sth in same_bit {
        list = chain_same(list, a, b, sth);
    }
    Some(list)
}

fn assert_list(m: usize, a: usize, b: usize, list: &Vec<usize>) {
    // debug!(list);
    let n = list.len();
    let mut cnt = vec![0; 1<<m];
    for i in 0..n-1 {
        let diff = list[i] ^ list[i+1];
        assert_eq!((diff as u64).count_ones(), 1);
    }
    for i in 0..n {
        cnt[list[i]] += 1;
    }
    for i in 0..(1<<m) {
        assert_eq!(cnt[i], 1);
    }
    cnt[0] == a;
    cnt[(1<<m)-1] == b;
}

fn main() {
    input! {
        n: usize, a: usize, b: usize
    };

    if let Some(list) = solve(n, a, b) {
        assert_list(n, a, b, &list);
        println!("YES");
        println!("{}", join!(list, " "));
    } else {
        println!("NO");
    }
}

