use std::collections::BTreeMap;

fn main() {
    input! {
        n: usize,
        a: usize,
        b: usize,
    }

    let mut gray = vec![0; 1 << n];

    for i in 0..gray.len() {
        gray[i] = i ^ (i >> 1);
    }

    let mut mm = BTreeMap::<(usize, usize), usize>::new();

    for i in 0..gray.len() {
        mm.insert((gray[i], gray[(i + 1) % gray.len()]), i);
    }

    let mut pos = None;

    for i in 0..n {
        for j in i..n {
            let aa = bswap(a, i, j);
            let bb = bswap(b, i, j);

            if let Some(p) = mm.get(&(aa, bb)) {
                pos = Some((false, p, i, j));
            } else if let Some(p) = mm.get(&(bb, aa)) {
                pos = Some((true, p, i, j));
            }
        }
    }

    // dbg!(&pos);

    if pos == None {
        println!("NO");
        return;
    }

    let (dir, pos, i, j) = pos.unwrap();

    println!("YES");

    for k in 0..gray.len() {
        if k > 0 {
            print!(" ");
        }
        if !dir {
            print!("{}", bswap(gray[(gray.len() + pos - k) % gray.len()], i, j));
        } else {
            print!("{}", bswap(gray[(pos + 1 + k) % gray.len()], i, j));
        }
    }
    println!();
}

fn bswap(a: usize, i: usize, j: usize) -> usize {
    (a & !(1 << i) & !(1 << j)) | ((a >> i) & 1) << j | ((a >> j) & 1) << i
}

