fn main() {
    input! {
        n: usize, a: usize, b: usize
    };
    let mut visited = vec![false; n];
    let mut ans: Vec<usize> = vec![];

    let mut an = vec![0; n];
    let mut bn = vec![0; n];
    let mut diffcnt = 0;
    for i in 0..n {
        an[i] = (a >> i) & 1;
        bn[i] = (b >> i) & 1;
        diffcnt += if an[i] == bn[i] { 0 } else { 1 };
    }
    if diffcnt % 2 == 0 {
        println!("NO");
        return;
    }

    for i in 0..n {
        if an[i] != bn[i] {
            visited[i] = true;
            ans.push(an[i] << i);
            ans.push(bn[i] << i);
            break;
        }
    }
    for i in 0..n {
        if an[i] == bn[i] {
            let up = an[i] << i;
            let dw = (1 << i) - up;
            let mut nans = vec![];
            let k = ans.len() / 2;
            for j in 0..k {
                let l = ans[j * 2];
                let r = ans[j * 2 + 1];
                nans.push(l ^ up);
                nans.push(l ^ dw);
                nans.push(r ^ dw);
                nans.push(r ^ up);
            }
            ans = nans;
        }
    }

    for i in 0..n {
        for j in 0..n {
            if an[i] != bn[i] && an[j] != bn[j] && !visited[i] && !visited[j] {
                visited[i] = true;
                visited[j] = true;

                let fr = an[i] << i;
                let ba = (1 << i) - fr;

                let up = an[j] << j;
                let dw = (1 << j) - up;

                let k = ans.len() / 2;
                let mut nans = vec![];
                for ki in 0..k {
                    let l = ans[ki * 2];
                    let r = ans[ki * 2 + 1];

                    nans.push(l ^ fr ^ up);
                    nans.push(l ^ ba ^ up);
                    nans.push(l ^ ba ^ dw);
                    nans.push(l ^ fr ^ dw);

                    nans.push(r ^ fr ^ dw);
                    nans.push(r ^ ba ^ dw);
                    nans.push(r ^ ba ^ up);
                    nans.push(r ^ fr ^ up);
                }
                ans = nans;
            }
        }
    }

    println!("YES");
    let n = ans.len();
    for i in 0..n {
        if i >= 1 {
            print!(" ");
        }
        print!("{}", ans[i]);
    }
}

// 0 -> C (< 2^N) をつくる
fn calc(n: usize, c: usize) -> Vec<usize> {
    assert!(c.count_ones() % 2 == 1);
    if n == 1 {
        return vec![0, 1];
    }
    if (c >> (n - 1)) & 1 == 0 {
        let mut i = n - 1;
        while (c >> i) & 1 == 0 {
            i -= 1;
        }
        let mut ans = calc(n, c | (1 << (n - 1)) ^ (1 << i));
        for a in ans.iter_mut() {
            let x = *a >> (n - 1) & 1;
            let y = *a >> i & 1;
            *a &= !(1 << (n - 1)) & !(1 << i);
            *a |= (x << i) | (y << (n - 1));
        }
        return ans;
    }
    let mut f = calc(n - 1, 1);
    let t = calc(n - 1, c ^ (1 << (n - 1)) ^ 1);
    for t in t {
        f.push(t ^ 1 ^ (1 << (n - 1)));
    }
    f
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let a: usize = it.next().unwrap().parse().unwrap();
    let b: usize = it.next().unwrap().parse().unwrap();
    let c = a ^ b;
    if c.count_ones() % 2 == 0 {
        println!("NO");
        return;
    }
    let ans = calc(c, n);
    assert!(ans.windows(2).all(|a| (a[0] ^ a[1]).count_ones() == 1));
    let mut out = String::from("NO\n");
    for x in ans {
        out.push_str(&format!("{} ", x ^ a));
    }
    out.pop();
    println!("{}", out);
}

fn main() {
    run();
}

