    let mut t = a ^ b;
    let mut cnt = 0;
    while t > 0 {
        if t & 1 == 1 {
            cnt += 1;
        }
        t >>= 1;
    }
    if cnt % 2 == 0 {
        println!("NO");
        return;
    }
    println!("Yes");
    let ans = find(n, a ^ b);
    print!("{}", ans[0] ^ a);
    for i in 1..1 << n {
        print!(" {}", ans[i] ^ a);
    }
    println!("");
}

fn find(n: usize, a: usize) -> Vec<usize> {
    let mut ret = Vec::new();
    let mut mask = 1;
    let mut m = n;
    let mut ones = vec![];
    while mask <= a {
        if a & mask == 0 {
            mask <<= 1;
            continue;
        }
        if mask == 1 << n - 1 {
            let mut vec = grays(m).iter().map(|x| add_ones(*x, n, &ones)).collect();
            ret.append(&mut vec);
            m = 0;
            break;
        }
        m -= 1;
        let mut vec = grays(m).iter().map(|x| add_ones(*x, n, &ones)).map(|x| add_zero(x, mask)).collect();
        ones.push(mask);
        ret.append(&mut vec);
        mask <<= 1;
    }
    if m > 0 {
        let mut vec = grays(m).iter().map(|x| add_ones(*x, n, &ones)).collect();
        ret.append(&mut vec);
    }
    ret
}

fn add_ones(x: usize, n: usize, ones: &Vec<usize>) -> usize {
    let mut ret = x;
    for mask in ones {
        let y = ret & mask - 1;
        ret = ((ret - y << 1) | mask) + y;
    }
    if ones.len() % 2 == 1 {
        ret ^= 1 << n - 1;
    }
    ret
}

fn add_zero(n: usize, mask: usize) -> usize {
    let y = n & mask - 1;
    (n - y << 1) + y
}

fn grays(n: usize) -> Vec<usize> {
    (0..1<<n).map(|x| x ^ (x >> 1)).collect()
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let a: usize = sc.read();
    let b: usize = sc.read();
    match solve(n, a, b) {
        Some(path) => {
            println!("YES");
            let mut ans = vec![0; 1 << n];
            let mut vis = vec![false; 1 << n];
            ans[0] = a;
            vis[a] = true;
            if dfs(0, &mut vis, &path, &mut ans, b) {
                for (i, p) in ans.into_iter().enumerate() {
                    if i > 0 {
                        print!(" ");
                    }
                    print!("{}", p);
                }
                println!();
            } else {
                unreachable!()
            }
        }
        None => println!("NO"),
    }
}

fn dfs(pos: usize, vis: &mut [bool], path: &[usize], ans: &mut [usize], b: usize) -> bool {
    if pos == ans.len() - 1 {
        return ans[pos] == b;
    }
    let cur = ans[pos];
    for i in 0..17 {
        let next = cur ^ (1 << i);
        if !vis[next] && next.count_ones() as usize == path[pos + 1] {
            ans[pos + 1] = next;
            vis[next] = true;
            if dfs(pos + 1, vis, path, ans, b) {
                return true;
            }
            vis[next] = false;
        }
    }
    false
}

fn solve(n: usize, a: usize, b: usize) -> Option<Vec<usize>> {
    let mut count: [i32; 18] = [0; 18];
    for mask in 0..(1 << n) {
        count[(mask as u32).count_ones() as usize] += 1;
    }

    let max_bit = count
        .iter()
        .enumerate()
        .filter(|(_, c)| **c > 0)
        .map(|(i, _)| i)
        .max()
        .unwrap();

    let goal_bit = b.count_ones() as usize;

    let mut vis = [0; 18];
    let mut cur = a.count_ones() as usize;
    let mut path = vec![cur];
    vis[cur] += 1;
    if vis[cur] > count[cur] {
        return None;
    }
    while cur > 0 {
        cur -= 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    assert_eq!(cur, 0);
    if vis == count {
        return Some(path);
    }
    cur += 1;
    path.push(cur);
    vis[cur] += 1;
    while cur < goal_bit {
        if vis[cur - 1] > count[cur - 1] {
            return None;
        }
        if vis[cur - 1] < count[cur - 1] {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }

    while cur < max_bit {
        cur += 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if vis == count {
        return Some(path);
    }
    assert_eq!(cur, max_bit);
    cur -= 1;
    path.push(cur);
    vis[cur] += 1;
    while vis != count {
        if vis[cur + 1] > count[cur + 1] {
            return None;
        }
        if vis[cur + 1] < count[cur + 1] {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if path[path.len() - 1] != goal_bit {
        None
    } else {
        Some(path)
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

