fn main() {
    input! {
        n: usize, a: usize, b: usize
    };
    let mut visited = vec![false; n];
    let mut ans: Vec<usize> = vec![];

    let mut an = vec![0; n];
    let mut bn = vec![0; n];
    let mut diffcnt = 0;
    for i in 0..n {
        an[i] = (a >> i) & 1;
        bn[i] = (b >> i) & 1;
        diffcnt += if an[i] == bn[i] { 0 } else { 1 };
    }
    if diffcnt % 2 == 0 {
        println!("NO");
        return;
    }

    for i in 0..n {
        if an[i] != bn[i] {
            visited[i] = true;
            ans.push(an[i] << i);
            ans.push(bn[i] << i);
            break;
        }
    }
    for i in 0..n {
        if an[i] == bn[i] {
            let up = an[i] << i;
            let dw = (1 << i) - up;
            let mut nans = vec![];
            let k = ans.len() / 2;
            for j in 0..k {
                let l = ans[j * 2];
                let r = ans[j * 2 + 1];
                nans.push(l ^ up);
                nans.push(l ^ dw);
                nans.push(r ^ dw);
                nans.push(r ^ up);
            }
            ans = nans;
        }
    }

    for i in 0..n {
        for j in i + 1..n {
            if an[i] != bn[i] && an[j] != bn[j] && !visited[i] && !visited[j] {
                visited[i] = true;
                visited[j] = true;

                let fr = an[i] << i;
                let ba = (1 << i) - fr;

                let up = an[j] << j;
                let dw = (1 << j) - up;

                let k = ans.len() / 2;
                let mut nans = vec![];
                for ki in 0..k {
                    let l = ans[ki * 2];
                    let r = ans[ki * 2 + 1];

                    if ki == k - 1 {
                        nans.push(l ^ fr ^ up);
                        nans.push(l ^ ba ^ up);
                        nans.push(r ^ ba ^ up);
                        nans.push(r ^ fr ^ up);
                        nans.push(r ^ fr ^ dw);
                        nans.push(l ^ fr ^ dw);
                        nans.push(l ^ ba ^ dw);
                        nans.push(r ^ ba ^ dw);
                    } else {
                        nans.push(l ^ fr ^ up);
                        nans.push(l ^ ba ^ up);
                        nans.push(l ^ ba ^ dw);
                        nans.push(l ^ fr ^ dw);
                        nans.push(r ^ fr ^ dw);
                        nans.push(r ^ ba ^ dw);
                        nans.push(r ^ ba ^ up);
                        nans.push(r ^ fr ^ up);
                    }
                }
                ans = nans;
            }
        }
    }

    println!("YES");
    let n = ans.len();
    for i in 0..n {
        if i >= 1 {
            print!(" ");
        }
        print!("{}", ans[i]);
    }
}

