fn is_correct(x: &[usize]) -> bool {
    let n = x.len();
    let mut s = HashSet::new();
    for value in x {
        if *value >= n {
            return false;
        }
        s.insert(value);
    }
    if s.len() != n {
        return false;
    }
    for i in 0..n - 1 {
        if (x[i] ^ x[i + 1]).count_ones() != 1 {
            return false;
        }
    }
    true
}

fn gen_one(level: usize, first: bool, memo: &mut HashMap<(usize, bool), Vec<usize>>) -> Vec<usize> {
    if memo.contains_key(&(level, first)) {
        return memo[&(level, first)].clone();
    }
    if level == 0 {
        vec![0]
    } else {
        if first {
            let mut res = Vec::new();
            let sub = gen_one(level - 1, first, memo);
            for x in &sub {
                res.push((x << 2) | (0b00usize));
            }
            for x in sub.iter().rev() {
                res.push((x << 2) | (0b01usize));
            }
            for x in &sub {
                res.push((x << 2) | (0b11usize));
            }
            for x in sub.iter().rev() {
                res.push((x << 2) | (0b10usize));
            }
            memo.insert((level, first), res);
            memo[&(level, first)].clone()
        } else {
            let mut res = Vec::new();
            let sub1 = gen_one(level - 1, true, memo);
            let sub2 = gen_one(level - 1, false, memo);
            for x in &sub1 {
                res.push((x << 2) | (0b10usize));
            }
            for x in sub1.iter().rev() {
                res.push((x << 2) | (0b00usize));
            }
            for x in &sub1 {
                res.push((x << 2) | (0b01usize));
            }
            for x in &sub2 {
                res.push((x << 2) | (0b11usize));
            }
            memo.insert((level, first), res);
            memo[&(level, first)].clone()
        }
    }
}

fn gen(one: usize, zero: usize) -> Vec<usize> {
    if one >= 1 {
        let mut res = Vec::new();
        let sub = gen(0, zero);
        let mut memo = HashMap::new();
        let first = gen_one(one / 2, true, &mut memo);
        let second = gen_one(one / 2, true, &mut memo);
        for x in first {
            for y in &sub {
                res.push(((y << one) | (x << 1) | 0));
            }
        }
        for x in second {
            for y in sub.iter().rev() {
                res.push(((y << one) | (x << 1) | 1));
            }
        }
        res
    } else if zero >= 1 {
        let mut res = Vec::new();
        let sub = gen(one, zero - 1);
        for x in &sub {
            res.push(x << 1);
        }
        for x in sub.iter().rev() {
            res.push((x << 1) | 1usize);
        }
        res
    } else {
        vec![0]
    }
}

fn generate_goal(goal: usize, n: usize) -> Vec<usize> {
    let mut one = Vec::new();
    let mut zero = Vec::new();
    for i in 0..n {
        if ((goal >> i) & 1) != 0 {
            one.push(i);
        } else {
            zero.push(i);
        }
    }
    //eprintln!("one = {:?} zero = {:?}", one, zero);
    let result = gen(one.len(), zero.len());
    //eprintln!("result = {:?}", result);
    let mut res = Vec::new();
    for x in result {
        let mut y = 0;
        for i in 0..one.len() {
            if ((x >> i) & 1) == 1 {
                y |= 1 << one[i];
            }
        }
        for i in 0..zero.len() {
            let j = one.len() + i;
            if ((x >> j) & 1) == 1 {
                y |= 1 << zero[i];
            }
        }
        res.push(y);
    }
    assert_eq!(0, res[0]);
    assert_eq!(goal, res[(1 << n) - 1]);
    res
}

fn solve_agc() {
    let (n, a, b) = read!(usize, usize, usize);
    if (a ^ b).count_ones() % 2 == 0 {
        println!("NO");
        return;
    }

    println!("YES");
    let answer = generate_goal(a ^ b, n);
    assert_eq!(a, answer[0] ^ a);
    assert_eq!(b, answer[(1 << n) - 1] ^ a);
    assert!(is_correct(&answer));
    for x in answer {
        println!("{}", x ^ a);
    }
}

fn run() {
    solve_agc();
}

