fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let a: usize = sc.read();
    let b: usize = sc.read();

    let (a, b, reversed) = if a > b { (b, a, true) } else { (a, b, false) };

    match solve(n, a, b) {
        Some(_) => {
            println!("YES");

            let m = 1 << n;
            let mut ans = vec![0; m];
            let mut vis = vec![false; m];

            let mut cur = b;
            vis[b] = true;
            ans[m - 1] = b;
            let mut pos = m - 1;
            while cur != m - 1 {
                for i in 0..n {
                    let next = cur ^ (1 << i);
                    if !vis[next] && cur < next {
                        cur = next;
                        pos -= 1;
                        vis[cur] = true;
                        ans[pos] = cur;
                        break;
                    }
                }
            }
            assert_eq!(cur, m - 1);

            let mut cur = a;
            vis[a] = true;
            ans[0] = a;
            let mut pos = 0;
            while cur != 0 {
                for i in 0..n {
                    let next = cur ^ (1 << i);
                    if !vis[next] && cur > next {
                        cur = next;
                        pos += 1;
                        vis[cur] = true;
                        ans[pos] = cur;
                        break;
                    }
                }
            }

            assert_eq!(cur, 0);
            loop {
                match (0..n)
                    .map(|i| cur ^ (1 << i))
                    .filter(|&next| next < cur)
                    .filter(|&next| !vis[next])
                    .next()
                {
                    Some(next) => {
                        pos += 1;
                        cur = next;
                        ans[pos] = cur;
                        vis[cur] = true;
                        continue;
                    }
                    None => {}
                }
                match (0..n)
                    .map(|i| cur ^ (1 << i))
                    .filter(|&next| !vis[next])
                    .next()
                {
                    Some(next) => {
                        assert!(next > cur);
                        pos += 1;
                        cur = next;
                        ans[pos] = cur;
                        vis[cur] = true;
                    }
                    None => {
                        break;
                    }
                }
            }

            if reversed {
                ans = ans.into_iter().rev().collect();
            }

            for (i, p) in ans.into_iter().enumerate() {
                if i > 0 {
                    print!(" ");
                }
                print!("{}", p);
            }
            println!();
        }
        None => println!("NO"),
    }
}

fn solve(n: usize, a: usize, b: usize) -> Option<Vec<usize>> {
    let mut count: [i32; 18] = [0; 18];
    for mask in 0..(1 << n) {
        count[(mask as u32).count_ones() as usize] += 1;
    }

    let max_bit = count
        .iter()
        .enumerate()
        .filter(|&(_, &c)| c > 0)
        .map(|(i, _)| i)
        .max()
        .unwrap();

    let goal_bit = b.count_ones() as usize;

    let mut vis = [0; 18];
    let mut cur = a.count_ones() as usize;
    let mut path = vec![cur];
    vis[cur] += 1;
    if vis[cur] > count[cur] {
        return None;
    }
    while cur > 0 {
        cur -= 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    assert_eq!(cur, 0);
    if vis == count {
        return Some(path);
    }
    cur += 1;
    path.push(cur);
    vis[cur] += 1;
    while cur < goal_bit {
        if vis[cur - 1] > count[cur - 1] {
            return None;
        }
        if vis[cur - 1] < count[cur - 1] {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }

    while cur < max_bit {
        cur += 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if vis == count {
        return Some(path);
    }
    assert_eq!(cur, max_bit);
    cur -= 1;
    path.push(cur);
    vis[cur] += 1;
    while vis != count {
        if vis[cur + 1] > count[cur + 1] {
            return None;
        }
        if vis[cur + 1] < count[cur + 1] {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if path[path.len() - 1] != goal_bit {
        None
    } else {
        Some(path)
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

