fn calc(a: i64, b: i64, n: usize, invalid_bits: i64) -> Vec<i64> {
    if n == 1 {
        return vec![a, b]
    }

    let x = a ^ b;
    let diff_bit = x & -x;
    let diff_bit_mask = !diff_bit;
    let next_invalid_bits = invalid_bits | diff_bit;
    let next_valid_bits = !next_invalid_bits;
    let c = a ^ (next_valid_bits & -next_valid_bits);
    let left = calc(a & diff_bit_mask, c & diff_bit_mask, n - 1, next_invalid_bits);
    let right = calc(c & diff_bit_mask, b & diff_bit_mask, n - 1, next_invalid_bits);

    let mut ret = left.iter().map(|&k| k | (a & diff_bit)) .collect::<Vec<_>>();
    ret.extend(right.iter().map(|&k| k | (b & diff_bit)) .collect::<Vec<_>>());
    ret
}

fn calc(n: usize, c: usize) -> Vec<usize> {
    assert!(c.count_ones() % 2 == 1);
    if n == 1 {
        return vec![0, 1];
    }
    if (c >> (n - 1)) & 1 == 0 {
        let mut i = n - 1;
        while (c >> i) & 1 == 0 {
            i -= 1;
        }
        let mut ans = calc(n, (c ^ (1 << i)) | (1 << (n - 1)));
        for a in ans.iter_mut() {
            let x = *a >> (n - 1) & 1;
            let y = *a >> i & 1;
            *a &= !(1 << (n - 1)) & !(1 << i);
            *a |= (x << i) | (y << (n - 1));
        }
        return ans;
    }
    let mut f = calc(n - 1, 1);
    let t = calc(n - 1, c ^ (1 << (n - 1)) ^ 1);
    for t in t {
        f.push(t ^ 1 ^ (1 << (n - 1)));
    }
    f
}

fn run() {
