const MOD: usize = 1e9 as usize + 7;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let a: u64 = sc.read();
    let b: u64 = sc.read();
    if let Some(ans) = construct(a, b, 1 << n) {
        sc.write("YES\n");
        for (i, ans) in ans.into_iter().enumerate() {
            if i > 0 {
                sc.write(" ");
            }
            sc.write(ans);
        }
        sc.write("\n");
    } else {
        sc.write("NO\n");
    }
