fn gen_gray(n: usize, a: usize, b: usize) -> Vec<usize> {
    // dbg!((n, a, b));

    let mut gray = vec![0; 1 << n];
    let mut v = vec![];

    for i in 0..gray.len() {
        gray[i] = i ^ (i >> 1);
    }

    let mut mm = BTreeMap::<(usize, usize), usize>::new();

    for i in 0..gray.len() {
        mm.insert((gray[i], gray[(i + 1) % gray.len()]), i);
    }

    let mut pos = None;

    for i in 0..n {
        for j in i..n {
            let aa = bswap(a, i, j);
            let bb = bswap(b, i, j);

            if let Some(p) = mm.get(&(aa, bb)) {
                pos = Some((false, p, i, j));
            } else if let Some(p) = mm.get(&(bb, aa)) {
                pos = Some((true, p, i, j));
            }
        }
    }

    let (dir, pos, i, j) = pos.unwrap();

    for k in 0..gray.len() {
        v.push(if !dir {
            bswap(gray[(gray.len() + pos - k) % gray.len()], i, j)
        } else {
            bswap(gray[(pos + 1 + k) % gray.len()], i, j)
        });
    }

    v
}

fn bswap(a: usize, i: usize, j: usize) -> usize {
    (a & !(1 << i) & !(1 << j)) | ((a >> i) & 1) << j | ((a >> j) & 1) << i
}

