fn rec(n: usize, b: usize, v: &mut Vec<usize>) {
    if b == 0 {
        let mut ok = true;
        for i in 0..n - 1 {
            let t = v[i] ^ v[i + 1];
            if t.count_ones() != 1 {
                ok = false;
                break;
            }
        }

        if ok {
            if (v[0] ^ v[v.len() - 1]).count_ones() != 1 {
                // dbg!(&v);
                println!(
                    "{}: {} {}",
                    (v[0] ^ v[v.len() - 1]).count_ones(),
                    v[0],
                    v.last().unwrap()
                );
            }
        }

        return;
    }

    for i in 0..n {
        if b & (1 << i) == 0 {
            continue;
        }

        if v.len() > 0 {
            if (v.last().unwrap() ^ i).count_ones() != 1 {
                continue;
            }
        }

        v.push(i);
        rec(n, b & !(1 << i), v);
        v.pop();
    }
}

