            let mut vis = vec![false; 1 << n];
            ans[0] = a;
            vis[a] = true;
            if dfs(0, &mut vis, &path, &mut ans, b) {
                for (i, p) in ans.into_iter().enumerate() {
                    if i > 0 {
                        print!(" ");
                    }
                    print!("{}", p);
                }
