fn dfs(pos: usize, vis: &mut [bool], path: &[usize], ans: &mut [usize], b: usize) -> bool {
    if pos == ans.len() - 1 {
        return ans[pos] == b;
    }
    let cur = ans[pos];
    for i in 0..17 {
        let next = cur ^ (1 << i);
        if !vis[next] && next.count_ones() as usize == path[pos + 1] {
            ans[pos + 1] = next;
            vis[next] = true;
            if dfs(pos + 1, vis, path, ans, b) {
                return true;
            }
            vis[next] = false;
        }
    }
    false
}

fn solve(n: usize, a: usize, b: usize) -> Option<Vec<usize>> {
    let mut count: [i32; 18] = [0; 18];
    for mask in 0..(1 << n) {
        count[(mask as u32).count_ones() as usize] += 1;
    }

    let max_bit = count
        .iter()
        .enumerate()
        .filter(|&(_, &c)| c > 0)
        .map(|(i, _)| i)
        .max()
        .unwrap();

    let goal_bit = b.count_ones() as usize;

    let mut vis = [0; 18];
    let mut cur = a.count_ones() as usize;
    let mut path = vec![cur];
    vis[cur] += 1;
    if vis[cur] > count[cur] {
        return None;
    }
    while cur > 0 {
        cur -= 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    assert_eq!(cur, 0);
    if vis == count {
        return Some(path);
    }
    cur += 1;
    path.push(cur);
    vis[cur] += 1;
    while cur < goal_bit {
        if vis[cur - 1] > count[cur - 1] {
            return None;
        }
        if vis[cur - 1] < count[cur - 1] {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }

    while cur < max_bit {
        cur += 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if vis == count {
        return Some(path);
    }
    assert_eq!(cur, max_bit);
    cur -= 1;
    path.push(cur);
    vis[cur] += 1;
    while vis != count {
        if vis[cur + 1] > count[cur + 1] {
            return None;
        }
        if vis[cur + 1] < count[cur + 1] {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if path[path.len() - 1] != goal_bit {
        None
    } else {
        Some(path)
    }
}

