fn cut(a: u64, m: u64) -> u64 {
    // cut m-th bit
    (a & ((1 << m) - 1)) | ((a >> (m + 1)) << m)
}

fn ins(a: u64, m: u64, b: u64) -> u64 {
    // insert b as m-th bit
    ((a >> m) << (m + 1)) |
        (b << m) |
        (a & ((1 << m) - 1))
}

fn solve(n: u64, a: u64, b: u64) -> Option<Vec<u64>> {
    if n == 1 {
        if a == b { return None }
        Some(vec![a, b])
    } else {
        for i in 0..n {
            let x = (a & (1 << i)) >> i;
            let y = (b & (1 << i)) >> i;
            if x == y { continue }
            let a2 = cut(a, i);
            let b2 = cut(b, i);
            for v in 0..(1 << (n-1)) {
                if v != a2 && v != b2 {
                    match (solve(n - 1, a2, v), solve(n - 1, v, b2)) {
                        (Some(xs), Some(ys)) => {
                            let mut res = vec![];
                            for &z in xs.iter() {
                                res.push(ins(z, i, x));
                            }
                            for &z in ys.iter() {
                                res.push(ins(z, i, y));
                            }
                            return Some(res)
                        },
                        _ => { return None }
                    }
                }
            }
        }
        None
    }
}

