use std::io::{self, Write};
use std::str::FromStr;
use std::collections::VecDeque;

struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
impl Scanner {
    fn new() -> Scanner { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let a: usize = sc.read();
    let b: usize = sc.read();
    match solve(n, a, b) {
        Some(path) => {
            println!("YES");
            let mut ans = vec![0; 1 << n];
            let mut vis = vec![false; 1 << n];
            ans[0] = a;
            vis[a] = true;
            if dfs(0, &mut vis, &path, &mut ans, b) {
                for (i, p) in ans.into_iter().enumerate() {
                    if i > 0 {
                        print!(" ");
                    }
                    print!("{}", p);
                }
                println!();
            } else {
                println!("NO");
            }
        }
        None => println!("NO"),
    }
}

fn dfs(pos: usize, vis: &mut [bool], path: &[usize], ans: &mut [usize], b: usize) -> bool {
    if pos == ans.len() - 1 {
        return ans[pos] == b;
    }
    let cur = ans[pos];
    for i in 0..17 {
        let next = cur ^ (1 << i);
        if !vis[next] && next.count_ones() as usize == path[pos + 1] {
            ans[pos + 1] = next;
            vis[next] = true;
            if dfs(pos + 1, vis, path, ans, b) {
                return true;
            }
            vis[next] = false;
        }
    }
    false
}

fn solve(n: usize, a: usize, b: usize) -> Option<Vec<usize>> {
    let mut count: [i32; 18] = [0; 18];
    for mask in 0..(1 << n) {
        count[(mask as u32).count_ones() as usize] += 1;
    }

    let max_bit = count
        .iter()
        .enumerate()
        .filter(|&(_, &c)| c > 0)
        .map(|(i, _)| i)
        .max()
        .unwrap();

    let goal_bit = b.count_ones() as usize;

    let mut vis = [0; 18];
    let mut cur = a.count_ones() as usize;
    let mut path = vec![cur];
    vis[cur] += 1;
    if vis[cur] > count[cur] {
        return None;
    }
    while cur > 0 {
        cur -= 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    assert_eq!(cur, 0);
    if vis == count {
        return Some(path);
    }
    cur += 1;
    path.push(cur);
    vis[cur] += 1;
    while cur < goal_bit {
        if vis[cur - 1] > count[cur - 1] {
            return None;
        }
        if vis[cur - 1] < count[cur - 1] {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }

    while cur < max_bit {
        cur += 1;
        path.push(cur);
        vis[cur] += 1;
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if vis == count {
        return Some(path);
    }
    assert_eq!(cur, max_bit);
    cur -= 1;
    path.push(cur);
    vis[cur] += 1;
    while vis != count {
        if vis[cur + 1] > count[cur + 1] {
            return None;
        }
        if vis[cur + 1] < count[cur + 1] {
            cur += 1;
            path.push(cur);
            vis[cur] += 1;
        } else {
            cur -= 1;
            path.push(cur);
            vis[cur] += 1;
        }
        if vis[cur] > count[cur] {
            return None;
        }
    }
    if path[path.len() - 1] != goal_bit {
        None
    } else {
        Some(path)
    }
}

