fn num_to_bits(mut num: u64, n: usize) -> Vec<i32> {
    let mut res = vec![0; n];
    for i in 0..n {
        res[i] = (num % 2) as i32;
        num /= 2;
    }
    res
}

fn bits_to_num(bits: &Vec<i32>) -> u64 {
    let mut res = 0;
    for i in 0..bits.len() {
        res += bits[i] as u64 * (1 << i);
    }
    res
}

fn invert_bit(i: usize, bits: &mut Vec<i32>) {
    if bits[i] == 1 {
        bits[i] = 0;
    } else {
        bits[i] = 1;
    }
}

fn route(start_bits: &Vec<i32>, end_bits: &Vec<i32>, bit_mask: &Vec<usize>) -> Vec<usize> {
    if bit_mask.len() == 2 {
        if start_bits[bit_mask[0]] != end_bits[bit_mask[0]] {
            assert!(start_bits[bit_mask[1]] == end_bits[bit_mask[1]]);
            return vec![bit_mask[1], bit_mask[0], bit_mask[1]];
        } else {
            assert!(start_bits[bit_mask[1]] != end_bits[bit_mask[1]]);
            return vec![bit_mask[0], bit_mask[1], bit_mask[0]];
        }
    }
    let mut new_bit_mask = Vec::new();
    let mut first_different_bit = 0usize;
    for &bit in bit_mask.iter() {
        if start_bits[bit] != end_bits[bit] {
            first_different_bit = bit;
            break;
        }
    }
    for &bit in bit_mask.iter() {
        if bit != first_different_bit {
            new_bit_mask.push(bit);
        }
    }

    let mut intermediate_bits = start_bits.clone();
    invert_bit(new_bit_mask[0], &mut intermediate_bits);
    let mut ret1 = route(&start_bits, &intermediate_bits, &new_bit_mask);

    invert_bit(first_different_bit, &mut intermediate_bits);
    ret1.push(first_different_bit);
    let ret2 = route(&intermediate_bits, &end_bits, &new_bit_mask);

    [ret1, ret2].concat()
}

fn main() {
    let v: Vec<u64> = read_vec();
    let (n, a, b) = (v[0], v[1], v[2]);
    let n = n as usize;

    let a_bits = num_to_bits(a, n);
    let b_bits = num_to_bits(b, n);

    if (a_bits.iter().sum::<i32>() - b_bits.iter().sum::<i32>()) % 2 == 0 {
        println!("NO");
        return;
    }
    println!("YES");
    if n == 1 {
        if a == 0 {
            println!("0 1");
        } else {
            println!("1 0");
        }
        return;
    }
    let bit_mask = (0..n).collect::<Vec<usize>>();
    let route_bits = route(&a_bits, &b_bits, &bit_mask);

    let mut answers = Vec::with_capacity(1 << n);
    let mut start_bits = a_bits;
    answers.push(bits_to_num(&start_bits));
    for &bit in route_bits.iter() {
        invert_bit(bit, &mut start_bits);
        answers.push(bits_to_num(&start_bits));
    }
    println!(
        "{}",
        answers
            .iter()
            .map(|&x| x.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
}

