fn lsb(x: usize) -> usize {
    (x as isize & -(x as isize)) as usize
}
fn rec(x: usize, e: usize) -> Vec<usize> {
    if e.count_ones() == 1 {
        vec![0, x]
    } else {
        let m = lsb(x);
        let ne = e ^ m;
        let s = lsb(ne);
        rec(s, ne)
            .into_iter()
            .chain(rec(x ^ m ^ s, ne).into_iter().map(|i| i ^ m ^ s))
            .collect::<Vec<_>>()
    }
}
fn main() {
    input! { n, a, b };
    let m = (0..n).filter(|i| (a ^ b) & 1usize << i != 0).count();
    if m % 2 == 0 {
        println!("NO");
    } else {
        println!("YES");
        let v = rec(a ^ b, (1 << n) - 1);
        for p in v.into_iter() {
            print!("{} ", p ^ a);
        }
        println!("");
    }
}
